static bool g_vmScaleUseBones = false, g_vmScaleRewriteLogged = false;
static float g_vmScaleLastWrite[2] = {1.f, 1.f};
static uint32_t g_vmScaleFieldWrites = 0, g_vmScaleRewrites = 0, g_vmScaleBoneBuilds = 0;
static float g_vmMoveStep = .1f, g_vmAngleStep = 1.f;
static skviewmodel::Store g_vmStore{}, g_vmIoStore{};
static wchar_t g_vmPath[SKT_PATH_CAP]{};
static std::atomic<int> g_vmJob{0}, g_vmResult{0};
static bool g_vmIoBusy = false, g_vmReady = false, g_vmWritable = true;
static bool g_vmDirty = false, g_vmSaveFailed = false;
static DWORD g_vmSaveAt = 0;
static int g_vmEditSlot = 0;
static UiId g_vmStatus = UiId::VmStatusInitial;
struct ViewModelBinding {
    void* entity; void* header; void* rawHeader; int modelIndex; int profile;
    uint32_t checksum; char model[260]; wchar_t label[260];
};
static ViewModelBinding g_vmBindings[2]{};
static void* g_vmLocal = nullptr;
using ViewModelCalcFn = void(__thiscall*)(void*, void*, const skviewmodel::Vec&, const skviewmodel::Vec&);
using ViewModelSetFn = void(__thiscall*)(void*, const skviewmodel::Vec&);
static ViewModelCalcFn g_vmOriginal = nullptr;
static ViewModelSetFn g_vmSetOrigin = nullptr, g_vmSetAngles = nullptr;
static void** g_vmHookSlot = nullptr;
static bool g_vmHooked = false, g_vmHookFailed = false;
static uint32_t g_vmCalcCalls = 0, g_vmApplied = 0, g_vmBindingChanges = 0;
static uint32_t g_vmSaveRequests = 0, g_vmLoadRequests = 0;
static void ViewModelGamePump();
static void WModelScaleGamePump();
static int EntIndexOf(void* ent);
static void ViewModelMirrorPump(bool wanted);
static void ViewModelMenuAdjust(int direction);
static void ViewModelMenuKey(int digit);
static const skviewmodel::Pose* ViewModelMenuPose();
static const wchar_t* ViewModelMenuModelName();
static const wchar_t* ViewModelStatusText();
static void ViewModelWorkerPump() {
    const int job = g_vmJob.exchange(0, std::memory_order_acquire);
    if (!job) return;
    int result = 0;
    if (job == 1) {
        result = g_vmPath[0] ? skviewmodelio::Load(g_vmPath, &g_vmIoStore) : 3;
        if (result == 2) g_vmIoStore = {};
    } else result = g_vmPath[0] && skviewmodelio::Save(g_vmPath, g_vmIoStore) ? 4 : 5;
    g_vmResult.store(result, std::memory_order_release);
}
static void ViewModelRequestSave() {
    if (!g_vmReady || !g_vmWritable || g_vmIoBusy || !g_vmDirty) return;
    g_vmIoStore = g_vmStore;
    g_vmDirty = false; g_vmSaveFailed = false; g_vmIoBusy = true;
    g_vmStatus = UiId::VmStatusSaving;
    ++g_vmSaveRequests;
    g_vmJob.store(2, std::memory_order_release);
}

