// Worker loop flag — cleared on process/DLL detach so we stop touching engine APIs during quit.
std::atomic_bool g_run{true};
// One process-lifetime stop event, created before installing any client hooks.
// Only UI/input threads wait on it; no engine calls, polling or per-frame work.
static HANDLE g_clientUiStopEvent = nullptr;
static std::atomic<unsigned> g_clientUiWaitFaults{0};
static std::atomic<DWORD> g_xhairUiShutdownWait{WAIT_OBJECT_0};
static bool ClientUiNextMessage(MSG* msg, const std::atomic_bool& running) {
	while (g_run.load(std::memory_order_acquire) && running.load(std::memory_order_acquire)) {
		if (PeekMessageW(msg, nullptr, 0, 0, PM_REMOVE)) return msg->message != WM_QUIT;
		const DWORD wait = MsgWaitForMultipleObjects(1, &g_clientUiStopEvent, FALSE, INFINITE, QS_ALLINPUT);
		if (wait == WAIT_OBJECT_0) return false;
		if (wait != WAIT_OBJECT_0 + 1) { ++g_clientUiWaitFaults; return false; }
	}
	return false;
}
