// =============================================================================
// Menu: IEngineVGui::Paint + ISurface (engine HUD draw). No Win32 menu HWND.
// Digits: Paint GetAsyncKeyState for UI; IN_KeyEvent chained once (Necola-style)
// eats 0–9/Esc/... while menu open so binds (slot*) do not fire. No heal loop.
// No SaveSettings/ClientCmd inside the detour. No slot1–10 ConCommand wrap.
// =============================================================================
static bool g_optSound = false;
static bool g_optBloodSplat = false;
static std::atomic<unsigned> g_bloodSplatDue{0};
static std::atomic<unsigned> g_bloodSplatCooldown{0};
// Debug log to game-root skeeto.log. Missing ini key = off (old and new users).
static bool g_optDebugLog = false;
static bool g_debugLogLaunch = false; // -skeeto_debug only affects this process; never saved to ini.
static bool DebugLogWanted() { return g_optDebugLog || g_debugLogLaunch; }
// Independent feedback SFX volume (0–100). Multiplies EmitAmbientSound only —
// does NOT touch engine volume / snd_musicvolume.
static int g_optSfxVol = 100;
static bool g_optIcon = false;
// Hit mode: 0=全部关闭（默认） 1=仅特感Hit 2=特感+普感
static int g_optHitMode = 0;
static bool g_optBossHitActiveOnly = true; // Tank/Witch: require recent local gun/melee activity
// 特感包开启后，画面/音效是否使用 [6] 选中的特感包；另一档为显式使用普感素材。二者独立。
static bool g_optSiVisual = false;
static bool g_optSiSound = false;
bool g_optKillFx = false;
static bool g_optFeedbackWorkshopRecovery = false;
static bool g_optFf = false; // friendly-fire feedback from player_hurt_concise only
// Registers particles/skeeto_*.txt using the engine's own manifest parser.
// Default off because registration is process-lifetime.
static bool g_optSkeetoParticlePlatform = false;
// Read on the engine manifest thread. 16/32/48, default 32. A menu change
// applies the next time the process builds the manifest.
static int g_skeetoParticleManifestLimit = 32;
static int SkeetoParticleManifestLimitNormalize(int v) {
	return v == 16 || v == 48 ? v : 32;
}
// -1: no valid command-line override; 0/1: force this process only.
// The saved menu setting remains independent and is never rewritten here.
static int g_skeetoParticlePlatformCmdOverride = -1;

static bool SkeetoParticlePlatformEffectiveEnabled() {
	return g_skeetoParticlePlatformCmdOverride >= 0
		? g_skeetoParticlePlatformCmdOverride != 0
		: g_optSkeetoParticlePlatform;
}

static bool HitModeCiAllowed() { return g_optHitMode == 2; }
static bool HitModeSiAllowed() { return g_optHitMode != 0; }
// Any feature that needs local gun/melee attribution via HP proxy or impact stamp.
static bool NeedGunHitAttribution() {
	return HitModeSiAllowed() || HitModeCiAllowed() || WorldNoticeAirborneTrackingWanted();
}
static bool NeedHealthProxyWork() {
	return HitModeSiAllowed() || WorldNoticeAirborneTrackingWanted();
}
