static constexpr bool MenuPageIdsUnique() {
	for (int i = 0; i < (int)(sizeof(kMenuPageIdAudit) / sizeof(kMenuPageIdAudit[0])); ++i)
		for (int j = i + 1; j < (int)(sizeof(kMenuPageIdAudit) / sizeof(kMenuPageIdAudit[0])); ++j)
			if (kMenuPageIdAudit[i] == kMenuPageIdAudit[j]) return false;
	return true;
}
static_assert(MenuPageIdsUnique(), "duplicate kMenuPage* id");
static constexpr int MenuPageIdAuditMax() {
	int m = kMenuPageIdAudit[0];
	for (int i = 1; i < (int)(sizeof(kMenuPageIdAudit) / sizeof(kMenuPageIdAudit[0])); ++i)
		if (kMenuPageIdAudit[i] > m) m = kMenuPageIdAudit[i];
	return m;
}
static_assert(kMenuPageIdNext == MenuPageIdAuditMax() + 1, "kMenuPageIdNext must be max(kMenuPage*) + 1");

