static std::atomic_bool g_menuReturnResetPending{ false };
static void MenuReturnReset() {
	if (g_paintTid && GetCurrentThreadId() != g_paintTid) {
		g_menuReturnResetPending.store(true, std::memory_order_release);
		return;
	}
	g_menuReturnDepth = 0;
	g_menuDiscoveryAnchor = -1;
	g_menuReturnResetPending.store(false, std::memory_order_release);
}
static void MenuReturnApplyPending() {
	if (g_menuReturnResetPending.exchange(false, std::memory_order_acq_rel)) {
		g_menuReturnDepth = 0;g_menuDiscoveryAnchor = -1;
	}
}
