static std::atomic<DWORD> g_menuBracketPendingAt{ 0 };

bool HudMenuPage(int page) {
	return g_menuVisible && !g_menuParked && g_menuPage == page;
}

// HUD position-preview rules (keep when adding new screen HUDs):
// 1) Own settings page: always draw with demo rows (HudMenuPage), even if the
//    option is currently off — so users can place it before enabling.
// 2) Peer layout preview: while ANY HudLayoutSubPage is open, every ENABLED
//    HUD in that list also draws (HudWantsDraw + opt). Those peers must fill
//    demo/fake rows via HudLayoutPeer(...), otherwise an empty live buffer
//    makes the panel invisible during position nudges.
// 3) Large panels (TAB 80/82, chapter stats 81/83/94/95) stay OUT of
//    HudLayoutSubPage so they do not auto-stack when adjusting other HUDs;
//    they only preview on their own pages (or held-key live view).
// 4) Chapter score toast HUD (93) is in the list; when that page is open the
//    Paint path may draw the big chapter/TAB panel underneath first.
bool HudLayoutSubPage() {
	if (!g_menuVisible || g_menuParked) return false;
	switch (g_menuPage) {
	case kMenuPageCacheOffload: return g_optCacheOffload;
	case kMenuPageRouteProgressHud: return true;
	case 5: case 12: case 13: case 14: case 15: case 17: case kMenuPageSiWarningHud:
	case 21: case 22: case 23: case 24: case 27: case 28: case 29: case 30: case 32: case 33: case 36: case 39: case 40: case 41: case kMenuPageMemoryHud: case kMenuPageSiPresenceHud: case kMenuPageWitchStartleHud: case kMenuPageTankRockNotice: case kMenuPageVoiceHud: case kMenuPageAmmoGfxHud: case kMenuPageAmmoSegHud: case kMenuPageBwSelfHud: case kMenuPageClientDmgNum: case kMenuPageUpgradeAmmoHud: case kMenuPageKillFeed: case kMenuPageMateLast: case kMenuPageMateLow: case kMenuPageMateSave: case kMenuPageInteractHud: case kMenuPageTongueCutHud: case kMenuPageChapStatsScoreHud: case kMenuPageTankTargetHud: case kMenuPageDamageSourceHud: case kMenuPageFriendlyFireHud: case kMenuPageSiAggroHud: case kMenuPageWitchRageHud: case kMenuPageBossDmgBoardHud: case kMenuPageIgniteHud: case kMenuPageWitchHpHud: 	case kMenuPageLaserRoundNotice:
	case kMenuPageLocalDirector:
	case kMenuPageSupplyScanHud:
		return true;
	default: return false;
	}
}

bool HudWantsDraw(bool opt, int page) {
	if (HudMenuPage(page)) return true;
	if (HudLayoutSubPage() && opt) return true;
	return opt;
}

bool HudLayoutPeer(bool opt, int page) {
	return HudLayoutSubPage() && opt && !HudMenuPage(page);
}

static bool CacheOffloadHudWanted() {
	return g_optCacheOffload && HudWantsDraw(g_optCacheOffloadHud, kMenuPageCacheOffload);
}

