static constexpr ClientBackItemMenuItem kClientBackItemMenuItems[] = {
	{"client_hide_back_items", UiId::HideBackMaster, L"[1] 隐藏背部物品总开关 %s"},
	{"client_hide_back_medicine", UiId::HideBackMedicine, L"[2] 隐藏药品（药丸 / 针） %s"},
	{"client_hide_back_medical", UiId::HideBackMedical, L"[3] 隐藏医疗包 / 电击器 %s"},
	{"client_hide_back_throwables", UiId::HideBackThrowables, L"[4] 隐藏投掷物 %s"},
	{"client_hide_back_tongue", UiId::HideBackTongue, L"[5] 隐藏 Smoker 舌头挂件 %s"},
};
static constexpr int ClientBackItemMenuItemCount() {
	return (int)(sizeof(kClientBackItemMenuItems) / sizeof(kClientBackItemMenuItems[0]));
}
static_assert(ClientBackItemMenuItemCount() == (int)ClientBackItemCategory::Count + 1
	&& ClientBackItemMenuItemCount() <= kMenuItemsPerPage, "back-item settings must fit one page");
static bool& ClientUxBackItemSetting(int item) {
	return item == 0 ? g_optClientHideBackItems : g_optClientBackItemHidden[item - 1];
}
static bool ClientUxLoadBackItemCategory(const char* line) {
	// Cold ini parsing; fixed category keys, no aliases for unpublished settings.
	for (int i = 1; i < ClientBackItemMenuItemCount(); ++i) {
		const char* key = kClientBackItemMenuItems[i].key;
		const size_t length = strlen(key);
		int value;
		if (!strncmp(line, key, length) && line[length] == '=' && sscanf(line + length + 1, "%d", &value) == 1) {
			ClientUxBackItemSetting(i) = value != 0;
			return true;
		}
	}
	return false;
}
