static int g_optClientDmgCritThresh = 3;    // index: 0=Off / 1=50 / 2=80 / 3=100(default) / 4=150 / 5=200
static constexpr int kDmgCritThreshN = 6;
static constexpr int kDmgCritThreshVals[kDmgCritThreshN] = { 0, 50, 80, 100, 150, 200 };
static int g_optClientDmgCritThresh2 = 2; // index: 100 / 150 / 200(default) / 250 / 300 / 400 / 500
static constexpr int kDmgCritThresh2N = 7;
static constexpr int kDmgCritThresh2Vals[kDmgCritThresh2N] = { 100, 150, 200, 250, 300, 400, 500 };
static int ClientDmgCritThreshValue() {
	int i = g_optClientDmgCritThresh;
	if (i < 0) i = 0;
	if (i >= kDmgCritThreshN) i = kDmgCritThreshN - 1;
	return kDmgCritThreshVals[i];
}
static int ClientDmgCritThresh2Value() {
	int i = g_optClientDmgCritThresh2;
	if (i < 0) i = 0;
	if (i >= kDmgCritThresh2N) i = kDmgCritThresh2N - 1;
	const int first = ClientDmgCritThreshValue();
	return kDmgCritThresh2Vals[i] < first ? first : kDmgCritThresh2Vals[i];
}
static void ClampClientDmgCritThresholds() {
	if (g_optClientDmgCritThresh < 0) g_optClientDmgCritThresh = 0;
	if (g_optClientDmgCritThresh >= kDmgCritThreshN) g_optClientDmgCritThresh = kDmgCritThreshN - 1;
	if (g_optClientDmgCritThresh2 < 0) g_optClientDmgCritThresh2 = 0;
	if (g_optClientDmgCritThresh2 >= kDmgCritThresh2N) g_optClientDmgCritThresh2 = kDmgCritThresh2N - 1;
	// Normalize only at settings boundaries; never allow tier 2 below tier 1.
	while (g_optClientDmgCritThresh2 < kDmgCritThresh2N - 1
		&& kDmgCritThresh2Vals[g_optClientDmgCritThresh2] < ClientDmgCritThreshValue())
		++g_optClientDmgCritThresh2;
}
static int ClientDmgCritTier(int damage) {
	const int first = ClientDmgCritThreshValue();
	if (first <= 0 || damage < first) return 0;
	return damage > ClientDmgCritThresh2Value() ? 2 : 1;
}
