int HudClampScale(int s) {
	if (s < kHudScaleMin) s = kHudScaleMin;
	if (s > kHudScaleMax) s = kHudScaleMax;
	s = ((s + kHudScaleStep / 2) / kHudScaleStep) * kHudScaleStep;
	if (s < kHudScaleMin) s = kHudScaleMin;
	return s;
}

int HudScalePx(int base, int scalePct) {
	const int s = HudClampScale(scalePct);
	const int autoPct = g_hudResolutionScalePct;
	int n = (base * s * autoPct + 5000) / 10000;
	return n < 1 ? 1 : n;
}

int HudFontPx(int base) {
	const int autoPct = g_hudResolutionScalePct;
	int n = (base * autoPct + 50) / 100;
	return n < 1 ? 1 : n;
}

void HudClampFont(int* font) {
	if (!font) return;
	if (*font < kHudFontMin) *font = kHudFontMin;
	if (*font > kHudFontMax) *font = kHudFontMax;
}

static int ClockDateLayoutTall(int layoutTimeFont) {
	int d = layoutTimeFont * 3 / 4;
	if (d < 18) d = 18;
	if (layoutTimeFont > 20 && d > layoutTimeFont - 2) d = layoutTimeFont - 2;
	return d;
}

