static bool BackgroundCoreWanted() {
	return g_optBackgroundEngine;
}

static bool BackgroundEnsureInitialized() {
	if (g_backgroundCoreInitialized.load(std::memory_order_acquire)) return true;
	if (!BackgroundCoreWanted() || g_backgroundShutdownPending.load(std::memory_order_acquire))
		return false;
	SkeetoBackgroundInitialize(g_gameL4d2Dir, &BackgroundLogBridge);
	g_backgroundCoreInitialized.store(true, std::memory_order_release);
	return true;
}

static void BackgroundUseAssets() {
	if (!BackgroundEnsureInitialized()) return;
	if (!SkeetoBackgroundEnabled()) {
		SkeetoBackgroundSetRandomStart(g_optBackgroundRandomStart);
		SkeetoBackgroundSelect(g_backgroundId);
		SkeetoBackgroundSetFit(g_backgroundFit);
		SkeetoBackgroundSetVolume(g_backgroundVolume);
		SkeetoBackgroundSetEnabled(true);
	}
}

static void BackgroundApplyConfig() {
	BackgroundSyncVolumeFromConVar();
	if (!BackgroundCoreWanted()) {
		if (g_backgroundCoreInitialized.load(std::memory_order_acquire)) {
			SkeetoBackgroundSetMenuActive(false);
			SkeetoBackgroundSetEnabled(false);
			SkeetoBackgroundSignalStop();
			g_backgroundShutdownPending.store(true, std::memory_order_release);
		}
		g_backgroundScanAttempted = false;
		BackgroundRestoreOriginal();
		return;
	}
	if (!BackgroundEnsureInitialized()) return;
	BackgroundUseAssets();
}

static void BackgroundSyncVolumeFromConVar() {
	if (!g_backgroundVolumeVar) return;
	int volume = ConVarReadIntBounded(g_backgroundVolumeVar, 0, 100);
	if (volume < 0 || volume > 100 || volume == g_backgroundVolume) return;
	g_backgroundVolume = volume;
	SkeetoBackgroundSetVolume(volume);
	// Persist the native ConVar change into the existing Skeeto settings too,
	// but coalesce disk I/O through the established deferred-save path.
	g_settingsDirty = true;
	g_settingsSaveAt = GetTickCount() + 800;
}

// Decoder teardown may wait for Media Foundation. Keep that wait off EngineVGui::Paint.
// Re-enable during the short handoff window is honored after the old worker has exited.
static void BackgroundLifecyclePump() {
	SkeetoSafeMusicLifecyclePump();
	SkeetoLastMusicLifecyclePump();
	if (!g_backgroundShutdownPending.exchange(false, std::memory_order_acq_rel)) return;
	if (g_backgroundCoreInitialized.exchange(false, std::memory_order_acq_rel)) {
		SkeetoBackgroundShutdown();
	}
	g_backgroundScanAttempted = false;
	if (!BackgroundCoreWanted()) return;
	BackgroundApplyConfig();
	if (g_backgroundCoreInitialized.load(std::memory_order_acquire)) {
		if (g_optBackgroundEngine) SkeetoBackgroundPreloadLoose();
	}
}

static void LogClose() {
	if (!g_log) return;
	fflush(g_log);
	fclose(g_log);
	g_log = nullptr;
}

static void LogOpenIfEnabled() {
	if (!DebugLogWanted()) {
		LogClose();
		return;
	}
	if (g_log) return;
	char dir[MAX_PATH]{};
	SkeetoGameRoot(dir, sizeof(dir));
	char logp[MAX_PATH]{};
	snprintf(logp, sizeof(logp), "%s\\skeeto.log", dir[0] ? dir : ".");
	g_log = fopen(logp, "a");
}

