static const int kKillStreakWindows[] = { 3, 5, 8, 10, 20, 30, 60, 0 };
static constexpr int kKillStreakWindowCount = sizeof(kKillStreakWindows) / sizeof(kKillStreakWindows[0]);

static void ClampKillStreakWindow() {
	for (int i = 0; i < kKillStreakWindowCount; ++i)
		if (g_killStreakWindowSec == kKillStreakWindows[i]) return;
	g_killStreakWindowSec = 8;
}

static void ClampFeedbackStreakWindow() {
	for (int i = 0; i < kKillStreakWindowCount; ++i)
		if (g_feedbackStreakWindowSec == kKillStreakWindows[i]) return;
	g_feedbackStreakWindowSec = 0;
}

static void CycleFeedbackStreakWindow() {
	ClampFeedbackStreakWindow();
	for (int i = 0; i < kKillStreakWindowCount; ++i) {
		if (g_feedbackStreakWindowSec != kKillStreakWindows[i]) continue;
		g_feedbackStreakWindowSec = kKillStreakWindows[(i + 1) % kKillStreakWindowCount];
		g_ciStreak = 0;
		g_siStreak = 0;
		g_ciStreakLastKillAt = 0;
		g_siStreakLastKillAt = 0;
		return;
	}
}

static void CycleKillStreakWindow() {
	ClampKillStreakWindow();
	for (int i = 0; i < kKillStreakWindowCount; ++i) {
		if (g_killStreakWindowSec != kKillStreakWindows[i]) continue;
		g_killStreakWindowSec = kKillStreakWindows[(i + 1) % kKillStreakWindowCount];
		return;
	}
}
