void* GetIface(const char* mod, const char* name) {
	HMODULE h = GetModuleHandleA(mod);
	if (!h) return nullptr;
	auto fn = (CreateInterfaceFn)GetProcAddress(h, "CreateInterface");
	return fn ? fn(name, nullptr) : nullptr;
}

void* VGet(void* inst, int idx) { return (*(void***)inst)[idx]; }

// Execute rights cannot be proven by reading: page query with a short per-page cache
// of positive answers (skmem::ExecutableAt), so repeated vtable-slot checks are free.
__declspec(noinline) bool IsExec(void* p) {
	return skmem::ExecutableAt(p, (uintptr_t)_ReturnAddress());
}

// Guarded one-byte read instead of VirtualQuery: same answer for the first byte
// (guard pages now fail), but cost no longer depends on the heap region size.
__declspec(noinline) bool PtrCommitted(const void* p) {
	return skmem::ProbeAt(p, (uintptr_t)_ReturnAddress());
}

__declspec(noinline) bool IfaceAlive(void* inst) {
	const uintptr_t site = (uintptr_t)_ReturnAddress();
	void** vt = nullptr;
	if (!skmem::CopyAt(&vt, inst, sizeof(vt), site)) return false;
	void* fn0 = nullptr;
	if (!skmem::CopyAt(&fn0, vt, sizeof(fn0), site)) return false;
	return skmem::ExecutableAt(fn0, site);
}

