int EngLocal() {
	if (!g_engine) return 0;
	using Fn = int(__thiscall*)(void*);
	static Fn s_fn = nullptr;
	if (!s_fn) {
		if (!IfaceAlive(g_engine)) return 0;
		s_fn = (Fn)VGet(g_engine, 12);
		if (!s_fn || !IsExec((void*)s_fn)) {
			s_fn = nullptr;
			return 0;
		}
	}
	return s_fn(g_engine);
}

