// Client gpGlobals->curtime — needed for temp-HP decay (m_healthBufferTime).
float EngClientCurTime() {
	static float* s_cur = nullptr;
	static bool s_tried = false;
	if (!s_tried) {
		s_tried = true;
		const uintptr_t hit = FindPat("client.dll", "A1 ?? ?? ?? ?? D9 40 0C 51 D9 1C 24 57");
		if (hit) {
			void** pp = *(void***)(hit + 1);
			if (pp && PtrCommitted(pp) && *pp && PtrCommitted((uint8_t*)*pp + 0x0C))
				s_cur = (float*)((uint8_t*)*pp + 0x0C);
		}
	}
	if (s_cur && PtrCommitted(s_cur)) {
		const float t = *s_cur;
		if (t == t && t > 0.f && t < 1.0e8f)
			return t;
	}
	return EngLastTimeStamp();
}
