// Remote mod-ban: Left4DHooks l4d2_addons_eclipse is FCVAR_NOTIFY only — the client
// never has that ConVar. Engine copies SVC_ServerInfo+0x5D into server_spawn.vanilla.
// sv_pure whitelist is a second lock. Recheck on event / connect / LevelInit / map-enter.
static std::atomic_bool g_pureSuppress{ false };
static std::atomic<int> g_eclipseVanilla{ -1 }; // -1 unknown, 0 addons on, 1 vanilla
static std::atomic_bool g_policyDirty{ false };
static uint8_t** s_pureClientState = nullptr;
static uint32_t s_pureWlOff = 0;
static bool s_pureResolved = false;
static bool s_pureResolveOk = false;

static int ConVarReadIntBounded(void* var, int lo, int hi) {
	if (!var) return lo - 1;
	// L4D2 ConVar: ConCommandBase (flags @ 0x14) + IConVar vptr, then m_pParent / m_Value.m_nValue.
	static const int kParentOff[] = { 0x1C, 0x18 };
	static const int kValueOff[] = { 0x30, 0x2C };
	for (int i = 0; i < 2; ++i) {
		void* parent = *(void**)((uint8_t*)var + kParentOff[i]);
		if (!parent) parent = var;
		// Callers poll this every Paint or every 100 ms: a guarded read, never a page query.
		int v = 0;
		if (!skmem::Copy(&v, (uint8_t*)parent + kValueOff[i], sizeof(v))) continue;
		if (v >= lo && v <= hi) return v;
	}
	return lo - 1;
}

static bool IsKnownMpGamemodeCstr(const char* s) {
	if (!s) return false;
	static const char* kModes[] = {
		"coop", "realism", "versus", "survival", "scavenge", "holdout", nullptr
	};
	for (int i = 0; kModes[i]; ++i) {
		if (_stricmp(s, kModes[i]) == 0) return true;
	}
	return false;
}

static bool IsReadableLowerName(const char* s, int maxLen) {
	char buf[32];
	if (!s || maxLen <= 0 || maxLen >= (int)sizeof(buf)) return false;
	// One guarded copy; a string that is not terminated within the buffer is rejected.
	if (!skmem::CopyCStr(buf, sizeof(buf), s)) return false;
	int len = 0;
	for (int i = 0; i < maxLen; ++i) {
		const char c = buf[i];
		if (!c) break;
		if (!((c >= 'a' && c <= 'z') || c == '_')) return false;
		++len;
	}
	return len >= 3 && len <= 16;
}

static const char* ConVarReadKnownGamemode(void* var) {
	if (!var) return nullptr;
	static const int kParentOff[] = { 0x1C, 0x18 };
	static const int kStrOff[] = { 0x24, 0x20, 0x28 };
	for (int i = 0; i < 2; ++i) {
		void* parent = *(void**)((uint8_t*)var + kParentOff[i]);
		if (!parent) parent = var;
		for (int j = 0; j < 3; ++j) {
			const char* s = nullptr;
			if (!skmem::Copy(&s, (uint8_t*)parent + kStrOff[j], sizeof(s))) continue;
			if (!IsReadableLowerName(s, 24)) continue;
			if (IsKnownMpGamemodeCstr(s)) return s;
		}
	}
	return nullptr;
}

