static void SktCvarReapplyOnMapEnter();
static void SktCvarApplyLoaded();
static void SktCvarFlushPins(bool force);
static void SktCvarEnsureLoaded();
static void SktCvarClearPins();

static void PurePolicyApply(bool lock, int eclipse, int pureMode, const char* mode, const char* trigger) {
	const bool was = g_pureSuppress.exchange(lock);
	if (lock == was) return;
	if (lock) {
		MenuForceClose();
		NetGraphHudApplyVanilla(false);
		SktCvarSuspendLive();
		Log("eclipse=%d sv_pure=%d mp_gamemode=%s — Skeeto features off (mod-ban policy) [%s]",
			eclipse, pureMode, mode ? mode : "?", trigger);
	} else {
		SktCvarResumeLive();
		if (g_optNetGraphHud) NetGraphHudApplyVanilla(true);
		Log("server policy clear — Skeeto features on (eclipse=%d sv_pure=%d mp_gamemode=%s) [%s]",
			eclipse, pureMode, mode ? mode : "?", trigger);
	}
}

static void PurePolicyRecheck(const char* trigger) {
	const char* mode = ReadMpGamemode();
	g_worldHudRealism = mode && _stricmp(mode, "realism") == 0;
	const bool listen = ListenIsHost();
	const int eclipse = g_eclipseVanilla.load(std::memory_order_relaxed);
	const int pureMode = ReadClientSvPureMode();
	const bool lock = !listen && (eclipse == 1 || pureMode >= 1);
	Log("mod-ban probe: eclipse=%d sv_pure=%d lock=%d listen=%d gamemode=%s [%s]",
		eclipse, pureMode, lock ? 1 : 0, listen ? 1 : 0, mode ? mode : "?", trigger ? trigger : "?");
	PurePolicyApply(lock, eclipse, pureMode, mode, trigger);
}

// Edge-triggered on Paint. LevelInit also rechecks on the game thread.
static void TickPurePolicy(bool connected, bool ingame) {
	if (g_paintTid && GetCurrentThreadId() != g_paintTid)
		return;

	static bool wasConnected = false;
	static bool wasInGame = false;

	if (!connected) {
		if (wasConnected) {
			g_eclipseVanilla.store(-1, std::memory_order_relaxed);
			g_policyDirty.store(false, std::memory_order_relaxed);
			if (g_pureSuppress.exchange(false)) {
				SktCvarResumeLive();
				Log("server policy: disconnected — Skeeto features re-enabled");
			}
			IdleSwapHudClearQuiet();
		}
		wasConnected = false;
		wasInGame = false;
		g_worldHudRealism = false;
		return;
	}

	const bool connectEdge = !wasConnected;
	const bool mapEdge = ingame && !wasInGame;
	const bool eventEdge = g_policyDirty.exchange(false, std::memory_order_relaxed);
	wasConnected = true;
	wasInGame = ingame;

	if (connectEdge || eventEdge || mapEdge) {
		const char* why = connectEdge ? "connect" : (eventEdge ? "server_spawn" : "map_enter");
		PurePolicyRecheck(why);
	}
}

