static bool ListenAddrIsStrictLoopback(const char* a) {
	if (!a || !a[0]) return false;
	if (_strnicmp(a, "loopback", 8) == 0) {
		const char c = a[8];
		return c == 0 || c == ':' || c == ' ' || c == '\t';
	}
	if (_strnicmp(a, "localhost", 9) == 0) {
		const char c = a[9];
		return c == 0 || c == ':' || c == ' ' || c == '\t';
	}
	return false;
}

static bool ListenAddrIsLoopback(const char* a) {
	if (!a || !a[0]) return false;
	if (ListenAddrIsStrictLoopback(a))
		return true;
	if (!strncmp(a, "127.", 4))
		return true;
	if (_strnicmp(a, "::1", 3) == 0)
		return true;
	return false;
}

static bool ListenAddrLooksRemote(const char* a) {
	if (!a || !a[0]) return false;
	if (ListenAddrIsLoopback(a)) return false;
	if (!strncmp(a, "0.0.0.0", 7)) return false;
	bool dot = false, digit = false;
	for (const char* p = a; *p && *p != ':'; ++p) {
		if (*p == '.') dot = true;
		if (*p >= '0' && *p <= '9') digit = true;
	}
	return dot && digit;
}

static bool ListenPtrLooksObject(void* inst) {
	if (!PtrCommitted(inst)) return false;
	void** vt = *(void***)inst;
	return PtrCommitted(vt);
}

static const char* ListenChanAddr(void* nc) {
	if (!nc || !ListenPtrLooksObject(nc)) return "";
	using AddrFn = const char*(__thiscall*)(void*);
	static const int kAddrSlot[] = { 1, 2, 0 };
	for (int i = 0; i < 3; ++i) {
		auto fn = (AddrFn)VGet(nc, kAddrSlot[i]);
		if (!fn || !IsExec((void*)fn)) continue;
		const char* a = fn(nc);
		// Demo playback / teardown can return a non-null junk pointer (observed 0x1c).
		// PtrCommitted before any dereference — !a[0] first AV'd on playdemo.
		if (!a || !PtrCommitted(a) || !a[0]) continue;
		if (ListenAddrIsLoopback(a) || ListenAddrLooksRemote(a) || strchr(a, ':'))
			return a;
	}
	return "";
}

static bool ListenChanCallIsLoopback(void* nc) {
	if (!nc || !ListenPtrLooksObject(nc)) return false;
	using Fn = bool(__thiscall*)(void*);
	auto fn = (Fn)VGet(nc, 6);
	if (!fn || !IsExec((void*)fn)) return false;
	return fn(nc);
}

static float ListenChanLatency(void* nc) {
	if (!nc || !ListenPtrLooksObject(nc)) return -1.f;
	using Fn = float(__thiscall*)(void*, int);
	static const int kSlot[] = { 10, 9, 11 };
	for (int i = 0; i < 3; ++i) {
		auto fn = (Fn)VGet(nc, kSlot[i]);
		if (!fn || !IsExec((void*)fn)) continue;
		const float v = fn(nc, 0);
		if (v >= 0.f && v < 2.f)
			return v;
	}
	return -1.f;
}

static bool ListenChanIsLoopback(void* nc) {
	if (!nc) return false;
	if (ListenAddrIsStrictLoopback(ListenChanAddr(nc)))
		return true;
	return ListenChanCallIsLoopback(nc) && !ListenAddrLooksRemote(ListenChanAddr(nc));
}

static bool ListenServerDllLoaded() {
	if (GetModuleHandleA("server.dll"))
		return true;
	if (!g_gameL4d2Dir[0])
		return false;
	char path[MAX_PATH]{};
	snprintf(path, sizeof(path), "%s\\bin\\server.dll", g_gameL4d2Dir);
	HMODULE h = nullptr;
	if (GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, path, &h) && h)
		return true;
	return false;
}

static void* EngNetChanFromClient() {
	if (!g_engine || !IfaceAlive(g_engine) || !EngConnected()) return nullptr;
	// Verified VEngineClient013 slot 74 returns the client's channel. Demos can
	// legitimately have none; adjacent slots have unrelated, incompatible ABIs.
	using Fn = void*(__thiscall*)(void*);
	auto fn = (Fn)VGet(g_engine, kEngineNetChanInfoSlot);
	if (!fn || !IsExec((void*)fn)) return nullptr;
	void* nc = fn(g_engine);
	return nc && ListenPtrLooksObject(nc) ? nc : nullptr;
}

static void* EngNetChan() {
	return EngNetChanFromClient();
}

static void ListenNoteServerSim();

static bool ListenDetectHost() {
	if (!g_run.load(std::memory_order_relaxed))
		return false;
	if (!g_engine || !IfaceAlive(g_engine) || !EngConnected())
		return false;
	ListenNoteServerSim();
	// This process is simulating the listen/dedicated server (lobby local included).
	if (g_listenMapHost.load(std::memory_order_relaxed)
		|| g_listenServerSimLive.load(std::memory_order_relaxed))
		return true;
	// Solo `map` / loopback before gpGlobals has ticked.
	void* nc = EngNetChan();
	if (!nc)
		return false;
	const char* addr = ListenChanAddr(nc);
	if (ListenAddrIsLoopback(addr))
		return true;
	if (ListenChanCallIsLoopback(nc) && !ListenAddrLooksRemote(addr))
		return true;
	return false;
}

static void ListenLogDetect(const char* why) {
	static DWORD s_last = 0;
	const DWORD now = GetTickCount();
	if (now - s_last < 2000 && why && why[0] != '!')
		return;
	s_last = now;
	void* nc = EngNetChan();
	const char* addr = ListenChanAddr(nc);
	Log("listen: %s host=%d server=%d mapHost=%d sim=%d connected=%d ingame=%d nc=%p addr='%s' loop=%d lat=%.3f idx=%d",
		why ? why : "?",
		ListenDetectHost() ? 1 : 0,
		ListenServerDllLoaded() ? 1 : 0,
		g_listenMapHost.load(std::memory_order_relaxed) ? 1 : 0,
		g_listenServerSimLive.load(std::memory_order_relaxed) ? 1 : 0,
		EngConnected() ? 1 : 0,
		EngInGame() ? 1 : 0,
		nc,
		addr && addr[0] ? addr : "-",
		ListenChanIsLoopback(nc) ? 1 : 0,
		ListenChanLatency(nc),
		kEngineNetChanInfoSlot);
}

static void* CvarParent(void* var) {
	if (!var) return nullptr;
	static const int kParentOff[] = { 0x1C, 0x18 };
	for (int i = 0; i < 2; ++i) {
		void* parent = *(void**)((uint8_t*)var + kParentOff[i]);
		if (parent && PtrCommitted(parent))
			return parent;
	}
	return var;
}

static int CvarFlagsOf(void* var) {
	if (!var || !PtrCommitted(var)) return 0;
	if (IfaceAlive(var)) {
		auto getFlags = (GetFlagsFn)VGet(var, 5);
		if (getFlags && IsExec((void*)getFlags))
			return getFlags(var);
	}
	return *(int*)((uint8_t*)var + 0x14);
}

static void CvarWriteFlags(void* var, int flags) {
	if (var && PtrCommitted(var))
		*(int*)((uint8_t*)var + 0x14) = flags;
	void* parent = CvarParent(var);
	if (parent && parent != var && PtrCommitted(parent))
		*(int*)((uint8_t*)parent + 0x14) = flags;
}

static int CvarPickValueLayout(void* parent) {
	if (!parent) return 0;
	static const int kNOff[] = { 0x30, 0x2C };
	static const int kFOff[] = { 0x2C, 0x28 };
	for (int i = 0; i < 2; ++i) {
		if (!PtrCommitted((uint8_t*)parent + kNOff[i]) || !PtrCommitted((uint8_t*)parent + kFOff[i]))
			continue;
		const float f = *(float*)((uint8_t*)parent + kFOff[i]);
		if (f == f && f > -1.0e8f && f < 1.0e8f)
			return i;
	}
	return 0;
}

bool CvarReadPair(void* var, int* nOut, float* fOut) {
	void* parent = CvarParent(var);
	if (!parent) return false;
	static const int kNOff[] = { 0x30, 0x2C };
	static const int kFOff[] = { 0x2C, 0x28 };
	const int i = CvarPickValueLayout(parent);
	if (!PtrCommitted((uint8_t*)parent + kNOff[i]) || !PtrCommitted((uint8_t*)parent + kFOff[i]))
		return false;
	if (nOut) *nOut = *(int*)((uint8_t*)parent + kNOff[i]);
	if (fOut) *fOut = *(float*)((uint8_t*)parent + kFOff[i]);
	return true;
}

static bool CvarPokePair(void* var, int n, float f) {
	void* parent = CvarParent(var);
	if (!parent) return false;
	static const int kNOff[] = { 0x30, 0x2C };
	static const int kFOff[] = { 0x2C, 0x28 };
	const int i = CvarPickValueLayout(parent);
	uint8_t* pn = (uint8_t*)parent + kNOff[i];
	uint8_t* pf = (uint8_t*)parent + kFOff[i];
	if (!PtrCommitted(pn) || !PtrCommitted(pf))
		return false;
	DWORD old = 0;
	if (VirtualProtect(pn, 4, PAGE_READWRITE, &old)) {
		*(int*)pn = n;
		DWORD tmp = 0;
		VirtualProtect(pn, 4, old, &tmp);
	} else {
		skmem::NoteFault((uintptr_t)_ReturnAddress());
		return false;
	}
	old = 0;
	if (VirtualProtect(pf, 4, PAGE_READWRITE, &old)) {
		*(float*)pf = f;
		DWORD tmp = 0;
		VirtualProtect(pf, 4, old, &tmp);
	} else {
		skmem::NoteFault((uintptr_t)_ReturnAddress());
		return false;
	}
	return true;
}

static ListenCvarSnap* ListenSnapFind(const char* name) {
	for (int i = 0; i < kListenSnapCount; ++i) {
		if (_stricmp(g_listenSnaps[i].name, name) == 0)
			return &g_listenSnaps[i];
	}
	return nullptr;
}

static void ListenSnapCapture(ListenCvarSnap* s) {
	if (!s || s->saved) return;
	void* var = CvarFind(s->name);
	if (!var) return;
	s->flags = CvarFlagsOf(var);
	if (!CvarReadPair(var, &s->n, &s->f))
		return;
	void* parent = CvarParent(var);
	if (parent && PtrCommitted((uint8_t*)parent + 0x3C)) {
		unsigned char b = *((uint8_t*)parent + 0x3C);
		if (b <= 1) {
			s->hasMax = b;
			s->hasMaxOk = true;
		}
	}
	s->saved = true;
}

static bool ListenCvarWriteInt(const char* name, int v) {
	ListenCvarSnap* s = ListenSnapFind(name);
	if (s) ListenSnapCapture(s);
	void* var = CvarFind(name);
	if (!var) return false;
	if (s && s->hasMaxOk) {
		void* parent = CvarParent(var);
		if (parent && PtrCommitted((uint8_t*)parent + 0x3C))
			*((uint8_t*)parent + 0x3C) = 0;
	}
	char buf[48]{};
	snprintf(buf, sizeof(buf), "%d", v);
	const bool ok = CvarWriteValue(name, buf);
	if (s) s->wrote = true;
	g_listenMutated = true;
	return ok;
}

static bool ListenPokeFloat(float* slot, float want) {
	if (!slot || !PtrCommitted(slot)) return false;
	DWORD old = 0;
	if (VirtualProtect(slot, 4, PAGE_READWRITE, &old)) {
		*slot = want;
		DWORD tmp = 0;
		VirtualProtect(slot, 4, old, &tmp);
	} else {
		skmem::NoteFault((uintptr_t)_ReturnAddress());
		return false;
	}
	return true;
}

// L4D2 ConVar (Necola CvarsB.h): m_fValue +0x2C, m_nValue +0x30.
// Do not scan nearby slots: 0.1f's bits look like a pointer, so a heuristic skip
// leaves GetFloat() stuck at the default (commons T-pose at high tick).
static bool CvarPokeFloatValue(void* var, float v) {
	void* parent = CvarParent(var);
	if (!parent || !PtrCommitted(parent)) return false;
	uint8_t* p = (uint8_t*)parent;
	if (!PtrCommitted(p + 0x30)) return false;
	if (!ListenPokeFloat((float*)(p + 0x2C), v)) return false;
	// GetFloat reads +0x2C. Do not smash m_nValue to 0 for 0.066 — only write n for whole numbers.
	if (v == (float)(int)v && PtrCommitted(p + 0x30)) {
		const int ni = (int)v;
		DWORD old = 0;
		if (VirtualProtect(p + 0x30, 4, PAGE_READWRITE, &old)) {
			*(int*)(p + 0x30) = ni;
			DWORD tmp = 0;
			VirtualProtect(p + 0x30, 4, old, &tmp);
		} else {
			skmem::NoteFault((uintptr_t)_ReturnAddress());
			return false;
		}
	}
	const int slen = *(int*)(p + 0x28);
	char* str = *(char**)(p + 0x24);
	if (slen >= 4 && slen <= 64 && str && PtrCommitted(str)) {
		char tmp[32]{};
		snprintf(tmp, sizeof(tmp), "%g", v);
		const size_t n = strlen(tmp);
		if (n + 1 <= (size_t)slen)
			memcpy(str, tmp, n + 1);
	}
	return true;
}

static void IdleFlashlightBrightWrite(float v);
static bool SktCvarSetFromString(void* var,const char* name,const char* value);

// Shared write path for skt_cvar / most force-cvar pins.
// Cheat numeric ConVars: poke memory only. EngClientCmd races with flag restore —
// the queued command runs after FCVAR_CHEAT is put back, prints
// "Can't use cheat cvar..." and may refuse the change, while a successful poke
// sticks for the process lifetime (unlike L4N-style ClientCmd-only writes that
// the engine clears on chapter change).
// NOT for r_flashlightbrightness: that needs the renderer command callback —
// see IdleFlashlightBrightWrite / floatCommandPin.
static bool CvarWriteValue(const char* name, const char* value) {
	if (!name || !name[0] || !value) return false;
	void* var = CvarFind(name);
	if (!var) return false;
	const int flagsBefore = CvarFlagsOf(var);
	const int clear = kFCvarCheat | kFCvarDevOnly | kFCvarHidden;
	const bool wasBlocked = (flagsBefore & clear) != 0;
	UnlockConCommand(name, clear, kFCvarClientCmdCanExecute);

	char* end = nullptr;
	const float want = strtof(value, &end);
	const bool numeric = end && end != value && *end == '\0' && want == want;

	if (numeric) {
		CvarPokeFloatValue(var, want);
		if (!wasBlocked) {
			char cmd[288]{};
			snprintf(cmd, sizeof(cmd), "%s %s", name, value);
			EngClientCmd(cmd);
			int n = 0;
			float f = 0.f;
			if (!CvarReadPair(var, &n, &f) || fabsf(f - want) > 0.001f)
				CvarPokeFloatValue(var, want);
		}
	} else {
		char cmd[288]{};
		snprintf(cmd, sizeof(cmd), "%s %s", name, value);
		EngClientCmd(cmd);
	}

	CvarWriteFlags(var, flagsBefore);
	return true;
}

static bool TeamWorldNamesReady() {
	return TeamWorldNamesWanted() && g_teamWorldNamesFont && g_teamWorldNamesFontPx == g_teamWorldNamesSize && g_surf && g_entlist
		&& g_engine && EngInGame() && !EngDrawingLoading() && !EngGameUiVisible()
		&& !g_hudPostMissionQuiet && !IdleSwapHudQuietActive()
		&& g_offOrigin >= 0 && g_offOrigin <= 0x4000 && g_offTeam >= 0 && g_offTeam <= 0x4000
		&& g_teamHudGatherPaintAt && GetTickCount() - g_teamHudGatherPaintAt <= 300u;
}

static constexpr int kSktCvarMax = 64;
struct SktCvarSlot {
	char name[80];
	char original[64];
	char desired[192];
	bool haveOriginal;
};
static SktCvarSlot g_sktCvarSlots[kSktCvarMax]{};
static int g_sktCvarN = 0;
static bool g_sktCvarSuspended = false;
static bool g_sktCvarLoading = false;
static bool g_sktCvarPinsLoaded = false;
static DWORD g_sktCvarSaveAt = 0;
struct SktCvarPinJob { int n = 0; char name[kSktCvarMax][80]{}; char desired[kSktCvarMax][192]{}; };
static SktCvarPinJob g_sktCvarJob{};
static std::atomic_int g_sktCvarJobPending{0};

static SktCvarSlot* SktCvarFindSlot(const char* name, bool add) {
	if (!name || !name[0]) return nullptr;
	for (int i = 0; i < g_sktCvarN; ++i) {
		if (!_stricmp(g_sktCvarSlots[i].name, name))
			return &g_sktCvarSlots[i];
	}
	if (!add || g_sktCvarN >= kSktCvarMax) return nullptr;
	SktCvarSlot& s = g_sktCvarSlots[g_sktCvarN++];
	memset(&s, 0, sizeof(s));
	strncpy(s.name, name, sizeof(s.name) - 1);
	return &s;
}

static void SktCvarRemember(const char* name, const char* original, const char* desired) {
	SktCvarSlot* s = SktCvarFindSlot(name, true);
	if (!s) {
		Log("skt_cvar: track table full (%s)", name ? name : "?");
		return;
	}
	if (!s->haveOriginal && original) {
		strncpy(s->original, original, sizeof(s->original) - 1);
		s->haveOriginal = true;
	}
	if (desired)
		strncpy(s->desired, desired, sizeof(s->desired) - 1);
	if (!g_sktCvarLoading && g_optSktCvarRemember)
		g_sktCvarSaveAt = GetTickCount() + 400u;
}

// Table stays process-lifetime. Only the live ConVar is restored while addon-ban
// policy is on; leaving the server writes desired values back.
static void SktCvarSuspendLive() {
	if (g_sktCvarSuspended) return;
	g_sktCvarSuspended = true;
	int n = 0;
	for (int i = 0; i < g_sktCvarN; ++i) {
		SktCvarSlot& s = g_sktCvarSlots[i];
		if (!s.haveOriginal || !s.name[0]) continue;
		if(SktCvarSetFromString(nullptr,s.name,s.original))++n;
	}
	if (n)
		Log("skt_cvar: suspended %d poke(s) for mod-ban policy", n);
}

static void SktCvarResumeLive() {
	if (!g_sktCvarSuspended) return;
	g_sktCvarSuspended = false;
	int n = 0;
	for (int i = 0; i < g_sktCvarN; ++i) {
		SktCvarSlot& s = g_sktCvarSlots[i];
		if (!s.desired[0] || !s.name[0]) continue;
		if(SktCvarSetFromString(nullptr,s.name,s.desired))++n;
	}
	if (n)
		Log("skt_cvar: resumed %d poke(s)", n);
}

// The engine can reset client ConVars during map loading. Reapply values
// recorded by skt_cvar once on the first ready Paint, never from the worker
// or a per-frame path. Server policy remains the authority while suspended.
static void SktCvarReapplyOnMapEnter() {
	SktCvarApplyLoaded();
}

static bool CfgOvSafeIdChar(char c) {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
		|| (c >= '0' && c <= '9') || c == '_' || c == '-';
}

static bool CfgOvLooksLikeCfgName(const char* leaf) {
	if (!leaf || _strnicmp(leaf, "skeeto_", 7) != 0) return false;
	const size_t len = strlen(leaf);
	if (len <= 11 || len >= (size_t)kCfgOvIdMax + 4) return false;
	if (_stricmp(leaf + len - 4, ".cfg") != 0) return false;
	for (size_t i = 0; i + 4 < len; ++i) {
		if (!CfgOvSafeIdChar(leaf[i])) return false;
	}
	return true;
}

static void CfgOvAddPresetLeaf(const char* leaf) {
	if (g_cfgOvPresetCount >= kCfgOvMaxPresets) return;
	if (!CfgOvLooksLikeCfgName(leaf)) return;
	char id[kCfgOvIdMax]{};
	const size_t stemLen = strlen(leaf) - 4;
	if (stemLen == 0 || stemLen >= sizeof(id)) return;
	memcpy(id, leaf, stemLen);
	id[stemLen] = 0;
	for (int i = 0; i < g_cfgOvPresetCount; ++i) {
		if (!_stricmp(g_cfgOvPresets[i], id)) return;
	}
	strncpy(g_cfgOvPresets[g_cfgOvPresetCount], id, sizeof(g_cfgOvPresets[0]) - 1);
	g_cfgOvPresets[g_cfgOvPresetCount][sizeof(g_cfgOvPresets[0]) - 1] = 0;
	++g_cfgOvPresetCount;
}

static int CfgOvPresetIndexOf(const char* id) {
	if (!id || !id[0]) return -1;
	for (int i = 0; i < g_cfgOvPresetCount; ++i) {
		if (!_stricmp(g_cfgOvPresets[i], id)) return i;
	}
	return -1;
}

static void CfgOvSelectPreset(const char* id) {
	g_cfgOvLoaded = false;
	g_cfgOvLineCount = 0;
	if (!id || !id[0]) {
		g_cfgOverridePreset[0] = 0;
		g_cfgOvPresetIdx = -1;
		return;
	}
	strncpy(g_cfgOverridePreset, id, sizeof(g_cfgOverridePreset) - 1);
	g_cfgOverridePreset[sizeof(g_cfgOverridePreset) - 1] = 0;
	g_cfgOvPresetIdx = CfgOvPresetIndexOf(g_cfgOverridePreset);
}

static bool CfgOvDiskPath(char* out, size_t outN, const char* stem) {
	if (!out || outN < 8 || !stem || !stem[0] || !g_gameL4d2Dir[0]) return false;
	const int n = snprintf(out, outN, "%s\\cfg\\%s.cfg", g_gameL4d2Dir, stem);
	return n > 0 && (size_t)n < outN;
}

// Loose cfg/skeeto_*.cfg only — same path Host_Exec_f uses (exec <stem>).
static void CfgOvScanPresets() {
	g_cfgOvPresetCount = 0;
	g_cfgOvPresetIdx = -1;
	g_cfgOvNeedScan = false;
	if (g_gameL4d2Dir[0]) {
		char pat[MAX_PATH]{};
		snprintf(pat, sizeof(pat), "%s\\cfg\\skeeto_*.cfg", g_gameL4d2Dir);
		WIN32_FIND_DATAA fd{};
		HANDLE h = FindFirstFileA(pat, &fd);
		if (h != INVALID_HANDLE_VALUE) {
			do {
				if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) continue;
				CfgOvAddPresetLeaf(fd.cFileName);
			} while (FindNextFileA(h, &fd) && g_cfgOvPresetCount < kCfgOvMaxPresets);
			FindClose(h);
		}
	}
	for (int i = 0; i + 1 < g_cfgOvPresetCount; ++i) {
		for (int j = i + 1; j < g_cfgOvPresetCount; ++j) {
			if (_stricmp(g_cfgOvPresets[j], g_cfgOvPresets[i]) < 0) {
				char tmp[kCfgOvIdMax]{};
				strncpy(tmp, g_cfgOvPresets[i], sizeof(tmp) - 1);
				strncpy(g_cfgOvPresets[i], g_cfgOvPresets[j], sizeof(g_cfgOvPresets[i]) - 1);
				strncpy(g_cfgOvPresets[j], tmp, sizeof(g_cfgOvPresets[j]) - 1);
			}
		}
	}
	int idx = CfgOvPresetIndexOf(g_cfgOverridePreset);
	if (idx < 0 && g_cfgOvPresetCount > 0)
		CfgOvSelectPreset(g_cfgOvPresets[0]);
	else if (idx >= 0)
		g_cfgOvPresetIdx = idx;
	else {
		g_cfgOverridePreset[0] = 0;
		g_cfgOvPresetIdx = -1;
	}
	g_cfgOvLoaded = false;
	g_cfgOvLineCount = 0;
	Log("cfg_override: scanned %d preset(s), current=%s",
		g_cfgOvPresetCount, g_cfgOverridePreset[0] ? g_cfgOverridePreset : "(none)");
}

// Menu preview only — raw file lines, no format filtering.
// On any open/read failure still mark loaded so the menu Paint path does not
// fopen every frame; Scan/SelectPreset clear g_cfgOvLoaded to retry.
static bool CfgOvLoadCurrent() {
	g_cfgOvLineCount = 0;
	g_cfgOvLoaded = false;
	if (!g_cfgOverridePreset[0]) return false;
	char path[MAX_PATH]{};
	if (!CfgOvDiskPath(path, sizeof(path), g_cfgOverridePreset)) return false;
	FILE* f = fopen(path, "rb");
	if (!f) {
		g_cfgOvLoaded = true;
		Log("cfg_override: read failed %s", path);
		return false;
	}
	char* text = (char*)malloc(kCfgOvMaxFileBytes + 1);
	if (!text) {
		fclose(f);
		g_cfgOvLoaded = true;
		return false;
	}
	const size_t rd = fread(text, 1, kCfgOvMaxFileBytes, f);
	fclose(f);
	text[rd] = 0;
	char* body = text;
	int size = (int)rd;
	if (size >= 3 && (unsigned char)body[0] == 0xEF
		&& (unsigned char)body[1] == 0xBB && (unsigned char)body[2] == 0xBF) {
		body += 3;
		size -= 3;
	}
	int cursor = 0;
	while (cursor < size && g_cfgOvLineCount < kCfgOvMaxLines) {
		int lineStart = cursor;
		while (cursor < size && body[cursor] != '\n' && body[cursor] != '\r') ++cursor;
		const int lineLen = cursor - lineStart;
		if (cursor < size && body[cursor] == '\r') ++cursor;
		if (cursor < size && body[cursor] == '\n') ++cursor;
		if (lineLen <= 0) continue;
		const int copy = lineLen < (kCfgOvLineMax - 1) ? lineLen : (kCfgOvLineMax - 1);
		memcpy(g_cfgOvLines[g_cfgOvLineCount], body + lineStart, (size_t)copy);
		g_cfgOvLines[g_cfgOvLineCount][copy] = 0;
		++g_cfgOvLineCount;
	}
	free(text);
	g_cfgOvLoaded = true;
	Log("cfg_override: preview %s lines=%d", g_cfgOverridePreset, g_cfgOvLineCount);
	return true;
}

static void CfgOvUnlockExec() {
	static bool s_done = false;
	if (s_done || !g_cvar) return;
	// ClientCmd (vtable 7) ignores commands without FCVAR_CLIENTCMD_CAN_EXECUTE.
	// Console typing bypasses that filter — that is why manual `exec` worked.
	s_done = UnlockConCommand("exec", 0, kFCvarClientCmdCanExecute);
}

// ClientCmd("exec x") still filters each line inside the cfg the same way.
// autoexec / console typing do not. Unlock every first token so official cfg
// lines (l4n_cvar, aliases, plain cvars, ...) match console behavior.
static void CfgOvUnlockCommandsInFile(const char* path) {
	FILE* f = fopen(path, "rb");
	if (!f) return;
	char* text = (char*)malloc(kCfgOvMaxFileBytes + 1);
	if (!text) {
		fclose(f);
		return;
	}
	const size_t rd = fread(text, 1, kCfgOvMaxFileBytes, f);
	fclose(f);
	text[rd] = 0;
	char* body = text;
	int size = (int)rd;
	if (size >= 3 && (unsigned char)body[0] == 0xEF
		&& (unsigned char)body[1] == 0xBB && (unsigned char)body[2] == 0xBF) {
		body += 3;
		size -= 3;
	}
	int cursor = 0;
	while (cursor < size) {
		int lineStart = cursor;
		while (cursor < size && body[cursor] != '\n' && body[cursor] != '\r') ++cursor;
		const int lineLen = cursor - lineStart;
		if (cursor < size && body[cursor] == '\r') ++cursor;
		if (cursor < size && body[cursor] == '\n') ++cursor;
		if (lineLen <= 0 || lineLen >= 240) continue;
		char line[256]{};
		memcpy(line, body + lineStart, (size_t)lineLen);
		line[lineLen] = 0;
		char* p = line;
		while (*p == ' ' || *p == '\t') ++p;
		if (!*p || *p == '#' || (*p == '/' && p[1] == '/')) continue;
		char name[64]{};
		int ni = 0;
		while (*p && *p != ' ' && *p != '\t' && ni < (int)sizeof(name) - 1)
			name[ni++] = *p++;
		name[ni] = 0;
		if (name[0])
			UnlockConCommand(name, 0, kFCvarClientCmdCanExecute);
	}
	free(text);
}

static void CfgOvFormatBaseline(void* var, char* out, int outN) {
	if (!out || outN <= 0) return;
	out[0] = 0;
	int n = 0;
	float f = 0.f;
	if (CvarReadPair(var, &n, &f)) {
		if (f == f && fabsf(f - (float)n) < 0.0001f)
			snprintf(out, outN, "%d", n);
		else
			snprintf(out, outN, "%g", (double)f);
	}
}

static void CfgOvRestoreTouched() {
	for (int i = 0; i < g_cfgOvTouchedCount; ++i)
		CvarWriteValue(g_cfgOvTouched[i].name, g_cfgOvTouched[i].baseline);
	if (g_cfgOvTouchedCount > 0) {
		if (g_cfgOvApplyLogLeft > 0) {
			--g_cfgOvApplyLogLeft;
			Log("cfg_override: restored %d touched cvar(s)", g_cfgOvTouchedCount);
		}
	}
	g_cfgOvTouchedCount = 0;
}

// Track ConVar writes inside a cfg so chapter-edge can undo leftovers the
// engine did not reset (same-chapter switching stays additive on purpose).
static bool CfgOvExtractCvarName(char* line, char* nameOut, size_t nameN) {
	if (!line || !nameOut || nameN < 2) return false;
	while (*line == ' ' || *line == '\t') ++line;
	if (!*line || *line == '#' || (*line == '/' && line[1] == '/')) return false;
	char* tok0 = line;
	char* sp = line;
	while (*sp && *sp != ' ' && *sp != '\t') ++sp;
	const bool hasMore = (*sp != 0);
	if (hasMore) *sp++ = 0;
	while (*sp == ' ' || *sp == '\t') ++sp;
	const char* name = tok0;
	if (!_stricmp(tok0, "skt_cvar") || !_stricmp(tok0, "skeeto_cvar")) {
		if (!*sp) return false;
		name = sp;
		char* end = sp;
		while (*end && *end != ' ' && *end != '\t') ++end;
		*end = 0;
	} else if (!hasMore) {
		return false;
	}
	if (!name[0] || strlen(name) >= nameN) return false;
	if (!CvarFind(name)) return false;
	strncpy(nameOut, name, nameN - 1);
	nameOut[nameN - 1] = 0;
	return true;
}

static void CfgOvNoteTouchesFromFile(const char* path) {
	FILE* f = fopen(path, "rb");
	if (!f) return;
	char* text = (char*)malloc(kCfgOvMaxFileBytes + 1);
	if (!text) {
		fclose(f);
		return;
	}
	const size_t rd = fread(text, 1, kCfgOvMaxFileBytes, f);
	fclose(f);
	text[rd] = 0;
	char* body = text;
	int size = (int)rd;
	if (size >= 3 && (unsigned char)body[0] == 0xEF
		&& (unsigned char)body[1] == 0xBB && (unsigned char)body[2] == 0xBF) {
		body += 3;
		size -= 3;
	}
	int cursor = 0;
	while (cursor < size && g_cfgOvTouchedCount < kCfgOvMaxTracked) {
		int lineStart = cursor;
		while (cursor < size && body[cursor] != '\n' && body[cursor] != '\r') ++cursor;
		const int lineLen = cursor - lineStart;
		if (cursor < size && body[cursor] == '\r') ++cursor;
		if (cursor < size && body[cursor] == '\n') ++cursor;
		if (lineLen <= 0 || lineLen >= 240) continue;
		char line[256]{};
		memcpy(line, body + lineStart, (size_t)lineLen);
		line[lineLen] = 0;
		char name[64]{};
		if (!CfgOvExtractCvarName(line, name, sizeof(name))) continue;
		bool exists = false;
		for (int i = 0; i < g_cfgOvTouchedCount; ++i) {
			if (!_stricmp(g_cfgOvTouched[i].name, name)) {
				exists = true;
				break;
			}
		}
		if (exists) continue;
		void* var = CvarFind(name);
		if (!var) continue;
		CfgOvTouch& t = g_cfgOvTouched[g_cfgOvTouchedCount];
		strncpy(t.name, name, sizeof(t.name) - 1);
		t.name[sizeof(t.name) - 1] = 0;
		CfgOvFormatBaseline(var, t.baseline, (int)sizeof(t.baseline));
		if (!t.baseline[0]) strncpy(t.baseline, "0", sizeof(t.baseline) - 1);
		++g_cfgOvTouchedCount;
	}
	free(text);
}

static void CfgOvApply(bool chapterEdge) {
	if (!g_optCfgOverride || !SkeetoFeaturesOn()) return;
	if (g_cfgOvApplying) return;
	if (g_cfgOvNeedScan) CfgOvScanPresets();
	if (!g_cfgOverridePreset[0]) return;
	char path[MAX_PATH]{};
	if (!CfgOvDiskPath(path, sizeof(path), g_cfgOverridePreset)) return;
	if (GetFileAttributesA(path) == INVALID_FILE_ATTRIBUTES) {
		if (g_cfgOvApplyLogLeft > 0) {
			--g_cfgOvApplyLogLeft;
			Log("cfg_override: missing %s", path);
		}
		return;
	}
	// Optional: undo ConVars written by earlier presets this session before
	// chapter exec. Default off — cvars that naturally survive chapters stay.
	if (chapterEdge && g_optCfgOverrideRestore)
		CfgOvRestoreTouched();
	if (g_optCfgOverrideRestore)
		CfgOvNoteTouchesFromFile(path);
	CfgOvUnlockExec();
	CfgOvUnlockCommandsInFile(path);
	char cmd[96]{};
	snprintf(cmd, sizeof(cmd), "exec %s", g_cfgOverridePreset);
	g_cfgOvApplying = true;
	EngClientCmd(cmd);
	g_cfgOvApplying = false;
	if (g_cfgOvApplyLogLeft > 0) {
		--g_cfgOvApplyLogLeft;
		Log("cfg_override: %s chapter=%d restore=%d touched=%d",
			cmd, chapterEdge ? 1 : 0, g_optCfgOverrideRestore ? 1 : 0, g_cfgOvTouchedCount);
	}
}

static bool CfgOvCycle(int delta, bool applyNow) {
	if (g_cfgOvNeedScan) CfgOvScanPresets();
	if (g_cfgOvPresetCount <= 0) return false;
	int idx = g_cfgOvPresetIdx;
	if (idx < 0) idx = 0;
	else {
		idx += (delta >= 0) ? 1 : -1;
		if (idx < 0) idx = g_cfgOvPresetCount - 1;
		if (idx >= g_cfgOvPresetCount) idx = 0;
	}
	CfgOvSelectPreset(g_cfgOvPresets[idx]);
	CfgOvLoadCurrent();
	if (applyNow) {
		g_optCfgOverride = true;
		CfgOvApply(false);
	}
	return true;
}

static bool CfgOvSetById(const char* id, bool applyNow) {
	if (!id || !id[0]) return false;
	if (g_cfgOvNeedScan) CfgOvScanPresets();
	char stem[kCfgOvIdMax]{};
	strncpy(stem, id, sizeof(stem) - 1);
	stem[sizeof(stem) - 1] = 0;
	size_t n = strlen(stem);
	if (n > 4 && !_stricmp(stem + n - 4, ".cfg"))
		stem[n - 4] = 0;
	int idx = CfgOvPresetIndexOf(stem);
	if (idx < 0) return false;
	CfgOvSelectPreset(g_cfgOvPresets[idx]);
	CfgOvLoadCurrent();
	if (applyNow) {
		g_optCfgOverride = true;
		CfgOvApply(false);
	}
	return true;
}

static bool ListenCvarWriteFloat(const char* name, float v) {
	ListenCvarSnap* s = ListenSnapFind(name);
	if (s) ListenSnapCapture(s);
	void* var = CvarFind(name);
	if (!var) return false;
	if (s && s->hasMaxOk) {
		void* parent = CvarParent(var);
		if (parent && PtrCommitted((uint8_t*)parent + 0x3C))
			*((uint8_t*)parent + 0x3C) = 0;
	}
	char buf[48]{};
	snprintf(buf, sizeof(buf), "%g", (double)v);
	const bool ok = CvarWriteValue(name, buf);
	if (s) s->wrote = true;
	g_listenMutated = true;
	void* parent = CvarParent(var);
	if (parent && PtrCommitted(parent)) {
		uint8_t* p = (uint8_t*)parent;
		Log("listen: cvar %s write=%.4f fValue=+2C=%.4f n=+30=%d ok=%d",
			name, v, *(float*)(p + 0x2C), *(int*)(p + 0x30), ok ? 1 : 0);
	}
	return ok;
}

static float* ListenResolveHostTick() {
	if (g_hostTickInterval && PtrCommitted(g_hostTickInterval)) {
		const float v = *g_hostTickInterval;
		if (v >= 0.007f && v <= 0.05f)
			return g_hostTickInterval;
		g_hostTickInterval = nullptr;
	}
	void* es = GetIface("engine.dll", "VEngineServer021");
	if (!es) es = GetIface("engine.dll", "VEngineServer022");
	if (!es || !IfaceAlive(es))
		return nullptr;
	void* fn = VGet(es, 0x50);
	if (!fn || !IsExec(fn))
		return nullptr;
	uint8_t* p = (uint8_t*)fn;
	uintptr_t obj = 0;
	if (p[6] == 0xA1)
		obj = *(uintptr_t*)(p + 7);
	else
		obj = *(uintptr_t*)(p + 7);
	if (!obj || !PtrCommitted((void*)obj))
		return nullptr;
	float* interval = (float*)(obj + 8);
	if (!PtrCommitted(interval))
		return nullptr;
	const float v = *interval;
	if (!(v >= 0.007f && v <= 0.05f))
		return nullptr;
	g_hostTickInterval = interval;
	Log("listen: host interval ptr=%p value=%.6f (tick~%.0f)",
		(void*)interval, v, (v > 0.f) ? (1.f / v) : 0.f);
	return interval;
}

static uint8_t* ListenGlobalsBase() {
	static uint8_t* s_g = nullptr;
	static DWORD s_at = 0;
	const DWORD now = GetTickCount();
	if (s_g && PtrCommitted(s_g + 0x1C) && now - s_at < 250)
		return s_g;
	s_at = now;
	s_g = nullptr;
	void* pim = GetIface("server.dll", "PlayerInfoManager002");
	if (!pim || !IfaceAlive(pim))
		return nullptr;
	using Fn = void*(__thiscall*)(void*);
	auto fn = (Fn)VGet(pim, 1);
	if (!fn || !IsExec((void*)fn))
		return nullptr;
	uint8_t* g = (uint8_t*)fn(pim);
	if (!g || !PtrCommitted(g + 0x1C))
		return nullptr;
	s_g = g;
	return s_g;
}

// CGlobalVarsBase: tickcount at +24, interval_per_tick at +0x1C.
// Advancing tickcount means THIS process is running the server sim (listen host).
static void ListenNoteServerSim() {
	if (!EngConnected()) {
		g_listenServerSimLive.store(false, std::memory_order_relaxed);
		g_listenSimPrevTick.store(-1, std::memory_order_relaxed);
		return;
	}
	uint8_t* g = ListenGlobalsBase();
	if (!g || !PtrCommitted(g + 24)) {
		g_listenServerSimLive.store(false, std::memory_order_relaxed);
		return;
	}
	const int tick = *(int*)(g + 24);
	const int prev = g_listenSimPrevTick.load(std::memory_order_relaxed);
	const DWORD now = GetTickCount();
	if (prev >= 0 && tick != prev)
		g_listenServerSimLive.store(true, std::memory_order_relaxed);
	else {
		const DWORD at = g_listenSimPrevAt.load(std::memory_order_relaxed);
		if (now - at > 1500)
			g_listenServerSimLive.store(false, std::memory_order_relaxed);
	}
	if (tick != prev) {
		g_listenSimPrevTick.store(tick, std::memory_order_relaxed);
		g_listenSimPrevAt.store(now, std::memory_order_relaxed);
	}
}

static float* ListenResolveGlobalsInterval() {
	void* pim = GetIface("server.dll", "PlayerInfoManager002");
	if (!pim || !IfaceAlive(pim))
		return nullptr;
	using Fn = void*(__thiscall*)(void*);
	auto fn = (Fn)VGet(pim, 1);
	if (!fn || !IsExec((void*)fn))
		return nullptr;
	uint8_t* g = (uint8_t*)fn(pim);
	if (!g || !PtrCommitted(g + 0x1C))
		return nullptr;
	float* slot = (float*)(g + 0x1C);
	const float v = *slot;
	if (v != 0.f && !(v >= 0.007f && v <= 0.05f))
		return nullptr;
	return slot;
}

static bool ListenWriteHostTick(int tick, bool alsoGlobals) {
	if (tick < 30) tick = 30;
	if (tick > 128) tick = 128;
	float* slot = ListenResolveHostTick();
	if (!slot) return false;
	const float want = 1.f / (float)tick;
	const float cur = *slot;
	const float d = (cur > want) ? (cur - want) : (want - cur);
	const bool same = (d <= 0.00005f);
	if (!same) {
		if (!g_hostTickSavedOk) {
			g_hostTickSaved = cur;
			g_hostTickSavedOk = true;
		}
		ListenPokeFloat(slot, want);
	}
	if (alsoGlobals) {
		float* gi = ListenResolveGlobalsInterval();
		if (gi) {
			const float gv = *gi;
			const float gd = (gv > want) ? (gv - want) : (want - gv);
			if (gd > 0.00005f) {
				ListenPokeFloat(gi, want);
				Log("listen: gpGlobals interval -> %.6f", want);
			}
		}
	}
	g_listenMutated = true;
	g_listenAppliedTick = tick;
	if (!same)
		Log("listen: host interval -> %.6f (tick %d) globals=%d", want, tick, alsoGlobals ? 1 : 0);
	return true;
}

static void ListenApplyRates(int tick) {
	if (tick < 30) tick = 30;
	ListenCvarWriteInt("sv_minrate", tick * 1000);
	ListenCvarWriteInt("sv_maxrate", tick * 1000);
	ListenCvarWriteInt("sv_mincmdrate", tick);
	ListenCvarWriteInt("sv_maxcmdrate", tick);
	ListenCvarWriteInt("sv_minupdaterate", tick);
	ListenCvarWriteInt("sv_maxupdaterate", tick);
	ListenCvarWriteInt("net_splitpacket_maxrate", (tick / 2) * 1000);
	ListenCvarWriteInt("net_splitrate", 2);
	ListenCvarWriteInt("cl_updaterate", tick);
	ListenCvarWriteInt("cl_cmdrate", tick);
	ListenCvarWriteInt("rate", tick * 1000);
	int fps = ConVarReadIntBounded(CvarFind("fps_max"), 0, 1000);
	if (fps > 0 && fps < tick)
		ListenCvarWriteInt("fps_max", 0);
}

static bool ListenNbWantedFreq(float* out) {
	if (!out) return false;
	if (g_optLocalNb == 1) {
		*out = 0.066f;
		return true;
	}
	if (g_optLocalNb == 2) {
		*out = 0.024f;
		return true;
	}
	if (g_optLocalNb == 3) {
		*out = 0.1f; // engine default
		return true;
	}
	return false; // 0 = 不改：不写 nb_*，避免和本地插件抢
}

static void ListenApplyNb() {
	float freq = 0.f;
	if (!ListenNbWantedFreq(&freq))
		return;
	ListenCvarWriteFloat("nb_update_frequency", freq);
	// ShouldUpdate: framelimit==0 skips the flagged path (Charger/Hunter never start
	// abilities). 15/30ms is the engine default but on listen+high tick commons burn
	// that budget first, so SI slide forever and never Think. Large positive = flagged
	// bots actually run. Frequency still controls how often they are scheduled.
	ListenCvarWriteFloat("nb_update_framelimit", 100.f);
}

static void ListenRestoreNamed(const char* const* names) {
	if (!names) return;
	for (int i = 0; names[i]; ++i) {
		ListenCvarSnap* s = ListenSnapFind(names[i]);
		if (!s || !s->saved || !s->wrote) continue;
		void* var = CvarFind(s->name);
		if (var) {
			CvarPokePair(var, s->n, s->f);
			if (s->hasMaxOk) {
				void* parent = CvarParent(var);
				if (parent && PtrCommitted((uint8_t*)parent + 0x3C))
					*((uint8_t*)parent + 0x3C) = s->hasMax;
			}
			CvarWriteFlags(var, s->flags);
		}
		s->wrote = false;
	}
}

static void ListenApplyAllow0Lerp() {
	ListenCvarWriteInt("sv_client_min_interp_ratio", -1);
	ListenCvarWriteInt("sv_client_max_interp_ratio", 1);
}

static void ListenApplyPausable() {
	if (g_optLocalPausable) {
		ListenCvarWriteInt("sv_pausable", 1);
		return;
	}
	ListenCvarSnap* s = ListenSnapFind("sv_pausable");
	if (s && s->wrote)
		EngClientCmdUnrestricted("unpause");
	static const char* kPause[] = { "sv_pausable", nullptr };
	ListenRestoreNamed(kPause);
}

static void ListenApplyLerp() {
	if (g_optLocalLerp < 0) return;
	ListenCvarWriteFloat("cl_interp", (float)g_optLocalLerp / 1000.f);
	ListenCvarWriteFloat("cl_interp_ratio", 0.f);
}

static void ListenApplyIdleBotAllow() {
	// Same requirement as solo-idle guides / most SM servers: keep running with only bots.
	const bool a = ListenCvarWriteInt("sb_all_bot_game", 1);
	const bool b = ListenCvarWriteInt("allow_all_bot_survivor_team", 1);
	Log("listen: idle bot allow sb_all_bot_game=%d allow_team=%d", a ? 1 : 0, b ? 1 : 0);
}

static void ListenApplyAirAccel() {
	// Never touch this during server LevelInit / loading — a bad IConVar
	// SetValue call crashed server.dll+F28DF on the loading screen.
	// Only the game thread (EngineVGui::Paint). Worker-thread ClientCmd
	// can drop KEY_UP and leave +forward latched.
	if (!g_paintTid || GetCurrentThreadId() != g_paintTid)
		return;
	int want = 10;
	if (g_optLocalAa == 100 || g_optLocalAa == 400 || g_optLocalAa == 1000)
		want = g_optLocalAa;
	if (g_aaCmdApplied == want)
		return;
	ListenCvarSnap* snap = ListenSnapFind("sv_airaccelerate");
	if (want == 10 && (!snap || !snap->wrote)) {
		g_aaCmdApplied = 10;
		return;
	}
	if (g_paintInGame.load(std::memory_order_relaxed)) {
		// cached this Paint — skip extra EngInGame
	} else if (!g_engine || !EngInGame() || EngDrawingLoading()) {
		return;
	}
	if (want == 10) {
		static const char* kAir[] = { "sv_airaccelerate", nullptr };
		ListenRestoreNamed(kAir);
		if (snap) snap->saved = false;
		g_aaCmdApplied = 10;
		return;
	}
	ListenSnapCapture(snap);
	if (!snap || !snap->saved) return;
	CvarSetInt("sv_airaccelerate", want);
	snap->wrote = true;
	g_aaCmdApplied = want;
	if (want != 10)
		g_listenMutated = true;
	Log("listen: sv_airaccelerate %d", want);
}

static void ListenRestoreAirAccel(const char* why) {
	static const char* kAir[] = { "sv_airaccelerate", nullptr };
	ListenRestoreNamed(kAir);
	g_aaCmdApplied = -1;
	(void)why;
}

// Solo AFK (all-bot) often spams chat with director flow errors — mute the string in-process.
static char* g_flowSpamStr = nullptr;
static char g_flowSpamOrig = 0;
static bool g_flowSpamMuted = false;

static char* FindModCString(const char* module, const char* needle) {
	HMODULE h = GetModuleHandleA(module);
	if (!h || !needle || !needle[0]) return nullptr;
	auto dos = (PIMAGE_DOS_HEADER)h;
	auto nt = (PIMAGE_NT_HEADERS)((uint8_t*)h + dos->e_lfanew);
	auto base = (uint8_t*)h;
	const size_t size = (size_t)nt->OptionalHeader.SizeOfImage;
	const size_t nlen = strlen(needle);
	if (nlen == 0 || nlen >= size) return nullptr;
	for (size_t i = 0; i + nlen < size; ++i) {
		if (base[i] != (uint8_t)needle[0]) continue;
		if (memcmp(base + i, needle, nlen) == 0)
			return (char*)(base + i);
	}
	return nullptr;
}

static void ListenMuteDirectorFlowSpam(bool mute) {
	if (mute == g_flowSpamMuted) return;
	if (mute) {
		if (!g_flowSpamStr) {
			g_flowSpamStr = FindModCString("server.dll", "ERROR: FLOW IS BROKEN");
			if (!g_flowSpamStr)
				g_flowSpamStr = FindModCString("server.dll", "FLOW IS BROKEN");
		}
		if (!g_flowSpamStr || !g_flowSpamStr[0]) {
			Log("listen: flow-spam string not found (ok if unused)");
			return;
		}
		DWORD old = 0;
		if (!VirtualProtect(g_flowSpamStr, 1, PAGE_READWRITE, &old)) return;
		g_flowSpamOrig = g_flowSpamStr[0];
		g_flowSpamStr[0] = '\0';
		VirtualProtect(g_flowSpamStr, 1, old, &old);
		g_flowSpamMuted = true;
		Log("listen: muted director flow-spam chat");
	} else {
		if (g_flowSpamStr && g_flowSpamMuted && g_flowSpamOrig) {
			DWORD old = 0;
			if (VirtualProtect(g_flowSpamStr, 1, PAGE_READWRITE, &old)) {
				g_flowSpamStr[0] = g_flowSpamOrig;
				VirtualProtect(g_flowSpamStr, 1, old, &old);
			}
		}
		g_flowSpamMuted = false;
		g_flowSpamOrig = 0;
		Log("listen: restored director flow-spam string");
	}
}

// go_afk_unlock + direct GoAwayFromKeyboard (left4dhooks-style).
// Vanilla command only sets a timer; PreThink later calls GoAway — flaky alone.
// JMP Input_GoAwayFromKeyboard -> call GoAwayFromKeyboard(this) so bind works every time.
enum {
	kAfkPreComp = 0, // PreThink +309: jcc -> 6xNOP (versus)
	kAfkPreHuman,    // PreThink +428: cmp imm 1->0 (auto-idle when alone)
	kAfkPreHumanJle, // PreThink +429: jle -> NOP
	kAfkSlotCount
};
struct AfkSlot {
	uint8_t* p;
	uint8_t orig[8];
	uint8_t patch[8];
	int n;
	bool applied;
	bool mismatch;
};
static AfkSlot g_afkSlot[kAfkSlotCount]{};
static HMODULE g_afkServerMod = nullptr;
static bool g_afkResolved = false;
static bool g_afkResolveFail = false;
static bool g_afkLoggedFail = false;
static uint8_t* g_afkInputFn = nullptr;
static uint8_t* g_afkGoAwayFn = nullptr;
static uint8_t* g_afkStub = nullptr;
static uint8_t g_afkInputOrig[5]{};
static bool g_afkInputDetoured = false;

static bool AfkWrite(uint8_t* p, const uint8_t* src, int n) {
	if (!p || n <= 0 || n > 8 || !PtrCommitted(p)) return false;
	DWORD old = 0, tmp = 0;
	if (!VirtualProtect(p, (SIZE_T)n, PAGE_EXECUTE_READWRITE, &old))
		return false;
	memcpy(p, src, (size_t)n);
	VirtualProtect(p, (SIZE_T)n, old, &tmp);
	FlushInstructionCache(GetCurrentProcess(), p, (SIZE_T)n);
	return true;
}

static bool AfkMemEq(const uint8_t* p, const uint8_t* b, int n) {
	return p && b && n > 0 && memcmp(p, b, (size_t)n) == 0;
}

static void AfkRemoveInputDetour() {
	if (!g_afkInputDetoured) return;
	if (g_afkInputFn && PtrCommitted(g_afkInputFn)
		&& GetModuleHandleA("server.dll") == g_afkServerMod)
		AfkWrite(g_afkInputFn, g_afkInputOrig, 5);
	g_afkInputDetoured = false;
	Log("listen: afk Input detour removed");
}

static void AfkForgetSlots() {
	AfkRemoveInputDetour();
	for (int i = 0; i < kAfkSlotCount; ++i) {
		AfkSlot& s = g_afkSlot[i];
		s.p = nullptr;
		s.n = 0;
		s.applied = false;
		s.mismatch = false;
		memset(s.orig, 0, sizeof(s.orig));
		memset(s.patch, 0, sizeof(s.patch));
	}
	g_afkResolved = false;
	g_afkInputFn = nullptr;
	g_afkGoAwayFn = nullptr;
}

static bool AfkFillSlot(AfkSlot& s, uint8_t* p, const uint8_t* patch, int n, const uint8_t* expect, int expectN) {
	s.p = nullptr;
	s.n = 0;
	s.mismatch = false;
	if (!p || !PtrCommitted(p) || n <= 0 || n > 8) return false;
	if (expect && expectN > 0 && !AfkMemEq(p, expect, expectN)) {
		s.mismatch = true;
		return false;
	}
	s.p = p;
	s.n = n;
	memcpy(s.patch, patch, (size_t)n);
	memcpy(s.orig, p, (size_t)n);
	return true;
}

static bool AfkEnsureStub() {
	if (g_afkStub) return true;
	g_afkStub = (uint8_t*)VirtualAlloc(nullptr, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
	if (!g_afkStub) {
		Log("listen: afk stub VirtualAlloc failed");
		return false;
	}
	return true;
}

static bool AfkInstallInputDetour() {
	if (!g_afkInputFn || !g_afkGoAwayFn || !AfkEnsureStub())
		return false;
	int32_t callRel = (int32_t)(g_afkGoAwayFn - (g_afkStub + 5));
	g_afkStub[0] = 0xE8;
	memcpy(g_afkStub + 1, &callRel, 4);
	g_afkStub[5] = 0xC3;
	FlushInstructionCache(GetCurrentProcess(), g_afkStub, 6);

	uint8_t jmp[5] = { 0xE9, 0, 0, 0, 0 };
	int32_t jmpRel = (int32_t)(g_afkStub - (g_afkInputFn + 5));
	memcpy(jmp + 1, &jmpRel, 4);
	if (g_afkInputDetoured) {
		if (!AfkMemEq(g_afkInputFn, jmp, 5))
			AfkWrite(g_afkInputFn, jmp, 5);
		return true;
	}
	memcpy(g_afkInputOrig, g_afkInputFn, 5);
	if (g_afkInputFn[0] != 0x57 || g_afkInputFn[1] != 0x8B || g_afkInputFn[3] != 0xE8) {
		Log("listen: afk Input head %02X %02X %02X %02X (want 57 8B ?? E8) — skip detour input=%p",
			g_afkInputFn[0], g_afkInputFn[1], g_afkInputFn[2], g_afkInputFn[3],
			(void*)g_afkInputFn);
		return false;
	}
	if (!AfkWrite(g_afkInputFn, jmp, 5))
		return false;
	g_afkInputDetoured = true;
	g_listenMutated = true;
	Log("listen: afk Input -> GoAway detour ok input=%p goaway=%p stub=%p",
		(void*)g_afkInputFn, (void*)g_afkGoAwayFn, (void*)g_afkStub);
	return true;
}

static bool ListenAfkResolve() {
	HMODULE mod = GetModuleHandleA("server.dll");
	if (!mod) {
		AfkForgetSlots();
		g_afkServerMod = nullptr;
		g_afkResolveFail = false;
		return false;
	}
	if (mod == g_afkServerMod && g_afkResolved)
		return true;
	if (mod == g_afkServerMod && g_afkResolveFail)
		return false;

	AfkForgetSlots();
	g_afkServerMod = mod;
	g_afkResolveFail = false;

	uintptr_t preHits[8]{};
	const int preN = CountPat("server.dll",
		"55 8B ? 83 ? ? A1 ? ? ? ? 33 ? 89 ? ? 56 57 8B ? E8 ? ? ? ? 8B ? E8",
		preHits, 8);
	const char* inpPat = "57 8B ? E8 ? ? ? ? 84 ? 75 ? 56 6A";
	uintptr_t inpHits[8]{};
	const int inpN = CountPat("server.dll", inpPat, inpHits, 8);
	uintptr_t goHits[8]{};
	const int goN = CountPat("server.dll",
		"55 8B EC 83 EC 08 53 56 57 8B F1 8B 06 8B 90 C8 08 00 00",
		goHits, 8);
	const uintptr_t pre = (preN == 1) ? preHits[0] : 0;
	const uintptr_t inp = (inpN == 1) ? inpHits[0] : 0;
	const uintptr_t go = (goN == 1) ? goHits[0] : 0;
	if (inpN != 1) {
		Log("listen: afk Input sig hits=%d (need 1) — skip Input detour", inpN);
		for (int i = 0; i < inpN && i < 8; ++i)
			Log("  input hit[%d]=%p", i, (void*)inpHits[i]);
	}
	if (preN != 1) {
		Log("listen: afk PreThink sig hits=%d (need 1)", preN);
		for (int i = 0; i < preN && i < 8; ++i)
			Log("  pre hit[%d]=%p", i, (void*)preHits[i]);
	}
	if (goN != 1) {
		Log("listen: afk GoAway sig hits=%d (need 1)", goN);
		for (int i = 0; i < goN && i < 8; ++i)
			Log("  go hit[%d]=%p", i, (void*)goHits[i]);
	}
	if (!pre || !go) {
		g_afkResolveFail = true;
		if (!g_afkLoggedFail) {
			g_afkLoggedFail = true;
			Log("listen: afk sig miss pre=%p input=%p goaway=%p (preN=%d goN=%d)",
				(void*)pre, (void*)inp, (void*)go, preN, goN);
		}
		return false;
	}

	uint8_t* preP = (uint8_t*)pre;
	g_afkInputFn = inp ? (uint8_t*)inp : nullptr;
	g_afkGoAwayFn = (uint8_t*)go;
	const uint8_t nop6[6] = { 0x90, 0x90, 0x90, 0x90, 0x90, 0x90 };
	const uint8_t nop2[2] = { 0x90, 0x90 };
	const uint8_t expectJcc[1] = { 0x0F };
	const uint8_t human0[1] = { 0x00 };
	const uint8_t expect1[1] = { 0x01 };
	const uint8_t expectJle[1] = { 0x7E };

	bool ok = true;
	ok = AfkFillSlot(g_afkSlot[kAfkPreComp], preP + 309, nop6, 6, expectJcc, 1) && ok;
	ok = AfkFillSlot(g_afkSlot[kAfkPreHuman], preP + 428, human0, 1, expect1, 1) && ok;
	ok = AfkFillSlot(g_afkSlot[kAfkPreHumanJle], preP + 429, nop2, 2, expectJle, 1) && ok;

	if (!ok) {
		g_afkResolveFail = true;
		if (!g_afkLoggedFail) {
			g_afkLoggedFail = true;
			Log("listen: afk PreThink offset mismatch pre+309=%02X pre+428=%02X pre+429=%02X",
				preP[309], preP[428], preP[429]);
		}
		AfkForgetSlots();
		return false;
	}

	g_afkResolved = true;
	Log("listen: afk resolved PreThink=%p Input=%p GoAway=%p", (void*)pre, (void*)inp, (void*)go);
	return true;
}

static bool AfkSlotWanted(int id) {
	return g_optLocalIdleSolo
		&& (id == kAfkPreComp || id == kAfkPreHuman || id == kAfkPreHumanJle);
}

static void ListenAfkRestoreUnlocked(const char* why) {
	AfkRemoveInputDetour();
	bool any = false;
	for (int i = 0; i < kAfkSlotCount; ++i) {
		AfkSlot& s = g_afkSlot[i];
		if (!s.applied) continue;
		if (s.p && PtrCommitted(s.p) && GetModuleHandleA("server.dll") == g_afkServerMod)
			AfkWrite(s.p, s.orig, s.n);
		s.applied = false;
		any = true;
	}
	if (any)
		Log("listen: afk restored (%s)", why ? why : "?");
}

static void ListenAfkRestore(const char* why) {
	ListenCsEnsure();
	EnterCriticalSection(&g_listenCs);
	ListenAfkRestoreUnlocked(why);
	LeaveCriticalSection(&g_listenCs);
}

static void ListenAfkSyncUnlocked() {
	const bool wantAny = g_optLocalIdleSolo || g_optLocalIdleNoDelay;
	if (!wantAny) {
		ListenAfkRestoreUnlocked("opts-off");
		return;
	}
	if (!ListenAfkResolve())
		return;

	int wrote = 0, restored = 0;
	for (int i = 0; i < kAfkSlotCount; ++i) {
		AfkSlot& s = g_afkSlot[i];
		const bool want = AfkSlotWanted(i);
		if (want) {
			if (s.applied && s.p && AfkMemEq(s.p, s.patch, s.n))
				continue;
			if (!s.p || !AfkWrite(s.p, s.patch, s.n)) continue;
			s.applied = true;
			g_listenMutated = true;
			++wrote;
		} else if (s.applied) {
			if (s.p && PtrCommitted(s.p))
				AfkWrite(s.p, s.orig, s.n);
			s.applied = false;
			++restored;
		}
	}

	bool detourOk = true;
	if (g_optLocalIdleNoDelay)
		detourOk = AfkInstallInputDetour();
	else
		AfkRemoveInputDetour();
	Log("listen: afk sync solo=%d nodelay=%d wrote=%d restored=%d detour=%d input0=%02X",
		g_optLocalIdleSolo ? 1 : 0, g_optLocalIdleNoDelay ? 1 : 0, wrote, restored, detourOk ? 1 : 0,
		g_afkInputFn ? g_afkInputFn[0] : 0xFF);
}

static void ListenAfkSync() {
	ListenCsEnsure();
	EnterCriticalSection(&g_listenCs);
	ListenAfkSyncUnlocked();
	LeaveCriticalSection(&g_listenCs);
}

static void ListenAfkSyncUnlocked();
static void LocalPlaySync(const char* why);
static void LocalPlayRestore(const char* why);
static void LocalPlayPaint();
static void StaggerHudPaint();
static void StaggerHudOnPlayerShoved(void* ev);
static void StaggerHudOnPlayerDeath(void* ev);
static void StaggerHudClear();
static void WorldTankPredictPaint();
static void WorldTankPredictClear();
static bool EntNetDormant(int index);
static void LocalPlayOnRoundBoundary(bool start);
static void LocalPlayOnWitchSpawn(void* ev);
static void LocalPlayOnWitchKilled(void* ev);
static bool IsWitchClass(const char* name);
static void LocalPlayClearHpTrack();
static bool LocalPlayOptsWanted();
static void LocalPlayPrecacheAllSurvivors(const char* why);
static void LocalPlayNotifySiHp(void* ent, int objectId, int newHp, int userid);
bool IsLocalAttacker(void* ev);

static void ListenRestoreSnaps() {
	for (int i = 0; i < kListenSnapCount; ++i) {
		ListenCvarSnap& s = g_listenSnaps[i];
		if (!s.saved || !s.wrote) {
			s.saved = false;
			s.wrote = false;
			s.hasMaxOk = false;
			continue;
		}
		void* var = CvarFind(s.name);
		if (var) {
			CvarPokePair(var, s.n, s.f);
			if (s.hasMaxOk) {
				void* parent = CvarParent(var);
				if (parent && PtrCommitted((uint8_t*)parent + 0x3C))
					*((uint8_t*)parent + 0x3C) = s.hasMax;
			}
			CvarWriteFlags(var, s.flags);
		}
		s.saved = false;
		s.wrote = false;
		s.hasMaxOk = false;
	}
}

static void ListenRestoreHostTick() {
	if (!g_hostTickSavedOk) return;
	// Never poke interval while a map is running — that launches the player.
	if (EngInGame()) return;
	const float want = (g_hostTickSavedOk && g_hostTickSaved >= 0.007f && g_hostTickSaved <= 0.05f)
		? g_hostTickSaved : (1.f / 30.f);
	if (!g_hostTickInterval || !PtrCommitted(g_hostTickInterval)) return;
	ListenPokeFloat(g_hostTickInterval, want);
	g_listenAppliedTick = (int)(1.f / want + 0.5f);
	g_hostTickSavedOk = false;
}

static void ListenRestore(const char* why) {
	if (!g_listenMutated) return;
	ListenCsEnsure();
	EnterCriticalSection(&g_listenCs);
	if (!g_listenMutated) {
		LeaveCriticalSection(&g_listenCs);
		return;
	}
	ListenAfkRestoreUnlocked(why);
	LocalPlayRestore(why);
	ListenMuteDirectorFlowSpam(false);
	ListenRestoreAirAccel(why);
	ListenRestoreSnaps();
	ListenRestoreHostTick();
	g_listenMutated = false;
	g_listenDirty = false;
	LeaveCriticalSection(&g_listenCs);
	Log("listen: restored (%s)", why ? why : "?");
}

static bool ListenOptsWanted() {
	return g_optLocalTick != 0 || g_optLocalNb != 0 || g_optLocalAllow0Lerp || g_optLocalLerp >= 0
		|| g_optLocalIdleSolo || g_optLocalIdleNoDelay
		|| g_optLocalAa != 10
		|| g_optLocalCharChange
		|| g_optLocalPausable;
}

static bool ListenWhyWritesTick(const char* why) {
	if (why && strcmp(why, "menu") == 0)
		return !EngInGame();
	if (why && (strcmp(why, "levelinit") == 0 || strcmp(why, "preentity") == 0
		|| strcmp(why, "server-levelinit") == 0))
		return true;
	return !EngInGame();
}

static bool ListenWriteTickNow(int tick, const char* why) {
	(void)why;
	return ListenWriteHostTick(tick, true);
}

static void ListenApply(const char* why) {
	if (!ListenDetectHost())
		return;
	ListenCsEnsure();
	EnterCriticalSection(&g_listenCs);
	if (!ListenDetectHost()) {
		LeaveCriticalSection(&g_listenCs);
		return;
	}
	if (!ListenOptsWanted() && !g_listenMutated) {
		g_listenDirty = false;
		LeaveCriticalSection(&g_listenCs);
		return;
	}
	if (g_optLocalTick != 0) {
		if (ListenWhyWritesTick(why)) {
			if (!ListenWriteTickNow(g_optLocalTick, why))
				Log("listen: tick unlock unavailable (cvars only) want=%d", g_optLocalTick);
			ListenApplyRates(g_optLocalTick);
		} else if (g_listenAppliedTick != g_optLocalTick) {
			Log("listen: tick %d queued until map change (now ~%d)", g_optLocalTick, g_listenAppliedTick);
		} else {
			ListenApplyRates(g_optLocalTick);
		}
	} else if (g_listenAppliedTick > 0 && g_hostTickSavedOk) {
		// 不改：若本会话曾写过 tick，恢复快照；从未动过则完全不碰
		if (!ListenWhyWritesTick(why)) {
			Log("listen: tick leave queued until map change (now ~%d)", g_listenAppliedTick);
		} else {
			ListenRestoreHostTick();
			static const char* kRate[] = {
				"sv_minrate", "sv_maxrate", "sv_mincmdrate", "sv_maxcmdrate",
				"sv_minupdaterate", "sv_maxupdaterate", "net_splitpacket_maxrate",
				"net_splitrate", "cl_updaterate", "cl_cmdrate", "rate", "fps_max",
				nullptr
			};
			for (int i = 0; kRate[i]; ++i) {
				ListenCvarSnap* s = ListenSnapFind(kRate[i]);
				if (!s || !s->saved || !s->wrote) continue;
				void* var = CvarFind(s->name);
				if (var) {
					CvarPokePair(var, s->n, s->f);
					if (s->hasMaxOk) {
						void* parent = CvarParent(var);
						if (parent && PtrCommitted((uint8_t*)parent + 0x3C))
							*((uint8_t*)parent + 0x3C) = s->hasMax;
					}
					CvarWriteFlags(var, s->flags);
				}
				s->wrote = false;
			}
		}
	}
	float nbFreq = 0.f;
	if (ListenNbWantedFreq(&nbFreq))
		ListenApplyNb();
	else {
		static const char* kNb[] = { "nb_update_frequency", "nb_update_framelimit", nullptr };
		ListenRestoreNamed(kNb);
	}
	if (g_optLocalAllow0Lerp)
		ListenApplyAllow0Lerp();
	else {
		static const char* kAllow[] = {
			"sv_client_min_interp_ratio", "sv_client_max_interp_ratio", nullptr
		};
		ListenRestoreNamed(kAllow);
	}
	if (g_optLocalLerp >= 0)
		ListenApplyLerp();
	else {
		static const char* kLerp[] = { "cl_interp", "cl_interp_ratio", nullptr };
		ListenRestoreNamed(kLerp);
	}
	if (g_optLocalIdleSolo)
		ListenApplyIdleBotAllow();
	else {
		static const char* kIdleBot[] = { "sb_all_bot_game", "allow_all_bot_survivor_team", nullptr };
		ListenRestoreNamed(kIdleBot);
	}
	ListenApplyPausable();
	ListenApplyAirAccel();
	ListenMuteDirectorFlowSpam(g_optLocalIdleSolo);
	ListenAfkSyncUnlocked();
	g_listenDirty = false;
	LeaveCriticalSection(&g_listenCs);
	LocalPlaySync(why);
	Log("listen: apply (%s) host=1 tick=%d nb=%d freq=%.4f allow0=%d lerp=%d idle=%d/%d aa=%d pause=%d mutated=%d",
		why ? why : "?", g_optLocalTick, g_optLocalNb, nbFreq,
		g_optLocalAllow0Lerp ? 1 : 0, g_optLocalLerp,
		g_optLocalIdleSolo ? 1 : 0, g_optLocalIdleNoDelay ? 1 : 0, g_optLocalAa,
		g_optLocalPausable ? 1 : 0, g_listenMutated ? 1 : 0);
}

// IServerGameDLL::LevelInit runs only in THIS process when it is hosting.
// Do not wait for loopback netchan — that is too late, NextBots already spawned.
static void ListenApplyServerBoot(const char* why) {
	ListenCsEnsure();
	EnterCriticalSection(&g_listenCs);
	if (g_optLocalTick != 0) {
		if (!ListenWriteHostTick(g_optLocalTick, true))
			Log("listen: tick unlock unavailable (cvars only) want=%d", g_optLocalTick);
		ListenApplyRates(g_optLocalTick);
	}
	float nbFreq = 0.f;
	if (ListenNbWantedFreq(&nbFreq))
		ListenApplyNb();
	if (g_optLocalAllow0Lerp)
		ListenApplyAllow0Lerp();
	if (g_optLocalLerp >= 0)
		ListenApplyLerp();
	if (g_optLocalIdleSolo)
		ListenApplyIdleBotAllow();
	if (g_optLocalPausable)
		ListenCvarWriteInt("sv_pausable", 1);
	ListenAfkSyncUnlocked();
	ListenMuteDirectorFlowSpam(g_optLocalIdleSolo);
	g_listenDirty = false;
	LeaveCriticalSection(&g_listenCs);
	LocalPlaySync(why);
	Log("listen: apply (%s) boot tick=%d nb=%d freq=%.4f allow0=%d lerp=%d idle=%d/%d aa=%d pause=%d",
		why ? why : "?", g_optLocalTick, g_optLocalNb, nbFreq,
		g_optLocalAllow0Lerp ? 1 : 0, g_optLocalLerp,
		g_optLocalIdleSolo ? 1 : 0, g_optLocalIdleNoDelay ? 1 : 0, g_optLocalAa,
		g_optLocalPausable ? 1 : 0);
}

static void ListenPump() {
	if (!g_run.load(std::memory_order_relaxed))
		return;
	// Worker must not call engine APIs once Paint owns the game thread.
	if (g_paintTid && GetCurrentThreadId() != g_paintTid)
		return;
	const DWORD now = GetTickCount();
	static DWORD s_listenAt = 0;
	const bool due = g_listenDirty || !s_listenAt || (now - s_listenAt >= 100);
	if (!due) {
		if (g_listenHost.load(std::memory_order_relaxed))
			ListenApplyAirAccel();
		return;
	}
	s_listenAt = now;
	// server.dll gone: drop AFK/listen binary patches (module memory invalid). Do not
	// return early — lobby still needs ListenWriteHostTick / remote restore paths.
	// Module presence changes are sampled with the rest of ListenPump at 10 Hz;
	// there is no reason to take the loader path on every rendered frame.
	if (!GetModuleHandleA("server.dll")) {
		if (g_afkResolved || g_afkInputDetoured || g_listenMutated) {
			ListenAfkRestore("no-server");
			ListenCsEnsure();
			EnterCriticalSection(&g_listenCs);
			AfkForgetSlots();
			g_afkServerMod = nullptr;
			g_afkResolveFail = false;
			LeaveCriticalSection(&g_listenCs);
			LocalPlayRestore("no-server");
			ListenRestore("no-server");
		}
		g_listenMapHost.store(false, std::memory_order_relaxed);
		g_listenServerSimLive.store(false, std::memory_order_relaxed);
	}
	EnsureServerGameHooks();
	const bool connected = (g_paintTid && GetCurrentThreadId() == g_paintTid)
		? g_paintConnected.load(std::memory_order_relaxed)
		: (g_engine && EngConnected());
	if (!connected) {
		g_listenMapHost.store(false, std::memory_order_relaxed);
		g_listenServerSimLive.store(false, std::memory_order_relaxed);
		g_listenSimPrevTick.store(-1, std::memory_order_relaxed);
	}
	ListenNoteServerSim();
	const bool host = ListenDetectHost();
	const bool was = g_listenHost.exchange(host, std::memory_order_relaxed);
	if (!host) {
		if (connected) {
			if (was || g_listenMutated) {
				ListenAfkRestore(was ? "left-listen" : "remote");
				LocalPlayRestore(was ? "left-listen" : "remote");
				ListenMuteDirectorFlowSpam(false);
				if (g_listenMutated)
					ListenRestore(was ? "left-listen" : "not-listen");
			}
			// A running map may have deferred the tick restore. Keep its snapshot
			// until the existing !EngInGame safe window; never force it in-game.
			if (g_hostTickSavedOk && !EngInGame()) {
				ListenCsEnsure();
				EnterCriticalSection(&g_listenCs);
				ListenRestoreHostTick();
				LeaveCriticalSection(&g_listenCs);
			}
		} else {
			// Lobby / map load: netchan may briefly look non-host — keep AFK patches.
			if (!(g_optLocalIdleSolo || g_optLocalIdleNoDelay))
				ListenAfkRestore("opts-off-lobby");
			ListenCsEnsure();
			EnterCriticalSection(&g_listenCs);
			if (g_optLocalTick != 0)
				ListenWriteHostTick(g_optLocalTick, false);
			else if (g_hostTickSavedOk)
				ListenRestoreHostTick();
			LeaveCriticalSection(&g_listenCs);
		}
		return;
	}
	if (!was)
		g_listenDirty = true;
	if (!was)
		ListenLogDetect("!entered");
	if (g_listenDirty || (ListenOptsWanted() && !g_listenMutated))
		ListenApply(was ? "pump" : "entered-listen");
	if (g_paintInGame.load(std::memory_order_relaxed))
		ListenApplyAirAccel();
}

