static void LocalPlayMarkSiDead(int uid, int ent) {
	if (ent < 1 || ent > 64) return;
	if (uid > 0 && g_hpLifeUid[ent].load(std::memory_order_relaxed) != uid) return;
	g_hpLifeDead[ent].store(true, std::memory_order_release);
	if (ent == g_hpTrackEnt) LocalPlayClearHpTrack();
}

static void LocalPlayOnHpLifeEvent(void* ev, bool spawn) {
	if (!g_optClientInfectedHp || !ev) return;
	const int uid = EvInt(ev, "userid");
	if (uid <= 0) return;
	// A first-hit kill may arrive before Paint has opened any bar for this slot.
	// Use the explicit death field only; never resolve an entity in this callback.
	if (!spawn) {
		const int ent = EvInt(ev, "entityid");
		if (ent >= 1 && ent <= 64) {
			int empty = 0;
			g_hpLifeUid[ent].compare_exchange_strong(empty, uid, std::memory_order_release);
		}
	}
	// At most 64 cached player slots, only on spawn/death; no engine lookup here.
	for (int i = 1; i <= 64; ++i) {
		if (g_hpLifeUid[i].load(std::memory_order_relaxed) != uid) continue;
		g_hpLifeDead[i].store(!spawn, std::memory_order_release);
		if (spawn) g_hpLifeSpawn[i].fetch_add(1, std::memory_order_release);
	}
}

static bool LocalPlayEntIsDead(void* ent) {
	if (!ent) return true;
	if (g_offLifeState >= 0 && g_offLifeState <= 0x4000) {
		// m_lifeState: 0=alive, 1=dying, 2=dead (byte on L4D2)
		if (*(uint8_t*)((uint8_t*)ent + g_offLifeState) != 0) return true;
	}
	if (g_offHealth >= 0 && g_offHealth <= 0x4000) {
		const int hp = *(int*)((uint8_t*)ent + g_offHealth);
		if (hp <= 0) return true;
	}
	return false;
}

static bool LocalPlayHpEntIsDead(void* ent) {
	if (LocalPlayEntIsDead(ent)) return true;
	// Tank's dying animation uses incapacitated HP before final player_death.
	return g_offZombieClass >= 0 && g_offZombieClass <= 0x4000
		&& *(int*)((uint8_t*)ent + g_offZombieClass) == 8
		&& g_offIsIncapacitated >= 0 && g_offIsIncapacitated <= 0x4000
		&& *(uint8_t*)((uint8_t*)ent + g_offIsIncapacitated) != 0;
}

float LocalPlayHeadLift(int zc) {
	switch (zc) {
	case 1: return 68.f;
	case 2: return 58.f;
	case 3: return 44.f;
	case 4: return 54.f;
	case 5: return 34.f;
	case 6: return 70.f;
	case 8: return 82.f;
	default: return 60.f;
	}
}

bool LocalPlayWorldToScreen(const float* world, float* outSx, float* outSy, int sw, int sh) {
	if (!g_engine || !world || !outSx || !outSy || sw < 8 || sh < 8) return false;
	using MatFn = const float*(__thiscall*)(void*);
	static MatFn s_getM = nullptr;
	if (!s_getM) {
		s_getM = (MatFn)VGet(g_engine, kEngWorldToScreenMatrix);
		if (!s_getM || !IsExec((void*)s_getM)) {
			s_getM = nullptr;
			return false;
		}
	}
	const float* m = s_getM(g_engine);
	if (!m) return false;
	const float x = world[0], y = world[1], z = world[2];
	const float w = m[12] * x + m[13] * y + m[14] * z + m[15];
	if (w < 0.001f) return false;
	const float inv = 1.f / w;
	const float nx = (m[0] * x + m[1] * y + m[2] * z + m[3]) * inv;
	const float ny = (m[4] * x + m[5] * y + m[6] * z + m[7]) * inv;
	*outSx = (sw * 0.5f) + (0.5f * nx * sw) + 0.5f;
	*outSy = (sh * 0.5f) - (0.5f * ny * sh) + 0.5f;
	return *outSx > -80.f && *outSx < sw + 80.f && *outSy > -80.f && *outSy < sh + 80.f;
}

static void StaggerHudTrackVictim(void* ev) {
	if (!g_optStaggerHud || !ev || !IsLocalAttacker(ev)) return;
	const int uid = EvInt(ev, "userid");
	const int ent = EngPlayerForUserID(uid);
	if (ent < 1 || ent > 64) return;
	void* e = EntGet(ent);
	if (!EntReadable(e) || g_offTeam < 0 || g_offTeam > 0x4000) return;
	if (*(int*)((uint8_t*)e + g_offTeam) != 3 || LocalPlayEntIsDead(e)) return;

	if (ent != g_staggerTrackEnt) {
		g_staggerAnimSeen = false;
		g_staggerAnimSequence = -1;
	}
	g_staggerTrackEnt = ent;
	g_staggerTrackUid = uid;
	g_staggerTrackZc = (g_offZombieClass >= 0 && g_offZombieClass <= 0x4000)
		? *(int*)((uint8_t*)e + g_offZombieClass) : 0;
	// The timer may arrive one or two snapshots after the event. Probe only this entity briefly.
	g_staggerProbeUntil = GetTickCount() + 900;
}


static void StaggerHudOnPlayerShoved(void* ev) {
	StaggerHudTrackVictim(ev);
}

static void StaggerHudOnPlayerDeath(void* ev) {
	if (!ev || g_staggerTrackEnt <= 0) return;
	const int uid = EvInt(ev, "userid");
	const int ent = EngPlayerForUserID(uid);
	if ((uid > 0 && uid == g_staggerTrackUid) || (ent > 0 && ent == g_staggerTrackEnt))
		StaggerHudClear();
}

static void LocalPlayNotifySiHp(void* ent, int objectId, int newHp, int userid) {
	if (!g_optClientInfectedHp) return;
	if (!ent || objectId < 1 || objectId > 64) return;
	LocalPlayResolveClientProps();
	if (newHp < 0) newHp = 0;
	if (newHp > kSiHpLimit || userid <= 0) return;
	const int oldUid = g_hpLifeUid[objectId].load(std::memory_order_relaxed);
	if (oldUid != userid) {
		g_hpLifeDead[objectId].store(false, std::memory_order_relaxed);
		g_hpLifeUid[objectId].store(userid, std::memory_order_release);
	}
	const unsigned spawn = g_hpLifeSpawn[objectId].load(std::memory_order_acquire);
	if (oldUid != userid || g_hpEntity[objectId] != ent || g_hpSeenSpawn[objectId] != spawn) {
		g_hpEntity[objectId] = ent;
		g_hpSeenSpawn[objectId] = spawn;
		g_hpMax[objectId] = 0;
		g_hpZc[objectId] = 0;
		if (g_hpTrackEnt == objectId) LocalPlayClearHpTrack();
	}
	// A corpse health reset is not a new life. Only spawn/user identity clears death.
	if (g_hpLifeDead[objectId].load(std::memory_order_acquire)) return;
	if (newHp <= 0 || LocalPlayHpEntIsDead(ent)) {
		LocalPlayMarkSiDead(userid, objectId);
		return;
	}
	// Several queued drops may be older than this Paint's snapshot. Never let an
	// older, larger sample refill the gauge or falsely latch a living SI as dead.
	if (g_offHealth >= 0 && g_offHealth <= 0x4000) {
		const int currentHp = *(int*)((uint8_t*)ent + g_offHealth);
		if (currentHp > 0 && currentHp <= kSiHpLimit && currentHp < newHp) newHp = currentHp;
	}
	// Apply the refill guard before BuildGauge can overwrite the previous value.
	// A positive increase alone may be a server heal; it is not proof of death.
	if (g_hpTrackEnt == objectId && g_hpTrackNow > 0 && newHp > g_hpTrackNow) {
		LocalPlayClearHpTrack();
		return;
	}
	const int zc = (g_offZombieClass >= 0) ? *(int*)((uint8_t*)ent + g_offZombieClass) : 0;
	if (g_hpZc[objectId] != zc) {
		g_hpZc[objectId] = zc;
		g_hpMax[objectId] = 0;
	}
	int entMax = (g_offMaxHealth >= 0) ? *(int*)((uint8_t*)ent + g_offMaxHealth) : 0;
	if (entMax < 1 || entMax > kSiHpLimit) entMax = 0;
	if (entMax >= 1)
		g_hpMax[objectId] = entMax;
	else if (newHp > g_hpMax[objectId])
		g_hpMax[objectId] = newHp;
	if (g_hpMax[objectId] < 1)
		g_hpMax[objectId] = newHp > 0 ? newHp : 1;
	if (newHp > g_hpMax[objectId])
		g_hpMax[objectId] = newHp;
	static constexpr UiTextList<9> kZcName = {{
		{UiId::Text_b1024cf3, L"特感"},
		{UiId::Count, L"Smoker"},
		{UiId::Count, L"Boomer"},
		{UiId::Count, L"Hunter"},
		{UiId::Count, L"Spitter"},
		{UiId::Count, L"Jockey"},
		{UiId::Count, L"Charger"},
		{UiId::Count, L"Witch"},
		{UiId::Count, L"Tank"}
	}};
	const wchar_t* name = (zc >= 0 && zc <= 8) ? kZcName[zc] : UiText(UiId::Text_b1024cf3, L"特感");
	g_hpTrackEnt = objectId;
	g_hpTrackUid = userid;
	g_hpTrackEntity = ent;
	g_hpTrackSpawn = spawn;
	g_hpTrackZc = zc;
	LocalPlayBuildGauge(newHp, g_hpMax[objectId], name);
}

static bool WitchFxCacheOrigin(int slot, int id) {
	if (slot < 0 || slot >= 8 || id <= 0 || g_offOriginCommon < 0 || g_offOriginCommon > 0x4000)
		return false;
	void* e = EntGet(id);
	if (!EntReadable(e)) return false;
	float* o = (float*)((uint8_t*)e + g_offOriginCommon);
	if (!PtrCommitted(o) || !(o[0] == o[0]) || !(o[1] == o[1]) || !(o[2] == o[2])) return false;
	g_witchFxPos[slot][0] = o[0];
	g_witchFxPos[slot][1] = o[1];
	g_witchFxPos[slot][2] = o[2] + 40.f;
	g_witchFxPosValid[slot] = true;
	return true;
}

static int LocalPlayEnsureWitchSlot(int id) {
	if (id <= 0) return -1;
	for (int i = 0; i < 8; ++i) {
		if (g_witchId[i] == id)
			return i;
	}
	int slot = -1;
	for (int i = 0; i < 8; ++i) {
		if (g_witchId[i] <= 0) {
			slot = i;
			break;
		}
	}
	if (slot < 0) {
		slot = g_witchCur;
		g_witchCur = (g_witchCur + 1) % 8;
	}
	g_witchId[slot] = id;
	g_witchFxPosValid[slot] = false;
	WitchFxCacheOrigin(slot, id);
	return slot;
}

static void LocalPlayOnWitchSpawn(void* ev) {
	if (!g_optKillFx || !ev) return;
	int id = EvInt(ev, "witchid");
	if (id <= 0) id = EvInt(ev, "entityid");
	if (id <= 0) return;
	LocalPlayEnsureWitchSlot(id);
}


static void LocalPlayOnWitchKilled(void* ev) {
	if (!ev) return;
	const int id = EvInt(ev, "witchid");
	for (int i = 0; i < 8; ++i) {
		if (g_witchId[i] == id) {
			g_witchId[i] = 0;
			g_witchFxPosValid[i] = false;
		}
	}
}

static void LocalPlayPaint() {
	if (!g_optClientInfectedHp && !(g_hpTipUntil && g_hpTipLine[0])) return;
	if (g_menuVisible && !g_menuParked) return;
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (!g_engine || !EngInGame()) return;
	if (!MenuEnsureSurf()) return;
	SurfEnsureHudFont();
	if (!g_hudFont) return;

	int sw = 0, sh = 0;
	using SzFn = void(__thiscall*)(void*, int*, int*);
	static SzFn s_getSz = nullptr;
	if (!s_getSz) {
		s_getSz = (SzFn)VGet(g_surf, 35);
		if (!s_getSz || !IsExec((void*)s_getSz)) {
			s_getSz = nullptr;
			return;
		}
	}
	s_getSz(g_surf, &sw, &sh);
	if (sw < 80 || sh < 80) return;

	if (g_hpTipUntil && GetTickCount() <= g_hpTipUntil && g_hpTipLine[0]) {
		const int tw = SurfTextWFont(g_hudFont, g_hpTipLine);
		if (tw > 0 && tw < sw)
			SurfTextAt(g_hudFont, (sw - tw) / 2, 56, RGB(180, 255, 180), g_hpTipLine);
	}

	if (!g_optClientInfectedHp) return;
	if (!g_hpTrackUntil || GetTickCount() > g_hpTrackUntil) {
		if (g_hpTrackUntil && GetTickCount() > g_hpTrackUntil)
			LocalPlayClearHpTrack();
		return;
	}

	float world[3]{};
	bool have = false;
	if (g_hpTrackEnt >= 1 && g_hpTrackEnt <= 64 && g_offOrigin >= 0 && g_offOrigin <= 0x4000) {
		void* e = EntGet(g_hpTrackEnt);
		if (!EntReadable(e) || e != g_hpTrackEntity
			|| g_hpLifeUid[g_hpTrackEnt].load(std::memory_order_relaxed) != g_hpTrackUid
			|| g_hpLifeSpawn[g_hpTrackEnt].load(std::memory_order_acquire) != g_hpTrackSpawn) {
			LocalPlayClearHpTrack();
			return;
		}
		if (g_hpLifeDead[g_hpTrackEnt].load(std::memory_order_acquire)) {
			LocalPlayClearHpTrack();
			return;
		}
		PlayerInfo pi{};
		if (!EngPlayerInfo(g_hpTrackEnt, &pi) || pi.userid != g_hpTrackUid) {
			LocalPlayClearHpTrack();
			return;
		}
		if (g_offTeam >= 0 && *(int*)((uint8_t*)e + g_offTeam) != 3) {
			LocalPlayClearHpTrack();
			return;
		}
		if (LocalPlayHpEntIsDead(e)) {
			LocalPlayMarkSiDead(g_hpTrackUid, g_hpTrackEnt);
			return;
		}
		if (g_offHealth >= 0) {
			int hp = *(int*)((uint8_t*)e + g_offHealth);
			if (hp >= 0 && hp <= kSiHpLimit) {
				// Never refill this sample; only explicit death state latches the life.
				if (g_hpTrackNow > 0 && hp > g_hpTrackNow) {
					LocalPlayClearHpTrack();
					return;
				}
				g_hpTrackNow = hp;
			}
			if (hp <= 0) { LocalPlayMarkSiDead(g_hpTrackUid, g_hpTrackEnt); return; }
		}
		float* o = (float*)((uint8_t*)e + g_offOrigin);
		world[0] = o[0]; world[1] = o[1]; world[2] = o[2];
		float lift = LocalPlayHeadLift(g_hpTrackZc);
		if (g_offViewOffset >= 0 && g_offViewOffset <= 0x4000) {
			float* vo = (float*)((uint8_t*)e + g_offViewOffset);
			if (vo[2] > 20.f && vo[2] < 120.f)
				lift = vo[2] + 2.f;
		}
		// Tank is much taller than the regular SI view offset suggests. Apply the
		// extra clearance only to this HP bar, without moving stagger/world notices.
		if (g_hpTrackZc == 8) lift += 18.f;
		else if (g_hpTrackZc == 6) lift += 8.f;
		world[2] += lift;
		have = true;
	}
	if (!have) return;

	float sx = 0.f, sy = 0.f;
	if (!LocalPlayWorldToScreen(world, &sx, &sy, sw, sh)) return;

	const int barW = 78;
	const int barH = 7;
	const int x0 = (int)(sx - barW * 0.5f);
	const int y0 = (int)(sy - 14.f);
	if (x0 < -40 || y0 < -40 || x0 > sw || y0 > sh) return;

	int maxHp = g_hpTrackMax > 0 ? g_hpTrackMax : 1;
	int nowHp = g_hpTrackNow;
	if (nowHp < 0) nowHp = 0;
	if (nowHp > maxHp) nowHp = maxHp;
	const float t = (float)nowHp / (float)maxHp;
	int fill = (int)(barW * t + 0.5f);
	if (fill < 0) fill = 0;
	if (fill > barW) fill = barW;

	int fr = 70, fg = 210, fb = 90;
	if (t <= 0.25f) { fr = 230; fg = 55; fb = 55; }
	else if (t <= 0.5f) { fr = 240; fg = 190; fb = 50; }

	SurfColor(0, 0, 0, 160);
	SurfFill(x0 - 2, y0 - 2, x0 + barW + 2, y0 + barH + 2);
	SurfColor(35, 35, 35, 220);
	SurfFill(x0, y0, x0 + barW, y0 + barH);
	if (fill > 0) {
		SurfColor(fr, fg, fb, 235);
		SurfFill(x0, y0, x0 + fill, y0 + barH);
	}
	SurfColor(255, 255, 255, 40);
	SurfFill(x0, y0, x0 + barW, y0 + 1);

	if (!g_optClientInfectedHpCompact) {
		wchar_t label[64]{};
		swprintf_s(label, 64, L"%s  %d/%d", g_hpTrackName, nowHp, maxHp);
		const int tw = SurfTextWFont(g_hudFont, label);
		const int tx = (int)(sx - tw * 0.5f);
		const int ty = y0 - (g_hudFontTall > 0 ? g_hudFontTall + 2 : 14);
		SurfTextAt(g_hudFont, tx, ty, RGB(255, 245, 220), label);
	}
}

using StaggerActivityFn = int(__thiscall*)(void*, int);
static StaggerActivityFn g_staggerActivityFn = nullptr;
static bool g_staggerActivityTried = false;

static void StaggerHudResolveActivityFn() {
	if (g_staggerActivityTried) return;
	g_staggerActivityTried = true;
	uintptr_t hits[2]{};
	const int n = CountPat("client.dll",
		"55 8B EC 56 57 8B 7D 08 8B F1 83 FF FF 75 09 5F 83 C8 FF 5E 5D C2 04 00",
		hits, 2);
	if (n == 1 && IsExec((void*)hits[0]))
		g_staggerActivityFn = (StaggerActivityFn)hits[0];
	Log("staggerhud sequence-activity resolver hits=%d fn=%p", n, (void*)g_staggerActivityFn);
}

static bool StaggerHudAnimSample(uint8_t* base, int* seqOut, float* remainFracOut) {
	if (!base || !seqOut || !remainFracOut || !g_staggerActivityFn) return false;
	if (g_offAnimSequence < 0 || g_offAnimSequence > 0x3FF0
		|| g_offAnimCycle < 0 || g_offAnimCycle > 0x3FF0) return false;
	const int* seqP = (const int*)(base + g_offAnimSequence);
	const float* cycleP = (const float*)(base + g_offAnimCycle);
	if (!PtrCommitted(seqP) || !PtrCommitted(cycleP)) return false;
	const int seq = *seqP;
	float cycle = *cycleP;
	if (seq < 0 || seq > 4096 || !(cycle == cycle) || cycle < -0.05f || cycle > 1.25f)
		return false;
	int activity = -1;
	__try {
		activity = g_staggerActivityFn(base, seq);
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_staggerActivityFn = nullptr;
		Log("staggerhud sequence-activity call fault; disabled");
		return false;
	}
	// L4D2 shared activities 621..643: all four shove directions, melee/bat/chainsaw,
	// wall impacts and seated shove variants. Engine IDs are global, not model sequence IDs.
	if (activity < 621 || activity > 643) return false;
	if (cycle < 0.f) cycle = 0.f;
	if (cycle > 1.f) cycle = 1.f;
	*seqOut = seq;
	*remainFracOut = 1.f - cycle;
	return true;
}

static float StaggerHudRemainingSeconds(uint8_t* base, float remainFrac) {
	// m_staggerTimer stores its end timestamp in the second float. Use it when
	// the recvprop is available, otherwise retain a bounded visual fallback.
	if (base && g_offStaggerTimer >= 0 && g_offStaggerTimer <= 0x3FF8) {
		const float* endTime = (const float*)(base + g_offStaggerTimer + sizeof(float));
		if (PtrCommitted(endTime)) {
			const float now = EngClientCurTime();
			const float remain = *endTime - now;
			if (now > 0.f && remain == remain && remain > 0.f && remain <= 5.f)
				return remain;
		}
	}
	return remainFrac * 2.f;
}

static void StaggerHudDrawHourglass(int cx, int top, int w, int h, float remainFrac, int seconds, int alpha) {
	// Inverted triangle (point down). Sand drains from the wide top toward the
	// tip; the last integer second turns the whole mark red, then it vanishes
	// with the stagger window. Texture-free scanlines only.
	if (w < 8 || h < 10) return;
	if (remainFrac < 0.f) remainFrac = 0.f;
	if (remainFrac > 1.f) remainFrac = 1.f;
	const bool danger = seconds <= 1;
	const int lr = danger ? 255 : 255;
	const int lg = danger ? 72 : 214;
	const int lb = danger ? 58 : 88;
	const int fr = danger ? 255 : 255;
	const int fg = danger ? 70 : 228;
	const int fb = danger ? 70 : 176;
	const int denom = h > 1 ? (h - 1) : 1;
	for (int y = 0; y < h; ++y) {
		int half = (w * (h - 1 - y) + denom) / (2 * denom);
		if (half < 0) half = 0;
		if (half <= 0 && y < h - 1) continue;
		SurfColor(10, 12, 14, alpha * 165 / 255);
		SurfFill(cx - half - 1, top + y, cx + half + 2, top + y + 1);
	}
	const int fillH = (int)((h - 2) * remainFrac + 0.5f);
	const int fillTop = h - 1 - fillH;
	for (int y = fillTop; y < h; ++y) {
		if (y < 1) continue;
		int half = (w * (h - 1 - y) + denom) / (2 * denom) - 1;
		if (half < 1) {
			if (y >= h - 2) {
				SurfColor(fr, fg, fb, alpha);
				SurfFill(cx, top + y, cx + 1, top + y + 1);
			}
			continue;
		}
		SurfColor(fr, fg, fb, alpha);
		SurfFill(cx - half, top + y, cx + half + 1, top + y + 1);
		if (y == fillTop && fillH > 2) {
			SurfColor(danger ? 255 : 255, danger ? 196 : 248, danger ? 196 : 214, alpha);
			SurfFill(cx - half, top + y, cx + half + 1, top + y + 1);
		}
	}
	SurfColor(lr, lg, lb, alpha);
	SurfFill(cx - w / 2, top, cx + w / 2 + 1, top + 2);
	for (int y = 0; y < h; ++y) {
		int half = (w * (h - 1 - y) + denom) / (2 * denom);
		if (half < 0) half = 0;
		SurfFill(cx - half, top + y, cx - half + 1, top + y + 1);
		SurfFill(cx + half, top + y, cx + half + 1, top + y + 1);
	}
	SurfFill(cx, top + h - 1, cx + 1, top + h);
	if (!g_staggerHudFont) return;
	wchar_t countdown[8]{};
	swprintf_s(countdown, 8, L"%d", seconds);
	const int tw = SurfTextWFont(g_staggerHudFont, countdown);
	const int tx = cx - tw / 2;
	const int ty = top + h / 5;
	const COLORREF tc = danger ? RGB(255, 214, 210) : RGB(48, 34, 16);
	SurfTextAt(g_staggerHudFont, tx, ty, tc, countdown);
}

static void StaggerHudPaint() {
	if (!g_optStaggerHud || g_staggerTrackEnt < 1 || g_staggerTrackEnt > 64) return;
	if (g_menuVisible && !g_menuParked) return;
	if (!g_run.load(std::memory_order_relaxed) || !g_engine || !EngInGame()) return;
	if (!g_staggerActivityFn || g_offAnimSequence < 0 || g_offAnimCycle < 0) return;

	void* e = EntGet(g_staggerTrackEnt);
	if (!EntReadable(e) || g_offTeam < 0 || *(int*)((uint8_t*)e + g_offTeam) != 3
		|| LocalPlayEntIsDead(e)) {
		StaggerHudClear();
		return;
	}
	int animSeq = -1;
	float frac = 0.f;
	if (!StaggerHudAnimSample((uint8_t*)e, &animSeq, &frac)) {
		// Once the shove activity changes, the SI has entered its next actionable animation.
		if (g_staggerAnimSeen || GetTickCount() > g_staggerProbeUntil)
			StaggerHudClear();
		return;
	}
	g_staggerAnimSeen = true;
	g_staggerAnimSequence = animSeq;

	if (!MenuEnsureSurf()) return;
	int sw = 0, sh = 0;
	using SzFn = void(__thiscall*)(void*, int*, int*);
	static SzFn s_getSz = nullptr;
	if (!s_getSz) {
		s_getSz = (SzFn)VGet(g_surf, 35);
		if (!s_getSz || !IsExec((void*)s_getSz)) { s_getSz = nullptr; return; }
	}
	s_getSz(g_surf, &sw, &sh);
	if (sw < 80 || sh < 80 || g_offOrigin < 0 || g_offOrigin > 0x4000) return;

	const float* o = (const float*)((const uint8_t*)e + g_offOrigin);
	if (!PtrCommitted(o)) return;
	float world[3] = { o[0], o[1], o[2] };
	float lift = LocalPlayHeadLift(g_staggerTrackZc);
	if (g_offViewOffset >= 0 && g_offViewOffset <= 0x4000) {
		const float* vo = (const float*)((const uint8_t*)e + g_offViewOffset);
		if (PtrCommitted(vo) && vo[2] > 20.f && vo[2] < 120.f)
			lift = vo[2] + 2.f;
	}
	world[2] += lift;
	float sx = 0.f, sy = 0.f;
	if (!LocalPlayWorldToScreen(world, &sx, &sy, sw, sh)) return;

	const int widgetW = g_staggerHudStyle == 0 ? 10 : 36;
	const int widgetH = g_staggerHudStyle == 0 ? 58 : 46;
	int x0 = 0, y0 = 0;
	if (g_staggerHudStyle == 0) {
		const int sideGap = 34;
		const bool placeRight = (int)sx + sideGap + widgetW <= sw - 4;
		x0 = placeRight ? (int)sx + sideGap : (int)sx - sideGap - widgetW;
		y0 = (int)sy - widgetH / 2 - 10;
	} else {
		// Head-centered, above the SI HP world HUD: bar at sy-14, optional
		// name/value text above the bar. Extra gap keeps the two from touching.
		// Tank/Charger HP uses extra world lift; keep the same classes higher here.
		const int hpBarAbove = 16;
		const int hpName = (g_hudFontTall > 0 ? g_hudFontTall : 16) + 4;
		const int extra = 12;
		const int classExtra = g_staggerTrackZc == 8 ? 22 : (g_staggerTrackZc == 6 ? 10 : 0);
		x0 = (int)(sx + 0.5f) - widgetW / 2;
		y0 = (int)(sy + 0.5f) - hpBarAbove - hpName - extra - classExtra - widgetH;
	}
	if (x0 < -widgetW || y0 < -widgetH || x0 > sw || y0 > sh) return;

	if (g_staggerHudStyle == 0) {
		const int trackX = x0 + 1;
		const int trackY = y0;
		const int trackW = 7;
		const int trackH = widgetH;
		int fillH = (int)(trackH * frac + 0.5f);
		if (fillH < 0) fillH = 0;
		if (fillH > trackH) fillH = trackH;
		SurfColor(0, 0, 0, 165);
		SurfFill(trackX - 2, trackY - 2, trackX + trackW + 2, trackY + trackH + 2);
		SurfColor(36, 39, 30, 220);
		SurfFill(trackX, trackY, trackX + trackW, trackY + trackH);
		if (fillH > 0) {
			const int fillTop = trackY + trackH - fillH;
			SurfColor(255, 205, 48, 248);
			SurfFill(trackX, fillTop, trackX + trackW, trackY + trackH);
			SurfColor(255, 249, 184, 220);
			SurfFill(trackX, fillTop, trackX + trackW, fillTop + 2);
		}
		SurfColor(255, 224, 88, 115);
		SurfFill(trackX - 2, trackY, trackX, trackY + trackH);
		return;
	}

	if (!g_staggerHudFont)
		g_staggerHudFont = SurfAcquireVguiFont(18, 800,
			0x010 | 0x080 | 0x200); // antialias + drop shadow + outline
	if (!g_staggerHudFont) return;
	int seconds = (int)ceilf(StaggerHudRemainingSeconds((uint8_t*)e, frac));
	if (seconds < 1) seconds = 1;
	if (seconds > 5) seconds = 5;
	StaggerHudDrawHourglass(x0 + widgetW / 2, y0, widgetW, widgetH, frac, seconds, 235);
}

// =============================================================================
// World HUD: Tank attack prediction (punch timer / facing / look-at).
// Surface + W2S only. No AnimOverlay ABI. Punch gestures use proven m_NetGesture* Recv.
// No Present/D3D, no rock-notice coupling.
// =============================================================================
static constexpr int kWorldTankPredictMax = 4;
static constexpr int kWorldTankPredictPunchActCap = 8;
static constexpr int kWorldTankPredictThrowActCap = 8;
static constexpr int kWorldTankPredictGestSlots = 7;

static int g_offTankEyeAngles = -1;   // cold FindOffset m_angEyeAngles[0]
static int g_offTankAngRotation = -1; // cold FindOffset m_angRotation (low confidence)

struct WorldTankPredictSlot {
	int ent = 0;
	int lookAtEnt = 0;
	float origin[3]{};
	float anchor[3]{};
	float yawDeg = 0.f;
	bool haveFacing = false;
	bool facingLowConf = false;
	bool punchActive = false;
	int punchSeq = -1;
	float punchLastCycle = 0.f;
	float punchEnd = 0.f;
	float punchDur = 2.f;
	float distSq = 0.f;
	bool valid = false;
	bool gestPrimed = false;
	int gestSeq[kWorldTankPredictGestSlots]{};
	float gestStart[kWorldTankPredictGestSlots]{};
};

static WorldTankPredictSlot g_wtpSlots[kWorldTankPredictMax]{};
static int g_wtpSlotCount = 0;
static int g_wtpPunchActs[kWorldTankPredictPunchActCap]{};
static int g_wtpPunchActN = 0;
static int g_wtpThrowActs[kWorldTankPredictThrowActCap]{};
static int g_wtpThrowActN = 0;
static int g_wtpClassLogLeft = 16;

static float g_wtpWindup = 0.5f;
static float g_wtpSwingInterval = 1.5f;
static float g_wtpSwingRange = 0.f;
static float g_wtpSwingArc = 0.f;
static bool g_wtpHaveRange = false;
static bool g_wtpHaveArc = false;
static DWORD g_wtpCvarNextAt = 0;
static bool g_wtpDiagCvarsLogged = false;
static int g_wtpDiagSampleLeft = 8;

static bool WorldTankPredictWanted() {
	return g_optWorldTankPredict
		&& (g_optWorldTankPredictTimer || g_optWorldTankPredictFacing
			|| g_optWorldTankPredictRange || g_optWorldTankPredictTarget)
		&& !g_optHideAllWorldHud && !g_optPauseSampling
		&& g_run.load(std::memory_order_relaxed) && SkeetoFeaturesOn();
}

static void WorldTankPredictClear() {
	memset(g_wtpSlots, 0, sizeof(g_wtpSlots));
	g_wtpSlotCount = 0;
	memset(g_wtpPunchActs, 0, sizeof(g_wtpPunchActs));
	g_wtpPunchActN = 0;
	memset(g_wtpThrowActs, 0, sizeof(g_wtpThrowActs));
	g_wtpThrowActN = 0;
}

static void WorldTankPredictClearPunch(WorldTankPredictSlot& s) {
	s.punchActive = false;
	s.punchSeq = -1;
	s.punchLastCycle = 0.f;
	s.punchEnd = 0.f;
	s.punchDur = 2.f;
}

// Same proven path as ShoveIntervalCvar / NetGraph: CvarFind + CvarReadPair (layout pick).
static float WorldTankPredictReadCvarFloat(const char* name, float lo, float hi, bool* found) {
	if (found) *found = false;
	void* var = CvarFind(name);
	if (!var) return 0.f;
	int n = 0;
	float f = 0.f;
	if (!CvarReadPair(var, &n, &f)) return 0.f;
	if (!(f == f) || f < lo || f > hi) return 0.f;
	if (found) *found = true;
	return f;
}

static void WorldTankPredictRefreshCvars(DWORD now) {
	if (g_wtpCvarNextAt && (LONG)(now - g_wtpCvarNextAt) < 0) return;
	g_wtpCvarNextAt = now + 500u;
	bool okW = false, okI = false, okR = false, okA = false;
	// Valve default tank_windup_time is 0 — lo must allow 0.
	const float windup = WorldTankPredictReadCvarFloat("tank_windup_time", 0.f, 5.f, &okW);
	const float interval = WorldTankPredictReadCvarFloat("tank_swing_interval", 0.2f, 10.f, &okI);
	const float range = WorldTankPredictReadCvarFloat("tank_swing_range", 1.f, 512.f, &okR);
	const float arc = WorldTankPredictReadCvarFloat("tank_swing_arc", 1.f, 360.f, &okA);
	g_wtpWindup = okW ? windup : 0.5f;
	g_wtpSwingInterval = okI ? interval : 1.5f;
	g_wtpHaveRange = okR;
	g_wtpHaveArc = okA;
	g_wtpSwingRange = okR ? range : 0.f;
	g_wtpSwingArc = okA ? arc : 0.f;
	if (!g_wtpDiagCvarsLogged) {
		g_wtpDiagCvarsLogged = true;
		Log("world-tank-predict: cvars W=%d/%.2f I=%d/%.2f R=%d/%.1f A=%d/%.1f gestSeqOff=%d",
			okW ? 1 : 0, g_wtpWindup, okI ? 1 : 0, g_wtpSwingInterval,
			okR ? 1 : 0, g_wtpSwingRange, okA ? 1 : 0, g_wtpSwingArc,
			g_offNetGestureSequence);
	}
}

static float WorldTankPredictPunchDuration() {
	float d = g_wtpWindup + g_wtpSwingInterval;
	if (!(d > 0.2f) || d > 12.f) d = 2.f;
	return d;
}

static void WorldTankPredictLearnAct(int* cache, int* count, int cap, int act) {
	if (act <= 0 || !cache || !count || *count < 0) return;
	for (int i = 0; i < *count; ++i) {
		if (cache[i] == act) return;
	}
	if (*count >= cap) return;
	cache[(*count)++] = act;
}

static bool WorldTankPredictActKnown(const int* cache, int count, int act) {
	if (act <= 0) return false;
	for (int i = 0; i < count; ++i) {
		if (cache[i] == act) return true;
	}
	return false;
}

static int WorldTankPredictActivityOf(void* animating, int seq) {
	if (!g_staggerActivityFn || !animating || seq < 0 || seq > 4096) return 0;
	int activity = 0;
	__try {
		activity = g_staggerActivityFn(animating, seq);
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_staggerActivityFn = nullptr;
		return 0;
	}
	return activity > 0 ? activity : 0;
}

static bool WorldTankPredictIsPunchSeq(int seq) {
	return seq >= 33 && seq <= 47;
}

static bool WorldTankPredictIsThrowSeq(int seq) {
	return seq >= 48 && seq <= 51;
}

// 0=other, 1=punch, 2=throw.
// Stock Visual punch catalog is 33..47. Allow bootstrap by that seq range even when
// GetSequenceActivity returns 0 (resolver missing/hostile on some Tank models).
// Sequences outside 33..47 still require a learned positive activity.
static int WorldTankPredictClassify(void* ent, int seq, int* actOut) {
	if (actOut) *actOut = 0;
	if (!ent || seq < 0 || seq > 4096) return 0;
	StaggerHudResolveActivityFn();
	const int act = WorldTankPredictActivityOf(ent, seq);
	if (actOut) *actOut = act;

	if (WorldTankPredictIsThrowSeq(seq)) {
		if (act > 0) WorldTankPredictLearnAct(g_wtpThrowActs, &g_wtpThrowActN, kWorldTankPredictThrowActCap, act);
		return 2;
	}
	if (act > 0 && WorldTankPredictActKnown(g_wtpThrowActs, g_wtpThrowActN, act))
		return 2;

	if (WorldTankPredictIsPunchSeq(seq)) {
		if (act > 0) WorldTankPredictLearnAct(g_wtpPunchActs, &g_wtpPunchActN, kWorldTankPredictPunchActCap, act);
		return 1;
	}
	if (act > 0 && WorldTankPredictActKnown(g_wtpPunchActs, g_wtpPunchActN, act))
		return 1;
	return 0;
}

static bool WorldTankPredictReadYaw(void* ent, float* yawOut, bool* lowConfOut) {
	if (!yawOut || !lowConfOut || !ent) return false;
	*lowConfOut = false;
	float ang[3]{};
	if (g_offTankEyeAngles >= 0 && g_offTankEyeAngles <= 0x3FF0
		&& EntReadBlock(ent, g_offTankEyeAngles, ang, sizeof(ang))) {
		if (ang[1] == ang[1] && ang[1] > -720.f && ang[1] < 720.f) {
			*yawOut = ang[1];
			return true;
		}
	}
	if (g_offTankAngRotation >= 0 && g_offTankAngRotation <= 0x3FF0
		&& EntReadBlock(ent, g_offTankAngRotation, ang, sizeof(ang))) {
		if (ang[1] == ang[1] && ang[1] > -720.f && ang[1] < 720.f) {
			*yawOut = ang[1];
			*lowConfOut = true;
			return true;
		}
	}
	return false;
}

static bool WorldTankPredictReadAliveTeam(void* ent, int wantTeam) {
	int team = 0;
	uint8_t life = 1;
	if (!EntRead(ent, g_offTeam, &team) || team != wantTeam) return false;
	if (g_offLifeState >= 0 && g_offLifeState <= 0x4000) {
		if (!EntRead(ent, g_offLifeState, &life) || life != 0) return false;
	} else if (LocalPlayEntIsDead(ent)) {
		return false;
	}
	return true;
}

static void WorldTankPredictStartPunch(WorldTankPredictSlot& s, int ent, int seq, int act,
	float punchDur, float curTime, const char* src) {
	s.punchActive = true;
	s.punchSeq = seq;
	s.punchDur = punchDur;
	s.punchEnd = (curTime > 0.f ? curTime : 0.f) + punchDur;
	s.punchLastCycle = 0.f;
	if (g_wtpClassLogLeft > 0) {
		--g_wtpClassLogLeft;
		Log("world-tank-predict: ent=%d punch onset seq=%d act=%d dur=%.2f src=%s",
			ent, seq, act, punchDur, src ? src : "-");
	}
}

// Proven Recv array (same family TongueCut uses). Detects moving punches that stay on
// mainline Idle/Run while the claw gesture lives in m_NetGestureSequence[7].
static int WorldTankPredictScanGestures(void* e, WorldTankPredictSlot& s, int ent,
	float punchDur, float curTime) {
	if (!e || g_offNetGestureSequence < 0 || g_offNetGestureSequence > 0x4000) return 0;
	if (g_offNetGestureStartTime < 0 || g_offNetGestureStartTime > 0x4000) return 0;
	const uint8_t* b = (const uint8_t*)e;
	const int* seqs = (const int*)(b + g_offNetGestureSequence);
	const float* starts = (const float*)(b + g_offNetGestureStartTime);
	if (!PtrCommitted(seqs) || !PtrCommitted(seqs + 6)
		|| !PtrCommitted(starts) || !PtrCommitted(starts + 6))
		return 0;

	int kind = 0; // 0 none, 1 punch onset, 2 throw seen
	for (int i = 0; i < kWorldTankPredictGestSlots; ++i) {
		const int gseq = seqs[i];
		const float gst = starts[i];
		if (!s.gestPrimed) {
			s.gestSeq[i] = gseq;
			s.gestStart[i] = gst;
			continue;
		}
		const int oldSeq = s.gestSeq[i];
		const float oldSt = s.gestStart[i];
		const bool changed = (gseq != oldSeq) || (gst != oldSt);
		s.gestSeq[i] = gseq;
		s.gestStart[i] = gst;
		if (!changed) continue;
		if (WorldTankPredictIsThrowSeq(gseq)) {
			kind = 2;
			if (g_wtpClassLogLeft > 0) {
				--g_wtpClassLogLeft;
				Log("world-tank-predict: ent=%d gest throw slot=%d seq=%d", ent, i, gseq);
			}
			continue;
		}
		if (!WorldTankPredictIsPunchSeq(gseq)) continue;
		// Fresh onset: sequence entered punch catalog or start time restarted.
		const bool freshStart = gst > 0.f && curTime > 0.f
			&& (curTime - gst) >= -0.25f && (curTime - gst) < punchDur + 0.35f;
		if (!freshStart) continue;
		if (kind != 2) kind = 1;
		if (g_optWorldTankPredictTimer) {
			const bool newOnset = !s.punchActive || s.punchSeq != gseq || gst != oldSt
				|| WorldTankPredictIsThrowSeq(oldSeq) || !WorldTankPredictIsPunchSeq(oldSeq);
			if (newOnset)
				WorldTankPredictStartPunch(s, ent, gseq, 0, punchDur, curTime, "net-gesture");
		}
	}
	s.gestPrimed = true;
	return kind;
}

static void WorldTankPredictSample(DWORD now) {
	if (!WorldTankPredictWanted() || !g_engine || !EngInGame() || EngDrawingLoading()) {
		WorldTankPredictClear();
		g_wtpDiagCvarsLogged = false;
		g_wtpDiagSampleLeft = 8;
		return;
	}
	if (g_offOrigin < 0 || g_offOrigin > 0x4000 || g_offTeam < 0 || g_offZombieClass < 0) {
		WorldTankPredictClear();
		return;
	}
	StaggerHudResolveActivityFn();
	WorldTankPredictRefreshCvars(now);
	const float punchDur = WorldTankPredictPunchDuration();
	const float curTime = EngClientCurTime();

	float localOrigin[3]{};
	bool haveLocal = false;
	const int localEnt = EngLocal();
	if (localEnt > 0 && localEnt <= 64) {
		void* me = EntGet(localEnt);
		if (EntReadable(me) && EntReadBlock(me, g_offOrigin, localOrigin, sizeof(localOrigin)))
			haveLocal = true;
	}

	WorldTankPredictSlot cand[32]{};
	int candN = 0;
	for (int ent = 1; ent <= 32 && candN < 32; ++ent) {
		if (EntNetDormant(ent)) continue;
		void* e = EntGet(ent);
		if (!EntReadable(e) || !EntLive(e)) continue;
		int zc = 0;
		if (!EntRead(e, g_offZombieClass, &zc) || zc != 8) continue;
		if (!WorldTankPredictReadAliveTeam(e, 3)) continue;

		float origin[3]{};
		if (!EntReadBlock(e, g_offOrigin, origin, sizeof(origin))) continue;

		WorldTankPredictSlot& s = cand[candN];
		s = {};
		s.ent = ent;
		s.origin[0] = origin[0]; s.origin[1] = origin[1]; s.origin[2] = origin[2];
		s.anchor[0] = origin[0]; s.anchor[1] = origin[1]; s.anchor[2] = origin[2];
		float lift = 72.f;
		if (g_offViewOffset >= 0 && g_offViewOffset <= 0x4000) {
			float vo[3]{};
			if (EntReadBlock(e, g_offViewOffset, vo, sizeof(vo)) && vo[2] > 20.f && vo[2] < 140.f)
				lift = vo[2] + 2.f;
		}
		s.anchor[2] += lift;
		if (haveLocal) {
			const float dx = origin[0] - localOrigin[0];
			const float dy = origin[1] - localOrigin[1];
			const float dz = origin[2] - localOrigin[2];
			s.distSq = dx * dx + dy * dy + dz * dz;
		} else {
			s.distSq = (float)candN;
		}

		s.haveFacing = WorldTankPredictReadYaw(e, &s.yawDeg, &s.facingLowConf);

		if (g_optWorldTankPredictTarget && g_offTankLookAtPlayer >= 0 && g_offTankLookAtPlayer <= 0x4000) {
			int rawHandle = 0;
			if (EntRead(e, g_offTankLookAtPlayer, &rawHandle)) {
				const int targetEnt = EntIndexFromHandle(rawHandle);
				if (targetEnt > 0 && targetEnt <= 64) {
					void* target = EntGet(targetEnt);
					if (WorldTankPredictReadAliveTeam(target, 2))
						s.lookAtEnt = targetEnt;
				}
			}
		}

		// Carry previous punch timer + gesture prime across samples for the same ent.
		for (int i = 0; i < g_wtpSlotCount; ++i) {
			if (g_wtpSlots[i].ent == ent) {
				if (g_wtpSlots[i].punchActive) {
					s.punchActive = g_wtpSlots[i].punchActive;
					s.punchSeq = g_wtpSlots[i].punchSeq;
					s.punchLastCycle = g_wtpSlots[i].punchLastCycle;
					s.punchEnd = g_wtpSlots[i].punchEnd;
					s.punchDur = g_wtpSlots[i].punchDur;
				}
				s.gestPrimed = g_wtpSlots[i].gestPrimed;
				memcpy(s.gestSeq, g_wtpSlots[i].gestSeq, sizeof(s.gestSeq));
				memcpy(s.gestStart, g_wtpSlots[i].gestStart, sizeof(s.gestStart));
				break;
			}
		}

		int seq = -1;
		float cycle = 0.f;
		bool haveAnim = false;
		if (g_offAnimSequence >= 0 && g_offAnimSequence <= 0x3FF0
			&& g_offAnimCycle >= 0 && g_offAnimCycle <= 0x3FF0
			&& EntRead(e, g_offAnimSequence, &seq) && EntRead(e, g_offAnimCycle, &cycle)
			&& seq >= 0 && seq <= 4096 && cycle == cycle && cycle >= -0.05f && cycle <= 1.25f) {
			haveAnim = true;
			if (cycle < 0.f) cycle = 0.f;
			if (cycle > 1.f) cycle = 1.f;
		}

		const int gestKind = WorldTankPredictScanGestures(e, s, ent, punchDur, curTime);
		if (gestKind == 2)
			WorldTankPredictClearPunch(s);

		if (haveAnim) {
			int act = 0;
			const int kind = WorldTankPredictClassify(e, seq, &act);
			if (g_wtpDiagSampleLeft > 0) {
				--g_wtpDiagSampleLeft;
				Log("world-tank-predict: sample ent=%d seq=%d act=%d kind=%d punch=%d look=%d gest=%d",
					ent, seq, act, kind, s.punchActive ? 1 : 0, s.lookAtEnt, gestKind);
			}
			if (kind == 2) {
				if (s.punchActive && g_wtpClassLogLeft > 0) {
					--g_wtpClassLogLeft;
					Log("world-tank-predict: ent=%d clear-punch throw seq=%d act=%d", ent, seq, act);
				}
				WorldTankPredictClearPunch(s);
			} else if (kind == 1 && g_optWorldTankPredictTimer) {
				const bool newOnset = !s.punchActive || s.punchSeq != seq
					|| cycle + 0.20f < s.punchLastCycle;
				if (newOnset)
					WorldTankPredictStartPunch(s, ent, seq, act, punchDur, curTime, "mainline");
				s.punchLastCycle = cycle;
			} else if (s.punchActive && curTime > 0.f && curTime >= s.punchEnd) {
				WorldTankPredictClearPunch(s);
			}
		} else if (s.punchActive && curTime > 0.f && curTime >= s.punchEnd) {
			WorldTankPredictClearPunch(s);
		}

		s.valid = true;
		++candN;
	}

	// Keep at most 4 nearest Tanks.
	for (int i = 0; i < candN; ++i) {
		for (int j = i + 1; j < candN; ++j) {
			if (cand[j].distSq < cand[i].distSq) {
				WorldTankPredictSlot tmp = cand[i];
				cand[i] = cand[j];
				cand[j] = tmp;
			}
		}
	}
	g_wtpSlotCount = candN < kWorldTankPredictMax ? candN : kWorldTankPredictMax;
	for (int i = 0; i < g_wtpSlotCount; ++i)
		g_wtpSlots[i] = cand[i];
	for (int i = g_wtpSlotCount; i < kWorldTankPredictMax; ++i)
		g_wtpSlots[i] = {};
}

static void WorldTankPredictThickLine(int x0, int y0, int x1, int y1, int thickness) {
	if (thickness < 1) thickness = 1;
	const int dx = x1 - x0, dy = y1 - y0;
	const int adx = dx < 0 ? -dx : dx, ady = dy < 0 ? -dy : dy;
	if (adx >= ady) {
		for (int i = 0; i < thickness; ++i)
			SurfLine(x0, y0 + i - thickness / 2, x1, y1 + i - thickness / 2);
	} else {
		for (int i = 0; i < thickness; ++i)
			SurfLine(x0 + i - thickness / 2, y0, x1 + i - thickness / 2, y1);
	}
}

static void WorldTankPredictDrawBar(float sx, float syBot, float remainFrac) {
	// Screen-space minimum size so the bar stays readable like Visual's stopwatch,
	// instead of vanishing into a 1px world stub at mid distance.
	float h = 78.f;
	float w = 12.f;
	const int trackW = (int)(w + 0.5f);
	const int trackH = (int)(h + 0.5f);
	const int x0 = (int)(sx + 0.5f) + 38;
	const int y0 = (int)(syBot + 0.5f) - trackH + 28;
	if (remainFrac < 0.f) remainFrac = 0.f;
	if (remainFrac > 1.f) remainFrac = 1.f;
	int fillH = (int)(trackH * remainFrac + 0.5f);
	if (fillH < 0) fillH = 0;
	if (fillH > trackH) fillH = trackH;
	SurfColor(0, 0, 0, 170);
	SurfFill(x0 - 3, y0 - 3, x0 + trackW + 3, y0 + trackH + 3);
	SurfColor(12, 28, 40, 230);
	SurfFill(x0, y0, x0 + trackW, y0 + trackH);
	if (fillH > 0) {
		const int fillTop = y0 + trackH - fillH;
		SurfColor(70, 220, 255, 250);
		SurfFill(x0, fillTop, x0 + trackW, y0 + trackH);
		SurfColor(210, 250, 255, 230);
		SurfFill(x0, fillTop, x0 + trackW, fillTop + 3);
	}
	SurfColor(90, 210, 245, 160);
	SurfFill(x0 - 3, y0, x0, y0 + trackH);
}


// Thin ground sector (first-draw style): 12-seg outer arc + two side rays,
// 1px SurfLine, z+4, modest alpha. Only when live range+arc and facing exist.
static void WorldTankPredictDrawSector(int sw, int sh, const float* origin, float yawDeg,
	float range, float arcDeg) {
	if (!origin || sw < 80 || sh < 80) return;
	if (!(range >= 1.f) || range > 512.f) return;
	if (!(arcDeg >= 1.f) || arcDeg > 360.f) return;
	const float half = arcDeg * 0.5f;
	const float yaw0 = yawDeg - half;
	const float yaw1 = yawDeg + half;
	const float z = origin[2] + 4.f;
	constexpr int kSeg = 12;
	auto pointAt = [&](float yaw, float r, float out[3]) {
		const float rad = yaw * 0.01745329251994329577f;
		out[0] = origin[0] + cosf(rad) * r;
		out[1] = origin[1] + sinf(rad) * r;
		out[2] = z;
	};
	auto thinSeg = [&](const float* a, const float* b) {
		float sx0 = 0.f, sy0 = 0.f, sx1 = 0.f, sy1 = 0.f;
		if (!LocalPlayWorldToScreen(a, &sx0, &sy0, sw, sh)) return;
		if (!LocalPlayWorldToScreen(b, &sx1, &sy1, sw, sh)) return;
		SurfLine((int)(sx0 + 0.5f), (int)(sy0 + 0.5f),
			(int)(sx1 + 0.5f), (int)(sy1 + 0.5f));
	};
	float p0[3]{}, p1[3]{};
	SurfColor(50, 230, 255, 140);
	for (int i = 0; i < kSeg; ++i) {
		const float a0 = yaw0 + (yaw1 - yaw0) * ((float)i / (float)kSeg);
		const float a1 = yaw0 + (yaw1 - yaw0) * ((float)(i + 1) / (float)kSeg);
		pointAt(a0, range, p0);
		pointAt(a1, range, p1);
		thinSeg(p0, p1);
	}
	float center[3] = { origin[0], origin[1], z };
	SurfColor(70, 220, 255, 130);
	pointAt(yaw0, range, p0);
	thinSeg(center, p0);
	pointAt(yaw1, range, p0);
	thinSeg(center, p0);
}

static void WorldTankPredictDrawArrow(int sw, int sh, const float* origin, float yawDeg, bool lowConf) {
	const float rad = yawDeg * 0.01745329251994329577f;
	const float fx = cosf(rad), fy = sinf(rad);
	const float len = 48.f;
	float tip[3] = { origin[0] + fx * len, origin[1] + fy * len, origin[2] + 8.f };
	float base[3] = { origin[0], origin[1], origin[2] + 8.f };
	float sx0 = 0.f, sy0 = 0.f, sx1 = 0.f, sy1 = 0.f;
	if (!LocalPlayWorldToScreen(base, &sx0, &sy0, sw, sh)) return;
	if (!LocalPlayWorldToScreen(tip, &sx1, &sy1, sw, sh)) return;
	const int a = lowConf ? 110 : 180;
	SurfColor(70, 210, 255, a);
	SurfLine((int)(sx0 + 0.5f), (int)(sy0 + 0.5f),
		(int)(sx1 + 0.5f), (int)(sy1 + 0.5f));
	const float dx = sx1 - sx0, dy = sy1 - sy0;
	const float L = sqrtf(dx * dx + dy * dy);
	if (L < 4.f) return;
	const float ux = dx / L, uy = dy / L;
	const float px = -uy, py = ux;
	const float back = 7.f, side = 4.f;
	const float ax = sx1 - ux * back + px * side;
	const float ay = sy1 - uy * back + py * side;
	const float bx = sx1 - ux * back - px * side;
	const float by = sy1 - uy * back - py * side;
	SurfLine((int)(sx1 + 0.5f), (int)(sy1 + 0.5f), (int)(ax + 0.5f), (int)(ay + 0.5f));
	SurfLine((int)(sx1 + 0.5f), (int)(sy1 + 0.5f), (int)(bx + 0.5f), (int)(by + 0.5f));
}

static void WorldTankPredictDrawTargetLine(int sw, int sh, const float* fromAnchor, int lookAtEnt) {
	if (lookAtEnt < 1 || lookAtEnt > 64 || g_offOrigin < 0) return;
	void* target = EntGet(lookAtEnt);
	if (!WorldTankPredictReadAliveTeam(target, 2)) return;
	float to[3]{};
	if (!EntReadBlock(target, g_offOrigin, to, sizeof(to))) return;
	if (g_offViewOffset >= 0 && g_offViewOffset <= 0x4000) {
		float vo[3]{};
		if (EntReadBlock(target, g_offViewOffset, vo, sizeof(vo)) && vo[2] > 20.f && vo[2] < 120.f)
			to[2] += vo[2] * 0.55f;
		else
			to[2] += 40.f;
	} else {
		to[2] += 40.f;
	}
	float sx0 = 0.f, sy0 = 0.f, sx1 = 0.f, sy1 = 0.f;
	if (!LocalPlayWorldToScreen(fromAnchor, &sx0, &sy0, sw, sh)) return;
	if (!LocalPlayWorldToScreen(to, &sx1, &sy1, sw, sh)) return;
	SurfColor(90, 220, 255, 210);
	WorldTankPredictThickLine((int)(sx0 + 0.5f), (int)(sy0 + 0.5f),
		(int)(sx1 + 0.5f), (int)(sy1 + 0.5f), 2);
}

static void WorldTankPredictPaint() {
	if (!WorldTankPredictWanted()) {
		WorldTankPredictClear();
		return;
	}
	if (g_menuVisible && !g_menuParked) return;
	if (!g_run.load(std::memory_order_relaxed) || !g_engine || !EngInGame()) return;

	const DWORD now = GetTickCount();
	WorldTankPredictSample(now);
	if (g_wtpSlotCount <= 0) return;
	if (!MenuEnsureSurf()) return;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 80 || sh < 80) return;

	const float curTime = EngClientCurTime();
	for (int i = 0; i < g_wtpSlotCount; ++i) {
		const WorldTankPredictSlot& s = g_wtpSlots[i];
		if (!s.valid || s.ent < 1) continue;

		float sx = 0.f, sy = 0.f;
		const bool gotAnchor = LocalPlayWorldToScreen(s.anchor, &sx, &sy, sw, sh);

		if (g_optWorldTankPredictTimer && s.punchActive && gotAnchor && curTime > 0.f) {
			float remain = s.punchEnd - curTime;
			if (remain < 0.f) remain = 0.f;
			float frac = s.punchDur > 0.05f ? (remain / s.punchDur) : 0.f;
			WorldTankPredictDrawBar(sx, sy, frac);
		}

		if (g_optWorldTankPredictFacing && s.haveFacing)
			WorldTankPredictDrawArrow(sw, sh, s.origin, s.yawDeg, s.facingLowConf);

		if (g_optWorldTankPredictRange && s.haveFacing && g_wtpHaveRange && g_wtpHaveArc)
			WorldTankPredictDrawSector(sw, sh, s.origin, s.yawDeg, g_wtpSwingRange, g_wtpSwingArc);

		if (g_optWorldTankPredictTarget && s.lookAtEnt > 0 && gotAnchor)
			WorldTankPredictDrawTargetLine(sw, sh, s.anchor, s.lookAtEnt);
	}
}

static constexpr int kDmgMax = 24; // 20 SI/Tank slots plus 4 isolated teammate-FF slots
static constexpr int kDmgSiMax = 20;
static constexpr int kDmgFriendlyFireMax = 4;
static constexpr DWORD kDmgLifeMs = 860;
static constexpr DWORD kDmgMergeMs = 50;
struct DmgNumSlot {
	int ent;
	int dmg;
	float x, y, z;
	float lift;
	float ang; // screen-space angle around the silhouette
	DWORD born;
	unsigned char pal;
	bool friendlyFire;
    bool terminalSiDamage;
    unsigned siGeneration;
};
static DmgNumSlot g_dmg[kDmgMax]{};
static int g_dmgN = 0;
static int g_dmgPalLast = -1;
// Paint owns fixed per-slot death receipts. Epoch + HP generation prevent
// late death/drop ordering from correcting another map or a reused slot.
// This is necessary because a lethal network HP value can remain 1, while
// an alive SI can also have 1HP. Reuse the existing bounded damage-event queue.
struct SiDamageDeath { unsigned epoch = 0, generation = 0; bool valid = false, received = false, applied = false; };
static SiDamageDeath g_siDamageDeath[65]{};
static SiDamageDeath& ClientUxDmgDeathFor(int ent, unsigned generation) {
    SiDamageDeath& death = g_siDamageDeath[ent];
    const unsigned epoch = SiDamageEpoch();
    if (!death.valid || death.epoch != epoch || death.generation != generation)
        death = SiDamageDeath{epoch, generation, true, false, false};
    return death;
}
static void ClientUxDmgConfirmDeath(int ent) {
    const unsigned generation = SiDamageGeneration(ent);
    SiDamageDeath& death = ClientUxDmgDeathFor(ent, generation);
    death.received = true;
    if (death.applied) return;
    const DWORD now = GetTickCount();
    int latest = -1; DWORD age = kDmgLifeMs;
    for (int i=0; i<g_dmgN; ++i) {
        const auto& slot = g_dmg[i];
        const DWORD slotAge = now - slot.born;
        if (!slot.friendlyFire && slot.ent == ent && slot.siGeneration == generation
            && slot.terminalSiDamage && slotAge < age) { latest = i; age = slotAge; }
    }
    if (latest >= 0) { if (g_dmg[latest].dmg < 9999) ++g_dmg[latest].dmg; death.applied = true; }
}


// Bright HUD colors only — picked once at spawn, paint just reads RGB.
static const unsigned char kDmgPal[][3] = {
	{255, 64, 64},
	{255, 220, 48},
	{255, 150, 40},
	{90, 255, 100},
	{50, 230, 255},
	{255, 90, 200},
	{200, 110, 255},
	{255, 255, 255},
	{40, 255, 190},
	{255, 90, 130},
};
static constexpr int kDmgPalN = (int)(sizeof(kDmgPal) / sizeof(kDmgPal[0]));

static void ClientUxDmgReset() {
	g_dmgN = 0;
	memset(g_dmg, 0, sizeof(g_dmg));
}

static void ClientUxDmgClearKind(bool friendlyFire) {
	int w = 0;
	for (int i = 0; i < g_dmgN; ++i)
		if (g_dmg[i].friendlyFire != friendlyFire) g_dmg[w++] = g_dmg[i];
	for (int i = w; i < g_dmgN; ++i) g_dmg[i] = {};
	g_dmgN = w;
}

static bool ClientUxDmgIsSiOrTank(void* e) {
	if (!e) return false;
	if (g_offTeam >= 0 && g_offTeam <= 0x4000) {
		if (*(int*)((uint8_t*)e + g_offTeam) != 3)
			return false;
	}
	if (g_offZombieClass >= 0 && g_offZombieClass <= 0x4000) {
		const int zc = *(int*)((uint8_t*)e + g_offZombieClass);
		if (zc == 7) return false; // witch
		if (zc < 1 || zc > 8) return false;
	}
	return true;
}

static float ClientUxDmgPickAng(int ent, int siCount) {
	const DWORD now = GetTickCount();
	const unsigned h = now * 1664525u + (unsigned)ent * 1013904223u + (unsigned)siCount * 747796405u;
	float ang = (float)(h & 1023) * (6.2831853f / 1024.f);
	// Screen y grows downward. 3pi/2 is straight up into the HP bar — skip that cone.
	const float up = 4.712389f;
	float d = ang - up;
	while (d > 3.1415927f) d -= 6.2831853f;
	while (d < -3.1415927f) d += 6.2831853f;
	if (d > -0.72f && d < 0.72f)
		ang = up + (d >= 0.f ? 0.72f : -0.72f);
	return ang;
}

static void ClientUxDmgPush(int ent, int dmg, const float* pos, float lift, bool friendlyFire = false,
    bool terminalSiDamage = false, unsigned siGeneration = 0) {
	if ((friendlyFire ? !g_optWorldFriendlyFireDmgNum : !g_optClientDmgNum)
		|| dmg < 1 || dmg > 9999 || !pos) return;
	const DWORD now = GetTickCount();
	for (int i = 0; i < g_dmgN; ++i) {
		if (g_dmg[i].ent == ent && g_dmg[i].friendlyFire == friendlyFire
			&& (friendlyFire || g_dmg[i].siGeneration == siGeneration)
			&& now - g_dmg[i].born < kDmgMergeMs) {
			g_dmg[i].dmg += dmg;
            g_dmg[i].terminalSiDamage = g_dmg[i].terminalSiDamage || terminalSiDamage;
			if (g_dmg[i].dmg > 9999) g_dmg[i].dmg = 9999;
			g_dmg[i].x = pos[0];
			g_dmg[i].y = pos[1];
			g_dmg[i].z = pos[2];
			g_dmg[i].lift = lift;
			return;
		}
	}
	int categoryCount = 0, oldestSameCategory = -1;
	DWORD oldestAge = 0;
	int siCount = 0;
	for (int i = 0; i < g_dmgN; ++i) {
		if (!g_dmg[i].friendlyFire) ++siCount;
		if (g_dmg[i].friendlyFire != friendlyFire) continue;
		++categoryCount;
		const DWORD age = now - g_dmg[i].born;
		if (oldestSameCategory < 0 || age > oldestAge) {
			oldestSameCategory = i;
			oldestAge = age;
		}
	}
	const int categoryLimit = friendlyFire ? kDmgFriendlyFireMax : kDmgSiMax;
	if (categoryCount >= categoryLimit && oldestSameCategory >= 0) {
		memmove(g_dmg + oldestSameCategory, g_dmg + oldestSameCategory + 1,
			(size_t)(g_dmgN - oldestSameCategory - 1) * sizeof(DmgNumSlot));
		--g_dmgN;
		if (!friendlyFire) --siCount;
	}
	if (g_dmgN >= kDmgMax) {
		return; // the per-category limits should keep the shared queue below this cap
	}
	g_dmg[g_dmgN].ent = ent;
	g_dmg[g_dmgN].dmg = dmg;
	g_dmg[g_dmgN].x = pos[0];
	g_dmg[g_dmgN].y = pos[1];
	g_dmg[g_dmgN].z = pos[2];
	g_dmg[g_dmgN].lift = lift;
	g_dmg[g_dmgN].ang = friendlyFire ? 4.712389f : ClientUxDmgPickAng(ent, siCount);
	g_dmg[g_dmgN].born = now;
	g_dmg[g_dmgN].friendlyFire = friendlyFire;
    g_dmg[g_dmgN].terminalSiDamage = terminalSiDamage;
    g_dmg[g_dmgN].siGeneration = siGeneration;
	int pick = 0;
	if (!friendlyFire) {
		pick = (int)((now * 1664525u + (DWORD)ent * 17u + (DWORD)siCount * 31u) % (unsigned)kDmgPalN);
		if (pick == g_dmgPalLast)
			pick = (pick + 1 + (int)(now & 3)) % kDmgPalN;
		g_dmgPalLast = pick;
	}
	g_dmg[g_dmgN].pal = (unsigned char)pick;
	++g_dmgN;
}

static bool ClientUxDmgReadHead(int ent, void* known, float* out, float* liftOut) {
	if (!out || ent <= 0) return false;
	void* e = known ? known : EntGet(ent);
	if (!e || g_offOrigin < 0 || g_offOrigin > 0x4000) return false;
	float* o = (float*)((uint8_t*)e + g_offOrigin);
	out[0] = o[0]; out[1] = o[1]; out[2] = o[2];
	int zc = 0;
	if (g_offZombieClass >= 0 && g_offZombieClass <= 0x4000)
		zc = *(int*)((uint8_t*)e + g_offZombieClass);
	float lift = LocalPlayHeadLift(zc);
	if (g_offViewOffset >= 0 && g_offViewOffset <= 0x4000) {
		float* vo = (float*)((uint8_t*)e + g_offViewOffset);
		if (vo[2] > 20.f && vo[2] < 120.f)
			lift = vo[2] + 2.f;
	}
	if (liftOut) *liftOut = lift;
	return true;
}

static void ClientUxDmgOnSi(void* ent, int objectId, int dmg, int remainingHp) {
	if (!g_optClientDmgNum || dmg < 1) return;
	if (ent && !ClientUxDmgIsSiOrTank(ent)) return;
	float p[3]{};
	float lift = 0.f;
	if (!ClientUxDmgReadHead(objectId, ent, p, &lift)) return;
    const unsigned generation = SiDamageGeneration(objectId);
    const bool terminal = remainingHp >= 0 && remainingHp <= 1;
    if (terminal) {
        SiDamageDeath& death = ClientUxDmgDeathFor(objectId, generation);
        if (!death.applied && (remainingHp == 0 || death.received)) {
            if (dmg < 9999) ++dmg;
            death.applied = true;
        }
    }
    ClientUxDmgPush(objectId, dmg, p, lift, false, terminal, generation);
}

static void ClientUxDmgOnFriendlyFire(int victimEnt, int dmg) {
	if (!g_optWorldFriendlyFireDmgNum || dmg < 1) return;
	float p[3]{};
	float lift = 0.f;
	if (!ClientUxDmgReadHead(victimEnt, nullptr, p, &lift)) return;
	ClientUxDmgPush(victimEnt, dmg, p, lift, true);
}

static void ClientUxPaintDmgNums() {
	if (!g_optClientDmgNum && !g_optWorldFriendlyFireDmgNum) {
		if (g_dmgN) ClientUxDmgReset();
		return;
	}
	if (g_menuVisible && !g_menuParked) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame()) return;
	if (!MenuEnsureSurf()) return;
	if (g_dmgN <= 0) return;
	SurfEnsureDmgFont();
	if (!g_dmgFont) {
		SurfEnsureHudFont();
		if (!g_hudFont) return;
	}

	int sw = 0, sh = 0;
	using SzFn = void(__thiscall*)(void*, int*, int*);
	static SzFn s_getSz = nullptr;
	if (!s_getSz) {
		s_getSz = (SzFn)VGet(g_surf, 35);
		if (!s_getSz || !IsExec((void*)s_getSz)) {
			s_getSz = nullptr;
			return;
		}
	}
	s_getSz(g_surf, &sw, &sh);
	if (sw < 80 || sh < 80) return;

	const DWORD now = GetTickCount();
	int w = 0;
	for (int i = 0; i < g_dmgN; ++i) {
		if ((g_dmg[i].friendlyFire ? !g_optWorldFriendlyFireDmgNum : !g_optClientDmgNum)
			|| now - g_dmg[i].born >= kDmgLifeMs) continue;
		if (g_dmg[i].ent > 0 && g_offOrigin >= 0 && g_offOrigin <= 0x4000) {
			void* e = EntGet(g_dmg[i].ent);
			if (e) {
				float* o = (float*)((uint8_t*)e + g_offOrigin);
				g_dmg[i].x = o[0];
				g_dmg[i].y = o[1];
				g_dmg[i].z = o[2];
			}
		}
		g_dmg[w++] = g_dmg[i];
	}
	g_dmgN = w;
	if (g_dmgN <= 0) return;
	bool hasFriendlyFire = false;
	for (int i = 0; i < g_dmgN; ++i) hasFriendlyFire = hasFriendlyFire || g_dmg[i].friendlyFire;
	if (hasFriendlyFire) {
		SurfEnsureFriendlyFireDmgFont();
	}

	const unsigned long font = g_dmgFont ? g_dmgFont : g_hudFont;
	using FontFn = void(__thiscall*)(void*, unsigned long);
	using ColFn = void(__thiscall*)(void*, int, int, int, int);
	using PosFn = void(__thiscall*)(void*, int, int);
	using PrintFn = void(__thiscall*)(void*, const wchar_t*, int, int);
	auto setFont = (FontFn)VGet(g_surf, 17);
	auto setCol = (ColFn)VGet(g_surf, 19);
	auto setPos = (PosFn)VGet(g_surf, 20);
	auto print = (PrintFn)VGet(g_surf, 22);
	if (!setFont || !setCol || !setPos || !print) return;
	setFont(g_surf, font);

	for (int i = 0; i < g_dmgN; ++i) {
		const bool friendlyFire = g_dmg[i].friendlyFire;
		if (friendlyFire && !g_dmgFriendlyFireFont) continue;
		const float t = (float)(now - g_dmg[i].born) / (float)kDmgLifeMs;
		int a = 255;
		if (t > 0.55f) {
			a = (int)(255.f * (1.f - (t - 0.55f) / 0.45f));
			if (a < 0) a = 0;
		}
		if (a < 18) continue;

		float feet[3] = { g_dmg[i].x, g_dmg[i].y, g_dmg[i].z };
		float head[3] = { g_dmg[i].x, g_dmg[i].y, g_dmg[i].z + g_dmg[i].lift };
		float fsx = 0.f, fsy = 0.f, hsx = 0.f, hsy = 0.f;
		const bool gotF = LocalPlayWorldToScreen(feet, &fsx, &fsy, sw, sh);
		const bool gotH = LocalPlayWorldToScreen(head, &hsx, &hsy, sw, sh);
		if (!gotF && !gotH) continue;
		if (!gotF) { fsx = hsx; fsy = hsy + 36.f; }
		if (!gotH) { hsx = fsx; hsy = fsy - 36.f; }

		const float cx = (fsx + hsx) * 0.5f;
		const float cy = (fsy + hsy) * 0.5f;
		float bh = fsy - hsy;
		if (bh < 28.f) bh = 28.f;
		float bw = bh * 0.42f;
		if (bw < 22.f) bw = 22.f;
		const int critTier = friendlyFire ? 0 : ClientDmgCritTier(g_dmg[i].dmg);
		const bool isCrit = critTier > 0;
		if (isCrit)
			SurfEnsureDmgCritFont();
		const skeeto_damage::FriendlyFireDamageTier ffTier = friendlyFire
			? skeeto_damage::FriendlyFireDamageTierFor(g_dmg[i].dmg)
			: skeeto_damage::kFriendlyFireDamageNone;

		const float ang = g_dmg[i].ang;
		const float rx = bw * 0.5f + 20.f;
		const float ry = bh * 0.5f + 14.f;
		const float floatY = isCrit ? (-18.f * t) : (-10.f * t);
		float sx = friendlyFire ? hsx : cx + cosf(ang) * rx;
		float sy = friendlyFire ? hsy - 30.f - 20.f * t : cy + sinf(ang) * ry + floatY;
		if (isCrit) {
			const DWORD age = now - g_dmg[i].born;
			if (age < 120u) {
				const float punch = 1.f - (float)age / 120.f;
				sy -= 6.f * punch;
			}
		}

		wchar_t txt[16]{};
		if (friendlyFire && ffTier == skeeto_damage::kFriendlyFireDamageHeavy)
			swprintf_s(txt, 16, L"-%d!!!", g_dmg[i].dmg);
		else if (friendlyFire)
			swprintf_s(txt, 16, L"-%d!", g_dmg[i].dmg);
		else if (critTier == 2)
			swprintf_s(txt, 16, L"%d!!!", g_dmg[i].dmg);
		else if (isCrit)
			swprintf_s(txt, 16, L"%d!", g_dmg[i].dmg);
		else
			swprintf_s(txt, 16, L"%d", g_dmg[i].dmg);
		const int len = (int)wcslen(txt);
		const unsigned long useFont = friendlyFire && g_dmgFriendlyFireFont
			? g_dmgFriendlyFireFont : ((isCrit && g_dmgCritFont) ? g_dmgCritFont : font);
		const int th = friendlyFire
			? (g_dmgFriendlyFireFontTall > 0 ? g_dmgFriendlyFireFontTall
				: skeeto_damage::FriendlyFireDamageFontPx(g_dmgFontTall > 0 ? g_dmgFontTall : 24))
			: (isCrit
			? (g_dmgCritFontTall > 0 ? g_dmgCritFontTall : 34)
			: (g_dmgFontTall > 0 ? g_dmgFontTall : 20));
		const int tw = len * (th * 3 / 5);
		int tx = (int)(sx + 0.5f) - tw / 2;
		int ty = (int)(sy + 0.5f);

		if (g_optClientInfectedHp && g_hpTrackEnt == g_dmg[i].ent
			&& g_hpTrackUntil && now <= g_hpTrackUntil) {
			const int barW = 78;
			const int barH = 7;
			const int barX0 = (int)(hsx - barW * 0.5f);
			const int barY0 = (int)(hsy - 14.f);
			const int labH = (g_hudFontTall > 0 ? g_hudFontTall : 12) + 4;
			const int avoidL = barX0 - 6;
			const int avoidR = barX0 + barW + 6;
			const int avoidT = barY0 - labH - 4;
			const int avoidB = barY0 + barH + 4;
			if (tx + tw > avoidL && tx < avoidR && ty + th > avoidT && ty < avoidB) {
				if (cx < hsx)
					tx = avoidL - tw - 2;
				else
					tx = avoidR + 2;
			}
		}

		setFont(g_surf, useFont);
		if (friendlyFire) {
			const bool heavy = ffTier == skeeto_damage::kFriendlyFireDamageHeavy;
			setCol(g_surf, 0, 0, 0, a);
			setPos(g_surf, tx + 2, ty + 2);
			print(g_surf, txt, len, 0);
			setCol(g_surf, 255, heavy ? 64 : 220, heavy ? 64 : 48, a);
			setPos(g_surf, tx, ty);
			print(g_surf, txt, len, 0);
		} else if (isCrit) {
			// Both tiers share the existing 140% font and outline; tier 2 has a red core.
			setCol(g_surf, 255, 120, 120, a);
			setPos(g_surf, tx + 1, ty);
			print(g_surf, txt, len, 0);
			setPos(g_surf, tx - 1, ty);
			print(g_surf, txt, len, 0);
			setPos(g_surf, tx, ty + 1);
			print(g_surf, txt, len, 0);
			setPos(g_surf, tx, ty - 1);
			print(g_surf, txt, len, 0);
			setCol(g_surf, 255, critTier == 2 ? 64 : 220, critTier == 2 ? 64 : 48, a);
			setPos(g_surf, tx, ty);
			print(g_surf, txt, len, 0);
		} else {
			const int pi = (g_dmg[i].pal < (unsigned char)kDmgPalN) ? (int)g_dmg[i].pal : 0;
			const int fr = kDmgPal[pi][0];
			const int fg = kDmgPal[pi][1];
			const int fb = kDmgPal[pi][2];
			setCol(g_surf, 0, 0, 0, a);
			setPos(g_surf, tx + 1, ty + 1);
			print(g_surf, txt, len, 0);
			setCol(g_surf, fr, fg, fb, a);
			setPos(g_surf, tx, ty);
			print(g_surf, txt, len, 0);
		}
	}
}

static void LocalPlayRestore(const char* why) {
	g_offSurvCharServer = -1;
	g_charCommandPending.store(-1, std::memory_order_release);
	// HP bar is client UX now — do not clear it when leaving listen-host localplay.
	g_hpTipUntil = 0;
	g_hpTipLine[0] = 0;
	if (why && why[0])
		Log("localplay: restored (%s)", why);
}

static void LocalPlaySync(const char* why) {
	if (!ListenDetectHost()) {
		LocalPlayRestore(why ? why : "not-host");
		return;
	}
	if (!LocalPlayOptsWanted()) {
		LocalPlayRestore("opts-off");
		return;
	}
	LocalPlayResolveClientProps();
	Log("localplay: sync (%s) char=%d",
		why ? why : "?", g_optLocalCharChange ? 1 : 0);
}

static bool ListenIsHost() {
	return g_listenHost.load(std::memory_order_relaxed);
}

static int ListenEngineTickGuess() {
	if (g_hostTickInterval && PtrCommitted(g_hostTickInterval)) {
		const float v = *g_hostTickInterval;
		if (v >= 0.007f && v <= 0.05f)
			return (int)(1.f / v + 0.5f);
	}
	return 30;
}

static int ListenCycleTick(int cur) {
	if (cur == 0) return 30;
	if (cur == 30) return 60;
	if (cur == 60) return 100;
	if (cur == 100) return 128;
	return 0;
}

static int ListenCycleLerp(int cur) {
	static const int kMs[] = { -1, 0, 24, 40, 60, 100 };
	int idx = 0;
	for (int i = 0; i < 6; ++i) {
		if (kMs[i] == cur) { idx = i; break; }
	}
	return kMs[(idx + 1) % 6];
}

static int ListenCycleAa(int cur) {
	if (cur == 10) return 100;
	if (cur == 100) return 400;
	if (cur == 400) return 1000;
	return 10;
}

static int ListenReadAirAccel() {
	void* var = CvarFind("sv_airaccelerate");
	if (!var) return -1;
	int n = 0;
	float f = 0.f;
	if (!CvarReadPair(var, &n, &f)) return -1;
	if (f > 0.5f && f < 100000.f) return (int)(f + 0.5f);
	if (n > 0 && n < 100000) return n;
	return -1;
}

