// IRecipientFilter (MSVC vtable[0]=dtor) — local player only.
struct SkRcptFilter {
	virtual ~SkRcptFilter() {}
	virtual bool IsReliable() { return false; }
	virtual bool IsInitMessage() { return false; }
	virtual int GetRecipientCount() { return 1; }
	virtual int GetRecipientIndex(int) {
		const int local = g_engine ? EngLocal() : 1;
		return local > 0 ? local : 1;
	}
};

// EmitSound(CHAN_STATIC family, ATTN_NONE): same SFX bus as gunfire UI, full loudness at 1.0.
// EmitAmbientSound was much quieter (ambient ducking in L4D2 combat).
enum class SfxEmitBus : unsigned {
	KillFeedback = 0, // hit/kill/headshot feedback — keep pool separate from UX SFX
	ClientUx = 1,     // shell impact, clank, low-ammo click
};

static bool EngEmitLocalSfxBus(const char* sample, float vol, SfxEmitBus bus, int pitch = 100) {
	if (!g_emitSoundOk || !g_engineSound || !sample || !sample[0]) return false;
	using Fn = void(__thiscall*)(void*, void*, int, int, const char*,
		float, float, int, int,
		const float*, const float*, void*, bool, float, int);
	auto fn = (Fn)VGet(g_engineSound, g_emitSoundIdx);
	if (!fn || !IsExec((void*)fn)) {
		g_emitSoundOk = false;
		return false;
	}
	if (vol < 0.f) vol = 0.f;
	if (vol > 1.f) vol = 1.f;
	if (pitch < 1) pitch = 1;
	if (pitch > 255) pitch = 255;

	SkRcptFilter filter;
	// Separate rotating pools so delayed shell/clank SFX cannot stomp kill feedback.
	static unsigned s_rotKill = 0;
	static unsigned s_rotUx = 0;
	const int base = (bus == SfxEmitBus::KillFeedback) ? 136 : 144;
	const unsigned rot = (bus == SfxEmitBus::KillFeedback) ? s_rotKill++ : s_rotUx++;
	const int chan = base + (int)(rot & 7); // 8 slots per bus

	fn(g_engineSound, &filter,
		-1,   // SOUND_FROM_LOCAL_PLAYER
		chan,
		sample,
		vol,
		0.0f, // ATTN_NONE
		0,
		pitch,
		nullptr, nullptr, nullptr,
		true,
		0.0f,
		-1);
	return true;
}

static bool EngEmitLocalSfx(const char* sample, float vol) {
	return EngEmitLocalSfxBus(sample, vol, SfxEmitBus::KillFeedback);
}

// Local-only fallback for the long-standing silent-SI edge case. Event callbacks
// only enqueue userids; this bounded player-slot sampler and engine sound call run
// on the established Paint/game thread.
static constexpr DWORD kSilentSiScanMs = 100u;
static constexpr DWORD kSilentSiCooldownMs = 4000u;
static constexpr DWORD kSilentSiPendingMs = 1500u;
static constexpr float kSilentSiTriggerDistSq = 300.f * 300.f;
static constexpr float kSilentSiRearmDistSq = 400.f * 400.f;
static constexpr int kSilentSiPendingCap = 8;

struct SilentSiSlot {
	void* entity = nullptr; // identity tag only; never dereferenced after sampling
	int zombieClass = 0;
	bool wasEligible = false;
	bool spawnPending = false;
	bool spawnDone = false;
	bool proximityArmed = true;
	DWORD lastEmitAt = 0;
	DWORD hudUntil = 0;
	bool hudProximity = false;
};

struct SilentSiPendingSpawn {
	int userId = 0;
	DWORD queuedAt = 0;
};

static SilentSiSlot g_silentSiSlots[33]{};
static SilentSiPendingSpawn g_silentSiPending[kSilentSiPendingCap]{};
static int g_silentSiPendingCount = 0;
static DWORD g_silentSiScanAt = 0;
static DWORD g_silentSiPrepareRetryAt = 0;
static DWORD g_silentSiTestAt = 0;
static bool g_silentSiSuppressExistingOnce = false;
static bool g_silentSiSoundsPrepared = false;
static int g_silentSiSoundsPreparedMode = -1; // which source the precache above belongs to

static const char* const kSilentSiClassSound[7] = {
	nullptr,
	"player/smoker/voice/alert/smoker_alert_01.wav",
	"player/boomer/voice/alert/male_boomer_alert_04.wav",
	"player/hunter/voice/alert/hunter_alert_01.wav",
	"player/spitter/voice/alert/spitter_alert_01.wav",
	"player/jockey/voice/alert/jockey_02.wav",
	"player/charger/voice/alert/charger_alert_01.wav",
};
static const char* const kSilentSiFemaleBoomerSound =
	"player/boomer/voice/alert/female_boomer_alert_04.wav";
// Source option 1: vanilla spawn music. The "s" variants are the alternate stingers; the
// first file of each pair is the one used here (mono 44.1 kHz, same format as the alerts).
static const char* const kSilentSiMusicSound[7] = {
	nullptr,
	"music/bacteria/smokerbacteria.wav",
	"music/bacteria/boomerbacteria.wav",
	"music/bacteria/hunterbacteria.wav",
	"music/bacteria/spitterbacteria.wav",
	"music/bacteria/jockeybacteria.wav",
	"music/bacteria/chargerbacteria.wav",
};

static const char* SilentSiClassName(int zombieClass) {
	switch (zombieClass) {
	case 1: return "smoker";
	case 2: return "boomer";
	case 3: return "hunter";
	case 4: return "spitter";
	case 5: return "jockey";
	case 6: return "charger";
	default: return "unknown";
	}
}

static const char* SilentSiPickSound(int zombieClass, void* entity) {
	if (zombieClass < 1 || zombieClass > 6) return nullptr;
	if (g_optClientSilentSiSource == 1)
		return kSilentSiMusicSound[zombieClass];
	if (zombieClass == 2 && entity && g_offModelIndex >= 0 && g_offModelIndex <= 0x4000) {
		const int modelIndex = *(const int*)((const uint8_t*)entity + g_offModelIndex);
		const char* model = TeamHudModelNameInner(modelIndex, true);
		if (model && (strstr(model, "boomette") || strstr(model, "female_boomer")))
			return kSilentSiFemaleBoomerSound;
	}
	return kSilentSiClassSound[zombieClass];
}

