static bool SilentSiPrepareSounds() {
	if (g_silentSiSoundsPrepared && g_silentSiSoundsPreparedMode == g_optClientSilentSiSource)
		return true;
	if (!g_engineSound || !IfaceAlive(g_engineSound)) return false;
	using IsPrecachedFn = bool(__thiscall*)(void*, const char*);
	using PrecacheFn = bool(__thiscall*)(void*, const char*, bool, bool);
	auto isPrecached = (IsPrecachedFn)VGet(g_engineSound, 1);
	auto precache = (PrecacheFn)VGet(g_engineSound, 0);
	if (!isPrecached || !precache || !IsExec((void*)isPrecached) || !IsExec((void*)precache)) return false;
	bool ok = true;
	auto want = [&](const char* sample) {
		if (!sample || !sample[0]) return false;
		if (isPrecached(g_engineSound, sample)) return true;
		if (precache(g_engineSound, sample, false, false)) return true;
		ok = false;
		return false;
	};
	if (g_optClientSilentSiSource == 1) {
		for (int i = 1; i <= 6; ++i) {
			if (!want(kSilentSiMusicSound[i])) want(kSilentSiClassSound[i]);
		}
	} else {
		for (int i = 1; i <= 6; ++i) want(kSilentSiClassSound[i]);
		want(kSilentSiFemaleBoomerSound);
	}
	if (!ok) return false;
	g_silentSiSoundsPreparedMode = g_optClientSilentSiSource;
	g_silentSiSoundsPrepared = true;
	return true;
}

static int EngEmitLocalSpatialVoice(int entIndex, const char* sample, const float origin[3]) {
	if (!g_silentSiSoundsPrepared || !g_engineSound || !IfaceAlive(g_engineSound)
		|| !sample || !sample[0] || !origin) return -1;
	auto fn = (EngineSoundEmitFn)VGet(g_engineSound, kVmtEngineSoundEmitAtten);
	if (!fn || !IsExec((void*)fn)) return -1;
	SkRcptFilter filter;
	fn(g_engineSound, &filter,
		entIndex,
		6,     // CHAN_STATIC: dedicated channel; CHAN_AUTO can be replaced by entity voice
		sample,
		1.0f,
		0.8f,  // ATTN_NORM: spatial and distance-attenuated, never map-wide
		0,
		100,
		origin, nullptr, nullptr,
		true,
		0.0f,
		-1);
	using GetGuidFn = int(__thiscall*)(void*);
	auto getGuid = (GetGuidFn)VGet(g_engineSound, 14);
	return getGuid && IsExec((void*)getGuid) ? getGuid(g_engineSound) : -1;
}

static void SilentSiClear(bool suppressExisting) {
	memset(g_silentSiSlots, 0, sizeof(g_silentSiSlots));
	memset(g_silentSiPending, 0, sizeof(g_silentSiPending));
	g_silentSiPendingCount = 0;
	g_silentSiScanAt = 0;
	g_silentSiTestAt = 0;
	g_silentSiSuppressExistingOnce = suppressExisting;
}

static void SilentSiOnPlayerSpawn(void* ev) {
	if (!ev || !g_optClientSilentSi || !SkeetoFeaturesOn()) return;
	const int userId = EvInt(ev, "userid", 0);
	if (userId <= 0) return;
	const DWORD now = GetTickCount();
	for (int i = 0; i < g_silentSiPendingCount; ++i) {
		if (g_silentSiPending[i].userId == userId) {
			g_silentSiPending[i].queuedAt = now;
			return;
		}
	}
	if (g_silentSiPendingCount >= kSilentSiPendingCap) {
		memmove(&g_silentSiPending[0], &g_silentSiPending[1],
			sizeof(g_silentSiPending[0]) * (kSilentSiPendingCap - 1));
		g_silentSiPendingCount = kSilentSiPendingCap - 1;
	}
	g_silentSiPending[g_silentSiPendingCount++] = { userId, now };
}

static void SilentSiRemovePending(int index) {
	if (index < 0 || index >= g_silentSiPendingCount) return;
	if (index + 1 < g_silentSiPendingCount) {
		memmove(&g_silentSiPending[index], &g_silentSiPending[index + 1],
			sizeof(g_silentSiPending[0]) * (g_silentSiPendingCount - index - 1));
	}
	--g_silentSiPendingCount;
}

static void SilentSiResolvePending(DWORD now) {
	int attempts = 0;
	for (int i = 0; i < g_silentSiPendingCount && attempts < 2;) {
		++attempts;
		const int entIndex = EngPlayerForUserID(g_silentSiPending[i].userId);
		if (entIndex > 0 && entIndex <= 32) {
			g_silentSiSlots[entIndex] = {};
			g_silentSiSlots[entIndex].spawnPending = true;
			g_silentSiSlots[entIndex].proximityArmed = true;
			SilentSiRemovePending(i);
			continue;
		}
		if ((DWORD)(now - g_silentSiPending[i].queuedAt) >= kSilentSiPendingMs) {
			SilentSiRemovePending(i);
			continue;
		}
		++i;
	}
}

static bool SilentSiPlayerSpanReadable(void* entity) {
	if (!entity) return false;
	size_t need = (size_t)g_offOrigin + sizeof(float) * 3;
	auto include = [&](int offset, size_t bytes) {
		if (offset < 0) return;
		const size_t end = (size_t)offset + bytes;
		if (end > need) need = end;
	};
	include(g_offTeam, sizeof(int));
	include(g_offLifeState, sizeof(uint8_t));
	include(g_offZombieClass, sizeof(int));
	include(g_offIsGhost, sizeof(uint8_t));
	if (g_offModelIndex >= 0 && g_offModelIndex <= 0x4000)
		include(g_offModelIndex, sizeof(int));
	if (g_offObserverMode >= 0 && g_offObserverMode <= 0x4000)
		include(g_offObserverMode, sizeof(int));
	return skmem::SpanProbeAt(entity, need, (uintptr_t)_ReturnAddress());
}

static bool SilentSiLocalOrigin(float out[3]) {
	if (!out || !g_engine || !g_entlist || !EngInGame()) return false;
	if (g_offTeam < 0 || g_offTeam > 0x4000
		|| g_offLifeState < 0 || g_offLifeState > 0x4000
		|| g_offOrigin < 0 || g_offOrigin > 0x4000) return false;
	const int local = EngLocal();
	if (local <= 0 || local > 32) return false;
	void* me = EntGet(local);
	if (!SilentSiPlayerSpanReadable(me)) return false;
	const int* team = (const int*)((const uint8_t*)me + g_offTeam);
	const uint8_t* life = (const uint8_t*)me + g_offLifeState;
	const float* origin = (const float*)((const uint8_t*)me + g_offOrigin);
	if (*team != 2 || *life != 0) return false;
	if (g_offObserverMode >= 0 && g_offObserverMode <= 0x4000) {
		const int* observer = (const int*)((const uint8_t*)me + g_offObserverMode);
		if (*observer != 0) return false;
	}
	out[0] = origin[0]; out[1] = origin[1]; out[2] = origin[2];
	return true;
}

static void SilentSiTick() {
	if (!g_optClientSilentSi || !SkeetoFeaturesOn()) return;
	const DWORD now = GetTickCount();
	// LevelInit can run before IEngineSound is ready. Retry preparation from the
	// game-thread tick so an enabled source does not remain permanently
	// silent after that one early failure.
	if (!g_silentSiSoundsPrepared && (!g_silentSiPrepareRetryAt
		|| (LONG)(now - g_silentSiPrepareRetryAt) >= 0)) {
		g_silentSiPrepareRetryAt = now + 1000u;
		(void)SilentSiPrepareSounds();
	}
	if (g_silentSiScanAt && (DWORD)(now - g_silentSiScanAt) < kSilentSiScanMs) return;
	g_silentSiScanAt = now;
	if (!g_engineSound || !g_entlist || !g_engine) return;
	if (g_offTeam < 0 || g_offTeam > 0x4000
		|| g_offLifeState < 0 || g_offLifeState > 0x4000
		|| g_offZombieClass < 0 || g_offZombieClass > 0x4000
		|| g_offIsGhost < 0 || g_offIsGhost > 0x4000
		|| g_offOrigin < 0 || g_offOrigin > 0x4000) return;
	float localOrigin[3]{};
	if (!SilentSiLocalOrigin(localOrigin)) return;
	if (g_silentSiTestAt && (LONG)(now - g_silentSiTestAt) >= 0) {
		g_silentSiTestAt = 0;
		// Check tone for the smoker class, using whichever source is selected.
		const char* probe = SilentSiPickSound(1, nullptr);
		const int guid = EngEmitLocalSpatialVoice(EngLocal(), probe, localOrigin);
		Log("silent-si: toggle test smoker=%s guid=%d ok=%d",
			probe ? probe : "?", guid, guid >= 0 ? 1 : 0);
	}
	SilentSiResolvePending(now);

	const bool suppressExisting = g_silentSiSuppressExistingOnce;
	bool attemptedThisScan = false;
	for (int i = 1; i <= 32; ++i) {
		void* e = EntGet(i);
		if (!SilentSiPlayerSpanReadable(e)) {
			g_silentSiSlots[i] = {};
			continue;
		}
		const int* team = (const int*)((const uint8_t*)e + g_offTeam);
		const uint8_t* life = (const uint8_t*)e + g_offLifeState;
		const int* zombieClass = (const int*)((const uint8_t*)e + g_offZombieClass);
		const uint8_t* ghost = (const uint8_t*)e + g_offIsGhost;
		const float* origin = (const float*)((const uint8_t*)e + g_offOrigin);
		const int zc = *zombieClass;
		const bool eligible = *team == 3 && *life == 0 && *ghost == 0 && zc >= 1 && zc <= 6;
		SilentSiSlot& slot = g_silentSiSlots[i];
		if (slot.entity != e || slot.zombieClass != zc) {
			slot = {};
			slot.entity = e;
			slot.zombieClass = zc;
			slot.proximityArmed = true;
			if (eligible) slot.spawnPending = true;
		} else if (eligible && !slot.wasEligible) {
			slot.spawnPending = true;
			slot.spawnDone = false;
			slot.proximityArmed = true;
		}
		slot.wasEligible = eligible;
		if (!eligible) continue;

		float distSq = -1.f;
		if (g_optClientSilentSiProximity || g_optClientSiProximityHud) {
			const float dx = origin[0] - localOrigin[0];
			const float dy = origin[1] - localOrigin[1];
			const float dz = origin[2] - localOrigin[2];
			 distSq = dx * dx + dy * dy + dz * dz;
		}
		if (g_optClientSiProximityHud && distSq >= 0.f) {
			if (distSq <= kSilentSiTriggerDistSq) {
				slot.hudUntil = now + 220u;
				slot.hudProximity = true;
			} else if (slot.hudProximity && distSq >= kSilentSiRearmDistSq) {
				slot.hudUntil = 0;
				slot.hudProximity = false;
			}
		}
		if (suppressExisting) {
			slot.spawnPending = false;
			slot.spawnDone = true;
			slot.proximityArmed = !g_optClientSilentSiProximity
				|| distSq > kSilentSiTriggerDistSq;
			continue;
		}

		if (g_optClientSilentSiProximity && !slot.proximityArmed
			&& distSq >= kSilentSiRearmDistSq)
			slot.proximityArmed = true;
		if (attemptedThisScan) continue;

		bool shouldEmit = false;
		const char* reason = nullptr;
		if (slot.spawnPending && !slot.spawnDone) {
			shouldEmit = true;
			reason = "spawn";
			slot.spawnPending = false;
			slot.spawnDone = true;
		} else if (g_optClientSilentSiProximity && slot.proximityArmed
			&& distSq <= kSilentSiTriggerDistSq
			&& (!slot.lastEmitAt || (DWORD)(now - slot.lastEmitAt) >= kSilentSiCooldownMs)) {
			shouldEmit = true;
			reason = "proximity";
		}
		if (!shouldEmit) continue;

		attemptedThisScan = true;
		const char* sample = SilentSiPickSound(zc, e);
		const int guid = EngEmitLocalSpatialVoice(i, sample, origin);
		const bool emitted = guid >= 0;
		if ((strcmp(reason, "spawn") == 0 && g_optClientSiSpawnHud)
			|| (strcmp(reason, "proximity") == 0 && g_optClientSiProximityHud)) {
			slot.hudUntil = now + (strcmp(reason, "spawn") == 0 ? 2600u : 1800u);
			slot.hudProximity = strcmp(reason, "proximity") == 0;
		}
		if (!strcmp(reason, "proximity")
			|| (g_optClientSilentSiProximity && distSq <= kSilentSiTriggerDistSq))
			slot.lastEmitAt = now;
		if (g_optClientSilentSiProximity && distSq <= kSilentSiTriggerDistSq)
			slot.proximityArmed = false;
		Log("silent-si: %s %s ent=%d distance2=%.0f sample=%s guid=%d ok=%d",
			reason, SilentSiClassName(zc), i, distSq, sample ? sample : "-", guid, emitted ? 1 : 0);
	}
	g_silentSiSuppressExistingOnce = false;
}

static const wchar_t* SilentSiWarningStyleName() {
	return g_siWarnStyle ? UiText(UiId::SiWarningStyleIcon, L"透明图标")
		: UiText(UiId::SiWarningStyleText, L"文字");
}

static void SilentSiIconLine(int x0, int y0, int x1, int y1, int thickness) {
	if (thickness < 1) thickness = 1;
	for (int i = 0; i < thickness; ++i)
		SurfLine(x0, y0 + i, x1, y1 + i);
}

static void SilentSiDrawWarningIcon(int zc, bool /*proximity*/, int cx, int cy, int scale, int alpha,
	COLORREF colorOverride = CLR_INVALID) {
	if (zc < 1 || zc > 6) return;
	static const COLORREF kColors[7] = {
		0, RGB(188, 198, 112), RGB(255, 204, 48), RGB(66, 145, 215),
		RGB(132, 225, 34), RGB(224, 42, 145), RGB(242, 58, 42)
	};
	const int iconPx = HudScalePx(44, scale);
	const int t = iconPx >= 88 ? 4 : (iconPx >= 66 ? 3 : (iconPx >= 44 ? 2 : 1));
	const auto p = [iconPx](int v) { return (v * iconPx) / 44; };
	const auto fill = [&](int l, int top, int r, int bottom) {
		SurfFill(cx + p(l), cy + p(top), cx + p(r), cy + p(bottom));
	};
	const auto line = [&](int x0, int y0, int x1, int y1) {
		SilentSiIconLine(cx + p(x0), cy + p(y0), cx + p(x1), cy + p(y1), t);
	};
	const COLORREF iconColor = colorOverride != CLR_INVALID ? colorOverride : kColors[zc];
	SurfColor(GetRValue(iconColor), GetGValue(iconColor), GetBValue(iconColor), alpha);
	switch (zc) {
	case 1: // Smoker: a curled tongue / smoke trail.
		line(-15, -12, -6, -15); line(-6, -15, 5, -12); line(5, -12, 10, -6);
		line(10, -6, 9, 2); line(9, 2, 3, 8); line(3, 8, -7, 9);
		line(-7, 9, -13, 5); line(-13, 5, -10, 1); line(-10, 1, -3, 1);
		line(-3, 1, -5, 6); line(-5, 6, -1, 12);
		fill(-12, 13, -7, 16); fill(-10, 11, -6, 14);
		break;
	case 2: // Boomer: a compact acid splat with droplets.
		fill(-9, -6, 9, 6); fill(-6, -10, 6, 10); fill(-4, 6, 4, 12);
		fill(-14, -10, -11, -6); fill(11, -12, 14, -8); fill(14, 5, 17, 9);
		fill(-17, 5, -14, 9); fill(-2, -16, 2, -12); fill(6, 12, 9, 16);
		break;
	case 3: // Hunter: three separated claw slashes.
		line(-15, 12, -6, -13); line(-7, 15, 2, -14); line(1, 15, 11, -11);
		line(-12, 13, -4, -10); line(-4, 15, 5, -11); line(4, 15, 14, -8);
		break;
	case 4: // Spitter: falling droplets over an acid splash.
		fill(-2, -17, 2, -8); fill(-1, -6, 2, -2); fill(8, -12, 12, -5);
		fill(-13, 7, 13, 12); fill(-9, 3, 9, 14); fill(-15, 9, -10, 13);
		fill(10, 8, 16, 12); fill(-4, 13, 5, 16); fill(3, -1, 7, 3);
		break;
	case 5: // Jockey: a compact spiral with crown spikes.
		line(-13, -8, -5, -13); line(-5, -13, 7, -11); line(7, -11, 13, -4);
		line(13, -4, 10, 5); line(10, 5, 2, 10); line(2, 10, -7, 8);
		line(-7, 8, -10, 2); line(-10, 2, -5, -2); line(-5, -2, 3, -3);
		line(3, -3, 6, 1); line(6, 1, 2, 5); line(2, 5, -2, 4);
		line(-11, -15, -7, -21); line(-2, -14, 0, -22); line(6, -13, 11, -19);
		break;
	case 6: // Charger: forward arrow / impact mark.
		fill(-17, -3, 4, 3); fill(-13, -7, -4, 7);
		line(2, -13, 16, 0); line(16, 0, 2, 13); line(2, 13, 6, 4);
		line(2, -13, 6, -4); line(-18, -10, -11, -7); line(-18, 10, -11, 7);
		break;
	default:
		break;
	}
}

static void SilentSiDrawWarningBadge(int zc, bool proximity, int x, int y, int scale, int /*alpha*/) {
	if (g_siWarnStyle) {
		static const wchar_t* kNames[7] = { L"", L"SMOKER", L"BOOMER", L"HUNTER", L"SPITTER", L"JOCKEY", L"CHARGER" };
		static const COLORREF kColors[7] = {
			0, RGB(188, 198, 112), RGB(255, 204, 48), RGB(66, 145, 215),
			RGB(132, 225, 34), RGB(224, 42, 145), RGB(242, 58, 42)
		};
		const int centerX = x + HudScalePx(42, scale);
		SilentSiDrawWarningIcon(zc, proximity, centerX, y + HudScalePx(22, scale), scale, 255);
		if (g_siWarnIconFont) {
			wchar_t name[32]{};
			swprintf_s(name, 32, proximity ? L">>>%s<<<" : L"%s", kNames[zc]);
			const int nameW = SurfTextWFont(g_siWarnIconFont, name);
			SurfTextAt(g_siWarnIconFont, centerX - nameW / 2, y + HudScalePx(47, scale), kColors[zc], name);
		}
		return;
	}
	if (zc < 1 || zc > 6 || !g_hudFont) return;
	static const wchar_t* kNames[7] = { L"", L"SMOKER", L"BOOMER", L"HUNTER", L"SPITTER", L"JOCKEY", L"CHARGER" };
	static const COLORREF kColors[7] = { 0, RGB(235, 76, 76), RGB(185, 210, 80), RGB(92, 151, 255), RGB(90, 230, 90), RGB(255, 157, 62), RGB(170, 145, 190) };
	wchar_t label[24]{};
	swprintf_s(label, 24, proximity ? L">>>%s<<<" : L"%s", kNames[zc]);
	unsigned long font = HudAcquireLayoutFont(HudScalePx(22, scale), &g_hudLayoutFont, &g_hudLayoutFontPx, 800);
	if (!font) font = g_hudFont;
	SurfTextAt(font, x, y, kColors[zc], label);
}
static void ClampSiWarningHud() {
	if (g_siWarnStyle < 0) g_siWarnStyle = 0;
	if (g_siWarnStyle > 1) g_siWarnStyle = 1;
	if (g_siWarnAlign < 0) g_siWarnAlign = 0;
	if (g_siWarnAlign > 5) g_siWarnAlign = 5;
	ClampHudAbsCoord(g_siWarnAbs, &g_siWarnOffX, &g_siWarnOffY,
		(g_siWarnAlign == 4 || g_siWarnAlign == 5) ? -400 : 0,
		(g_siWarnAlign == 4 || g_siWarnAlign == 5) ? 400 : 600);
	g_siWarnScale = HudClampScale(g_siWarnScale);
}

static void SiWarningHudResetPos() {
	g_siWarnAbs = false;
	g_siWarnAlign = 4;
	g_siWarnOffX = 0;
	g_siWarnOffY = 72;
}

static void SilentSiWarningHudPaint() {
	const bool preview = HudMenuPage(kMenuPageSiWarningHud);
	if ((!g_optClientSilentSi && !preview) || (!g_optClientSiSpawnHud && !g_optClientSiProximityHud && !preview)) return;
	if (!MenuEnsureSurf()) return;
	SurfEnsureHudFont();
	const DWORD now = GetTickCount();
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;
	const int sc = HudClampScale(g_siWarnScale);
	unsigned long font = 0;
	if (!g_siWarnStyle) {
		if (!g_hudFont) return;
		font = HudAcquireLayoutFont(HudScalePx(22, sc), &g_hudLayoutFont, &g_hudLayoutFontPx, 800);
		if (!font) font = g_hudFont;
	} else {
		g_siWarnIconFont = HudAcquireLayoutFont(HudScalePx(14, sc),
			&g_siWarnIconFont, &g_siWarnIconFontPx, 800);
		if (!g_siWarnIconFont) return;
	}
	static const wchar_t* kNames[7] = { L"", L"SMOKER", L"BOOMER", L"HUNTER", L"SPITTER", L"JOCKEY", L"CHARGER" };
	int panelW = HudScalePx(84, sc);
	int panelH = HudScalePx(66, sc);
	if (!g_siWarnStyle) {
		panelW = 0;
		for (int zc = 1; zc <= 6; ++zc) {
			const int normalW = SurfTextWFont(font, kNames[zc]);
			wchar_t nearName[24]{};
			swprintf_s(nearName, 24, L">>>%s<<<", kNames[zc]);
			const int nearW = SurfTextWFont(font, nearName);
			if (normalW > panelW) panelW = normalW;
			if (nearW > panelW) panelW = nearW;
		}
		panelW += HudScalePx(8, sc);
		panelH = HudScalePx(30, sc);
	}
	int x = 0, y = 0;
	ClampSiWarningHud();
	HudFinalizePos(&g_siWarnAbs, &g_siWarnOffX, &g_siWarnOffY, g_siWarnAlign, sw, sh, panelW, panelH, &x, &y);
	int count = 0;
	for (int i = 1; i <= 32 && count < 6; ++i) {
		SilentSiSlot& slot = g_silentSiSlots[i];
		if (!slot.hudUntil || (LONG)(now - slot.hudUntil) >= 0) { slot.hudUntil = 0; continue; }
		if (slot.hudProximity ? !g_optClientSiProximityHud : !g_optClientSiSpawnHud) continue;
		if (slot.zombieClass < 1 || slot.zombieClass > 6) continue;
		SilentSiDrawWarningBadge(slot.zombieClass, slot.hudProximity, x, y, sc, 255);
		count = 1;
		break;
	}
	if (count > 0) return;
	if (!preview && !HudLayoutPeer(g_optClientSilentSi && (g_optClientSiSpawnHud || g_optClientSiProximityHud), kMenuPageSiWarningHud))
		return;
	const bool isNear = g_optClientSiProximityHud && !g_optClientSiSpawnHud;
	SilentSiDrawWarningBadge(1, isNear, x, y, sc, 190);
}
static void PtWarmEnqueue(const char* name, bool /*worldSpace*/) {
	if (!name || !name[0] || g_ptWarmCount >= kPtWarmCap) return;
	for (int i = 0; i < g_ptWarmCount; ++i) {
		if (!_stricmp(g_ptWarmName[i], name))
			return;
	}
	strncpy(g_ptWarmName[g_ptWarmCount], name, sizeof(g_ptWarmName[0]) - 1);
	g_ptWarmName[g_ptWarmCount][sizeof(g_ptWarmName[0]) - 1] = 0;
	++g_ptWarmCount;
}

static void PtWarmEnqueueFx(const DlcFx* fx) {
	if (!fx || !fx->used) return;
	if (fx->particle[0])
		PtWarmEnqueue(fx->particle, fx->worldSpace);
	for (int i = 0; i < fx->particleExtraCount; ++i) {
		if (fx->particleExtra[i][0])
			PtWarmEnqueue(fx->particleExtra[i], fx->worldSpace);
	}
}

static void PtWarmEnqueueStyle(const DlcStyle* st) {
	if (!st) return;
	PtWarmEnqueueFx(&st->hit);
	PtWarmEnqueueFx(&st->kill);
	PtWarmEnqueueFx(&st->headshot);
	PtWarmEnqueueFx(&st->melee);
	for (int i = 1; i <= 11; ++i) {
		if (st->streakSlot[i])
			PtWarmEnqueueFx(&st->streak[i]);
	}
	for (int i = 0; i < st->namedCount; ++i)
		PtWarmEnqueueFx(&st->named[i].fx);
}

static void PtWarmBuildSelected() {
	g_ptWarmCount = 0;
	static const char* kChannels[] = { "ci", "si", "ff", "fx" };
	for (int i = 0; i < 4; ++i) {
		const char* id = DlcGetSelected(kChannels[i]);
		if (id && id[0] && _stricmp(id, "off"))
			PtWarmEnqueueStyle(DlcFindStyle(id));
	}

	// These are the built-in fallbacks used by FireFX when the selected fx style
	// does not override a named event. Only the enabled feature can emit them.
	if (g_optKillFx) {
		static const char* kKillFx[] = {
			"skeet", "melee_skeet", "headshot_skeet",
			"crown", "perfect_crown", "melee_crown",
			"crit_text", "level", "tongue_cut",
			nullptr
		};
		for (int i = 0; kKillFx[i]; ++i)
			PtWarmEnqueue(kKillFx[i], true);
	}
}

// Current selections > PrecacheParticleSystem. Call only on the game thread.
// Preloading every discovered DIY style on every chapter was unnecessary map-edge
// resource work and could populate the engine with assets the user never selected.
static void PrecacheSelectedParticles(const char* reason) {
	if (!g_precache || !IsExec((void*)g_precache)) {
		Log("particle precache skip: PrecacheParticleSystem unavailable");
		return;
	}

	PtWarmBuildSelected();

	int done = 0;
	int known = 0;
	for (int i = 0; i < g_ptWarmCount; ++i) {
		const char* name = g_ptWarmName[i];
		if (!name[0]) continue;
		// FindParticleSystem != usable this map. Necola still calls
		// PrecacheParticleSystemOffset after a successful find; skipping it
		// made combat Dispatch a no-op (queued=N precached=0 already-in-mgr=N).
		if (g_findParticle && g_particleMgr && IsExec((void*)g_findParticle)
			&& g_findParticle(g_particleMgr, name))
			++known;
		g_precache(name);
		++done;
	}
	Log("particle precache (selected): reason=%s queued=%d precached=%d already-in-mgr=%d styles=%d",
		reason ? reason : "?", g_ptWarmCount, done, known, DlcGetCatalog()->count);
}

// Shared with the main-menu Addons indicator. Game/Paint thread only; callers
// own their cadence. Signature binding is process/module-once, then three small
// guarded reads with no page queries, enumeration, allocation or engine calls.
// Retail gameui.dll SHA256 321ec9b5... / timestamp 6A440E8A / x86:
// BasePanel queues update_addon_paths/mission_reload before setting +0x2D0.
// It may defer that work while connected; never force addon remounts in a map.
static int NativeAddonsLoadState() {
	static HMODULE checked = nullptr;
	static void** baseSlot = nullptr;
	static uintptr_t moduleEnd = 0;
	const HMODULE module = GetModuleHandleA("gameui.dll");
	if (!module) return -1;
	__try {
		if (module != checked) {
			checked = module;
			baseSlot = nullptr;
			auto dos = (PIMAGE_DOS_HEADER)module;
			auto nt = (PIMAGE_NT_HEADERS)((unsigned char*)module + dos->e_lfanew);
			if (nt->FileHeader.Machine != IMAGE_FILE_MACHINE_I386) return -1;
			moduleEnd = (uintptr_t)module + nt->OptionalHeader.SizeOfImage;
			uintptr_t hits[2]{};
			const char* pattern = "E8 ? ? ? ? 80 B8 D0 02 00 00 00 8B 8E F0 02 00 00 8B 11 8B 92 84 00 00 00 0F 94 C0 0F B6 C0 50 FF D2";
			if (CountPat("gameui.dll", pattern, hits, 2) != 1) {
				Log("addon completion state unavailable: unsupported GameUI signature");
				return -1;
			}
			int relative = 0;
			memcpy(&relative, (void*)(hits[0] + 1), 4);
			const uintptr_t getter = hits[0] + 5 + relative;
			if (!BackgroundPtrInModule((void*)getter, module)
				|| !BackgroundPtrInModule((void*)(getter + 5), module) || !IsExec((void*)getter)
				|| *(unsigned char*)getter != 0xA1 || *(unsigned char*)(getter + 5) != 0xC3) return -1;
			uintptr_t slot = 0;
			memcpy(&slot, (void*)(getter + 1), 4);
			if (!BackgroundPtrInModule((void*)slot, module)
				|| !BackgroundPtrInModule((void*)(slot + 3), module)) return -1;
			baseSlot = (void**)slot;
		}
		void* base = nullptr;
		void* vtable = nullptr;
		unsigned char complete = 0;
		if (!baseSlot || !skmem::Copy(&base, baseSlot, sizeof(base)) || !base) return -1;
		if (!skmem::Copy(&vtable, base, sizeof(vtable))
			|| (uintptr_t)vtable < (uintptr_t)module || (uintptr_t)vtable >= moduleEnd) return -1;
		if (!skmem::Copy(&complete, (const unsigned char*)base + 0x2D0, sizeof(complete)) || complete > 1) return -1;
		return complete ? 0 : 1;
	} __except (skmem::FaultFilter(GetExceptionCode(), GetExceptionInformation())) {
		skmem::NoteFault((uintptr_t)_ReturnAddress());
		baseSlot = nullptr;
		return -1;
	}
}

static bool g_feedbackCatalogRecoveryDone = false;
static bool g_feedbackCatalogRecoveryRunning = false;
static DWORD g_feedbackCatalogReadAt = 0;
static int g_feedbackCatalogMountState = -1;

static void FeedbackCatalogPump() {
	const bool menu = g_engine && !g_paintConnected.load(std::memory_order_relaxed)
		&& !g_paintInGame.load(std::memory_order_relaxed) && !g_paintLoading.load(std::memory_order_relaxed);
	if (!g_optFeedbackWorkshopRecovery || !SkeetoFeaturesOn()) {
		if (g_feedbackCatalogRecoveryRunning) DlcCatalogRecoveryCancel();
		g_feedbackCatalogRecoveryRunning = false;
		g_feedbackCatalogRecoveryDone = false;
		g_feedbackCatalogReadAt = 0;
		g_feedbackCatalogMountState = -1;
		// The existing ordinary menu catalog remains independent of this option.
		if (!DlcEngineGlobTried() || DlcGetCatalog()->count <= 0 || (menu && DlcStyleLimitPending())) {
			if (DlcEnsureCatalog(g_gameL4d2Dir, menu))
				Log("catalog ready (Paint) styles=%d GAME=%d ms=%d", DlcGetCatalog()->count,
					DlcLastEngineJsonCount(), DlcLastReloadMs());
		}
		return;
	}
	DlcEnsureCatalog(g_gameL4d2Dir, false);
	if (g_feedbackCatalogRecoveryDone && !(menu && DlcStyleLimitPending())) return;
	if (g_paintLoading.load(std::memory_order_relaxed)
		|| g_mapEnterGameThreadResetPending.load(std::memory_order_acquire)
		|| (!menu && !g_paintInGame.load(std::memory_order_relaxed))
		|| (!menu && DlcStyleLimitPending())) {
		if (g_feedbackCatalogRecoveryRunning) DlcCatalogRecoveryCancel();
		g_feedbackCatalogRecoveryRunning = false;
		g_feedbackCatalogReadAt = 0;
		g_feedbackCatalogMountState = -1;
		return;
	}
	const DWORD now = GetTickCount();
	const bool sample = !g_feedbackCatalogReadAt || (LONG)(now - g_feedbackCatalogReadAt) >= 0;
	if (sample || g_feedbackCatalogRecoveryRunning) {
		const int previous = g_feedbackCatalogMountState;
		g_feedbackCatalogReadAt = now + 500u;
		g_feedbackCatalogMountState = NativeAddonsLoadState();
		// Native completion queues update_addon_paths. Require completion on two
		// spaced samples so a second UI Paint in the same engine frame cannot
		// enumerate the old paths before the queued command gets its turn.
		if (previous != 0 && g_feedbackCatalogMountState == 0 && !g_feedbackCatalogRecoveryRunning) return;
	}
	if (g_feedbackCatalogMountState != 0) {
		if (g_feedbackCatalogRecoveryRunning) DlcCatalogRecoveryCancel();
		g_feedbackCatalogRecoveryRunning = false;
		return;
	}
	if (!g_feedbackCatalogRecoveryRunning) {
		if (!sample) return;
		if (!DlcEngineCatalogReady()) {
			g_feedbackCatalogMountState = -1;
			return;
		}
		if (!DlcCatalogRecoveryBegin()) {
			g_feedbackCatalogRecoveryDone = true;
			Log("catalog workshop recovery could not open GAME enumeration; selections retained");
			return;
		}
		g_feedbackCatalogRecoveryDone = false;
		g_feedbackCatalogRecoveryRunning = true;
		// Separate first enumeration and first JSON read into different Paints.
		return;
	}
	const int result = DlcCatalogRecoveryPump();
	if (result != 0) {
		g_feedbackCatalogRecoveryRunning = false;
		if (result == 1 && DlcGetCatalog()->count <= 0 && !DlcEngineGlobTried()) {
			g_feedbackCatalogMountState = -1;
			g_feedbackCatalogReadAt = GetTickCount() + 500u;
			Log("catalog workshop recovery empty; retry after addon paths settle");
		} else {
			g_feedbackCatalogRecoveryDone = true;
			if (result == 1 && g_paintInGame.load(std::memory_order_relaxed))
				PrecacheSelectedParticles("catalog-workshop-recovery");
			Log("catalog workshop recovery result=%d styles=%d GAME=%d cpuMs=%d; selections retained",
				result, DlcGetCatalog()->count, DlcLastEngineJsonCount(), DlcLastReloadMs());
		}
	}
}

static bool VtProtectWrite(void** slot, void* neu, void** prevOut) {
	if (!slot) return false;
	DWORD old = 0;
	if (!VirtualProtect(slot, sizeof(void*), PAGE_EXECUTE_READWRITE, &old))
		return false;
	if (prevOut) *prevOut = *slot;
	*slot = neu;
	DWORD tmp = 0;
	VirtualProtect(slot, sizeof(void*), old, &tmp);
	return true;
}

static bool SoundSampleContains(const char* sample, const char* needle) {
	if (!sample || !needle || !needle[0]) return false;
	for (const char* p = sample; *p; ++p) {
		const char* a = p;
		const char* b = needle;
		while (*a && *b && tolower((unsigned char)*a) == tolower((unsigned char)*b)) {
			++a;
			++b;
		}
		if (!*b) return true;
	}
	return false;
}

enum class SoundVolumeGroup : unsigned char {
	None,
	Gunfire,
	WeaponHandling,
	Melee,
	Chainsaw,
	Footsteps,
	SurvivorVoice,
	SpecialInfected,
	CommonInfected,
	Tank,
	Witch,
	Explosions,
	Throwables,
	Ambient,
	Ui,
	Vehicles,
	Items,
	ScriptCue,
};

static constexpr char SoundPathLower(char c) {
	return c >= 'A' && c <= 'Z' ? (char)(c + ('a' - 'A')) : (c == '\\' ? '/' : c);
}

static constexpr bool SoundPathStartsWith(const char* sample, const char* prefix) {
	if (!sample || !prefix) return false;
	while (*prefix) {
		if (!*sample || SoundPathLower(*sample) != SoundPathLower(*prefix)) return false;
		++sample;
		++prefix;
	}
	return true;
}

static constexpr bool SoundPathContains(const char* sample, const char* needle) {
	if (!sample || !needle || !*needle) return false;
	for (const char* p = sample; *p; ++p) {
		const char* a = p;
		const char* b = needle;
		while (*a && *b && SoundPathLower(*a) == SoundPathLower(*b)) {
			++a;
			++b;
		}
		if (!*b) return true;
	}
	return false;
}

static constexpr bool SoundSourceControlPrefix(char c) {
	return c == '*' || c == '#' || c == '!' || c == '@' || c == '>' || c == '<'
		|| c == '^' || c == ')' || c == '}' || c == '$' || c == '?' || c == ' ' || c == '\t';
}

static constexpr const char* NormalizeSoundSample(const char* sample) {
	if (!sample) return "";
	while (*sample && SoundSourceControlPrefix(*sample)) ++sample;
	return SoundPathStartsWith(sample, "sound/") ? sample + 6 : sample;
}

static constexpr bool IsKnownMeleeWeaponPath(const char* sample) {
	return SoundPathStartsWith(sample, "weapons/melee/")
		|| SoundPathStartsWith(sample, "weapons/axe/")
		|| SoundPathStartsWith(sample, "weapons/bat/")
		|| SoundPathStartsWith(sample, "weapons/baseball_bat/")
		|| SoundPathStartsWith(sample, "weapons/cricket_bat/")
		|| SoundPathStartsWith(sample, "weapons/cricketbat/")
		|| SoundPathStartsWith(sample, "weapons/crowbar/")
		|| SoundPathStartsWith(sample, "weapons/electric_guitar/")
		|| SoundPathStartsWith(sample, "weapons/fireaxe/")
		|| SoundPathStartsWith(sample, "weapons/frying_pan/")
		|| SoundPathStartsWith(sample, "weapons/golf_club/")
		|| SoundPathStartsWith(sample, "weapons/guitar/")
		|| SoundPathStartsWith(sample, "weapons/katana/")
		|| SoundPathStartsWith(sample, "weapons/knife/")
		|| SoundPathStartsWith(sample, "weapons/machete/")
		|| SoundPathStartsWith(sample, "weapons/pan/")
		|| SoundPathStartsWith(sample, "weapons/pitchfork/")
		|| SoundPathStartsWith(sample, "weapons/shovel/")
		|| SoundPathStartsWith(sample, "weapons/tonfa/");
}

static constexpr bool IsThrowableWeaponPath(const char* sample) {
	return SoundPathStartsWith(sample, "weapons/molotov/")
		|| SoundPathStartsWith(sample, "weapons/pipe_bomb/")
		|| SoundPathStartsWith(sample, "weapons/pipebomb/")
		|| SoundPathStartsWith(sample, "weapons/vomitjar/")
		|| SoundPathStartsWith(sample, "weapons/bile_jar/")
		|| SoundPathStartsWith(sample, "weapons/bilejar/");
}

static constexpr bool IsExplosionPath(const char* sample) {
	if (SoundPathStartsWith(sample, "weapons/explode/")
		|| SoundPathStartsWith(sample, "ambient/explosions/"))
		return true;
	if (SoundPathContains(sample, "explod") || SoundPathContains(sample, "/blast"))
		return true;
	return false;
}

static constexpr bool IsVehiclePath(const char* sample) {
	if (SoundPathStartsWith(sample, "vehicles/")
		|| SoundPathStartsWith(sample, "npc/vehicles/"))
		return true;
	// Parish finale uses a C130; its loops often say propeller/c130, not helicopter.
	return SoundPathContains(sample, "helicopter")
		|| SoundPathContains(sample, "chopper")
		|| SoundPathContains(sample, "c130")
		|| SoundPathContains(sample, "propeller")
		|| SoundPathContains(sample, "airplane")
		|| SoundPathContains(sample, "aircraft")
		|| SoundPathContains(sample, "rotor")
		|| SoundPathContains(sample, "/boat")
		|| SoundPathContains(sample, "ferry");
}

static constexpr bool IsSpecialInfectedPath(const char* sample) {
	return SoundPathStartsWith(sample, "player/hunter/")
		|| SoundPathStartsWith(sample, "player/smoker/")
		|| SoundPathStartsWith(sample, "player/boomer/")
		|| SoundPathStartsWith(sample, "player/charger/")
		|| SoundPathStartsWith(sample, "player/jockey/")
		|| SoundPathStartsWith(sample, "player/spitter/")
		|| SoundPathStartsWith(sample, "player/pz/");
}

static constexpr SoundVolumeGroup ClassifySoundVolumeSample(const char* rawSample) {
	const char* sample = NormalizeSoundSample(rawSample);
	if (SoundPathStartsWith(sample, "emsc/")
		|| SoundPathStartsWith(sample, "lasc/")
		|| SoundPathStartsWith(sample, "weapons/spent_mags/"))
		return SoundVolumeGroup::ScriptCue;
	if (SoundPathStartsWith(sample, "player/footsteps/"))
		return SoundVolumeGroup::Footsteps;
	if (SoundPathStartsWith(sample, "player/survivor/voice/"))
		return SoundVolumeGroup::SurvivorVoice;
	// swing = whoosh / miss; hit = shove + melee flesh/world impact (vanilla shove lives here).
	if (SoundPathStartsWith(sample, "player/survivor/swing/")
		|| SoundPathStartsWith(sample, "player/survivor/hit/"))
		return SoundVolumeGroup::Melee;
	if (SoundPathStartsWith(sample, "weapons/chainsaw/"))
		return SoundVolumeGroup::Chainsaw;
	if (IsKnownMeleeWeaponPath(sample))
		return SoundVolumeGroup::Melee;
	if (IsThrowableWeaponPath(sample))
		return SoundVolumeGroup::Throwables;
	if (SoundPathStartsWith(sample, "weapons/")
		&& (SoundPathContains(sample, "/gunfire/")
			|| (SoundPathContains(sample, "/grenadefire/")
				&& SoundPathContains(sample, "/grenade_launcher_fire"))
			|| SoundPathContains(sample, "/50cal_shoot")
			|| SoundPathContains(sample, "/minigun_shoot")))
		return SoundVolumeGroup::Gunfire;
	if (SoundPathStartsWith(sample, "weapons/")
		&& (SoundPathContains(sample, "/gunother/")
			|| SoundPathContains(sample, "/grenadeother/")
			|| SoundPathContains(sample, "/clipempty_")))
		return SoundVolumeGroup::WeaponHandling;
	if (IsExplosionPath(sample))
		return SoundVolumeGroup::Explosions;
	if (SoundPathStartsWith(sample, "player/tank/")
		|| SoundPathStartsWith(sample, "npc/tank/"))
		return SoundVolumeGroup::Tank;
	if (SoundPathStartsWith(sample, "npc/witch/"))
		return SoundVolumeGroup::Witch;
	if (IsSpecialInfectedPath(sample))
		return SoundVolumeGroup::SpecialInfected;
	if (SoundPathStartsWith(sample, "npc/infected/"))
		return SoundVolumeGroup::CommonInfected;
	if (IsVehiclePath(sample))
		return SoundVolumeGroup::Vehicles;
	if (SoundPathStartsWith(sample, "player/items/")
		|| SoundPathStartsWith(sample, "items/"))
		return SoundVolumeGroup::Items;
	if (SoundPathStartsWith(sample, "ui/")
		|| SoundPathStartsWith(sample, "buttons/"))
		return SoundVolumeGroup::Ui;
	if (SoundPathStartsWith(sample, "ambient/")
		|| SoundPathStartsWith(sample, "doors/")
		|| SoundPathStartsWith(sample, "physics/"))
		return SoundVolumeGroup::Ambient;
	return SoundVolumeGroup::None;
}

