// Remote-server only: defer vgui walks + entity HUD while pawn/observer settle after idle-swap.
static void IdleSwapHudClearQuiet() {
	g_idleSwapHudQuietUntil = 0;
}

bool IdleSwapHudQuietActive() {
	if (ListenIsHost()) return false;
	const DWORD until = g_idleSwapHudQuietUntil;
	if (!until) return false;
	const DWORD now = GetTickCount();
	if ((LONG)(now - until) >= 0) {
		IdleSwapHudClearQuiet();
		return false;
	}
	// Do not end early on one observer/team sample: remote idle/takeover snapshots can
	// flip several times while VGUI destroys and recreates survivor panels.
	return true;
}

static void IdleSwapHudBeginQuiet(const char* why, DWORD ms) {
	if (!why || !ms || ListenIsHost()) return;
	const DWORD now = GetTickCount();
	const bool alreadyQuiet = g_idleSwapHudQuietUntil
		&& (LONG)(now - g_idleSwapHudQuietUntil) < 0;
	// Remote servers can emit a burst of alternating replace events for one
	// transition. Coalesce the burst; synchronous logging here caused visible hitches.
	if (alreadyQuiet) return;
	g_idleSwapHudQuietUntil = now + ms;
	Log("idle-swap hud quiet max=%lums [%s] listen=0", (unsigned long)ms, why);
}

static void IdleSwapHudOnSwapEvent(const char* evName, int playerUid, int botUid) {
	if (ListenIsHost()) return; // remote server idle/takeover only
	if (!evName || (playerUid <= 0 && botUid <= 0)) return;
	if (g_localUserId <= 0)
		RefreshLocalUserId();
	if (g_localUserId <= 0 || (playerUid != g_localUserId && botUid != g_localUserId))
		return;
	const bool takeover = (evName[0] == 'b'); // bot_player_replace
	const DWORD ms = takeover ? 700u : 400u;
	IdleSwapHudBeginQuiet(evName, ms);
}

static void HudPostMissionQuietBegin(const char* why) {
	g_siPresenceResetPending.store(true, std::memory_order_release);
	g_hudTransitionQuiet.store(true, std::memory_order_relaxed);
	if (g_hudPostMissionQuiet) return;
	g_hudPostMissionQuiet = true;
	// The static crosshair is an ownerless topmost layered window.  Do not carry
	// that HWND across renderer/map transitions: its UI thread will release it
	// now, and XhairTick recreates it when the new map is no longer loading.
	XhairResetWindowOnBoundary();
	Log("hud post-mission quiet on [%s]", why ? why : "?");
}

static void HudPostMissionQuietClear(const char* why) {
	g_hudTransitionQuiet.store(false, std::memory_order_relaxed);
	if (!g_hudPostMissionQuiet) return;
	g_hudPostMissionQuiet = false;
	Log("hud post-mission quiet off [%s]", why ? why : "?");
}

static void HudMapEnterStableArm(const char* why) {
	g_localDebugHitboxesApplied = false;
	g_siPresenceResetPending.store(true, std::memory_order_release);
	if (g_optLaserRoundNotice) LaserRoundPost(1); // LevelInit also covers loads with no loading Paint.
	if (why && !strcmp(why, "LevelInit"))
		g_mapRoundStartSeen = false;
	else if (why && !strcmp(why, "round_start"))
		g_mapRoundStartSeen = true;
	g_levelInitResetRequestedAt.store(GetTickCount(), std::memory_order_relaxed);
	g_mapEnterGameThreadResetPending.store(true, std::memory_order_release);
	g_mapEnterCvarReapplyPending.store(true, std::memory_order_release);
	HudPostMissionQuietClear(why);
}

bool IdleSwapDeferEntityHud(bool menuPreview) {
	if (menuPreview) return false;
	if (g_hudPostMissionQuiet) return true;
	return IdleSwapHudQuietActive();
}

static bool HudVguiReady() {
	if (!g_ipanel)
		g_ipanel = GetIface("vgui2.dll", "VGUI_Panel009");
	if (!g_ipanel) return false;
	// Factory-owned interface; revalidate a changed vtable immediately, otherwise
	// at most once a second. No VirtualQuery chain for every parked panel/Paint.
	static void* s_iface = nullptr;
	static void* s_vtable = nullptr;
	static DWORD s_at = 0;
	const DWORD now = GetTickCount();
	__try {
		void* vt = *(void**)g_ipanel;
		if (s_iface == g_ipanel && s_vtable == vt && now - s_at < 1000u) return true;
		if (!IfaceAlive(g_ipanel)) return false;
		s_iface = g_ipanel; s_vtable = vt; s_at = now;
		return true;
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_hvPanelFaulted = true;
		return false;
	}
}

static void* HudVguiMethod(int slot) {
	// Observe the actual slot on every call so other plugins may replace it.
	// Executable-page validation is only repeated when its address changes.
	static void* s_methods[40]{};
	static bool s_valid[40]{};
	if (!g_ipanel || slot < 0 || slot >= 40) return nullptr;
	__try {
		void* fn = VGet(g_ipanel, slot);
		if (fn != s_methods[slot]) {
			s_methods[slot] = fn;
			s_valid[slot] = fn && IsExec(fn);
		}
		if (s_valid[slot]) return fn;
	} __except (EXCEPTION_EXECUTE_HANDLER) {}
	g_hvPanelFaulted = true;
	return nullptr;
}

// In-game vgui apply (SetVisible hide/show). Must not use g_paintInGame — HudHideTick runs before PaintCacheLocalPawn updates it.
static bool HudVguiApplyContextOk() {
	if (!HudVguiReady()) return false;
	if (!g_engine || !EngInGame() || EngDrawingLoading()) return false;
	return true;
}

// Heavy vgui tree walk (search/unpark): skip while SKT menu is painting on top.
static bool HudVguiTraverseContextOk() {
	if (!HudVguiApplyContextOk()) return false;
	if (g_menuVisible && !g_menuParked) return false;
	return true;
}

// Panel discovery may run while menu is open so toggling hide works immediately.
static bool HudVguiSearchContextOk() {
	return HudVguiApplyContextOk();
}

