static constexpr float kTongueCutFarRange = 600.f;
static constexpr float kTongueCutFarSpeed = 1000.f;
static constexpr float kTongueCutMediumEta = 0.300f;
static constexpr float kTongueCutPrepEstimate = 1.0f; // 中/远档发射前倒计时条的估算，发射后改实算
static constexpr float kTongueCutTrialTimeout = 4.0f;
static constexpr DWORD kTongueCutScanMs = 250;
static constexpr DWORD kTongueCutResultMs = 800;
static constexpr DWORD kTongueCutPulledMs = 500;
static constexpr DWORD kTongueCutEngageMs = 4000;
// CTongue::m_tongueState：server.dll 状态表 0x107b0ea0 起依次为
// IN_MOUTH / MISFIRE / EXTENDING / ATTACHED_TO_TARGET / DROPPING_TO_GROUND（0..4）。
static constexpr int kTongueStateInMouth = 0;
static constexpr int kTongueStateExtending = 2;
static constexpr int kTongueStateAttached = 3;
static constexpr DWORD kTongueCutFlowMs = 3000;     // 吐舌时距本次计时开始/提示不超过此值才算“本轮”
static constexpr float kTongueCutAimGraceSec = 0.3f; // 吐舌前 0.3s 内瞄着自己也算以自己为目标
static constexpr DWORD kTongueCutDodgeMinMs = 150;  // 躲开了：吐出到回嘴的合理窗口
static constexpr DWORD kTongueCutDodgeMaxMs = 3000;

