// L4D2: NUM_ENT_ENTRY_BITS=12 > mask 0xFFF, but only idx < MAX_EDICTS(2048) are networkable.
// A handle is index | serial << 12. The index alone can name a different entity after
// the slot is reused, so once IClientEntityList slot 4 (GetClientEntityFromHandle, one
// by-value handle argument) is proven against a live handle, lookups also check the
// serial. Until proven, or if it cannot be proven, the index-only behavior is kept.
// Proof and serial lookup run only on the game/Paint thread; every other thread keeps the
// index-only lookup and never touches this state. Unproven (0) retries every 250 ms;
// rejected (-1) is final until g_entlist changes.
static int g_handleLookupState = 0; // 0 not yet proven, 1 proven, -1 rejected
static DWORD g_handleLookupTryAt = 0;
static void* g_handleLookupList = nullptr;
static bool HandleLookupOnPaintThread() { return g_paintTid && GetCurrentThreadId() == g_paintTid; }

static void* EntFromHandleSlot(int h) {
	using Fn = void*(__thiscall*)(void*, int);
	return ((Fn)VGet(g_entlist, 4))(g_entlist, h);
}

// Game/Paint thread only. Needs a live local player for a real handle with a serial.
static void HandleLookupProve() {
	if (!g_entlist || !g_engine) return;
	const DWORD now = GetTickCount();
	if (g_handleLookupTryAt && now - g_handleLookupTryAt < 250u) return;
	g_handleLookupTryAt = now;
	if (!IfaceAlive(g_entlist) || !EngInGame() || EngDrawingLoading()) return;
	const int local = EngLocal();
	if (local <= 0 || local >= 2048) return;
	void* e = EntGet(local);
	if (!e || !EntReadable(e)) return;
	using GetRef = const unsigned long*(__thiscall*)(void*);
	auto getRef = (GetRef)VGet(e, 2); // IHandleEntity::GetRefEHandle
	if (!getRef || !IsExec((void*)getRef)) return;
	const unsigned long* ph = getRef(e);
	int h = 0;
	if (!ph || !EntRead(ph, 0, &h)) return;
	if (h == 0 || h == -1 || (h & 0xFFF) != local || ((unsigned)h >> 12) == 0) return;
	void* slot = VGet(g_entlist, 4);
	if (!slot || !IsExec(slot)) { g_handleLookupState = -1; return; }
	const bool ok = EntFromHandleSlot(h) == e
		&& EntFromHandleSlot(h ^ 0x1000) == nullptr
		&& EntFromHandleSlot(-1) == nullptr;
	g_handleLookupState = ok ? 1 : -1;
	Log("handle lookup: IClientEntityList slot 4 %s (local=%d handle=0x%X)",
		ok ? "verified, serial check on" : "rejected, index-only kept", local, (unsigned)h);
}

// True when the serial-checked slot may be used on this call.
static bool HandleLookupUsable() {
	if (!HandleLookupOnPaintThread()) return false;
	if (g_handleLookupList != g_entlist) {
		g_handleLookupList = g_entlist;
		g_handleLookupState = 0;
		g_handleLookupTryAt = 0;
	}
	if (g_handleLookupState == 0) HandleLookupProve();
	return g_handleLookupState == 1;
}

void* EntFromHandle(int h) {
	if (h == 0 || h == -1) return nullptr;
	const int idx = h & 0xFFF;
	if (idx <= 0 || idx >= 2048) return nullptr;
	if (HandleLookupUsable()) return EntFromHandleSlot(h);
	return EntGet(idx);
}

int EntIndexFromHandle(int h) {
	if (h == 0 || h == -1) return 0;
	const int idx = h & 0xFFF;
	if (idx <= 0 || idx >= 2048) return 0;
	if (HandleLookupUsable() && !EntFromHandleSlot(h)) return 0;
	return idx;
}









