using WeaponInfoFn = void*(__cdecl*)(unsigned short);
static WeaponInfoFn g_weaponInfoFn = nullptr;

static void WeaponCapacityResolve() {
	// Cold startup only. Current x86 client c0a8e1e...af1f: the native
	// GetWeaponData entry may be detoured by other plugins. Its sibling getter
	// still proves handle +9da and calls the same cdecl FileWeaponInfo lookup.
	// Parse confirms clip_size at +160; never guess a GetMaxClip1 vtable slot.
	uintptr_t getter[2]{}, parser[2]{};
	const int g = CountPat("client.dll", "0F B7 81 DA 09 00 00 50 E8 ?? ?? ?? ?? 83 C4 04 05 A6 00 00 00 C2 04 00", getter, 2);
	const int p = CountPat("client.dll", "68 ?? ?? ?? ?? 8B CF E8 ?? ?? ?? ?? 6A FF 68 ?? ?? ?? ?? 8B CF 89 86 60 01 00 00 E8 ?? ?? ?? ?? 89 86 64 01 00 00", parser, 2);
	const char* key = nullptr; char text[16]{}; int relative = 0;
	if (g == 1 && p == 1 && skmem::Copy(&key, (void*)(parser[0] + 1), sizeof(key))
		&& skmem::CopyCStr(text, sizeof(text), key) && !strcmp(text, "clip_size")
		&& skmem::Copy(&relative, (void*)(getter[0] + 9), sizeof(relative))) {
		const uintptr_t lookup = getter[0] + 13 + relative;
		const unsigned char expected[] = {0x55,0x8b,0xec,0x66,0x8b,0x45,0x08};
		unsigned char body[sizeof(expected)]{};
		if (skmem::Copy(body, (void*)lookup, sizeof(body)) && !memcmp(body, expected, sizeof(body)))
			g_weaponInfoFn = (WeaponInfoFn)lookup;
	}
	Log("weapon capacity: native script lookup=%p; missing/invalid data uses vanilla fallback", (void*)g_weaponInfoFn);
}

// Weapon clip capacity sampling begin
static bool WeaponHasDualPistols(void* weapon) {
	uint8_t dual = 0;
	return g_offHasDualWeapons >= 0 && EntRead(weapon, g_offHasDualWeapons, &dual) && dual != 0;
}

static int WeaponClipCapacity(void* weapon, int kind) {
	// Paint/CreateMove game thread, O(1): native table lookup + bounded reads.
	// No IO, allocation, scan or per-entity cache; UI workers only see snapshots.
	int capacity = 0;
	// Existing ListenPump publishes host status independently of local options.
	// Remote servers do not replicate script clip_size: preserve vanilla limits.
	if (g_weaponInfoFn && g_listenHost.load(std::memory_order_relaxed)) {
		void* info = nullptr; unsigned short handle = 0xffff;
		if (!EntRead(weapon, 0x9da, &handle)) return TeamHudGunMaxClipKind(kind);
		__try { info = g_weaponInfoFn(handle); }
		__except (EXCEPTION_EXECUTE_HANDLER) {
			g_weaponInfoFn = nullptr;
			Log("weapon capacity: native lookup fault; disabled, using vanilla fallback");
		}
		if (!EntRead(info, 0x160, &capacity) || capacity < 1 || capacity > 65535) capacity = 0;
	}
	if (!capacity) capacity = TeamHudGunMaxClipKind(kind);
	if (kind == TW_Pistol && WeaponHasDualPistols(weapon)) capacity *= 2;
	return capacity;
}
// Weapon clip capacity sampling end

bool WeaponEntHasDualPistols(int index) {
	if (index <= 0 || index >= 2048) return false;
	return WeaponHasDualPistols(EntGet(index));
}

int WepClipCapResolve(int wepIdx, int /*clip*/) {
	if (wepIdx <= 0 || wepIdx >= 2048) return 0;
	void* weapon = EntGet(wepIdx);
	if (!EntReadable(weapon)) return 0;
	const int kind = TeamHudWepKindCorrected(wepIdx, EntNetClassName(wepIdx));
	return WeaponClipCapacity(weapon, kind);
}



