// Never wipe+recreate when full: that leaked CreateNewTextureID calls in Paint and
// matched "teamhud on > multiplayer play a while > crash" (solo sees fewer unique mats).
HudMatCache g_hudMat[kHudMatMax]{};
int g_hudMatN = 0;
static DWORD g_hudMatHealthAt = 0;
static int g_hudMatHealthCursor = 0;
// SurfHudMat/SurfHudMatSize are called many times per rendered TeamHud frame.
// A plain linear lookup therefore became progressively more expensive as new
// weapon/mod materials accumulated across chapters. These direct-mapped hints
// keep the common path O(1); collisions safely fall back to the bounded table.
static int g_hudMatNameHot[kHudMatMax]{}; // cache index + 1
static int g_hudMatIdHot[kHudMatMax]{};   // cache index + 1

static unsigned HudMatNameHash(const char* s) {
	unsigned h = 2166136261u;
	for (; s && *s; ++s) {
		unsigned char c = (unsigned char)*s;
		if (c >= 'A' && c <= 'Z') c = (unsigned char)(c - 'A' + 'a');
		h = (h ^ c) * 16777619u;
	}
	return h;
}

static void HudMatIndexOne(int i) {
	if (i < 0 || i >= g_hudMatN) return;
	g_hudMatNameHot[HudMatNameHash(g_hudMat[i].name) & (kHudMatMax - 1)] = i + 1;
	if (g_hudMat[i].id >= 0)
		g_hudMatIdHot[(unsigned)g_hudMat[i].id & (kHudMatMax - 1)] = i + 1;
}

void HudMatRebuildHot() {
	memset(g_hudMatNameHot, 0, sizeof(g_hudMatNameHot));
	memset(g_hudMatIdHot, 0, sizeof(g_hudMatIdHot));
	for (int i = 0; i < g_hudMatN; ++i) HudMatIndexOne(i);
}

// Crashguard: verified x86 startup patches, immutable launch choices, explicit diagnostics.
// Binary constants stay valid without this DLL. The temporary index-init detour removes
// itself on its first native call; never resize a live GPU buffer or patch from Event/recv.
struct CrashGuardPatch {
	void* address;
	unsigned char before[8], after[8];
	size_t length;
	DWORD protection;
	bool writable;
};
struct CrashGuardCommitResult { bool committed; bool protectionWarning; };
static bool CrashGuardReadable(const void* address, size_t length) {
	if (!address || !length) return false;
	MEMORY_BASIC_INFORMATION info{};
	if (!skmem::Query(address, &info, (uintptr_t)_ReturnAddress()) || info.State != MEM_COMMIT
		|| (info.Protect & (PAGE_NOACCESS | PAGE_GUARD))) return false;
	const uintptr_t start = reinterpret_cast<uintptr_t>(address);
	const uintptr_t region = reinterpret_cast<uintptr_t>(info.BaseAddress);
	return start >= region && start - region <= info.RegionSize
		&& length <= info.RegionSize - (start - region);
}
static void CrashGuardChange(CrashGuardPatch& change, void* address, unsigned before, unsigned after, size_t length) {
	change = {};
	change.address = address;
	change.length = length <= sizeof(unsigned) ? length : 0;
	memcpy(change.before, &before, change.length);
	memcpy(change.after, &after, change.length);
}
static CrashGuardCommitResult CrashGuardCommit(CrashGuardPatch* changes, int count) {
	if (!changes || count < 1 || count > 12) return {};
	bool ok = false;
	bool protectionsRestored = true;
	int written = 0;
	__try {
		for (int i = 0; i < count; ++i) {
			auto& c = changes[i];
			c.writable = false;
			if (!c.length || c.length > sizeof(c.before) || !CrashGuardReadable(c.address, c.length)
				|| memcmp(c.address, c.before, c.length)) return {};
		}
		bool protectedAll = true;
		for (int i = 0; i < count; ++i) {
			auto& c = changes[i];
			if (!memcmp(c.before, c.after, c.length)) continue;
			if (!VirtualProtect(c.address, c.length, PAGE_EXECUTE_READWRITE, &c.protection)) {
				protectedAll = false; break;
			}
			c.writable = true;
		}
		if (protectedAll) {
			for (int i = 0; i < count; ++i)
				if (memcmp(changes[i].address, changes[i].before, changes[i].length)) protectedAll = false;
		}
		if (protectedAll) {
			for (int i = 0; i < count; ++i) {
				if (changes[i].writable) memcpy(changes[i].address, changes[i].after, changes[i].length);
				written = i + 1;
			}
			ok = true;
		}
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		for (int i = written - 1; i >= 0; --i) {
			auto& c = changes[i];
			if (c.writable && CrashGuardReadable(c.address, c.length)
				&& !memcmp(c.address, c.after, c.length)) memcpy(c.address, c.before, c.length);
		}
	}
	// Reverse order also restores the original protection when several changes share a page.
	SYSTEM_INFO systemInfo{};
	GetSystemInfo(&systemInfo);
	const uintptr_t pageSize = systemInfo.dwPageSize ? systemInfo.dwPageSize : 4096u;
	const uintptr_t pageMask = ~(pageSize - 1u);
	for (int i = count - 1; i >= 0; --i) {
		auto& c = changes[i];
		if (!c.writable) continue;
		const uintptr_t page = reinterpret_cast<uintptr_t>(c.address) & pageMask;
		bool hasEarlierChangeOnPage = false;
		for (int j = 0; j < i; ++j) {
			if (changes[j].writable && (reinterpret_cast<uintptr_t>(changes[j].address) & pageMask) == page) {
				hasEarlierChangeOnPage = true;
				break;
			}
		}
		if (hasEarlierChangeOnPage) { c.writable = false; continue; }
		FlushInstructionCache(GetCurrentProcess(), c.address, c.length);
		DWORD unused = 0;
		if (!VirtualProtect(c.address, c.length, c.protection, &unused)
			&& !VirtualProtect(c.address, c.length, c.protection, &unused)) protectionsRestored = false;
		for (int j = 0; j < count; ++j)
			if ((reinterpret_cast<uintptr_t>(changes[j].address) & pageMask) == page) changes[j].writable = false;
	}
	return {ok, !protectionsRestored};
}
static int CrashGuardNormalize(int value, bool cache) {
	if (cache) return value == 512 || value == 1024 || value == 2048 ? value : 0;
	return value == 32768 || value == 65535 || value == 131072 ? value : 0;
}
enum CrashGuardState {
	kCrashGuardNoChange, kCrashGuardPending, kCrashGuardArmed, kCrashGuardApplied,
	kCrashGuardUnsupported, kCrashGuardConflict, kCrashGuardLate, kCrashGuardFailed
};
static std::atomic<int> g_crashGuardCacheState{kCrashGuardNoChange}, g_crashGuardIndexState{kCrashGuardNoChange};
static std::atomic_bool g_crashGuardCacheProtectionWarning{false}, g_crashGuardIndexProtectionWarning{false};
static int g_crashGuardLaunchCacheMb = 0, g_crashGuardLaunchIndexCount = 0;
static DWORD g_crashGuardStartedAt = 0, g_crashGuardCacheTryAt = 0;
static std::atomic_bool g_crashGuardStatusRequested{false};
static HMODULE g_crashGuardShader = nullptr;
using CrashGuardIndexInitFn = void(__thiscall*)(void*);
static CrashGuardIndexInitFn g_crashGuardIndexInit = nullptr;
static CrashGuardPatch g_crashGuardIndexEntry{};
static std::atomic_bool g_crashGuardIndexEntryOwned{false};
static bool CrashGuardModule(HMODULE module, DWORD timestamp, DWORD imageSize) {
	if (!CrashGuardReadable(module, sizeof(IMAGE_DOS_HEADER))) return false;
	__try {
		const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(module);
		if (dos->e_magic != IMAGE_DOS_SIGNATURE || dos->e_lfanew < 0 || dos->e_lfanew > 4096) return false;
		const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS*>(reinterpret_cast<const unsigned char*>(module) + dos->e_lfanew);
		return CrashGuardReadable(nt, sizeof(*nt)) && nt->Signature == IMAGE_NT_SIGNATURE
			&& nt->FileHeader.Machine == IMAGE_FILE_MACHINE_I386
			&& nt->OptionalHeader.Magic == IMAGE_NT_OPTIONAL_HDR32_MAGIC
			&& nt->FileHeader.TimeDateStamp == timestamp && nt->OptionalHeader.SizeOfImage == imageSize;
	} __except (EXCEPTION_EXECUTE_HANDLER) { return false; }
}
static int CrashGuardShaderDelta(HMODULE module) {
	if (CrashGuardModule(module, 0x6A440E0A, 0xFF000)) return 0;
	if (CrashGuardModule(module, 0x6A440DF3, 0xFF000)) return -32;
	return 1; // Unsupported; never treat a failed check as the DX9 offsets.
}
static bool CrashGuardBytes(const void* address, const unsigned char* bytes, size_t length) {
	return CrashGuardReadable(address, length) && memcmp(address, bytes, length) == 0;
}
static bool CrashGuardIndexLayout(HMODULE module, int delta) {
	if (delta == 1) return false;
	auto* base = reinterpret_cast<unsigned char*>(module);
	static const unsigned char ctor[] = {0x53,0x56,0x8B,0xF1,0x57,0x8D,0x4E,0x04,0xC7,0x06};
	static const unsigned char call[] = {0x0F,0xB6,0xC0,0x50,0x68};
	static const unsigned char count[] = {0xC7,0x86,0xC8,0x03,0,0};
	static const unsigned char bytes[] = {0xC7,0x86,0xCC,0x03,0,0};
	return CrashGuardBytes(base + 0xD9F0 + delta, ctor, sizeof(ctor))
		&& CrashGuardBytes(base + 0xCCD1 + delta, call, sizeof(call))
		&& CrashGuardBytes(base + 0xDB24 + delta, count, sizeof(count))
		&& CrashGuardBytes(base + 0xDB1A + delta, bytes, sizeof(bytes))
		&& base[0x8D70 + delta] == 0xB8 && base[0x8D75 + delta] == 0xC3
		&& *reinterpret_cast<uintptr_t*>(base + 0xCE488) == *reinterpret_cast<uintptr_t*>(base + 0xD9FA + delta);
}
static void CrashGuardRestoreIndexEntry() {
	if (!g_crashGuardIndexEntryOwned.load(std::memory_order_acquire)) return;
	CrashGuardPatch restore = g_crashGuardIndexEntry;
	memcpy(restore.before, g_crashGuardIndexEntry.after, restore.length);
	memcpy(restore.after, g_crashGuardIndexEntry.before, restore.length);
	const auto result = CrashGuardCommit(&restore, 1);
	if (result.protectionWarning) g_crashGuardIndexProtectionWarning.store(true, std::memory_order_release);
	if (result.committed) g_crashGuardIndexEntryOwned.store(false, std::memory_order_release);
}
static void __fastcall CrashGuardIndexInitHook(void* object, void*) {
	// Runs in the game's native renderer initialization, before original Init allocates buffers.
	// CAS handles device-reset/reentrant calls even if restoring the prologue is refused.
	int armed = kCrashGuardArmed;
	if (g_crashGuardIndexState.compare_exchange_strong(armed, kCrashGuardPending, std::memory_order_acq_rel)) {
		int state = kCrashGuardConflict;
		__try {
			auto* base = reinterpret_cast<unsigned char*>(g_crashGuardShader);
			const int d = CrashGuardShaderDelta(g_crashGuardShader);
			if (CrashGuardIndexLayout(g_crashGuardShader, d) && object == base + 0xCE488) {
				auto* mesh = static_cast<unsigned char*>(object);
				if (*reinterpret_cast<void**>(mesh + 0x1EC) || *reinterpret_cast<void**>(mesh + 0x3C0)
					|| *reinterpret_cast<void**>(mesh + 0x3C4)) state = kCrashGuardLate;
				else {
					const unsigned count = (static_cast<unsigned>(g_crashGuardLaunchIndexCount) + 1u) & ~1u;
					CrashGuardPatch changes[6]{};
					CrashGuardChange(changes[0], base + 0x8D71 + d, 32768, count, 4);
					CrashGuardChange(changes[1], base + 0xCCD6 + d, 32768, count, 4);
					CrashGuardChange(changes[2], base + 0xDB2A + d, 32768, count, 4);
					CrashGuardChange(changes[3], base + 0xDB20 + d, 65536, count * 2u, 4);
					// The embedded object was already constructed by the DLL's CRT; no GPU/CPU buffer exists yet.
					CrashGuardChange(changes[4], mesh + 0x3C8, 32768, count, 4);
					CrashGuardChange(changes[5], mesh + 0x3CC, 65536, count * 2u, 4);
					const auto result = CrashGuardCommit(changes, 6);
					if (result.protectionWarning) g_crashGuardIndexProtectionWarning.store(true, std::memory_order_release);
					state = result.committed ? kCrashGuardApplied : kCrashGuardFailed;
				}
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) { state = kCrashGuardFailed; }
		g_crashGuardIndexState.store(state, std::memory_order_release);
	}
	CrashGuardRestoreIndexEntry();
	if (g_crashGuardIndexInit) g_crashGuardIndexInit(object);
}
static void CrashGuardBootstrap() {
	g_crashGuardLaunchCacheMb = g_optCrashGuardCacheMb;
	g_crashGuardLaunchIndexCount = g_optCrashGuardIndexCount;
	g_crashGuardStartedAt = GetTickCount();
	if (g_crashGuardLaunchCacheMb) g_crashGuardCacheState.store(kCrashGuardPending, std::memory_order_release);
	if (!g_crashGuardLaunchIndexCount) return; // No loading, scanning, patching or Hook at "No change".
	g_crashGuardIndexState.store(kCrashGuardUnsupported, std::memory_order_release);
	const char* name = CmdLineHasFlag("-vulkan") ? "shaderapivk.dll" : "shaderapidx9.dll";
	g_crashGuardShader = GetModuleHandleA(name);
	// Never load a renderer on this worker: CShaderDeviceBase's CRT constructor records
	// the loading thread as device owner. Preloading here makes native main-thread events
	// requeue indefinitely (confirmed in the two 2026-10-07 startup OOM dumps).
	// Wait only for the game's normal loader. No Source interfaces, extra thread or IO.
	const DWORD waitStarted = GetTickCount();
	while (!g_crashGuardShader && g_run.load(std::memory_order_relaxed)
		&& GetTickCount() - waitStarted < 15000u) {
		Sleep(1);
		g_crashGuardShader = GetModuleHandleA(name);
	}
	Log("crashguard: native backend=%s module=%p wait=%lu ms worker=%lu requested=%d",
		name, g_crashGuardShader, GetTickCount() - waitStarted, GetCurrentThreadId(), g_crashGuardLaunchIndexCount);
	const int d = CrashGuardShaderDelta(g_crashGuardShader);
	if (d == 1) return;
	g_crashGuardIndexState.store(kCrashGuardConflict, std::memory_order_release);
	__try {
		auto* base = reinterpret_cast<unsigned char*>(g_crashGuardShader);
		auto* mesh = base + 0xCE488;
		// GetModuleHandle may see the image before its CRT has constructed CMeshMgr.
		// A zero vtable is still loading, not evidence of another platform's patch.
		// Wait for the original constructor; never patch a half-constructed instance.
		while (!*reinterpret_cast<volatile uintptr_t*>(mesh) && g_run.load(std::memory_order_relaxed)
			&& GetTickCount() - waitStarted < 15000u) Sleep(1);
		if (!CrashGuardIndexLayout(g_crashGuardShader, d)) {
			Log("crashguard: index layout refused live-vtable=%p ctor-vtable=%p wait=%lu ms",
				*reinterpret_cast<void**>(mesh), *reinterpret_cast<void**>(base + 0xD9FA + d), GetTickCount() - waitStarted);
			return;
		}
		if (*reinterpret_cast<void**>(mesh + 0x1EC) || *reinterpret_cast<void**>(mesh + 0x3C0)
			|| *reinterpret_cast<void**>(mesh + 0x3C4)) {
			g_crashGuardIndexState.store(kCrashGuardLate, std::memory_order_release); return;
		}
		static const unsigned char prologue[] = {0x56,0x8B,0xF1,0x57,0x6A,0x24};
		auto* entry = base + 0xCC90 + d;
		if (!CrashGuardBytes(entry, prologue, sizeof(prologue))) {
			Log("crashguard: index Init entry differs from original; skip"); return;
		}
		auto* trampoline = static_cast<unsigned char*>(VirtualAlloc(nullptr, 11, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE));
		if (!trampoline) { g_crashGuardIndexState.store(kCrashGuardFailed, std::memory_order_release); return; }
		memcpy(trampoline, prologue, 6);
		trampoline[6] = 0xE9;
		const uintptr_t returnJump = reinterpret_cast<uintptr_t>(entry + 6) - reinterpret_cast<uintptr_t>(trampoline + 11);
		memcpy(trampoline + 7, &returnJump, 4);
		DWORD previous = 0;
		if (!VirtualProtect(trampoline, 11, PAGE_EXECUTE_READ, &previous)) {
			VirtualFree(trampoline, 0, MEM_RELEASE);
			g_crashGuardIndexState.store(kCrashGuardFailed, std::memory_order_release); return;
		}
		FlushInstructionCache(GetCurrentProcess(), trampoline, 11);
		g_crashGuardIndexInit = reinterpret_cast<CrashGuardIndexInitFn>(trampoline);
		g_crashGuardIndexEntry = {};
		g_crashGuardIndexEntry.address = entry;
		g_crashGuardIndexEntry.length = 6;
		memcpy(g_crashGuardIndexEntry.before, prologue, 6);
		g_crashGuardIndexEntry.after[0] = 0xE9;
		const uintptr_t detourJump = reinterpret_cast<uintptr_t>(&CrashGuardIndexInitHook) - reinterpret_cast<uintptr_t>(entry + 5);
		memcpy(g_crashGuardIndexEntry.after + 1, &detourJump, 4);
		g_crashGuardIndexEntry.after[5] = 0x90;
		g_crashGuardIndexEntryOwned.store(true, std::memory_order_release);
		g_crashGuardIndexState.store(kCrashGuardArmed, std::memory_order_release);
		CrashGuardPatch install = g_crashGuardIndexEntry; // Keep the published entry bytes immutable for the native caller.
		const auto installResult = CrashGuardCommit(&install, 1);
		if (installResult.protectionWarning) g_crashGuardIndexProtectionWarning.store(true, std::memory_order_release);
		if (!installResult.committed) {
			// A protection-restore failure may still have installed our bytes; retain the valid trampoline.
			CrashGuardRestoreIndexEntry();
			g_crashGuardIndexState.store(kCrashGuardFailed, std::memory_order_release);
		}
	} __except (EXCEPTION_EXECUTE_HANDLER) { g_crashGuardIndexState.store(kCrashGuardFailed, std::memory_order_release); }
	Log("crashguard: index startup state=%d", g_crashGuardIndexState.load(std::memory_order_acquire));
}
static int CrashGuardApplyCache() {
	if (!g_cvar) return kCrashGuardPending;
	const HMODULE module = GetModuleHandleA("datacache.dll");
	if (!module) return kCrashGuardPending;
	if (!CrashGuardModule(module, 0x6A440DAD, 0x49000)) return kCrashGuardUnsupported;
	unsigned used = 0, limit = 0;
	if (!MemoryHudReadDc(&used, &limit)) return kCrashGuardPending;
	__try {
		auto* base = reinterpret_cast<unsigned char*>(module);
		void* root = CvarParent(CvarFind("datacachesize"));
		static const unsigned char arithmetic[] = {0x99,0x81,0xE2,0xFF,0xFF,0x0F,0,0x03,0xC2,0xC1,0xF8,0x14};
		static const unsigned char setter[] = {0x55,0x8B,0xEC,0x56,0x57,0x8B,0x7D,0x08,0x8D,0x71,0x08};
		static const unsigned char callback[] = {0x55,0x8B,0xEC,0x83,0xEC,0x08,0x8B,0x45,0x08,0x50,0x8D,0x4D,0xF8};
		if (root != base + 0x3D858 || !CrashGuardReadable(root, 0x48)
			|| *reinterpret_cast<void**>(base + 0x3D89C) != base + 0x18E0
			|| !CrashGuardBytes(base + 0x1402, arithmetic, sizeof(arithmetic))
			|| !CrashGuardBytes(base + 0x1924, arithmetic, sizeof(arithmetic))
			|| !CrashGuardBytes(base + 0x13E0, setter, sizeof(setter))
			|| !CrashGuardBytes(base + 0x18E0, callback, sizeof(callback))) return kCrashGuardConflict;
		void* cache = GetIface("datacache.dll", "VDataCache003");
		if (!IfaceAlive(cache) || VGet(cache, 5) != base + 0x13E0) return kCrashGuardConflict;
		CrashGuardPatch changes[4]{};
		const float wanted = static_cast<float>(g_crashGuardLaunchCacheMb);
		unsigned newMax = 0; memcpy(&newMax, &wanted, 4);
		CrashGuardChange(changes[0], base + 0x2A7FC, 0x44000000u, newMax, 4); // 512.0f
		CrashGuardChange(changes[1], base + 0x3D898, 0x44000000u, newMax, 4); // ConVar maximum
		const unsigned shift = g_crashGuardLaunchCacheMb == 2048 ? 0xE8u : 0xF8u;
		// Preserve native rounding and -1 sentinel; use logical SHR for unsigned 2GiB budgets.
		CrashGuardChange(changes[2], base + 0x140C, 0xF8, shift, 1);
		CrashGuardChange(changes[3], base + 0x192E, 0xF8, shift, 1);
		const auto result = CrashGuardCommit(changes, 4);
		if (result.protectionWarning) g_crashGuardCacheProtectionWarning.store(true, std::memory_order_release);
		if (!result.committed) return kCrashGuardFailed;
		const unsigned bytes = static_cast<unsigned>(g_crashGuardLaunchCacheMb) << 20;
		int signedBytes = 0; memcpy(&signedBytes, &bytes, sizeof(bytes));
		using SetSizeFn = void(__thiscall*)(void*, int);
		reinterpret_cast<SetSizeFn>(base + 0x13E0)(cache, signedBytes);
		// Native SetSize also updates the ConVar string/value via its own callback, once.
		return MemoryHudReadDc(&used, &limit) && limit == bytes
			&& *reinterpret_cast<int*>(base + 0x3D888) == g_crashGuardLaunchCacheMb
			? kCrashGuardApplied : kCrashGuardFailed;
	} __except (EXCEPTION_EXECUTE_HANDLER) { return kCrashGuardFailed; }
}
static const wchar_t* CrashGuardStateName(int state) {
	switch (state) {
	case kCrashGuardNoChange: return UiText(UiId::CrashGuardNoChange, L"不改");
	case kCrashGuardPending: return UiText(UiId::CrashGuardPending, L"等待启动应用");
	case kCrashGuardArmed: return UiText(UiId::CrashGuardArmed, L"等待原生初始化");
	case kCrashGuardApplied: return UiText(UiId::CrashGuardApplied, L"已应用");
	case kCrashGuardUnsupported: return UiText(UiId::CrashGuardUnsupported, L"游戏 DLL 版本不匹配，未修改");
	case kCrashGuardConflict: return UiText(UiId::CrashGuardConflict, L"原始状态不匹配，已跳过");
	case kCrashGuardLate: return UiText(UiId::CrashGuardLate, L"缓冲区已初始化，已跳过");
	default: return UiText(UiId::CrashGuardFailed, L"应用或核验失败");
	}
}
static void CrashGuardFormatState(int state, bool protectionWarning, wchar_t* output, size_t capacity) {
	const wchar_t* name = CrashGuardStateName(state);
	if (protectionWarning)
		swprintf_s(output, capacity, UiText(UiId::CrashGuardProtectionWarningFormat,
			L"%s（恢复内存页原权限失败，请检查并重启游戏）"), name);
	else wcscpy_s(output, capacity, name);
}
static void CrashGuardEcho(const wchar_t* text) {
	char utf8[1536]{};
	if (WideCharToMultiByte(CP_UTF8, 0, text, -1, utf8, sizeof(utf8), nullptr, nullptr)) ConEcho(utf8);
}
static const wchar_t* CacheOffloadStateName(skeeto_cache::Status status) {
	switch(status) {
	case skeeto_cache::Status::Off: return UiText(UiId::CacheOffloadOff,L"未启用");
	case skeeto_cache::Status::Starting: return UiText(UiId::CacheOffloadStarting,L"等待缓存接口");
	case skeeto_cache::Status::Ready: return UiText(UiId::CacheOffloadReady,L"已启用");
	case skeeto_cache::Status::Unsupported: return UiText(UiId::CacheOffloadUnsupported,L"游戏 DLL 版本不匹配，未启用");
	case skeeto_cache::Status::Conflict: return UiText(UiId::CacheOffloadConflict,L"检测到缓存接口改动，已停止搬运");
	case skeeto_cache::Status::HostFailed: return UiText(UiId::CacheOffloadHostFailed,L"辅助进程不可用，已停止搬运");
	default: return UiText(UiId::CacheOffloadFailed,L"初始化失败，未启用");
	}
}
static void CacheOffloadReport() {
	const auto s=skeeto_cache::ReadSnapshot();
	wchar_t text[384]{};
	swprintf_s(text,UiText(UiId::CacheOffloadReportLaunch,L"缓存搬运: 保存=%d, 本次启动=%d, 状态=%s"),
		g_optCacheOffload?1:0,g_cacheOffloadLaunch?1:0,CacheOffloadStateName(s.status));
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportBytes,L"当前外置=%u 项 / %.2f MB; 模型=%.2f MB, 动画=%.2f MB, 声音=%.2f MB"),
		s.coldItems,(s.meshBytes+s.animationBytes+s.audioBytes)/1048576.0,s.meshBytes/1048576.0,s.animationBytes/1048576.0,s.audioBytes/1048576.0);
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportHost,L"辅助进程 PID=%u, 实际映射=%.1f MB, 正在搬运=%u 项 / %.1f MB"),s.hostPid,s.hostBytes/1048576.0,s.pendingItems,s.pendingBytes/1048576.0);
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportCounts,L"取回=%u 次, 失败=%u 次, 保护不足保留=%u 项, 累计回收=%.2f MB"),s.restores,s.failures,s.unsafeItems,s.reclaimedBytes/1048576.0);
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportHistory,L"本次启动: 累计搬出=%.2f MB / %u 次, 外置峰值=%.2f MB"),s.movedBytes/1048576.0,s.moves,s.peakColdBytes/1048576.0);
	CrashGuardEcho(text);
	const wchar_t* names[3]{UiText(UiId::CacheOffloadModel,L"模型"),UiText(UiId::CacheOffloadAnimation,L"动画"),UiText(UiId::CacheOffloadSound,L"声音")};
	for(int i=0;i<3;++i){
		swprintf_s(text,UiText(UiId::CacheOffloadReportSource,L"%s: 接入=%d, 源缓存=%.2f MB, 锁定采样=%.2f MB / %u 项, 跟踪=%u 项, 保护不足保留=%u 项"),
			names[i],(s.boundMask&(1u<<i))?1:0,s.residentBytes[i]/1048576.0,s.lockedBytes[i]/1048576.0,s.lockedItems[i],s.trackedItems[i],s.unsafePerKind[i]);
		CrashGuardEcho(text);
		swprintf_s(text,UiText(UiId::CacheOffloadReportRetained,L"%s: 近期访问=%.2f MB, 保护不足保留=%.2f MB, 旧动画池=%.2f MB; 原生锁定累计字段=%u 字节 / %u 项"),
			names[i],s.idleBytes[i]/1048576.0,s.unsafeBytes[i]/1048576.0,s.slabBytes[i]/1048576.0,s.rawLockedBytes[i],s.rawLockedItems[i]);
		CrashGuardEcho(text);
	}
	swprintf_s(text,UiText(UiId::CacheOffloadReportAudio,L"声音 DLL 核验=%d, 动画可释放页分配=%d; 当前闲置门槛=%u 秒，仅允许释放已核验的模型自身缓存锁"),s.audioVerified?1:0,s.independentAnimations?1:0,s.idleMs/1000u);
	CrashGuardEcho(text);
	CrashGuardEcho(UiText(UiId::CacheOffloadReportSchedule,L"搬运调度: 最多 16 项在途，每次维护总复制 512 KB、预算 0.5 ms（单次系统操作可能超出）；进图前 30 秒按闲置 3 秒挑选，之后恢复 10 秒。进图加速、在途搬运和主动回收逐 Paint 推进，其余巡检最多 20 Hz；辅助进程按事件唤醒。"));
	swprintf_s(text,UiText(UiId::CacheOffloadReportAudioHistory,L"声音 WaveData: 外置峰值=%.2f MB, 累计搬出=%.2f MB, 累计取回=%.2f MB, 状态查询=%u 次（外置时=%u 次）；只统计本分区，不代表全部声音内存。"),s.audioPeakBytes/1048576.0,s.audioMovedBytes/1048576.0,s.audioRestoredBytes/1048576.0,s.audioMetadataChecks,s.audioColdMetadataChecks);
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportVa,L"独立缓冲占用 VA=%.2f MB, 搬出累计实际释放 VA=%.2f MB, 分配/释放失败=%u; 累计释放可重复，不是 AV 净增量，也不包含原生堆释放。"),
		s.bufferVaBytes/1048576.0,s.moveReleasedVaBytes/1048576.0,s.bufferFailures);
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportMeshPin,L"模型自身缓存锁释放=%u 次, 帧结束提交=%u 次, 帧结束提交峰值=%.3f ms; 其他锁和裸指针仍保留。"),
		s.meshPinReleases,s.meshDeferredCommits,s.meshCommitPeakMs);
	CrashGuardEcho(text);
	swprintf_s(text,UiText(UiId::CacheOffloadReportInventory,L"锁定采样有效=%d, 巡检周期=%u ms（跨帧，不是 CPU 耗时）；逐条采样，非同时快照。保护不足含裸指针和接入前未知条目；保留原因可以重叠。"),s.inventoryReady?1:0,s.inventoryCycleMs);
	CrashGuardEcho(text);
	if(s.timing){
		swprintf_s(text,UiText(UiId::CacheOffloadReportTiming,L"HUD 计时: 最近窗口维护均值/峰值=%.3f/%.3f ms, 本次启动观测取回峰值=%.3f ms"),s.maintenanceAvgMs,s.maintenancePeakMs,s.restorePeakMs);
		CrashGuardEcho(text);
	}
	CrashGuardEcho(UiText(UiId::CacheOffloadTimingHint,L"维护计时只含本模块 Paint 工作；取回计时含映射、分配和复制，不含完整帧或其他 Hook/宿主开销。HUD 关闭或隐藏时停止计时。"));
	CrashGuardEcho(UiText(UiId::CacheOffloadMeasureHint,L"当前外置是此刻未取回的数据；VA释放累计只统计搬出时实际归还的独立页，允许重复，不等于 AV 净节省。回收是主动丢弃外置项，另行计数。其他锁、裸指针、旧动画池和不支持的资源仍留在游戏。"));
}
static void CacheOffloadGamePump() {
	if(!g_run.load(std::memory_order_relaxed)||!g_ready.load(std::memory_order_acquire))return;
	if(g_cacheOffloadLaunch){
		const bool playing=EngInGame(),loading=EngDrawingLoading();
		skeeto_cache::SetTimingEnabled(g_optCacheOffload && g_optCacheOffloadHud && SkeetoFeaturesOn()
			&& !HudCustomHidden() && !g_hudPostMissionQuiet && playing && !loading
			&& !g_paintGameUiVisible.load(std::memory_order_relaxed));
		skeeto_cache::Pump(playing,loading);
	}
	if(g_cacheOffloadReportRequested.exchange(false,std::memory_order_acq_rel))CacheOffloadReport();
}
static void SkCmd_CacheStatus(int*) { g_cacheOffloadReportRequested.store(true,std::memory_order_release); }
static void SkCmd_CacheReclaim(int*) { if(g_cacheOffloadLaunch)skeeto_cache::RequestReclaim(); }
static void CrashGuardReport() {
	wchar_t line[384]{};
	wchar_t cacheState[160]{}, indexState[160]{};
	CrashGuardFormatState(g_crashGuardCacheState.load(std::memory_order_acquire),
		g_crashGuardCacheProtectionWarning.load(std::memory_order_acquire), cacheState, _countof(cacheState));
	CrashGuardFormatState(g_crashGuardIndexState.load(std::memory_order_acquire),
		g_crashGuardIndexProtectionWarning.load(std::memory_order_acquire), indexState, _countof(indexState));
	swprintf_s(line, UiText(UiId::CrashGuardReportCache, L"Datacache: 保存=%d MB, 本次启动=%d MB, 状态=%s (0=不改)"),
		g_optCrashGuardCacheMb, g_crashGuardLaunchCacheMb, cacheState);
	CrashGuardEcho(line);
	unsigned used = 0, limit = 0;
	if (MemoryHudReadDc(&used, &limit)) {
		swprintf_s(line, UiText(UiId::CrashGuardReportCacheLive, L"Datacache 实际用量=%.1f MB, 实际上限=%.1f MB"), used / 1048576.0, limit / 1048576.0);
		CrashGuardEcho(line);
	} else CrashGuardEcho(UiText(UiId::CrashGuardCacheUnavailable, L"Datacache: 当前接口不可用，无法核验实际上限。"));
	swprintf_s(line, UiText(UiId::CrashGuardReportIndex, L"index_buffer_size: 保存=%d, 本次启动=%d, 状态=%s (0=不改)"),
		g_optCrashGuardIndexCount, g_crashGuardLaunchIndexCount, indexState);
	CrashGuardEcho(line);
	const char* name = CmdLineHasFlag("-vulkan") ? "shaderapivk.dll" : "shaderapidx9.dll";
	const HMODULE module = GetModuleHandleA(name); // Diagnostic is read-only; never load a backend.
	const int d = CrashGuardShaderDelta(module);
	if (d == 1) {
		CrashGuardEcho(UiText(UiId::CrashGuardIndexUnavailable, L"索引缓冲: 当前模块缺失或版本不匹配，无法核验。")); return;
	}
	__try {
		auto* base = reinterpret_cast<unsigned char*>(module);
		if (!CrashGuardIndexLayout(module, d)) {
			CrashGuardEcho(UiText(UiId::CrashGuardIndexUnavailable, L"索引缓冲: 当前模块缺失或版本不匹配，无法核验。")); return;
		}
		auto* buffer = *reinterpret_cast<unsigned char**>(base + 0xCE488 + 0x1EC);
		unsigned live = 0;
		if (buffer && CrashGuardReadable(buffer, 0x24)) live = *reinterpret_cast<unsigned*>(buffer + 4);
		const unsigned embedded = *reinterpret_cast<unsigned*>(base + 0xCE488 + 0x3C8);
		const unsigned maximum = *reinterpret_cast<unsigned*>(base + 0x8D71 + d);
		swprintf_s(line, UiText(UiId::CrashGuardReportIndexLive, L"索引缓冲实际容量=%u, 内置缓冲容量=%u, 渲染查询上限=%u (0=尚未创建)"), live, embedded, maximum);
		CrashGuardEcho(line);
		if (g_crashGuardLaunchIndexCount) {
			const unsigned expected = (static_cast<unsigned>(g_crashGuardLaunchIndexCount) + 1u) & ~1u;
			if (!live) CrashGuardEcho(UiText(UiId::CrashGuardIndexVerifyPending, L"索引容量核验: 运行时缓冲尚未创建，暂不能确认。"));
			else if (live == expected && embedded == expected && maximum == expected)
				CrashGuardEcho(UiText(UiId::CrashGuardIndexVerifyPass, L"索引容量核验: 三处运行时容量均与本次启动档位一致。"));
			else CrashGuardEcho(UiText(UiId::CrashGuardIndexVerifyMismatch, L"索引容量核验: 运行时容量与本次启动档位不一致，请检查上述状态。"));
		}
		CrashGuardEcho(UiText(UiId::CrashGuardReportIndexExplain, L"65535 档按引擎偶数对齐为 65536；上述容量来自运行时对象，不是 ini 数字，也不代表所有闪退已解决。"));
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		CrashGuardEcho(UiText(UiId::CrashGuardIndexUnavailable, L"索引缓冲: 当前模块缺失或版本不匹配，无法核验。"));
	}
}
static void CrashGuardClearDecalsPump() {
	if (!g_optCrashGuardAutoClearDecals || !g_run.load(std::memory_order_relaxed)
		|| !SkeetoFeaturesOn() || !g_engine || !EngInGame() || EngDrawingLoading()) {
		if (!g_optCrashGuardAutoClearDecals) g_crashGuardClearDecalsImmediate = false;
		return;
	}
	const DWORD now = GetTickCount();
	const DWORD intervalMs = (DWORD)g_optCrashGuardClearDecalsInterval * 1000u;
	const bool due = g_crashGuardClearDecalsImmediate
		|| !g_crashGuardClearDecalsLastAt
		|| now - g_crashGuardClearDecalsLastAt >= intervalMs;
	if (!due) return;
	g_crashGuardClearDecalsImmediate = false;
	g_crashGuardClearDecalsLastAt = now;
	UnlockConCommand("r_cleardecals", 0, kFCvarClientCmdCanExecute);
	EngClientCmdUnrestricted("r_cleardecals");
	static DWORD s_loggedAt = 0;
	if (!s_loggedAt || now - s_loggedAt > 60000u) {
		s_loggedAt = now;
		Log("crashguard: r_cleardecals interval=%ds", g_optCrashGuardClearDecalsInterval);
	}
}

static void CrashGuardGamePump() {
	if (!g_run.load(std::memory_order_relaxed) || !g_ready.load(std::memory_order_acquire)) return;
	// A full Paint proves renderer initialization has passed. If its one-shot hook never
	// ran, disarm now instead of applying a surprise patch during a later device reset.
	int armed = kCrashGuardArmed;
	if (g_crashGuardIndexState.compare_exchange_strong(armed, kCrashGuardLate, std::memory_order_acq_rel))
		CrashGuardRestoreIndexEntry();
	const bool report = g_crashGuardStatusRequested.exchange(false, std::memory_order_acq_rel);
	if (g_crashGuardCacheState.load(std::memory_order_acquire) == kCrashGuardPending) {
		const DWORD now = GetTickCount();
		if (now - g_crashGuardStartedAt > 60000u) g_crashGuardCacheState.store(kCrashGuardFailed, std::memory_order_release);
		else if ((!g_crashGuardCacheTryAt || now - g_crashGuardCacheTryAt >= 250u) && !EngDrawingLoading()) {
			g_crashGuardCacheTryAt = now;
			// Reject late injection during a map; budget reductions may evict resources.
			g_crashGuardCacheState.store(EngInGame() ? kCrashGuardLate : CrashGuardApplyCache(), std::memory_order_release);
		}
	}
	if (report) CrashGuardReport();
	CrashGuardClearDecalsPump();
}

static void SkCmd_CrashGuardStatus(int*) {
	// Console callback only publishes; validated interface reads run on the known Paint thread.
	g_crashGuardStatusRequested.store(true, std::memory_order_release);
}

// skeeto_memprobe: page-query and guarded-read fault counters since the previous
// report. Sites are Skeeto RVAs; map them with skeeto.pdb of the same build.
static std::atomic_bool g_memProbeRequested{false};
static uint32_t g_memProbeFrames = 0;
static void MemProbeReport() {
	const DWORD now = GetTickCount();
	const DWORD started = skmem::g_windowStart.load(std::memory_order_relaxed);
	const double secs = started ? (double)(now - started) / 1000.0 : 0.0;
	const uint32_t queries = skmem::g_queries.load(std::memory_order_relaxed);
	const uint32_t faults = skmem::g_faults.load(std::memory_order_relaxed);
	LARGE_INTEGER freq{};
	QueryPerformanceFrequency(&freq);
	const double tickUs = freq.QuadPart > 0 ? 1e6 / (double)freq.QuadPart : 0.0;
	char line[256];
	sprintf_s(line, "[memprobe] window %.1fs, %u paint frames, VirtualQuery %u (%.1f/frame), exec-cache hits %u, guarded faults %u, guard rearm %u, slot overflow %u",
		secs, g_memProbeFrames, queries, g_memProbeFrames ? (double)queries / g_memProbeFrames : 0.0,
		skmem::g_execCacheHits.exchange(0, std::memory_order_relaxed),
		faults, skmem::g_guardRearmed.load(std::memory_order_relaxed),
		skmem::g_slotOverflow.load(std::memory_order_relaxed));
	ConEcho(line);
	Log("%s", line);
	if (!started) ConEcho("[memprobe] first call opens the window; run it again after playing a while.");
	sprintf_s(line, "[back items] enabled=%d hook=%d failed=%d calls=%u filtered=%u wrong-thread=%u (process totals)",
		g_optClientHideBackItems ? 1 : 0, g_clientAddonHooked ? 1 : 0, g_clientAddonFailed ? 1 : 0,
		g_clientAddonCalls, g_clientAddonFiltered, g_clientAddonWrongThread.load(std::memory_order_relaxed));
	ConEcho(line);
	constexpr int kTop = 24;
    sprintf_s(line, "[viewmodel] enabled=%d hook=%d failed=%d profiles=%d calls=%u applied=%u binds=%u loads=%u saves=%u (process totals)",
        g_vmEnabled ? 1 : 0, g_vmHooked ? 1 : 0, g_vmHookFailed ? 1 : 0, g_vmStore.count,
        g_vmCalcCalls, g_vmApplied, g_vmBindingChanges, g_vmLoadRequests, g_vmSaveRequests);
    ConEcho(line);
    sprintf_s(line, "[viewmodel mirror] mode=%s global=%d native=%d failed=%d conflict=%d changes=%u restores=%u builds=%u matrices=%u", g_vmMirrorPerModel ? "model" : "global", g_vmMirrorEnabled ? 1 : 0, g_vmMirrorActive ? 1 : 0, g_vmMirrorFailed ? 1 : 0, g_vmMirrorConflict ? 1 : 0, g_vmMirrorChanges, g_vmMirrorRestores, g_vmMirrorBuilds, g_vmMirrorMatrices);
    ConEcho(line);
    sprintf_s(line, "[viewmodel scale] off=%d bones=%d fieldWrites=%u rewrites=%u boneBuilds=%u",
        g_offModelScale, g_vmScaleUseBones ? 1 : 0, g_vmScaleFieldWrites, g_vmScaleRewrites, g_vmScaleBoneBuilds);
    ConEcho(line);
	int top[kTop];
	uint64_t topCost[kTop];
	int topCount = 0;
	for (int i = 0; i < skmem::kProbeSlots; ++i) {
		const skmem::ProbeSlot& s = skmem::g_slots[i];
		if (!s.site.load(std::memory_order_relaxed)) continue;
		const uint32_t q = s.queries.load(std::memory_order_relaxed);
		const uint32_t f = s.faults.load(std::memory_order_relaxed);
		if (!q && !f) continue;
		const uint64_t cost = s.ticks.load(std::memory_order_relaxed) + (uint64_t)f * 1000000u;
		int at = topCount < kTop ? topCount++ : kTop;
		if (at == kTop) {
			if (cost <= topCost[kTop - 1]) continue;
			at = kTop - 1;
		}
		while (at > 0 && topCost[at - 1] < cost) {
			top[at] = top[at - 1];
			topCost[at] = topCost[at - 1];
			--at;
		}
		top[at] = i;
		topCost[at] = cost;
	}
	const uintptr_t base = (uintptr_t)g_self;
	for (int k = 0; k < topCount; ++k) {
		const skmem::ProbeSlot& s = skmem::g_slots[top[k]];
		const uintptr_t site = s.site.load(std::memory_order_relaxed);
		const uint32_t q = s.queries.load(std::memory_order_relaxed);
		const double totalUs = (double)s.ticks.load(std::memory_order_relaxed) * tickUs;
		sprintf_s(line, "[memprobe]  site %s%08X  queries %u  total %.0fus  avg %.2fus  faults %u",
			site >= base && site - base < 0x01000000u ? "skeeto+" : "abs ", (unsigned)(site >= base && site - base < 0x01000000u ? site - base : site),
			q, totalUs, q ? totalUs / q : 0.0, s.faults.load(std::memory_order_relaxed));
		ConEcho(line);
		Log("%s", line);
	}
	skmem::ResetCounters();
	g_memProbeFrames = 0;
}
static void MemProbeGamePump() {
	++g_memProbeFrames;
	if (g_memProbeRequested.exchange(false, std::memory_order_acq_rel)) MemProbeReport();
}
static void SkCmd_MemProbe(int*) {
	g_memProbeRequested.store(true, std::memory_order_release);
}

// These are the L4D2 VDataCache003 layouts, not Source SDK 2013 IAppSystem slots.
// Verified in game 2.2.4.3 datacache.dll: GetStatus=8, Flush=13, both ret 8.
struct MemoryCacheStatus { unsigned bytes, items, lockedBytes, lockedItems, finds, hits; };
struct MemoryCacheLimits { unsigned maxBytes, maxItems, minBytes, minItems; };
static_assert(sizeof(MemoryCacheStatus) == 24 && sizeof(MemoryCacheLimits) == 16, "datacache ABI");

static void* MemoryHudMethod(void* object, int slot, HMODULE module) {
	if (!object || !module) return nullptr;
	__try {
		if (!IfaceAlive(object)) return nullptr;
		void* fn = VGet(object, slot);
		HMODULE owner = nullptr;
		if (!fn || !IsExec(fn) || !GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS
			| GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
			reinterpret_cast<LPCSTR>(fn), &owner) || owner != module) return nullptr;
		return fn;
	} __except (EXCEPTION_EXECUTE_HANDLER) { return nullptr; }
}

static bool MemoryHudResolveDc() {
	const HMODULE mod = GetModuleHandleA("datacache.dll");
	if (mod != g_memoryDcModule) {
		g_memoryDcModule = mod;
		g_memoryDataCache = nullptr;
		g_memoryDcFaulted = false;
		g_memoryBridgeState = 0;
	}
	if (!mod || g_memoryDcFaulted) return false;
	if (g_memoryDataCache) return true;
	__try {
		void* object = GetIface("datacache.dll", "VDataCache003");
		const auto status = static_cast<const unsigned char*>(MemoryHudMethod(object, 8, mod));
		const auto flush = static_cast<const unsigned char*>(MemoryHudMethod(object, 13, mod));
		// Guard the verified ABI before passing writable status buffers or purge args.
		static const unsigned char statusPrefix[] = {0x55,0x8B,0xEC,0x8B,0x45,0x08,0x33,0xD2,0x56};
		static const unsigned char flushPrefix[] = {0x55,0x8B,0xEC,0x56,0x8B,0xF1,0x80,0xBE,0x88,0,0,0,0};
		if (!status || !flush || memcmp(status, statusPrefix, sizeof(statusPrefix))
			|| memcmp(flush, flushPrefix, sizeof(flushPrefix))) {
			g_memoryBridgeState = 2;
			g_memoryDcFaulted = true;
			return false;
		}
		g_memoryDataCache = object;
		g_memoryBridgeState = 1;
		return true;
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_memoryBridgeState = 2;
		g_memoryDcFaulted = true;
		return false;
	}
}

static bool MemoryHudReadDc(unsigned* used, unsigned* limit) {
	if (g_memoryDcClearing || !MemoryHudResolveDc()) return false;
	__try {
		using Fn = void(__thiscall*)(void*, MemoryCacheStatus*, MemoryCacheLimits*);
		auto fn = reinterpret_cast<Fn>(MemoryHudMethod(g_memoryDataCache, 8, g_memoryDcModule));
		if (!fn) return false;
		MemoryCacheStatus status{};
		MemoryCacheLimits limits{};
		fn(g_memoryDataCache, &status, &limits);
		if (limits.maxBytes < 16u * 1024u * 1024u || limits.maxBytes == 0xFFFFFFFFu
			) return false;
		g_memoryDcLockedBytes = status.lockedBytes > status.bytes ? status.bytes : status.lockedBytes;
		*used = status.bytes;
		*limit = limits.maxBytes;
		return true;
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_memoryDcFaulted = true;
		g_memoryBridgeState = 2;
		return false;
	}
}

static bool MemoryHudReadEnts(int* count) {
	const HMODULE mod = GetModuleHandleA("client.dll");
	__try {
		// VClientEntityList003::NumberOfEntities(true), slot 5, ret 4.
		using Fn = int(__thiscall*)(void*, bool);
		auto fn = reinterpret_cast<Fn>(MemoryHudMethod(g_entlist, 5, mod));
		if (!fn) return false;
		static const unsigned char prefix[] = {0x55,0x8B,0xEC,0x80,0x7D,0x08,0x01};
		if (memcmp(reinterpret_cast<const void*>(fn), prefix, sizeof(prefix))) return false;
		const int value = fn(g_entlist, true);
		if (value < 0 || value > 65536) return false;
		*count = value;
		return true;
	} __except (EXCEPTION_EXECUTE_HANDLER) { return false; }
}

static void MemoryHudSetScanWanted(bool wanted) {
	// Only the game/Paint thread changes the requested lifecycle.
	if (g_memoryFreeScanWanted.load(std::memory_order_relaxed) != wanted) {
		g_memoryFreeScanGeneration.fetch_add(1, std::memory_order_acq_rel);
		g_memoryFreeScanWanted.store(wanted, std::memory_order_release);
		g_memoryFreeScanValid.store(false, std::memory_order_release);
	}
	if (!wanted) g_memoryFreeScanValid.store(false, std::memory_order_release);
}

static bool MemoryHudHaveFreeSnapshot() {
	return g_memoryFreeScanWanted.load(std::memory_order_acquire)
		&& g_memoryFreeScanValid.load(std::memory_order_acquire)
		&& g_memoryFreeSnapshotGeneration.load(std::memory_order_acquire)
			== g_memoryFreeScanGeneration.load(std::memory_order_acquire);
}

static void MemoryHudClearSample() {
	MemoryHudSetScanWanted(false);
	g_memoryHudHaveSample = false;
	g_memoryHaveDc = g_memoryHaveAv = g_memoryHaveEnts = false;
	g_memoryHaveProcess = false;
	g_memoryHudSampleAt = 0;
	g_memoryDcBytes = g_memoryDcLimitBytes = 0;
	g_memoryDcLockedBytes = 0;
	g_memoryAvailBytes = 0;
	g_memoryEnts = 0;
}

static bool MemoryHudPressure(unsigned used, unsigned limit, unsigned long long avail) {
	return avail < 300ull * 1048576ull
		|| (limit != 0 && 10ull * used >= 9ull * limit);
}

static void MemoryHudWorkerPump() {
	// Existing worker only: Windows queries, no game interfaces or entity access.
	static bool active = false, haveCompleted = false;
	static DWORD completedAt = 0;
	static unsigned generation = 0;
	static unsigned long long cursor = 0, ceiling = 0, largest = 0;
	const unsigned requested = g_memoryFreeScanGeneration.load(std::memory_order_acquire);
	if (requested != generation) {
		generation = requested;
		active = haveCompleted = false;
		g_memoryFreeScanValid.store(false, std::memory_order_release);
	}
	if (!g_memoryFreeScanWanted.load(std::memory_order_acquire)) {
		active = haveCompleted = false;
		g_memoryFreeScanValid.store(false, std::memory_order_release);
		return;
	}
	const DWORD started = GetTickCount();
	if (!active) {
		if (haveCompleted && started - completedAt < 30000u) return;
		SYSTEM_INFO info{};
		GetSystemInfo(&info);
		ceiling = reinterpret_cast<uintptr_t>(info.lpMaximumApplicationAddress);
		cursor = largest = 0;
		active = true;
	}
	for (int i = 0; i < 64; ++i) {
		if (!g_memoryFreeScanWanted.load(std::memory_order_acquire)
			|| g_memoryFreeScanGeneration.load(std::memory_order_acquire) != generation) {
			active = haveCompleted = false;
			return;
		}
		MEMORY_BASIC_INFORMATION region{};
		const SIZE_T read = VirtualQuery(reinterpret_cast<const void*>(static_cast<uintptr_t>(cursor)),
			&region, sizeof(region));
		const unsigned long long next = reinterpret_cast<uintptr_t>(region.BaseAddress)
			+ static_cast<unsigned long long>(region.RegionSize);
		if (read != sizeof(region) || region.RegionSize == 0 || next <= cursor) {
			active = false;
			haveCompleted = true;
			completedAt = GetTickCount();
			g_memoryFreeScanValid.store(false, std::memory_order_release);
			return;
		}
		if (region.State == MEM_FREE && region.RegionSize > largest) largest = region.RegionSize;
		cursor = next;
		if (cursor > ceiling) {
			active = false;
			haveCompleted = true;
			completedAt = GetTickCount();
			if (g_memoryFreeScanWanted.load(std::memory_order_acquire)
				&& g_memoryFreeScanGeneration.load(std::memory_order_acquire) == generation) {
				g_memoryLargestFreeBytes.store(largest, std::memory_order_relaxed);
				g_memoryFreeSnapshotGeneration.store(generation, std::memory_order_release);
				g_memoryFreeScanValid.store(true, std::memory_order_release);
			}
			return;
		}
		if (GetTickCount() - started >= 2u) return;
	}
}

static void MemoryHudSample() {
	if (g_memoryDcClearing) return;
	const DWORD now = GetTickCount();
	if (g_memoryHudSampleAt && now - g_memoryHudSampleAt < 1000u) return;
	g_memoryHudSampleAt = now;
	g_memoryHaveDc = MemoryHudReadDc(&g_memoryDcBytes, &g_memoryDcLimitBytes);
	MEMORYSTATUSEX mem{};
	mem.dwLength = sizeof(mem);
	g_memoryHaveAv = GlobalMemoryStatusEx(&mem) != FALSE;
	if (g_memoryHaveAv) g_memoryAvailBytes = mem.ullAvailVirtual;
	g_memoryHaveEnts = g_optMemoryHud && MemoryHudReadEnts(&g_memoryEnts);
	g_memoryHaveProcess = false;
	if (g_optMemoryHud && g_memoryHudInfo) {
		PROCESS_MEMORY_COUNTERS_EX process{};
		process.cb = sizeof(process);
		g_memoryHaveProcess = GetProcessMemoryInfo(GetCurrentProcess(),
			reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&process), sizeof(process)) != FALSE;
		if (g_memoryHaveProcess) {
			g_memoryWorkingSetBytes = process.WorkingSetSize;
			g_memoryPrivateBytes = process.PrivateUsage;
		}
	}
	g_memoryHudHaveSample = g_memoryHaveDc || g_memoryHaveAv || g_memoryHaveEnts;
	if (g_optClientAutoClearDatacache && g_memoryHaveDc && g_memoryHaveAv
		&& (!g_memoryClearDcHaveLast || now - g_memoryClearDcLastAt >= 600000u)
		&& MemoryHudPressure(g_memoryDcBytes, g_memoryDcLimitBytes, g_memoryAvailBytes))
		g_memoryClearDcPending.store(true, std::memory_order_release);
}

static void MemoryHudTick() {
	if (!g_optMemoryHud && !g_optClientAutoClearDatacache
		&& !g_memoryClearDcManual.load(std::memory_order_acquire)
		&& !g_memoryHudHaveSample && !g_memoryHudSampleAt) {
		MemoryHudSetScanWanted(false);
		return;
	}
	const bool valid = SkeetoFeaturesOn() && g_engine && EngInGame() && !EngDrawingLoading();
	const bool detailed = valid && g_optMemoryHud && g_memoryHudInfo;
	MemoryHudSetScanWanted(detailed);
	if (!valid || (!g_optMemoryHud && !g_optClientAutoClearDatacache)) {
		g_memoryClearDcPending.store(false, std::memory_order_release);
		if (!valid && g_memoryClearDcManual.exchange(false, std::memory_order_acq_rel))
			ConEcho("datacache: unavailable while disconnected, loading or Skeeto is disabled");
		if (g_memoryHudHaveSample || g_memoryHudSampleAt) MemoryHudClearSample();
		return;
	}
	MemoryHudSample();
}

static bool MemoryHudFlushDc(unsigned* released) {
	if (!MemoryHudResolveDc()) return false;
	__try {
		using Fn = unsigned(__thiscall*)(void*, bool, bool);
		auto fn = reinterpret_cast<Fn>(MemoryHudMethod(g_memoryDataCache, 13, g_memoryDcModule));
		if (!fn) return false;
		// Never force eviction of locked resources. Engine notifications remain enabled.
		*released = fn(g_memoryDataCache, true, true);
		return true;
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_memoryDcFaulted = true;
		g_memoryBridgeState = 2;
		return false;
	}
}

static void MemoryDatacachePump() {
	if (g_memoryDcClearing) return;
	const bool manual = g_memoryClearDcManual.exchange(false, std::memory_order_acq_rel);
	const bool automatic = g_memoryClearDcPending.exchange(false, std::memory_order_acq_rel)
		&& g_optClientAutoClearDatacache;
	if (!manual && !automatic) return;
	if (!SkeetoFeaturesOn() || !g_engine || !EngInGame() || EngDrawingLoading()
		|| g_hudPostMissionQuiet) {
		if (manual) ConEcho("datacache: unavailable while disconnected, loading or Skeeto is disabled");
		return;
	}
	const DWORD now = GetTickCount();
	if (g_memoryClearDcHaveLast && now - g_memoryClearDcLastAt < (manual ? 5000u : 600000u)) {
		if (manual) ConEcho("datacache: please wait at least 5 seconds between manual clears");
		return;
	}
	unsigned used = 0, limit = 0;
	if (!MemoryHudReadDc(&used, &limit)) {
		if (manual) ConEcho("datacache: game interface unavailable; no cleanup performed");
		return;
	}
	if (!manual) {
		MEMORYSTATUSEX mem{};
		mem.dwLength = sizeof(mem);
		if (!GlobalMemoryStatusEx(&mem) || !MemoryHudPressure(used, limit, mem.ullAvailVirtual)) return;
	}
	g_memoryDcClearing = true;
	unsigned released = 0;
	const bool ok = MemoryHudFlushDc(&released);
	g_memoryDcClearing = false;
	g_memoryClearDcPending.store(false, std::memory_order_release);
	if (!ok) {
		if (manual) ConEcho("datacache: cleanup failed; no forced eviction attempted");
		return;
	}
	g_memoryLastReleasedBytes = released;
	g_memoryClearDcLastAt = GetTickCount();
	g_memoryClearDcHaveLast = true;
	g_memoryHudSampleAt = 0;
	if (manual) {
		char message[128];
		snprintf(message, sizeof(message), "datacache: released %.1f MB of unlocked cache", released / 1048576.0);
		ConEcho(message);
	}
	Log("datacache: cleared unlocked cache, released=%u manual=%d", released, manual ? 1 : 0);
}

static void SkCmd_ClearDatacache(int*) {
	// Command callbacks only enqueue; the game/Paint thread owns the cache operation.
	g_memoryClearDcManual.store(true, std::memory_order_release);
}

static COLORREF MemoryHudRatioColor(float value, float warn, float danger,
	bool highIsBad, COLORREF safeColor) {
	const bool bad = highIsBad ? value >= danger : value <= danger;
	const bool mid = highIsBad ? value >= warn : value <= warn;
	if (bad) return RGB(255, 86, 72);
	if (mid) return RGB(248, 194, 88);
	return safeColor;
}

struct MemoryHudRow {
	const wchar_t* label;
	wchar_t value[128];
	COLORREF base, color;
	const wchar_t* secondLabel;
	wchar_t secondValue[64];
};

static int MemoryHudBuildRows(MemoryHudRow (&rows)[7], bool preview) {
	const bool fake = preview && !g_optMemoryHud;
	const bool haveDc = g_memoryHaveDc || fake, haveAv = g_memoryHaveAv || fake;
	const bool haveEnts = g_memoryHaveEnts || fake;
	const unsigned dc = g_memoryHaveDc ? g_memoryDcBytes : 124u * 1048576u;
	const unsigned limit = g_memoryHaveDc ? g_memoryDcLimitBytes : 2048u * 1048576u;
	const double avMb = g_memoryHaveAv ? g_memoryAvailBytes / 1048576.0 : 512.0;
	const int ents = g_memoryHaveEnts ? g_memoryEnts : 901;
	const COLORREF muted = RGB(170, 180, 184);
	rows[0].label = L"DC"; rows[0].base = RGB(92, 206, 244);
	rows[1].label = L"AV"; rows[1].base = RGB(123, 218, 159);
	rows[2].label = L"ENTS"; rows[2].base = RGB(190, 166, 242);
	for (int i = 0; i < 7; ++i) rows[i].color = muted;
	if (haveDc) {
		swprintf_s(rows[0].value, L"%.0f/%.0f MB", dc / 1048576.0, limit / 1048576.0);
		rows[0].color = MemoryHudRatioColor(limit ? float(dc) / limit : 0.f,
			0.70f, 0.90f, true, rows[0].base);
	} else wcsncpy_s(rows[0].value, g_memoryBridgeState == 2
		? UiText(UiId::Text_aadd0ea4, L"N/A") : UiText(UiId::Text_c57f260f, L"WAIT"), _TRUNCATE);
	if (haveAv) {
		swprintf_s(rows[1].value, L"%.0f MB", avMb);
		rows[1].color = MemoryHudRatioColor(float(avMb), 512.f, 256.f, false, rows[1].base);
	} else wcscpy_s(rows[1].value, L"--");
	if (haveEnts) {
		swprintf_s(rows[2].value, L"%d", ents);
		rows[2].color = MemoryHudRatioColor(float(ents), 1500.f, 1850.f, true, rows[2].base);
	} else wcscpy_s(rows[2].value, L"--");
	if (!g_memoryHudInfo) return 3;
	rows[5] = rows[2];
	rows[2] = rows[1];
	rows[1].label = UiText(UiId::MemoryCacheLocked, L"锁定");
	rows[1].base = RGB(128, 191, 214);
	rows[1].secondLabel = UiText(UiId::MemoryCacheUnlocked, L"未锁定");
	wcscpy_s(rows[1].secondValue, L"--");
	rows[3].label = UiText(UiId::MemoryLargestFree, L"最大连续内存");
	rows[3].base = RGB(148, 204, 169);
	rows[4].label = UiText(UiId::MemoryProcessPair, L"实际占用");
	rows[4].base = RGB(255, 255, 255);
	rows[4].secondLabel = UiText(UiId::MemoryPrivateCommit, L"私有提交");
	wcscpy_s(rows[4].secondValue, L"--");
	rows[6].label = UiText(UiId::MemoryLastClear, L"CLR");
	rows[6].base = RGB(157, 177, 194);
	wcscpy_s(rows[1].value, L"--");
	wcscpy_s(rows[3].value, L"--");
	wcscpy_s(rows[4].value, L"--");
	if (haveDc) {
		const unsigned locked = fake ? 32u * 1048576u : g_memoryDcLockedBytes;
		const unsigned unlocked = dc > locked ? dc - locked : 0;
		swprintf_s(rows[1].value, L"%.0f MB", locked / 1048576.0);
		swprintf_s(rows[1].secondValue, L"%.0f MB", unlocked / 1048576.0);
		rows[1].color = rows[1].base;
	}
	if (MemoryHudHaveFreeSnapshot() || fake) {
		const double largest = fake ? 256.0 : g_memoryLargestFreeBytes.load(std::memory_order_relaxed) / 1048576.0;
		swprintf_s(rows[3].value, L"%.0f MB", largest);
		rows[3].color = MemoryHudRatioColor(float(largest), 256.f, 128.f, false, rows[3].base);
	}
	if (g_memoryHaveProcess || fake) {
		const double ram = fake ? 850.0 : g_memoryWorkingSetBytes / 1048576.0;
		const double commit = fake ? 1100.0 : g_memoryPrivateBytes / 1048576.0;
		swprintf_s(rows[4].value, L"%.0f MB", ram);
		swprintf_s(rows[4].secondValue, L"%.0f MB", commit);
		rows[4].color = rows[4].base;
	}
	if (g_memoryClearDcHaveLast || fake) {
		const double released = fake ? 96.0 : g_memoryLastReleasedBytes / 1048576.0;
		const unsigned seconds = fake ? 45 : (GetTickCount() - g_memoryClearDcLastAt) / 1000u;
		swprintf_s(rows[6].value, UiText(UiId::MemoryClearHistory, L"%.0f MB / %us"), released, seconds);
		rows[6].color = rows[6].base;
	} else wcsncpy_s(rows[6].value, UiText(UiId::MemoryNeverCleared, L"--"), _TRUNCATE);
	return 7;
}

// Fixed, bounded line mapping; labels stay next to their values in both styles.
static void MemoryHudPaintLayout(int sw, int sh, bool preview, bool compact) {
	const int sc = HudClampScale(g_memoryHudScale);
	const int mainPx = HudScalePx(g_memoryHudLayoutFont, sc);
	const unsigned long font = HudAcquireLayoutFont(mainPx,
		&g_memoryHudFontId, &g_memoryHudFontTall, 700);
	if (!font) return;
	MemoryHudRow rows[7]{};
	const int count = MemoryHudBuildRows(rows, preview);
	const bool detailed = count == 7;
	const int left[5] = { 0, detailed ? 1 : 1, 2, 3, 4 };
	const int right[5] = { detailed ? 6 : -1, detailed ? -1 : 2, detailed ? 5 : -1, -1, -1 };
	const int lines = detailed ? 5 : 2;
	const int pad = HudScalePx(8, sc), gap = SurfTextWFont(font, L" ");
	const int pairGap = SurfTextWFont(font, L"  ");
	const int rowH = mainPx + HudScalePx(compact ? 2 : 4, sc);
	const int titleH = compact ? 0 : mainPx + HudScalePx(7, sc);
	auto fieldWidth = [&](const wchar_t* label, const wchar_t* value) {
		return SurfTextWFont(font, label) + gap + SurfTextWFont(font, value);
	};
	int leftWidth = 0, rightWidth = 0, singleWidth = 0;
	for (int line = 0; line < lines; ++line) {
		const MemoryHudRow& first = rows[left[line]];
		const int width = fieldWidth(first.label, first.value);
		const MemoryHudRow* second = right[line] >= 0 ? &rows[right[line]] : nullptr;
		const wchar_t* secondLabel = second ? second->label : first.secondLabel;
		const wchar_t* secondValue = second ? second->value : first.secondValue;
		if (secondLabel) {
			const int other = fieldWidth(secondLabel, secondValue);
			if (width > leftWidth) leftWidth = width;
			if (other > rightWidth) rightWidth = other;
		} else if (width > singleWidth) singleWidth = width;
	}
	const int pairWidth = leftWidth + pairGap + rightWidth;
	const int inner = pairWidth > singleWidth ? pairWidth : singleWidth;
	const int panelW = pad * 2 + inner;
	const int panelH = pad * 2 + titleH + rowH * lines;
	int x = 0, y = 0;
	HudFinalizePos(&g_memoryHudAbs, &g_memoryHudOffX, &g_memoryHudOffY,
		g_memoryHudAlign, sw, sh, panelW, panelH, &x, &y);
	const COLORREF accent = compact ? RGB(65, 225, 178) : RGB(104, 204, 236);
	HudPanelShadow(x, y, panelW, panelH);
	HudGlassBody(x, y, panelW, panelH);
	HudSideAccent(x, y, panelH, accent, HudScalePx(3, sc));
	HudCornerBrackets(x, y, panelW, panelH, HudScalePx(10, sc), accent, preview ? 210 : 120);
	int ty = y + pad;
	if (!compact) {
		const COLORREF rail[3] = { rows[0].base, rows[detailed ? 2 : 1].base, rows[detailed ? 5 : 2].base };
		for (int i = 0; i < 3; ++i) {
			SurfColor(GetRValue(rail[i]), GetGValue(rail[i]), GetBValue(rail[i]), 235);
			SurfFill(x + panelW * i / 3, y, x + panelW * (i + 1) / 3, y + HudScalePx(2, sc));
		}
		SurfTextAt(font, x + pad, ty, RGB(184, 222, 232), UiText(UiId::MemoryHudCardTitle, L"MEMORY"));
		const wchar_t* tag = UiText(UiId::MemoryHudBrand, L"Skeeto");
		const int tagPad = HudScalePx(4, sc);
		const int tagW = SurfTextWFont(font, tag) + tagPad * 2;
		const int tagX = x + panelW - pad - tagW;
		SurfColor(GetRValue(accent), GetGValue(accent), GetBValue(accent), 34);
		SurfFill(tagX, ty - 1, x + panelW - pad, ty + mainPx + HudScalePx(2, sc));
		SurfTextAt(font, tagX + tagPad, ty, RGB(132, 205, 224), tag);
		ty += titleH;
	}
	for (int line = 0; line < lines; ++line) {
		int tx = x + pad;
		if (!compact) {
			const COLORREF base = rows[left[line]].base;
			SurfColor(GetRValue(base), GetGValue(base), GetBValue(base), 15);
			SurfFill(tx - 2, ty, x + panelW - pad + 2, ty + rowH);
		}
		auto field = [&](int at, const wchar_t* label, const wchar_t* value,
			COLORREF base, COLORREF color, bool single) {
			SurfTextAt(font, at, ty, compact ? color : base, label);
			const int valueX = single ? x + panelW - pad - SurfTextWFont(font, value)
				: at + SurfTextWFont(font, label) + gap;
			SurfTextAt(font, valueX, ty, color, value);
		};
		const MemoryHudRow& first = rows[left[line]];
		const MemoryHudRow* second = right[line] >= 0 ? &rows[right[line]] : nullptr;
		const wchar_t* secondLabel = second ? second->label : first.secondLabel;
		const wchar_t* secondValue = second ? second->value : first.secondValue;
		field(tx, first.label, first.value, first.base, first.color, !secondLabel);
		if (secondLabel) {
			const int secondX = x + panelW - pad - fieldWidth(secondLabel, secondValue);
			field(secondX, secondLabel, secondValue,
				second ? second->base : first.base, second ? second->color : first.color, false);
		}
		ty += rowH;
	}
}

static void MemoryHudPaint() {
	const bool preview = HudMenuPage(kMenuPageMemoryHud);
	if (!HudWantsDraw(g_optMemoryHud, kMenuPageMemoryHud)) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || !MenuEnsureSurf()) return;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;
	MemoryHudPaintLayout(sw, sh, preview, g_memoryHudStyle != 0);
}

// Layout/text and AV are sampled only while this HUD is visible, at most 1 Hz.
// Paint uses cached extents; no VA-region scan, engine cache enumeration or I/O.
struct CacheOffloadHudLayout {
	bool valid = false, english = false, demo = false;
	DWORD at = 0;
	int sw = 0, sh = 0, requestedPx = 0, scale = 0;
	int px = 0, pad = 0, rowH = 0, titleH = 0, width = 0, height = 0, tagWidth = 0;
	unsigned long font = 0;
	const wchar_t* title = nullptr;
	const wchar_t* tag = nullptr;
	const wchar_t* labels[7]{};
	wchar_t values[7][112]{};
	int valueWidths[7]{};
	COLORREF accent = RGB(103, 212, 193);
};
static const wchar_t* CacheOffloadHudState(const skeeto_cache::Snapshot& s, bool demo) {
	if (demo) return UiText(UiId::CacheHudDemo, L"示例");
	if (!g_cacheOffloadLaunch) return UiText(UiId::CacheHudRestart, L"待重启");
	if (s.reclaiming) return UiText(UiId::CacheHudReclaiming, L"回收中");
	switch (s.status) {
	case skeeto_cache::Status::Ready: return UiText(UiId::CacheHudRunning, L"运行中");
	case skeeto_cache::Status::Starting: return UiText(UiId::CacheHudWaiting, L"等待接口");
	case skeeto_cache::Status::Unsupported: return UiText(UiId::CacheHudUnsupported, L"版本不符");
	case skeeto_cache::Status::Conflict: return UiText(UiId::CacheHudConflict, L"接口改动");
	case skeeto_cache::Status::HostFailed: return UiText(UiId::CacheHudHostFailed, L"宿主离线");
	default: return UiText(UiId::CacheHudUnavailable, L"未就绪");
	}
}
static void CacheOffloadHudRefresh(CacheOffloadHudLayout& c, int sw, int sh, bool demo, DWORD now) {
	c.valid = false; g_cacheHudDirty = false; c.at = now; c.sw = sw; c.sh = sh; c.demo = demo;
	c.english = g_uiEnglish.load(std::memory_order_relaxed);
	c.scale = HudClampScale(g_cacheHudScale);
	c.requestedPx = HudScalePx(g_cacheHudFont, c.scale);
	c.title = UiText(UiId::CacheOffloadTitle, L"缓存搬运");
	const auto s = skeeto_cache::ReadSnapshot();
	c.tag = CacheOffloadHudState(s, demo);
	c.accent = demo || s.status == skeeto_cache::Status::Ready ? RGB(103, 212, 193) : RGB(245, 183, 79);
	c.labels[0] = UiText(UiId::CacheHudCurrent, L"当前外置");
	c.labels[1] = UiText(UiId::CacheHudPeakMoved, L"峰值 / 累计");
	c.labels[2] = UiText(UiId::CacheHudKinds, L"模型 / 动画 / 声音");
	c.labels[3] = UiText(UiId::CacheHudSourceLocked, L"源缓存 / 锁定采样");
	c.labels[4] = UiText(UiId::CacheHudCounts, L"取回 / 失败 / 保留");
	c.labels[5] = UiText(UiId::CacheHudAvReclaimed, L"AV剩余 / VA释放累计");
	c.labels[6] = UiText(UiId::CacheHudTiming, L"维护均 / 峰 / 取回峰");
	const double mb = 1048576.0;
	swprintf_s(c.values[0], UiText(UiId::CacheHudCurrentValue, L"%.2f MB / %u项"),
		demo ? 24.25 : (s.meshBytes + s.animationBytes + s.audioBytes) / mb, demo ? 68u : s.coldItems);
	swprintf_s(c.values[1], L"%.2f / %.2f MB", demo ? 32.50 : s.peakColdBytes / mb, demo ? 45.25 : s.movedBytes / mb);
	swprintf_s(c.values[2], L"%.2f / %.2f / %.2f MB", demo ? 12.50 : s.meshBytes / mb,
		demo ? 8.25 : s.animationBytes / mb, demo ? 3.50 : s.audioBytes / mb);
	const uint64_t resident = uint64_t(s.residentBytes[0]) + s.residentBytes[1] + s.residentBytes[2];
	const uint64_t locked = uint64_t(s.lockedBytes[0]) + s.lockedBytes[1] + s.lockedBytes[2];
	if (demo || (s.boundMask && s.inventoryReady)) swprintf_s(c.values[3], L"%.1f / %.1f MB", demo ? 192.0 : resident / mb, demo ? 96.0 : locked / mb);
	else if(s.boundMask)swprintf_s(c.values[3], L"%.1f / -- MB",resident/mb);
	else wcscpy_s(c.values[3], L"-- / -- MB");
	swprintf_s(c.values[4], L"%u / %u / %u", demo ? 20u : s.restores, demo ? 0u : s.failures, demo ? 12u : s.unsafeItems);
	MEMORYSTATUSEX memory{}; memory.dwLength = sizeof(memory);
	const bool haveAv = !demo && GlobalMemoryStatusEx(&memory) != FALSE;
	if (demo || haveAv) swprintf_s(c.values[5], L"%.0f / %.2f MB", demo ? 960.0 : memory.ullAvailVirtual / mb, demo ? 24.0 : s.moveReleasedVaBytes / mb);
	else swprintf_s(c.values[5], L"-- / %.2f MB", s.moveReleasedVaBytes / mb);
	if (demo || s.timing) swprintf_s(c.values[6], L"%.3f / %.3f / %.3f ms", demo ? 0.015 : s.maintenanceAvgMs,
		demo ? 0.120 : s.maintenancePeakMs, demo ? 0.180 : s.restorePeakMs);
	else wcscpy_s(c.values[6], L"-- / -- / -- ms");
	// Measure with the actual Surface font. A bounded fallback keeps large font
	// settings on screen without recreating fonts on every Paint.
	c.px = c.requestedPx;
	for (int attempt = 0; attempt < 3; ++attempt) {
		c.font = HudAcquireLayoutFont(c.px, &g_cacheHudFontId, &g_cacheHudFontTall, 700);
		if (!c.font) return;
		c.pad = HudScalePx(8, c.scale);
		c.rowH = (g_cacheHudFontTall > c.px ? g_cacheHudFontTall : c.px) + HudScalePx(4, c.scale);
		c.titleH = c.rowH + HudScalePx(6, c.scale);
		int labelW = 0, valueW = SurfTextWFont(c.font, L"1024.00 / 8192.00 MB");
		for (int i = 0; i < 7; ++i) {
			const int lw = SurfTextWFont(c.font, c.labels[i]);
			c.valueWidths[i] = SurfTextWFont(c.font, c.values[i]);
			if (lw > labelW) labelW = lw;
			if (c.valueWidths[i] > valueW) valueW = c.valueWidths[i];
		}
		c.tagWidth = SurfTextWFont(c.font, c.tag);
		c.width = labelW + valueW + c.pad * 3;
		const int titleWidth = SurfTextWFont(c.font, c.title) + c.tagWidth + c.pad * 4;
		if (titleWidth > c.width) c.width = titleWidth;
		c.height = c.pad * 2 + c.titleH + c.rowH * 7;
		const int maxW = sw > 32 ? sw - 32 : sw, maxH = sh > 32 ? sh - 32 : sh;
		if (c.width <= maxW && c.height <= maxH) { c.valid = true; break; }
		if (c.px <= 10) break;
		const float ratioW = float(maxW) / c.width, ratioH = float(maxH) / c.height;
		int next = int(c.px * (ratioW < ratioH ? ratioW : ratioH) * 0.94f);
		if (next >= c.px) next = c.px - 1;
		c.px = next < 10 ? 10 : next;
	}
	g_cacheHudDirty = false;
}
static void CacheOffloadHudPaint() {
	if (!CacheOffloadHudWanted() || !g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || EngDrawingLoading() || !MenuEnsureSurf()) return;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw <= 0 || sh <= 0) return;
	const bool demo = HudMenuPage(kMenuPageCacheOffload) || HudLayoutPeer(g_optCacheOffloadHud, kMenuPageCacheOffload);
	const DWORD now = GetTickCount();
	static CacheOffloadHudLayout c;
	if (g_cacheHudDirty || !c.at || c.sw != sw || c.sh != sh || c.demo != demo
		|| c.english != g_uiEnglish.load(std::memory_order_relaxed)
		|| c.scale != HudClampScale(g_cacheHudScale) || c.requestedPx != HudScalePx(g_cacheHudFont, c.scale)
		|| now - c.at >= 1000u) CacheOffloadHudRefresh(c, sw, sh, demo, now);
	if (!c.valid) return;
	int x = 0, y = 0;
	HudFinalizePos(&g_cacheHudAbs, &g_cacheHudOffX, &g_cacheHudOffY, g_cacheHudAlign,
		sw, sh, c.width, c.height, &x, &y);
	HudPanelShadow(x, y, c.width, c.height);
	HudGlassBody(x, y, c.width, c.height);
	HudSideAccent(x, y, c.height, c.accent, HudScalePx(3, c.scale));
	SurfTextAt(c.font, x + c.pad, y + c.pad, RGB(184, 222, 232), c.title);
	SurfTextAt(c.font, x + c.width - c.pad - c.tagWidth, y + c.pad, c.accent, c.tag);
	for (int i = 0; i < 7; ++i) {
		const int ty = y + c.pad + c.titleH + c.rowH * i;
		SurfTextAt(c.font, x + c.pad, ty, RGB(180, 196, 201), c.labels[i]);
		SurfTextAt(c.font, x + c.width - c.pad - c.valueWidths[i], ty,
			i == 0 ? RGB(119, 228, 208) : RGB(229, 234, 236), c.values[i]);
	}
}
static void SiPresenceHudSample() {
	SiPresenceHudSampleImpl();
}

static COLORREF SiPresenceTotalColor(int count) {
	if (count <= 0) return RGB(196, 204, 208);
	if (count <= 3) return RGB(76, 222, 126);
	// The requested ranges overlap at six; the higher-alert orange tier wins.
	if (count < 6) return RGB(190, 224, 74);
	if (count <= 8) return RGB(248, 154, 58);
	return RGB(190, 112, 238);
}

static COLORREF SiPresenceSmokerColor(int count) {
	return count > 0 ? RGB(238, 78, 82) : RGB(196, 204, 208);
}

static void SiPresenceHudPaint() {
	const bool preview = HudMenuPage(kMenuPageSiPresenceHud);
	if (!HudWantsDraw(g_optSiPresenceTotal || g_optSiPresenceSmoker, kMenuPageSiPresenceHud)) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || !MenuEnsureSurf()) return;
	if (g_optSiPresenceTotal || g_optSiPresenceSmoker) SiPresenceHudSample();
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;
	const bool showTotal = g_optSiPresenceTotal || preview;
	const bool showSmoker = g_optSiPresenceSmoker || preview;
	const int cells = (showTotal ? 1 : 0) + (showSmoker ? 1 : 0);
	if (cells <= 0) return;
	const int sc = HudClampScale(g_siPresenceHudScale);
	const int labelPx = HudScalePx(g_siPresenceHudLayoutFont, sc);
	const int bigPx = HudScalePx(g_siPresenceHudLayoutFont + 12, sc);
	const unsigned long labelFont = HudAcquireLayoutFont(labelPx,
		&g_siPresenceHudFontId, &g_siPresenceHudFontTall, 700);
	const unsigned long bigFont = HudAcquireLayoutFont(bigPx,
		&g_siPresenceHudBigFontId, &g_siPresenceHudBigFontTall, 800);
	if (!labelFont || !bigFont) return;
	const int pad = HudScalePx(7, sc);
	const int titleH = labelPx + HudScalePx(5, sc);
	const int cellW = HudScalePx(92, sc);
	const int bodyH = bigPx + HudScalePx(12, sc);
	const int gap = HudScalePx(3, sc);
	const int panelW = pad * 2 + cells * cellW + (cells - 1) * gap;
	const int panelH = pad * 2 + titleH + bodyH;
	int x = 0, y = 0;
	HudFinalizePos(&g_siPresenceHudAbs, &g_siPresenceHudOffX, &g_siPresenceHudOffY,
		g_siPresenceHudAlign, sw, sh, panelW, panelH, &x, &y);
	const COLORREF cyan = RGB(68, 219, 230);
	HudPanelShadow(x, y, panelW, panelH);
	HudGlassBody(x, y, panelW, panelH);
	// Offset rails and a compact scanner notch intentionally distinguish this
	// card from the rectangular network/memory readouts.
	SurfColor(54, 72, 88, 230);
	SurfFill(x + pad, y + pad + titleH - 1, x + panelW - pad, y + pad + titleH);
	SurfColor(GetRValue(cyan), GetGValue(cyan), GetBValue(cyan), 230);
	SurfFill(x, y, x + panelW - HudScalePx(18, sc), y + HudScalePx(2, sc));
	SurfFill(x + panelW - HudScalePx(13, sc), y, x + panelW, y + HudScalePx(2, sc));
	HudCornerBrackets(x, y, panelW, panelH, HudScalePx(9, sc), cyan, preview ? 220 : 130);
	SurfTextAt(labelFont, x + pad, y + pad, RGB(188, 216, 224), L"THREAT SCAN");
	int cx = x + pad;
	auto cell = [&](const wchar_t* label, int value, COLORREF color) {
		const int cy = y + pad + titleH;
		SurfColor(GetRValue(color), GetGValue(color), GetBValue(color), 34);
		SurfFill(cx, cy, cx + cellW, cy + bodyH);
		SurfColor(GetRValue(color), GetGValue(color), GetBValue(color), 210);
		SurfFill(cx, cy, cx + HudScalePx(2, sc), cy + bodyH);
		SurfTextAt(labelFont, cx + HudScalePx(7, sc), cy + HudScalePx(4, sc), color, label);
		wchar_t valueText[16]{};
		if (g_siPresenceHaveSample || preview)
			swprintf_s(valueText, 16, L"%d", g_siPresenceHaveSample ? value : (label[0] == L'S' ? 1 : 4));
		else
			wcsncpy_s(valueText, 16, L"--", _TRUNCATE);
		const int valueW = SurfTextWFont(bigFont, valueText);
		SurfTextAt(bigFont, cx + cellW - HudScalePx(7, sc) - valueW,
			cy + bodyH - bigPx - HudScalePx(3, sc), color, valueText);
		cx += cellW + gap;
	};
	const int totalForColor = g_siPresenceHaveSample ? g_siPresenceTotal : (preview ? 4 : 0);
	const int smokerForColor = g_siPresenceHaveSample ? g_siPresenceSmokers : (preview ? 1 : 0);
	if (showTotal) cell(UiText(UiId::Text_b1024cf3, L"特感"), g_siPresenceTotal, SiPresenceTotalColor(totalForColor));
	if (showSmoker) cell(L"SMOKER", g_siPresenceSmokers, SiPresenceSmokerColor(smokerForColor));
}

static void HudMatDropAt(int at) {
	if (at < 0 || at >= g_hudMatN) return;
	for (int i = at; i + 1 < g_hudMatN; ++i)
		g_hudMat[i] = g_hudMat[i + 1];
	--g_hudMatN;
	if (g_hudMatN >= 0)
		g_hudMat[g_hudMatN] = {};
	if (g_hudMatHealthCursor > g_hudMatN)
		g_hudMatHealthCursor = 0;
	HudMatRebuildHot();
}

static void HudMatInvalidateAt(int at, bool allowRetry = true) {
	if (at < 0 || at >= g_hudMatN || g_hudMat[at].id < 0) return;
	g_hudMat[at].id = -1;
	g_hudMat[at].tw = 0;
	g_hudMat[at].th = 0;
	g_hudMat[at].probeMisses = 0;
	g_hudMat[at].rebind = false;
	g_hudMat[at].retry = allowRetry
		&& g_hudMatCreateTotal < kHudMatCreateLifeMax
		&& g_hudMatInvalidations < kHudMatSoftInvalidationLifeMax;
	++g_hudMatInvalidations;
	HudMatRebuildHot();
}

void HudMatOnLevelInit() {
	// Renew soft-invalidation budget each map. Stale IDs after materialsystem rebuild
	// must re-DrawSetTextureFile; never keep a known-suspect handle for Paint.
	g_hudMatInvalidations = 0;
	int w = 0;
	for (int r = 0; r < g_hudMatN; ++r) {
		HudMatCache& e = g_hudMat[r];
		if (e.id < 0) {
			if (!e.retry) continue; // permanent miss — drop
		} else {
			e.rebind = true;
			e.tw = 0;
			e.th = 0;
			e.probeMisses = 0;
		}
		if (w != r) g_hudMat[w] = e;
		++w;
	}
	g_hudMatN = w;
	HudMatRebuildHot();
}

static void SurfHudMatQuerySize(int texId, int* tw, int* th);

static bool HudMatRebindAt(int at) {
	if (at < 0 || at >= g_hudMatN) return false;
	HudMatCache& c = g_hudMat[at];
	if (c.id < 0 || !c.name[0] || !g_surf) return false;
	using SetFileFn = void(__thiscall*)(void*, int, const char*, int, bool);
	auto setFile = (SetFileFn)VGet(g_surf, kVmtSurfDrawSetTextureFile);
	if (!setFile || !IsExec((void*)setFile)) return false;
	__try {
		setFile(g_surf, c.id, c.name, 0, false);
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		++g_surfTextureCreateFaults;
		return false;
	}
	int tw = 0, th = 0;
	SurfHudMatQuerySize(c.id, &tw, &th);
	if (tw <= 0 || th <= 0) return false;
	c.tw = tw;
	c.th = th;
	c.probeMisses = 0;
	c.rebind = false;
	c.retry = false;
	HudMatIndexOne(at);
	return true;
}

static void SurfTextureFaulted(int id, bool immediate) {
	if (id < 0) return;
	if (id == g_texXhairId) {
		if (immediate) g_texXhairProbeMisses = 1;
		if (++g_texXhairProbeMisses >= 2) {
			++g_texXhairRecoveryCount;
			++g_texXhairInvalidations;
			if (g_texXhairRecoveryCount > kTexXhairRecoveryMax) {
				strncpy(g_texXhairRecoveryBlockedMat, g_texXhairBound,
					sizeof(g_texXhairRecoveryBlockedMat) - 1);
				g_texXhairRecoveryBlockedMat[sizeof(g_texXhairRecoveryBlockedMat) - 1] = 0;
			}
			g_texXhairId = -1;
			g_texXhairW = g_texXhairH = 0;
			g_texXhairProbeMisses = 0;
			g_texXhairProbeAt = 0;
		}
		return;
	}
	for (int i = 0; i < g_hudMatN; ++i) {
		if (g_hudMat[i].id != id) continue;
		if (g_hudMat[i].probeMisses == 0xFFu)
			g_hudMat[i].probeMisses = 0;
		// Draw faults must drop on first hit: L4N Crashpad can terminate before a second miss.
		if (immediate) g_hudMat[i].probeMisses = 1;
		if (++g_hudMat[i].probeMisses >= 2)
			HudMatInvalidateAt(i, true);
		return;
	}
}

static void SurfHudMatQuerySize(int texId, int* tw, int* th) {
	SurfTryTextureSize(texId, tw, th);
}

int SurfHudMat(const char* mat) {
	if (!mat || !mat[0] || !g_surf) return -1;
	g_hudMatTouchedThisPaint = true;
	const unsigned nameHash = HudMatNameHash(mat);
	const int hot = g_hudMatNameHot[nameHash & (kHudMatMax - 1)] - 1;
	int found = -1;
	if (hot >= 0 && hot < g_hudMatN && !_stricmp(g_hudMat[hot].name, mat))
		found = hot;
	if (found < 0) {
		for (int i = 0; i < g_hudMatN; ++i) {
			if (!_stricmp(g_hudMat[i].name, mat)) {
				found = i;
				break;
			}
		}
	}
	if (found >= 0) {
		g_hudMatNameHot[nameHash & (kHudMatMax - 1)] = found + 1;
		if (g_hudMat[found].id >= 0 && g_hudMat[found].rebind) {
			if (HudMatRebindAt(found))
				return g_hudMat[found].id;
			// Rebind failed (surface/material not ready): drop id, allow bounded recreate.
			HudMatInvalidateAt(found, true);
			return -1;
		}
		if (!(g_hudMat[found].id < 0 && g_hudMat[found].retry))
			return g_hudMat[found].id;
		// A previously valid engine texture failed two independent probes. Remove
		// only that cache record so the existing bounded creation path can lazily
		// bind it again; never wipe the whole process-lifetime cache.
		HudMatDropAt(found);
	}
	if (g_hudMatN >= kHudMatMax) {
		int w = 0;
		for (int r = 0; r < g_hudMatN; ++r) {
			if (g_hudMat[r].id >= 0) {
				if (w != r) g_hudMat[w] = g_hudMat[r];
				++w;
			}
		}
		g_hudMatN = w;
		HudMatRebuildHot();
	}
	if (g_hudMatN >= kHudMatMax) {
		static int s_fullLog = 3;
		if (s_fullLog > 0) {
			--s_fullLog;
			Log("teamhud mat cache full, skip %s", mat);
		}
		return -1;
	}
	// Spread CreateNewTextureID across frames — do NOT permanently miss (breaks mod icons).
	if (g_hudMatCreatesThisPaint >= kHudMatCreateBudgetPerPaint)
		return -1;

	if (g_hudMatCreateTotal >= kHudMatCreateLifeMax) {
		static int s_capLog = 8;
		if (s_capLog > 0) {
			--s_capLog;
			Log("teamhud mat create life-cap, keep existing IDs and skip %s", mat);
		}
		// Never repoint a live texture ID at another material. Cache this fallback
		// until the next soft flush so Paint does not retry filesystem work every frame.
		HudMatCache& c = g_hudMat[g_hudMatN++];
		strncpy(c.name, mat, 71);
		c.name[71] = 0;
		c.id = -1;
		c.tw = 0;
		c.th = 0;
		c.probeMisses = 0;
		c.retry = false;
		c.rebind = false;
		HudMatIndexOne(g_hudMatN - 1);
		return -1;
	}

	char vmt[96]{};
	snprintf(vmt, sizeof(vmt), "materials/%s.vmt", mat);
	if (!DlcGameFileExists(vmt)) {
		static int s_missLog = 8;
		if (s_missLog > 0) {
			--s_missLog;
			Log("teamhud mat miss %s", mat);
		}
		HudMatCache& c = g_hudMat[g_hudMatN++];
		strncpy(c.name, mat, 71);
		c.name[71] = 0;
		c.id = -1;
		c.tw = 0;
		c.th = 0;
		c.probeMisses = 0;
		c.retry = false;
		c.rebind = false;
		HudMatIndexOne(g_hudMatN - 1);
		return -1;
	}

	int id = -1;
	int tw = 0, th = 0;
	using CreateIdFn = int(__thiscall*)(void*, bool);
	using SetFileFn = void(__thiscall*)(void*, int, const char*, int, bool);
	auto createId = (CreateIdFn)VGet(g_surf, kVmtSurfCreateNewTextureID);
	auto setFile = (SetFileFn)VGet(g_surf, kVmtSurfDrawSetTextureFile);
	if (createId && setFile && IsExec((void*)createId) && IsExec((void*)setFile)) {
		__try {
			const int created = createId(g_surf, false);
			if (created >= 0) {
				// The engine allocated this ID even if the following bind faults.
				// Charge both budgets immediately so SEH cannot bypass the life cap.
				++g_hudMatCreatesThisPaint;
				++g_hudMatCreateTotal;
				setFile(g_surf, created, mat, 0, false);
				id = created;
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			++g_surfTextureCreateFaults;
			id = -1;
		}
	}
	if (id >= 0)
		SurfHudMatQuerySize(id, &tw, &th);
	HudMatCache& c = g_hudMat[g_hudMatN++];
	strncpy(c.name, mat, 71);
	c.name[71] = 0;
	c.id = id;
	c.tw = tw;
	c.th = th;
	c.probeMisses = 0;
	c.retry = false;
	c.rebind = false;
	HudMatIndexOne(g_hudMatN - 1);
	return id;
}

bool SurfHudMatSize(int id, int* tw, int* th) {
	if (id < 0 || !tw || !th) return false;
	const int hot = g_hudMatIdHot[(unsigned)id & (kHudMatMax - 1)] - 1;
	if (hot >= 0 && hot < g_hudMatN && g_hudMat[hot].id == id
		&& g_hudMat[hot].tw > 0 && g_hudMat[hot].th > 0) {
		*tw = g_hudMat[hot].tw;
		*th = g_hudMat[hot].th;
		return true;
	}
	for (int i = 0; i < g_hudMatN; ++i) {
		if (g_hudMat[i].id == id && g_hudMat[i].tw > 0 && g_hudMat[i].th > 0) {
			g_hudMatIdHot[(unsigned)id & (kHudMatMax - 1)] = i + 1;
			*tw = g_hudMat[i].tw;
			*th = g_hudMat[i].th;
			return true;
		}
	}
	return SurfTryTextureSize(id, tw, th);
}


static void SurfHudMatHealthTick() {
	if (!g_surf || g_hudMatN <= 0) return;
	const DWORD now = GetTickCount();
	if (g_hudMatHealthAt && (LONG)(now - g_hudMatHealthAt) < 0)
		return;
	g_hudMatHealthAt = now + 250u;
	for (int checked = 0; checked < g_hudMatN; ++checked) {
		if (g_hudMatHealthCursor >= g_hudMatN)
			g_hudMatHealthCursor = 0;
		const int at = g_hudMatHealthCursor++;
		HudMatCache& c = g_hudMat[at];
		if (c.id < 0 || c.tw <= 0 || c.th <= 0 || c.probeMisses == 0xFFu) continue;
		int tw = 0, th = 0;
		if (SurfTryTextureSize(c.id, &tw, &th) && tw == c.tw && th == c.th) {
			c.probeMisses = 0;
			return;
		}
		if (++c.probeMisses < 2)
			return;
		if (g_hudMatCreateTotal >= kHudMatCreateLifeMax
			|| g_hudMatInvalidations >= kHudMatSoftInvalidationLifeMax) {
			// Fail closed: never keep a known-suspect id for Paint. Crashpad may kill
			// on first-chance AV before SurfDrawTexturedUv's __try can retire it.
			const int staleId = c.id;
			char staleName[72]{};
			strncpy(staleName, c.name, sizeof(staleName) - 1);
			c.id = -1;
			c.tw = 0;
			c.th = 0;
			c.probeMisses = 0xFFu;
			c.retry = false;
			c.rebind = false;
			HudMatRebuildHot();
			Log("hud texture retired id=%d mat=%s (soft-cap)", staleId, staleName);
			return;
		}
		const int staleId = c.id;
		char staleName[72]{};
		strncpy(staleName, c.name, sizeof(staleName) - 1);
		HudMatInvalidateAt(at);
		Log("hud texture soft-invalidated id=%d mat=%s", staleId, staleName);
		return;
	}
}

// Mod VTFs often pack "big icon + small icon" side-by-side. Drawing UV 0–1 = ghost duplicate.
