static const char* WeaponEntModelNameDirect(int wepIdx) {
	if (wepIdx <= 0 || wepIdx >= 2048 || g_offModelIndex < 0 || g_offModelIndex > 0x4000) return nullptr;
	void* wep = EntGet(wepIdx);
	if (!EntReadable(wep)) return nullptr;
	int* pm = (int*)((uint8_t*)wep + g_offModelIndex);
	if (!PtrCommitted(pm) || *pm <= 0) return nullptr;
	return TeamHudModelNameInner(*pm, true);
}

bool ModelPathIsHuntRifle(const char* model) {
	if (!model || !model[0]) return false;
	return TeamHudCnIHas(model, "huntingrifle")
		|| TeamHudCnIHas(model, "hunting_rifle")
		|| TeamHudCnIHas(model, "sniper_hunting")
		|| TeamHudCnIHas(model, "mini14")
		|| TeamHudCnIHas(model, "w_sniper_mini");
}

static bool LocalViewModelIsHuntRifle(void* me) {
	if (!me || !EntReadable(me) || g_offViewModel < 0 || g_offViewModel > 0x4000) return false;
	int* ph = (int*)((uint8_t*)me + g_offViewModel);
	if (!PtrCommitted(ph)) return false;
	const int idx = EntIndexFromHandle(*ph);
	if (idx <= 0 || idx >= 2048) return false;
	return ModelPathIsHuntRifle(WeaponEntModelNameDirect(idx));
}

bool WeaponEntIsHuntRifle(int wepIdx) {
	if (wepIdx <= 0 || wepIdx >= 2048) return false;
	if (TeamHudLocalIsSpectating()) return false;
	const char* cn = EntNetClassName(wepIdx);
	if (TeamHudIsHuntRifle(cn)) return true;
	if (ModelPathIsHuntRifle(WeaponEntModelNameDirect(wepIdx))) return true;
	const int local = EngLocal();
	if (local <= 0) return false;
	void* me = EntGet(local);
	if (!EntReadable(me) || g_offActiveWeapon < 0 || g_offActiveWeapon > 0x4000) return false;
	int* ph = (int*)((uint8_t*)me + g_offActiveWeapon);
	if (!PtrCommitted(ph)) return false;
	const int h = *ph;
	const int active = EntIndexFromHandle(h);
	if (active != wepIdx) return false;
	return LocalViewModelIsHuntRifle(me);
}






