static int GlowStateMenuIndex(int kind) {
	if (kind < 0 || kind >= kGlowStateCvarCount) return 0;
	const int color = g_glowStateColor[kind];
	if (color < 0) return 0;
	for (int i = 0; i < kSurvivorGlowPaletteCount; ++i)
		if (color == kSurvivorGlowPalette[i]) return i + 1;
	return -1;
}

static void GlowStateDescribeW(int kind, wchar_t* out, size_t cap) {
	if (!out || cap == 0) return;
	out[0] = 0;
	if (kind < 0 || kind >= kGlowStateCvarCount) return;
	const int color = g_glowStateColor[kind];
	const int idx = GlowStateMenuIndex(kind);
	if (idx == 0) {
		wcsncpy(out, UiText(UiId::Text_a90d2811, L"启用前原值"), cap - 1);
		out[cap - 1] = 0;
		return;
	}
	const int r = color & 0xFF, g = (color >> 8) & 0xFF, b = (color >> 16) & 0xFF;
	if (idx > 0)
		swprintf_s(out, cap, L"%s #%02X%02X%02X", kSurvivorGlowPaletteNames[idx - 1], r, g, b);
	else
		swprintf_s(out, cap, UiText(UiId::Text_8d6db2d8, L"自定义 #%02X%02X%02X"), r, g, b);
}

static void GlowStateCycleSelected(int delta) {
	if (g_glowStateSel < 0 || g_glowStateSel >= kGlowStateCvarCount) g_glowStateSel = 0;
	const int count = kSurvivorGlowPaletteCount + 1; // game original + shared colors
	int idx = GlowStateMenuIndex(g_glowStateSel);
	if (idx < 0) idx = 1;
	idx = (idx + (delta < 0 ? -1 : 1) + count) % count;
	g_glowStateColor[g_glowStateSel] = idx == 0 ? -1 : kSurvivorGlowPalette[idx - 1];
	ClientUxApplyForceCvars(true);
	SaveSettings();
	EngClientCmd("play buttons/button14");
}

static int SurvivorGlowMenuIndex(int character) {
	if (character < 0 || character >= kTeamHudCharMax) return 0;
	const int color = g_survivorGlowColor[character];
	if (color < 0) return 0;
	if (color == kSurvivorGlowPreset[character]) return 1;
	for (int i = 0; i < kSurvivorGlowPaletteCount; ++i)
		if (color == kSurvivorGlowPalette[i]) return i + 2;
	return -1; // exact console-command custom color
}

static void SurvivorGlowDescribeW(int character, wchar_t* out, size_t cap) {
	if (!out || cap == 0) return;
	out[0] = 0;
	if (character < 0 || character >= kTeamHudCharMax) return;
	const int color = g_survivorGlowColor[character];
	const int idx = SurvivorGlowMenuIndex(character);
	if (idx == 0) {
		wcsncpy(out, UiText(UiId::Text_69c11909, L"服务器默认"), cap - 1);
		out[cap - 1] = 0;
		return;
	}
	const int r = color & 0xFF, g = (color >> 8) & 0xFF, b = (color >> 16) & 0xFF;
	if (idx == 1)
		swprintf_s(out, cap, UiText(UiId::Text_ee61609c, L"SKT预设 #%02X%02X%02X"), r, g, b);
	else if (idx >= 2)
		swprintf_s(out, cap, L"%s #%02X%02X%02X", kSurvivorGlowPaletteNames[idx - 2], r, g, b);
	else
		swprintf_s(out, cap, UiText(UiId::Text_8d6db2d8, L"自定义 #%02X%02X%02X"), r, g, b);
}

static void SurvivorGlowCycleSelected(int delta) {
	if (g_survivorGlowSel < 0 || g_survivorGlowSel >= kTeamHudCharMax) g_survivorGlowSel = 0;
	const int count = kSurvivorGlowPaletteCount + 2; // server default + SKT preset + shared colors
	int idx = SurvivorGlowMenuIndex(g_survivorGlowSel);
	if (idx < 0) idx = 1; // custom RGB joins the cycle next to the character preset
	idx = (idx + (delta < 0 ? -1 : 1) + count) % count;
	if (idx == 0) g_survivorGlowColor[g_survivorGlowSel] = -1;
	else if (idx == 1) g_survivorGlowColor[g_survivorGlowSel] = kSurvivorGlowPreset[g_survivorGlowSel];
	else g_survivorGlowColor[g_survivorGlowSel] = kSurvivorGlowPalette[idx - 2];
	SurvivorGlowConfigChanged();
	SaveSettings();
}

static void SurvivorGlowAdjustRender(int delta) {
	int* value = g_survivorGlowRenderSel == 1
		? &g_survivorGlowBlurPct : &g_survivorGlowBrightnessPct;
	*value = ClampAdd(*value, delta < 0 ? -10 : 10, 50, 200);
	ClientUxApplyForceCvars(true);
	SaveSettings();
	Log("survivor glow render: brightness=%d blur=%d selected=%d",
		g_survivorGlowBrightnessPct, g_survivorGlowBlurPct, g_survivorGlowRenderSel);
	EngClientCmd("play buttons/button14");
}

static void __fastcall Hooked_SurvivorGetGlowColor(void* ecx, void*,
	float* r, float* g, float* b, float* a) {
	if (g_origSurvivorGetGlowColor)
		g_origSurvivorGetGlowColor(ecx, r, g, b, a);
	if (!ecx || !r || !g || !b || !a || g_worldHudRealism || !SkeetoFeaturesOn()) return;
	for (int i = 0; i < kTeamHudMax; ++i) {
		if (g_survivorGlowHookEnt[i] != ecx) continue;
		const int color = g_survivorGlowHookColor[i];
		if (color >= 0) {
			*r = (float)(color & 0xFF) / 255.f;
			*g = (float)((color >> 8) & 0xFF) / 255.f;
			*b = (float)((color >> 16) & 0xFF) / 255.f;
		}
		// The stock function keeps each survivor glow registered and expresses its
		// LOS/distance/state fade through alpha. Reusing this existing callback is
		// constant work and avoids entity writes or rebuilding CGlowProperty.
		if (g_optSurvivorGlowAlways)
			*a = 1.f;
		return;
	}
}

static bool SurvivorGlowUnhook() {
	memset(g_survivorGlowHookEnt, 0, sizeof(g_survivorGlowHookEnt));
	memset(g_survivorGlowHookColor, 0, sizeof(g_survivorGlowHookColor));
	bool restored = false;
	if (g_survivorGlowVtable && g_origSurvivorGetGlowColor) {
		void** slot = &g_survivorGlowVtable[kSurvivorGetGlowColorVmt];
		if (PtrCommitted(slot) && *slot == (void*)&Hooked_SurvivorGetGlowColor)
			restored = VtProtectWrite(slot, (void*)g_origSurvivorGetGlowColor, nullptr);
	}
	// If another module chained after us, keep the trampoline alive; our empty
	// cache makes the callback a transparent pass-through until that chain leaves.
	if (restored || !g_survivorGlowVtable || !PtrCommitted(g_survivorGlowVtable)) {
		g_survivorGlowVtable = nullptr;
		g_origSurvivorGetGlowColor = nullptr;
		return true;
	}
	return false;
}

static bool SurvivorGlowEnsureHook(void* e) {
	if (!e || !EntReadable(e)) return false;
	void** vt = *(void***)e;
	if (!vt || !PtrCommitted(&vt[kSurvivorGetGlowColorVmt])) return false;
	if (g_survivorGlowVtable == vt && g_origSurvivorGetGlowColor) return true;
	if (!SurvivorGlowUnhook()) return false;
	void* original = vt[kSurvivorGetGlowColorVmt];
	if (!original || !IsExec(original)) return false;
	void* prev = nullptr;
	if (!VtProtectWrite(&vt[kSurvivorGetGlowColorVmt], (void*)&Hooked_SurvivorGetGlowColor, &prev))
		return false;
	if (!prev || !IsExec(prev) || prev == (void*)&Hooked_SurvivorGetGlowColor) {
		VtProtectWrite(&vt[kSurvivorGetGlowColorVmt], original, nullptr);
		return false;
	}
	g_survivorGlowVtable = vt;
	g_origSurvivorGetGlowColor = (SurvivorGetGlowColorFn)prev;
	Log("survivor glow color hook installed vt=%p orig=%p slot=%d", vt, prev, kSurvivorGetGlowColorVmt);
	return true;
}

static void SurvivorGlowConfigChanged() {
	g_survivorGlowNextAt = 0;
	if (!SurvivorGlowWanted()) SurvivorGlowUnhook();
	// Renderer Cvars are owned only while Skeeto is actively providing survivor
	// glow behavior. Dropping the last custom color/always-on option restores the
	// exact values captured before Skeeto touched them.
	ClientUxApplyForceCvars(true);
}

static void SurvivorGlowTick(bool force) {
	static bool hookFailLogged = false;
	// Other custom HUDs can enter the shared Paint block while survivor glow is
	// untouched. With no requested colors and no installed hook, there is no
	// state to clear or restore.
	const bool wanted = SurvivorGlowWanted();
	if (!wanted && !g_survivorGlowVtable && !g_origSurvivorGetGlowColor)
		return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()
		|| !g_engine || !EngInGame() || EngDrawingLoading() || g_worldHudRealism
		|| !wanted) {
		SurvivorGlowUnhook();
		return;
	}
	const DWORD now = GetTickCount();
	if (!force && g_survivorGlowNextAt && (LONG)(now - g_survivorGlowNextAt) < 0) return;
	g_survivorGlowNextAt = now + 250;
	void* first = nullptr;
	for (int i = 0; i < kTeamHudMax; ++i) {
		const TeamHudSlot& s = g_teamHudSlots[i];
		if (!s.present || s.isLocal || s.dead || s.ent <= 0 || s.ent > 32
			|| s.character < 0 || s.character >= kTeamHudCharMax) continue;
		if (g_survivorGlowColor[s.character] < 0 && !g_optSurvivorGlowAlways) continue;
		void* e = EntGet(s.ent);
		if (!e || !EntReadable(e)) continue;
		first = e;
		break;
	}
	if (!first) {
		SurvivorGlowUnhook();
		hookFailLogged = false;
		return;
	}
	if (!SurvivorGlowEnsureHook(first)) {
		memset(g_survivorGlowHookEnt, 0, sizeof(g_survivorGlowHookEnt));
		if (!hookFailLogged) {
			hookFailLogged = true;
			Log("WARN: survivor glow color hook install failed");
		}
		return;
	}
	hookFailLogged = false;
	memset(g_survivorGlowHookEnt, 0, sizeof(g_survivorGlowHookEnt));
	memset(g_survivorGlowHookColor, 0, sizeof(g_survivorGlowHookColor));
	int out = 0;
	for (int i = 0; i < kTeamHudMax && out < kTeamHudMax; ++i) {
		const TeamHudSlot& s = g_teamHudSlots[i];
		if (!s.present || s.isLocal || s.dead || s.ent <= 0 || s.ent > 32
			|| s.character < 0 || s.character >= kTeamHudCharMax) continue;
		const int color = g_survivorGlowColor[s.character];
		if (color < 0 && !g_optSurvivorGlowAlways) continue;
		void* e = EntGet(s.ent);
		if (!e || !EntReadable(e)) continue;
		g_survivorGlowHookEnt[out] = e;
		g_survivorGlowHookColor[out] = color;
		++out;
	}
}





















// Cheap local-only control edge tracker. Five handle reads at most every 50 ms,
// only while the rescue notice option is enabled; no player/entity scan.














// Close-range kill emblems need to read clearly even at 1080p. The optional
// global resolution scale still applies on top for 1440p/4K users.




















void StatusHudNameId(wchar_t* out, int outN, const wchar_t* name, int uid, bool showUid) {
	if (!out || outN <= 0) return;
	const wchar_t* n = (name && name[0]) ? name : L"?";
	if (showUid && uid > 0) swprintf_s(out, outN, L"%s（%d）", n, uid);
	else swprintf_s(out, outN, L"%s", n);
}




static void FinaleHudEnsureFonts() {
	ClampFinaleHud();
	const int flags = kFontFlagAntiAlias | kFontFlagDropShadow | kFontFlagOutline;
	const int subFlags = kFontFlagAntiAlias | kFontFlagDropShadow;
	int sm = g_finaleHudFont * 11 / 20;
	if (sm < 12) sm = 12;
	const int mainWant = HudFontPx(g_finaleHudFont), smWant = HudFontPx(sm);
	if (!g_finaleHudFontId || g_finaleHudFontTall != mainWant) {
		unsigned long f = SurfMakeYahei(mainWant, 800, flags);
		if (f) { g_finaleHudFontId = f; g_finaleHudFontTall = mainWant; }
	}
	if (!g_finaleHudFontSmId || g_finaleHudFontSmTall != smWant) {
		unsigned long f = SurfMakeYahei(smWant, 650, subFlags);
		if (f) { g_finaleHudFontSmId = f; g_finaleHudFontSmTall = smWant; }
	}
}



static float AdrenDurationCvar() {
	void* var = CvarFind("adrenaline_duration");
	if (!var) return 15.f;
	void* parent = CvarParent(var);
	if (!parent || !PtrCommitted(parent)) return 15.f;
	uint8_t* p = (uint8_t*)parent;
	if (!PtrCommitted(p + 0x2C)) return 15.f;
	const float f = *(float*)(p + 0x2C);
	if (f >= 1.f && f <= 120.f) return f;
	return 15.f;
}

static void AdrenHudInvalidateFont() {
	g_adrenHudFontId = 0;
	g_adrenHudFontTall = 0;
	g_adrenHudFontSmId = 0;
	g_adrenHudFontSmTall = 0;
}

static void AdrenHudEnsureFonts() {
	ClampAdrenHud();
	const int flags = kFontFlagAntiAlias | kFontFlagDropShadow | kFontFlagOutline;
	int sm = g_adrenHudFont * 11 / 20;
	if (sm < 14) sm = 14;
	const int mainWant = HudFontPx(g_adrenHudFont), smWant = HudFontPx(sm);
	if (!g_adrenHudFontId || g_adrenHudFontTall != mainWant) {
		unsigned long f = SurfMakeYahei(mainWant, 800, flags);
		if (f) { g_adrenHudFontId = f; g_adrenHudFontTall = mainWant; }
	}
	if (!g_adrenHudFontSmId || g_adrenHudFontSmTall != smWant) {
		unsigned long f = SurfMakeYahei(smWant, 650, flags);
		if (f) { g_adrenHudFontSmId = f; g_adrenHudFontSmTall = smWant; }
	}
}

// Local estimate — stock L4D2 does not replicate an adrenaline CountdownTimer.
static bool g_adrenWas = false;
static bool g_adrenRefresh = false; // set on local adrenaline_used (re-inject while active)
static float g_adrenEndLocal = 0.f;
static float g_adrenDurLocal = 15.f;

// Event thread / HandleEvent only. Paint consumes via AdrenHudSample.
static void AdrenHudOnLocalUsed() {
	g_adrenRefresh = true;
}

// Local player only — no entity-table scan.
// Stock L4D2 only replicates m_bAdrenalineActive (no CountdownTimer recvprop).
// Duration is always local: adrenaline_duration cvar + adrenaline_used refresh.
static bool AdrenHudSample(float* remainOut, float* durOut) {
	if (!remainOut || !durOut) return false;
	*remainOut = 0.f;
	*durOut = AdrenDurationCvar();
	if (!g_entlist || g_offAdrenalineActive < 0 || g_offAdrenalineActive > 0x4000)
		return false;
	const int local = EngLocal();
	if (local <= 0) return false;
	void* me = EntGet(local);
	if (!EntReadable(me)) return false;
	const uint8_t* base = (const uint8_t*)me;
	if (!PtrCommitted((void*)(base + g_offAdrenalineActive))) return false;
	const bool active = (*(const unsigned char*)(base + g_offAdrenalineActive) != 0);
	const float now = EngClientCurTime();

	if (active) {
		float rem = 0.f;
		float dur = AdrenDurationCvar();
		if (!g_adrenWas || g_adrenRefresh) {
			// Fresh inject, or re-inject while still active (bool stays true).
			g_adrenDurLocal = dur;
			g_adrenEndLocal = now + dur;
			g_adrenRefresh = false;
			rem = dur;
		} else {
			rem = g_adrenEndLocal - now;
			dur = g_adrenDurLocal;
		}
		g_adrenWas = true;
		if (rem < 0.f) rem = 0.f;
		if (dur < 0.5f) dur = AdrenDurationCvar();
		*remainOut = rem;
		*durOut = dur;
		return rem > 0.02f;
	}
	g_adrenWas = false;
	g_adrenRefresh = false;
	g_adrenEndLocal = 0.f;
	return false;
}

static void AdrenHudPaint() {
	const bool preview = HudMenuPage(27);
	if (IdleSwapDeferEntityHud(preview)) return;
	if (!HudWantsDraw(g_optAdrenHud, 27)) return;
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (!SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || EngDrawingLoading()) return;
	if (!MenuEnsureSurf()) return;
	AdrenHudEnsureFonts();
	if (!g_adrenHudFontId) return;

	float remain = 0.f, dur = 15.f;
	bool on = AdrenHudSample(&remain, &dur);
	if ((preview || HudLayoutPeer(g_optAdrenHud, 27)) && !on) {
		on = true;
		remain = 9.4f;
		dur = 15.f;
	}
	if (!on) return;

	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;

	const int sc = g_adrenHudScale;

	float frac = (dur > 0.01f) ? (remain / dur) : 0.f;
	if (frac < 0.f) frac = 0.f;
	if (frac > 1.f) frac = 1.f;
	const bool urgent = remain < 4.f;
	const DWORD tick = GetTickCount();
	const float pulse = 0.55f + 0.45f * (0.5f + 0.5f * sinf((float)tick * 0.011f));

	const int padX = HudScalePx(10, sc);
	const int padY = HudScalePx(8, sc);
	const int ampW = 18;
	const int ampH = 52;
	const int layoutMainPx = HudScalePx(g_adrenHudLayoutFont, sc);
	const int layoutSmPx = HudScalePx(HudSmLayoutBase(g_adrenHudLayoutFont), sc);
	unsigned long layoutMainFont = HudAcquireLayoutFont(layoutMainPx, &g_adrenLayoutFontId, &g_adrenLayoutFontPx, 800);
	unsigned long layoutSmFont = HudAcquireLayoutFont(layoutSmPx, &g_adrenLayoutFontSmId, &g_adrenLayoutFontSmPx, 650);
	const int h1 = layoutMainPx + 2;
	const int h2 = layoutSmPx + 2;
	const int ecgH = 14;
	const int gap = 12;
	wchar_t timeBuf[24]{};
	if (remain >= 10.f)
		swprintf_s(timeBuf, 24, L"%.0f", remain);
	else
		swprintf_s(timeBuf, 24, L"%.1f", remain);
	const int timeW = layoutMainFont ? SurfTextWFont(layoutMainFont, timeBuf) : 0;
	const int labW = layoutSmFont ? SurfTextWFont(layoutSmFont, UiText(UiId::Text_d8df1ca7, L"肾上腺素")) : 64;
	const int rightW = (timeW > labW ? timeW : labW) + 8;
	const int panelW = padX * 2 + ampW + gap + rightW;
	const int panelH = padY * 2 + (ampH > (h2 + 4 + h1 + 4 + ecgH) ? ampH : (h2 + 4 + h1 + 4 + ecgH));

	int x = 0, y = 0;
	HudFinalizePos(&g_adrenHudAbs, &g_adrenHudOffX, &g_adrenHudOffY, g_adrenHudAlign, sw, sh, panelW, panelH, &x, &y);

	const int ar = urgent ? 255 : 255;
	const int ag = urgent ? (int)(72 + 40 * pulse) : 196;
	const int ab = urgent ? (int)(140 + 40 * pulse) : 64;
	const int aGlow = (int)(70 + 50 * pulse);

	// Soft dark plate — not HudGlassPanel / left-stripe family.
	SurfColor(6, 10, 16, 150);
	SurfFill(x, y, x + panelW, y + panelH);
	SurfColor(ar, ag, ab, aGlow);
	SurfOutline(x, y, x + panelW, y + panelH);
	SurfColor(ar, ag, ab, 28);
	SurfFill(x + 1, y + 1, x + panelW - 1, y + 3);

	// Ampoule body (vertical serum).
	const int ax0 = x + padX;
	const int ay0 = y + (panelH - ampH) / 2;
	const int ax1 = ax0 + ampW;
	const int ay1 = ay0 + ampH;
	SurfColor(255, 255, 255, 28);
	SurfFill(ax0 + 2, ay0, ax1 - 2, ay0 + 4); // cap
	SurfColor(ar, ag, ab, 200);
	SurfOutline(ax0, ay0 + 4, ax1, ay1);
	SurfColor(12, 18, 26, 210);
	SurfFill(ax0 + 2, ay0 + 6, ax1 - 2, ay1 - 2);
	const int liquidH = (int)((ampH - 12) * frac + 0.5f);
	if (liquidH > 0) {
		const int ly1 = ay1 - 2;
		const int ly0 = ly1 - liquidH;
		SurfColor(urgent ? 255 : 64, urgent ? 90 : 220, urgent ? 160 : 255, 210);
		SurfFill(ax0 + 3, ly0, ax1 - 3, ly1);
		SurfColor(255, 255, 255, 70);
		SurfFill(ax0 + 4, ly0, ax0 + 7, ly1); // highlight
	}
	// Needle tip
	SurfColor(ar, ag, ab, 220);
	SurfLine(ax0 + ampW / 2, ay1, ax0 + ampW / 2, ay1 + 4);

	const int tx = ax1 + gap;
	int ty = y + padY;
	if (g_adrenHudFontSmId)
		SurfTextAt(g_adrenHudFontSmId, tx, ty, RGB(ar, ag, ab), UiText(UiId::Text_d8df1ca7, L"肾上腺素"));
	ty += h2 + 2;
	SurfTextAt(g_adrenHudFontId, tx, ty, RGB(255, 244, 220), timeBuf);
	if (g_adrenHudFontSmId) {
		const int secW = SurfTextWFont(g_adrenHudFontSmId, UiText(UiId::Text_73d18cc8, L"秒"));
		SurfTextAt(g_adrenHudFontSmId, tx + timeW + 4, ty + (h1 - h2) / 2, RGB(200, 210, 220), UiText(UiId::Text_73d18cc8, L"秒"));
		(void)secW;
	}
	ty += h1 + 2;

	// ECG trace — short polyline under the clock.
	const int ecgW = rightW;
	const int ey = ty + ecgH / 2;
	const int ex0 = tx;
	const int phase = (int)(tick / 28) % (ecgW > 8 ? ecgW : 8);
	SurfColor(ar, ag, ab, 90);
	SurfFill(ex0, ey, ex0 + ecgW, ey + 1);
	SurfColor(ar, ag, ab, 230);
	int px = ex0;
	int py = ey;
	for (int i = 0; i < ecgW; i += 3) {
		const int t = (i + phase) % 36;
		int ny = ey;
		if (t == 10) ny = ey - 7;
		else if (t == 13) ny = ey + 5;
		else if (t == 16) ny = ey - 2;
		else if (t == 18) ny = ey;
		const int nx = ex0 + i;
		SurfLine(px, py, nx, ny);
		px = nx;
		py = ny;
	}

	if (preview) {
		SurfColor(ar, ag, ab, 160);
		SurfOutline(x - 1, y - 1, x + panelW + 1, y + panelH + 1);
	}
}

// Cheap arc (≤32 segments). Local HUD only — no entity scans.
void SurfDrawArc(int cx, int cy, int r, float a0, float a1, int segs, int rr, int gg, int bb, int aa) {
	if (r < 4 || segs < 3) return;
	if (segs > 32) segs = 32;
	SurfColor(rr, gg, bb, aa);
	float step = (a1 - a0) / (float)segs;
	int px = cx + (int)(cosf(a0) * r + 0.5f);
	int py = cy + (int)(sinf(a0) * r + 0.5f);
	for (int i = 1; i <= segs; ++i) {
		const float a = a0 + step * (float)i;
		const int nx = cx + (int)(cosf(a) * r + 0.5f);
		const int ny = cy + (int)(sinf(a) * r + 0.5f);
		SurfLine(px, py, nx, ny);
		px = nx;
		py = ny;
	}
}

static int ShoveMaxPenaltyCvar() {
	int n = CvarGetIntRange("z_gun_swing_coop_max_penalty", 2, 16, -1);
	if (n < 0) n = CvarGetIntRange("z_gun_swing_vs_max_penalty", 2, 16, 8);
	return n;
}

static float ShoveIntervalCvar() {
	void* var = CvarFind("z_gun_swing_interval");
	int n = 0;
	float f = 0.7f;
	if (var && CvarReadPair(var, &n, &f) && f == f && f > 0.15f && f < 4.f)
		return f;
	return 0.7f;
}

static void ShoveHudInvalidateFont() {
	g_shoveHudFontId = 0;
	g_shoveHudFontTall = 0;
}
static void ShoveHudEnsureFonts() {
	ClampShoveHud();
	const int flags = kFontFlagAntiAlias | kFontFlagDropShadow | kFontFlagOutline;
	const int want = HudFontPx(g_shoveHudFont);
	if (!g_shoveHudFontId || g_shoveHudFontTall != want) {
		unsigned long f = SurfMakeYahei(want, 700, flags);
		if (f) { g_shoveHudFontId = f; g_shoveHudFontTall = want; }
	}
}

// Local player only.
// m_iShovePenalty often stays sticky on the client until the next shove, even
// though the game already lets you shove again after idle / fatigue CD ends.
// Mirror that with a light local decay while next-shove CD is clear; once we
// decay, ignore sticky high raw until the next shove pulse.
static bool ShoveHudSample(int* penOut, int* maxOut, float* cdOut) {
	if (!penOut || !maxOut || !cdOut) return false;
	*penOut = 0;
	*maxOut = ShoveMaxPenaltyCvar();
	*cdOut = 0.f;
	if (!g_entlist || g_offShovePenalty < 0 || g_offShovePenalty > 0x4000) return false;
	const int local = EngLocal();
	if (local <= 0) return false;
	void* me = EntGet(local);
	if (!EntReadable(me)) return false;
	const uint8_t* base = (const uint8_t*)me;
	if (!PtrCommitted((void*)(base + g_offShovePenalty))) return false;

	int raw = *(const int*)(base + g_offShovePenalty);
	if (raw < 0 || raw > 16)
		raw = (int)(*(const unsigned char*)(base + g_offShovePenalty));
	if (raw < 0) raw = 0;
	if (raw > *maxOut) raw = *maxOut;

	float nextTs = 0.f;
	const float now = EngClientCurTime();
	if (g_offNextShoveTime >= 0 && g_offNextShoveTime <= 0x4000
		&& PtrCommitted((void*)(base + g_offNextShoveTime))) {
		nextTs = *(const float*)(base + g_offNextShoveTime);
		if (nextTs > now && nextTs - now < 8.f)
			*cdOut = nextTs - now;
	}

	static int s_disp = 0;
	static float s_lastNext = 0.f;
	static float s_idle = 0.f;
	static float s_lastNow = 0.f;
	static int s_lastLocal = 0;
	static bool s_ignoreSticky = false;
	if (local != s_lastLocal) {
		s_lastLocal = local;
		s_disp = raw;
		s_lastNext = nextTs;
		s_idle = 0.f;
		s_lastNow = now;
		s_ignoreSticky = false;
	}

	const bool shovePulse = (nextTs > s_lastNext + 0.05f);
	s_lastNext = nextTs;
	if (shovePulse) {
		s_disp = raw;
		s_ignoreSticky = false;
		s_idle = 0.f;
	} else if (!s_ignoreSticky) {
		if (raw != s_disp) s_disp = raw;
	} else if (raw < s_disp) {
		s_disp = raw;
		if (raw <= 0) s_ignoreSticky = false;
	}

	const float dt = (s_lastNow > 0.f && now >= s_lastNow) ? (now - s_lastNow) : 0.f;
	s_lastNow = now;
	if (dt > 0.f && dt < 0.5f) {
		if (*cdOut > 0.02f) {
			s_idle = 0.f;
		} else if (s_disp > 0) {
			if (s_disp >= *maxOut) {
				// Fatigue lockout finished — clear HUD without waiting for another shove.
				s_disp = 0;
				s_ignoreSticky = true;
				s_idle = 0.f;
			} else {
				s_idle += dt;
				const float step = ShoveIntervalCvar();
				while (s_idle >= step && s_disp > 0) {
					s_idle -= step;
					--s_disp;
					s_ignoreSticky = true;
				}
			}
		}
	}

	*penOut = s_disp;
	return s_disp > 0 || *cdOut > 0.02f;
}

static void ShoveHudPaint() {
	const bool preview = HudMenuPage(28);
	if (IdleSwapDeferEntityHud(preview)) return;
	if (!HudWantsDraw(g_optShoveHud, 28)) return;
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (!SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || EngDrawingLoading()) return;
	if (!MenuEnsureSurf()) return;
	ShoveHudEnsureFonts();
	if (!g_shoveHudFontId) return;

	int pen = 0, maxP = 6;
	float cd = 0.f;
	bool on = ShoveHudSample(&pen, &maxP, &cd);
	if ((preview || HudLayoutPeer(g_optShoveHud, 28)) && !on) {
		on = true;
		pen = 3;
		maxP = 6;
		cd = 0.55f;
	}
	if (!on) return;
	if (maxP < 2) maxP = 6;
	if (pen > maxP) pen = maxP;
	const int left = maxP - pen; // shoves until full fatigue

	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;

	const int sc = g_shoveHudScale;

	const int slot = HudScalePx(14, sc);
	const int gap = HudScalePx(4, sc);
	const int rowW = maxP * slot + (maxP - 1) * gap;
	const int h1 = HudScalePx(g_shoveHudLayoutFont, sc) + 2;
	const int padX = HudScalePx(10, sc), padY = HudScalePx(8, sc);
	const int panelW = padX * 2 + (rowW > 120 ? rowW : 120);
	const int panelH = padY * 2 + h1 + 6 + slot + 10 + 6;
	int x = 0, y = 0;
	HudFinalizePos(&g_shoveHudAbs, &g_shoveHudOffX, &g_shoveHudOffY, g_shoveHudAlign, sw, sh, panelW, panelH, &x, &y);

	const bool fat = (pen >= maxP);
	const int cr = fat ? 255 : 120;
	const int cg = fat ? 90 : 190;
	const int cb = fat ? 70 : 220;

	// Punch-dial plate — diagonal cut corners, not glass stripe.
	SurfColor(8, 12, 20, 155);
	SurfFill(x + 4, y, x + panelW - 4, y + panelH);
	SurfColor(cr, cg, cb, 200);
	SurfLine(x + 4, y, x + panelW - 4, y);
	SurfLine(x + panelW - 4, y, x + panelW, y + 4);
	SurfLine(x + panelW, y + 4, x + panelW, y + panelH - 4);
	SurfLine(x + panelW, y + panelH - 4, x + panelW - 4, y + panelH);
	SurfLine(x + panelW - 4, y + panelH, x + 4, y + panelH);
	SurfLine(x + 4, y + panelH, x, y + panelH - 4);
	SurfLine(x, y + panelH - 4, x, y + 4);
	SurfLine(x, y + 4, x + 4, y);

	wchar_t title[40]{};
	if (fat)
		wcsncpy(title, UiText(UiId::Text_90346e5e, L"推击疲劳"), 39);
	else
		swprintf_s(title, 40, UiText(UiId::Text_b0719d80, L"还可推 %d"), left);
	SurfTextAt(g_shoveHudFontId, x + padX, y + padY, RGB(cr, cg, cb), title);

	const int sx0 = x + (panelW - rowW) / 2;
	const int sy0 = y + padY + h1 + 6;
	for (int i = 0; i < maxP; ++i) {
		const int sx = sx0 + i * (slot + gap);
		const bool filled = (i < pen);
		// Diamond tick
		const int mx = sx + slot / 2;
		const int my = sy0 + slot / 2;
		const int d = slot / 2 - 1;
		if (filled) {
			SurfColor(cr, cg, cb, 220);
			SurfFill(mx - 1, my - d, mx + 2, my + d);
			SurfFill(mx - d, my - 1, mx + d, my + 2);
		} else {
			SurfColor(80, 100, 130, 120);
			SurfLine(mx, my - d, mx + d, my);
			SurfLine(mx + d, my, mx, my + d);
			SurfLine(mx, my + d, mx - d, my);
			SurfLine(mx - d, my, mx, my - d);
		}
	}

	// Cooldown wick under diamonds
	const int barY = sy0 + slot + 4;
	const int barW = rowW;
	SurfColor(255, 255, 255, 24);
	SurfFill(sx0, barY, sx0 + barW, barY + 4);
	if (cd > 0.02f) {
		float frac = cd / 1.2f;
		if (frac > 1.f) frac = 1.f;
		const int fw = (int)(barW * frac + 0.5f);
		SurfColor(200, 220, 255, 210);
		if (fw > 0)
			SurfFill(sx0, barY, sx0 + fw, barY + 4);
	}

	if (preview) {
		SurfColor(cr, cg, cb, 150);
		SurfOutline(x, y, x + panelW, y + panelH);
	}
}

static void* LocalActiveWeaponEnt() {
	if (g_offActiveWeapon < 0 || g_offActiveWeapon > 0x4000) return nullptr;
	const int local = EngLocal();
	if (local <= 0) return nullptr;
	void* me = EntGet(local);
	if (!EntReadable(me)) return nullptr;
	const int h = *(int*)((uint8_t*)me + g_offActiveWeapon);
	if (h == -1 || h == 0) return nullptr;
	const int idx = EntIndexFromHandle(h);
	if (idx <= 0) return nullptr;
	void* wep = EntGet(idx);
	return EntReadable(wep) ? wep : nullptr;
}

bool ReloadProgressSample(bool* reloadOut, float* reloadFracOut, float* fireRemainOut) {
	if (!reloadOut || !reloadFracOut) return false;
	*reloadOut = false;
	*reloadFracOut = 0.f;
	if (fireRemainOut) *fireRemainOut = 0.f;
	if (g_offNextPrimaryAttack < 0 || g_offNextPrimaryAttack > 0x4000) return false;
	void* wep = LocalActiveWeaponEnt();
	if (!wep) return false;
	uint8_t* b = (uint8_t*)wep;
	if (!PtrCommitted(b + g_offNextPrimaryAttack)) return false;
	const float next = *(float*)(b + g_offNextPrimaryAttack);
	const float now = EngClientCurTime();
	float rem = next - now;
	if (rem < 0.f) rem = 0.f;
	if (rem > 5.f) rem = 5.f;
	if (fireRemainOut) *fireRemainOut = rem;

	bool reloading = false;
	if (g_offInReload >= 0 && g_offInReload <= 0x4000 && PtrCommitted(b + g_offInReload))
		reloading = (*(unsigned char*)(b + g_offInReload) != 0);
	*reloadOut = reloading;

	static bool s_wasReload = false;
	static float s_reloadPeak = 0.f;
	if (reloading) {
		if (!s_wasReload || rem > s_reloadPeak)
			s_reloadPeak = rem > 0.05f ? rem : 0.05f;
		s_wasReload = true;
		*reloadFracOut = 1.f - (rem / s_reloadPeak);
		if (*reloadFracOut < 0.f) *reloadFracOut = 0.f;
		if (*reloadFracOut > 1.f) *reloadFracOut = 1.f;
	} else {
		s_wasReload = false;
		s_reloadPeak = 0.f;
	}
	// Skip tiny auto-fire gaps so spray doesn't keep the ring lit every frame.
	return reloading || rem > 0.18f;
}

static bool FireGateHudSample(bool* reloadOut, float* fireRemainOut, float* reloadFracOut) {
	return ReloadProgressSample(reloadOut, reloadFracOut, fireRemainOut);
}

static float FireGateHudArcBiasRad() {
	// Bottom arc: 0.15π..0.85π (bulge down). Rotate for top/left/right.
	const float pi = 3.14159265f;
	switch (g_fireGateHudSide) {
	case 1: return pi;           // top — bulge up
	case 2: return pi * 0.5f;    // left
	case 3: return -pi * 0.5f;   // right
	default: return 0.f;         // bottom (default)
	}
}

static const wchar_t* FireGateHudSideLabel() {
	switch (g_fireGateHudSide) {
	case 1: return UiText(UiId::Text_f4055f32, L"上");
	case 2: return UiText(UiId::Text_7ed414c4, L"左");
	case 3: return UiText(UiId::Text_631946f8, L"右");
	default: return UiText(UiId::Text_ed1e6e73, L"下");
	}
}

static void FireGateHudPaint() {
	if(!g_fireGateHudReload && !g_fireGateHudFire)return;
	const bool preview = HudMenuPage(29);
	if (IdleSwapDeferEntityHud(preview)) return;
	if (!HudWantsDraw(g_optFireGateHud, 29)) return;
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (!SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || EngDrawingLoading()) return;
	if (!MenuEnsureSurf()) return;

	bool reloading = false;
	float fireRem = 0.f, reloadFrac = 0.f;
	bool on = FireGateHudSample(&reloading, &fireRem, &reloadFrac);
	reloading = reloading && g_fireGateHudReload; if(!g_fireGateHudFire)fireRem=0.f;
	on=on && (reloading || fireRem>.04f);
	if ((preview || HudLayoutPeer(g_optFireGateHud, 29)) && !on) {
		on = true;
		reloading = g_fireGateHudReload;
		reloadFrac = 0.62f;
		fireRem = g_fireGateHudFire ? 0.35f : 0.f;
	}
	if (!on) return;

	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;
	ClampFireGateHud();

	// Centered radial — nudge offsets from screen center (not glass panel).
	if (!g_fireGateHudAbs) {
		g_fireGateHudOffX = 0;
		g_fireGateHudOffY = 0;
		g_fireGateHudAbs = true;
		g_settingsDirty = true;
		g_settingsSaveAt = GetTickCount() + 800;
	}
	const int cx = sw / 2 + g_fireGateHudOffX;
	const int cy = sh / 2 + g_fireGateHudOffY;
	const int R = g_fireGateHudSize;
	const float pi = 3.14159265f;
	const float bias = FireGateHudArcBiasRad();
	const float aStart = pi * 0.15f + bias;
	const float aEnd = pi * 0.85f + bias;

	// Track (idle rail)
	if(g_fireGateHudReload)SurfDrawArc(cx, cy, R, aStart, aEnd, 24, 40, 50, 70, 90);
	if(g_fireGateHudFire)SurfDrawArc(cx, cy, R - 6, aStart, aEnd, 20, 30, 40, 55, 70);

	// This is the only in-game reload arc; the separate reload-ring overlay has its own switch.
	if (reloading) {
		const float aFill = aStart + (aEnd - aStart) * reloadFrac;
		SurfDrawArc(cx, cy, R, aStart, aFill, 28, 180, 90, 255, 230);
		SurfDrawArc(cx, cy, R - 1, aStart, aFill, 28, 220, 160, 255, 120);
		// Tick marks at ends
		const int tx0 = cx + (int)(cosf(aStart) * (R + 4));
		const int ty0 = cy + (int)(sinf(aStart) * (R + 4));
		const int tx1 = cx + (int)(cosf(aFill) * (R + 4));
		const int ty1 = cy + (int)(sinf(aFill) * (R + 4));
		SurfColor(200, 140, 255, 255);
		SurfFill(tx0 - 1, ty0 - 1, tx0 + 2, ty0 + 2);
		SurfFill(tx1 - 1, ty1 - 1, tx1 + 2, ty1 + 2);
	}

	if (fireRem > 0.04f) {
		float f = fireRem / 0.85f;
		if (f > 1.f) f = 1.f;
		const float aFill = aStart + (aEnd - aStart) * (1.f - f);
		SurfDrawArc(cx, cy, R - 7, aFill, aEnd, 22, 80, 230, 180, 220);
	}

	if (preview) {
		SurfColor(180, 120, 255, 140);
		SurfOutline(cx - R - 8, cy - 8, cx + R + 8, cy + R + 8);
	}
}

// =============================================================================
// Hazard tags HUD — ground molotov / bile jar (throw-timed).
// Throw path hooks ClientUx only when ground timers enabled.
// =============================================================================
static bool HazHudThrowNotifyWanted() {
	return g_optHazMolotov || g_optHazBileJar;
}

static float HazMolotovLifetimeCvar() {
	void* var = CvarFind("inferno_flame_lifetime");
	int n = 0;
	float f = 15.f;
	if (var && CvarReadPair(var, &n, &f) && f == f && f >= 3.f && f <= 60.f)
		return f;
	return 15.f;
}

static float HazBileJarLifetimeCvar() {
	// Ground lure ≈ 20s; no dedicated replicated cvar — use infected-bot duration as hint.
	int n = CvarGetIntRange("vomitjar_duration_infected_bot", 5, 60, 20);
	if (n < 5) n = 20;
	return (float)n;
}

static void HazHudOnThrow(int kind, const float land[3], float flightSec) {
	(void)land;
	if (!HazHudThrowNotifyWanted()) return;
	if (kind != kHazMolotov && kind != kHazBileGround) return;
	if (kind == kHazMolotov && !g_optHazMolotov) return;
	if (kind == kHazBileGround && !g_optHazBileJar) return;
	if (flightSec < 0.f) flightSec = 0.f;
	if (flightSec > 8.f) flightSec = 8.f;
	const float now = EngClientCurTime();
	const float life = (kind == kHazMolotov) ? HazMolotovLifetimeCvar() : HazBileJarLifetimeCvar();
	if (life < 1.f) return;
	const float start = now + flightSec;
	// Shift FIFO when full.
	for (int i = kHazZoneMax - 1; i > 0; --i)
		g_hazZones[i] = g_hazZones[i - 1];
	g_hazZones[0].type = kind;
	g_hazZones[0].start = start;
	g_hazZones[0].end = start + life;
}

static void HazHudOnSpitBurst() {
	// spit_burst is emitted when the projectile becomes a ground acid pool.
	// Keep this event path constant-time: no entity lookup, scan, Trace or pointer retention.
	if (!g_optHazSpitter) return;
	static constexpr float kDefaultSpitDuration = 8.f;
	const float now = EngClientCurTime();
	if (!(now == now)) return;
	for (int i = kHazZoneMax - 1; i > 0; --i)
		g_hazZones[i] = g_hazZones[i - 1];
	g_hazZones[0].type = kHazSpitGround;
	g_hazZones[0].start = now;
	g_hazZones[0].end = now + kDefaultSpitDuration;
}

static void HazHudOnSpitterDeath(void* ev) {
	if (!g_optHazSpitter || !ev) return;
	bool spitter = false;
	const int uid = EvInt(ev, "userid");
	const int entIndex = uid > 0 ? EngPlayerForUserID(uid) : 0;
	if (entIndex > 0 && entIndex <= 32 && g_offZombieClass >= 0 && g_offZombieClass <= 0x4000) {
		void* ent = EntGet(entIndex);
		if (EntReadable(ent)) {
			const int* zc = (const int*)((const uint8_t*)ent + g_offZombieClass);
			spitter = PtrCommitted(zc) && *zc == 4;
		}
	}
	// player_death normally still exposes the victim entity. Keep the event's
	// stable internal English class name as a fallback for late entity teardown.
	if (!spitter) {
		const char* victim = EvStr(ev, "victimname");
		spitter = victim && !_stricmp(victim, "Spitter");
	}
	if (spitter) HazHudOnSpitBurst();
}

static void HazHudPruneZones(float now) {
	for (int i = 0; i < kHazZoneMax; ++i) {
		if (g_hazZones[i].type && g_hazZones[i].end <= now)
			g_hazZones[i] = {};
	}
}

static void HazHudInvalidateFont() {
	g_hazHudFontId = 0;
	g_hazHudFontTall = 0;
}
static void HazHudEnsureFonts() {
	ClampHazHud();
	const int flags = kFontFlagAntiAlias | kFontFlagDropShadow | kFontFlagOutline;
	const int want = HudFontPx(g_hazHudFont);
	if (!g_hazHudFontId || g_hazHudFontTall != want) {
		unsigned long f = SurfMakeYahei(want, 600, flags);
		if (f) { g_hazHudFontId = f; g_hazHudFontTall = want; }
	}
}

static void HazHudDrawTagIcon(int x, int y, int kind, float frac) {
	const int s = 18;
	if (kind == kHazMolotov) {
		// Ember seal — hex-ish with inner spark.
		const int cr = 255, cg = 140, cb = 40;
		SurfColor(20, 10, 4, 200);
		SurfFill(x, y + 4, x + s, y + s - 2);
		SurfColor(cr, cg, cb, 220);
		SurfLine(x + s / 2, y + 2, x + s - 2, y + s / 2);
		SurfLine(x + s - 2, y + s / 2, x + s / 2, y + s - 2);
		SurfLine(x + s / 2, y + s - 2, x + 2, y + s / 2);
		SurfLine(x + 2, y + s / 2, x + s / 2, y + 2);
		const int fy = y + s - 3 - (int)((s - 6) * frac + 0.5f);
		SurfColor(255, 220, 120, 240);
		SurfFill(x + 4, fy, x + s - 4, fy + 2);
	} else if (kind == kHazBileGround) {
		const int cr = 120, cg = 230, cb = 70;
		SurfColor(8, 18, 6, 200);
		SurfFill(x + 3, y + 2, x + s - 3, y + s - 4);
		SurfColor(cr, cg, cb, 220);
		SurfLine(x + 3, y + 2, x + s - 3, y + 2);
		SurfLine(x + s - 3, y + 2, x + s - 3, y + s - 4);
		SurfLine(x + s - 3, y + s - 4, x + 3, y + s - 4);
		SurfLine(x + 3, y + s - 4, x + 3, y + 2);
		const int fillH = (int)((s - 8) * frac + 0.5f);
		if (fillH > 0)
			SurfFill(x + 5, y + s - 5 - fillH, x + s - 5, y + s - 5);
		SurfColor(cr, cg, cb, 200);
		SurfFill(x + s / 2 - 1, y + s - 3, x + s / 2 + 2, y + s);
	} else if (kind == kHazSpitGround) {
		// Acid vial: angular cyan-green frame with a draining core.
		const int cr = 78, cg = 238, cb = 190;
		SurfColor(3, 20, 17, 210);
		SurfFill(x + 2, y + 3, x + s - 2, y + s - 2);
		SurfColor(cr, cg, cb, 225);
		SurfLine(x + 5, y + 1, x + s - 5, y + 1);
		SurfLine(x + 2, y + 4, x + 5, y + 1);
		SurfLine(x + s - 5, y + 1, x + s - 2, y + 4);
		SurfLine(x + 2, y + 4, x + 2, y + s - 3);
		SurfLine(x + s - 2, y + 4, x + s - 2, y + s - 3);
		const int fillH = (int)((s - 8) * frac + 0.5f);
		if (fillH > 0) {
			SurfColor(cr, cg, cb, 210);
			SurfFill(x + 5, y + s - 4 - fillH, x + s - 5, y + s - 4);
		}
		SurfColor(205, 255, 238, 230);
		SurfFill(x + s / 2 - 1, y + 5, x + s / 2 + 1, y + 7);
	}
}

static void HazHudPaint() {
	const bool hazOn = g_optHazMolotov || g_optHazBileJar || g_optHazSpitter;
	const bool preview = HudMenuPage(30);
	const bool layoutPeer = HudLayoutPeer(hazOn, 30);
	if (!preview && !HudWantsDraw(hazOn, 30)) return;
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (!SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || EngDrawingLoading()) return;
	if (!MenuEnsureSurf()) return;
	HazHudEnsureFonts();
	if (!g_hazHudFontId) return;

	const float now = EngClientCurTime();
	HazHudPruneZones(now);

	struct Row { int kind; float rem; float dur; wchar_t label[16]; };
	Row rows[kHazZoneMax]{};
	int rowN = 0;

	if (g_optHazMolotov || preview || layoutPeer) {
		for (int i = 0; i < kHazZoneMax && rowN < kHazZoneMax; ++i) {
			if (g_hazZones[i].type != kHazMolotov) continue;
			if (now < g_hazZones[i].start) continue;
			float rem = g_hazZones[i].end - now;
			if (rem <= 0.03f) continue;
			float dur = g_hazZones[i].end - g_hazZones[i].start;
			if (dur < 0.5f) dur = HazMolotovLifetimeCvar();
			rows[rowN].kind = kHazMolotov;
			rows[rowN].rem = rem;
			rows[rowN].dur = dur;
			wcsncpy(rows[rowN].label, UiText(UiId::Text_46733245, L"地面燃烧"), 15);
			++rowN;
		}
		if ((preview || layoutPeer) && rowN < kHazZoneMax && !g_hazZones[0].type) {
			rows[rowN].kind = kHazMolotov;
			rows[rowN].rem = 9.5f;
			rows[rowN].dur = 15.f;
			wcsncpy(rows[rowN].label, UiText(UiId::Text_46733245, L"地面燃烧"), 15);
			++rowN;
		}
	}
	if (g_optHazBileJar || preview || layoutPeer) {
		for (int i = 0; i < kHazZoneMax && rowN < kHazZoneMax; ++i) {
			if (g_hazZones[i].type != kHazBileGround) continue;
			if (now < g_hazZones[i].start) continue;
			float rem = g_hazZones[i].end - now;
			if (rem <= 0.03f) continue;
			float dur = g_hazZones[i].end - g_hazZones[i].start;
			if (dur < 0.5f) dur = HazBileJarLifetimeCvar();
			rows[rowN].kind = kHazBileGround;
			rows[rowN].rem = rem;
			rows[rowN].dur = dur;
			wcsncpy(rows[rowN].label, UiText(UiId::Text_bfc75a75, L"地面胆汁"), 15);
			++rowN;
		}
		if ((preview || layoutPeer) && rowN < kHazZoneMax) {
			bool have = false;
			for (int j = 0; j < rowN; ++j)
				if (rows[j].kind == kHazBileGround) have = true;
			if (!have) {
				rows[rowN].kind = kHazBileGround;
				rows[rowN].rem = 14.f;
				rows[rowN].dur = 20.f;
				wcsncpy(rows[rowN].label, UiText(UiId::Text_bfc75a75, L"地面胆汁"), 15);
				++rowN;
			}
		}
	}
	if (g_optHazSpitter || preview || layoutPeer) {
		for (int i = 0; i < kHazZoneMax && rowN < kHazZoneMax; ++i) {
			if (g_hazZones[i].type != kHazSpitGround) continue;
			if (now < g_hazZones[i].start) continue;
			const float rem = g_hazZones[i].end - now;
			if (rem <= 0.03f) continue;
			rows[rowN].kind = kHazSpitGround;
			rows[rowN].rem = rem;
			rows[rowN].dur = 8.f;
			wcsncpy(rows[rowN].label, UiText(UiId::Text_95651b7a, L"酸液残留"), 15);
			++rowN;
		}
		if ((preview || layoutPeer) && rowN < kHazZoneMax) {
			bool have = false;
			for (int j = 0; j < rowN; ++j)
				if (rows[j].kind == kHazSpitGround) have = true;
			if (!have) {
				rows[rowN].kind = kHazSpitGround;
				rows[rowN].rem = 5.6f;
				rows[rowN].dur = 8.f;
				wcsncpy(rows[rowN].label, UiText(UiId::Text_95651b7a, L"酸液残留"), 15);
				++rowN;
			}
		}
	}
	if (!rowN) return;

	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh)) return;

	const int sc = g_hazHudScale;

	const int rowH = HudScalePx(30, sc);
	const int padX = HudScalePx(10, sc), padY = HudScalePx(8, sc);
	const int iconW = 22;
	const int barW = 88;
	const int panelW = padX * 2 + iconW + 8 + 72 + 8 + barW;
	const int panelH = padY * 2 + rowN * rowH + (rowN > 1 ? (rowN - 1) * 4 : 0);
	int x = 0, y = 0;
	HudFinalizePos(&g_hazHudAbs, &g_hazHudOffX, &g_hazHudOffY, g_hazHudAlign, sw, sh, panelW, panelH, &x, &y);

	// Ticket rail — colored spine, not glass stripe.
	SurfColor(6, 10, 14, 170);
	SurfFill(x + 3, y, x + panelW - 3, y + panelH);
	int ry = y + padY;
	for (int r = 0; r < rowN; ++r) {
		int cr = 200, cg = 200, cb = 200;
		if (rows[r].kind == kHazMolotov) { cr = 255; cg = 150; cb = 50; }
		else if (rows[r].kind == kHazBileGround) { cr = 140; cg = 230; cb = 80; }
		else if (rows[r].kind == kHazSpitGround) { cr = 78; cg = 238; cb = 190; }
		else { cr = 180; cg = 255; cb = 100; }
		SurfColor(cr, cg, cb, 200);
		SurfFill(x, ry, x + 4, ry + rowH - 2);
		float frac = (rows[r].dur > 0.01f) ? (rows[r].rem / rows[r].dur) : 0.f;
		if (frac < 0.f) frac = 0.f;
		if (frac > 1.f) frac = 1.f;
		HazHudDrawTagIcon(x + padX, ry + 4, rows[r].kind, frac);
		wchar_t sec[12]{};
		swprintf_s(sec, 12, L"%.1f", rows[r].rem);
		SurfTextAt(g_hazHudFontId, x + padX + iconW + 4, ry + 4, RGB(cr, cg, cb), rows[r].label);
		if (g_hazHudFontTall > 0)
			SurfTextAt(g_hazHudFontId, x + padX + iconW + 4, ry + 4 + g_hazHudFontTall - 2, RGB(200, 210, 220), sec);
		const int bx = x + panelW - padX - barW;
		const int by = ry + rowH / 2;
		SurfColor(255, 255, 255, 28);
		SurfFill(bx, by, bx + barW, by + 3);
		const int fw = (int)(barW * frac + 0.5f);
		if (fw > 0)
			SurfFill(bx, by, bx + fw, by + 3);
		ry += rowH + 4;
	}
	if (preview) {
		SurfColor(200, 220, 255, 120);
		SurfOutline(x, y, x + panelW, y + panelH);
	}
}





const wchar_t* DirectorTempoName(int tempo) {
	switch (tempo) {
	case 0: return L"BUILD_UP";
	case 1: return L"SUSTAIN_PEAK";
	case 2: return L"PEAK_FADE";
	case 3: return L"RELAX";
	default: return L"";
	}
}

struct ListenDirectorInfo {
	int tempo = 0;
	bool haveRemain = false;
	int remainSec = 0;
	bool haveLock = false;
	bool locked = false;
	bool haveFlow = false;
	int flow = 0;
};

static bool ListenFloatOk(float v, float lo, float hi) {
	return v == v && v >= lo && v <= hi;
}

// Listen-host server.dll only. Client tempo at director+0x10EC is a different object.
// This server.dll (x86, SHA-256 a93ec916a8f26fbea85688c321d2ba8dd346d435fab09a0b926dd950c2e1ea12):
// CDirector+0x194 is the 0..3 tempo, +0x1A0 is the phase-timer timestamp.
// RELAX stores the lead flow at +0x1A4 and leaves for BUILD_UP once that lead passes
// +0x1A4 + RelaxMaxFlowTravel. +0x24C is the lead's current flow, not the map length.
static bool ListenDirectorSample(ListenDirectorInfo* out) {
	static bool tried = false;
	static void** dirSlot = nullptr;
	static void** globalsSlot = nullptr;
	if (!tried) {
		tried = true;
		const uintptr_t music = FindPat("server.dll",
			"55 8B EC 83 EC ?? 56 57 8B F9 8B 0D ?? ?? ?? ?? E8 ?? ?? ?? ?? 84 C0 0F");
		if (music && PtrCommitted((void*)(music + 16))) {
			const uintptr_t slot = *(uint32_t*)(music + 12);
			if (slot && PtrCommitted((void*)slot)) dirSlot = (void**)slot;
		}
		const uintptr_t nowFn = FindPat("server.dll", "A1 ?? ?? ?? ?? D9 40 0C C3");
		if (nowFn && PtrCommitted((void*)(nowFn + 5))) {
			const uintptr_t slot = *(uint32_t*)(nowFn + 1);
			if (slot && PtrCommitted((void*)slot)) globalsSlot = (void**)slot;
		}
		Log("listen director: dir=%p time=%p", dirSlot, globalsSlot);
	}
	if (!out || !dirSlot || !PtrCommitted(dirSlot)) return false;
	void* dir = *dirSlot;
	if (!dir || !PtrCommitted(dir)) return false;
	auto* base = (uint8_t*)dir;
	if (!PtrCommitted(base + 0x194)) return false;
	const int tempo = *(int*)(base + 0x194);
	if (tempo < 0 || tempo > 3) return false;
	*out = {};
	out->tempo = tempo;
	if (globalsSlot && PtrCommitted(globalsSlot) && PtrCommitted(base + 0x1A0)) {
		void* globals = *globalsSlot;
		if (globals && PtrCommitted((uint8_t*)globals + 0xC)) {
			const float now = *(float*)((uint8_t*)globals + 0xC);
			const float stamp = *(float*)(base + 0x1A0);
			const float left = stamp - now;
			if (ListenFloatOk(now, 0.f, 1000000.f) && ListenFloatOk(stamp, 0.f, 1000000.f)
				&& left > 0.f && left <= 600.f) {
				out->haveRemain = true;
				out->remainSec = (int)(left + 0.5f);
			}
		}
	}
	void* mode = nullptr;
	void* flag = nullptr;
	void* pace = nullptr;
	if (PtrCommitted(base + 0x648)) {
		mode = *(void**)(base + 0x638);
		flag = *(void**)(base + 0x640);
		pace = *(void**)(base + 0x644);
	}
	if (mode && flag && pace && PtrCommitted(mode) && PtrCommitted((uint8_t*)mode + 0x111)
		&& PtrCommitted(flag) && PtrCommitted((uint8_t*)pace + 8)) {
		const char* gameMode = ReadMpGamemode();
		out->haveLock = true;
		out->locked = (gameMode && !_stricmp(gameMode, "versus"))
			|| *(int*)mode != 5
			|| *(uint8_t*)flag != 0
			|| *(uint8_t*)((uint8_t*)mode + 0x111) != 0
			|| *(uint8_t*)((uint8_t*)pace + 8) != 0;
	}
	if (out->tempo == 3 && PtrCommitted(base + 0x1A4) && PtrCommitted(base + 0x24C)) {
		const float anchor = *(float*)(base + 0x1A4);
		const float lead = *(float*)(base + 0x24C);
		int limitN = 0;
		float limit = 0.f;
		static void* travel = nullptr;
		if (!travel) travel = FindCvarVar("director_relax_max_flow_travel");
		if (travel && CvarReadPair(travel, &limitN, &limit)
			&& ListenFloatOk(anchor, 0.f, 1000000.f) && ListenFloatOk(lead, 0.f, 1000000.f)
			&& ListenFloatOk(limit, 0.f, 100000.f)) {
			float left = anchor + limit - lead;
			if (left < 0.f) left = 0.f;
			out->haveFlow = true;
			out->flow = (int)(left + 0.5f);
		}
	}
	return true;
}

static void ListenDirectorPanelPaint() {
	const bool preview = HudMenuPage(kMenuPageLocalDirector);
	const bool peer = HudLayoutPeer(g_optLocalDirector, kMenuPageLocalDirector);
	if (!preview && !ListenDetectHost()) return;
	if (peer && !ListenDetectHost()) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || EngDrawingLoading() || HudCustomHidden()) return;
	if (!MenuEnsureSurf()) return;
	ListenDirectorInfo info{};
	const bool live = ListenDetectHost() && ListenDirectorSample(&info);
	const wchar_t* livePhase = live ? DirectorTempoName(info.tempo) : L"";
	if ((!livePhase || !livePhase[0]) && !preview && !peer) return;
	wchar_t rows[4][96]{};
	int rowN = 0;
	int accentTempo = 0;
	if (livePhase && livePhase[0]) {
		accentTempo = info.tempo;
		swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorPhase, L"阶段  %s"), livePhase);
		if (info.tempo == 3 && info.haveRemain && (!info.haveFlow || info.flow > 0))
			swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorCountdown, L"倒计时  %d 秒"), info.remainSec);
		if (info.haveLock)
			swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorLock, L"锁定  %s"),
				info.locked ? UiText(UiId::LocalDirectorLockOn, L"是") : UiText(UiId::LocalDirectorLockOff, L"否"));
		if (info.haveFlow)
			swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorFlow, L"路程  %d 码"), info.flow);
	} else {
		swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorPhase, L"阶段  %s"), L"BUILD_UP");
		swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorCountdown, L"倒计时  %d 秒"), 12);
		swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorLock, L"锁定  %s"), UiText(UiId::LocalDirectorLockOff, L"否"));
		swprintf_s(rows[rowN++], UiText(UiId::LocalDirectorFlow, L"路程  %d 码"), 3000);
	}
	ClampLocalDirectorHud();
	const int want = HudFontPx(g_localDirectorFont);
	if (!g_localDirectorFontId || g_localDirectorFontTall != want) {
		g_localDirectorFontId = SurfMakeYahei(want, 700, kFontFlagAntiAlias | kFontFlagDropShadow);
		g_localDirectorFontTall = want;
	}
	if (!g_localDirectorFontId) return;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 640 || sh < 400) return;
	int textW = 0;
	for (int i = 0; i < rowN; ++i) {
		const int w = SurfTextWFont(g_localDirectorFontId, rows[i]);
		if (w > textW) textW = w;
	}
	const int sc = g_localDirectorScale;
	const int lineH = g_localDirectorFontTall + HudScalePx(4, sc);
	const int pad = HudScalePx(10, sc);
	const int bar = HudScalePx(3, sc);
	const int panelW = textW + pad * 2 + bar + HudScalePx(6, sc);
	const int panelH = lineH * rowN + pad * 2;
	int x = 0, y = 0;
	HudFinalizePos(&g_localDirectorAbs, &g_localDirectorOffX, &g_localDirectorOffY,
		g_localDirectorAlign, sw, sh, panelW, panelH, &x, &y);
	const COLORREF accent = DirectorTempoColor(accentTempo);
	HudPanelShadow(x, y, panelW, panelH);
	HudGlassBody(x, y, panelW, panelH);
	HudTopAccent(x, y, panelW, accent, 2);
	HudCornerBrackets(x, y, panelW, panelH, HudScalePx(8, sc), accent, 150);
	SurfColor(GetRValue(accent), GetGValue(accent), GetBValue(accent), 200);
	SurfFill(x, y + 2, x + bar, y + panelH - 2);
	for (int i = 0; i < rowN; ++i) {
		const int rowY = y + pad + lineH * i;
		if (i > 0) {
			SurfColor(255, 255, 255, 22);
			SurfFill(x + pad + bar, rowY - HudScalePx(2, sc), x + panelW - pad, rowY - HudScalePx(1, sc));
		}
		SurfTextAt(g_localDirectorFontId, x + pad + bar + HudScalePx(4, sc), rowY,
			i == 0 ? accent : RGB(236, 242, 246), rows[i]);
	}
}

COLORREF DirectorTempoColor(int tempo) {
	switch (tempo) {
	case 0: return RGB(242, 76, 92);    // BUILD_UP
	case 1: return RGB(255, 178, 58);   // SUSTAIN_PEAK
	case 2: return RGB(80, 164, 236);    // PEAK_FADE
	case 3: return RGB(72, 214, 132);    // RELAX
	default: return RGB(72, 214, 132);
	}
}


// Menu layout contract (also docs/agent-guides/menu-and-settings.md):
// - Max 9 numbered options per subpage, starting at [1].
// - Paginate only when total > 9. Earlier subpages MUST be full (9) before a
//   later subpage exists — e.g. 14 items => 9+5, never 8+6. After deletes,
//   backfill from later pages into earlier empty slots.
// - Toggle rows: col() green/red. Enter-settings / multi-choice / one-shot /
//   inert rows: white cText (cMuted when locked). Never leave enter-settings green.
// - A value adjusted with -/+ must show "- / + 调节" beside that value, in
//   cAdjust yellow/orange; a footer-only hint is too easy to miss.
// - Main-menu root options stay concise and do not carry an entry suffix in either
//   language; their page position already signals navigation. Inside feature pages,
//   clickable setup pages say "【进入设置】" and read-only pages say "【进入说明】"
//   on the entry row (localized equivalents in English).
// - Multi-page row order and page count should come from the same descriptor or setting range.
// - UI strings: skeeto_ui_text.h / skeeto_ui_en.inc (CN default + EN fallback).
