static constexpr int kNavSuppliesFirstSetting = 10;
static constexpr int kNavSuppliesEndSetting = 22;
static constexpr int kNavWeaponsFirstSetting = 22;
static constexpr int kNavWeaponsEndSetting = 44;
static constexpr int NavMenuPageCount(int page) {
	if (page == kMenuPageNavDisplay) return MenuPageCountForItems(kNavDisplayItemCount);
	if (page == kMenuPageNavSupplies)
		return MenuPageCountForItems(kNavSuppliesEndSetting - kNavSuppliesFirstSetting);
	if (page == kMenuPageNavWeapons)
		return MenuPageCountForItems(kNavWeaponsEndSetting - kNavWeaponsFirstSetting);
	return 1;
}
static_assert(MenuPageCountForItems(kNavSuppliesEndSetting - kNavSuppliesFirstSetting) == 2,
	"navigation supply setting range should span two pages");
static_assert(MenuPageCountForItems(kNavWeaponsEndSetting - kNavWeaponsFirstSetting) == 3,
	"navigation weapon setting range should span three pages");
static int NavMenuSettingIndexForRow(int page, int sub, int row) {
	if (row < 0 || row >= kMenuItemsPerPage) return -1;
	switch (page) {
	case kMenuPageNavDisplay: {
		const int item = sub * kMenuItemsPerPage + row;
		return item >= 0 && item < kNavDisplayItemCount ? kNavDisplaySettings[item] : -1;
	}
	case kMenuPageNavRoute:
		if (row == 0) return 8;
		if (row == 1) return 9;
		if (row == 2) return 44;
		if (row == 4) return kNavArrowColorSetting;
		if (row == 5) return kNavWorldHudSetting;
		return -1;
	case kMenuPageNavSupplies: {
		const int index = kNavSuppliesFirstSetting + sub * kMenuItemsPerPage + row;
		return index < kNavSuppliesEndSetting ? index : -1;
	}
	case kMenuPageNavWeapons: {
		const int index = kNavWeaponsFirstSetting + sub * kMenuItemsPerPage + row;
		return index < kNavWeaponsEndSetting ? index : -1;
	}
	default: return -1;
	}
}
static int NavMenuPageRows(int page, int sub) {
	if (page == kMenuPageNavDisplay) { const int remaining = kNavDisplayItemCount - sub * kMenuItemsPerPage; return remaining > 0 ? (remaining < kMenuItemsPerPage ? remaining : kMenuItemsPerPage) : 0; }
	if (page == kMenuPageNavRoute) return 7;
	const int pageCount = NavMenuPageCount(page);
	if (sub < 0 || sub >= pageCount) return 0;
	const int first = page == kMenuPageNavSupplies ? kNavSuppliesFirstSetting
		: page == kMenuPageNavWeapons ? kNavWeaponsFirstSetting : -1;
	const int end = page == kMenuPageNavSupplies ? kNavSuppliesEndSetting
		: page == kMenuPageNavWeapons ? kNavWeaponsEndSetting : -1;
	if (first >= 0) {
		const int remaining = end - (first + sub * kMenuItemsPerPage);
		return remaining < kMenuItemsPerPage ? remaining : kMenuItemsPerPage;
	}
	return 0;
}
static int NavMenuPageFirstSetting(int page, int sub) {
	if (page == kMenuPageNavDisplay) return 0;
	if (page == kMenuPageNavRoute) return 8;
	if (page == kMenuPageNavSupplies) return kNavSuppliesFirstSetting + sub * kMenuItemsPerPage;
	if (page == kMenuPageNavWeapons) return kNavWeaponsFirstSetting + sub * kMenuItemsPerPage;
	return -1;
}
static bool NavMenuHasSettingSelection() {
	// Action rows use -1; never treat that sentinel as a settings index.
	if (g_navMenuSel < 0 || g_navMenuSel >= skeeto_nav::kSettingCount) return false;
	for (int row = 0; row < NavMenuPageRows(g_menuPage, g_menuSub); ++row)
		if (NavMenuSettingIndexForRow(g_menuPage, g_menuSub, row) == g_navMenuSel) return true;
	return false;
}
static int NavMenuStep(int index) {
	switch (index) {
	case 1: return 20; case 2: return 100; case 5: case 6: return 250;
	case 7: return 10; case 11: return 100; case kNavRefreshSetting: return 5; default: return 1;
	}
}
static void NavMenuAdjust(int direction) {
	if (!NavMenuHasSettingSelection()) return;
	const int index = g_navMenuSel;
	if (index < 0 || index >= skeeto_nav::kSettingCount) return;
	int value = skeeto_nav::Get(index);
	if (skeeto_nav::Maximum(index) == 1)
		value = value ? 0 : 1;
	else if (index == 9)
		value = (value + direction + (int)skeeto_nav::GoalCount() + 1) % ((int)skeeto_nav::GoalCount() + 1);
	else if (index == kNavArrowColorSetting)
		value = (value + direction + 7) % 7;
	else
		value = ClampAdd(value, direction * NavMenuStep(index), skeeto_nav::Minimum(index), skeeto_nav::Maximum(index));
	skeeto_nav::Set(index, value);
	g_settingsDirty = true;
	g_settingsSaveAt = GetTickCount() + 400u;
	MenuMarkDirty();
}
