static const SoundVolumeAuxMenuItem* SoundVolumeAuxItemForSelection(int selectionIndex) {
	for (int row = 0; row < SoundVolumeAuxMenuItemCount(); ++row) {
		const SoundVolumeAuxMenuItem* item = SoundVolumeAuxMenuItemAt(row);
		if (item && item->selectionIndex == selectionIndex) return item;
	}
	return nullptr;
}
static int SoundVolumeAuxSelectedStep(int selectionIndex) {
	const SoundVolumeAuxMenuItem* item = SoundVolumeAuxItemForSelection(selectionIndex);
	if (item && item->action == SoundVolumeAuxAction::AdjustSafeMusic) return g_safeMusicVolumeStep;
	if (item && item->action == SoundVolumeAuxAction::AdjustLastMusic) return g_lastMusicVolumeStep;
	return g_optClientSoundVolStep;
}
