static constexpr int SoundVolumeMenuItemCount() {
	return static_cast<int>(sizeof(kSoundVolumeMenuItems) / sizeof(kSoundVolumeMenuItems[0]));
}
static constexpr int SoundVolumeContentCount() {
	return SoundVolumeMenuItemCount() + SoundVolumeAuxMenuItemCount();
}
static constexpr int SoundVolumeMenuPageCount() {
	const int rest = SoundVolumeContentCount() - kSoundVolumeFirstPageCount;
	return 1 + (rest > 0 ? (rest + kMenuItemsPerPage - 1) / kMenuItemsPerPage : 0);
}
static constexpr int SoundVolumeContentIndex(int subpage, int row) {
	if (subpage < 0 || row < 0 || row >= kMenuItemsPerPage || subpage >= SoundVolumeMenuPageCount())
		return -1;
	const int index = subpage == 0
		? (row < kSoundVolumeMainControlRows ? -1 : row - kSoundVolumeMainControlRows)
		: kSoundVolumeFirstPageCount + (subpage - 1) * kMenuItemsPerPage + row;
	return index >= 0 && index < SoundVolumeContentCount() ? index : -1;
}
static constexpr bool SoundVolumeMenuItemsValid() {
	if (SoundVolumeMenuItemCount() != kSoundVolumeSliderCount) return false;
	if (kSoundVolumeMainControlRows + kSoundVolumeFirstPageCount != kMenuItemsPerPage) return false;
	for (int i = 0; i < SoundVolumeMenuItemCount(); ++i)
		if (kSoundVolumeMenuItems[i].settingIndex != i) return false;
	const int pages = SoundVolumeMenuPageCount();
	if (pages < 1) return false;
	for (int page = 0; page < pages - 1; ++page) {
		const int firstRow = page == 0 ? kSoundVolumeMainControlRows : 0;
		for (int row = firstRow; row < kMenuItemsPerPage; ++row)
			if (SoundVolumeContentIndex(page, row) < 0) return false;
	}
	bool lastHasRow = false;
	for (int row = 0; row < kMenuItemsPerPage; ++row)
		if (SoundVolumeContentIndex(pages - 1, row) >= 0) lastHasRow = true;
	return lastHasRow;
}
static_assert(SoundVolumeMenuItemsValid(), "sound volume menu setting order needs review");
static const SoundVolumeMenuItem* SoundVolumeMenuItemAt(int subpage, int row) {
	const int index = SoundVolumeContentIndex(subpage, row);
	return index >= 0 && index < SoundVolumeMenuItemCount() ? &kSoundVolumeMenuItems[index] : nullptr;
}
static const SoundVolumeAuxMenuItem* SoundVolumeAuxMenuItemAt(int subpage, int row) {
	const int index = SoundVolumeContentIndex(subpage, row) - SoundVolumeMenuItemCount();
	return index >= 0 && index < SoundVolumeAuxMenuItemCount() ? &kSoundVolumeAuxMenuItems[index] : nullptr;
}
static bool SoundVolumeSelectionVisible(int subpage, int settingIndex) {
	for (int row = 0; row < kMenuItemsPerPage; ++row) {
		const SoundVolumeMenuItem* item = SoundVolumeMenuItemAt(subpage, row);
		if (item && item->settingIndex == settingIndex) return true;
	}
	return false;
}
static bool SoundVolumeAuxSelectionVisible(int subpage, int selectionIndex) {
	if (selectionIndex < 0) return false;
	for (int row = 0; row < kMenuItemsPerPage; ++row) {
		const SoundVolumeAuxMenuItem* item = SoundVolumeAuxMenuItemAt(subpage, row);
		if (item && item->selectionIndex == selectionIndex) return true;
	}
	return false;
}

