// Numbered page order and keyboard destination share these entries. The text
// resources retain their existing numeric prefix; MenuRenumberItem replaces it
// from the current slot so moving an entry does not leave a stale number behind.
static void MenuRenumberItem(wchar_t* text, size_t capacity, int number) {
	if (!text || capacity < 8 || text[0] != L'[') return;
	wchar_t* close = wcschr(text, L']');
	if (!close || close == text + 1 || close - text > 4 || close[1] != L' ') return;
	wchar_t label[192]{};
	wcsncpy_s(label, _countof(label), close + 2, _TRUNCATE);
	swprintf_s(text, capacity, L"[%d] %s", number, label);
}

