static constexpr int kViewModelMenuPageCount = (sizeof(kViewModelMenuItems) / sizeof(kViewModelMenuItems[0]) + 8) / 9;
static_assert(sizeof(kViewModelMenuItems) / sizeof(kViewModelMenuItems[0]) == 20, "viewmodel menu must keep full pages before the final action");
static const ViewModelMenuItem* ViewModelMenuItemAt(int sub, int digit) {
    if (sub < 0 || sub >= kViewModelMenuPageCount || digit < 1 || digit > 9) return nullptr;
    const int index = sub * 9 + digit - 1;
    return index < int(sizeof(kViewModelMenuItems) / sizeof(kViewModelMenuItems[0])) ? &kViewModelMenuItems[index] : nullptr;
}

static ViewModelMenuAction g_vmSelected = ViewModelMenuAction::PosX;
static ViewModelMenuAction ViewModelMenuPageSelection(int sub) {
    for (int digit = 1; digit <= 9; ++digit) {
        const auto* item = ViewModelMenuItemAt(sub, digit);
        if (!item) break;
        const auto action = item->action;
        if ((action >= ViewModelMenuAction::PosX && action <= ViewModelMenuAction::Roll)
            || (action >= ViewModelMenuAction::PivotX && action <= ViewModelMenuAction::Scale))
            return action;
    }
    const auto* first = ViewModelMenuItemAt(sub, 1);
    return first ? first->action : ViewModelMenuAction::PosX;
}
static const skviewmodel::Pose* ViewModelMenuPose() {
    const auto& b = g_vmBindings[g_vmEditSlot];
    if (!g_vmReady || !b.model[0]) return nullptr;
    static const skviewmodel::Pose zero{};
    return b.profile < 0 ? &zero : &g_vmStore.records[b.profile].pose;
}
