static constexpr int MenuRootItemCount() {
	return static_cast<int>(sizeof(kMenuRootItems) / sizeof(kMenuRootItems[0]));
}
static constexpr int MenuRootPageCount() {
	return (MenuRootItemCount() + kMenuRootItemsPerPage - 1) / kMenuRootItemsPerPage;
}
static constexpr bool MenuRootItemsValid() {
	for (int i = 0; i < MenuRootItemCount(); ++i) {
		const MenuRootItem& item = kMenuRootItems[i];
		if ((item.action == MenuRootAction::OpenChangelog) != (item.targetPage < 0)) return false;
	}
	return MenuRootItemCount() > 0 && MenuRootPageCount() <= 3;
}
static const MenuRootItem* MenuRootItemAt(int subpage, int digit) {
	if (subpage < 0 || digit < 1 || digit > kMenuRootItemsPerPage) return nullptr;
	const int index = subpage * kMenuRootItemsPerPage + digit - 1;
	return index >= 0 && index < MenuRootItemCount() ? &kMenuRootItems[index] : nullptr;
}
static_assert(MenuRootItemCount() == 24, "root menu item count changed; review pagination and key mapping");
static_assert(MenuRootPageCount() == 3, "root menu pagination changed; review visible slots");
static_assert(MenuRootItemsValid(), "root menu item has an invalid navigation target");

