enum class StaticCrosshairMenuAction : unsigned char {
	Toggle, CycleStyle, CycleColor, CycleSize, CycleLength, CycleGap, CycleThick, CycleDot, CycleOutline,
	ResetStyle, AdjustAlpha,
};
struct StaticCrosshairMenuItem { StaticCrosshairMenuAction action; };
static constexpr StaticCrosshairMenuItem kStaticCrosshairMenuItems[] = {
	{StaticCrosshairMenuAction::Toggle}, {StaticCrosshairMenuAction::CycleStyle},
	{StaticCrosshairMenuAction::CycleColor}, {StaticCrosshairMenuAction::CycleSize},
	{StaticCrosshairMenuAction::CycleLength}, {StaticCrosshairMenuAction::CycleGap},
	{StaticCrosshairMenuAction::CycleThick}, {StaticCrosshairMenuAction::CycleDot},
	{StaticCrosshairMenuAction::CycleOutline},
	{StaticCrosshairMenuAction::AdjustAlpha}, {StaticCrosshairMenuAction::ResetStyle},
};
static_assert(_countof(kStaticCrosshairMenuItems) == 11, "static crosshair is a full page plus opacity and reset");
static_assert(kStaticCrosshairMenuItems[9].action == StaticCrosshairMenuAction::AdjustAlpha
	&& kStaticCrosshairMenuItems[10].action == StaticCrosshairMenuAction::ResetStyle,
	"static crosshair page 2 is opacity then reset");
static constexpr bool StaticCrosshairAdjustable(StaticCrosshairMenuAction action) {
	return action != StaticCrosshairMenuAction::Toggle && action != StaticCrosshairMenuAction::ResetStyle;
}
static const StaticCrosshairMenuItem* StaticCrosshairMenuItemAt(int subpage, int digit) {
	const int index = subpage * kMenuItemsPerPage + digit - 1;
	if (digit < 1 || index < 0 || index >= (int)_countof(kStaticCrosshairMenuItems)) return nullptr;
	return &kStaticCrosshairMenuItems[index];
}
static int StaticCrosshairActiveSel() {
	const int total = (int)_countof(kStaticCrosshairMenuItems);
	const int begin = g_menuSub * kMenuItemsPerPage;
	int end = begin + kMenuItemsPerPage;
	if (end > total) end = total;
	if (g_staticXhairSel >= begin && g_staticXhairSel < end
		&& StaticCrosshairAdjustable(kStaticCrosshairMenuItems[g_staticXhairSel].action))
		return g_staticXhairSel;
	for (int i = begin; i < end; ++i)
		if (StaticCrosshairAdjustable(kStaticCrosshairMenuItems[i].action)) return i;
	return -1;
}

