static constexpr int WorldHudMenuItemCount() {
	return static_cast<int>(sizeof(kWorldHudMenu) / sizeof(kWorldHudMenu[0]));
}
static constexpr int WorldHudMenuPageCount() {
	return (WorldHudMenuItemCount() + kMenuItemsPerPage - 1) / kMenuItemsPerPage;
}
static constexpr bool WorldHudMenuItemsValid() {
	for (int i = 0; i < WorldHudMenuItemCount(); ++i) {
		const WorldHudMenuItem& item = kWorldHudMenu[i];
		if ((item.action == WorldHudMenuAction::OpenPage) != (item.targetPage >= 0)) return false;
	}
	return WorldHudMenuItemCount() == 24 && WorldHudMenuPageCount() == 3;
}
static_assert(WorldHudMenuItemsValid(), "world HUD menu order, targets, or pagination need review");
static const WorldHudMenuItem* WorldHudMenuItemAt(int subpage, int digit) {
	if (subpage < 0 || digit < 1 || digit > kMenuItemsPerPage) return nullptr;
	const int index = subpage * kMenuItemsPerPage + digit - 1;
	return index >= 0 && index < WorldHudMenuItemCount() ? &kWorldHudMenu[index] : nullptr;
}
static bool WorldHudMenuItemEnabled(WorldHudMenuAction action) {
	switch (action) {
	case WorldHudMenuAction::ToggleHideAll: return g_optHideAllWorldHud;
	case WorldHudMenuAction::ToggleTeamHud: return g_optTeamWorldHud;
	case WorldHudMenuAction::ToggleWitchKill: return g_optWorldWitchKill;
	case WorldHudMenuAction::ToggleTankKill: return g_optWorldTankKill;
	case WorldHudMenuAction::ToggleRescue: return g_optWorldRescue;
	case WorldHudMenuAction::ToggleMeleeSkeet: return g_optWorldMeleeSkeet;
	case WorldHudMenuAction::ToggleLevel: return g_optWorldLevel;
	case WorldHudMenuAction::ToggleSkeet: return g_optWorldSkeet;
	case WorldHudMenuAction::ToggleTongueCut: return g_optWorldTongueCut;
	case WorldHudMenuAction::ToggleMeleeCrown: return g_optWorldMeleeCrown;
	case WorldHudMenuAction::ToggleCrown: return g_optWorldCrown;
	case WorldHudMenuAction::ToggleActionProgress: return g_optWorldActionProgress;
	case WorldHudMenuAction::ToggleBileMark: return g_optWorldBileMark;
	case WorldHudMenuAction::ToggleTankSlayer: return g_optWorldTankSlayer;
	case WorldHudMenuAction::ToggleWitchStartle: return g_optWorldWitchStartle;
	case WorldHudMenuAction::ToggleBlackWhite: return g_optWorldBlackWhite;
	case WorldHudMenuAction::ToggleFriendlyFire: return g_optWorldFriendlyFire;
	case WorldHudMenuAction::ToggleFriendlyFireDamage: return g_optWorldFriendlyFireDmgNum;
	case WorldHudMenuAction::OpenPage: return false;
	}
	return false;
}

static constexpr int ThrowLandParentSubpage() {
	for (int i = 0; i < WorldHudMenuItemCount(); ++i)
		if (kWorldHudMenu[i].targetPage == kMenuPageThrowLand) return i / kMenuItemsPerPage;
	return -1;
}
