template <typename Item, size_t N>
static const Item* SinglePageMenuItemAt(const Item (&items)[N], int subpage, int digit) {
	return subpage == 0 && digit >= 1 && digit <= SinglePageMenuItemCount(items) ? &items[digit - 1] : nullptr;
}

