					case 2: layLab = UiText(UiId::ChapStatsLayoutTactical, L"战术简报"); break;
					case 3: layLab = UiText(UiId::ChapStatsLayoutGrid, L"档案卡阵列"); break;
					case 4: layLab = UiText(UiId::ChapStatsLayoutArcade, L"街机排行榜"); break;
