static void MainUiRefreshBindings(bool force=false){
 DWORD now=GetTickCount();if(!force&&g_mainUiBindingsAt&&(DWORD)(now-g_mainUiBindingsAt)<200u)return;g_mainUiBindingsAt=now;
 int* values[]={&g_mainUiNativeKey,&g_mainUiHomeKey,&g_mainUiEditKey};bool changed=false;
 for(int i=0;i<3;++i){int vk=g_mainUiFixedShortcuts?VK_F3+i:HoldSemiReloadVirtualKey(EngLookupBinding(kMainUiShortcutCommands[i]));if(vk!=*values[i]){*values[i]=vk;changed=true;}}
 if(changed){g_mainUiHotkeySeed=true;g_mainUiInputSeed=true;++g_mainUiTextRevision;}
}
static void MainUiShortcutRequest(int which){
 if(!g_engine||!SkeetoFeaturesOn()||EngConnected()||EngInGame()||EngDrawingLoading()||g_mainUiKeyCapture>=0||g_mainUiEditTextField)return;
 DWORD now=GetTickCount();if(g_mainUiShortcutStamp&&(DWORD)(now-g_mainUiShortcutStamp)<80u)return;g_mainUiShortcutStamp=now;
 if(which==0)g_mainUiRequest.store(2,std::memory_order_release);
 else {if(!g_optMainMenuUi)MainUiSetEnabled(true);g_mainUiRequest.store(which==2?(g_mainUiEditing?5:3):1,std::memory_order_release);}
}
static void MainUiShortcutsPump(){
 if(!g_ready.load(std::memory_order_relaxed))return;
 MainUiRefreshBindings();
}
static bool MainUiBindShortcut(int which,int vk){
 int code=vk?MainUiEngineKeyCode(vk):0;if(vk&&!code)return false;
 const char* old=EngLookupBinding(kMainUiShortcutCommands[which]);char prior[32]{};if(old&&strlen(old)<sizeof(prior))strcpy_s(prior,old);
 // Only clear this command's binding; never clear an unrelated key assignment.
 if(prior[0]){char command[64]{};snprintf(command,sizeof(command),"unbind \"%s\"",prior);EngClientCmdUnrestricted(command);}
 if(code){char command[96]{};snprintf(command,sizeof(command),"bind %s %s",kMainUiEngineKeys[code],kMainUiShortcutCommands[which]);EngClientCmdUnrestricted(command);}
 g_mainUiBindingsAt=0;MainUiSettingsChanged();return true;
}
static const wchar_t* MainUiKeyLabel(int key){static wchar_t labels[256][48]{};if(!key)return UiText(UiId::MainUiUnbound,L"未绑定");if(key<0||key>255)return L"--";if(!labels[key][0]){UINT scan=MapVirtualKeyW(key,MAPVK_VK_TO_VSC);LONG code=(LONG)(scan<<16);if(key==VK_INSERT||key==VK_DELETE||key==VK_HOME||key==VK_END||key==VK_PRIOR||key==VK_NEXT||key>=VK_LEFT&&key<=VK_DOWN)code|=1<<24;if(!GetKeyNameTextW(code,labels[key],48))swprintf_s(labels[key],L"VK %d",key);}return labels[key];}
static void MainUiStartKeyCapture(int which){if(g_mainUiFixedShortcuts)return;g_mainUiKeyCapture=which;g_mainUiInputSeed=false;for(int i=0;i<256;++i)g_mainUiCaptureKeys[i]=(GetAsyncKeyState(i)&0x8000)!=0;g_mainUiPressed=-1;}
static bool MainUiCaptureInput(){if(g_mainUiKeyCapture<0)return false;
 if(g_mainUiInputSeed){for(int i=0;i<256;++i)g_mainUiCaptureKeys[i]=(GetAsyncKeyState(i)&0x8000)!=0;g_mainUiInputSeed=false;return true;}
 for(int key=VK_BACK;key<256;++key){bool down=(GetAsyncKeyState(key)&0x8000)!=0;bool edge=down&&!g_mainUiCaptureKeys[key];g_mainUiCaptureKeys[key]=down;if(!edge||key==VK_SHIFT||key==VK_CONTROL||key==VK_MENU||key>=VK_LSHIFT&&key<=VK_RMENU)continue;
  if(key!=VK_ESCAPE){int chosen=key==VK_BACK||key==VK_DELETE?0:key;if(!MainUiBindShortcut(g_mainUiKeyCapture,chosen))continue;++g_mainUiTextRevision;}
  g_mainUiKeyCapture=-1;g_mainUiInputSeed=g_mainUiHotkeySeed=true;return true;
 }return true;
}
