static bool MainUiOpenNative(const char* command) {
	// Click/Enter edge on Paint thread, never a per-frame command or a worker call.
	// VGUI_Panel009::GetPanel(55) checks the module and returns the primary Panel.
	// Retail MainMenu::OnCommand is primary-vtable slot 96 (thiscall, ret 4).
	using GetPanelFn = void*(__thiscall*)(void*,unsigned int,const char*);
	using CommandFn = void(__thiscall*)(void*,const char*);
	static HMODULE checkedModule = nullptr;
	static uintptr_t expectedCommand = 0;
	HMODULE module = GetModuleHandleA("gameui.dll");
	if (!module || !command || !command[0] || !MainUiHomeMatches()) { g_mainUiNotice=1; return false; }
	if (module != checkedModule) {
		checkedModule=module;
		// Unique retail command dispatcher, verified against the current x86 DLL.
		expectedCommand=FindPat("gameui.dll", "55 8B EC 81 EC CC 01 00 00 A1 ? ? ? ? 33 C5 89 45 FC 53 8B 5D 08 56 57 8B F1 89 9D 68 FE FF FF");
	}
	auto getPanel=(GetPanelFn)VGet(g_ipanel,55);
	if (!expectedCommand || !getPanel || !IsExec((void*)getPanel)) { g_mainUiNotice=1; return false; }
	__try {
		void* panel=getPanel(g_ipanel,g_mainUiHome,"GameUI");
		auto onCommand=panel ? (CommandFn)VGet(panel,96) : nullptr;
		if (!onCommand || (uintptr_t)onCommand!=expectedCommand || !IsExec((void*)onCommand)) {
			g_mainUiNotice=1; return false;
		}
		// Restore the parent for native dialog close/focus handling. This is a
		// temporary handoff, not F8/native mode: the custom home resumes itself.
		MainUiRestore();
		g_mainUiNative=false; g_mainUiFlyout=-1;
		strncpy_s(g_mainUiLastCommand,command,_TRUNCATE);
		onCommand(panel,command);
		// This action opens Steam's binding overlay rather than a VGUI dialog.
		// Its active state is not exposed by our current input gate.
		if (!_stricmp(command,"SteamController")) g_mainUiNative=true;
		g_mainUiPopupAt=0; g_mainUiInputSeed=true; g_mainUiNotice=0;
		return true;
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_mainUiFault=true; g_mainUiNotice=1; MainUiGate("native-command-fault"); MainUiRestore(); return false;
	}
}

// One explicit click on Paint; names narrow the search, exact dispatcher
// identity is required before calling the retail FoundGames Panel slot 96.
static void MainUiFindLobbySource(unsigned int p,int depth,int* budget,unsigned int* found,int* hits){
 if(!p||*budget<=0||depth>6||g_hvPanelFaulted)return;--*budget;
 if(!HudVguiIsVisible(p)||g_hvPanelFaulted)return;
 const char* name=HudVguiName(p);
 if(!_stricmp(name,"FoundGames")){*found=p;++*hits;return;}
 if(!_stricmp(name,"MainMenu"))return;
 int n=HudVguiChildCount(p);if(n<0||n>256){*budget=0;return;}
 for(int i=0;i<n&&*budget>0&&!g_hvPanelFaulted;++i)MainUiFindLobbySource(HudVguiChild(p,i),depth+1,budget,found,hits);
}
static bool MainUiOpenLobby(const char* mode="coop"){
 static HMODULE checked=nullptr;static uintptr_t expected=0;
 HMODULE module=GetModuleHandleA("gameui.dll");
 if(!module){g_mainUiNotice=1;return false;}
 if(module!=checked){checked=module;expected=FindPat("gameui.dll","55 8B EC 83 EC 4C A1 ? ? ? ? 33 C5 89 45 FC 53 8B 5D 08 56 57 68 ? ? ? ? 53 8B F1 E8 ? ? ? ? 83 C4 08 85 C0");}
 if(!expected){g_mainUiNotice=1;return false;}
 char open[80]{};snprintf(open,sizeof(open),"FriendsMatch_%s",mode);
 if(!MainUiOpenNative(open))return false;
 int budget=192,hits=0;unsigned int found=0;
 MainUiFindLobbySource(HudVguiEnginePanel(1),0,&budget,&found,&hits);
 if(!found||hits!=1||!budget||g_hvPanelFaulted){g_mainUiNotice=1;return false;}
 using GetPanelFn=void*(__thiscall*)(void*,unsigned int,const char*);
 using CommandFn=void(__thiscall*)(void*,const char*);
 auto getPanel=(GetPanelFn)VGet(g_ipanel,55);
 if(!getPanel||!IsExec((void*)getPanel)){g_mainUiNotice=1;return false;}
 __try{void* panel=getPanel(g_ipanel,found,"GameUI");auto command=panel?(CommandFn)VGet(panel,96):nullptr;
  if(!command||(uintptr_t)command!=expected||!IsExec((void*)command)){g_mainUiNotice=1;return false;}
  command(panel,"CreateGame");snprintf(g_mainUiLastCommand,sizeof(g_mainUiLastCommand),"FriendsMatch_%s / CreateGame",mode);g_mainUiPopupAt=0;g_mainUiInputSeed=true;return true;
 }__except(EXCEPTION_EXECUTE_HANDLER){g_mainUiFault=true;g_mainUiNotice=1;MainUiRestore();return false;}
}
