// Match UI keeps its own difficulty dropdown; z_difficulty before Open is often
// overwritten when the player confirms. Reapply for a local listen-host start.
static int g_mainUiExpertPending = 0;
static void MainUiPushExpertDifficulty() {
	EngClientCmdUnrestricted("z_difficulty Impossible");
	CvarWriteValue("z_difficulty", "Impossible");
	g_mainUiExpertPending = 2;
}
static void MainUiClearExpertPending() {
	g_mainUiExpertPending = 0;
}
static void MainUiConsumeExpertPending() {
	if (g_mainUiExpertPending <= 0) return;
	if (!ListenIsHost()) {
		g_mainUiExpertPending = 0;
		return;
	}
	EngClientCmdUnrestricted("z_difficulty Impossible");
	CvarWriteValue("z_difficulty", "Impossible");
	--g_mainUiExpertPending;
}
static std::atomic<int> g_mainUiQuickTestLoadoutState{ 0 };
