static void MainUiQuickTestLoadoutArm(int mapId) {
	if (!MainUiQuickTestMapName(mapId)) return;
	g_mainUiQuickTestLoadoutArmedAt.store(GetTickCount(), std::memory_order_relaxed);
	g_mainUiQuickTestLoadoutState.store(mapId, std::memory_order_release);
}
static void MainUiQuickTestLoadoutLevelInit(const char* mapName) {
	int state = g_mainUiQuickTestLoadoutState.load(std::memory_order_acquire);
	if (!state) return;
	const int mapId = state < 0 ? -state : state;
	const char* expected = MainUiQuickTestMapName(mapId);
	if (!ListenIsHost() || !mapName || !expected || _stricmp(mapName, expected) != 0) {
		g_mainUiQuickTestLoadoutState.compare_exchange_strong(state, 0, std::memory_order_acq_rel);
		return;
	}
	if (state > 0)
		g_mainUiQuickTestLoadoutState.compare_exchange_strong(state, -state, std::memory_order_acq_rel);
}
static void MainUiQuickTestLoadoutPump() {
	int state = g_mainUiQuickTestLoadoutState.load(std::memory_order_acquire);
	if (!state) return;
	if ((DWORD)(GetTickCount() - g_mainUiQuickTestLoadoutArmedAt.load(std::memory_order_relaxed)) >= 300000u) {
		g_mainUiQuickTestLoadoutState.compare_exchange_strong(state, 0, std::memory_order_acq_rel);
		return;
	}
	if (state > 0) return; // Wait for LevelInit to confirm the selected test map.
	if (!ListenIsHost()) {
		g_mainUiQuickTestLoadoutState.compare_exchange_strong(state, 0, std::memory_order_acq_rel);
		return;
	}
	if (!g_paintInGame.load(std::memory_order_relaxed)
		|| g_dbgLifeState.load(std::memory_order_relaxed) != 0
		|| g_dbgLocalTeam.load(std::memory_order_relaxed) != 2
		|| g_dbgObsMode.load(std::memory_order_relaxed) != 0)
		return;
	if (!g_mainUiQuickTestLoadoutState.compare_exchange_strong(state, 0, std::memory_order_acq_rel))
		return;
	// The local test-map host gets one kit; laser attaches to the SMG.
	EngClientCmdUnrestricted("sv_cheats 1; give knife; give smg_silenced; slot1; upgrade_add LASER_SIGHT; give first_aid_kit; give pain_pills; give molotov");
}
