    case 528: {const int next=g_mainUiButtonLimit==256?512:256;if(g_mainUiLayoutCount<=next){g_mainUiButtonLimit=next;MainUiSettingsChanged();}break;}
	case 27: g_mainUiBackgroundOnly.store(true,std::memory_order_relaxed);g_mainUiRequest.store(4,std::memory_order_release);break;
	case 928: {const auto state=SkeetoBackgroundGetPlayback();if(state.available)SkeetoBackgroundSetPaused(!state.paused);break;}
	case 929: break;
	case 24: EngClientCmdUnrestricted("skeeto_background_reload"); break;
	case 26: CycleSoundVolStep(1); MainUiSharedSettingsChanged(); break;
	case 108: MainUiClearExpertPending(); MainUiOpenNative("SoloPlay"); break;
	case 200: case 204:
		g_mainUiFlyout=g_mainUiFlyout==(action==200 ? 8 : 9) ? -1 : action==200 ? 8 : 9;
		g_mainUiFlyAnchor=action; g_mainUiPressed=-1; g_mainUiFocus=g_mainUiFlyout<0 ? action : 300; break;
	case 205: MainUiOpenNative("GroupServer_coop"); break;
