static bool MainUiActionAllowed(int action,bool keyboard) {
 if(action>=10000&&action<50000)return !g_mainUiEditing&&MainUiFriendHitAllowed(action);
	if(g_mainUiEditing){if(g_mainUiEditTextField)return action>=730&&action<=737;
		if(g_mainUiEditActionPage>=0)return action>=880&&action<=898;return (action==738||action==739)||(action>=700&&action<=725)||(action>=kMainUiEditorHitBase&&action<kMainUiEditorHitBase+g_mainUiDraftCount);}
	if(action==208)return true;
	if(action==528&&g_mainUiButtonLimit==512&&g_mainUiLayoutCount>256)return false;
	if(g_mainUiFlyout==12)return (action>=300&&action<309)||action==318||action==319||action==320||action==321||(!keyboard&&action==g_mainUiCustomMenu);
	if(g_mainUiPanel==0 && g_mainUiFlyout>=0){auto* b=MainUiLayoutFind(action);if(b)action=b->action;}
	if ((action==15 || action==24) && (!g_optBackgroundEngine
		|| !g_backgroundCoreInitialized.load(std::memory_order_acquire)
		|| g_backgroundShutdownPending.load(std::memory_order_acquire))) return false;
	if(g_mainUiPanel==1&&(action==928||action==929)){const auto state=SkeetoBackgroundGetPlayback();if(!state.available||(action==929&&!state.seekable))return false;}
	if (g_mainUiFlyout>=0) return (action>=300 && action<316)
		|| (!keyboard && ((action>=100 && action<108) || action==200 || action==204 || action==206));
	if (g_mainUiPanel!=0 && ((action>=100 && action<=108) || action==1 || action==4 || action==5 || action==8 || action==208))
		return false;
	return true;
}
static int MainUiFocusStep(int dir) {
	int eligible[kMainUiHitMax]{},n=0,selected=-1;
	for (int i=0;i<g_mainUiButtonCount && i<kMainUiHitMax;++i) {
		const int action=g_mainUiButtons[i].action;
		if (!MainUiActionAllowed(action,true)) continue;
		if (action==g_mainUiFocus) selected=n;
		eligible[n++]=action;
	}
	if (!n) return -1;
	if (selected<0) return eligible[dir<0 ? n-1 : 0];
	return eligible[(selected+(dir<0 ? n-1 : dir>0 ? 1 : 0))%n];
}
static int MainUiHit(int x,int y) {
	for (int i=g_mainUiButtonCount-1;i>=0;--i) {
		const auto& b=g_mainUiButtons[i];
		if (!MainUiActionAllowed(b.action,false)) continue;
		if (x>=b.x0 && y>=b.y0 && x<b.x1 && y<b.y1) return b.action;
	}
	return -1;
}

static bool MainUiMouse(int* mx, int* my) {
	POINT p{}; RECT rect{};
	if (!g_gameHwnd || !GetCursorPos(&p) || !ScreenToClient(g_gameHwnd, &p)
		|| !GetClientRect(g_gameHwnd, &rect) || rect.right <= 0 || rect.bottom <= 0) return false;
	*mx = MulDiv(p.x, g_mainUiSw, rect.right);
	*my = MulDiv(p.y, g_mainUiSh, rect.bottom);
	return *mx >= 0 && *my >= 0 && *mx < g_mainUiSw && *my < g_mainUiSh;
}
static void MainUiPollInput() {
	if(MainUiCaptureInput())return;
	const int keys[] = {VK_LBUTTON,VK_UP,VK_DOWN,VK_TAB,VK_RETURN,VK_ESCAPE,VK_LEFT,VK_RIGHT,0};
	bool down[9]{};
	for (int i=0;i<9;++i) down[i]=keys[i] && (GetAsyncKeyState(keys[i])&0x8000)!=0;
	if (g_mainUiInputSeed) {
		memcpy(g_mainUiKeys,down,sizeof(down)); g_mainUiInputSeed=false; return;
	}
	int mx=0,my=0;
	const bool mouse=MainUiMouse(&mx,&my);
	const int hit=mouse ? MainUiHit(mx,my) : -1;
    const int oldFocus=g_mainUiFocus;
	if (mouse && (mx!=g_mainUiMouseX || my!=g_mainUiMouseY)) g_mainUiMouseMode=true;
	g_mainUiMouseX=mx; g_mainUiMouseY=my;
	if (down[0] && !g_mainUiKeys[0]) {
		g_mainUiMouseMode=true; g_mainUiPressed=hit;
		if (MainUiSliderValue(hit)||MainUiCustomSlider(hit)||MainUiPlaybackSlider(hit)){g_mainUiFocus=hit;MainUiSound(true);}
	}
	if (down[0] && mouse && MainUiActionAllowed(g_mainUiPressed,false) && (MainUiSliderValue(g_mainUiPressed)||MainUiCustomSlider(g_mainUiPressed))) {if(MainUiCustomSlider(g_mainUiPressed))MainUiCustomSliderDrag(g_mainUiPressed,mx,false);else MainUiDragSlider(g_mainUiPressed,mx);}
	int action=-1;
	if(down[0]&&mouse&&MainUiActionAllowed(g_mainUiPressed,false)&&MainUiPlaybackSlider(g_mainUiPressed))MainUiPlaybackDrag(g_mainUiPressed,mx,false);
	if (!down[0] && g_mainUiKeys[0]) {
        if(mouse&&MainUiActionAllowed(g_mainUiPressed,false)&&MainUiPlaybackSlider(g_mainUiPressed))MainUiPlaybackDrag(g_mainUiPressed,mx,true);
        g_mainUiPlaybackDragId=-1;
        if(mouse&&(g_mainUiPressed==584||g_mainUiPressed==585))MainUiDragSlider(g_mainUiPressed,mx,true);
        if(mouse&&MainUiActionAllowed(g_mainUiPressed,false)&&MainUiCustomSlider(g_mainUiPressed))MainUiCustomSliderDrag(g_mainUiPressed,mx,true);
		if (hit>=0 && hit==g_mainUiPressed && !MainUiSliderValue(hit) && !MainUiCustomSlider(hit) && !MainUiPlaybackSlider(hit)) action=hit;
		else if (hit<0 && g_mainUiFlyout>=0) { g_mainUiFlyout=-1; g_mainUiFocus=g_mainUiFlyAnchor; }
		g_mainUiPressed=-1;
	}
	if ((down[1]&&!g_mainUiKeys[1]) || (down[2]&&!g_mainUiKeys[2]) || (down[3]&&!g_mainUiKeys[3])) {
		g_mainUiMouseMode=false;
		const int dir=down[1] || (down[3]&&(GetAsyncKeyState(VK_SHIFT)&0x8000)) ? -1 : 1;
		g_mainUiFocus=MainUiFocusStep(dir);
	}
	if ((down[6]&&!g_mainUiKeys[6]) || (down[7]&&!g_mainUiKeys[7])) {
		g_mainUiMouseMode=false;
		int* value=MainUiSliderValue(g_mainUiFocus);
		if(MainUiPlaybackSlider(g_mainUiFocus))MainUiPlaybackStep(g_mainUiFocus,down[6]?-1:1);
		else if(MainUiCustomSlider(g_mainUiFocus))MainUiCustomSliderSet(g_mainUiFocus,0,down[6]?-1:1,false,false);
		else if (value) {int next=*value+(down[6] ? -1 : 1)*MainUiSliderStep(g_mainUiFocus);if(g_mainUiFocus==584||g_mainUiFocus==585)MainUiNativeVolumeSet(g_mainUiFocus,next,true);else MainUiSetSlider(g_mainUiFocus,next);}
		else if (down[6] && g_mainUiFlyout>=0) { if(g_mainUiFlyout==12)MainUiCustomBack();else {g_mainUiFlyout=g_mainUiFlyout==11 ? 10 : -1; g_mainUiFocus=g_mainUiFlyout<0 ? g_mainUiFlyAnchor : 300;} }
		else if (down[7] && ((g_mainUiFocus>=100 && g_mainUiFocus<108) || g_mainUiFocus==200 || g_mainUiFocus==204 || g_mainUiFocus==206)) action=g_mainUiFocus;
	}
	if (down[4]&&!g_mainUiKeys[4]) {
		action=g_mainUiMouseMode && hit>=0 ? hit : g_mainUiFocus;
		g_mainUiMouseMode=false;
	}
	if (down[5]&&!g_mainUiKeys[5]) {
		if (g_mainUiFlyout>=0) { if(g_mainUiFlyout==12)MainUiCustomBack();else {g_mainUiFlyout=g_mainUiFlyout==11 ? 10 : -1; g_mainUiFocus=g_mainUiFlyout<0 ? g_mainUiFlyAnchor : 300;} action=-1; }
		else action=g_mainUiPanel ? 13 : 4;
	}

	memcpy(g_mainUiKeys,down,sizeof(down));
	if(g_mainUiFocus!=oldFocus && !g_mainUiMouseMode)MainUiSound(false);
	static int lastHover=-1;if(hit>=0 && hit!=lastHover && g_mainUiMouseMode)MainUiSound(false);lastHover=hit;
	if (action>=0){MainUiSound(true);MainUiDispatch(action);}
}

// Localized labels and versioned editor values, fitted once per content change.
// Fixed cache, bounded binary search, no allocation or recurring measurement.
static void MainUiText(unsigned long font, int x, int y, COLORREF color, const wchar_t* text, int width, unsigned contentVersion=0, int* drawnWidth=nullptr) {
	if(drawnWidth)*drawnWidth=0;
	if (!text || !text[0] || width <= 0) return;
	struct Fit { const wchar_t* source; unsigned long font; int width,drawnWidth; unsigned contentVersion; wchar_t text[192]; };
	static Fit cache[kMainUiLayoutMax*3]{};
	static unsigned next = 0;
	static int epoch = 0;
	static unsigned revision=0;static bool english=false;const bool language=g_uiEnglish.load(std::memory_order_relaxed);
	if (epoch != g_sktFontEpoch || revision != g_mainUiTextRevision || english!=language) {
		memset(cache,0,sizeof(cache)); epoch=g_sktFontEpoch; revision=g_mainUiTextRevision;english=language;next=0;
	}
	Fit* changed=nullptr;
	// Fixed open-addressed lookup; no allocations, the same cache capacity and
	// invalidation rules. Warm draws no longer walk every preceding text label.
	unsigned hash=(unsigned)(uintptr_t)text ^ (unsigned)font*0x9e3779b9u ^ (unsigned)width*0x85ebca6bu;
	hash^=hash>>16;hash*=0x7feb352du;hash^=hash>>15;
	const unsigned start=hash%(kMainUiLayoutMax*3);
	for(unsigned probe=0;probe<kMainUiLayoutMax*3;++probe){
		auto& item=cache[(start+probe)%(kMainUiLayoutMax*3)];
		if(!item.source){changed=&item;break;}
		if (item.source == text && item.font == font && item.width == width) {
			if(item.contentVersion==contentVersion){if(drawnWidth)*drawnWidth=item.drawnWidth;SurfTextAt(font,x,y,color,item.text); return;}
			changed=&item;break;
		}
	}
	auto& item = changed?*changed:cache[next++ % (kMainUiLayoutMax*3)];
	item.source = text; item.font = font; item.width = width; item.contentVersion=contentVersion;
	wcsncpy_s(item.text,text,_TRUNCATE);
	item.drawnWidth=SurfTextWFont(font,item.text);
	if (item.drawnWidth > width) {
		int lo = 0, hi = (int)wcslen(item.text);
		wchar_t trial[192]{};
		// Reserve one position for the ellipsis and one for the terminator.
		if (hi > 190) hi = 190;
		while (lo < hi) {
			const int n = (lo + hi + 1) / 2;
			wmemcpy(trial,item.text,n); trial[n] = 0x2026; trial[n+1] = 0;
			if (SurfTextWFont(font,trial) <= width) lo = n; else hi = n - 1;
		}
		item.text[lo] = 0x2026; item.text[lo+1] = 0;
		item.drawnWidth=SurfTextWFont(font,item.text);
		if (item.drawnWidth > width) {item.text[0] = 0;item.drawnWidth=0;}
	}
	if(drawnWidth)*drawnWidth=item.drawnWidth;
	SurfTextAt(font,x,y,color,item.text);
}
