static void MainUiPrepareLayer() {
	if (g_mainUiUnderlay) {
		if (!BackgroundInstallGameUiHook()) {
			MainUiRestore(); MainUiGate("underlay-unavailable");
		}
	} else if (!g_backgroundWasMenuActive || !g_optBackgroundEngine || !g_backgroundCoreInitialized.load(std::memory_order_acquire)
		|| g_backgroundShutdownPending.load(std::memory_order_acquire)) {
		BackgroundRemoveGameUiHook();
	}
}
static void MainUiPaintUnderlay() {
	if (g_mainUiBackgroundOnly.load(std::memory_order_relaxed) || !g_mainUiUnderlay || !g_mainUiDraw || !g_run.load(std::memory_order_relaxed)
		|| !SkeetoFeaturesOn() || !g_optMainMenuUi) return;
	// Native PaintBackground already owns the Surface context. Do not begin/end
	// another one or poll input; foreground native controls retain their input.
	SurfFillFlush(); SurfDrawColorInvalidate();
	MainUiDrawHome(false); ++g_mainUiDrawCount;
	SurfFillFlush(); SurfDrawColorInvalidate();
}
static void MainUiPaintStartup(int mode){
 if(g_mainUiBackgroundOnly.load(std::memory_order_relaxed)||!g_mainUiDraw||g_mainUiUnderlay||!(mode&kPaintUiPanels))return;
 SurfFillFlush();SurfDrawingLease drawing;if(!drawing.ready)return;SurfDrawColorInvalidate();MainUiDrawHome(false);++g_mainUiDrawCount;
 SurfFillFlush();SurfDrawColorInvalidate();
}
static void MainUiAfterPaint(int mode) {
    if(g_mainUiBackgroundOnly.load(std::memory_order_relaxed))return;
	if (g_mainUiUnderlay) return; // Drawn beneath native panels, never over them.
	if (!g_mainUiDraw || !(mode & kPaintUiPanels)) return;
	if (g_mainUiFontEpoch != g_sktFontEpoch && !MainUiEnsureFonts()) { MainUiRestore(); return; }
	SurfFillFlush();
	SurfDrawingLease drawing;
	if (!drawing.ready) return;
	SurfDrawColorInvalidate();
	if(!g_mainUiInputReady.load(std::memory_order_acquire)){if(g_menuVisible&&!g_menuParked)MenuPaintEngine();else MainUiDrawHome(false);++g_mainUiDrawCount;SurfFillFlush();SurfDrawColorInvalidate();return;}
	MenuPollPaintKeys(); MenuTick();
	if (g_menuVisible && !g_menuParked) {
		g_mainUiInputSeed = true; g_mainUiPressed = -1;
		MenuPaintEngine();
		++g_mainUiDrawCount;
	} else if (g_mainUiDraw) {
		MainUiDrawHome(true); // Hit regions only; no dry-pass drawing/measurement.
		if(!g_mainUiEditing)g_mainUiFocus=MainUiFocusStep(0);
		if(g_mainUiEditing)MainUiEditorPoll();else MainUiPollInput();
		if (g_mainUiDraw && !g_menuVisible) { MainUiDrawHome(false); ++g_mainUiDrawCount; }
		else if (g_menuVisible) { MenuPaintEngine(); ++g_mainUiDrawCount; }
	}
	SurfFillFlush();
	SurfDrawColorInvalidate();
}
