static void SktCvarPinPath(wchar_t* out, int cap) {
	if (!out || cap < 8) return;
	out[0] = 0;
	if (!g_escUiDirectory[0]) return;
	swprintf_s(out, cap, L"%s\\skt_cvar_pins.txt", g_escUiDirectory);
}

static void SktCvarEnsureLoaded() {
	if (g_sktCvarPinsLoaded || !g_optSktCvarRemember || !g_escUiDirectory[0]) return;
	g_sktCvarPinsLoaded = true;
	wchar_t path[SKT_PATH_CAP]{};
	SktCvarPinPath(path, SKT_PATH_CAP);
	if (!path[0]) return;
	FILE* f = _wfopen(path, L"rb");
	if (!f) return;
	g_sktCvarLoading = true;
	char line[320]{};
	while (fgets(line, (int)sizeof(line), f)) {
		char* eq = strchr(line, '=');
		if (!eq || eq == line) continue;
		*eq = 0;
		char* val = eq + 1;
		val[strcspn(val, "\r\n")] = 0;
		if (!SktCvarNameOk(line) || strlen(line) >= 80 || strlen(val) >= 192 || !val[0]) continue;
		SktCvarRemember(line, nullptr, val);
	}
	fclose(f);
	g_sktCvarLoading = false;
	g_sktCvarSaveAt = 0;
}

static void SktCvarApplyLoaded() {
	SktCvarEnsureLoaded();
	if (g_sktCvarSuspended || !SkeetoFeaturesOn()) return;
	for (int i = 0; i < g_sktCvarN; ++i) {
		SktCvarSlot& s = g_sktCvarSlots[i];
		if (!s.name[0] || !s.desired[0]) continue;
		void* var = CvarFind(s.name);
		if (!var) {
			Log("skt_cvar: remembered pin skipped, ConVar missing (%s)", s.name);
			continue;
		}
		if (!s.haveOriginal) {
			char original[64]{};
			SktCvarFormatValue(var, original, (int)sizeof(original));
			if (original[0]) {
				strncpy(s.original, original, sizeof(s.original) - 1);
				s.haveOriginal = true;
			}
		}
		SktCvarSetFromString(var, s.name, s.desired);
	}
}

static void SktCvarFlushPins(bool force) {
	if (!g_escUiDirectory[0]) return;
	if (!force) {
		if (!g_sktCvarSaveAt || (LONG)(GetTickCount() - g_sktCvarSaveAt) < 0) return;
	} else if (!g_sktCvarSaveAt && !g_sktCvarJobPending.load(std::memory_order_acquire)) {
		return;
	}
	if (g_sktCvarJobPending.load(std::memory_order_acquire)) return;
	g_sktCvarSaveAt = 0;
	if (!g_optSktCvarRemember) return;
	SktCvarPinJob job{};
	job.n = 0;
	for (int i = 0; i < g_sktCvarN && job.n < kSktCvarMax; ++i) {
		const SktCvarSlot& s = g_sktCvarSlots[i];
		if (!s.name[0] || !s.desired[0] || !SktCvarNameOk(s.name)) continue;
		strncpy(job.name[job.n], s.name, 79);
		strncpy(job.desired[job.n], s.desired, 191);
		++job.n;
	}
	g_sktCvarJob = job;
	g_sktCvarJobPending.store(1, std::memory_order_release);
}

static void SktCvarClearPins() {
	for (int i = 0; i < g_sktCvarN; ++i) {
		SktCvarSlot& s = g_sktCvarSlots[i];
		if (s.haveOriginal && s.name[0])
			SktCvarSetFromString(nullptr, s.name, s.original);
	}
	g_sktCvarN = 0;
	memset(g_sktCvarSlots, 0, sizeof(g_sktCvarSlots));
	g_sktCvarSaveAt = 0;
	g_sktCvarPinsLoaded = true;
	if (g_sktCvarJobPending.load(std::memory_order_acquire)) return;
	g_sktCvarJob = {};
	g_sktCvarJob.n = -1;
	g_sktCvarJobPending.store(1, std::memory_order_release);
}

static void SktCvarWritePinJob() {
	if (!g_sktCvarJobPending.exchange(0, std::memory_order_acq_rel)) return;
	wchar_t path[SKT_PATH_CAP]{};
	SktCvarPinPath(path, SKT_PATH_CAP);
	if (!path[0]) return;
	if (g_sktCvarJob.n < 0) {
		DeleteFileW(path);
		return;
	}
	wchar_t directory[SKT_PATH_CAP]{};
	wcscpy_s(directory, g_escUiDirectory);
	const int made = SHCreateDirectoryExW(nullptr, directory, nullptr);
	if (made != ERROR_SUCCESS && made != ERROR_ALREADY_EXISTS && made != ERROR_FILE_EXISTS) {
		Log("skt_cvar: pin directory unavailable");
		return;
	}
	wchar_t temporary[SKT_PATH_CAP + 8]{};
	swprintf_s(temporary, L"%s.tmp", path);
	FILE* f = _wfopen(temporary, L"wb");
	if (!f) {
		Log("skt_cvar: pin file not written");
		return;
	}
	for (int i = 0; i < g_sktCvarJob.n; ++i)
		fprintf(f, "%s=%s\n", g_sktCvarJob.name[i], g_sktCvarJob.desired[i]);
	fclose(f);
	if (!MoveFileExW(temporary, path, MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)) {
		DeleteFileW(temporary);
		Log("skt_cvar: pin file not replaced");
	}
}

static void EscUiWorkerPump(){
    skescpreset::Worker();
    SktCvarWritePinJob();
    const int job=g_escUiIoJob.exchange(0,std::memory_order_acquire);if(!job)return;
    wchar_t path[SKT_PATH_CAP]{};
    if(job==4){
        swprintf_s(path,L"%s\\profiles",g_escUiDirectory);
        const int result=SHCreateDirectoryExW(nullptr,path,nullptr);
        g_escUiIoResult.store(result==ERROR_SUCCESS||result==ERROR_ALREADY_EXISTS||result==ERROR_FILE_EXISTS?1:3,std::memory_order_release);
        return;
    }
    if(job==1)wcscpy_s(path,g_escUiCurrentPath);
    else swprintf_s(path,L"%s\\profiles\\slot%d.hud",g_escUiDirectory,g_escUiIoProfile);
    int result=job==3?skescio::Load(path,g_escUiIoLayout):(skescio::Save(path,g_escUiIoLayout)?1:-1);
    g_escUiIoResult.store(result==1?1:result==0?2:3,std::memory_order_release);
}
static bool EscUiPostIo(int kind){
    if(g_escUiIoBusy){g_escUiStatus=EscUiStatus::Busy;return false;}
    g_escUiIoKind=kind;g_escUiIoProfile=g_escUiProfile;
    if(kind==1||kind==2)g_escUiIoLayout=kind==1?g_escUiLayout:g_escUiDraft;
    g_escUiIoBusy=true;g_escUiStatus=EscUiStatus::Saving;g_escUiIoJob.store(kind,std::memory_order_release);return true;
}
static void EscUiConfigPump(){
    if(!g_escUiIoBusy)return;
    const int result=g_escUiIoResult.exchange(0,std::memory_order_acq_rel);if(!result)return;
    g_escUiIoBusy=false;
    if(g_escUiIoKind==4){
        g_escUiStatus=result!=1?EscUiStatus::SaveError:MainUiServicesOpen(1,"left4dead2\\skeeto\\escmenu\\profiles")?EscUiStatus::Ready:EscUiStatus::Busy;
    }else if(g_escUiIoKind==3){
        if(g_escUiEditing&&result==1){g_escUiDraft=g_escUiIoLayout;g_escUiSelected=0;EscUiSelectOne(0);g_escUiFlyout=-1;g_escUiFlyoutPage=0;g_escUiTextDirty=true;g_escUiStatus=EscUiStatus::ProfileLoaded;}
        else if(g_escUiEditing)g_escUiStatus=result==2?EscUiStatus::ProfileMissing:EscUiStatus::BadProfile;
    }else g_escUiStatus=result==1?(g_escUiIoKind==1?EscUiStatus::Saved:EscUiStatus::ProfileSaved):EscUiStatus::SaveError;
}
