static void EscUiRestore() {
    EscUiNativeRelease();
    g_escUiOwned=false;EscUiSuspendInput();
}
static void EscUiFindHome(unsigned int p,int depth,int& budget,unsigned int& found,int& hits) {
    if(!p||budget<=0||depth>6||g_hvPanelFaulted)return;
    --budget;if(!HudVguiIsVisible(p))return;
    if(!_stricmp(HudVguiName(p),"InGameMainMenu")){found=p;++hits;return;}
    const int count=HudVguiChildCount(p);
    if(count<0||count>256){budget=0;return;}
    if(depth==6)return;
    for(int i=0;i<count&&budget>0&&!g_hvPanelFaulted;++i)
        EscUiFindHome(HudVguiChild(p,i),depth+1,budget,found,hits);
}
static void EscUiBeforePaint(int mode) {
    EscUiConfigPump();EscUiExtrasPump();
    const int request=g_escUiRequest.exchange(0,std::memory_order_acq_rel);
    if(request==1)EscUiSetEnabled(true);
    else if(request==2)EscUiSetEnabled(false);
    else if((request>=3&&request<=5)||(request<=-3&&request>=-5)){
        const int opening=request<0?-request:request;
        if(g_engine&&g_run.load(std::memory_order_relaxed)&&EngConnected()&&EngInGame()&&!EngDrawingLoading()
            &&(opening==3||SkeetoFeaturesOn())){
            if(request>0){
                if(opening!=3&&!g_optEscMenuUi)EscUiSetEnabled(true);
                EscUiShow(opening==3);
            }
            if(!EngGameUiVisible()){
                // Negative requests wait for the one queued activation. A new
                // user request wins; never enqueue activation every Paint.
                int empty=0;g_escUiRequest.compare_exchange_strong(empty,-opening,std::memory_order_release,std::memory_order_relaxed);
            }else{
                if(opening!=4&&g_escUiEditing)EscUiAbortEditor();
                g_escUiRoute=opening==3?EscUiRoute::Native:EscUiRoute::Custom;
                if(opening==4)g_escUiEditRequested=true;
            }
        }
    }
    if(!g_optEscMenuUi&&!g_escUiHome&&!g_escUiHomeTable){g_escUiOpen=false;g_escUiGate="disabled";return;}
    const bool allowed=g_engine&&EscUiContext(g_optEscMenuUi,g_run.load(std::memory_order_relaxed),SkeetoFeaturesOn(),
        EngConnected(),EngInGame(),EngDrawingLoading());
    if(!allowed){
        EscUiExtrasClose();
        if(g_escUiEditing||g_escUiEditRequested)EscUiAbortEditor();
        EscUiRestore();g_escUiHome=g_escUiParent=0;g_escUiIdentity=0;
        g_escUiOpen=false;g_escUiRoute=EscUiRoute::Custom;g_escUiSearchAt=0;g_escUiGate="disabled-or-outside-game";return;
    }
    if(g_escUiRoute!=EscUiRoute::Native&&!g_escUiFault&&!g_hvPanelFaulted&&!g_escUiOwned){
        if(!HudVguiReady()||!EscUiNativeAcquire()){
            g_escUiFault=true;EscUiRestore();g_escUiGate="native-bridge-unavailable";return;
        }
    }
    const bool gameUi=EngGameUiVisible();
    g_escUiDraw=false;
    if(!gameUi){
        if(g_escUiOpen){
            // End the opening once. A console must not leak into the next ESC.
            if(BackgroundConsoleOpen())EngClientCmdUnrestricted("hideconsole");
            if(g_escUiEditing||g_escUiEditRequested)EscUiAbortEditor();
            EscUiExtrasClose();EscUiNativeFlyoutReturn();EscUiSuspendInput();g_escUiOpen=false;g_escUiRoute=EscUiRoute::Custom;g_escUiFlyout=-1;g_escUiFlyoutPage=0;
        }
        g_escUiGate="closed";return;
    }
    g_escUiOpen=true;
    if(!(mode&kPaintUiPanels))return;
    if(g_escUiFault||g_hvPanelFaulted){EscUiRestore();g_escUiGate="panel-or-command-fault";return;}
    if(g_escUiRoute==EscUiRoute::Native){EscUiRestore();g_escUiGate="explicit-native";return;}
    if(!MenuEnsureSurf()||!HudVguiReady()||!SurfEnsureDrawingFns()){g_escUiGate="surface-unavailable";return;}
    if(g_escUiHome&&!EscUiHomeMatches()){
        g_escUiHome=0;g_escUiBasePanel=nullptr;g_escUiSearchAt=0;
    }
    const DWORD now=GetTickCount();
    if(!g_escUiHome){
        if(g_escUiSearchAt&&(LONG)(now-g_escUiSearchAt)<0)return;
        g_escUiSearchAt=now+250u;int budget=192,hits=0;unsigned int found=0;
        EscUiFindHome(HudVguiEnginePanel(1),0,budget,found,hits);
        if(hits!=1||!budget||g_hvPanelFaulted){g_escUiGate="home-not-unique-or-budget";return;}
        g_escUiHome=found;g_escUiParent=HudVguiParent(found);g_escUiIdentity=HudVguiPanelIdentity(found);
        g_escUiSeed=true;
    }
    if(!EscUiNativeBaseReady()||g_escUiNativeFaults.load(std::memory_order_relaxed)){
        g_escUiFault=true;EscUiRestore();g_escUiGate="native-entry-fault";return;
    }
    const bool foreground=g_gameHwnd&&GetForegroundWindow()==g_gameHwnd;
    const bool console=BackgroundConsoleOpen();
    const bool steamChord=foreground&&(GetAsyncKeyState(VK_SHIFT)&0x8000)&&(GetAsyncKeyState(VK_TAB)&0x8000);
    // Steam's overlay can retain focus after Shift+Tab is released. Preserve
    // the opening's suspended route, without restoring the stock homepage;
    // closing/reopening ESC or an explicit home/edit request returns ownership.
    if(steamChord)g_escUiRoute=EscUiRoute::Suspended;
    if(!foreground||console||g_escUiRoute==EscUiRoute::Suspended||(g_menuVisible&&!g_menuParked)){
        EscUiSuspendInput();g_escUiGate="interaction-suspended";return;
    }
    if(!SurfGetScreenSize(&g_escUiWidth,&g_escUiHeight)||g_escUiWidth<640||g_escUiHeight<360){
        EscUiSuspendInput();g_escUiGate="screen-size";return;
    }
    g_escUiDraw=true;g_escUiGate="ready";
    if(g_escUiEditRequested)EscUiBeginEditor();
}

static void EscUiActivate(int action) {
    if(action==6||action==skesc::kQuit){EscUiSuspendInput();EngClientCmdUnrestricted(action==6?"disconnect":"quit");return;}
    if(action==7){EscUiRestore();g_escUiRoute=EscUiRoute::Native;return;}
    if(action==5){EscUiSuspendInput();if(!g_menuVisible)MenuToggle();return;}
    // Retail x86 InGameMainMenu, distinct from MainMenu: primary slot 96,
    // ECX=this, one const char* argument, ret 4. Resolve only on an action edge.
    using GetFn=void*(__thiscall*)(void*,unsigned int,const char*);
    using CommandFn=void(__thiscall*)(void*,const char*);
    static uintptr_t expected=0;
    if(!expected)expected=FindPat("gameui.dll","55 8B EC 81 EC C0 00 00 00 A1 ? ? ? ? 33 C5 89 45 FC 53 56 8B 75 08 57 8B F9");
    auto get=(GetFn)VGet(g_ipanel,55);
    if(!expected||!get||!IsExec((void*)get)||!EscUiHomeMatches()){
        EscUiRestore();g_escUiFault=true;g_escUiGate="native-entry-unavailable";return;
    }
    __try{
        void* panel=get(g_ipanel,g_escUiHome,"GameUI");
        auto command=panel?(CommandFn)VGet(panel,96):nullptr;
        if((uintptr_t)command!=expected){EscUiRestore();g_escUiFault=true;g_escUiGate="native-entry-mismatch";return;}
        EscUiSuspendInput();if(action==skesc::kNativeVote||action==skesc::kNativeOptions){
            const char* flyout=action==skesc::kNativeVote?"FlmVoteFlyout":"FlmOptionsFlyout";
            EscUiNativeKeyboard(g_escUiHome,true);
            command(panel,flyout);
            if(!EscUiNativeFlyoutTake(flyout)){
                g_escUiFault=true;EscUiRestore();g_escUiGate="native-flyout-unavailable";
            }
        }else command(panel,EscUiNativeItem(action).command);
    }__except(EXCEPTION_EXECUTE_HANDLER){g_escUiFault=true;EscUiRestore();g_escUiGate="native-command-fault";}
}
