static bool SurvivorGlowParseHex(const char* s, int* out) {
	if (!s || !out) return false;
	if (*s == '#') ++s;
	else if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) s += 2;
	if (strlen(s) != 6) return false;
	for (int i = 0; i < 6; ++i) if (!isxdigit((unsigned char)s[i])) return false;
	const unsigned rgb = strtoul(s, nullptr, 16);
	*out = RGB((rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF);
	return true;
}

static void SkCmd_SurvivorGlow(int* cmd, int character, const char* commandName) {
	if (character < 0 || character >= kTeamHudCharMax) return;
	bool changed = false;
	if (CmdArgC(cmd) >= 2) {
		const char* a = CmdArg(cmd, 1);
		int color = -1;
		if (!_stricmp(a, "default") || !_stricmp(a, "server") || !_stricmp(a, "off") || !strcmp(a, "-1")) {
			color = -1;
			changed = true;
		} else if (!_stricmp(a, "preset") || !_stricmp(a, "skt")) {
			color = kSurvivorGlowPreset[character];
			changed = true;
		} else if (CmdArgC(cmd) >= 4) {
			const int r = atoi(CmdArg(cmd, 1));
			const int g = atoi(CmdArg(cmd, 2));
			const int b = atoi(CmdArg(cmd, 3));
			if (r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255) {
				color = RGB(r, g, b);
				changed = true;
			}
		} else if (SurvivorGlowParseHex(a, &color)) {
			changed = true;
		}
		if (changed) {
			g_survivorGlowColor[character] = color;
			SurvivorGlowConfigChanged();
			SaveSettings();
		}
	}
	const int color = g_survivorGlowColor[character];
	char b[192]{};
	if (color < 0)
		snprintf(b, sizeof(b), "%s default  (RGB: %s R G B | preset | default)", commandName, commandName);
	else
		snprintf(b, sizeof(b), "%s %d %d %d  (#%02X%02X%02X)", commandName,
			color & 0xFF, (color >> 8) & 0xFF, (color >> 16) & 0xFF,
			color & 0xFF, (color >> 8) & 0xFF, (color >> 16) & 0xFF);
	ConEcho(b);
}


static bool WorldNamesParseInt(const char* text,int lo,int hi,int* out) {
 if(!text||!*text||!out) return false;
 char* end=nullptr;const long value=strtol(text,&end,10);
 if(!end||*end||value<lo||value>hi) return false;
 *out=(int)value;return true;
}
