static void SkCmd_Plugins(int* cmd) {
    const int argc=CmdArgC(cmd);const char* action=CmdArg(cmd,1);
    if(argc==2 && !_stricmp(action,"status")){
        const auto c=skplugins::Stats();char text[320]{};
        snprintf(text,sizeof(text),"[Skeeto plugins] next_start=%d started=%d loading=%d count=%u limit=%d loads=%u init=%u builds=%u actions=%u pending=%d",
            g_optPluginPlatform?1:0,skplugins::Started()?1:0,skplugins::Loading()?1:0,skplugins::Count(),skplugins::Limited()?1:0,
            c.loads,c.inits,c.builds,c.actions,skplugins::Pending()?1:0);ConEcho(text);
        for(unsigned i=0;i<skplugins::Count();++i){const auto* p=skplugins::At(i);
            snprintf(text,sizeof(text),"[Skeeto plugins] slot=%u id=%s state=%u error=%u menu=%d",i+1,p->id,(unsigned)p->state,p->error,p->hasMenu?1:0);ConEcho(text);}
        return;
    }
    if(argc==2 && (!_stricmp(action,"on") || !_stricmp(action,"off"))){
        g_optPluginPlatform=!_stricmp(action,"on");g_settingsDirty=true;g_settingsSaveAt=GetTickCount()+400;MenuMarkDirty();
        ConEcho("[Skeeto plugins] Startup setting changed; takes effect after a full game restart.");return;
    }
    if(argc==2 && !_stricmp(action,"refresh")){PluginMenuRefresh();return;}
    if(argc==1 || (argc==2 && !_stricmp(action,"open"))){
        if(!g_menuVisible)MenuToggle();
        if(g_menuVisible){MenuReturnReset();g_menuPage=kMenuPagePluginPlatform;g_menuSub=0;MenuMarkDirty();}
        return;
    }
    ConEcho("skeeto_plugins: open | status | on | off | refresh (on/off apply next process)");
}

