static void* RegisterSkeetoIntConVar(const char* name, const char* help,
	int initial, int defaultValue, int lo, int hi) {
	if (!g_cvar || !name || !name[0]) return nullptr;
	if (void* existing = CvarFind(name)) return existing;
	// L4D2 ConVar layout is confirmed elsewhere in this module by its parent and
	// value offsets. Reuse the engine-owned ConVar vtables and register fixed,
	// process-lifetime objects with buffers large enough for every legal value.
	void* prototype = CvarFind("volume");
	if (!prototype || !PtrCommitted(prototype)) {
		Log("WARN: ConVar prototype unavailable for '%s'", name);
		return nullptr;
	}
	uint8_t* mem = (uint8_t*)malloc(96);
	char* value = (char*)malloc(16);
	char* defaultText = (char*)malloc(16);
	if (!mem || !value || !defaultText) {
		if (mem) free(mem);
		if (value) free(value);
		if (defaultText) free(defaultText);
		return nullptr;
	}
	memset(mem, 0, 96);
	snprintf(value, 16, "%d", initial);
	snprintf(defaultText, 16, "%d", defaultValue);
	*(void**)(mem + 0x00) = *(void**)((uint8_t*)prototype + 0x00);
	*(const char**)(mem + 0x0C) = name;
	*(const char**)(mem + 0x10) = help;
	*(int*)(mem + 0x14) = kFCvarArchive;
	*(void**)(mem + 0x18) = *(void**)((uint8_t*)prototype + 0x18);
	*(void**)(mem + 0x1C) = mem;
	*(const char**)(mem + 0x20) = defaultText;
	*(char**)(mem + 0x24) = value;
	*(int*)(mem + 0x28) = 16;
	*(float*)(mem + 0x2C) = (float)initial;
	*(int*)(mem + 0x30) = initial;
	*(bool*)(mem + 0x34) = true;
	*(float*)(mem + 0x38) = (float)lo;
	*(bool*)(mem + 0x3C) = true;
	*(float*)(mem + 0x40) = (float)hi;
	using RegisterFn = void(__thiscall*)(void*, void*);
	auto registerFn = (RegisterFn)VGet(g_cvar, 6);
	if (!registerFn || !IsExec((void*)registerFn)) {
		Log("WARN: ConVar register entry unavailable for '%s'", name);
		free(defaultText);
		free(value);
		free(mem);
		return nullptr;
	}
	registerFn(g_cvar, mem);
	void* var = CvarFind(name);
	if (!var) {
		Log("WARN: ConVar registration failed for '%s'", name);
		return nullptr;
	}
	Log("cvar '%s' registered value=%d range=%d..%d", name, initial, lo, hi);
	return var;
}

