static bool FastLoadAttachFailed() {
	if (!g_optFastLoad) return false;
	switch (skload::g_status) {
	case skload::Status::Unsupported:
	case skload::Status::Conflict:
	case skload::Status::PatchFailed:
		return true;
	default:
		return false;
	}
}
static const wchar_t* FastLoadStatusText() {
	const auto status=skload::g_status==skload::Status::Off && g_optFastLoad && g_optFastLoadLocalTransition
		&& g_fastLoadLocalLevel.load(std::memory_order_relaxed)
		? skload::g_localTransitionWait.status : skload::g_status;
	switch (status) {
	case skload::Status::Ready: return UiText(UiId::FastLoadReady, L"已接入，详细统计见控制台");
	case skload::Status::Unsupported: return UiText(UiId::FastLoadUnsupported, L"游戏调用点不匹配，未接入");
	case skload::Status::Conflict: return UiText(UiId::FastLoadConflict, L"调用点被其他模块改动，已停用");
	case skload::Status::PatchFailed: return UiText(UiId::FastLoadFailed, L"调用点修改失败，已停用");
	default: return UiText(UiId::FastLoadOff, L"未启用");
	}
}
static bool FastLoadAsyncRead(const char* name,int* n,float* f) {
	void* var=CvarFind(name);
	return var && CvarReadPair(var,n,f);
}
static bool FastLoadAsyncWrite(const char* name,int n,float f) {
	// The retail loaders poll numeric fields directly. One write per switch that
	// was off, at each load edge. No callback/string edits and no writes during play.
	void* var=CvarFind(name);
	if(!var || !CvarPokePair(var,n,f))return false;
	int actualInt=0;float actualFloat=0;
	return CvarReadPair(var,&actualInt,&actualFloat) && actualInt==n && actualFloat==f;
}
// Both helpers run only at loading metadata edges on the admitted owner thread.
static void FastLoadVpkTarget() {
	using Fn=const char*(__thiscall*)(void*);
	auto* module=(uint8_t*)GetModuleHandleA("engine.dll");
	void* fn=g_engine?VGet(g_engine,52):nullptr;
	// Retail VEngineClient013 slot52 returns clientstate+0xe0 once state>=2.
	uint8_t expected[]={0x80,0x3d,0,0,0,0,0,0x74,0x06,0xb8,0,0,0,0,0xc3,0xe8,0xcc,0x3a,0x02,0,0x83,0x78,0x68,0x02,0x7d,0x06,0xb8,0,0,0,0,0xc3,0xe8,0xbb,0x3a,0x02,0,0x05,0xe0,0,0,0,0xc3};
	if(!module||fn!=module+0x5f1c0){++skvpkexp::g_controller.stats.failures;return;}
	uintptr_t p=uintptr_t(module+0x645680);memcpy(expected+2,&p,4);
	p=uintptr_t(module+0x35a658);memcpy(expected+10,&p,4);
	p=uintptr_t(module+0x3504a0);memcpy(expected+27,&p,4);uint8_t actual[sizeof(expected)]{};
	if(!skmem::Copy(actual,fn,sizeof(actual))||memcmp(actual,expected,sizeof(actual))){++skvpkexp::g_controller.stats.failures;return;}
	skvpkexp::g_controller.SetMap(((Fn)fn)(g_engine));
}
static int FastLoadVpkMission(const char* name,const char* map,skvpkexp::MapSet& campaign) {
	if(strchr(name,'/')||strchr(name,'\\')||strstr(name,".."))return -1;
	char path[100]{};snprintf(path,sizeof(path),"missions/%s.txt",name);void* data=nullptr;int size=0;
	// GAME reads recurse into the existing splitter. Preserve its outer one-key
	// cache only for these <=128 cold metadata reads, never on ordinary queries.
	const auto saved=skload::g_pathCache;
	const bool read=DlcReadGameBinaryLimited(nullptr,path,&data,&size,65536);
	skload::g_pathCache=saved;
	if(!read)return -1;
	const int result=skvpkexp::MissionContains((const char*)data,size,map,campaign);free(data);return result;
}
static void FastLoadAsyncEdge(bool loading) {
	if(loading) {
		if(EngDrawingLoading()) {
			if(skvpkexp::g_controller.enabled){skvpkexp::g_controller.BeginLoad();if(skvpkexp::g_controller.enabled&1u)FastLoadVpkTarget();}
			skload::g_nativePreload.Begin();
			const unsigned experiments=(skload::g_mode.load(std::memory_order_relaxed)>>8)&7u;
			if(experiments) {
				auto& lease=skload::g_loadingExperiments;
				lease.read=FastLoadAsyncRead;lease.write=FastLoadAsyncWrite;lease.Begin(experiments);
			}
		}
	} else {
		const bool asyncDone=skload::g_nativePreload.Complete();
		const bool experimentsDone=skload::g_loadingExperiments.Complete();
		if(!asyncDone || !experimentsDone)skload::g_status=skload::Status::PatchFailed;
	}
}
static void FastLoadBindNativeAsync() {
	static bool checked=false;
	if(checked)return;
	checked=true;
	auto* module=reinterpret_cast<uint8_t*>(GetModuleHandleW(L"datacache.dll"));
	void* object=GetIface("datacache.dll","MDLCache004");
	uintptr_t table=0;
	if(!module || !object || !skmem::Copy(&table,object,4) || table!=uintptr_t(module+0x2ad14))return;
	// Retail x86 SHA256 520aa669...25a4b9: MDLCache004 slot 29,
	// void __thiscall FinishPendingLoads(void*), RVA f3a0; REA ev_1b86b4f3.
	uint8_t wanted[]{0x55,0x8b,0xec,0x51,0x53,0x8b,0xd9,0xff,0x15,0x0c,0xa1,0x02,0x10,0x84,0xc0,0x74};
	const uintptr_t relocated=uintptr_t(module+0x2a10c);
	memcpy(wanted+9,&relocated,4);
	uint8_t actual[sizeof(wanted)]{};uintptr_t target=0;
	if(!skmem::Copy(&target,reinterpret_cast<void*>(table+29*4),4) || target!=uintptr_t(module+0xf3a0)
		|| !skmem::Copy(actual,module+0xf3a0,sizeof(actual)) || memcmp(actual,wanted,sizeof(actual)))return;
	HMODULE engine=GetModuleHandleA("engine.dll"),client=GetModuleHandleA("client.dll");MODULEINFO engineInfo{},clientInfo{};
	if(!engine || !client || !GetModuleInformation(GetCurrentProcess(),engine,&engineInfo,sizeof(engineInfo))
		|| !GetModuleInformation(GetCurrentProcess(),client,&clientInfo,sizeof(clientInfo))
		|| !skload::g_staticPropGroups.Bind(static_cast<uint8_t*>(engineInfo.lpBaseOfDll),engineInfo.SizeOfImage,
			static_cast<uint8_t*>(clientInfo.lpBaseOfDll),clientInfo.SizeOfImage))return;
	auto& native=skload::g_nativePreload;
	native.object=object;native.read=FastLoadAsyncRead;native.write=FastLoadAsyncWrite;
	native.finish=reinterpret_cast<decltype(native.finish)>(module+0xf3a0);
}
static void FastLoadBeginLocalReady(bool background) {
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (GetCurrentThreadId()!=skload::g_ownerThread.load(std::memory_order_relaxed)) {
		if (!background && (skload::g_mode.load(std::memory_order_relaxed)&64u))
			skload::g_localReadyForeignThread.fetch_add(1,std::memory_order_relaxed);
		return;
	}
	if (skload::g_localReadyEndPending.exchange(false,std::memory_order_acq_rel)) skload::EndLocalReadyDelay();
	if (background || !(skload::g_mode.load(std::memory_order_relaxed)&64u)) return;
	MODULEINFO info{};
	HMODULE module=GetModuleHandleA("server.dll");
	if (!module || !GetModuleInformation(GetCurrentProcess(),module,&info,sizeof(info))) {
		++skload::g_localReadyDelay.failures;skload::g_localReadyDelay.status=skload::Status::Unsupported;return;
	}
	skload::g_localReadyDelay.Begin(static_cast<uint8_t*>(info.lpBaseOfDll),info.SizeOfImage);
}
static void FastLoadGamePump() {
	static bool transitionWanted = false;
	if (!g_optFastLoad
		&& !transitionWanted && !skload::g_localTransitionWait.owned
		&& !g_fastLoadLocalLevelEdge.load(std::memory_order_acquire)
		&& !g_fastLoadLocalTransitionPending.load(std::memory_order_acquire)
		&& !skload::g_installed && !skload::g_pathInstalled && !skload::g_waitSuppressed && !skload::g_finishedInstalled && !skload::g_readInstalled
		&& g_fastLoadCommand.load(std::memory_order_acquire) < 0
		&& g_fastLoadDiagCommand.load(std::memory_order_acquire) < 0
		&& !g_fastLoadReport.load(std::memory_order_acquire) && !g_fastLoadReset.load(std::memory_order_acquire)) return;
	// Native redraw synchronously invokes Paint. Leave all requests queued until
	// outside that call, before changing options or the cached configure edge.
	if(skload::g_inside)return;
	// A foreign shutdown requests one owner-thread close. Connection/host flags
	// can be false during early loading and are not shutdown evidence.
	if(skload::g_localReadyEndPending.load(std::memory_order_relaxed)
		&& skload::g_localReadyEndPending.exchange(false,std::memory_order_acq_rel)) skload::EndLocalReadyDelay();
	const int command = g_fastLoadCommand.exchange(-1, std::memory_order_acq_rel);
	const int diag = g_fastLoadDiagCommand.exchange(-1, std::memory_order_acq_rel);
	if(command>=0) {
		g_optFastLoad=(command&1)!=0;g_optFastLoadPathReuse=(command&2)!=0;
		g_optFastLoadVpkSkip=(command&4)!=0;
		g_optFastLoadAsyncMesh=g_optFastLoadAsyncCollide=(command&8)!=0;
		g_optFastLoadAsyncAnims=(command&256)!=0;
		g_optFastLoadWait=(command&16)!=0;g_optFastLoadLocalReady=(command&32)!=0;
		g_optFastLoadEarlyView=(command&64)!=0;skload::g_requestedMode=~0u;
		g_optFastLoadLocalTransition=(command&128)!=0;
		g_optFastLoadLessModelData=(command&512)!=0;g_optFastLoadLessTouch=(command&1024)!=0;g_optFastLoadLessPreload=(command&2048)!=0;
		g_optFastLoadMapPacks=(command&4096)!=0;g_optFastLoadFileFilter=(command&8192)!=0;
		g_optFastLoadLessTextureWarmup=(command&16384)!=0;
	}
	if(diag>=0)g_optFastLoadDiag=diag!=0;
	const bool wantTransition=SkeetoFeaturesOn() && g_optFastLoad && g_optFastLoadLocalTransition;
	const bool levelEdge=g_fastLoadLocalLevelEdge.exchange(false,std::memory_order_acq_rel);
	const bool transitionPending=g_fastLoadLocalTransitionPending.exchange(false,std::memory_order_acq_rel);
	if(levelEdge || transitionPending || wantTransition!=transitionWanted) {
		if(wantTransition!=transitionWanted) {
			transitionWanted=wantTransition;
			g_fastLoadLocalTransitionEnabled.store(wantTransition,std::memory_order_release);
		}
		auto& local=skload::g_localTransitionWait;
		void* module=GetModuleHandleA("server.dll");
		local.read=FastLoadAsyncRead;local.write=FastLoadAsyncWrite;
		const bool localLevel=g_fastLoadLocalLevel.load(std::memory_order_relaxed);
		if(!wantTransition || !localLevel) local.End(module);
		else {
			// A foreign shutdown can be followed by the next LevelInit before
			// Paint sees the false level edge; close the previous lease here.
			if(levelEdge && local.owned) local.End(module);
			if(transitionPending) local.Begin(module);
		}
	}
	const unsigned vpkWant=SkeetoFeaturesOn()&&g_optFastLoad?((g_optFastLoadMapPacks?1u:0u)|(g_optFastLoadFileFilter?2u:0u)):0u;
	skvpkexp::g_controller.Configure(vpkWant);skvpkexp::g_controller.mission=FastLoadVpkMission;
	const unsigned asyncWant=(g_optFastLoadAsyncMesh?1u:0u)|(g_optFastLoadAsyncCollide?2u:0u)|(g_optFastLoadAsyncAnims?4u:0u);
	skload::g_nativeAsyncWant.store(asyncWant,std::memory_order_relaxed);
	const unsigned mode=SkeetoFeaturesOn()?skload::ConfiguredMode(g_optFastLoad,g_optFastLoadPathReuse,
		g_optFastLoadVpkSkip||vpkWant!=0,asyncWant!=0,g_optFastLoadWait,g_optFastLoadLocalReady,g_optFastLoadEarlyView,g_optFastLoadDiag,
		(g_optFastLoadLessModelData?1u:0u)|(g_optFastLoadLessTouch?2u:0u)|(g_optFastLoadLessPreload?4u:0u)|(g_optFastLoadLessTextureWarmup?8u:0u),vpkWant):0u;
	if(mode&32u)FastLoadBindNativeAsync();
	skload::g_loadingEdge=FastLoadAsyncEdge;
	skload::Configure(mode, g_engineVgui);
	if (g_fastLoadReset.exchange(false, std::memory_order_acq_rel)) skload::ClearStats();
	if (mode) skload::Observe(g_paintLoading.load(std::memory_order_relaxed),
		g_paintInGame.load(std::memory_order_relaxed), GetTickCount());
	if (!g_fastLoadReport.exchange(false, std::memory_order_acq_rel)) return;
	const auto& s = skload::g_stats;
	char text[384]{};
	const auto& x=skvpkexp::g_controller;const auto& xs=x.stats;
	snprintf(text,sizeof(text),"[Skeeto VPK Experiments] wanted=%u active=%u map=%s builds=%llu names=%llu map_skipped=%llu file_queries=%llu file_rejected=%llu mission_reads=%llu unknown=%llu failures=%llu",
		x.requested,x.enabled,x.map,(unsigned long long)xs.builds,(unsigned long long)xs.names,(unsigned long long)xs.mapSkipped,
		(unsigned long long)xs.fileQueries,(unsigned long long)xs.fileRejected,(unsigned long long)xs.missionReads,(unsigned long long)xs.unknown,(unsigned long long)xs.failures);ConEcho(text);
	snprintf(text,sizeof(text),"[Skeeto VPK File] native_checks=%llu memo_hits=%llu",
		(unsigned long long)xs.fileChecks,(unsigned long long)xs.fileHits);ConEcho(text);
	const auto& texture=sktexturewarm::g_controller;
	snprintf(text,sizeof(text),"[Skeeto Load Texture] active=%d status=%d skipped=%llu failures=%u",texture.installed?1:0,int(texture.status),(unsigned long long)texture.skipped,texture.failures);ConEcho(text);
	const auto& e=skload::g_loadingExperiments;
	snprintf(text,sizeof(text),"[Skeeto Load Experiments] data=%d touch=%d preload=%d owned=%d writes=%u restores=%u conflicts=%u failures=%u",
		g_optFastLoadLessModelData?1:0,g_optFastLoadLessTouch?1:0,g_optFastLoadLessPreload?1:0,e.active?1:0,e.writes,e.restores,e.conflicts,e.failures);ConEcho(text);
	snprintf(text,sizeof(text),"[Skeeto Load Options] master=%d paths=%d vpk=%d mesh=%d collide=%d anim=%d background=%d local_start=%d early_view=%d local_transition=%d diagnostics=%d",
		g_optFastLoad?1:0,g_optFastLoadPathReuse?1:0,g_optFastLoadVpkSkip?1:0,
		g_optFastLoadAsyncMesh?1:0,g_optFastLoadAsyncCollide?1:0,g_optFastLoadAsyncAnims?1:0,
		g_optFastLoadWait?1:0,g_optFastLoadLocalReady?1:0,g_optFastLoadEarlyView?1:0,g_optFastLoadLocalTransition?1:0,g_optFastLoadDiag?1:0);
	ConEcho(text);
	const auto& transition=skload::g_localTransitionWait;
	snprintf(text,sizeof(text),"[Skeeto Load Transition] active=%d status=%d writes=%u restores=%u failures=%u conflicts=%u local_level=%d",
		transition.owned?1:0,int(transition.status),transition.writes,transition.restores,transition.failures,transition.conflicts,
		g_fastLoadLocalLevel.load(std::memory_order_relaxed)?1:0);
	ConEcho(text);
	snprintf(text, sizeof(text), "[Skeeto Load] requested=%u active=%u status=%d calls=%llu drawn=%llu redraw_ms=%.3f",
		mode, skload::g_mode.load(std::memory_order_relaxed), int(skload::g_status),
		(unsigned long long)s.calls, (unsigned long long)s.drawn, skload::DrawMilliseconds());
	ConEcho(text);
	snprintf(text, sizeof(text), "[Skeeto Load] progress_to_ingame_paint_ms=%u complete=%d reentries=%u (proxy interval; not full local load or server wait)",
		s.progressToPaintMs, s.completed ? 1 : 0, s.reentries);
	ConEcho(text);
	snprintf(text, sizeof(text), "[Skeeto Load Paths] calls=%llu repeated=%llu hits=%llu bypass=%llu native_calls=%llu samples=%llu sampled_native_ms=%.3f path_status=%d path_active=%d wait_status=%d wait_active=%d wait_edges=%u finish_status=%d finish_calls=%u finish_thread=%lu owner_thread=%lu",
		(unsigned long long)s.pathCalls, (unsigned long long)s.pathCandidates, (unsigned long long)s.pathHits,
		(unsigned long long)s.pathBypasses, (unsigned long long)s.pathNativeCalls, (unsigned long long)s.pathSamples,
		skload::PathMilliseconds(), int(skload::g_pathStatus),
		skload::g_pathInstalled ? 1 : 0, int(skload::g_waitStatus), skload::g_waitSuppressed ? 1 : 0, s.waitEdges,
		int(skload::g_finishedStatus), s.finishedCalls, skload::g_finishedThread.load(std::memory_order_relaxed), skload::g_ownerThread.load(std::memory_order_relaxed));
	ConEcho(text);
	snprintf(text, sizeof(text), "[Skeeto Load IO] vpk_reads=%llu bytes=%llu small_le_4k=%llu failures=%llu samples=%llu sampled_read_ms=%.3f read_status=%d read_active=%d (main-thread API reads; includes OS cache)",
		(unsigned long long)s.readCalls, (unsigned long long)s.readBytes, (unsigned long long)s.readSmall,
		(unsigned long long)s.readFailures, (unsigned long long)s.readSamples, skload::ReadMilliseconds(),
		int(skload::g_readStatus), skload::g_readInstalled ? 1 : 0);
	ConEcho(text);
	snprintf(text, sizeof(text), "[Skeeto Load Index] active=%d status=%d queries=%llu rejected=%llu builds=%llu nodes=%llu build_ms=%.3f bypass=%llu verified=%llu mismatches=%llu mutations=%u mutation_thread=%lu",
		skload::g_pathInstalled && skload::g_pathUsesCandidate ? 1 : 0,int(skload::g_candidateStatus),
		(unsigned long long)s.indexQueries,(unsigned long long)s.indexRejected,(unsigned long long)s.indexBuilds,
		(unsigned long long)s.indexNodes,skload::g_frequency.QuadPart ? 1000.0 * double(s.indexTicks) / double(skload::g_frequency.QuadPart) : 0.0,
		(unsigned long long)s.indexBypasses,(unsigned long long)s.indexVerified,(unsigned long long)s.indexMismatches,
		skload::g_candidateMutations.load(),skload::g_candidateMutationThread.load());
	ConEcho(text);
	snprintf(text, sizeof(text), "[Skeeto Load Loops] lists=%llu rejected_calls=%llu avoided_calls=%llu",
		(unsigned long long)s.candidateLists,(unsigned long long)s.loopRejected,(unsigned long long)s.loopSkipped);
	ConEcho(text);
	snprintf(text,sizeof(text),"[Skeeto Load Async] bound=%d active=%d begins=%llu writes=%llu restores=%llu failures=%llu conflicts=%llu finish_ms=%.3f group_failures=%u",
		skload::g_nativePreload.object?1:0,skload::g_nativePreload.active?1:0,
		(unsigned long long)s.asyncBegins,(unsigned long long)s.asyncWrites,(unsigned long long)s.asyncRestores,
		(unsigned long long)s.asyncFailures,(unsigned long long)s.asyncConflicts,
		skload::g_frequency.QuadPart ? 1000.0*double(s.asyncFinishTicks)/double(skload::g_frequency.QuadPart):0.0,
		skload::g_staticPropGroups.failures);
	ConEcho(text);
	const auto& local=skload::g_localReadyDelay;
	snprintf(text,sizeof(text),"[Skeeto Load Local] active=%d status=%d begins=%u restores=%u failures=%u conflicts=%u begin_thread=%lu end_thread=%lu foreign_thread=%u",
		local.owned?1:0,int(local.status),local.begins,local.restores,local.failures,local.conflicts,
		local.beginThread,local.endThread,skload::g_localReadyForeignThread.load(std::memory_order_relaxed));
	ConEcho(text);
	const auto& view=skload::g_earlyGameView;
	snprintf(text,sizeof(text),"[Skeeto Load View] active=%d status=%d writes=%u restores=%u failures=%u conflicts=%u",
		view.owned?1:0,int(view.status),view.writes,view.restores,view.failures,view.conflicts);
	ConEcho(text);
}
static bool SkCmdParseBoundedAt(const int* cmd, int index, int lo, int hi, int* out);
static void SkCmd_FastLoad(int* cmd) {
	int mask=0;
	if(CmdArgC(cmd)!=2 || !SkCmdParseBoundedAt(cmd,1,0,32767,&mask)) {
		ConEcho("usage: skeeto_fast_load mask (1=master, 2=paths, 4=VPK, 8=mesh and collision async, 16=background, 32=local start wait, 64=early game view, 128=local transition wait, 256=animation async, 512=reduce forced model caching, 1024=reduce model warm-up, 2048=reduce forced preloading, 4096=skip other map packs, 8192=file filter, 16384=reduce forced texture warm-up; combine; session only)");return;
	}
	g_fastLoadCommand.store(mask, std::memory_order_release);
	// Main-menu/minimized Paint can stop. Apply on the established Paint thread
	// when the engine invokes the command there; other callers only queue it.
	if (GetCurrentThreadId() == skload::g_ownerThread && !skload::g_inside) FastLoadGamePump();
}
static void SkCmd_LoadProbe(int* cmd) {
	const char* arg = CmdArgC(cmd) == 2 ? CmdArg(cmd, 1) : "status";
	if (CmdArgC(cmd) > 2) { ConEcho("usage: skeeto_load_probe [0|1|reset|status]"); return; }
	if (!strcmp(arg, "0") || !strcmp(arg, "1")) g_fastLoadDiagCommand.store(arg[0] == '1' ? 1 : 0, std::memory_order_release);
	else if (!strcmp(arg, "reset")) g_fastLoadReset.store(true, std::memory_order_release);
	else if (!strcmp(arg, "status")) g_fastLoadReport.store(true, std::memory_order_release);
	else ConEcho("usage: skeeto_load_probe [0|1|reset|status]");
	if (GetCurrentThreadId() == skload::g_ownerThread && !skload::g_inside) FastLoadGamePump();
}

static void SkCmd_BackgroundPause(int* cmd) {
	int value=2;
	if(CmdArgC(cmd)>2||(CmdArgC(cmd)>1&&!SkCmdParseBoundedAt(cmd,1,0,1,&value))){ConEcho("[Skeeto] Usage: skeeto_background_pause [0|1] (no argument: toggle)");return;}
	g_backgroundPauseRequest.store(value,std::memory_order_release);
}

static void SkCmd_BackgroundToggle(int*) {
	g_optBackgroundEngine = !g_optBackgroundEngine;
	BackgroundApplyConfig();
	if (g_optBackgroundEngine
		&& g_backgroundCoreInitialized.load(std::memory_order_acquire)
		&& !g_backgroundShutdownPending.load(std::memory_order_acquire)
		&& SkeetoBackgroundCount() <= 0)
		SkeetoBackgroundScan();
	SaveSettings();
	ConEcho(g_optBackgroundEngine
		? "[Skeeto] Background Engine: ON"
		: "[Skeeto] Background Engine: OFF");
}

static void SkCmd_BackgroundReload(int*) {
	if (!g_optBackgroundEngine
		|| !g_backgroundCoreInitialized.load(std::memory_order_acquire)
		|| g_backgroundShutdownPending.load(std::memory_order_acquire)) {
		ConEcho("[Skeeto] Background Engine is OFF. Enable it before scanning.");
		return;
	}
	const bool ok = SkeetoBackgroundReload();
	const char* current = SkeetoBackgroundCurrentId();
	strncpy(g_backgroundId, current ? current : "", sizeof(g_backgroundId) - 1);
	g_backgroundId[sizeof(g_backgroundId) - 1] = 0;
	SaveSettings();
	char out[128]{};
	snprintf(out, sizeof(out), "[Skeeto] Background scan: %d asset(s)%s",
		SkeetoBackgroundCount(), ok ? "" : " (none)");
	ConEcho(out);
}

static void SkCmd_BackgroundNext(int*) {
	if (!g_optBackgroundEngine
		|| !g_backgroundCoreInitialized.load(std::memory_order_acquire)
		|| g_backgroundShutdownPending.load(std::memory_order_acquire)) {
		ConEcho("[Skeeto] Background Engine is OFF. Enable it before selecting assets.");
		return;
	}
	if (!SkeetoBackgroundNext()) {
		ConEcho("[Skeeto] No background assets found. Use skeeto_background_reload after installing one.");
		return;
	}
	const char* current = SkeetoBackgroundCurrentId();
	strncpy(g_backgroundId, current ? current : "", sizeof(g_backgroundId) - 1);
	g_backgroundId[sizeof(g_backgroundId) - 1] = 0;
	SaveSettings();
	char out[192]{};
	snprintf(out, sizeof(out), "[Skeeto] Background: %s", SkeetoBackgroundCurrentName());
	ConEcho(out);
}

static bool SkCmdParseBoundedAt(const int* cmd, int index, int lo, int hi, int* out) {
	if (!out || CmdArgC(cmd) <= index) return false;
	const char* s = CmdArg(cmd, index);
	if (!s || !s[0]) return false;
	char* end = nullptr;
	const long v = strtol(s, &end, 10);
	if (!end || *end != 0 || v < lo || v > hi) return false;
	*out = (int)v;
	return true;
}

