static void SkCmd_RenderProbe(int* cmd) {
	if (CmdArgC(cmd) >= 2 && !_stricmp(CmdArg(cmd, 1), "off")) {
		g_renderProbeUntil.store(0, std::memory_order_relaxed);
		ConEcho("[Skeeto] Render probe: OFF");
		return;
	}
	LARGE_INTEGER freq{};
	if (!QueryPerformanceFrequency(&freq) || freq.QuadPart <= 0) {
		g_renderProbeUntil.store(0, std::memory_order_relaxed);
		ConEcho("[Skeeto] Render probe unavailable: QPC frequency query failed");
		return;
	}
	g_renderProbeQpcFreq = freq.QuadPart;
	g_renderProbeFrames = 0;
	g_renderProbeSlowFrames = 0;
	g_renderProbeMaxTotalUs = 0;
	g_renderProbeMaxOrigUs = 0;
	g_renderProbeMaxSkeetoUs = 0;
	g_throwPredictDiag.probeMaxUs.store(0, std::memory_order_relaxed);
	g_renderProbeUntil.store(GetTickCount() + 10000u, std::memory_order_relaxed);
	ConEcho("[Skeeto] Render probe: sampling 10 seconds; run skeeto_dump_render_state afterwards");
}

static void SkCmd_DumpRenderState(int*) {
	char out[300]{};
	const DWORD now = GetTickCount();
	const DWORD until = g_renderProbeUntil.load(std::memory_order_relaxed);
	const DWORD remain = (until && (LONG)(until - now) > 0) ? (until - now) : 0;
	snprintf(out, sizeof(out),
		"[Skeeto] map ingame=%d loading=%d quiet=%d resetPending=%d cvarPending=%d paintDt=%lums",
		g_paintInGame.load(std::memory_order_relaxed) ? 1 : 0,
		g_paintLoading.load(std::memory_order_relaxed) ? 1 : 0,
		g_hudPostMissionQuiet ? 1 : 0,
		g_mapEnterGameThreadResetPending.load(std::memory_order_relaxed) ? 1 : 0,
		g_mapEnterCvarReapplyPending.load(std::memory_order_relaxed) ? 1 : 0,
		(unsigned long)g_paintLastDtMs.load(std::memory_order_relaxed));
	ConEcho(out);
	snprintf(out, sizeof(out),
		"[Skeeto] textures cache=%d creates=%d drawFaults=%u queryFaults=%u createFaults=%u invalid=%u xhairInvalid=%u",
		g_hudMatN, g_hudMatCreateTotal, g_surfTextureDrawFaults,
		g_surfTextureQueryFaults, g_surfTextureCreateFaults,
		g_hudMatInvalidations, g_texXhairInvalidations);
	ConEcho(out);
	snprintf(out, sizeof(out),
		"[Skeeto] vgui bags=%d/%d/%d/%d/%d/%d searches=%u faults=%u visibleWrites=%u staleDrops=%u overlayOwned=%d",
		g_hvTeam.n, g_hvWep.n, g_hvPickup.n, g_hvScript.n, g_hvProgress.n, g_hvTips.n,
		g_hvChapterSearches, g_hvChapterFaults, g_hvChapterVisibleCalls,
		g_hvIdentityDropsTotal, g_overlayClearAt ? 1 : 0);
	ConEcho(out);
	snprintf(out, sizeof(out),
		"[Skeeto] probe frames=%u slow25ms=%u maxTotal=%.3fms maxOrig=%.3fms maxSkeeto=%.3fms remaining=%lums",
		g_renderProbeFrames, g_renderProbeSlowFrames,
		(double)g_renderProbeMaxTotalUs / 1000.0,
		(double)g_renderProbeMaxOrigUs / 1000.0,
		(double)g_renderProbeMaxSkeetoUs / 1000.0,
		(unsigned long)remain);
	ConEcho(out);
	snprintf(out, sizeof(out),
		"[Skeeto] throw preview simulations=%u tracesLast=%u tracesMax=%u candidatesLast=%u limited=%u probeMax=%.3fms onAttack=%d throwTimeOffset=%d handleLookup=%d",
		g_throwPredictDiag.simulations.load(std::memory_order_relaxed),
		g_throwPredictDiag.lastTraces.load(std::memory_order_relaxed),
		g_throwPredictDiag.maxTraces.load(std::memory_order_relaxed),
		g_throwPredictDiag.lastCandidates.load(std::memory_order_relaxed),
		g_throwPredictDiag.limited.load(std::memory_order_relaxed),
		(double)g_throwPredictDiag.probeMaxUs.load(std::memory_order_relaxed) / 1000.0,
		g_throwLandOnAttack ? 1 : 0, g_offThrowTime, g_handleLookupState);
	ConEcho(out);
	snprintf(out, sizeof(out), "[Skeeto] client threads: waitFaults=%u overlayShutdownWait=%lu inputAlive=%d",
		g_clientUiWaitFaults.load(), g_xhairUiShutdownWait.load(), g_holdSemiHookAlive.load() ? 1 : 0);
	ConEcho(out);
}

static void SkCmd_BotNamesToggle(int* cmd) {
	if (CmdArgC(cmd) >= 2) {
		const char* value = CmdArg(cmd, 1);
		if (!strcmp(value, "1") || !_stricmp(value, "on"))
			g_optClientBotNames = true;
		else if (!strcmp(value, "0") || !_stricmp(value, "off"))
			g_optClientBotNames = false;
		else {
			ConEcho("usage: skeeto_bot_names 1|0");
			return;
		}
		SaveSettings();
		MenuMarkDirty();
	}
	ConEcho(g_optClientBotNames
		? "[Skeeto] Custom BOT names: ON"
		: "[Skeeto] Custom BOT names: OFF");
}

static void SkCmd_BotName(int* cmd, int role, const char* commandName) {
	if (role < 0 || role >= kBotNameCount || !commandName) return;
	if (CmdArgC(cmd) != 2) {
		char usage[192]{};
		snprintf(usage, sizeof(usage), "usage: %s \"name\"  |  %s reset",
			commandName, commandName);
		ConEcho(usage);
		return;
	}
	const char* value = CmdArg(cmd, 1);
	if (!_stricmp(value, "reset")) {
		BotNameResetValue(role);
		SaveSettings();
		MenuMarkDirty();
		ConEcho("[Skeeto] BOT name reset; game/mod localization will be used.");
		Log("bot names: console reset role=%s", kBotNameDefs[role].setting);
		return;
	}
	if (!BotNameAssignUtf8Value(role, value)) {
		ConEcho("[Skeeto] Invalid BOT name: use valid UTF-8 text, 1-23 characters, no line breaks.");
		return;
	}
	SaveSettings();
	MenuMarkDirty();
	ConEcho(g_optClientBotNames
		? "[Skeeto] BOT name saved and active."
		: "[Skeeto] BOT name saved; enable with skeeto_bot_names 1.");
	Log("bot names: console applied role=%s enabled=%d", kBotNameDefs[role].setting,
		g_optClientBotNames ? 1 : 0);
}

