static bool SkCmdToggleOrSet(int* cmd, bool current, bool* value) {
	if (!value) return false;
	if (CmdArgC(cmd) < 2) {
		*value = !current;
		return true;
	}
	const char* arg = CmdArg(cmd, 1);
	if (!strcmp(arg, "1") || !_stricmp(arg, "on")) {
		*value = true;
		return true;
	}
	if (!strcmp(arg, "0") || !_stricmp(arg, "off")) {
		*value = false;
		return true;
	}
	return false;
}

