static bool SkCmdParseNavigationGoal(const char* token, int* value) {
	if (!token || !token[0] || !value) return false;
	if (!_stricmp(token, "auto") || !strcmp(token, "0")) {
		*value = 0;
		return true;
	}
	int parsed = 0;
	for (const char* p = token; *p; ++p) {
		if (*p < '0' || *p > '9') return false;
		parsed = parsed * 10 + (*p - '0');
		if (parsed > 16) return false;
	}
	if (parsed < 1) return false;
	*value = parsed;
	return true;
}

static void SkCmd_NavigationGoal(int* cmd) {
	const unsigned count = skeeto_nav::GoalCount();
	const int argc = CmdArgC(cmd);
	int value = 0;
	if (argc == 1) {
		if (!count) {
			ConEcho("[Skeeto] No safehouse candidates are loaded");
			return;
		}
		const int current = skeeto_nav::Get(9);
		value = current >= (int)count ? 0 : current + 1;
	} else if (argc != 2 || !SkCmdParseNavigationGoal(CmdArg(cmd, 1), &value)) {
		ConEcho("usage: skeeto_nav_goal [auto|1..N] (no argument cycles candidates)");
		return;
	}
	if (value > 0 && (unsigned)value > count) {
		ConEcho("[Skeeto] Candidate is not available on this map");
		return;
	}
	skeeto_nav::Set(9, value);
	g_settingsDirty = true;
	g_settingsSaveAt = GetTickCount() + 400u;
	MenuMarkDirty();
	if (value == 0)
		ConEcho("[Skeeto] Safehouse selection: Auto");
	else {
		char status[96]{};
		snprintf(status, sizeof(status), "[Skeeto] Safehouse candidate: %d/%u", value, count);
		ConEcho(status);
	}
}

