static bool LocalBugTeleport() {
	if (!ListenDetectHost() || !g_optLocalBug) return false;
	float x = 0.f, y = 0.f, z = 0.f;
	if (!skeeto_nav::BugNearestPoint(&x, &y, &z)) return false;
	auto dot = [](char* out, int cap, float v) {
		if (cap < 2) return;
		const bool neg = v < 0.f;
		if (neg) v = -v;
		int whole = (int)v;
		int frac = (int)((v - (float)whole) * 100.f + 0.5f);
		if (frac >= 100) { frac -= 100; ++whole; }
		snprintf(out, (size_t)cap, "%s%d.%02d", neg ? "-" : "", whole, frac);
	};
	char xs[24]{}, ys[24]{}, zs[24]{}, cmd[384]{};
	dot(xs, (int)sizeof xs, x);
	dot(ys, (int)sizeof ys, y);
	dot(zs, (int)sizeof zs, z);
	int cheatN = 0;
	float cheatF = 0.f;
	void* cheat = CvarFind("sv_cheats");
	const bool cheatsOn = cheat && CvarReadPair(cheat, &cheatN, &cheatF) && cheatF >= 0.5f;
	if (cheatsOn)
		snprintf(cmd, sizeof cmd,
			"setpos %s %s %s; script GetListenServerHost().SetVelocity(Vector(0,0,0))",
			xs, ys, zs);
	else
		snprintf(cmd, sizeof cmd,
			"sv_cheats 1; setpos %s %s %s; script GetListenServerHost().SetVelocity(Vector(0,0,0)); sv_cheats 0",
			xs, ys, zs);
	EngClientCmdUnrestricted(cmd);
	return true;
}

static void SkCmd_BugTeleport(int*) {
	if (!ListenDetectHost()) {
		ConEcho("[Skeeto] skeeto_bug_teleport only works on your own listen server.");
		return;
	}
	if (!g_optLocalBug) {
		ConEcho("[Skeeto] Turn on invincible bug spots first.");
		return;
	}
	if (!LocalBugTeleport())
		ConEcho("[Skeeto] No invincible bug spot yet.");
}

static void SkCmd_AcidOutlineToggle(int* cmd) {
	if (CmdArgC(cmd) > 2) {
		ConEcho("usage: skeeto_acid_outline_toggle [0|1]");
		return;
	}
	bool value = false;
	if (!SkCmdToggleOrSet(cmd, g_optClientAcidOutline, &value)) {
		ConEcho("usage: skeeto_acid_outline_toggle [0|1]");
		return;
	}
	if (value != g_optClientAcidOutline) {
		g_optClientAcidOutline = value;
		ClientUxAcidOutlineClear();
		g_settingsDirty = true;
		g_settingsSaveAt = GetTickCount() + 400u;
		MenuMarkDirty();
	}
	ConEcho(value
		? "[Skeeto] Acid outline estimate: ON"
		: "[Skeeto] Acid outline estimate: OFF");
}

