static void LocalPlaySetCharChangeEnabled(bool enabled, const char* why) {
	g_optLocalCharChange = enabled;
	if (enabled) {
		if (EngInGame() && ListenDetectHost())
			LocalPlayPrecacheAllSurvivors(why ? why : "char-enable");
		return;
	}
	static const char* kPrecache[] = { "precache_all_survivors", nullptr };
	ListenRestoreNamed(kPrecache);
	ListenCvarSnap* precache = ListenSnapFind("precache_all_survivors");
	if (precache) precache->saved = false;
	g_charCommandPending.store(-1, std::memory_order_release);
	g_charWantProp = -1;
	g_charWantModel[0] = 0;
	g_charWantName[0] = 0;
	g_charReapplyAt = 0;
	g_charReapplyAt2 = 0;
}

