		case TeamHealthMenuAction::CycleShow:
			g_teamHudShow = CycleWrap(g_teamHudShow, kTeamHudShowAll, kTeamHudShowSelf);
			if (g_teamHudShow == kTeamHudShowSelf)
				g_teamHudSel = kTeamHudSelSelf;
