			g_csPageManual = -1;
			break;
		case ChapStatsMenuAction::CycleLayout:
			g_chapStatsLayout = (g_chapStatsLayout + 1) % 5;
			ChapStatsInvalidateNameFit();
			break;
		case ChapStatsMenuAction::OpenScoreHud:
			g_menuPage = kMenuPageChapStatsScoreHud;
