	int ci, si;
	int sk;            // survivors killed (infected rows)
	int wep, side, nade, kit, pills;
	int clip;          // primary magazine (-1 unknown)
	float revive;      // <0 none
	bool local, bot, dead, incap, hanging, third, ghost;
	char melee[24];
