// ---- kill counters (event ingest; only while the board option is on) --------
struct TabKillRec { int userid; int ci; int si; int sk; };
static TabKillRec g_tbKills[64];
static int g_tbKillN = 0;

static void TabBoardKillsClear() { g_tbKillN = 0; }

// kind: 0 common, 1 special, 2 survivor (killed by an infected player)
static void TabBoardCountKindKill(int uid, int kind) {
	if (!g_optTabBoard || uid <= 0) return;
	int n = g_tbKillN;
	if (n < 0 || n > 64) n = 0;
	int i = 0;
	for (; i < n; ++i)
		if (g_tbKills[i].userid == uid) break;
	if (i == n) {
		if (n >= 64) return;
		g_tbKills[n] = TabKillRec{ uid, 0, 0, 0 };
		g_tbKillN = n + 1;
	}
	if (kind == 1) ++g_tbKills[i].si;
	else if (kind == 2) ++g_tbKills[i].sk;
	else ++g_tbKills[i].ci;
}

static void TabBoardCountKill(int uid, bool si) { TabBoardCountKindKill(uid, si ? 1 : 0); }

static void TabBoardUncountCiKill(int uid) {
	if (uid <= 0) return;
	int n = g_tbKillN;
	if (n < 0 || n > 64) n = 0;
	for (int i = 0; i < n; ++i) {
		if (g_tbKills[i].userid != uid) continue;
		if (g_tbKills[i].ci > 0) --g_tbKills[i].ci;
		return;
	}
}

static void TabBoardKillsFor(int uid, int* ci, int* si, int* sk) {
	*ci = 0;
	*si = 0;
	*sk = 0;
	int n = g_tbKillN;
	if (n < 0 || n > 64) n = 0;
	for (int i = 0; i < n; ++i) {
		if (g_tbKills[i].userid == uid) {
			*ci = g_tbKills[i].ci;
			*si = g_tbKills[i].si;
			*sk = g_tbKills[i].sk;
			return;
		}
	}
}

static void TabBoardOnPlayerDeath(void* ev) {
	if (!g_optTabBoard || !ev) return;
	const int atk = EvInt(ev, "attacker", 0);
	const int vic = EvInt(ev, "userid", 0);
	if (atk <= 0 || atk == vic) return;
	const int kind = KillFeedVicKind(EvStr(ev, "victimname"));
	if (kind >= kKfVicHunter && kind <= kKfVicTank) { // SI incl. Tank; no witch/commons
		if (!CkptZombieKillsReady())
			TabBoardCountKindKill(atk, 1);
		return;
	}
	// Survivor player killed: credit an infected attacker (versus board column).
	const int ve = vic > 0 ? EngPlayerForUserID(vic) : 0;
	const int ae = EngPlayerForUserID(atk);
	void* vp = ve > 0 ? EntGet(ve) : nullptr;
	void* ap = ae > 0 ? EntGet(ae) : nullptr;
	if (!vp || !ap || !EntReadable(vp) || !EntReadable(ap) || g_offTeam < 0 || g_offTeam > 0x4000) return;
	const int* vt = (const int*)((const uint8_t*)vp + g_offTeam);
	const int* at = (const int*)((const uint8_t*)ap + g_offTeam);
	if (PtrCommitted(vt) && PtrCommitted(at) && *vt == 2 && *at == 3)
		TabBoardCountKindKill(atk, 2);
}

// ---- CTerrorPlayerResource (ping / alive / infected class) -------------------
struct TabPrArr { int base; int stride; };
static bool g_tbPrOffsDone = false;
static TabPrArr g_tbPrPing{ -1, 0 }, g_tbPrAlive{ -1, 0 }, g_tbPrHealth{ -1, 0 },
	g_tbPrMaxHealth{ -1, 0 }, g_tbPrZc{ -1, 0 }, g_tbPrGhost{ -1, 0 },
	g_tbPrTeam{ -1, 0 }, g_tbPrIncap{ -1, 0 }, g_tbPrConnected{ -1, 0 };
static int g_tbOffHumanSpecUid = -1;    // SurvivorBot::m_humanSpectatorUserID
static int g_tbPrIdx = 0;
static int g_tbPrScanNext = 1;
static DWORD g_tbPrRetryAt = 0;

static TabPrArr TabPrArray(RecvTable* t, const char* name) {
	TabPrArr a{ -1, 0 };
	const int off = FindOffset(t, name);
	uint8_t* prop = FindRecvProp(t, name);
	if (off < 0 || !prop) return a;
	RecvTable* child = *(RecvTable**)(prop + 0x28);
	if (!child || !child->props || child->nProps < 2) return a;
	uint8_t* p0 = (uint8_t*)child->props;
	const int o0 = *(int*)(p0 + 0x2C);
	const int o1 = *(int*)(p0 + 0x3C + 0x2C);
	const int st = o1 - o0;
	if (st != 1 && st != 2 && st != 4) return a;
	if (off + o0 < 0 || off + o0 > 0x8000) return a;
	a.base = off + o0;
	a.stride = st;
	return a;
}

static void TabPrResolveOffsets() {
	if (g_tbPrOffsDone) return;
	g_tbPrOffsDone = true;
	void* bc = GetIface("client.dll", "VClient016");
	if (!bc) return;
	using Fn = ClientClass*(__thiscall*)(void*);
	auto fn = (Fn)VGet(bc, 7);
	if (!fn || !IsExec((void*)fn)) return;
	for (auto* cc = fn(bc); cc; cc = cc->next) {
		if (!cc->name || !cc->table) continue;
		if (!strcmp(cc->name, "CTerrorPlayerResource")) {
			g_tbPrPing = TabPrArray(cc->table, "m_iPing");
			g_tbPrAlive = TabPrArray(cc->table, "m_bAlive");
			g_tbPrConnected = TabPrArray(cc->table, "m_bConnected");
			g_tbPrHealth = TabPrArray(cc->table, "m_iHealth");
			g_tbPrMaxHealth = TabPrArray(cc->table, "m_maxHealth");
			g_tbPrZc = TabPrArray(cc->table, "m_zombieClass");
			g_tbPrGhost = TabPrArray(cc->table, "m_isGhost");
			g_tbPrTeam = TabPrArray(cc->table, "m_iTeam");
			g_tbPrIncap = TabPrArray(cc->table, "m_isIncapacitated");
		} else if (!strcmp(cc->name, "SurvivorBot")) {
			const int o = FindOffset(cc->table, "m_humanSpectatorUserID");
			g_tbOffHumanSpecUid = (o > 0 && o < 0x8000) ? o : -1;
		}
	}
	Log("tabboard: idleUid off=%d", g_tbOffHumanSpecUid);
	Log("tabboard: PR ping=%d/%d alive=%d/%d hp=%d/%d maxhp=%d/%d zc=%d/%d ghost=%d/%d team=%d/%d incap=%d/%d",
		g_tbPrPing.base, g_tbPrPing.stride, g_tbPrAlive.base, g_tbPrAlive.stride,
		g_tbPrHealth.base, g_tbPrHealth.stride, g_tbPrMaxHealth.base, g_tbPrMaxHealth.stride,
		g_tbPrZc.base, g_tbPrZc.stride, g_tbPrGhost.base, g_tbPrGhost.stride,
		g_tbPrTeam.base, g_tbPrTeam.stride, g_tbPrIncap.base, g_tbPrIncap.stride);
}

static bool TabPrRead(void* pr, const TabPrArr& a, int slot, int* out) {
	if (!pr || a.base < 0 || a.stride <= 0 || slot < 0 || slot > 64) return false;
	const uint8_t* p = (const uint8_t*)pr + a.base + slot * a.stride;
	if (!PtrCommitted(p)) return false;
	if (a.stride == 1) *out = *(const uint8_t*)p;
	else if (a.stride == 2) *out = *(const int16_t*)p;
	else *out = *(const int*)p;
	return true;
}

static void* TabPrEntity();

static void SiPresenceHudResetSample() {
    g_siPresenceHudSampleAt = 0;
    g_siPresenceHaveSample = false;
    g_siPresenceTotal = g_siPresenceSmokers = 0;
}
static void SiPresenceHudSampleImpl() {
    // Boundary invalidation precedes the 500ms throttle and any resource reads.
    // Round-end PlayerResource can still report last-round live infected.
    if (g_hudPostMissionQuiet || !g_engine || !g_entlist || !EngInGame() || EngDrawingLoading()) {
        SiPresenceHudResetSample(); return;
    }
	const DWORD now = GetTickCount();
	if (g_siPresenceHudSampleAt && now - g_siPresenceHudSampleAt < 500u) return;
	g_siPresenceHudSampleAt = now;
	g_siPresenceHaveSample = false;
	TabPrResolveOffsets();
	void* pr = TabPrEntity();
	int total = 0, smokers = 0;
	if (pr && g_tbPrTeam.base >= 0 && g_tbPrAlive.base >= 0
		&& g_tbPrZc.base >= 0 && g_tbPrGhost.base >= 0 && g_tbPrConnected.base >= 0) {
		for (int i = 1; i <= 32; ++i) {
			int team = 0, alive = 0, zc = 0, ghost = 0, connected = 0;
			// Resource entries retain alive/class after a bot disconnects on restart.
			if (!TabPrRead(pr, g_tbPrConnected, i, &connected) || !connected) continue;
			if (!TabPrRead(pr, g_tbPrTeam, i, &team)) continue;
			if (!TabPrRead(pr, g_tbPrAlive, i, &alive)) continue;
			if (!TabPrRead(pr, g_tbPrZc, i, &zc)) continue;
			if (!TabPrRead(pr, g_tbPrGhost, i, &ghost)) continue;
			if (team != 3 || alive == 0 || ghost != 0) continue;
			if ((zc >= 1 && zc <= 6) || zc == 8) {
				++total;
				if (zc == 1) ++smokers;
			}
		}
		g_siPresenceTotal = total;
		g_siPresenceSmokers = smokers;
		g_siPresenceHaveSample = true;
		return;
	}

	// Fallback: entity slots (PVS-sensitive).
	if (g_offTeam < 0 || g_offTeam > 0x4000
		|| g_offZombieClass < 0 || g_offZombieClass > 0x4000
		|| g_offLifeState < 0 || g_offLifeState > 0x4000
		|| g_offIsGhost < 0 || g_offIsGhost > 0x4000) return;
	for (int i = 1; i <= 32; ++i) {
		void* e = EntGet(i);
		if (!EntReadable(e) || !EntNetworkable(i)) continue;
		const int* team = (const int*)((const uint8_t*)e + g_offTeam);
		const int* zc = (const int*)((const uint8_t*)e + g_offZombieClass);
		const uint8_t* life = (const uint8_t*)e + g_offLifeState;
		const uint8_t* ghost = (const uint8_t*)e + g_offIsGhost;
		if (!PtrCommitted(team) || !PtrCommitted(zc)
			|| !PtrCommitted(life) || !PtrCommitted(ghost)) continue;
		if (*team != 3 || *life != 0 || *ghost != 0) continue;
		if ((*zc >= 1 && *zc <= 6) || *zc == 8) {
			++total;
			if (*zc == 1) ++smokers;
		}
	}
	g_siPresenceTotal = total;
	g_siPresenceSmokers = smokers;
	g_siPresenceHaveSample = true;
}

static void* TabPrEntity() {
	if (g_tbPrIdx > 0) {
		const char* cn = EntNetClassName(g_tbPrIdx);
		if (cn && !strcmp(cn, "CTerrorPlayerResource")) {
			void* e = EntGet(g_tbPrIdx);
			if (e && EntReadable(e)) return e;
		}
		g_tbPrIdx = 0;
		g_tbPrScanNext = 1;
	}
	const DWORD now = GetTickCount();
	if (g_tbPrRetryAt && (LONG)(now - g_tbPrRetryAt) < 0) return nullptr;
	g_tbPrRetryAt = 0;
	// Bounded one-time search: the resource entity sits just above the player
	// slots. Never walks the 0..2047 entity table.
	for (int budget = 64; budget > 0 && g_tbPrScanNext <= 255; --budget) {
		const int i = g_tbPrScanNext++;
		const char* cn = EntNetClassName(i);
		if (cn && !strcmp(cn, "CTerrorPlayerResource")) {
			g_tbPrIdx = i;
			void* e = EntGet(i);
			return (e && EntReadable(e)) ? e : nullptr;
		}
	}
	if (g_tbPrScanNext > 255) {
		g_tbPrScanNext = 1;
		g_tbPrRetryAt = now + 3000u;
	}
	return nullptr;
}

// ---- Steam avatars (fetched in command callbacks only) -----------------------
enum { kTabAvEmpty = 0, kTabAvPending, kTabAvRgba, kTabAvReady, kTabAvNone };
struct TabAvatar {
	uint32_t acct;
	int texPlus1;      // surface texture id + 1 (0 = not created); kept for reuse
	int w, h;
	int state;
	int tries;
	int grade;         // 2 = large avatar kept; 1 = medium while large is still downloading
	int epoch;
	DWORD lastUse;
	DWORD retryAt;
};
static constexpr int kTabAvMax = 40; // >= 32 player slots + churn
static constexpr int kTabAvPx = 184; // Steam large friend avatar
static TabAvatar g_tbAv[kTabAvMax];
static unsigned char g_tbAvRgba[kTabAvMax][kTabAvPx * kTabAvPx * 4];
static int g_tbSteamUniverse = 0;

static TabAvatar* TabAvatarFind(uint32_t acct) {
	if (!acct) return nullptr;
	for (int i = 0; i < kTabAvMax; ++i)
		if (g_tbAv[i].acct == acct) return &g_tbAv[i];
	return nullptr;
}

static TabAvatar* TabAvatarAlloc(uint32_t acct, DWORD now) {
	TabAvatar* hit = TabAvatarFind(acct);
	if (hit) return hit;
	int pick = -1;
	for (int i = 0; i < kTabAvMax; ++i) {
		if (!g_tbAv[i].acct) { pick = i; break; }
		if (pick < 0 || (LONG)(g_tbAv[i].lastUse - g_tbAv[pick].lastUse) < 0) pick = i;
	}
	if (pick < 0) return nullptr;
	TabAvatar& a = g_tbAv[pick];
	const int keepTex = a.texPlus1;
	a = TabAvatar{};
	a.texPlus1 = keepTex;
	a.acct = acct;
	a.lastUse = now;
	return &a;
}

static bool TabSteamIfaces(void** friends, void** utils) {
	*friends = nullptr;
	*utils = nullptr;
	if (!g_engine || !IfaceAlive(g_engine)) return false;
	using CtxFn = void*(__thiscall*)(void*);
	auto fn = (CtxFn)VGet(g_engine, 170); // IVEngineClient013::GetSteamAPIContext (as L4N)
	if (!fn || !IsExec((void*)fn)) return false;
	uint8_t* ctx = (uint8_t*)fn(g_engine);
	if (!ctx || !PtrCommitted(ctx) || !PtrCommitted(ctx + 0xC)) return false;
	void* fr = *(void**)(ctx + 0x8);   // ISteamFriends
	void* ut = *(void**)(ctx + 0xC);   // ISteamUtils
	if (!fr || !ut || !IfaceAlive(fr) || !IfaceAlive(ut)) return false;
	*friends = fr;
	*utils = ut;
	return true;
}

// 1 = final RGBA copied, 2 = medium copied while the large avatar is still downloading,
// 0 = still downloading, -1 = no avatar / failure.
static int TabAvatarFetchOne(void* fr, void* ut, uint64_t sid, unsigned char* out, int* w, int* h) {
	using ReqFn = bool(__thiscall*)(void*, uint64_t, bool);
	using AvFn = int(__thiscall*)(void*, uint64_t);
	using SizeFn = bool(__thiscall*)(void*, int, uint32_t*, uint32_t*);
	using RgbaFn = bool(__thiscall*)(void*, int, uint8_t*, int);
	using AvCdecl = int(__cdecl*)(void*, uint64_t);
	static AvCdecl largeFn = nullptr, mediumFn = nullptr;
	static bool avatarBound = false;
	if (!avatarBound) {
		avatarBound = true;
		HMODULE api = GetModuleHandleW(L"steam_api.dll");
		if (api) {
			largeFn = (AvCdecl)GetProcAddress(api, "SteamAPI_ISteamFriends_GetLargeFriendAvatar");
			mediumFn = (AvCdecl)GetProcAddress(api, "SteamAPI_ISteamFriends_GetMediumFriendAvatar");
		}
	}
	auto req = (ReqFn)VGet(fr, 37);   // RequestUserInformation
	auto av = (AvFn)VGet(fr, 35);     // GetMediumFriendAvatar fallback
	auto sz = (SizeFn)VGet(ut, 5);    // GetImageSize
	auto rgba = (RgbaFn)VGet(ut, 6);  // GetImageRGBA
	if (!req || !sz || !rgba || !IsExec((void*)req) || !IsExec((void*)sz) || !IsExec((void*)rgba))
		return -1;
	if (!largeFn && !mediumFn && (!av || !IsExec((void*)av))) return -1;
	__try {
		// RequestUserInformation: true = persona already local, false = request sent.
		const bool already = req(fr, sid, false);
		int img = 0;
		bool largeReady = false;
		bool largeLoading = false;
		if (largeFn) {
			const int large = largeFn(fr, sid);
			if (large > 0) { img = large; largeReady = true; }
			else if (large < 0) largeLoading = true; // -1 = still downloading
		}
		if (img <= 0)
			img = mediumFn ? mediumFn(fr, sid) : (av ? av(fr, sid) : 0);
		if (img < 0) return 0; // Steam: -1 = still loading
		if (img == 0) return (already && !largeLoading) ? -1 : 0;
		uint32_t iw = 0, ih = 0;
		if (!sz(ut, img, &iw, &ih) || iw == 0 || ih == 0 || iw > (uint32_t)kTabAvPx || ih > (uint32_t)kTabAvPx) return -1;
		if (!rgba(ut, img, out, (int)(iw * ih * 4u))) return 0;
		*w = (int)iw;
		*h = (int)ih;
		return largeReady ? 1 : (largeLoading ? 2 : 1);
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		return -1;
	}
}

static int TabSteamUniverse(void* ut) {
	if (g_tbSteamUniverse >= 1 && g_tbSteamUniverse <= 4) return g_tbSteamUniverse;
	using UniFn = int(__thiscall*)(void*);
	auto fn = (UniFn)VGet(ut, 2);     // GetConnectedUniverse
	int u = 0;
	if (fn && IsExec((void*)fn)) {
		__try { u = fn(ut); } __except (EXCEPTION_EXECUTE_HANDLER) { u = 0; }
	}
	g_tbSteamUniverse = (u >= 1 && u <= 4) ? u : 1;
	return g_tbSteamUniverse;
}

static void TabAvatarFetch(int maxWork) {
	if (!(g_optTabBoard || g_optChapStats) || !g_engine || !EngInGame() || EngDrawingLoading()) return;
	void* fr = nullptr;
	void* ut = nullptr;
	bool ifaces = false;
	const DWORD now = GetTickCount();
	int work = 0;
	for (int pass = 0; pass < 2 && work < maxWork; ++pass) {
		const bool upgrades = pass == 1;
		for (int i = 1; i <= 32 && work < maxWork; ++i) {
		PlayerInfo pi{};
		if (!EngPlayerInfo(i, &pi) || PlayerInfoIsBot(pi)) continue;
		uint32_t acct = 0;
		memcpy(&acct, pi.pad1 + 36, sizeof(acct)); // player_info_t::friendsID
		if (!acct) continue;
		TabAvatar* a = TabAvatarAlloc(acct, now);
		if (!a) continue;
		a->lastUse = now;
		const bool have = a->state == kTabAvRgba || a->state == kTabAvReady;
		if (have && a->grade >= 2) continue;
		if (!upgrades && have) continue;
		if (have && a->retryAt && (LONG)(now - a->retryAt) < 0) continue;
		if (a->state == kTabAvNone && (LONG)(now - a->retryAt) < 0) continue;
		if (!ifaces) {
			if (!TabSteamIfaces(&fr, &ut)) return;
			ifaces = true;
		}
		++work;
		const uint64_t sid = (uint64_t)acct | (1ull << 32) | (1ull << 52)
			| ((uint64_t)TabSteamUniverse(ut) << 56);
		int w = 0, h = 0;
		const int r = TabAvatarFetchOne(fr, ut, sid, g_tbAvRgba[a - g_tbAv], &w, &h);
		if (r == 1 || r == 2) {
			const bool changed = !have || a->w != w || a->h != h;
			a->w = w;
			a->h = h;
			a->grade = r == 1 ? 2 : 1;
			if (r == 2) {
				if (!have) a->tries = 0;
				if (++a->tries > 8) a->grade = 2;
				else a->retryAt = now + 3000u;
			} else {
				a->tries = 0;
				a->retryAt = 0;
			}
			if (changed) a->state = kTabAvRgba;
		} else if (r == 0) {
			if (have) {
				a->retryAt = now + 3000u;
			} else {
				a->state = kTabAvPending;
				if (++a->tries > 12) {
					a->state = kTabAvNone;
					a->tries = 0;
					a->retryAt = now + 60000u;
				}
			}
		} else if (!have) {
			a->state = kTabAvNone;
			a->retryAt = now + 120000u;
		}
	}
	}
}

static void TabAvatarUploadTick(int budget = 2) {
	if (!g_surf) return; // keep RGBA avatar data pending until the Paint Surface exists
	if (budget < 1) budget = 1;
	for (int i = 0; i < kTabAvMax && budget > 0; ++i) {
		TabAvatar& a = g_tbAv[i];
		if (a.state == kTabAvReady && a.epoch != g_sktFontEpoch) a.state = kTabAvRgba;
		if (a.state != kTabAvRgba || a.w <= 0 || a.h <= 0) continue;
		if (a.texPlus1 <= 0) {
			using CreateIdFn = int(__thiscall*)(void*, bool);
			auto createId = (CreateIdFn)VGet(g_surf, kVmtSurfCreateNewTextureID);
			if (!createId || !IsExec((void*)createId)) return;
			const int id = createId(g_surf, true);
			if (id < 0) return;
			a.texPlus1 = id + 1;
		}
		SurfSetTextureRGBA(a.texPlus1 - 1, g_tbAvRgba[i], a.w, a.h, 1);
		a.state = kTabAvReady;
		a.epoch = g_sktFontEpoch;
		--budget;
	}
}

static int TabAvatarTex(uint32_t acct) {
	const TabAvatar* a = TabAvatarFind(acct);
	return (a && a->state == kTabAvReady && a->texPlus1 > 0) ? a->texPlus1 - 1 : -1;
}

// In-game only: pull missing avatars and upload all pending RGBA before the
// settle snapshot goes quiet (loading Paint must not CreateNewTextureID).
static void ChapStatsAvatarFlush() {
	if (!g_engine || !EngInGame() || EngDrawingLoading()) return;
	TabAvatarFetch(16);
	TabAvatarUploadTick(kTabAvMax);
}

// ---- commands ----------------------------------------------------------------
// Board usable right now. Post-mission quiet still counts: the board draws
// then without material icons. GameUI on
// top (ESC menu, loading curtain) does not: the key falls back to +showscores.
static bool TabBoardActive() {
	return g_optTabBoard && !HudCustomHidden() && SkeetoFeaturesOn()
		&& g_engine && EngInGame() && !EngDrawingLoading()
		&& !g_paintGameUiVisible.load(std::memory_order_relaxed);
}

static void TabBoardSetVanilla(bool on) {
	if (on == g_tbVanillaOn) return;
	g_tbVanillaOn = on;
	EngClientCmdUnrestricted(on ? "+showscores" : "-showscores");
}

static void TabBoardApplyHeld() {
	g_tbHeld = g_tbHeldMask != 0;
	const bool skeeto = TabBoardActive() && ((g_tbSkeetoMask & g_tbHeldMask) != 0);
	g_tabBoardShow = skeeto;
	TabBoardSetVanilla(!skeeto && ((g_tbVanillaMask & g_tbHeldMask) != 0));
}

static void TabBoardDown(bool skeetoFirst, int source) {
	if (source < 1 || source > 2) return;
	const unsigned int bit = 1u << (source - 1);
	const int slot = source - 1;
	const DWORD now = GetTickCount();
	// Separate commands can both be present in a user's config; suppress repeats
	// per source so one held key cannot swallow the other source's press.
	if (g_tbHeldMask & bit) {
		if ((now - g_tbHeldAt[slot]) < 600u) {
			g_tbHeldAt[slot] = now;
			return;
		}
		g_tbHeldMask &= ~bit;
		g_tbVanillaMask &= ~bit;
		g_tbSkeetoMask &= ~bit;
	}
	if (!TabBoardActive()) {
		// Transparent fallback: behave exactly like a +showscores binding.
		g_tbLastDownAt[slot] = 0;
		g_tbHeldMask |= bit;
		g_tbVanillaMask |= bit;
		g_tbSkeetoMask &= ~bit;
		g_tbHeldAt[slot] = now;
		TabBoardApplyHeld();
		return;
	}
	const DWORD dblMs = (DWORD)(g_tabBoardDoubleMs < 150 ? 150 : (g_tabBoardDoubleMs > 600 ? 600 : g_tabBoardDoubleMs));
	const bool dbl = g_tbLastDownAt[slot] && (now - g_tbLastDownAt[slot]) <= dblMs;
	g_tbLastDownAt[slot] = dbl ? 0 : now;
	const bool skeeto = dbl ? !skeetoFirst : skeetoFirst;
	g_tbHeldMask |= bit;
	g_tbHeldAt[slot] = now;
	if (skeeto) {
		g_tbSkeetoMask |= bit;
		g_tbVanillaMask &= ~bit;
		g_tbGatherAt = 0;
	} else {
		g_tbVanillaMask |= bit;
		g_tbSkeetoMask &= ~bit;
	}
	TabBoardApplyHeld();
	TabAvatarFetch(16);
}

static void TabBoardUp(int source) {
	if (source < 1 || source > 2) return;
	const unsigned int bit = 1u << (source - 1);
	if (!(g_tbHeldMask & bit)) return;
	g_tbHeldMask &= ~bit;
	g_tbVanillaMask &= ~bit;
	g_tbSkeetoMask &= ~bit;
	TabBoardApplyHeld();
	if (TabBoardActive()) TabAvatarFetch(16);
}

static void SkCmd_TabDown(int*) { TabBoardDown(true, 1); }
static void SkCmd_TabUp(int*) { TabBoardUp(1); }
static void SkCmd_TabVanillaDown(int*) { TabBoardDown(false, 2); }
static void SkCmd_TabVanillaUp(int*) { TabBoardUp(2); }

static void TabBoardClearHeld() {
	g_tbHeldMask = 0;
	g_tbVanillaMask = 0;
	g_tbSkeetoMask = 0;
	g_tbHeldAt[0] = g_tbHeldAt[1] = 0;
	g_tbLastDownAt[0] = g_tbLastDownAt[1] = 0;
	g_tbHeld = false;
	g_tabBoardShow = false;
	TabBoardSetVanilla(false);
}

static void TabBoardOnToggle() {
	g_tabBoardShow = false;
	g_tbGatherAt = 0;
	g_tbRowN = 0;
	if (!g_optTabBoard) {
		TabBoardClearHeld();
		TabBoardKillsClear();
	}
}

// Cheap per-paint guard: drop the Skeeto board when it can no longer be shown.
static void TabBoardTick() {
	if (!g_tabBoardShow && !g_tbHeld && !g_tbVanillaOn) return;
	if (TabBoardActive()) return;
	g_tabBoardShow = false;
	g_tbRowN = 0;
	// Map change / disconnect: drop the held latch so a missed release can't stick.
	if (!g_engine || !EngInGame() || EngDrawingLoading()) {
		TabBoardClearHeld();
	}
}

// ---- sampling ----------------------------------------------------------------
static void TabBoardName(TabBoardRow& r, const PlayerInfo& pi, const wchar_t* fallback) {
	r.name[0] = 0;
	char tmp[33]{};
	memcpy(tmp, pi.name, 32);
	tmp[32] = 0;
	if (tmp[0] && MultiByteToWideChar(CP_UTF8, 0, tmp, -1, r.name, 40) <= 0)
		MultiByteToWideChar(CP_ACP, 0, tmp, -1, r.name, 40);
	r.name[39] = 0;
	if (!r.name[0] && fallback && fallback[0]) {
		wcsncpy(r.name, fallback, 39);
		r.name[39] = 0;
	}
}

// TAB rows are keyed by entity/userid, never by character. Keep duplicate
// display names readable by numbering later occurrences after the full gather.
static void TabBoardUniqueNames(TabBoardRow* rows, int n) {
	if (!rows || n <= 0) return;
	if (n > kTabRowsMax) n = kTabRowsMax;
	for (int i = 0; i < n; ++i) {
		const wchar_t* base = rows[i].name[0] ? rows[i].name : L"?";
		int occurrence = 0;
		for (int j = 0; j < i; ++j)
			if (!wcscmp(rows[j].name[0] ? rows[j].name : L"?", base)) ++occurrence;
		if (!occurrence) {
			wcsncpy(rows[i].display, base, 47);
			rows[i].display[47] = 0;
			continue;
		}
		int suffix = occurrence;
		for (;;) {
			swprintf_s(rows[i].display, 48, L"%s (%d)", base, suffix);
			bool collision = false;
			for (int j = 0; j < i; ++j)
				if (!wcscmp(rows[j].display, rows[i].display)) { collision = true; break; }
			if (!collision) {
				for (int j = i + 1; j < n; ++j)
					if (!wcscmp(rows[j].name[0] ? rows[j].name : L"?", rows[i].display)) { collision = true; break; }
			}
			if (!collision || suffix >= 99) break;
			++suffix;
		}
	}
}

static bool TabRowBefore(const TabBoardRow& a, const TabBoardRow& b) {
	if (a.local != b.local) return a.local;
	if (a.bot != b.bot) return !a.bot;
	return a.ent < b.ent;
}

static void TabRowSort(TabBoardRow* rows, int n) {
	for (int i = 1; i < n; ++i) {
		const TabBoardRow key = rows[i];
		int j = i;
		while (j > 0 && TabRowBefore(key, rows[j - 1])) {
			rows[j] = rows[j - 1];
			--j;
		}
		rows[j] = key;
	}
}

static int TabReadInt(void* e, int off, int dflt) {
	if (!e || off < 0 || off > 0x4000) return dflt;
	const int* p = (const int*)((const uint8_t*)e + off);
	return PtrCommitted(p) ? *p : dflt;
}

static int TabReadByte(void* e, int off, int dflt) {
	if (!e || off < 0 || off > 0x4000) return dflt;
	const uint8_t* p = (const uint8_t*)e + off;
	return PtrCommitted(p) ? *p : dflt;
}


static bool LastMusicShouldPlay(int mode,int total,int alive,int standing,bool selfAlive,bool selfStanding,bool failed) {
 if(total<2||alive<0||standing<0||standing>alive||alive>total)return false;
 switch(mode){case 0:return failed||alive==0;case 1:return alive==1;case 2:return standing==1;case 3:return alive==1&&selfAlive;case 4:return standing==1&&selfStanding;default:return false;}
}
