static int ChapStatsScoreTotal(const ChapStatsRec& r);
static int ChapStatsKills(const ChapStatsRec& r);

// Battle archive capture. Runs once after the successful exit roster refresh,
// copies at most kMainUiBattleMates survivor rows out of g_csLive (<= 32 rows, one bounded scan, no
// Source calls, no IO) and posts a fixed record to the services worker. Failures (mission_lost,
// disconnect) are never archived. Cost: ~8 mates * ~250 bytes per record, 10 records kept (~25 KB),
// written once per chapter by the worker thread.
static void MainUiHubCaptureLive(int result) {
 if(result!=0)return;
 if(!g_optMainUiBattleArchive || !g_optMainMenuUi || !g_optChapStats || !SkeetoFeaturesOn() || g_mainUiBattleCaptured)return;
 if(g_localUserId<=0)return;
 const ChapStatsRec* own=nullptr;for(int i=0;i<g_csLive.n && i<kCsRecMax;++i)if(g_csLive.rec[i].userid==g_localUserId&&!g_csLive.rec[i].bot){own=&g_csLive.rec[i];break;}
 if(!own)return;ChapStatsRec personal=*own;
 if(own->acct)for(int i=0;i<g_csLive.n&&i<kCsRecMax;++i){const auto& r=g_csLive.rec[i];if(&r==own||r.bot||r.acct!=own->acct)continue;for(int k=0;k<kCsStatN;++k)personal.st[k]+=r.st[k];for(int k=0;k<=kCsWitch;++k)personal.hsKill[k]+=r.hsKill[k];}
 const int localUid=own->userid;own=&personal;MainUiBattleRecord row{};row.result=0;row.seconds=g_mainUiBattleStart?(int)((GetTickCount()-g_mainUiBattleStart)/1000):0;
 row.scoreEnabled=g_optChapStatsScore?1:0;row.score=row.scoreEnabled?ChapStatsScoreTotal(*own):0;
 row.pageMask=(g_optChapStatsKills?1:0)|(g_optChapStatsSi?2:0)|(g_optChapStatsTeam?4:0)|(g_optChapStatsSpecial?8:0)|(g_optChapStatsDmg?16:0);
	static_assert(kCsStatN<=32);row.statCount=kCsStatN;
 memcpy(row.stats,own->st,sizeof(own->st));memcpy(row.headshots,own->hsKill,sizeof(own->hsKill));
	const int weights[]={g_csScore.ci,g_csScore.smoker,g_csScore.boomer,g_csScore.hunter,g_csScore.spitter,g_csScore.jockey,g_csScore.charger,g_csScore.tank,g_csScore.witch,g_csScore.hsMul,g_csScore.pinned,g_csScore.incap,g_csScore.death,g_csScore.revive,g_csScore.defib,g_csScore.heal,g_csScore.rescue,g_csScore.meleeSi,g_csScore.skeet,g_csScore.meleeSkeet,g_csScore.crownMelee,g_csScore.tongueCut,g_csScore.chargerLevel,g_csScore.ffDmgMul,-1,g_csScore.tankDmgPer100,g_csScore.witchDmgPer100};
 static_assert(_countof(weights)==kCsStatN);memcpy(row.weights,weights,sizeof(weights));
 // Squad rows: every present survivor (bots included), sorted by MVP key (score when scoring is on,
 // else CI+SI+Tank+Witch kills; ties: kills, then local player, then slot order). Top row is the MVP.
 struct Key{int idx,primary,kills,local;};Key keys[kCsRecMax];int keyN=0;
 for(int i=0;i<g_csLive.n&&i<kCsRecMax;++i){const ChapStatsRec& r=g_csLive.rec[i];if(!r.survivor||!r.present)continue;
  const int kills=ChapStatsKills(r)+r.st[kCsWitch];keys[keyN++]={i,row.scoreEnabled?ChapStatsScoreTotal(r):kills,kills,r.userid==localUid&&!r.bot};}
 for(int i=1;i<keyN;++i){const Key k=keys[i];int j=i;while(j>0){const Key& o=keys[j-1];const bool better=k.primary!=o.primary?k.primary>o.primary:k.kills!=o.kills?k.kills>o.kills:(k.local&&!o.local);if(!better)break;keys[j]=keys[j-1];--j;}keys[j]=k;}
 row.mateCount=keyN<kMainUiBattleMates?keyN:kMainUiBattleMates;
 for(int m=0;m<row.mateCount;++m){const ChapStatsRec& r=g_csLive.rec[keys[m].idx];MainUiBattleMate& out=row.mates[m];
  const wchar_t* name=r.display[0]?r.display:r.name;WideCharToMultiByte(CP_UTF8,0,name,-1,out.name,sizeof(out.name),nullptr,nullptr);out.name[sizeof(out.name)-1]=0;
  out.userid=r.userid;out.bot=r.bot?1:0;out.local=(r.userid==localUid&&!r.bot)?1:0;out.score=row.scoreEnabled?keys[m].primary:0;
  memcpy(out.stats,r.st,sizeof(r.st));memcpy(out.headshots,r.hsKill,sizeof(r.hsKill));}
 if(row.mateCount&&keys[0].primary>0)row.mates[0].mvp=1; // nothing scored: no MVP badge
 strncpy_s(row.map,g_elimLastMap,_TRUNCATE);strncpy_s(row.version,SKEETO_VERSION,_TRUNCATE);
 WideCharToMultiByte(CP_UTF8,0,own->name,-1,row.player,sizeof(row.player),nullptr,nullptr);
 wchar_t campaign[64]{},chapter[64]{};MapHudCopyDisplayNames(row.map,campaign,64,chapter,64);
 WideCharToMultiByte(CP_UTF8,0,campaign,-1,row.campaign,sizeof(row.campaign),nullptr,nullptr);
 WideCharToMultiByte(CP_UTF8,0,chapter,-1,row.chapter,sizeof(row.chapter),nullptr,nullptr);
 if(TryAcquireSRWLockShared(&g_mainUiServerLock)){strcpy_s(row.server,g_mainUiCurrentServer.address);strcpy_s(row.serverName,g_mainUiCurrentServer.name);ReleaseSRWLockShared(&g_mainUiServerLock);}
 if(MainUiServicesBattle(row))g_mainUiBattleCaptured=true;
}
static void ChapStatsScoreHudClear() {
	g_csScoreToastN = 0;
}

static bool ChapStatsScoreHudCaptureWanted(int uid) {
	return g_optChapStats && g_optChapStatsScore && g_optChapStatsScoreHud
		&& !HudCustomHidden() && uid > 0 && uid == g_localUserId;
}

static void ChapStatsScoreHudPush(int uid, int before, int after, int kind, int stat, int detail) {
	if (before == after || !ChapStatsScoreHudCaptureWanted(uid)) return;
	const DWORD now = GetTickCount();
	int w = 0;
	int count = g_csScoreToastN;
	if (count < 0) count = 0;
	if (count > kCsScoreToastMax) count = kCsScoreToastMax;
	for (int i = 0; i < count; ++i)
		if ((DWORD)(now - g_csScoreToast[i].born) < kCsScoreToastLifeMs)
			g_csScoreToast[w++] = g_csScoreToast[i];
	g_csScoreToastN = w;
	if (g_csScoreToastN >= kCsScoreToastMax) {
		memmove(&g_csScoreToast[0], &g_csScoreToast[1], sizeof(g_csScoreToast[0]) * (kCsScoreToastMax - 1));
		g_csScoreToastN = kCsScoreToastMax - 1;
	}
	g_csScoreToast[g_csScoreToastN++] = { after - before, kind, stat, detail, now };
}

static void ChapStatsSetClear(ChapStatsSet& s) {
	s.n = 0;
}


static void ChapStatsClearAll() {
	g_mainUiBattlePending = false;
	ChapStatsScoreHudClear();
	ChapStatsSetClear(g_csLive);
	ChapStatsSetClear(g_csSnap);
	g_csSnapValid = false;
	g_csSnapAt = 0;
	g_csSnapMap[0] = 0;
	g_csSnapCampaign[0] = 0;
	g_csSnapChapter[0] = 0;
	g_csWarmSnapAt = 0;
	g_csWarmLayout = g_csWarmScale = g_csWarmRows = -1;
	g_csWarmRes = g_csWarmRawPct = g_csWarmEpoch = -1;
	g_csFreezePending = false;
	g_csFrozenThisRound = false;
	g_csSettleArmed = false;
	g_csHeld = false;
	g_csRefreshAt = 0;
	g_csPageManual = -1;
	g_csPageManualAt = 0;
	memset(g_csTankDupUid, 0, sizeof(g_csTankDupUid));
	g_csTankDupNext = 0;
	ChapStatsNatRelease();
}

static bool ChapStatsRecAny(const ChapStatsRec& r) {
	for (int i = 0; i < kCsStatN; ++i)
		if (r.st[i]) return true;
	return false;
}

static void ChapStatsFillIdentity(ChapStatsRec& r, int ent, const PlayerInfo& pi) {
	uint32_t acct = 0;
	memcpy(&acct, pi.pad1 + 36, sizeof(acct)); // player_info_t::friendsID
	r.bot = PlayerInfoIsBot(pi);
	r.acct = r.bot ? 0 : acct;
	char tmp[33]{};
	memcpy(tmp, pi.name, 32);
	tmp[32] = 0;
	r.name[0] = 0;
	if (tmp[0] && MultiByteToWideChar(CP_UTF8, 0, tmp, -1, r.name, 32) <= 0)
		MultiByteToWideChar(CP_ACP, 0, tmp, -1, r.name, 32);
	r.name[31] = 0;
	wcsncpy(r.display, r.name[0] ? r.name : L"?", 47);
	r.display[47] = 0;
	r.fitPx = 0;
	void* e = EntGet(ent);
	if (e && EntReadable(e) && TabReadInt(e, g_offTeam, 0) == 2)
		r.survivor = true;
}

// Keep same-character survivors as separate rows; suffix only identical labels.
// Bounded by the 32 player slots and called on refresh/freeze, never every Paint.
static void ChapStatsUniqueNames(ChapStatsSet& s) {
	const int n = (s.n >= 0 && s.n <= kCsRecMax) ? s.n : 0;
	for (int i = 0; i < n; ++i) {
		ChapStatsRec& r = s.rec[i];
		const wchar_t* base = r.name[0] ? r.name : L"?";
		if (!r.survivor) {
			wcsncpy(r.display, base, 47);
			r.display[47] = 0;
			r.fitPx = 0;
			continue;
		}
		int occurrence = 0;
		for (int j = 0; j < i; ++j)
			if (s.rec[j].survivor
				&& !wcscmp(s.rec[j].name[0] ? s.rec[j].name : L"?", base)) ++occurrence;
		if (!occurrence) {
			wcsncpy(r.display, base, 47);
			r.display[47] = 0;
			r.fitPx = 0;
			continue;
		}
		int suffix = occurrence;
		for (;;) {
			swprintf_s(r.display, 48, L"%s (%d)", base, suffix);
			bool collision = false;
			for (int j = 0; j < i; ++j)
				if (s.rec[j].survivor && !wcscmp(s.rec[j].display, r.display)) { collision = true; break; }
			if (!collision) {
				for (int j = i + 1; j < n; ++j)
					if (s.rec[j].survivor
						&& !wcscmp(s.rec[j].name[0] ? s.rec[j].name : L"?", r.display)) { collision = true; break; }
			}
			if (!collision || suffix >= 99) break;
			++suffix;
		}
		r.fitPx = 0;
	}
}

static void ChapStatsInvalidateNameFit() {
	for (int i = 0; i < g_csLive.n && i < kCsRecMax; ++i) g_csLive.rec[i].fitPx = 0;
	for (int i = 0; i < g_csSnap.n && i < kCsRecMax; ++i) g_csSnap.rec[i].fitPx = 0;
}

// Slot for a new userid when all 32 are used: only a record with no stats that is
// no longer present may be recycled (never hands old numbers to a newcomer).
static int ChapStatsEvictSlot(ChapStatsSet& s) {
	for (int i = 0; i < s.n; ++i)
		if (!s.rec[i].present && !ChapStatsRecAny(s.rec[i])) return i;
	return -1;
}

static ChapStatsRec* ChapStatsRecFor(int uid) {
	if (uid <= 0) return nullptr;
	ChapStatsSet& s = g_csLive;
	if (s.n < 0 || s.n > kCsRecMax) s.n = 0;
	for (int i = 0; i < s.n; ++i)
		if (s.rec[i].userid == uid) return &s.rec[i];
	const int ent = EngPlayerForUserID(uid);
	if (ent <= 0 || ent > 32) return nullptr;
	PlayerInfo pi{};
	if (!EngPlayerInfo(ent, &pi) || pi.userid != uid) return nullptr;
	int slot = s.n < kCsRecMax ? s.n : ChapStatsEvictSlot(s);
	if (slot < 0) return nullptr;
	if (slot == s.n) ++s.n;
	ChapStatsRec& r = s.rec[slot];
	memset(&r, 0, sizeof(r));
	r.userid = uid;
	r.ch = -1;
	r.present = true;
	ChapStatsFillIdentity(r, ent, pi);
	ChapStatsUniqueNames(s);
	return &r;
}

static bool ChapStatsUidIsSurvivor(int uid) {
	if (uid <= 0) return false;
	const int ent = EngPlayerForUserID(uid);
	if (ent <= 0 || ent > 32) return false;
	void* e = EntGet(ent);
	return e && EntReadable(e) && TabReadInt(e, g_offTeam, 0) == 2;
}

static void ChapStatsBump(int uid, int stat, int detail = kCsDetailNone) {
	ChapStatsRec* r = ChapStatsRecFor(uid);
	if (!r || stat < 0 || stat >= kCsStatN) return;
	const bool toast = ChapStatsScoreHudCaptureWanted(uid);
	const int before = toast ? ChapStatsScoreTotal(*r) : 0;
	++r->st[stat];
	if (toast) {
		const int kind = (stat == kCsCi) ? kCsToastCommon
			: ((stat >= kCsSmoker && stat <= kCsWitch) ? kCsToastSi
				: (stat == kCsRevive ? kCsToastRevive
					: ((stat == kCsDefib || stat == kCsHeal || stat == kCsRescue) ? kCsToastSupport
						: ((stat == kCsPinned || stat == kCsIncap || stat == kCsDeath) ? kCsToastPenalty
							: kCsToastSpecial))));
		ChapStatsScoreHudPush(uid, before, ChapStatsScoreTotal(*r), kind, stat, detail);
	}
}

static void ChapStatsBumpDamage(int uid, int damage) {
	if (damage <= 0) return;
	// Caused FF stays on player_hurt_concise (Paint). m_checkpointSurvivorDamage is not
	// a reliable live substitute for the chapter FF ledger.
	ChapStatsRec* r = ChapStatsRecFor(uid);
	if (!r) return;
	const bool toast = ChapStatsScoreHudCaptureWanted(uid);
	const int before = toast ? ChapStatsScoreTotal(*r) : 0;
	if (damage > 0x7fffffff - r->st[kCsFfDamage])
		r->st[kCsFfDamage] = 0x7fffffff;
	else
		r->st[kCsFfDamage] += damage;
	if (toast)
		ChapStatsScoreHudPush(uid, before, ChapStatsScoreTotal(*r),
			kCsToastPenalty, kCsFfDamage, kCsDetailNone);
}

static void ChapStatsBumpTakenDamage(int uid, int damage) {
	if (damage <= 0) return;
	ChapStatsRec* r = ChapStatsRecFor(uid);
	if (!r) return;
	if (damage > 0x7fffffff - r->st[kCsFfDamageTaken])
		r->st[kCsFfDamageTaken] = 0x7fffffff;
	else
		r->st[kCsFfDamageTaken] += damage;
}

// AI Tank deaths may arrive as player_death(Tank) and tank_killed: credit once.
static bool ChapStatsTankDup(int tankUid) {
	if (tankUid <= 0) return false;
	const DWORD now = GetTickCount();
	for (int i = 0; i < 4; ++i)
		if (g_csTankDupUid[i] == tankUid && (LONG)(now - g_csTankDupAt[i]) < 5000) return true;
	const int k = g_csTankDupNext & 3;
	g_csTankDupUid[k] = tankUid;
	g_csTankDupAt[k] = now;
	g_csTankDupNext = k + 1;
	return false;
}

static void ChapStatsRequestFreeze() {
	// One freeze per settle. After the snapshot is cleared (next chapter live),
	// FrozenThisRound must not block the next map_transition — round_start can be
	// missed across a level change, which previously left only the first map working.
	if (g_csFrozenThisRound && (g_csSnapValid || g_csFreezePending)) return;
	g_csFrozenThisRound = true;
	g_csFreezePending = true;
}

// Paint ~2 Hz: absolute checkpoint ledger for base kills / incap / death / revive / FF caused.
// Special ops and toasts stay on the event path.
static void ChapStatsCkptPaintPump() {
	const bool wantChap = g_optChapStats;
	const bool wantTab = g_optTabBoard;
	if (!wantChap && !wantTab) return;
	if (!CkptZombieKillsReady()) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()
		|| !g_engine || !EngInGame()) return;
	static DWORD s_at = 0;
	const DWORD now = GetTickCount();
	if (s_at && now - s_at < 500u) return;
	s_at = now;

	// All survivor slots: checkpoint RecvProps are on every CTerrorPlayer the client has.
	for (int i = 1; i <= 32; ++i) {
		void* e = EntGet(i);
		if (!EntReadable(e)) continue;
		PlayerInfo pi{};
		if (!EngPlayerInfo(i, &pi) || pi.userid <= 0) continue;
		if (g_offTeam >= 0 && g_offTeam <= 0x4000) {
			const int* team = (const int*)((const uint8_t*)e + g_offTeam);
			if (!PtrCommitted(team) || *team != 2) continue;
		}
		int zk[kCkptZkN]{};
		if (!CkptReadZombieKills(e, zk)) continue;

		if (wantChap) {
			ChapStatsRec* r = ChapStatsRecFor(pi.userid);
			if (r) {
				r->st[kCsCi] = zk[0];
				r->st[kCsSmoker] = zk[1];
				r->st[kCsBoomer] = zk[2];
				r->st[kCsHunter] = zk[3];
				r->st[kCsSpitter] = zk[4];
				r->st[kCsJockey] = zk[5];
				r->st[kCsCharger] = zk[6];
				r->st[kCsWitch] = zk[7];
				r->st[kCsTank] = zk[8];
				int v = 0;
				// Headshot count: take max(event, field). Field alone is often 0 mid-chapter.
				if (CkptReadIntField(e, g_offCkptHeadshots, &v) && v > r->st[kCsHs])
					r->st[kCsHs] = v;
				if (CkptReadIntField(e, g_offCkptIncaps, &v)) r->st[kCsIncap] = v;
				if (CkptReadIntField(e, g_offCkptDeaths, &v)) r->st[kCsDeath] = v;
				if (CkptReadIntField(e, g_offCkptReviveOther, &v)) r->st[kCsRevive] = v;
				// Accuracy RecvProps resolve but stay 0 client-side for the whole chapter.
				if (CkptReadIntField(e, g_offCheckpointDamageToTank, &v)) r->st[kCsTankDmg] = v;
				if (CkptReadIntField(e, g_offCheckpointDamageToWitch, &v)) r->st[kCsWitchDmg] = v;			}
		}
		if (wantTab) {
			int ci = zk[0];
			int si = 0;
			for (int k = 1; k < kCkptZkN; ++k) si += zk[k];
			int n = g_tbKillN;
			if (n < 0 || n > 64) n = 0;
			int slot = -1;
			for (int j = 0; j < n; ++j) {
				if (g_tbKills[j].userid == pi.userid) { slot = j; break; }
			}
			if (slot < 0) {
				if (n >= 64 || (ci <= 0 && si <= 0)) continue;
				g_tbKills[n] = TabKillRec{ pi.userid, 0, 0, 0 };
				slot = n;
				g_tbKillN = n + 1;
			}
			g_tbKills[slot].ci = ci;
			g_tbKills[slot].si = si;
		}
	}
}

// Event thread = game thread. Records counters only; O(1) string dispatch.
static void ChapStatsOnEvent(const char* n, void* ev) {
	if (!g_optChapStats || !n || !ev) return;
	switch (n[0]) {
	case 'i':
		if (!strcmp(n, "infected_death")) {
			// Witch also fires infected_death; undo only needed when ledger is unavailable.
			g_csCiUndo = {};
			const int atk = EvInt(ev, "attacker", 0);
			ChapStatsRec* r = ChapStatsRecFor(atk);
			if (!r) return;
			const bool headshot = EvBool(ev, "headshot", false);
			const bool toast = ChapStatsScoreHudCaptureWanted(atk);
			const int before = toast ? ChapStatsScoreTotal(*r) : 0;
			const bool ckpt = CkptZombieKillsReady();
			if (!ckpt) ++r->st[kCsCi];
			if (headshot) {
				++r->st[kCsHs]; // keep event HS even when kill ledger is checkpoint-backed
				++r->hsKill[kCsCi]; // score breakdown still needs per-type HS
			}
			DWORD toastAt = 0;
			if (toast) {
				// Ledger owns the counter; temp +1 so score toast still has a delta.
				if (ckpt) {
					++r->st[kCsCi];
					if (headshot) ++r->st[kCsHs];
				}
				toastAt = GetTickCount();
				ChapStatsScoreHudPush(atk, before, ChapStatsScoreTotal(*r),
					headshot ? kCsToastHeadshot : kCsToastCommon, kCsCi, kCsDetailNone);
				if (ckpt) {
					--r->st[kCsCi];
					if (headshot) --r->st[kCsHs];
				}
			}
			// Witch also fires infected_death. Arm undo so witch_killed can strip the
			// CI miscount. Under checkpoint the kill total is ledger-owned (undoCi=false)
			// but event HS / toast still need cleanup.
			if (!ckpt || headshot || toast)
				g_csCiUndo = { atk, headshot, toast, toastAt, true, !ckpt };
		}
		return;
	case 'p':
		if (!strcmp(n, "player_death")) {
			const int vic = EvInt(ev, "userid", 0);
			const int atk = EvInt(ev, "attacker", 0);
			const int kind = KillFeedVicKind(EvStr(ev, "victimname"));
			int stat = -1;
			switch (kind) {
			case kKfVicSmoker: stat = kCsSmoker; break;
			case kKfVicBoomer: stat = kCsBoomer; break;
			case kKfVicHunter: stat = kCsHunter; break;
			case kKfVicSpitter: stat = kCsSpitter; break;
			case kKfVicJockey: stat = kCsJockey; break;
			case kKfVicCharger: stat = kCsCharger; break;
			case kKfVicTank: stat = kCsTank; break;
			default: break;
			}
			if (stat >= 0) {
				if (atk <= 0 || atk == vic) return;
				if (stat == kCsTank && ChapStatsTankDup(vic)) return;
				ChapStatsRec* r = ChapStatsRecFor(atk);
				if (!r) return;
				const bool headshot = EvBool(ev, "headshot", false);
				const bool toast = ChapStatsScoreHudCaptureWanted(atk);
				const int before = toast ? ChapStatsScoreTotal(*r) : 0;
				int killDetail = kCsDetailNone;
				const bool ckpt = CkptZombieKillsReady();
				if (!ckpt) ++r->st[stat];
				if (headshot) {
					++r->st[kCsHs]; // keep event HS even when kill ledger is checkpoint-backed
					if (stat >= kCsCi && stat <= kCsWitch) ++r->hsKill[stat];
				}
				if (g_optChapStatsSpecial && stat >= kCsSmoker && stat <= kCsCharger) {
					const bool melee = EventWeaponIsMelee(ev);
					if (melee) { ++r->st[kCsMeleeSi]; killDetail = kCsDetailMelee; }
					if (stat == kCsHunter || stat == kCsJockey) {
						const int ve = EngPlayerForUserID(vic);
						if (VictimWasAirborne(ve, stat == kCsJockey)) {
							++r->st[melee ? kCsMeleeSkeet : kCsSkeet];
							killDetail = melee ? kCsDetailMeleeSkeet : kCsDetailSkeet;
						}
					} else if (stat == kCsCharger && melee) {
						const int ve = EngPlayerForUserID(vic);
						if (WorldNoticeWasCharging(ve)) {
							++r->st[kCsChargerLevel];
							killDetail = kCsDetailChargerLevel;
						}
					}
				}
				if (toast) {
					if (ckpt) {
						++r->st[stat];
						if (headshot) ++r->st[kCsHs];
					}
					ChapStatsScoreHudPush(atk, before, ChapStatsScoreTotal(*r),
						headshot ? kCsToastHeadshot : kCsToastSi, stat, killDetail);
					if (ckpt) {
						--r->st[stat];
						if (headshot) --r->st[kCsHs];
					}
				}
				return;
			}
			if (kind == kKfVicPlayer && ChapStatsUidIsSurvivor(vic)
				&& !(CkptZombieKillsReady() && g_offCkptDeaths >= 0))
				ChapStatsBump(vic, kCsDeath);
		} else if (!strcmp(n, "player_incapacitated")) {
			const int uid = EvInt(ev, "userid", 0);
			if (ChapStatsUidIsSurvivor(uid)
				&& !(CkptZombieKillsReady() && g_offCkptIncaps >= 0))
				ChapStatsBump(uid, kCsIncap);
		} else if (!strcmp(n, "pounce_stopped")) {
			const int who = EvInt(ev, "userid", 0);
			if (who > 0 && who != EvInt(ev, "victim", 0)) ChapStatsBump(who, kCsRescue, kCsDetailHunter);
		}
		return;
	case 't':
		if (!strcmp(n, "tank_killed")) {
			const int atk = EvInt(ev, "attacker", 0);
			const int tank = EvInt(ev, "userid", 0);
			if (atk <= 0 || atk == tank || ChapStatsTankDup(tank)) return;
			if (!CkptZombieKillsReady())
				ChapStatsBump(atk, kCsTank);
		} else if (!strcmp(n, "tongue_pull_stopped")) {
			const int who = EvInt(ev, "userid", 0);
			const int vic = EvInt(ev, "victim", 0);
			if (who > 0 && who != vic) ChapStatsBump(who, kCsRescue, kCsDetailSmoker);
			if (g_optChapStatsSpecial && who > 0 && EvInt(ev, "release_type", 0) == 4)
				ChapStatsBump(who, kCsTongueCut);
		}
		return;
	case 'l':
		if (!strcmp(n, "lunge_pounce")) ChapStatsBump(EvInt(ev, "victim", 0), kCsPinned, kCsDetailHunter);
		return;
	case 'j':
		if (!strcmp(n, "jockey_ride")) {
			ChapStatsBump(EvInt(ev, "victim", 0), kCsPinned, kCsDetailJockey);
		} else if (!strcmp(n, "jockey_ride_end")) {
			const int who = EvInt(ev, "rescuer", 0);
			if (who > 0 && who != EvInt(ev, "victim", 0)) ChapStatsBump(who, kCsRescue, kCsDetailJockey);
		}
		return;
	case 'c':
		if (!strcmp(n, "choke_start")) {
			// Pulling still allows self-clear; count only the choking phase.
			ChapStatsBump(EvInt(ev, "victim", 0), kCsPinned, kCsDetailSmoker);
		} else if (!strcmp(n, "charger_pummel_start")) {
			// Collision/carry can end with the Charger killed before any pummel.
			ChapStatsBump(EvInt(ev, "victim", 0), kCsPinned, kCsDetailChargerPummel);
		} else if (!strcmp(n, "charger_pummel_end")) {
			const int who = EvInt(ev, "rescuer", 0);
			if (who > 0 && who != EvInt(ev, "victim", 0)) ChapStatsBump(who, kCsRescue, kCsDetailChargerPummel);
		}
		return;
	case 'w':
		if (!strcmp(n, "witch_killed")) {
			const int who = EvInt(ev, "userid", 0);
			if (g_csCiUndo.valid && g_csCiUndo.uid == who) {
				ChapStatsRec* undoRec = ChapStatsRecFor(who);
				if (undoRec) {
					if (g_csCiUndo.undoCi && undoRec->st[kCsCi] > 0) --undoRec->st[kCsCi];
					if (g_csCiUndo.hs) {
						if (undoRec->st[kCsHs] > 0) --undoRec->st[kCsHs];
						if (undoRec->hsKill[kCsCi] > 0) --undoRec->hsKill[kCsCi];
					}
					if (g_csCiUndo.toast && g_csScoreToastN > 0) {
						const ChapStatsScoreToast& last = g_csScoreToast[g_csScoreToastN - 1];
						if (last.stat == kCsCi && last.born == g_csCiUndo.toastAt)
							--g_csScoreToastN;
					}
					Log("chap-ci-undo uid=%d hs=%d toast=%d undoCi=%d", who, g_csCiUndo.hs ? 1 : 0,
						g_csCiUndo.toast ? 1 : 0, g_csCiUndo.undoCi ? 1 : 0);
				} else {
					Log("chap-ci-undo miss uid=%d", who);
				}
				g_csCiUndo = {};
			} else if (g_csCiUndo.valid) {
				Log("chap-ci-undo miss uid=%d slot=%d valid=%d", who, g_csCiUndo.uid,
					g_csCiUndo.valid ? 1 : 0);
				g_csCiUndo = {};
			}
			ChapStatsRec* r = ChapStatsRecFor(who);
			if (!r) return;
			const bool toast = ChapStatsScoreHudCaptureWanted(who);
			const int before = toast ? ChapStatsScoreTotal(*r) : 0;
			const bool ckpt = CkptZombieKillsReady();
			if (!ckpt)
				++r->st[kCsWitch];
			bool crownMelee = false;
			// witch_killed has no weapon field. EventWeaponIsMelee falls back
			// to our active weapon, which cannot identify a teammate's weapon.
			if (g_optChapStatsSpecial && who > 0
				&& EngPlayerForUserID(who) == EngLocal() && EventWeaponIsMelee(ev)) {
				++r->st[kCsCrownMelee];
				crownMelee = true;
			}
			if (toast) {
				if (ckpt) ++r->st[kCsWitch];
				ChapStatsScoreHudPush(who, before, ChapStatsScoreTotal(*r),
					crownMelee ? kCsToastSpecial : kCsToastSi, kCsWitch,
					crownMelee ? kCsDetailCrownMelee : kCsDetailNone);
				if (ckpt) --r->st[kCsWitch];
			}
		}
		return;
	case 'r':
		if (!strcmp(n, "revive_success")) {
			const int who = EvInt(ev, "userid", 0);
			if (who > 0 && who != EvInt(ev, "subject", 0)
				&& !(CkptZombieKillsReady() && g_offCkptReviveOther >= 0))
				ChapStatsBump(who, kCsRevive);
		} else if (!strcmp(n, "round_start")) {
			// Data-only freeze if Paint has not run yet — never WarmFonts / face
			// bind on the event thread (Surface / material work stays on Paint).
			if (g_csFreezePending) ChapStatsFreezeData(false);
			ChapStatsScoreHudClear();
			ChapStatsSetClear(g_csLive);
			g_csFrozenThisRound = false;
			g_csFreezePending = false;
			memset(g_csTankDupUid, 0, sizeof(g_csTankDupUid));
		}
		return;
	case 'd':
		if (!strcmp(n, "defibrillator_used")) ChapStatsBump(EvInt(ev, "userid", 0), kCsDefib);
		return;
	case 'h':
		if (!strcmp(n, "heal_success")) {
			const int who = EvInt(ev, "userid", 0);
			if (who > 0 && who != EvInt(ev, "subject", 0)) ChapStatsBump(who, kCsHeal);
		}
		return;
	case 'm':
		if (!strcmp(n, "map_transition")) ChapStatsRequestFreeze();
		else if (!strcmp(n, "mission_lost")) {
			// Wipe: this attempt is not settled; the restart's round_start clears it.
			ChapStatsScoreHudClear();
			ChapStatsSetClear(g_csLive);
			g_csFreezePending = false;
			g_csFrozenThisRound = true; // nothing to freeze until the next round_start
		}
		return;
	default:
		return;
	}
}

// Paint thread, bounded 1..32: presence, survivor flag, character and names.
static void ChapStatsRefreshPlayers() {
	ChapStatsSet& s = g_csLive;
	if (s.n < 0 || s.n > kCsRecMax) s.n = 0;
	for (int i = 0; i < s.n; ++i) s.rec[i].present = false;
	if (!g_entlist) return;
	for (int i = 1; i <= 32; ++i) {
		void* e = EntGet(i);
		if (!e || !EntReadable(e)) continue;
		PlayerInfo pi{};
		if (!EngPlayerInfo(i, &pi) || !pi.name[0] || pi.userid <= 0) continue;
		const int team = TabReadInt(e, g_offTeam, 0);
		ChapStatsRec* r = nullptr;
		for (int k = 0; k < s.n; ++k)
			if (s.rec[k].userid == pi.userid) { r = &s.rec[k]; break; }
		if (!r) {
			if (team != 2) continue; // only survivors get an empty row
			r = ChapStatsRecFor(pi.userid);
			if (!r) continue;
		} else {
			uint32_t acct = 0;
			memcpy(&acct, pi.pad1 + 36, sizeof(acct));
			if (!PlayerInfoIsBot(pi) && r->acct && acct && r->acct != acct) {
				// Same userid, different account: never carry numbers over.
				const int uid = r->userid;
				memset(r, 0, sizeof(*r));
				r->userid = uid;
				r->ch = -1;
			}
			ChapStatsFillIdentity(*r, i, pi);
		}
		r->present = true;
		if (team == 2) {
			r->survivor = true;
			const int raw = TabReadInt(e, g_offSurvivorCharacter, -1);
			int prop = TeamHudResolveAvatarProp(e, raw, &pi);
			if (prop < 0 || prop > 7) prop = r->ch;
			r->ch = prop;
		}
	}
	ChapStatsUniqueNames(s);
}

// Quiet-band scale (stock header 0..60 and tip bar r65 of 480). Used at freeze so
// fonts exist before IsDrawingLoadingImage, and again in ChapStatsPaint.
static int ChapStatsQuietScale(int sw, int sh, int designW, int designH, int maxWidthPct) {
	const int bandTop = sh * 60 / 480 + sh / 60;
	const int bandBot = sh * 415 / 480 - sh / 60;
	int sc = HudClampScale(g_chapStatsScale);
	const int maxW = sw * maxWidthPct / 100;
	const int maxH = bandBot - bandTop;
	const int wantW = HudScalePxPanel(designW, sc, g_optChapStatsResScale);
	if (wantW > maxW && wantW > 0) sc = sc * maxW / wantW;
	const int wantH = HudScalePxPanel(designH > 0 ? designH : 280, sc, g_optChapStatsResScale);
	if (wantH > maxH && maxH > 0 && wantH > 0) sc = sc * maxH / wantH;
	const int fit = sc;
	sc = HudClampScale(sc);
	if (sc > fit && sc - kHudScaleStep >= kHudScaleMin) sc -= kHudScaleStep;
	return sc;
}

static bool ChapStatsEnsureFonts(int sc, bool allowCreate);

static void ChapStatsWarmDesign(int* designW, int* designH, int* maxWidthPct) {
	if (!designW || !designH || !maxWidthPct) return;
	const int n = (g_csSnap.n >= 0 && g_csSnap.n <= kCsRecMax) ? g_csSnap.n : 0;
	const int total = n; // FreezeData snapshots only present survivor rows.
	const int maxRows = g_chapStatsMaxRows <= 4 ? 4 : (g_chapStatsMaxRows <= 8 ? 8 : (g_chapStatsMaxRows <= 12 ? 12 : 16));
	const int shown = total < maxRows ? total : maxRows;
	const int count = shown > 0 ? shown : 1;
	const int more = total - shown;
	if (g_chapStatsLayout == 1) {
		const int cardW = count < 4 ? 220 : (count <= 8 ? 180 : 118);
		const int cardH = 508;
		*designW = count * cardW + (count > 1 ? (count - 1) * 14 : 0);
		*designH = 52 + cardH + (more > 0 ? 22 : 8);
		*maxWidthPct = 96;
		return;
	}
	if (g_chapStatsLayout == 3) {
		const int cols = count < 4 ? count : 4;
		const int rows = (count + cols - 1) / cols;
		const int cardW = count < 4 ? 350 : (count <= 8 ? 320 : 294);
		const int cardH = rows >= 3 ? 162 : (rows == 2 ? 188 : 220);
		*designW = cols * cardW + (cols - 1) * 12 + 24;
		*designH = 72 + rows * cardH + (rows - 1) * 10 + (more > 0 ? 24 : 12);
		*maxWidthPct = 94;
		return;
	}
	const int tier = shown < 4 ? 0 : (shown <= 8 ? 1 : 2);
	const int rowH = tier == 0 ? 48 : (tier == 1 ? 38 : 28);
	*designW = (g_chapStatsLayout == 2 || g_chapStatsLayout == 4) ? 1240 : 940;
	*designH = 64 + 30 + count * rowH + (more > 0 ? 22 : 0) + 10;
	*maxWidthPct = 94;
}

// Build fonts at the quiet-band size while still in-game — loading Paint must not
// create fonts and must not blank the panel over a one-step scale mismatch.
static bool ChapStatsWarmFonts() {
	if (!MenuEnsureSurf()) return false;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 320 || sh < 240) return false;
	int designW = 940, designH = 280, maxWidthPct = 94;
	ChapStatsWarmDesign(&designW, &designH, &maxWidthPct);
	return ChapStatsEnsureFonts(ChapStatsQuietScale(sw, sh, designW, designH, maxWidthPct), true);
}

// BOT rows have no Steam friendsID. TAB / teammate HUD bind vgui/s_panel_* in
// live in-game Paint; the settle snapshot is quiet and must not CreateNewTextureID
// during the loading image. Bind the 8 survivor portraits while still in-game
// and keep the ISurface ids for quiet draw.
static int g_csFaceTex[8] = { -1, -1, -1, -1, -1, -1, -1, -1 };
static int g_csFaceEpoch = -1;

static void ChapStatsPrefetchFaces() {
	if (!g_engine || !EngInGame() || EngDrawingLoading() || !g_surf) return;
	if (g_csFaceEpoch != g_sktFontEpoch) {
		for (int i = 0; i < 8; ++i) g_csFaceTex[i] = -1;
		g_csFaceEpoch = g_sktFontEpoch;
	}
	for (int ch = 0; ch < 8; ++ch) {
		if (g_csFaceTex[ch] >= 0) continue;
		g_csFaceTex[ch] = TeamHudBindFace(ch, false);
	}
}

static int ChapStatsFaceTex(int ch) {
	if (ch < 0 || ch > 7) return -1;
	if (g_csFaceEpoch == g_sktFontEpoch && g_csFaceTex[ch] >= 0)
		return g_csFaceTex[ch];
	return -1;
}

static void ChapStatsFreezeData(bool refreshPlayers) {
	g_csFreezePending = false;
	// Paint owns engine/entity reads. The round_start fallback can only freeze
	// the already cached player records before clearing the next round's state.
	if (refreshPlayers) ChapStatsRefreshPlayers();
	if (g_mainUiBattlePending) {
		MainUiHubCaptureLive(0);
		g_mainUiBattlePending = false;
	}
	// Keep every currently present userid as its own row, including survivors that
	// share a character. Preserve the old takeover behavior only for absent records:
	// their counters may fold into one present same-character row.
	{
		ChapStatsSet out{};
		out.n = 0;
		int slotByCh[8];
		for (int i = 0; i < 8; ++i) slotByCh[i] = -1;
		const int n = (g_csLive.n >= 0 && g_csLive.n <= kCsRecMax) ? g_csLive.n : 0;
		auto mergeSt = [](ChapStatsRec& dst, const ChapStatsRec& src) {
			for (int s = 0; s < kCsStatN; ++s) dst.st[s] += src.st[s];
			for (int s = 0; s <= kCsWitch; ++s) dst.hsKill[s] += src.hsKill[s];
		};
		for (int i = 0; i < n; ++i) {
			const ChapStatsRec& src = g_csLive.rec[i];
			if (!src.present || !src.survivor) continue;
			if (out.n >= kCsRecMax) continue;
			const int slot = out.n++;
			out.rec[slot] = src;
			if (src.ch >= 0 && src.ch < 8 && slotByCh[src.ch] < 0)
				slotByCh[src.ch] = slot;
		}
		for (int i = 0; i < n; ++i) {
			const ChapStatsRec& src = g_csLive.rec[i];
			if (src.present || !src.survivor || src.ch < 0 || src.ch > 7) continue;
			bool any = false;
			for (int s = 0; s < kCsStatN; ++s) if (src.st[s]) { any = true; break; }
			if (!any) continue;
			const int slot = slotByCh[src.ch];
			if (slot < 0) continue; // no present owner of this character — drop (left the squad)
			mergeSt(out.rec[slot], src);
		}
		g_csSnap = out;
		ChapStatsUniqueNames(g_csSnap);
	}
	g_csSnapValid = true;
	g_csSnapAt = GetTickCount();
	g_csWarmSnapAt = 0;
	g_csWarmLayout = g_csWarmScale = g_csWarmRows = -1;
	g_csWarmRes = g_csWarmRawPct = g_csWarmEpoch = -1;
	g_csSettleArmed = false;
	strncpy(g_csSnapMap, g_elimLastMap, sizeof(g_csSnapMap) - 1);
	g_csSnapMap[sizeof(g_csSnapMap) - 1] = 0;
	MapHudCopyDisplayNames(g_elimLastMap, g_csSnapCampaign, 64, g_csSnapChapter, 64);
	// Account for the next chapter immediately — do not wait for round_start.
	// Human userid is stable across maps; bots get new userids — both must wipe.
	ChapStatsSetClear(g_csLive);
	ChapStatsScoreHudClear();
	memset(g_csTankDupUid, 0, sizeof(g_csTankDupUid));
	g_csTankDupNext = 0;
	g_csNatTries = 0;
	g_csNatSearchAt = 0;
	g_csPageManual = -1;
	g_csPageManualAt = 0;
}

// Paint / Tick only: fonts + face binds. Never call from FireGameEvent.
static void ChapStatsWarmAfterFreeze() {
	if (!g_csSnapValid) return;
	bool needFace = (g_csFaceEpoch != g_sktFontEpoch);
	if (!needFace) {
		for (int i = 0; i < 8; ++i)
			if (g_csFaceTex[i] < 0) { needFace = true; break; }
	}
	const bool configChanged = g_csWarmSnapAt != g_csSnapAt || g_csWarmLayout != g_chapStatsLayout
		|| g_csWarmScale != g_chapStatsScale || g_csWarmRows != g_chapStatsMaxRows
		|| g_csWarmRes != (g_optChapStatsResScale ? 1 : 0)
		|| g_csWarmRawPct != g_hudResolutionScaleRawPct || g_csWarmEpoch != g_sktFontEpoch;
	const bool needFont = !g_csFontTitle || !g_csFontName || !g_csFontNum || !g_csFontSmall
		|| g_csFontEpoch != g_sktFontEpoch;
	if (!needFont && !configChanged && !needFace) return;
	const bool fontReady = (needFont || configChanged) ? ChapStatsWarmFonts() : true;
	if (needFace) ChapStatsPrefetchFaces();
	if (!fontReady) return;
	g_csWarmSnapAt = g_csSnapAt;
	g_csWarmLayout = g_chapStatsLayout;
	g_csWarmScale = g_chapStatsScale;
	g_csWarmRows = g_chapStatsMaxRows;
	g_csWarmRes = g_optChapStatsResScale ? 1 : 0;
	g_csWarmRawPct = g_hudResolutionScaleRawPct;
	g_csWarmEpoch = g_sktFontEpoch;
	int faces = 0;
	for (int i = 0; i < 8; ++i)
		if (g_csFaceTex[i] >= 0) ++faces;
	Log("chapstats: warm fonts=%d faces=%d",
		(g_csFontName && g_csFontNum && g_csFontSmall) ? 1 : 0, faces);
}

static void ChapStatsFreeze() {
	ChapStatsFreezeData(true);
	ChapStatsAvatarFlush();
	ChapStatsWarmAfterFreeze();
}

static bool ChapStatsQuietWanted() {
	return g_optChapStats && g_csSnapValid && !HudCustomHidden()
		&& g_run.load(std::memory_order_relaxed) && SkeetoFeaturesOn();
}

static bool ChapStatsLiveWanted() {
	return (g_optChapStats && g_csHeld)
		|| HudMenuPage(kMenuPageChapStats) || HudMenuPage(kMenuPageChapStatsStyle)
		|| HudMenuPage(kMenuPageChapStatsSize) || HudMenuPage(kMenuPageChapStatsDisplay);
}

// ---- stock transition stats ----------------------------------------------------
// Stock page = client viewport "transition_stats" (CTransitionStatsPanel). We only
// park its middle body SurvivorHighlightStatsPanel — keep the header (loading
// spinner / next map) and footer. Hiding the whole window blanks the load screen
// to pure black. Our panel draws in the band between header and tip bar; during
// IsDrawingLoadingImage that draw needs StartDrawing/FinishDrawing (see SurfDrawing*).
// Restore only when the snapshot ends — never force-show into a live chapter.
struct ChapStatsNatSlot {
	unsigned int pan;
	uint32_t identity;
	int x, y;
	bool saved, parked, wasVisible;
};
static ChapStatsNatSlot g_csNat{};

static bool ChapStatsIsTransitionRoot(const char* n, const char* cls) {
	return (n && n[0] && !_stricmp(n, "transition_stats"))
		|| (cls && cls[0] && !_stricmp(cls, "CTransitionStatsPanel"));
}

static bool ChapStatsIsHighlightBody(const char* n, const char* cls) {
	return (n && n[0] && !_stricmp(n, "SurvivorHighlightStatsPanel"))
		|| (cls && cls[0] && !_stricmp(cls, "CSurvivorHighlightStatsPanel"));
}

static void ChapStatsNatConsider(unsigned int p) {
	if (!p || g_csNatHit) return;
	if (ChapStatsIsTransitionRoot(HudVguiName(p), HudVguiClass(p)))
		g_csNatHit = p;
}

// VGUI work while connected between levels OR during the loading image: the
// highlight body paints under Fullscreen Root then too. Restore stays deferred
// until !loading so we never force-show into a live chapter.
static bool ChapStatsVguiCtxOk() {
	if (g_hvPanelFaulted || !HudVguiReady()) return false;
	if (!g_engine) return false;
	return EngConnected();
}

// Distinct roots, most likely first: client DLL, embedded surface, engine root, GameUI.
static int ChapStatsRoots(unsigned int* out) {
	const unsigned int cand[4] = {
		HudVguiEnginePanel(kPanelClientDll), HudVguiEmbedded(), HudVguiEnginePanel(0), HudVguiEnginePanel(1)
	};
	int n = 0;
	for (int i = 0; i < 4; ++i) {
		if (!cand[i]) continue;
		bool dup = false;
		for (int k = 0; k < n; ++k)
			if (out[k] == cand[i]) dup = true;
		if (!dup) out[n++] = cand[i];
	}
	return n;
}

// One line: up to 4 ancestors, i.e. which root the stock panel really hangs under.
static void ChapStatsLogChain(const char* tag, unsigned int p) {
	char buf[384];
	int len = 0;
	buf[0] = 0;
	unsigned int cur = HudVguiParent(p);
	for (int d = 0; d < 4 && cur && !g_hvPanelFaulted; ++d) {
		const int w = snprintf(buf + len, sizeof(buf) - (size_t)len, "%s%s/%s", d ? " < " : "",
			HudVguiName(cur), HudVguiClass(cur));
		if (w < 0) break;
		len += w;
		if (len >= (int)sizeof(buf) - 1) { len = (int)sizeof(buf) - 1; break; }
		const unsigned int up = HudVguiParent(cur);
		if (up == cur) break;
		cur = up;
	}
	Log("chapstats: %s pan=%u name=%s class=%s visible=%d parents=[%s]", tag, p,
		HudVguiName(p), HudVguiClass(p), HudVguiIsVisible(p) ? 1 : 0, buf);
}

static void ChapStatsNatSearch() {
	g_csNatHit = 0;
	unsigned int roots[4];
	const int nr = ChapStatsRoots(roots);
	unsigned int root = 0;
	for (int i = 0; i < nr && !root && !g_hvPanelFaulted; ++i) {
		g_csNatHit = 0;
		HudVguiVisitViewportLeaves(roots[i], ChapStatsNatConsider);
		if (g_csNatHit) root = g_csNatHit;
	}
	if (!root || g_hvPanelFaulted) { g_csNatHit = 0; return; }
	if (g_csNatRoot != root)
		ChapStatsLogChain("stock transition_stats found", root);
	g_csNatRoot = root;
	// Body only — never park the whole transition_stats window (that blanks load).
	unsigned int body = 0;
	unsigned int kids[64];
	const int nk = HudVguiFillKids(root, kids, 64);
	for (int i = 0; i < nk && !body && !g_hvPanelFaulted; ++i) {
		if (ChapStatsIsHighlightBody(HudVguiName(kids[i]), HudVguiClass(kids[i]))) {
			body = kids[i];
			break;
		}
		unsigned int g2[32];
		const int n2 = HudVguiFillKids(kids[i], g2, 32);
		for (int j = 0; j < n2 && !body && !g_hvPanelFaulted; ++j) {
			if (ChapStatsIsHighlightBody(HudVguiName(g2[j]), HudVguiClass(g2[j])))
				body = g2[j];
		}
	}
	if (!body || g_hvPanelFaulted) {
		g_csNatHit = 0;
		if (g_csNatLog != 3) {
			g_csNatLog = 3;
			Log("chapstats: no SurvivorHighlightStatsPanel child; vanilla left as is");
		}
		return;
	}
	const uint32_t id = HudVguiPanelIdentity(body);
	if (!id) { g_csNatHit = 0; return; }
	memset(&g_csNat, 0, sizeof(g_csNat));
	g_csNat.pan = body;
	g_csNat.identity = id;
	g_csNatHit = body;
}

static bool ChapStatsNatIdentityOk() {
	if (!g_csNat.pan) return false;
	const uint32_t id = HudVguiPanelIdentity(g_csNat.pan);
	return id && id == g_csNat.identity;
}

static void ChapStatsNatPark() {
	const unsigned int p = g_csNat.pan;
	if (!g_csNat.saved) {
		int x = 0, y = 0;
		HudVguiGetPos(p, &x, &y);
		if (g_hvPanelFaulted) return;
		if (x > -2000 && y > -2000) {
			g_csNat.x = x;
			g_csNat.y = y;
			g_csNat.wasVisible = HudVguiIsVisible(p);
			if (g_hvPanelFaulted) return;
			g_csNat.saved = true;
		}
	}
	int cx = 0, cy = 0;
	HudVguiGetPos(p, &cx, &cy);
	if (g_hvPanelFaulted) return;
	if (cx > -2000 || cy > -2000)
		HudVguiSetPos(p, -8000, -8000);
	if (g_hvPanelFaulted) return;
	// The parent cycles its highlight screens and may re-show the body: verify every
	// Paint, but only call SetVisible(false) when it is actually visible.
	if (HudVguiIsVisible(p)) {
		HudVguiSetVisible(p, false);
		if (g_hvPanelFaulted) return;
	}
	g_csNat.parked = true;
}

// Put the stats body back (position + the visibility it had when first parked) and
// forget every handle. Deferred while VGUI work is not allowed (loading image).
static void ChapStatsNatRelease() {
	if (g_csNat.parked || g_csNat.saved) {
		if (g_hvPanelFaulted || !HudVguiReady() || (g_engine && EngDrawingLoading())) return;
		if (ChapStatsNatIdentityOk()) {
			if (g_csNat.saved) HudVguiSetPos(g_csNat.pan, g_csNat.x, g_csNat.y);
			if (!g_hvPanelFaulted && g_csNat.wasVisible) HudVguiSetVisible(g_csNat.pan, true);
			Log("chapstats: stock SurvivorHighlightStatsPanel restored%s", g_hvPanelFaulted ? " (fault)" : "");
		} else {
			Log("chapstats: stock SurvivorHighlightStatsPanel handle changed; dropped without touching it");
		}
	}
	memset(&g_csNat, 0, sizeof(g_csNat));
	g_csNatRoot = 0;
	g_csNatHit = 0;
	g_csNatTries = 0;
	g_csNatSearchAt = 0;
	g_csNatLog = 0;
}

// Before the original engine Paint (next to HudHideTick) so a re-shown stock body
// is parked again before it can draw. O(1) when off and idle.
static void ChapStatsNativeTick() {
	const bool snapWant = g_optChapStats && g_csSnapValid && !HudCustomHidden()
		&& g_run.load(std::memory_order_relaxed) && SkeetoFeaturesOn();
	const bool loading = g_engine && EngDrawingLoading();
	const bool inGame = g_engine && EngInGame();
	// Keep searching / parking for the whole snapshot life. Timing alignment with
	// stock is done by g_csSettleArmed (only arm once transition_stats is visible
	// or the classic loading / !inGame window). Releasing on brief inGame&&!loading
	// flashes had left vanilla stats on subsequent chapter exits.
	if (!snapWant) {
		if (g_csNat.pan || g_csNatRoot || g_csNatTries)
			ChapStatsNatRelease();
		g_csSettleArmed = false;
		return;
	}
	if (!ChapStatsVguiCtxOk()) return;
	if (g_hvPanelFaulted) return;
	if (!g_csNat.pan) {
		const DWORD now = GetTickCount();
		if (g_csNatSearchAt && (LONG)(now - g_csNatSearchAt) < 500) return;
		g_csNatSearchAt = now;
		++g_csNatTries;
		ChapStatsNatSearch();
		if (g_hvPanelFaulted) return;
		if (!g_csNat.pan) {
			// Loading / !inGame can still arm so we paint even if the body search lags.
			if (loading || !inGame) g_csSettleArmed = true;
			else if (g_csNatRoot && HudVguiIsVisible(g_csNatRoot) && !g_hvPanelFaulted)
				g_csSettleArmed = true;
			if (g_csNatTries >= 6 && g_csNatLog != 2) {
				g_csNatLog = 2;
				Log("chapstats: stock highlight body not found yet (%d tries, ingame=%d loading=%d); still looking",
					g_csNatTries, inGame ? 1 : 0, loading ? 1 : 0);
			}
			return;
		}
	}
	// Handle can change across a level load — drop and re-search next tick, never give up.
	if (!ChapStatsNatIdentityOk()) {
		if (g_hvPanelFaulted) return;
		Log("chapstats: stock SurvivorHighlightStatsPanel identity changed; re-search");
		memset(&g_csNat, 0, sizeof(g_csNat));
		g_csNatHit = 0;
		g_csNatRoot = 0;
		return;
	}
	const bool rootVis = g_csNatRoot && HudVguiIsVisible(g_csNatRoot);
	if (g_hvPanelFaulted) return;
	if (loading || !inGame || rootVis)
		g_csSettleArmed = true;
	if (!g_csSettleArmed) return; // door-close head: parent not up yet
	ChapStatsNatPark();
	if (g_csNat.parked && g_csNatLog != 1 && !g_hvPanelFaulted) {
		g_csNatLog = 1;
		Log("chapstats: stock SurvivorHighlightStatsPanel hidden (ingame=%d rootvis=%d)",
			inGame ? 1 : 0, rootVis ? 1 : 0);
	}
}

// Every Paint (before the in-game return). O(1) when off and idle.
static void ChapStatsTick() {
	if (!g_optChapStats) {
		g_mainUiBattlePending = false;
		if (g_csLive.n || g_csSnapValid || g_csHeld || g_csFreezePending)
			ChapStatsClearAll();
		return;
	}
	if (!g_engine || !EngConnected()) {
		g_mainUiBattlePending = false;
		if (g_csLive.n || g_csSnapValid || g_csHeld || g_csFreezePending)
			ChapStatsClearAll();
		return;
	}
	// Drain copied PHC damage before the chapter snapshot freezes; no entity reads
	// happen on the event callback. A pending settle may resolve its final queue
	// while the old chapter is leaving the in-game state.
	if (g_csFreezePending && DamageEventQueuePending()) DrainDamageEventQueue(true);
	// Freeze ASAP (even mid-load / !inGame): map_transition may be followed by
	// loading before another in-game Paint, and round_start would wipe live data.
	if (g_csFreezePending) ChapStatsFreeze();
	// Finale wins have no map_transition freeze. Resolve their roster once on
	// Paint, without changing the chapter HUD's settle display.
	if (g_mainUiBattlePending) {
		ChapStatsRefreshPlayers();
		MainUiHubCaptureLive(0);
		g_mainUiBattlePending = false;
	}
	// Event-thread FreezeData leaves fonts/faces cold — warm while still in-game.
	// Freeze already did one ChapStatsAvatarFlush burst; keep retries rate-limited
	// here (Prefetch) instead of Fetch(16)+Upload(all) every Paint.
	if (g_csSnapValid && EngInGame() && !EngDrawingLoading()) {
		ChapStatsAvatarPrefetch();
		ChapStatsWarmAfterFreeze();
	}
	if (!EngInGame() || EngDrawingLoading()) return;
	if (g_csSnapValid && !g_hudPostMissionQuiet
		&& (LONG)(GetTickCount() - g_csSnapAt) > 1500) {
		g_csSnapValid = false;
		g_csFrozenThisRound = false; // next chapter's map_transition may freeze again
		g_csSettleArmed = false;
		ChapStatsSetClear(g_csSnap);
		if (g_csNat.pan || g_csNatRoot || g_csNatTries)
			ChapStatsNatRelease();
	}
}

static void ChapStatsTransitionPaint(int mode) {
	if (!g_optChapStats) return;
	const int bits = mode & (kPaintUiPanels | kPaintInGamePanels);
	if (!bits) return;
	if (!g_csSnapValid) return;
	const bool loading = g_engine && EngDrawingLoading();
	const bool inGame = g_engine && EngInGame();
	const bool gameUi = g_paintGameUiVisible.load(std::memory_order_relaxed);
	// Align with stock: paint only after settle is armed, and only while the stock
	// page would be up (loading / !inGame / transition_stats visible) — not the
	// door-close head or the post-load quiet tail.
	bool rootVis = false;
	if (g_csSettleArmed && g_csNatRoot && ChapStatsVguiCtxOk()) {
		rootVis = HudVguiIsVisible(g_csNatRoot);
		if (g_hvPanelFaulted) rootVis = false;
	}
	const bool stockUp = loading || !inGame || rootVis;
	const bool quietOk = ChapStatsQuietWanted() && g_csSettleArmed && stockUp;
	if (quietOk && (bits & kPaintUiPanels) && !(gameUi && inGame && !loading)
		&& g_chapStatsView != 2) {
		SurfDrawingLease drawing;
		if (drawing.ready) {
			const bool drew = ChapStatsPaint(true);
			if (drew) SurfFillFlush();
		}
	}
}

static void SkCmd_ChapStatsDown(int*) {
	if (!g_optChapStats || !g_engine || !EngInGame()) return;
	if (!g_csHeld) g_csHeldAt = GetTickCount();
	g_csHeld = true;
	g_csRefreshAt = 0;
	TabAvatarFetch(8);
}

static void SkCmd_ChapStatsUp(int*) {
	g_csHeld = false;
}

static void SkCmd_ChapStatsScoreReload(int*) {
	if (ChapStatsScoreLoad())
		ConEcho("chapstats: score weights reloaded from skeeto_chapstats_score.ini");
	else
		ConEcho("chapstats: score reload failed (see log)");
}

static void ChapStatsOnToggle() {
	ChapStatsClearAll();
	if (g_optChapStats && g_optChapStatsScore) ChapStatsScoreLoad();
}

// Normal (non-quiet) HUD paint only: the snapshot is drawn during visual quiet,
// where no texture upload happens, so Steam avatars are cached ahead of time.
// Every 1 s: <= 8 Steam requests (TAB board cache, missing first) and <= 2 uploads.
static DWORD g_csAvAt = 0;
static void ChapStatsAvatarPrefetch() {
	const DWORD now = GetTickCount();
	if (g_csAvAt && (LONG)(now - g_csAvAt) < 1000) return;
	g_csAvAt = now;
	TabAvatarFetch(8);
	TabAvatarUploadTick();
	ChapStatsPrefetchFaces();
}

// ---- paint -------------------------------------------------------------------
// allowCreate=false (not in game / loading): reuse the cached set even if the
// quiet-band scale wants a slightly different px. Returning false blanked the
// whole panel for the entire load after a one-step shrink.
static bool ChapStatsEnsureFonts(int sc, bool allowCreate) {
	const int pxT = HudScalePxPanel(21, sc, g_optChapStatsResScale);
	const int pxN = HudScalePxPanel(16, sc, g_optChapStatsResScale);
	const int pxS = HudScalePxPanel(12, sc, g_optChapStatsResScale);
	if (g_csFontTitle && g_csFontName && g_csFontNum && g_csFontSmall
		&& g_csFontEpoch == g_sktFontEpoch) {
		if (g_csPxTitle == pxT && g_csPxName == pxN && g_csPxSmall == pxS)
			return true;
		if (!allowCreate)
			return true;
	}
	if (!allowCreate) return false;
	const int fl = kFontFlagAntiAlias | kFontFlagDropShadow;
	g_csFontTitle = SurfMakeYahei(pxT, 800, fl);
	g_csFontName = SurfMakeYahei(pxN, 600, fl);
	g_csFontNum = SurfMakeYahei(pxN, 800, fl);
	g_csFontSmall = SurfMakeYahei(pxS, 700, fl);
	g_csPxTitle = pxT;
	g_csPxName = pxN;
	g_csPxSmall = pxS;
	g_csFontEpoch = g_sktFontEpoch;
	return g_csFontName && g_csFontSmall && g_csFontNum;
}

static bool ChapStatsScoreHudEnsureFonts(int sc, bool allowCreate) {
	const int pxN = HudScalePxPanel(16, sc, g_optChapStatsResScale);
	const int pxS = HudScalePxPanel(12, sc, g_optChapStatsResScale);
	if (g_csScoreFontNum && g_csScoreFontSmall && g_csScoreFontEpoch == g_sktFontEpoch) {
		if (g_csScorePxNum == pxN && g_csScorePxSmall == pxS) return true;
		if (!allowCreate) return true;
	}
	if (!allowCreate) return false;
	const int fl = kFontFlagAntiAlias | kFontFlagDropShadow;
	g_csScoreFontNum = SurfMakeYahei(pxN, 800, fl);
	g_csScoreFontSmall = SurfMakeYahei(pxS, 700, fl);
	g_csScorePxNum = pxN;
	g_csScorePxSmall = pxS;
	g_csScoreFontEpoch = g_sktFontEpoch;
	return g_csScoreFontNum && g_csScoreFontSmall;
}

static int ChapStatsKills(const ChapStatsRec& r) {
	int k = 0;
	for (int i = kCsCi; i <= kCsTank; ++i) k += r.st[i];
	return k;
}

static int ChapStatsHsKillSum(const ChapStatsRec& r) {
	int h = 0;
	for (int i = kCsCi; i <= kCsWitch; ++i) h += r.hsKill[i];
	if (r.st[kCsHs] > h) h = r.st[kCsHs];
	return h;
}

static int ChapStatsSiKills(const ChapStatsRec& r) {
	int k = 0;
	for (int i = kCsSmoker; i <= kCsCharger; ++i) k += r.st[i];
	return k;
}

struct ChapStatsScoreParts {
	// Fixed-point hundredths: all scoring views and toast deltas share this unit.
	int kills, hs, siKills, siHs, support, penalty, special, dmg, total;
};

// Per full 100 damage (floor: 879 Tank with tank_dmg_per_100=1 -> +8).
static int ChapStatsDmgScoreCents(const ChapStatsRec& r) {
	int tank = r.st[kCsTankDmg];
	int witch = r.st[kCsWitchDmg];
	if (tank < 0) tank = 0;
	if (witch < 0) witch = 0;
	const ChapStatsScoreW& w = g_csScore;
	return (tank / 100 * w.tankDmgPer100 + witch / 100 * w.witchDmgPer100) * 100;
}

static ChapStatsScoreParts ChapStatsScoreOf(const ChapStatsRec& r) {
	const ChapStatsScoreW& w = g_csScore;
	ChapStatsScoreParts p{};
	for (int k = kCsCi; k <= kCsWitch; ++k) {
		const bool si = k >= kCsSmoker && k <= kCsCharger;
		if (!(si ? g_optChapStatsSi : g_optChapStatsKills)) continue;
		const int base = ChapStatsKillBasePts(w, k);
		p.kills += r.st[k] * base * 100;
		// Keep the fractional bonus: base 1 with hs_mul 125 is 25 cents.
		p.hs += r.hsKill[k] * base * (w.hsMul - 100);
		if (si) {
			p.siKills += r.st[k] * base * 100;
			p.siHs += r.hsKill[k] * base * (w.hsMul - 100);
		}
	}
	if (g_optChapStatsDmg)
		p.dmg = ChapStatsDmgScoreCents(r);
	if (g_optChapStatsTeam) {
		p.support = (r.st[kCsRevive] * w.revive + r.st[kCsDefib] * w.defib
			+ r.st[kCsHeal] * w.heal + r.st[kCsRescue] * w.rescue) * 100;
		p.penalty = (r.st[kCsPinned] * w.pinned + r.st[kCsIncap] * w.incap + r.st[kCsDeath] * w.death) * 100
			- skeeto_damage::FriendlyFirePenaltyCents(r.st[kCsFfDamage], w.ffDmgMul);
	}
	if (g_optChapStatsSpecial) {
		// Plain melee SI only: knife skeet / level already pay their own bonus.
		int plainMelee = r.st[kCsMeleeSi] - r.st[kCsMeleeSkeet] - r.st[kCsChargerLevel];
		if (plainMelee < 0) plainMelee = 0;
		p.special = (plainMelee * w.meleeSi + r.st[kCsSkeet] * w.skeet
			+ r.st[kCsMeleeSkeet] * w.meleeSkeet + r.st[kCsCrownMelee] * w.crownMelee
			+ r.st[kCsTongueCut] * w.tongueCut + r.st[kCsChargerLevel] * w.chargerLevel) * 100;
	}
	p.total = p.kills + p.hs + p.support + p.penalty + p.special + p.dmg;
	return p;
}

static int ChapStatsScoreTotal(const ChapStatsRec& r) {
	return ChapStatsScoreOf(r).total;
}


static int ChapStatsPageScoreContribution(const ChapStatsRec& r, int pageKind) {
	const ChapStatsScoreParts p = ChapStatsScoreOf(r);
	switch (pageKind) {
	case kCsKindKills:
		// SI is credited exclusively to its detail page, never twice in total.
		return p.kills + p.hs - p.siKills - p.siHs;
	case kCsKindDmg:
		return p.dmg;
	case kCsKindSi:
		return p.siKills + p.siHs;
	case kCsKindTeam:
		return p.support + p.penalty;
	case kCsKindSpec:
		return p.special;
	case kCsKindScore:
	default:
		return p.total;
	}
}

static int ChapStatsDisplayScore(const ChapStatsRec& r, int page) {
	if (!g_optChapStatsScore) return ChapStatsKills(r);
	return ChapStatsPageScoreContribution(r, ChapStatsPageKind(page));
}

static const wchar_t* ChapStatsDisplayScoreLabel(int page) {
	if (!g_optChapStatsScore)
		return UiText(UiId::ChapStatsCardKills, L"击杀");
	if (ChapStatsPageKind(page) == kCsKindScore)
		return UiText(UiId::ChapStatsCardScore, L"总分");
	return UiText(UiId::ChapStatsCardPageScore, L"本页得分");
}

static int ChapStatsScoreMetric(const ChapStatsRec& r, int page) {
	return g_optChapStatsScore
		? ChapStatsPageScoreContribution(r, ChapStatsPageKind(page)) : ChapStatsKills(r);
}

static bool ChapStatsIsScoreCol(int col) {
	return col >= kCsColScoreTotal && col <= kCsColScoreDmg;
}

static bool ChapStatsIsPercentCol(int col) {
	return col == kCsColHsRate;
}

static void ChapStatsFormatScore(wchar_t* out, size_t cap, int cents, bool showPlus = false) {
	const wchar_t* sign = cents < 0 ? L"-" : (showPlus && cents > 0 ? L"+" : L"");
	const long long magnitude = cents < 0 ? -(long long)cents : (long long)cents;
	const long long whole = magnitude / 100;
	const int fraction = (int)(magnitude % 100);
	if (!fraction) swprintf_s(out, cap, L"%s%lld", sign, whole);
	else if (fraction % 10 == 0) swprintf_s(out, cap, L"%s%lld.%d", sign, whole, fraction / 10);
	else swprintf_s(out, cap, L"%s%lld.%02d", sign, whole, fraction);
}

static void ChapStatsFormatValue(wchar_t* out, size_t cap, int value, int col) {
	if (value < 0 && !ChapStatsIsScoreCol(col)) wcscpy_s(out, cap, L"\x2014");
	else if (ChapStatsIsPercentCol(col)) swprintf_s(out, cap, L"%d%%", value);
	else if (ChapStatsIsScoreCol(col)) ChapStatsFormatScore(out, cap, value);
	else swprintf_s(out, cap, L"%d", value);
}

// Column value; -1 = not applicable ("—").
static int ChapStatsValue(const ChapStatsRec& r, int col) {
	if (col == kCsColSiSum) return ChapStatsSiKills(r);
	if (col == kCsColHsRate) {
		// Include Witch in the denominator; numerator prefers event hsKill[] (reliable).
		const int k = ChapStatsKills(r) + r.st[kCsWitch];
		const int h = ChapStatsHsKillSum(r);
		return k > 0 ? (h * 100 + k / 2) / k : -1;
	}
	if (ChapStatsIsScoreCol(col)) {
		const ChapStatsScoreParts p = ChapStatsScoreOf(r);
		switch (col) {
		case kCsColScoreTotal: return p.total;
		case kCsColScoreKills: return p.kills;
		case kCsColScoreHs: return p.hs;
		case kCsColScoreSupport: return p.support;
		case kCsColScorePenalty: return p.penalty;
		case kCsColScoreSpecial: return p.special;
		case kCsColScoreDmg: return p.dmg;
		default: break;
		}
	}
	return (col >= 0 && col < kCsStatN) ? r.st[col] : 0;
}

struct ChapStatsCol { int id; bool higher; UiId label; const wchar_t* zh; };

// ←/→ while the panel is on screen: step theme pages. After 8s idle, resume auto.
static int ChapStatsResolvePage(DWORD elapsed) {
	const int pages = ChapStatsPageCount();
	if (pages <= 0) return 0;
	const int autoPage = (int)((elapsed / ChapStatsPageMs()) % (DWORD)pages);
	const DWORD now = GetTickCount();
	auto edge = [](int vk, bool* prev) {
		const bool down = (GetAsyncKeyState(vk) & 0x8000) != 0;
		const bool fire = down && !*prev;
		*prev = down;
		return fire;
	};
	int delta = 0;
	if (edge(VK_LEFT, &g_csPageKeyL)) delta = -1;
	if (edge(VK_RIGHT, &g_csPageKeyR)) delta = 1;
	if (delta) {
		int cur = g_csPageManual >= 0 ? g_csPageManual : autoPage;
		cur = (cur + delta + pages) % pages;
		g_csPageManual = cur;
		g_csPageManualAt = now;
	}
	if (g_csPageManual >= 0) {
		if (g_csPageManual >= pages) g_csPageManual = pages - 1;
		if ((LONG)(now - g_csPageManualAt) > 8000) {
			g_csPageManual = -1;
			return autoPage;
		}
		return g_csPageManual % pages;
	}
	return autoPage;
}

// Vertical survivor cards. Same snapshot data as the table; layout only.
// Paint thread, only while the chapter panel is actually drawing.
static void ChapStatsPlaceLine(bool live, int humans, int bots, wchar_t* out, int outCap) {
	wchar_t campaign[64]{}, level[64]{};
	if (live)
		MapHudCopyDisplayNames(g_elimLastMap, campaign, 64, level, 64);
	else {
		wcsncpy_s(campaign, g_csSnapCampaign, _TRUNCATE);
		wcsncpy_s(level, g_csSnapChapter, _TRUNCATE);
		if (!campaign[0] && !level[0])
			MapHudCopyDisplayNames(g_csSnapMap, campaign, 64, level, 64);
	}
	char stem[64]{};
	MapHudStem(live ? g_elimLastMap : g_csSnapMap, stem, 64);
	int camp = 0, chap = 0;
	MapHudParse(stem, &camp, &chap);
	int total = 0;
	MapHudChapterCounts(stem, &chap, &total);
	wchar_t chapW[48]{};
	if (chap > 0 && total > 0)
		swprintf_s(chapW, UiText(UiId::TabBoardChapterOf, L"第 %d/%d 关"), chap, total);
	else if (chap > 0)
		swprintf_s(chapW, UiText(UiId::TabBoardChapter, L"第 %d 关"), chap);
	wchar_t who[64]{};
	swprintf_s(who, UiText(UiId::TabBoardHumansBots, L"真人 %d / BOT %d"), humans, bots);
	wchar_t code[64]{};
	const wchar_t* mapName = campaign;
	if (!mapName[0]) {
		if (level[0]) mapName = level;
		else {
			MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, stem, -1, code, 64);
			if (!code[0]) MultiByteToWideChar(CP_ACP, 0, stem, -1, code, 64);
			mapName = code;
		}
	}
	const bool showLevel = level[0] && mapName != level && wcscmp(level, mapName) != 0;
	// ASCII " / " only — Yahei via ISurface often lacks U+00B7 (·) and draws '?'.
	swprintf_s(out, outCap, L"%s%s%s%s%s%s%s",
		mapName,
		showLevel ? L" / " : L"",
		showLevel ? level : L"",
		chapW[0] ? L" / " : L"",
		chapW,
		(mapName[0] || chapW[0]) ? L" / " : L"",
		who);
}

static bool ChapStatsPaintCards(const ChapStatsSet& S, const int* idx, int shown, int more,
	int humans, int bots, const ChapStatsCol* cols, int nCols, const int* best, const bool* mark,
	int page, DWORD elapsed, bool quiet, bool live, bool inGame, bool loading, int sw, int sh) {
	const int nCards = shown > 0 ? shown : 1;
	// Three density bands: under 4, 4-8, and 9-16 players.
	const int kCardW = nCards < 4 ? 220 : (nCards <= 8 ? 180 : 118);
	const int kGap = 14;
	const int kCap = 52;
	// Extra height for the stronger label/value rows below the hero score.
	const int kCardH = nCols > 6 ? 508 : 480;
	const int designW = nCards * kCardW + (nCards > 1 ? (nCards - 1) * kGap : 0);
	const int designH = kCap + kCardH + (more > 0 ? 22 : 8);
	const int bandTop = quiet ? sh * 60 / 480 + sh / 60 : 0;
	const int bandBot = quiet ? sh * 415 / 480 - sh / 60 : sh;
	int sc = HudClampScale(g_chapStatsScale);
	{
		const int maxW = sw * 96 / 100;
		const int maxH = quiet ? (bandBot - bandTop) : sh * 92 / 100;
		const int wantW = HudScalePxPanel(designW, sc, g_optChapStatsResScale);
		if (wantW > maxW && wantW > 0) sc = sc * maxW / wantW;
		const int wantH = HudScalePxPanel(designH, sc, g_optChapStatsResScale);
		if (wantH > maxH && maxH > 0 && wantH > 0) sc = sc * maxH / wantH;
		const int fit = sc;
		sc = HudClampScale(sc);
		if (sc > fit && sc - kHudScaleStep >= kHudScaleMin) sc -= kHudScaleStep;
	}
	auto U = [&](int v) { return HudScalePxPanel(v, sc, g_optChapStatsResScale); };
	if (!ChapStatsEnsureFonts(sc, inGame && !loading)) return false;

	const int W = U(designW), H = U(designH);
	const int x0 = (sw - W) / 2;
	int y0;
	if (quiet) {
		y0 = bandTop + (bandBot - bandTop - H) / 2;
		if (y0 < bandTop) y0 = bandTop;
	} else {
		y0 = (sh - H) * 2 / 5;
		if (y0 < U(8)) y0 = U(8);
	}
	PanelStyleColors ps{};
	PanelStyleResolve(g_csStyle, &ps);
	const int aSr = ps.accR, aSg = ps.accG, aSb = ps.accB;
	const int aBr = ps.hiR, aBg = ps.hiG, aBb = ps.hiB;
	const COLORREF cText = ps.text;
	const COLORREF cMuted = RGB(138, 148, 166);
	const COLORREF cDim = RGB(96, 104, 120);
	const COLORREF cBest = RGB(aBr, aBg, aBb);

	int tops[16]{};
	int topN = 0;
	const int lim = shown < 16 ? shown : 16;
	for (int i = 0; i < lim; ++i) {
		const ChapStatsRec& r = S.rec[idx[i]];
		int n = 0;
		for (int c = 0; c < nCols; ++c) {
			const int v = ChapStatsValue(r, cols[c].id);
			const bool isBest = mark[c] && v == best[c]
				&& !(cols[c].id == kCsColHsRate && ChapStatsKills(r) < kCsRateMinKills);
			if (isBest) ++n;
		}
		tops[i] = n;
		if (n > topN) topN = n;
	}

	{
		const wchar_t* title = live ? UiText(UiId::ChapStatsTitleLive, L"本章累计（实时）")
			: UiText(UiId::ChapStatsTitle, L"章节结算");
		TbText(g_csFontTitle ? g_csFontTitle : g_csFontName, x0, y0 + U(16), g_csPxTitle, cText, title);
		wchar_t sub[224]{};
		ChapStatsPlaceLine(live, humans, bots, sub, 224);
		TbText(g_csFontSmall, x0, y0 + U(36), g_csPxSmall, cMuted, sub);
		TbTextRight(g_csFontSmall, x0 + W, y0 + U(36), g_csPxSmall, cDim,
			UiText(UiId::ChapStatsPageHint, L"← → 翻页"));

		const wchar_t* tabs[kCsPagesMax]{};
		const int pageN = ChapStatsFillTabLabels(tabs, kCsPagesMax);
		int xr = x0 + W;
		const int cy = y0 + U(16), bh = U(20), pad = U(8);
		for (int t = pageN - 1; t >= 0; --t) {
			const int w = SurfTextWFont(g_csFontSmall, tabs[t]) + pad * 2;
			xr -= w;
			if (t == page) {
				TbFillRound(xr, cy - bh / 2, xr + w, cy - bh / 2 + bh, bh / 2, aSr, aSg, aSb, 230);
				TbText(g_csFontSmall, xr + pad, cy, g_csPxSmall, RGB(10, 24, 20), tabs[t]);
				if (g_csPageManual < 0) {
					const int pw = (int)((long long)w * (long long)(elapsed % ChapStatsPageMs()) / (long long)ChapStatsPageMs());
					TbFill(xr, cy + bh / 2 + U(2), xr + pw, cy + bh / 2 + U(4), aSr, aSg, aSb, 220);
				} else {
					TbFill(xr, cy + bh / 2 + U(2), xr + w, cy + bh / 2 + U(4), aBr, aBg, aBb, 180);
				}
			} else {
				TbText(g_csFontSmall, xr + pad, cy, g_csPxSmall, cMuted, tabs[t]);
			}
			xr -= U(10);
		}
	}

	const int cardsTop = y0 + U(kCap);
	const int step = U(kCardW + kGap);
	const int cardW = U(kCardW), cardH = U(kCardH);
	if (shown <= 0) {
		const int cx0 = x0, cy0 = cardsTop;
		PanelStyleDrawFrame(ps, cx0, cy0, cx0 + cardW, cy0 + cardH, U(10), cy0);
		TbTextCenter(g_csFontName, cx0 + cardW / 2, cy0 + cardH / 2, g_csPxName, cMuted,
			UiText(UiId::ChapStatsNoData, L"本章暂无统计数据"));
		return true;
	}
	for (int i = 0; i < shown && i < 16; ++i) {
		const ChapStatsRec& r = S.rec[idx[i]];
		const int cx0 = x0 + i * step;
		const int cx1 = cx0 + cardW;
		const int cy0 = cardsTop;
		const int cy1 = cy0 + cardH;
		const bool local = g_localUserId > 0 && r.userid == g_localUserId;
		const COLORREF tc = TeamHudCharColor(r.ch);
		const int cr = GetRValue(tc), cg = GetGValue(tc), cb = GetBValue(tc);
		PanelStyleDrawFrame(ps, cx0, cy0, cx1, cy1, U(12), cy0);
		TbFill(cx0 + U(12), cy0, cx1 - U(12), cy0 + U(4), local ? aBr : cr, local ? aBg : cg, local ? aBb : cb, 255);
		TbFill(cx0, cy0 + U(14), cx0 + U(4), cy1 - U(14), cr, cg, cb, 255);

		const int av = U(nCards <= 4 ? 84 : (nCards <= 6 ? 64 : 48));
		const int ax = cx0 + (cardW - av) / 2;
		const int ay = cy0 + U(16);
		TbFill(ax - U(3), ay - U(3), ax + av + U(3), ay + av + U(3), cr / 3 + 12, cg / 3 + 12, cb / 3 + 16, 255);
		TbFill(ax - 1, ay - 1, ax + av + 1, ay + av + 1, 255, 255, 255, 46);
		TbFill(ax, ay, ax + av, ay + av, 22, 24, 30, 255);
		int tex = r.acct ? TabAvatarTex(r.acct) : -1;
		if (tex < 0 && r.ch >= 0) {
			if (!quiet) {
				tex = TeamHudBindFace(r.ch, false);
				if (tex >= 0 && r.ch < 8) {
					g_csFaceTex[r.ch] = tex;
					g_csFaceEpoch = g_sktFontEpoch;
				}
			} else {
				tex = ChapStatsFaceTex(r.ch);
			}
		}
		if (tex >= 0) {
			SurfColor(255, 255, 255, 255);
			SurfDrawTextured(ax, ay, ax + av, ay + av, tex);
		} else if (r.ch >= 0) {
			TbFill(ax, ay, ax + av, ay + av, cr / 2, cg / 2, cb / 2, 255);
			TbTextCenter(g_csFontName, ax + av / 2, ay + av / 2, g_csPxName, RGB(255, 255, 255), TabCharTag(r.ch));
		}

		wchar_t name[48]{};
		wcsncpy(name, r.display[0] ? r.display : (r.name[0] ? r.name : L"?"), 47);
		name[47] = 0;
		const int nameMax = cardW - U(28);
		int len = (int)wcslen(name);
		while (len > 1 && SurfTextWFont(g_csFontName, name) > nameMax) {
			--len;
			name[len - 1] = L'.';
			name[len] = 0;
		}
		int ny = ay + av + U(16);
		TbTextCenter(g_csFontName, cx0 + cardW / 2, ny, g_csPxName,
			local ? RGB(255, 226, 168) : (r.bot ? RGB(186, 194, 208) : cText), name);
		if (r.bot) {
			const wchar_t* bot = L"BOT";
			const int bw = SurfTextWFont(g_csFontSmall, bot) + U(10);
			const int bx = cx0 + (cardW - bw) / 2;
			const int by = ny + U(14);
			TbFillRound(bx, by - U(8), bx + bw, by + U(8), U(4), 70, 76, 90, 230);
			TbTextCenter(g_csFontSmall, cx0 + cardW / 2, by, g_csPxSmall, RGB(210, 216, 226), bot);
			ny = by + U(16);
		}

		wchar_t hero[16]{};
		const bool useScore = g_optChapStatsScore;
		if (useScore) ChapStatsFormatScore(hero, 16, ChapStatsDisplayScore(r, page));
		else swprintf_s(hero, 16, L"%d", ChapStatsKills(r));
		const int hy = ny + U(r.bot ? 18 : 28);
		const COLORREF heroC = local ? cBest : RGB(cr, cg, cb);
		TbTextCenter(g_csFontTitle ? g_csFontTitle : g_csFontNum, cx0 + cardW / 2, hy, g_csPxTitle, heroC, hero);
		TbTextCenter(g_csFontSmall, cx0 + cardW / 2, hy + U(16), g_csPxSmall, cMuted,
			ChapStatsDisplayScoreLabel(page));
		const int ruleY = hy + U(28);
		TbFill(cx0 + U(18), ruleY, cx1 - U(18), ruleY + 1, 255, 255, 255, 28);

		// Stat rows: brighter labels, same-band numbers, left rail so each pair
		// reads without competing with the hero score. Dense pages keep Small labels.
		const COLORREF cLabel = RGB(208, 216, 230);
		const bool dense = nCols > 6;
		const unsigned labelFont = dense ? g_csFontSmall : g_csFontName;
		const int labelPx = dense ? g_csPxSmall : g_csPxName;
		const int rowH = U(dense ? 26 : 30);
		int sy = ruleY + U(14);
		for (int c = 0; c < nCols; ++c) {
			const int v = ChapStatsValue(r, cols[c].id);
			wchar_t t[16]{};
			ChapStatsFormatValue(t, 16, v, cols[c].id);
			const bool isBest = mark[c] && v == best[c]
				&& !(cols[c].id == kCsColHsRate && ChapStatsKills(r) < kCsRateMinKills);
			const int ly = sy + c * rowH;
			const int rail = isBest ? 255 : (v > 0 ? 160 : 70);
			TbFill(cx0 + U(12), ly - U(7), cx0 + U(15), ly + U(7),
				isBest ? aBr : aSr, isBest ? aBg : aSg, isBest ? aBb : aSb, rail);
			TbText(labelFont, cx0 + U(20), ly, labelPx, isBest ? cBest : cLabel, UiText(cols[c].label, cols[c].zh));
			const int numW = SurfTextWFont(g_csFontNum, t);
			if (isBest)
				TbFillRound(cx1 - U(14) - numW - U(8), ly - U(10), cx1 - U(10), ly + U(10), U(4), aBr, aBg, aBb, 48);
			TbTextRight(g_csFontNum, cx1 - U(14), ly, g_csPxName, isBest ? cBest : (v > 0 ? cText : cDim), t);
		}
		if (topN > 0 && tops[i] == topN) {
			const wchar_t* rib = UiText(UiId::ChapStatsCardBest, L"本页最佳");
			const int rw = SurfTextWFont(g_csFontSmall, rib) + U(16);
			const int rx = cx0 + (cardW - rw) / 2;
			const int ry = cy1 - U(18);
			TbFillRound(rx, ry - U(9), rx + rw, ry + U(9), U(4), aBr, aBg, aBb, 210);
			TbTextCenter(g_csFontSmall, cx0 + cardW / 2, ry, g_csPxSmall, RGB(28, 18, 8), rib);
		}
	}
	if (more > 0) {
		wchar_t t[48]{};
		swprintf_s(t, 48, UiText(UiId::TabBoardMore, L"还有 %d 人"), more);
		TbTextCenter(g_csFontSmall, x0 + W / 2, cardsTop + cardH + U(12), g_csPxSmall, cDim, t);
	}
	return true;
}

// Four-column chapter board. It reuses the same snapshot, theme pages, cached
// faces and panel colors; only the selected layout reaches this painter.
static bool ChapStatsPaintCardGrid(const ChapStatsSet& S, const int* idx, int shown, int more,
	int humans, int bots, const ChapStatsCol* cols, int nCols, const int* best, const bool* mark,
	int page, DWORD elapsed, bool quiet, bool live, bool inGame, bool loading, int sw, int sh) {
	const int count = shown > 0 ? shown : 1;
	const int gridCols = count < 4 ? count : 4;
	const int gridRows = (count + gridCols - 1) / gridCols;
	const int cardW = count < 4 ? 350 : (count <= 8 ? 320 : 294);
	const int gapX = 12, gapY = 10, headH = 72;
	const int cardH = gridRows >= 3 ? 162 : (gridRows == 2 ? 188 : 220);
	const int designW = gridCols * cardW + (gridCols - 1) * gapX + 24;
	const int designH = headH + gridRows * cardH + (gridRows - 1) * gapY + (more > 0 ? 24 : 12);
	const int bandTop = quiet ? sh * 60 / 480 + sh / 60 : 0;
	const int bandBot = quiet ? sh * 415 / 480 - sh / 60 : sh;
	int sc = HudClampScale(g_chapStatsScale);
	{
		const int maxW = sw * 94 / 100;
		const int maxH = quiet ? (bandBot - bandTop) : sh * 90 / 100;
		const int wantW = HudScalePxPanel(designW, sc, g_optChapStatsResScale);
		if (wantW > maxW && wantW > 0) sc = sc * maxW / wantW;
		const int wantH = HudScalePxPanel(designH, sc, g_optChapStatsResScale);
		if (wantH > maxH && maxH > 0 && wantH > 0) sc = sc * maxH / wantH;
		const int fit = sc;
		sc = HudClampScale(sc);
		if (sc > fit && sc - kHudScaleStep >= kHudScaleMin) sc -= kHudScaleStep;
	}
	auto U = [&](int v) { return HudScalePxPanel(v, sc, g_optChapStatsResScale); };
	if (!ChapStatsEnsureFonts(sc, inGame && !loading)) return false;
	const int W = U(designW), H = U(designH);
	const int x0 = (sw - W) / 2;
	int y0 = quiet ? bandTop + (bandBot - bandTop - H) / 2 : (sh - H) * 2 / 5;
	if (y0 < (quiet ? bandTop : U(8))) y0 = quiet ? bandTop : U(8);
	const int x1 = x0 + W, y1 = y0 + H;
	PanelStyleColors ps{};
	PanelStyleResolve(g_csStyle, &ps);
	const COLORREF text = ps.text;
	const COLORREF muted = RGB(138, 148, 166);
	const COLORREF cLabel = RGB(208, 216, 230);
	const COLORREF cDim = RGB(96, 104, 120);
	const int ar = ps.accR, ag = ps.accG, ab = ps.accB;
	const int hr = ps.hiR, hg = ps.hiG, hb = ps.hiB;
	PanelStyleDrawFrame(ps, x0, y0, x1, y1, U(10), y0 + U(headH));
	TbFill(x0 + U(8), y0, x1 - U(8), y0 + U(3), ar, ag, ab, 255);
	const wchar_t* title = live ? UiText(UiId::ChapStatsTitleLive, L"本章累计（实时）")
		: UiText(UiId::ChapStatsTitle, L"章节结算");
	TbText(g_csFontTitle, x0 + U(18), y0 + U(25), g_csPxTitle, text, title);
	wchar_t who[224]{};
	ChapStatsPlaceLine(live, humans, bots, who, 224);
	TbText(g_csFontSmall, x0 + U(20), y0 + U(51), g_csPxSmall, muted, who);
	const wchar_t* tabs[kCsPagesMax]{};
	const int pageN = ChapStatsFillTabLabels(tabs, kCsPagesMax);
	wchar_t pageLabel[96]{};
	if (pageN > 0 && page >= 0 && page < pageN)
		swprintf_s(pageLabel, 96, L"%s  %d / %d", tabs[page], page + 1, pageN);
	TbTextRight(g_csFontSmall, x1 - U(18), y0 + U(25), g_csPxSmall, RGB(ar, ag, ab),
		pageLabel[0] ? pageLabel : UiText(UiId::ChapStatsPageHint, L"← → 翻页"));
	const int cardsX = x0 + U(12);
	const int cardsY = y0 + U(headH);
	const int cw = U(cardW), ch = U(cardH), gx = U(gapX), gy = U(gapY);
	if (shown <= 0) {
		TbTextCenter(g_csFontName, (x0 + x1) / 2, cardsY + ch / 2, g_csPxName, muted,
			UiText(UiId::ChapStatsNoData, L"本章暂无统计数据"));
		return true;
	}
	for (int i = 0; i < shown && i < 16; ++i) {
		const ChapStatsRec& r = S.rec[idx[i]];
		const int cx = cardsX + (i % gridCols) * (cw + gx);
		const int cy = cardsY + (i / gridCols) * (ch + gy);
		const int cx1 = cx + cw, cy1 = cy + ch;
		const bool local = g_localUserId > 0 && r.userid == g_localUserId;
		const COLORREF role = TeamHudCharColor(r.ch);
		PanelStyleDrawFrame(ps, cx, cy, cx1, cy1, U(8), cy);
		TbFill(cx + U(8), cy, cx1 - U(8), cy + U(3), local ? hr : ar, local ? hg : ag, local ? hb : ab, 255);
		const COLORREF rankColor = i == 0 ? RGB(hr, hg, hb) : (i < 3 ? RGB(ar, ag, ab) : muted);
		wchar_t rank[12]{};
		swprintf_s(rank, 12, L"%d", i + 1);
		TbText(g_csFontNum, cx + U(12), cy + U(27), g_csPxName, rankColor, rank);
		const int av = U(gridRows >= 3 ? 34 : 42);
		const int ax = cx + U(42), ay = cy + U(10);
		TbFill(ax - 1, ay - 1, ax + av + 1, ay + av + 1, 255, 255, 255, 42);
		TbFill(ax, ay, ax + av, ay + av, 24, 28, 36, 255);
		int tex = r.acct ? TabAvatarTex(r.acct) : -1;
		if (tex < 0 && r.ch >= 0) {
			if (!quiet) {
				tex = TeamHudBindFace(r.ch, false);
				if (tex >= 0 && r.ch < 8) { g_csFaceTex[r.ch] = tex; g_csFaceEpoch = g_sktFontEpoch; }
			} else tex = ChapStatsFaceTex(r.ch);
		}
		if (tex >= 0) {
			SurfColor(255, 255, 255, 255);
			SurfDrawTextured(ax, ay, ax + av, ay + av, tex);
		} else if (r.ch >= 0) {
			TbFill(ax, ay, ax + av, ay + av, GetRValue(role) / 2, GetGValue(role) / 2, GetBValue(role) / 2, 255);
			TbTextCenter(g_csFontSmall, ax + av / 2, ay + av / 2, g_csPxSmall, text, TabCharTag(r.ch));
		}
		wchar_t name[48]{};
		wcsncpy(name, r.display[0] ? r.display : (r.name[0] ? r.name : L"?"), 47);
		name[47] = 0;
		const int nameX = ax + av + U(8);
		wchar_t score[24]{};
		if (g_optChapStatsScore) ChapStatsFormatScore(score, 24, ChapStatsDisplayScore(r, page));
		else swprintf_s(score, 24, L"%d", ChapStatsKills(r));
		const int scoreRight = cx1 - U(12);
		const wchar_t* scoreLabel = ChapStatsDisplayScoreLabel(page);
		const int scoreLabelW = SurfTextWFont(g_csFontSmall, scoreLabel);
		const int scoreNumW = SurfTextWFont(g_csFontNum, score);
		const int scoreLabelX = scoreRight - scoreNumW - U(6) - scoreLabelW;
		const int nameXMax = scoreLabelX - U(7);
		const int botW = r.bot ? U(38) : 0;
		const int nameMax = nameXMax - nameX - (botW ? botW + U(5) : 0);
		int nameLen = (int)wcslen(name);
		while (nameLen > 1 && SurfTextWFont(g_csFontName, name) > nameMax) {
			--nameLen; name[nameLen - 1] = L'.'; name[nameLen] = 0;
		}
		TbText(g_csFontName, nameX, cy + U(27), g_csPxName,
			local ? RGB(255, 226, 168) : (r.bot ? RGB(196, 205, 218) : text), name);
		if (r.bot) {
			const int bx = nameX + SurfTextWFont(g_csFontName, name) + U(5), by = cy + U(27), bw = U(38), bh = U(17);
			TbFillRound(bx, by - bh / 2, bx + bw, by + bh / 2, U(4), 70, 76, 90, 230);
			TbTextCenter(g_csFontSmall, bx + bw / 2, by, g_csPxSmall, RGB(210, 216, 226), L"BOT");
		}
		TbText(g_csFontSmall, scoreLabelX, cy + U(27), g_csPxSmall, muted, scoreLabel);
		TbTextRight(g_csFontNum, scoreRight, cy + U(27), g_csPxName, RGB(255, 207, 105), score);
		TbFill(cx + U(10), cy + U(53), cx1 - U(10), cy + U(54), 255, 255, 255, 32);
		const int fields = nCols < 4 ? nCols : 4;
		const int statY = cy + U(61);
		const int fieldW = fields > 0 ? (cw - U(20)) / fields : cw - U(20);
		for (int c = 0; c < fields; ++c) {
			const int fx = cx + U(10) + c * fieldW;
			if (c > 0) TbFill(fx, statY + U(3), fx + 1, cy1 - U(8), 255, 255, 255, 24);
			const int v = ChapStatsValue(r, cols[c].id);
			wchar_t value[20]{};
			ChapStatsFormatValue(value, 20, v, cols[c].id);
			const bool isBest = mark[c] && v == best[c]
				&& !(cols[c].id == kCsColHsRate && ChapStatsKills(r) < kCsRateMinKills);
			const COLORREF bestC = RGB(hr, hg, hb);
			TbFill(fx + fieldW / 2 - U(10), statY + U(2), fx + fieldW / 2 + U(10), statY + U(4),
				isBest ? hr : ar, isBest ? hg : ag, isBest ? hb : ab, isBest ? 255 : (v > 0 ? 150 : 70));
			TbTextCenter(g_csFontSmall, fx + fieldW / 2, statY + U(14), g_csPxSmall,
				isBest ? bestC : cLabel, UiText(cols[c].label, cols[c].zh));
			TbTextCenter(g_csFontNum, fx + fieldW / 2, statY + U(38), g_csPxName,
				isBest ? bestC : (v > 0 ? text : cDim), value);
		}
	}
	if (more > 0) {
		wchar_t t[48]{};
		swprintf_s(t, 48, UiText(UiId::TabBoardMore, L"还有 %d 人"), more);
		TbTextCenter(g_csFontSmall, (x0 + x1) / 2, y1 - U(6), g_csPxSmall, muted, t);
	}
	return true;
}

// Tactical briefing: two wide player cards per row, with each active stat page
// shown as compact, comparable cells. This stays separate from the table and
// card-grid painters; only the selected layout performs these extra draws.
static bool ChapStatsPaintTactical(const ChapStatsSet& S, const int* idx, int shown, int more,
	int humans, int bots, const ChapStatsCol* cols, int nCols, const int* best, const bool* mark,
	int page, DWORD elapsed, bool quiet, bool live, bool inGame, bool loading, int sw, int sh) {
	const int gridCols = shown <= 1 ? 1 : 2;
	const int gridRows = shown > 0 ? (shown + gridCols - 1) / gridCols : 1;
	const int cardH = shown > 8 ? 108 : (shown >= 4 ? 128 : 160);
	const int gapX = 12, gapY = 9, headH = 66, padX = 12;
	const int designW = 1240;
	const int designH = headH + gridRows * cardH + (gridRows - 1) * gapY + (more > 0 ? 22 : 10);
	const int bandTop = quiet ? sh * 60 / 480 + sh / 60 : 0;
	const int bandBot = quiet ? sh * 415 / 480 - sh / 60 : sh;
	int sc = HudClampScale(g_chapStatsScale);
	{
		const int maxW = sw * 94 / 100;
		const int maxH = quiet ? (bandBot - bandTop) : sh * 90 / 100;
		const int wantW = HudScalePxPanel(designW, sc, g_optChapStatsResScale);
		if (wantW > maxW && wantW > 0) sc = sc * maxW / wantW;
		const int wantH = HudScalePxPanel(designH, sc, g_optChapStatsResScale);
		if (wantH > maxH && wantH > 0) sc = sc * maxH / wantH;
		const int fit = sc;
		sc = HudClampScale(sc);
		if (sc > fit && sc - kHudScaleStep >= kHudScaleMin) sc -= kHudScaleStep;
	}
	auto U = [&](int v) { return HudScalePxPanel(v, sc, g_optChapStatsResScale); };
	if (!ChapStatsEnsureFonts(sc, inGame && !loading)) return false;
	const int W = U(designW), H = U(designH);
	const int x0 = (sw - W) / 2;
	int y0;
	if (quiet) {
		y0 = bandTop + (bandBot - bandTop - H) / 2;
		if (y0 < bandTop) y0 = bandTop;
	} else {
		y0 = (sh - H) * 2 / 5;
		if (y0 < U(12)) y0 = U(12);
	}
	const int x1 = x0 + W;
	PanelStyleColors ps{};
	PanelStyleResolve(g_csStyle, &ps);
	const int aSr = ps.accR, aSg = ps.accG, aSb = ps.accB;
	const int aBr = ps.hiR, aBg = ps.hiG, aBb = ps.hiB;
	const COLORREF cText = ps.text;
	const COLORREF cMuted = RGB(138, 148, 166);
	const COLORREF cDim = RGB(96, 104, 120);
	const COLORREF cBest = RGB(aBr, aBg, aBb);
	PanelStyleDrawFrame(ps, x0, y0, x1, y0 + H, U(10), y0 + U(headH));
	TbFill(x0 + U(10), y0, x1 - U(10), y0 + U(3), aSr, aSg, aSb, 255);

	const wchar_t* title = live ? UiText(UiId::ChapStatsTitleLive, L"本章累计（实时）")
		: UiText(UiId::ChapStatsTitle, L"章节结算");
	TbText(g_csFontTitle ? g_csFontTitle : g_csFontName, x0 + U(20), y0 + U(23), g_csPxTitle, cText, title);
	TbFillRound(x0 + U(242), y0 + U(12), x0 + U(366), y0 + U(34), U(9), aSr, aSg, aSb, 220);
	TbTextCenter(g_csFontSmall, x0 + U(304), y0 + U(23), g_csPxSmall, RGB(10, 24, 20),
		UiText(UiId::ChapStatsLayoutTactical, L"战术简报"));
	wchar_t subtitle[224]{};
	ChapStatsPlaceLine(live, humans, bots, subtitle, 224);
	TbText(g_csFontSmall, x0 + U(20), y0 + U(47), g_csPxSmall, cMuted, subtitle);

	const wchar_t* tabs[kCsPagesMax]{};
	const int tabN = ChapStatsFillTabLabels(tabs, kCsPagesMax);
	int tabX = x1 - U(18);
	const int tabY = y0 + U(26), tabPad = U(7), tabH = U(21);
	for (int t = tabN - 1; t >= 0; --t) {
		const int tabW = SurfTextWFont(g_csFontSmall, tabs[t]) + tabPad * 2;
		tabX -= tabW;
		if (t == page) {
			TbFillRound(tabX, tabY - tabH / 2, tabX + tabW, tabY + tabH / 2, tabH / 2, aSr, aSg, aSb, 225);
			TbText(g_csFontSmall, tabX + tabPad, tabY, g_csPxSmall, RGB(10, 24, 20), tabs[t]);
			if (g_csPageManual < 0) {
				const int progress = (int)((long long)tabW * (long long)(elapsed % ChapStatsPageMs()) / (long long)ChapStatsPageMs());
				TbFill(tabX, tabY + tabH / 2 + U(2), tabX + progress, tabY + tabH / 2 + U(4), aSr, aSg, aSb, 200);
			} else {
				TbFill(tabX, tabY + tabH / 2 + U(2), tabX + tabW, tabY + tabH / 2 + U(4), aBr, aBg, aBb, 190);
			}
		} else {
			TbText(g_csFontSmall, tabX + tabPad, tabY, g_csPxSmall, cMuted, tabs[t]);
		}
		tabX -= U(5);
	}

	const int bodyY = y0 + U(headH);
	const int bodyPad = U(padX), cardW = (W - bodyPad * 2 - U(gapX * (gridCols - 1))) / gridCols;
	if (shown <= 0) {
		const int cx = x0 + bodyPad, cy = bodyY;
		PanelStyleDrawFrame(ps, cx, cy, cx + cardW, cy + U(cardH), U(8), cy + U(30));
		TbTextCenter(g_csFontName, cx + cardW / 2, cy + U(cardH / 2), g_csPxName, cMuted,
			UiText(UiId::ChapStatsNoData, L"本章暂无统计数据"));
	}
	for (int i = 0; i < shown && i < 16; ++i) {
		const ChapStatsRec& r = S.rec[idx[i]];
		const int col = i % gridCols, row = i / gridCols;
		const int cx = x0 + bodyPad + col * (cardW + U(gapX));
		const int cy = bodyY + row * U(cardH + gapY), cy1 = cy + U(cardH);
		const bool local = g_localUserId > 0 && r.userid == g_localUserId;
		const COLORREF charColor = r.ch >= 0 ? TeamHudCharColor(r.ch) : RGB(101, 154, 177);
		PanelStyleDrawFrame(ps, cx, cy, cx + cardW, cy1, U(8), cy + U(30));
		if (local) TbFill(cx + U(2), cy + U(3), cx + U(5), cy1 - U(3), aBr, aBg, aBb, 255);
		else TbFill(cx + U(2), cy + U(3), cx + U(5), cy1 - U(3), GetRValue(charColor), GetGValue(charColor), GetBValue(charColor), 220);
		if (!local && ps.zebra && (i & 1))
			TbFill(cx + U(7), cy + U(3), cx + cardW - U(3), cy1 - U(3), ps.rowR, ps.rowG, ps.rowB, ps.bgA);

		wchar_t rank[16]{};
		swprintf_s(rank, 16, L"#%02d", i + 1);
		COLORREF rankColor = i == 0 ? cBest : i == 1 ? RGB(193, 202, 210) : i == 2 ? RGB(206, 151, 104) : cMuted;
		TbFillRound(cx + U(10), cy + U(7), cx + U(51), cy + U(27), U(6), GetRValue(rankColor) / 3,
			GetGValue(rankColor) / 3, GetBValue(rankColor) / 3, 230);
		TbTextCenter(g_csFontSmall, cx + U(30), cy + U(17), g_csPxSmall, rankColor, rank);

		wchar_t name[48]{};
		wcsncpy(name, r.display[0] ? r.display : (r.name[0] ? r.name : L"?"), 47);
		name[47] = 0;
		const int av = U(22);
		const int ax = cx + U(58), ay = cy + U(5);
		TbFill(ax - 1, ay - 1, ax + av + 1, ay + av + 1, 255, 255, 255, 42);
		TbFill(ax, ay, ax + av, ay + av, 24, 28, 36, 255);
		int tex = r.acct ? TabAvatarTex(r.acct) : -1;
		if (tex < 0 && r.ch >= 0) {
			if (!quiet) {
				tex = TeamHudBindFace(r.ch, false);
				if (tex >= 0 && r.ch < 8) {
					g_csFaceTex[r.ch] = tex;
					g_csFaceEpoch = g_sktFontEpoch;
				}
			} else {
				tex = ChapStatsFaceTex(r.ch);
			}
		}
		if (tex >= 0) {
			SurfColor(255, 255, 255, 255);
			SurfDrawTextured(ax, ay, ax + av, ay + av, tex);
		} else if (r.ch >= 0) {
			TbFill(ax, ay, ax + av, ay + av, GetRValue(charColor) / 2,
				GetGValue(charColor) / 2, GetBValue(charColor) / 2, 255);
			TbTextCenter(g_csFontSmall, ax + av / 2, ay + av / 2, g_csPxSmall, cText, TabCharTag(r.ch));
		}

		const int scoreW = U(154);
		const int botTagW = r.bot ? U(38) + U(5) : 0;
		const int nameMax = cardW - U(70) - scoreW - U(30) - botTagW;
		int nameLen = (int)wcslen(name);
		while (nameLen > 1 && SurfTextWFont(g_csFontName, name) > nameMax) {
			--nameLen;
			name[nameLen - 1] = L'.';
			name[nameLen] = 0;
		}
		TbText(g_csFontName, cx + U(86), cy + U(17), g_csPxName, cText, name);
		if (r.bot)
			TbText(g_csFontSmall, cx + U(90) + SurfTextWFont(g_csFontName, name), cy + U(17), g_csPxSmall, cMuted, L"BOT");
		wchar_t score[32]{};
		if (g_optChapStatsScore) ChapStatsFormatScore(score, 32, ChapStatsDisplayScore(r, page));
		else swprintf_s(score, 32, L"%d", ChapStatsKills(r));
		const wchar_t* scoreLabel = ChapStatsDisplayScoreLabel(page);
		const int scoreRight = cx + cardW - U(12);
		const int scoreNumW = SurfTextWFont(g_csFontNum, score);
		const int scoreLabelW = SurfTextWFont(g_csFontSmall, scoreLabel);
		TbText(g_csFontSmall, scoreRight - scoreNumW - U(6) - scoreLabelW, cy + U(17),
			g_csPxSmall, cMuted, scoreLabel);
		TbTextRight(g_csFontNum, scoreRight, cy + U(17), g_csPxName, rankColor, score);

		const int metricRows = nCols > 0 ? (nCols + 3) / 4 : 1;
		const int actualCols = nCols < 4 ? nCols : 4;
		const COLORREF cLabel = RGB(208, 216, 230);
		const bool dense = shown > 8;
		const unsigned long valueFont = dense ? g_csFontSmall : g_csFontNum;
		const int valueFontPx = dense ? g_csPxSmall : g_csPxName;
		const int metricsTop = cy + U(34), metricsBottom = cy1 - U(5);
		const int cellGap = U(4), cellW = actualCols > 0
			? (cardW - U(20) - cellGap * (actualCols - 1)) / actualCols : cardW;
		const int cellH = (metricsBottom - metricsTop) / metricRows;
		for (int c = 0; c < nCols; ++c) {
			const int metricRow = c / 4, metricCol = c % 4;
			const int mx = cx + U(10) + metricCol * (cellW + cellGap);
			const int my = metricsTop + metricRow * cellH;
			const int value = ChapStatsValue(r, cols[c].id);
			const bool isBest = mark[c] && value == best[c]
				&& !(cols[c].id == kCsColHsRate && ChapStatsKills(r) < kCsRateMinKills);
			TbFill(mx, my, mx + cellW, my + U(1), 255, 255, 255, 24);
			TbFill(mx + cellW / 2 - U(10), my + U(2), mx + cellW / 2 + U(10), my + U(4),
				isBest ? aBr : aSr, isBest ? aBg : aSg, isBest ? aBb : aSb, isBest ? 255 : (value > 0 ? 150 : 70));
			TbTextCenter(g_csFontSmall, mx + cellW / 2, my + U(10), g_csPxSmall,
				isBest ? cBest : cLabel, UiText(cols[c].label, cols[c].zh));
			wchar_t valueText[24]{};
			ChapStatsFormatValue(valueText, 24, value, cols[c].id);
			TbTextCenter(valueFont, mx + cellW / 2, my + U(22), valueFontPx,
				isBest ? cBest : (value > 0 ? cText : cDim), valueText);
			if (cols[c].higher && value > 0 && best[c] > 0) {
				const int barX = mx + U(6), barW = cellW - U(12), barY = my + cellH - U(3);
				int fill = (int)((long long)barW * value / best[c]);
				if (fill > barW) fill = barW;
				TbFill(barX, barY, barX + barW, barY + U(2), 67, 76, 91, 165);
				if (fill > 0) TbFill(barX, barY, barX + fill, barY + U(2),
					isBest ? aBr : aSr, isBest ? aBg : aSg, isBest ? aBb : aSb, 225);
			}
		}
	}
	if (more > 0) {
		wchar_t t[64]{};
		swprintf_s(t, 64, UiText(UiId::ChapStatsMorePlayers, L"其余 %d 名玩家未显示"), more);
		TbTextCenter(g_csFontSmall, x0 + W / 2, y0 + H - U(5), g_csPxSmall, cDim, t);
	}
	return true;
}

static bool ChapStatsPaint(bool quiet) {
	if (ChapStatsPageCount() == 0) return false;
	const bool preview = HudMenuPage(kMenuPageChapStats) || HudMenuPage(kMenuPageChapStatsStyle)
		|| HudMenuPage(kMenuPageChapStatsSize) || HudMenuPage(kMenuPageChapStatsDisplay);
	const bool live = !quiet && (preview || g_csHeld);
	if (!quiet && !live) return false;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return false;
	if (!g_engine || !MenuEnsureSurf()) return false;
	// The snapshot also draws while connected but not in game and while the engine
	// draws the loading image (level change): colored rects, text with the fonts
	// built before the load, and already uploaded avatar textures only.
	const bool loading = EngDrawingLoading();
	const bool inGame = EngInGame();
	if (live && (loading || !inGame)) return false;
	if (quiet && !inGame && !EngConnected()) return false;
	// [6] 过图显示 only gates the settle snapshot, not hold-key / menu preview.
	if (quiet && g_chapStatsView == 2) return false;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 320 || sh < 240) return false;
	const DWORD now = GetTickCount();
	if (live && (!g_csRefreshAt || (LONG)(now - g_csRefreshAt) >= 1000)) {
		g_csRefreshAt = now;
		ChapStatsRefreshPlayers();
	}
	if (!quiet) TabAvatarUploadTick();
	const ChapStatsSet& S = live ? g_csLive : g_csSnap;
	const int setN = (S.n >= 0 && S.n <= kCsRecMax) ? S.n : 0;
	const DWORD base = live ? (preview ? 0u : g_csHeldAt) : g_csSnapAt;
	const DWORD elapsed = now - base;
	const int page = ChapStatsResolvePage(elapsed);

	int selfUid = 0;
	if (quiet && g_chapStatsView == 1) {
		const int local = EngLocal();
		PlayerInfo pi{};
		if (local > 0 && EngPlayerInfo(local, &pi)) selfUid = pi.userid;
	}

	// Rows: settle snapshot is already present-only. Live hold/preview still
	// drops absent empty rows, but keeps absent rows that scored this chapter.
	int idx[kCsRecMax];
	int total = 0, humans = 0, bots = 0;
	for (int i = 0; i < setN; ++i) {
		const ChapStatsRec& r = S.rec[i];
		if (!r.survivor) continue;
		if (quiet) {
			if (!r.present) continue;
		} else if (!r.present && !ChapStatsRecAny(r)) {
			continue;
		}
		if (g_chapStatsView == 1 && selfUid > 0 && r.userid != selfUid) continue;
		idx[total++] = i;
		if (r.bot) ++bots; else ++humans;
	}
	for (int i = 1; i < total; ++i) { // stable insertion sort: page score/kills, humans, userid
		const int key = idx[i];
		int j = i;
		while (j > 0) {
			const ChapStatsRec& a = S.rec[key];
			const ChapStatsRec& b = S.rec[idx[j - 1]];
			const int ka = ChapStatsScoreMetric(a, page);
			const int kb = ChapStatsScoreMetric(b, page);
			const bool before = ka != kb ? ka > kb : (a.bot != b.bot ? !a.bot : a.userid < b.userid);
			if (!before) break;
			idx[j] = idx[j - 1];
			--j;
		}
		idx[j] = key;
	}
	const int maxRows = g_chapStatsMaxRows <= 4 ? 4 : (g_chapStatsMaxRows <= 8 ? 8 : (g_chapStatsMaxRows <= 12 ? 12 : 16));
	const int shown = total < maxRows ? total : maxRows;
	const int more = total - shown;

	// Accuracy / headshot-accuracy RecvProps resolve but stay 0 on the client for the
	// whole chapter (server does not push live values). Keep Skeeto-computed HS kill rate.
	static const ChapStatsCol kPage0[] = {
		{ kCsCi, true, UiId::ChapStatsColCi, L"普感" },
		{ kCsColSiSum, true, UiId::ChapStatsColSi, L"特感" },
		{ kCsTank, true, UiId::ChapStatsColTank, L"坦克" },
		{ kCsWitch, true, UiId::ChapStatsColWitch, L"女巫" },
		{ kCsHs, true, UiId::ChapStatsColHs, L"爆头" },
		{ kCsColHsRate, true, UiId::ChapStatsColHsRate, L"爆头击杀率" },
	};
	static const ChapStatsCol kPageDmg[] = {
		{ kCsTankDmg, true, UiId::ChapStatsColTankDmg, L"坦克伤害" },
		{ kCsWitchDmg, true, UiId::ChapStatsColWitchDmg, L"女巫伤害" },
	};
	static const ChapStatsCol kPage1[] = {
		{ kCsSmoker, true, UiId::TabBoardZcSmoker, L"舌头" },
		{ kCsBoomer, true, UiId::TabBoardZcBoomer, L"胖子" },
		{ kCsHunter, true, UiId::TabBoardZcHunter, L"猎人" },
		{ kCsSpitter, true, UiId::TabBoardZcSpitter, L"口水" },
		{ kCsJockey, true, UiId::TabBoardZcJockey, L"猴子" },
		{ kCsCharger, true, UiId::TabBoardZcCharger, L"牛" },
	};
	static const ChapStatsCol kPage2[] = {
		{ kCsPinned, false, UiId::ChapStatsColPinned, L"被控" },
		{ kCsIncap, false, UiId::ChapStatsColIncap, L"倒地" },
		{ kCsDeath, false, UiId::ChapStatsColDeath, L"死亡" },
		{ kCsRevive, true, UiId::ChapStatsColRevive, L"救起" },
		{ kCsDefib, true, UiId::ChapStatsColDefib, L"电击" },
		{ kCsHeal, true, UiId::ChapStatsColHeal, L"治疗队友" },
		{ kCsRescue, true, UiId::ChapStatsColRescue, L"解控" },
		{ kCsFfDamage, false, UiId::ChapStatsColFfDamage, L"黑枪" },
		{ kCsFfDamageTaken, false, UiId::ChapStatsColFfDamageTaken, L"被黑" },
	};
	static const ChapStatsCol kPageSpec[] = {
		{ kCsMeleeSi, true, UiId::ChapStatsColMeleeSi, L"近战特感" },
		{ kCsSkeet, true, UiId::ChapStatsColSkeet, L"空爆" },
		{ kCsMeleeSkeet, true, UiId::ChapStatsColMeleeSkeet, L"近战空爆" },
		{ kCsCrownMelee, true, UiId::ChapStatsColCrownMelee, L"近战杀妹" },
		{ kCsTongueCut, true, UiId::ChapStatsColTongueCut, L"砍舌" },
		{ kCsChargerLevel, true, UiId::ChapStatsColChargerLevel, L"砍牛" },
	};
	const int kind = ChapStatsPageKind(page);
	const ChapStatsCol* cols = kPage0;
	int nCols = 6;
	if (kind == kCsKindScore) {
		static ChapStatsCol scoreBuf[8];
		int sn = 0;
		scoreBuf[sn++] = { kCsColScoreKills, true, UiId::ChapStatsColScoreKills, L"击杀分" };
		scoreBuf[sn++] = { kCsColScoreHs, true, UiId::ChapStatsColScoreHs, L"爆头加分" };
		if (g_optChapStatsDmg) scoreBuf[sn++] = { kCsColScoreDmg, true, UiId::ChapStatsColScoreDmg, L"伤害分" };
		scoreBuf[sn++] = { kCsColScoreSupport, true, UiId::ChapStatsColScoreSupport, L"支援分" };
		scoreBuf[sn++] = { kCsColScorePenalty, true, UiId::ChapStatsColScorePenalty, L"惩罚" };
		if (g_optChapStatsSpecial) scoreBuf[sn++] = { kCsColScoreSpecial, true, UiId::ChapStatsColScoreSpecial, L"特殊加分" };
		if (g_chapStatsLayout < 2) scoreBuf[sn++] = { kCsColScoreTotal, true, UiId::ChapStatsColScoreTotal, L"总分" };
		cols = scoreBuf;
		nCols = sn;
	} else if (kind == kCsKindDmg) {
		cols = kPageDmg;
		nCols = 2;
	} else if (kind == kCsKindSi) {
		cols = kPage1;
		nCols = 6;
	} else if (kind == kCsKindTeam) {
		cols = kPage2;
		nCols = 9;
	} else if (kind == kCsKindSpec) {
		cols = kPageSpec;
		nCols = 6;
	} else {
		cols = kPage0;
		nCols = 6;
	}

	// Best value per column over every listed row (hidden overflow rows included).
	int best[9];
	bool mark[9];
	for (int c = 0; c < nCols; ++c) {
		best[c] = -1;
		mark[c] = false;
		int lo = 0x7fffffff, hi = -0x7fffffff - 1, eligible = 0;
		for (int i = 0; i < total; ++i) {
			const ChapStatsRec& r = S.rec[idx[i]];
			if (cols[c].id == kCsColHsRate && ChapStatsKills(r) < kCsRateMinKills) continue;
			const int v = ChapStatsValue(r, cols[c].id);
			if (v < 0 && !ChapStatsIsScoreCol(cols[c].id)) continue;
			++eligible;
			if (v < lo) lo = v;
			if (v > hi) hi = v;
		}
		if (eligible >= 2 && lo != hi) {
			best[c] = cols[c].higher ? hi : lo;
			mark[c] = true;
		}
	}

	if (g_chapStatsLayout == 1)
		return ChapStatsPaintCards(S, idx, shown, more, humans, bots, cols, nCols, best, mark,
			page, elapsed, quiet, live, inGame, loading, sw, sh);
	if (g_chapStatsLayout == 3)
		return ChapStatsPaintCardGrid(S, idx, shown, more, humans, bots, cols, nCols, best, mark,
			page, elapsed, quiet, live, inGame, loading, sw, sh);
	if (g_chapStatsLayout == 2)
		return ChapStatsPaintTactical(S, idx, shown, more, humans, bots, cols, nCols, best, mark,
			page, elapsed, quiet, live, inGame, loading, sw, sh);

	const int rowsD = shown > 0 ? shown : 1;
	const int tier = shown < 4 ? 0 : (shown <= 8 ? 1 : 2);
	const int rowD = tier == 2 ? 28 : (tier == 1 ? 38 : 48);
	const bool ranked = g_chapStatsLayout == 4;
	const bool arcade = g_chapStatsLayout == 4;
	const int kW = ranked ? 1240 : 940, kHead = 64, kColH = 34;
	const int designH = kHead + kColH + rowsD * rowD + (more > 0 ? 22 : 0) + 10;
	// Snapshot: keep clear of the stock transition header (res 0..60 of 480) and the
	// loading tip bar (res r65), in real pixels of this resolution.
	const int bandTop = quiet ? sh * 60 / 480 + sh / 60 : 0;
	const int bandBot = quiet ? sh * 415 / 480 - sh / 60 : sh;
	int sc = HudClampScale(g_chapStatsScale);
	{
		const int maxW = sw * 94 / 100;
		const int maxH = quiet ? (bandBot - bandTop) : sh * 90 / 100;
		const int wantW = HudScalePxPanel(kW, sc, g_optChapStatsResScale);
		if (wantW > maxW && wantW > 0) sc = sc * maxW / wantW;
		const int wantH = HudScalePxPanel(designH, sc, g_optChapStatsResScale);
		if (wantH > maxH && wantH > 0) sc = sc * maxH / wantH;
		const int fit = sc;
		sc = HudClampScale(sc);
		if (sc > fit && sc - kHudScaleStep >= kHudScaleMin) sc -= kHudScaleStep;
	}
	auto U = [&](int v) { return HudScalePxPanel(v, sc, g_optChapStatsResScale); };
	if (!ChapStatsEnsureFonts(sc, inGame && !loading)) return false;

	const int W = U(kW), H = U(designH);
	const int x0 = (sw - W) / 2;
	int y0;
	if (quiet) {
		y0 = bandTop + (bandBot - bandTop - H) / 2;
		if (y0 < bandTop) y0 = bandTop;
	} else {
		y0 = (sh - H) * 2 / 5;
		if (y0 < U(12)) y0 = U(12);
	}
	const int x1 = x0 + W, y1 = y0 + H;
	PanelStyleColors ps{};
	PanelStyleResolve(g_csStyle, &ps);
	const int aSr = ps.accR, aSg = ps.accG, aSb = ps.accB; // accent (teal by default)
	const int aBr = ps.hiR, aBg = ps.hiG, aBb = ps.hiB;    // best / local (amber by default)
	const COLORREF cText = ps.text;
	const COLORREF cMuted = RGB(138, 148, 166);
	const COLORREF cLabel = RGB(208, 216, 230);
	const COLORREF cDim = RGB(96, 104, 120);
	const COLORREF cBest = RGB(aBr, aBg, aBb);

	const int headH = U(kHead);
	PanelStyleDrawFrame(ps, x0, y0, x1, y1, U(8), y0 + headH);
	TbFill(x0 + U(8), y0, x1 - U(8), y0 + U(3), aSr, aSg, aSb, 255);

	// Header: title + campaign / chapter line; theme tabs on the right.
	{
		const wchar_t* title = live ? UiText(UiId::ChapStatsTitleLive, L"本章累计（实时）")
			: UiText(UiId::ChapStatsTitle, L"章节结算");
		TbText(g_csFontTitle ? g_csFontTitle : g_csFontName, x0 + U(20), y0 + U(24), g_csPxTitle, cText, title);
		wchar_t sub[224]{};
		ChapStatsPlaceLine(live, humans, bots, sub, 224);
		TbText(g_csFontSmall, x0 + U(20), y0 + U(48), g_csPxSmall, cMuted, sub);
		TbTextRight(g_csFontSmall, x1 - U(18), y0 + U(48), g_csPxSmall, cDim,
			UiText(UiId::ChapStatsPageHint, L"← → 翻页"));

		const wchar_t* tabs[kCsPagesMax]{};
		const int pageN = ChapStatsFillTabLabels(tabs, kCsPagesMax);
		int xr = x1 - U(18);
		const int cy = y0 + U(24), bh = U(22), pad = U(9);
		for (int t = pageN - 1; t >= 0; --t) {
			const int w = SurfTextWFont(g_csFontSmall, tabs[t]) + pad * 2;
			xr -= w;
			if (t == page) {
				TbFillRound(xr, cy - bh / 2, xr + w, cy - bh / 2 + bh, bh / 3, aSr, aSg, aSb, 220);
				TbText(g_csFontSmall, xr + pad, cy, g_csPxSmall, RGB(10, 24, 20), tabs[t]);
				if (g_csPageManual < 0) {
					const int pw = (int)((long long)w * (long long)(elapsed % ChapStatsPageMs()) / (long long)ChapStatsPageMs());
					TbFill(xr, cy + bh / 2 + U(3), xr + pw, cy + bh / 2 + U(5), aSr, aSg, aSb, 200);
				} else {
					TbFill(xr, cy + bh / 2 + U(3), xr + w, cy + bh / 2 + U(5), aBr, aBg, aBb, 180);
				}
			} else {
				TbFillRound(xr, cy - bh / 2, xr + w, cy - bh / 2 + bh, bh / 3, 60, 66, 80, 200);
				TbText(g_csFontSmall, xr + pad, cy, g_csPxSmall, RGB(200, 206, 216), tabs[t]);
			}
			xr -= U(6);
		}
	}

	const int xName = U(96), wName = U(240), xStats = U(360);
	const int scoreWidth = ranked ? U(112) : 0;
	const int barWidth = arcade ? U(210) : 0;
	const int barGap = arcade ? U(12) : 0;
	const int rightEdge = x1 - U(20);
	const int barX = arcade ? rightEdge - barWidth : 0;
	const int scoreRight = ranked ? rightEdge - barWidth - barGap : rightEdge;
	const int scoreX = ranked ? scoreRight - scoreWidth : rightEdge;
	const int dataRight = ranked ? scoreX - U(14) : rightEdge;
	int wStats = dataRight - (x0 + xStats);
	if (wStats < U(1)) wStats = U(1);
	const int colW = nCols > 0 ? wStats / nCols : wStats;
	auto colRight = [&](int c) { return x0 + xStats + colW * (c + 1) - U(10); };
	int barMetricMax = 0;
	if (arcade) {
		for (int i = 0; i < total; ++i) {
			const int value = ChapStatsDisplayScore(S.rec[idx[i]], page);
			if (i == 0 || value > barMetricMax) barMetricMax = value;
		}
	}
	int y = y0 + headH;
	{
		const int cy = y + U(kColH) / 2 + U(1);
		if (ranked) {
			TbTextCenter(g_csFontSmall, x0 + U(31), cy, g_csPxSmall, RGB(aSr, aSg, aSb), L"#");
		} else {
			TbFill(x0 + U(16), cy - U(7), x0 + U(19), cy + U(7), aSr, aSg, aSb, 255);
			TbText(g_csFontSmall, x0 + U(26), cy, g_csPxSmall, RGB(aSr, aSg, aSb),
				UiText(UiId::TabBoardGroupSurv, L"生还者"));
		}
		TbText(g_csFontName, x0 + xName, cy, g_csPxName, cLabel, UiText(UiId::TabBoardColName, L"名字"));
		for (int c = 0; c < nCols; ++c)
			TbTextRight(g_csFontName, colRight(c), cy, g_csPxName, cLabel, UiText(cols[c].label, cols[c].zh));
		if (ranked) {
			const wchar_t* scoreLabel = ChapStatsDisplayScoreLabel(page);
			TbTextRight(g_csFontName, scoreRight, cy, g_csPxName, RGB(aSr, aSg, aSb), scoreLabel);
		}
		TbFill(x0 + U(12), y + U(kColH) - 1, x1 - U(12), y + U(kColH), 255, 255, 255, 36);
		y += U(kColH);
	}
	const int rowH = U(rowD);
	const int avS = U(tier == 2 ? 20 : (tier == 1 ? 26 : 32));
	const int tagH = U(tier == 2 ? 16 : (tier == 1 ? 20 : 24));
	if (shown <= 0) {
		TbTextCenter(g_csFontName, (x0 + x1) / 2, y + rowH / 2, g_csPxName, cMuted,
			UiText(UiId::ChapStatsNoData, L"本章暂无统计数据"));
		y += rowH;
	}
	for (int i = 0; i < shown; ++i) {
		const ChapStatsRec& r = S.rec[idx[i]];
		const int ry0 = y, ry1 = y + rowH, cy = y + rowH / 2;
		const bool local = g_localUserId > 0 && r.userid == g_localUserId;
		if (local) {
			TbFill(x0 + U(8), ry0 + 1, x1 - U(8), ry1 - 1, aBr, aBg, aBb, 30);
			TbFill(x0 + U(8), ry0 + 1, x0 + U(11), ry1 - 1, aBr, aBg, aBb, 255);
		} else if (ps.zebra && (i & 1)) {
			TbFill(x0 + U(8), ry0 + 1, x1 - U(8), ry1 - 1, ps.rowR, ps.rowG, ps.rowB, ps.bgA);
		}
		if (ranked) {
			const int scoreBgRight = arcade ? barX - U(6) : x1 - U(10);
			TbFill(scoreX, ry0 + 1, scoreBgRight, ry1 - 1, aSr, aSg, aSb, local ? 40 : 24);
			wchar_t rankText[12]{};
			swprintf_s(rankText, 12, L"%d", i + 1);
			const COLORREF rc = i == 0 ? cBest : (i < 3 ? RGB(aSr, aSg, aSb) : cMuted);
			TbTextCenter(g_csFontNum, x0 + U(31), cy, g_csPxName, rc, rankText);
		} else {
			const COLORREF tc = TeamHudCharColor(r.ch);
			TbFillRound(x0 + U(16), cy - tagH / 2, x0 + U(46), cy - tagH / 2 + tagH, U(5),
				GetRValue(tc), GetGValue(tc), GetBValue(tc), 235);
			TbTextCenter(g_csFontSmall, x0 + U(31), cy, g_csPxSmall, RGB(255, 255, 255), TabCharTag(r.ch));
		}
		{
			const int ax = x0 + U(54), ay = cy - avS / 2;
			TbFill(ax - 1, ay - 1, ax + avS + 1, ay + avS + 1, 255, 255, 255, 40);
			TbFill(ax, ay, ax + avS, ay + avS, 30, 36, 46, 255);
			// Humans: Steam medium avatar. Bots: the same vgui/s_panel_* portrait
			// TAB / teammate HUD use. Quiet settle cannot bind materials, so the
			// ids must already be in g_csFaceTex (prefetch while in-game).
			int tex = r.acct ? TabAvatarTex(r.acct) : -1;
			if (tex < 0 && r.ch >= 0) {
				if (!quiet) {
					tex = TeamHudBindFace(r.ch, false);
					if (tex >= 0 && r.ch < 8) {
						g_csFaceTex[r.ch] = tex;
						g_csFaceEpoch = g_sktFontEpoch;
					}
				} else {
					tex = ChapStatsFaceTex(r.ch);
				}
			}
			if (tex >= 0) {
				SurfColor(255, 255, 255, 255);
				SurfDrawTextured(ax, ay, ax + avS, ay + avS, tex);
			} else if (r.ch >= 0) {
				const COLORREF tc = TeamHudCharColor(r.ch);
				TbFill(ax, ay, ax + avS, ay + avS, GetRValue(tc) / 2, GetGValue(tc) / 2, GetBValue(tc) / 2, 255);
				TbTextCenter(g_csFontName ? g_csFontName : g_csFontSmall, ax + avS / 2, cy,
					g_csPxName > 0 ? g_csPxName : g_csPxSmall, RGB(255, 255, 255), TabCharTag(r.ch));
			}
		}
		{
			ChapStatsRec& rw = const_cast<ChapStatsRec&>(r);
			if (rw.fitPx != g_csPxName) {
				// Measured once per font size; the snapshot keeps its own copy.
				rw.fitPx = g_csPxName;
				wcsncpy(rw.fit, rw.display[0] ? rw.display : (rw.name[0] ? rw.name : L"?"), 47);
				rw.fit[47] = 0;
				const int maxW = wName - (r.bot ? U(40) : 0);
				int len = (int)wcslen(rw.fit);
				while (len > 1 && SurfTextWFont(g_csFontName, rw.fit) > maxW) {
					--len;
					rw.fit[len - 1] = L'.';
					rw.fit[len] = 0;
				}
			}
			const COLORREF nc = local ? RGB(255, 226, 168) : (r.bot ? RGB(186, 194, 208) : cText);
			TbText(g_csFontName, x0 + xName, cy, g_csPxName, r.present ? nc : cDim, r.fit);
			if (r.bot) {
				const int nw = SurfTextWFont(g_csFontName, r.fit);
				const int bx = x0 + xName + nw + U(6), bh = U(16), bp = U(5);
				const int bw = SurfTextWFont(g_csFontSmall, L"BOT") + bp * 2;
				TbFillRound(bx, cy - bh / 2, bx + bw, cy - bh / 2 + bh, bh / 3, 70, 76, 90, 230);
				TbText(g_csFontSmall, bx + bp, cy, g_csPxSmall, RGB(210, 216, 226), L"BOT");
			}
		}
		for (int c = 0; c < nCols; ++c) {
			const int v = ChapStatsValue(r, cols[c].id);
			wchar_t t[16]{};
			ChapStatsFormatValue(t, 16, v, cols[c].id);
			const bool isBest = mark[c] && v == best[c]
				&& !(cols[c].id == kCsColHsRate && ChapStatsKills(r) < kCsRateMinKills);
			const int xr = colRight(c);
			const int tw = SurfTextWFont(g_csFontNum, t);
			if (isBest) {
				const int ph = U(tier == 2 ? 22 : 26), pp = U(8);
				TbFillRound(xr - tw - pp, cy - ph / 2, xr + pp, cy - ph / 2 + ph, ph / 3, aBr, aBg, aBb, 64);
			} else if (v > 0) {
				TbFill(xr - tw - U(4), cy + U(8), xr, cy + U(10), aSr, aSg, aSb, 90);
			}
			TbTextRight(g_csFontNum, xr, cy, g_csPxName, isBest ? cBest : (v > 0 ? cText : cDim), t);
		}
		if (ranked) {
			const int metric = ChapStatsDisplayScore(r, page);
			wchar_t metricText[24]{};
			if (g_optChapStatsScore) ChapStatsFormatScore(metricText, 24, metric);
			else swprintf_s(metricText, 24, L"%d", metric);
			const COLORREF mc = local ? cBest : (i == 0 ? RGB(aSr, aSg, aSb) : (metric != 0 ? cText : cDim));
			TbTextRight(g_csFontNum, scoreRight, cy, g_csPxName, mc, metricText);
			if (arcade) {
				const int bh = U(tier == 2 ? 11 : 14);
				const int by = cy - bh / 2;
				const int bw = barWidth;
				TbFillRound(barX, by, barX + bw, by + bh, bh / 2, 40, 49, 62, 220);
				int fill = 0;
				if (barMetricMax > 0 && metric > 0)
					fill = (int)((long long)bw * metric / barMetricMax);
				else if (metric == barMetricMax)
					fill = bw;
				if (fill < 0) fill = 0;
				if (fill > bw) fill = bw;
				if (fill > 0) {
					const COLORREF bc = i == 0 ? cBest : RGB(aSr, aSg, aSb);
					TbFillRound(barX, by, barX + fill, by + bh, bh / 2,
						GetRValue(bc), GetGValue(bc), GetBValue(bc), 235);
				}
			}
		}
		y += rowH;
	}
	if (more > 0) {
		wchar_t t[48]{};
		swprintf_s(t, 48, UiText(UiId::TabBoardMore, L"还有 %d 人"), more);
		TbText(g_csFontSmall, x0 + xName, y + U(11), g_csPxSmall, cDim, t);
		y += U(22);
	}
	return true;
}

static const wchar_t* ChapStatsScoreVictimName(int stat) {
	switch (stat) {
	case kCsSmoker: return UiText(UiId::TabBoardZcSmoker, L"舌头");
	case kCsBoomer: return UiText(UiId::TabBoardZcBoomer, L"胖子");
	case kCsHunter: return UiText(UiId::TabBoardZcHunter, L"猎人");
	case kCsSpitter: return UiText(UiId::TabBoardZcSpitter, L"口水");
	case kCsJockey: return UiText(UiId::TabBoardZcJockey, L"猴子");
	case kCsCharger: return UiText(UiId::TabBoardZcCharger, L"牛");
	case kCsTank: return UiText(UiId::ChapStatsColTank, L"坦克");
	case kCsWitch: return UiText(UiId::ChapStatsColWitch, L"女巫");
	default: return nullptr;
	}
}

static const wchar_t* ChapStatsScoreKillBonus(int detail) {
	switch (detail) {
	case kCsDetailMelee: return UiText(UiId::ChapStatsScoreBonusMelee, L"（近战）");
	case kCsDetailSkeet: return UiText(UiId::ChapStatsScoreBonusSkeet, L"（空爆）");
	case kCsDetailMeleeSkeet: return UiText(UiId::ChapStatsScoreBonusMeleeSkeet, L"（近战空爆）");
	case kCsDetailChargerLevel: return UiText(UiId::ChapStatsScoreBonusChargerLevel, L"（砍牛）");
	case kCsDetailCrownMelee: return UiText(UiId::ChapStatsScoreBonusCrownMelee, L"（近战杀妹）");
	default: return L"";
	}
}

static const wchar_t* ChapStatsScoreToastLabel(const ChapStatsScoreToast& toast, wchar_t* out, size_t cap) {
	if (toast.stat == kCsCi && toast.kind == kCsToastHeadshot)
		return UiText(UiId::ChapStatsScoreLabelCommonHeadshot, L"普感爆头击杀");
	if (toast.stat == kCsCi)
		return UiText(UiId::ChapStatsScoreLabelCommon, L"普通感染者击杀");
	if (toast.stat == kCsFfDamage)
		return UiText(UiId::ChapStatsScoreReasonFriendlyFire, L"黑枪伤害累计扣分");
	if (const wchar_t* victim = ChapStatsScoreVictimName(toast.stat)) {
		const bool headshot = toast.kind == kCsToastHeadshot;
		swprintf_s(out, cap,
			UiText(headshot ? UiId::ChapStatsScoreSiHeadshotFmt : UiId::ChapStatsScoreSiKillFmt,
				headshot ? L"爆头击杀%s" : L"击杀%s"), victim);
		wcsncat_s(out, cap, ChapStatsScoreKillBonus(toast.detail), _TRUNCATE);
		return out;
	}
	switch (toast.stat) {
	case kCsRevive: return UiText(UiId::ChapStatsScoreReasonRevive, L"扶起倒地队友");
	case kCsDefib: return UiText(UiId::ChapStatsScoreReasonDefib, L"电击复活队友");
	case kCsHeal: return UiText(UiId::ChapStatsScoreReasonHeal, L"治疗队友");
	case kCsRescue:
		switch (toast.detail) {
		case kCsDetailSmoker: return UiText(UiId::ChapStatsScoreRescueSmoker, L"解救被舌头控制的队友");
		case kCsDetailHunter: return UiText(UiId::ChapStatsScoreRescueHunter, L"解救被猎人扑倒的队友");
		case kCsDetailJockey: return UiText(UiId::ChapStatsScoreRescueJockey, L"解救被猴子骑乘的队友");
		case kCsDetailChargerPummel: return UiText(UiId::ChapStatsScoreRescueCharger, L"解救被牛控制的队友");
		default: return UiText(UiId::ChapStatsScoreReasonRescue, L"解救被控队友");
		}
	case kCsPinned:
		switch (toast.detail) {
		case kCsDetailSmoker: return UiText(UiId::ChapStatsScorePinnedSmoker, L"被舌头抓住");
		case kCsDetailHunter: return UiText(UiId::ChapStatsScorePinnedHunter, L"被猎人扑倒");
		case kCsDetailJockey: return UiText(UiId::ChapStatsScorePinnedJockey, L"被猴子骑乘");
		case kCsDetailChargerPummel: return UiText(UiId::ChapStatsScorePinnedChargerPummel, L"被牛殴打");
		default: return UiText(UiId::ChapStatsScoreReasonPinned, L"被特感控制");
		}
	case kCsIncap: return UiText(UiId::ChapStatsScoreReasonIncap, L"倒地");
	case kCsDeath: return UiText(UiId::ChapStatsScoreReasonDeath, L"死亡");
	case kCsTongueCut: return UiText(UiId::ChapStatsScoreReasonTongueCut, L"砍断舌头");
	case kCsMeleeSi: return UiText(UiId::ChapStatsScoreReasonMeleeSi, L"近战击杀特感");
	case kCsSkeet: return UiText(UiId::ChapStatsScoreReasonSkeet, L"空爆特感");
	case kCsMeleeSkeet: return UiText(UiId::ChapStatsScoreReasonMeleeSkeet, L"近战空爆特感");
	case kCsCrownMelee: return UiText(UiId::ChapStatsScoreReasonCrownMelee, L"近战杀妹");
	case kCsChargerLevel: return UiText(UiId::ChapStatsScoreReasonChargerLevel, L"砍牛");
	default: return UiText(UiId::ChapStatsScoreLabelSpecial, L"评分变化");
	}
}

static void ChapStatsScoreToastColor(int kind, int* r, int* g, int* b) {
	*r = 97; *g = 243; *b = 255;
	switch (kind) {
	case kCsToastSi: *r = 255; *g = 154; *b = 102; break;
	case kCsToastHeadshot: *r = 199; *g = 144; *b = 255; break;
	case kCsToastRevive: *r = 135; *g = 239; *b = 145; break;
	case kCsToastSupport: *r = 101; *g = 218; *b = 227; break;
	case kCsToastPenalty: *r = 255; *g = 97; *b = 114; break;
	case kCsToastSpecial: *r = 255; *g = 121; *b = 215; break;
	default: break;
	}
}

// Game/Paint thread only. Event path supplies bounded score deltas.
// Match kill-feed non-local rows: soft glass body, no opaque backdrop, no left color bar.
static void ChapStatsScoreHudNudgeScreen(int dx, int dy) {
	if (!dx && !dy) return;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 320 || sh < 240) return;
	const int sc = HudClampScale(g_chapStatsScoreHudScale);
	const auto U = [&](int v) { return HudScalePxPanel(v, sc, g_optChapStatsResScale); };
	const int panelW = U(340);
	const int panelH = U(42) + 4 * (U(34) + U(5));
	const int minX = U(8), minY = U(8);
	const int maxX = (sw - U(8) - panelW > minX) ? sw - U(8) - panelW : minX;
	const int maxY = (sh - U(8) - panelH > minY) ? sh - U(8) - panelH : minY;
	if (!g_chapStatsScoreHudAbs) {
		g_chapStatsScoreHudOffX = sw * 70 / 100;
		g_chapStatsScoreHudOffY = sh * 31 / 100;
		g_chapStatsScoreHudAbs = true;
	}
	g_chapStatsScoreHudOffX = PsClamp(g_chapStatsScoreHudOffX + dx, minX, maxX);
	g_chapStatsScoreHudOffY = PsClamp(g_chapStatsScoreHudOffY + dy, minY, maxY);
	g_settingsDirty = true;
	g_settingsSaveAt = GetTickCount() + 400u;
}

static void ChapStatsScoreHudPaint() {
	const bool preview = HudMenuPage(kMenuPageChapStatsScoreHud);
	const bool active = g_optChapStatsScoreHud && g_optChapStats && g_optChapStatsScore;
	const bool peer = HudLayoutPeer(active, kMenuPageChapStatsScoreHud);
	if (!active) ChapStatsScoreHudClear();
	if ((!active && !preview) || HudCustomHidden() || !g_run.load(std::memory_order_relaxed)
		|| !SkeetoFeaturesOn() || !g_engine || !EngInGame() || EngDrawingLoading()) {
		if (!preview) ChapStatsScoreHudClear();
		return;
	}
	if (g_menuVisible && !g_menuParked && !preview && !peer) return;
	if (!MenuEnsureSurf()) return;
	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 320 || sh < 240) return;
	const int sc = HudClampScale(g_chapStatsScoreHudScale);
	if (!ChapStatsScoreHudEnsureFonts(sc, true)) return;
	const auto U = [&](int v) { return HudScalePxPanel(v, sc, g_optChapStatsResScale); };
	const int panelW = U(340), totalH = U(42), rowH = U(34), gap = U(5);
	const int stackH = totalH + 4 * (rowH + gap);
	int x = 0, y = 0;
	if (g_chapStatsScoreHudAbs) {
		HudPlaceAbs(sw, sh, panelW, stackH, g_chapStatsScoreHudOffX, g_chapStatsScoreHudOffY, &x, &y);
	} else {
		x = sw * 70 / 100;
		y = sh * 31 / 100;
	}
	const int minX = U(8), minY = U(8);
	const int maxX = (sw - U(8) - panelW > minX) ? sw - U(8) - panelW : minX;
	const int maxY = (sh - U(8) - stackH > minY) ? sh - U(8) - stackH : minY;
	x = PsClamp(x, minX, maxX);
	y = PsClamp(y, minY, maxY);
	const DWORD now = GetTickCount();
	int write = 0;
	for (int i = 0; i < g_csScoreToastN && i < kCsScoreToastMax; ++i) {
		if ((DWORD)(now - g_csScoreToast[i].born) >= kCsScoreToastLifeMs) continue;
		g_csScoreToast[write++] = g_csScoreToast[i];
	}
	g_csScoreToastN = write;
	int total = 0;
	const int n = (g_csLive.n >= 0 && g_csLive.n <= kCsRecMax) ? g_csLive.n : 0;
	for (int i = 0; i < n; ++i) {
		if (g_localUserId > 0 && g_csLive.rec[i].userid == g_localUserId) {
			total = ChapStatsScoreTotal(g_csLive.rec[i]);
			break;
		}
	}
	const int alpha = 230;
	const int totalY = y;
	KillFeedDrawGlass(x, totalY, panelW, totalH, alpha * 148 / 255);
	TbText(g_csScoreFontSmall, x + U(14), totalY + totalH / 2, g_csScorePxSmall,
		RGB(231, 235, 244), UiText(UiId::ChapStatsScoreTotal, L"本章总分"));
	wchar_t totalText[32]{};
	ChapStatsFormatScore(totalText, 32, total);
	TbTextRight(g_csScoreFontNum, x + panelW - U(14), totalY + totalH / 2, g_csScorePxNum,
		RGB(255, 207, 105), totalText);
	const int show = g_csScoreToastN < 4 ? g_csScoreToastN : 4;
	for (int row = 0; row < show; ++row) {
		const ChapStatsScoreToast& toast = g_csScoreToast[g_csScoreToastN - 1 - row];
		const DWORD age = now - toast.born;
		int fade = 255;
		if (age < 140) fade = (int)(255u * age / 140u);
		else if (age > kCsScoreToastLifeMs - 400)
			fade = (int)(255u * (kCsScoreToastLifeMs - age) / 400u);
		if (fade < 8) continue;
		int cr = 0, cg = 0, cb = 0;
		ChapStatsScoreToastColor(toast.kind, &cr, &cg, &cb);
		if (toast.delta < 0) { cr = 255; cg = 97; cb = 114; }
		const int slide = age < 140 ? U(12) * (140 - (int)age) / 140 : 0;
		const int rx = x + slide;
		const int ry = totalY + totalH + gap + row * (rowH + gap);
		KillFeedDrawGlass(rx, ry, panelW, rowH, fade * 148 / 255);
		wchar_t label[64]{};
		TbText(g_csScoreFontSmall, rx + U(14), ry + rowH / 2, g_csScorePxSmall,
			RGB(235, 238, 246), ChapStatsScoreToastLabel(toast, label, 64));
		wchar_t deltaText[32]{};
		ChapStatsFormatScore(deltaText, 32, toast.delta, true);
		TbTextRight(g_csScoreFontNum, rx + panelW - U(14), ry + rowH / 2, g_csScorePxNum,
			RGB(cr, cg, cb), deltaText);
	}
}

// =============================================================================
// Edit-keys list Skeeto section (menu style page 2 [3]). Default ON (special case).
// A generated scripts/kb_act.lst (Skeeto section + the current list) in
// <game root>\skeeto_kbact sits at the head of the GAME search path (runtime only,
// no hook). Left 4 Neko's ReadFile detour still prepends its own section, so the
// final order is L4N > Skeeto > stock.
// Threads: engine filesystem calls (read original, add/remove/check search path)
// stay on the game thread and only run on state edges; the worker thread does the
// Win32 file write/delete only (KbActFile*), so Paint never touches the disk.
// =============================================================================
static bool g_kbSecApplied = false;   // our path mounted with a written file
static bool g_kbSecFileReady = false; // mount retries never rewrite a ready file
static bool g_kbSecWaiting = false;   // worker write in flight
static bool g_kbSecGaveUp = false;
static bool g_kbSecCleanPosted = false;
static int g_kbSecSig = -1;
static int g_kbSecFails = 0;
static int g_kbSecReaddLog = 4;
static DWORD g_kbSecNextAt = 0;
static std::atomic<int> g_kbSecReq{ 0 };    // game thread -> worker: 1 write, 2 delete
static std::atomic<int> g_kbSecResult{ 0 }; // worker -> game thread: 1 ok, -1 failed
static char g_kbSecJobDir[MAX_PATH];
static char g_kbSecJobData[65536];
static int g_kbSecJobLen = 0;

static void KbListSectionDir(char* out, size_t n) {
	SkeetoGameRoot(out, n);
	if (!out[0]) return;
	const size_t len = strlen(out);
	if (len + 16 >= n) {
		out[0] = 0;
		return;
	}
	strcat(out, "\\skeeto_kbact");
}

// Worker thread (existing MainThread loop): Win32 file IO only, no engine/VGUI.
static void KbListSectionWorkerPump() {
	const int req = g_kbSecReq.load(std::memory_order_acquire);
	if (req == 1) {
		const int r = KbActFileSync(g_kbSecJobDir, g_kbSecJobData, g_kbSecJobLen);
		g_kbSecResult.store(r > 0 ? 1 : -1, std::memory_order_relaxed);
		if (r == 1) Log("kb list: file written (%d bytes)", g_kbSecJobLen);
		g_kbSecReq.store(0, std::memory_order_release);
	} else if (req == 2) {
		if (KbActFileExists(g_kbSecJobDir)) {
			KbActFileDelete(g_kbSecJobDir);
			Log("kb list: Skeeto section files removed");
		}
		g_kbSecResult.store(1, std::memory_order_relaxed);
		g_kbSecReq.store(0, std::memory_order_release);
	}
}

static void KbListSectionBuild(char* out, int cap) {
	struct Item { const char* cmd; UiId id; const wchar_t* zh; };
	const Item items[] = {
		{ "skeeto_menu", UiId::KbSecMenu, L"打开 / 关闭 Skeeto 菜单" },
		{ "skeeto_nav", UiId::KbSecNav, L"小地图导航与物资显示 开 / 关" },
		{ "skeeto_nav_goal", UiId::KbSecNavGoal, L"切换导航安全屋候选；控制台可输入 auto 或编号" },
		{ "+skeeto_tab", UiId::KbSecTabSkeeto,
			L"TAB 单击显示 Skeeto 面板；双击显示原版计分板" },
		{ "+skeeto_tab_vanilla", UiId::KbSecTabVanilla,
			L"TAB 单击显示原版计分板；双击显示 Skeeto 面板" },
		{ "+skeeto_chapterstats", UiId::KbSecChapStats, L"按住查看本章统计（章节结算面板）" },
		{ "skeeto_spotlight", UiId::KbSecSpotlight, L"聚光灯夜视仪 开 / 关" },
		{ "skeeto_hud_toggle", UiId::KbSecHud, L"隐藏 / 显示 Skeeto 自定义 HUD" },
		{ "skeeto_world_hud_toggle", UiId::KbSecWorldHud, L"隐藏 / 显示 Skeeto 世界 HUD" },
		{ "skeeto_xhair_toggle", UiId::KbSecXhair, L"隐藏 / 显示 Skeeto 准星" },
		{ "skeeto_viewmodel_mirror", UiId::KbSecViewModelMirror, L"全局镜像反转 开 / 关" },
		{ "skeeto_acid_outline_toggle", UiId::KbSecAcid, L"口水范围轮廓 开 / 关" },
		{ "skeeto_supply_scan", UiId::KbSecSupplyScan, L"物资扫描，即Survivor Sense" },
		{ "skeeto_interact_scan", UiId::KbSecInteractScan, L"可交互物品扫描" },
		{ "skeeto_bug_teleport", UiId::KbSecBugTeleport, L"传送到最近无敌Bug点（仅本地服）" },
		{ "skt_cfg_next", UiId::KbSecCfgNext, L"下一个 Config Override 预设" },
		{ "skt_cfg_prev", UiId::KbSecCfgPrev, L"上一个 Config Override 预设" },
		{ "skeeto_background_toggle", UiId::KbSecBgToggle, L"主菜单背景引擎 开 / 关" },
		{ "skeeto_background_next", UiId::KbSecBgNext, L"切换下一个主菜单背景" },
		{ "skeeto_background_pause", UiId::KbSecBgPause, L"暂停 / 继续 MP4 主菜单背景" },
		{ "skeeto_ui_reload", UiId::KbSecUiReload, L"重载 Skeeto UI（字体 / 贴图）" },
		{ "skeeto_clear_datacache", UiId::KbSecClearCache, L"清理未锁定的 datacache 缓存" },
	};
	int o = snprintf(out, cap,
		"\"blank\"\t\t\"==========================\"\r\n"
		"\"blank\"\t\t\"Skeeto\"\r\n"
		"\"blank\"\t\t\"==========================\"\r\n");
	for (const Item& it : items) {
		if (o <= 0 || o >= cap - 8) break;
		char label[192]{};
		if (WideCharToMultiByte(CP_UTF8, 0, UiText(it.id, it.zh), -1, label, (int)sizeof(label), nullptr, nullptr) <= 0)
			strcpy(label, it.cmd);
		for (char* p = label; *p; ++p)
			if (*p == '"' || *p == '\r' || *p == '\n') *p = ' ';
		const int n = snprintf(out + o, (size_t)(cap - o), "\"%s\"\t\t\"%s\"\r\n", it.cmd, label);
		if (n <= 0 || n >= cap - o) break;
		o += n;
	}
}

static void KbListSectionTick() {
	const DWORD now = GetTickCount();
	if (!g_optKbListSection) {
		if (!g_kbSecApplied && !g_kbSecWaiting && g_kbSecCleanPosted) return;
		if (g_kbSecReq.load(std::memory_order_acquire) != 0) return; // job in flight
		char dir[MAX_PATH]{};
		KbListSectionDir(dir, sizeof(dir));
		if (dir[0] && g_kbSecApplied) FsKbActRemovePath(dir);
		g_kbSecApplied = false;
		g_kbSecFileReady = false;
		g_kbSecWaiting = false;
		g_kbSecSig = -1;
		g_kbSecFails = 0;
		g_kbSecGaveUp = false;
		g_kbSecNextAt = 0;
		if (dir[0]) {
			strcpy_s(g_kbSecJobDir, dir);
			g_kbSecReq.store(2, std::memory_order_release); // worker deletes if present
		}
		g_kbSecCleanPosted = true;
		return;
	}
	g_kbSecCleanPosted = false;
	if (g_kbSecGaveUp) return;
	if (g_kbSecWaiting) {
		if (g_kbSecReq.load(std::memory_order_acquire) != 0) return;
		g_kbSecWaiting = false;
		if (g_kbSecResult.load(std::memory_order_relaxed) != 1) {
			if (++g_kbSecFails >= 30) {
				g_kbSecGaveUp = true;
				Log("kb list: Skeeto section give up (write failed %d)", g_kbSecFails);
			}
			g_kbSecNextAt = now + 2000u;
			return;
		}
		g_kbSecFileReady = true;
		g_kbSecApplied = false;
		g_kbSecFails = 0;
		g_kbSecNextAt = 0;
	}
	if (g_kbSecNextAt && (LONG)(now - g_kbSecNextAt) < 0) return;
	if (g_paintLoading.load(std::memory_order_relaxed)) {
		g_kbSecNextAt = now + 1000u;
		return;
	}
	g_kbSecNextAt = now + 5000u;
	char dir[MAX_PATH]{};
	KbListSectionDir(dir, sizeof(dir));
	if (!dir[0]) {
		g_kbSecGaveUp = true;
		return;
	}
	const int sig = g_uiEnglish.load(std::memory_order_relaxed) ? 1 : 0;
	if (!g_kbSecFileReady || sig != g_kbSecSig) {
		if (g_kbSecReq.load(std::memory_order_acquire) != 0) {
			g_kbSecNextAt = now + 500u;
			return;
		}
		// State edge (startup / enable / language): read the current list
		// through the engine filesystem (our path removed first), compose, post write.
		char* orig = nullptr;
		int origLen = 0;
		const int r = FsKbActReadOriginal(dir, &orig, &origLen);
		g_kbSecApplied = false;
		g_kbSecFileReady = false;
		if (r < 0 || (r == 0 && ++g_kbSecFails >= 30)) {
			g_kbSecGaveUp = true;
			Log("kb list: Skeeto section give up r=%d fails=%d", r, g_kbSecFails);
			return;
		}
		if (r == 0) {
			g_kbSecNextAt = now + 2000u;
			return;
		}
		const unsigned char* ub = (const unsigned char*)orig;
		const bool bom = origLen >= 3 && ub[0] == 0xEF && ub[1] == 0xBB && ub[2] == 0xBF;
		int o = 0;
		const int cap = (int)sizeof(g_kbSecJobData);
		if (bom) {
			memcpy(g_kbSecJobData, ub, 3);
			o = 3;
		}
		KbListSectionBuild(g_kbSecJobData + o, cap - o);
		o += (int)strlen(g_kbSecJobData + o);
		const char* body = bom ? orig + 3 : orig;
		const int bodyLen = bom ? origLen - 3 : origLen;
		const bool fits = o + bodyLen <= cap;
		if (fits) {
			memcpy(g_kbSecJobData + o, body, (size_t)bodyLen);
			o += bodyLen;
		}
		free(orig);
		if (!fits) {
			g_kbSecGaveUp = true;
			Log("kb list: list too large (%d), give up", o + bodyLen);
			return;
		}
		strcpy_s(g_kbSecJobDir, dir);
		g_kbSecJobLen = o;
		g_kbSecSig = sig;
		g_kbSecResult.store(0, std::memory_order_relaxed);
		g_kbSecReq.store(1, std::memory_order_release);
		g_kbSecWaiting = true;
		return;
	}
	if (!g_kbSecApplied) {
		FsKbActAddPath(dir);
		g_kbSecApplied = FsKbActVerify(g_kbSecJobData, g_kbSecJobLen);
		if (!g_kbSecApplied) {
			FsKbActRemovePath(dir);
			g_kbSecGaveUp = true;
			return;
		}
		g_kbSecFails = 0;
		Log("kb list: Skeeto section mounted sig=%d", g_kbSecSig);
	}
	// Do not fight later addon mounts or repeatedly rebuild another mod's list.

}

static void SktUiRebindHudMats() {
	if (!g_surf || g_hudMatN <= 0) return;
	using SetFileFn = void(__thiscall*)(void*, int, const char*, int, bool);
	auto setFile = (SetFileFn)VGet(g_surf, kVmtSurfDrawSetTextureFile);
	if (!setFile || !IsExec((void*)setFile)) return;
	for (int i = 0; i < g_hudMatN; ++i) {
		HudMatCache& c = g_hudMat[i];
		if (c.id < 0 || !c.name[0]) continue;
		__try {
			setFile(g_surf, c.id, c.name, 0, false);
			c.rebind = false;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			c.probeMisses = 0;
			c.retry = true;
			c.rebind = false;
			c.id = -1;
			c.tw = 0;
			c.th = 0;
		}
	}
	HudMatRebuildHot();
}

static void SktUiRebindTexXhair() {
	if (!g_surf || g_texXhairId < 0 || !g_texXhairBound[0]) return;
	using SetFileFn = void(__thiscall*)(void*, int, const char*, int, bool);
	auto setFile = (SetFileFn)VGet(g_surf, kVmtSurfDrawSetTextureFile);
	if (!setFile || !IsExec((void*)setFile)) return;
	__try {
		setFile(g_surf, g_texXhairId, g_texXhairBound, 0, false);
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		g_texXhairId = -1;
		g_texXhairBound[0] = 0;
		g_texXhairW = g_texXhairH = 0;
	}
	g_texXhairMissingUntil = 0;
	g_texXhairProbeMisses = 0;
	g_texXhairProbeAt = 0;
}

// 0 fullscreen, 1 windowed, 2 borderless.
static int SktUiWindowedFlag() {
	HWND hwnd = (g_gameHwnd && IsWindow(g_gameHwnd)) ? g_gameHwnd : FindGameWindow();
	if (hwnd) {
		const LONG style = GetWindowLong(hwnd, GWL_STYLE);
		if (style & (WS_CAPTION | WS_THICKFRAME))
			return 1;
	}
	if (CmdLineHasFlag("-window") || CmdLineHasFlag("-sw"))
		return 1;
	if (CmdLineHasFlag("-noborder"))
		return 2;
	char root[MAX_PATH]{};
	SkeetoGameRoot(root, sizeof(root));
	if (!root[0]) return 0;
	char path[MAX_PATH]{};
	snprintf(path, sizeof(path), "%s\\left4dead2\\cfg\\video.txt", root);
	FILE* f = fopen(path, "rb");
	if (!f) {
		snprintf(path, sizeof(path), "%s\\cfg\\video.txt", root);
		f = fopen(path, "rb");
	}
	if (!f) return 0;
	char buf[2048]{};
	const size_t n = fread(buf, 1, sizeof(buf) - 1, f);
	fclose(f);
	buf[n < sizeof(buf) ? n : sizeof(buf) - 1] = 0;
	auto readQuoted01 = [](const char* key, const char* bufIn) -> int {
		const char* p = strstr(bufIn, key);
		if (!p) return -1;
		const char* end = p + 80;
		for (const char* s = p; s < end && *s; ++s) {
			if (s[0] == '"' && s[2] == '"' && (s[1] == '0' || s[1] == '1'))
				return s[1] - '0';
		}
		return -1;
	};
	const int fs = readQuoted01("setting.fullscreen", buf);
	const int nb = readQuoted01("setting.nowindowborder", buf);
	if (fs == 1) return 0;
	if (nb == 1) return 2;
	if (fs == 0) return 1;
	return 0;
}

