static void MenuAdjustSupplyScan(int dir) {
	if (!g_menuVisible || g_menuPage != kMenuPageSupplyScan) return;
	if (g_supplyScanSel < 0 || g_supplyScanSel >= SupplyScanMenuCount()) return;
	const int step = dir < 0 ? -1 : 1;
	switch (kSupplyScanMenuItems[g_supplyScanSel].action) {
	case SupplyScanMenuAction::AdjustRadius: {
		const int next = ClampAdd(g_supplyScanRadius, step * 200, 400, 3200);
		if (next == g_supplyScanRadius) return;
		g_supplyScanRadius = next;
		break;
	}
	case SupplyScanMenuAction::AdjustHold: {
		const int next = ClampAdd(g_supplyScanHoldSec, step, 1, 15);
		if (next == g_supplyScanHoldSec) return;
		g_supplyScanHoldSec = next;
		break;
	}
	case SupplyScanMenuAction::AdjustLimit: {
		const int next = ClampAdd(g_supplyScanSlotLimit, step * 32, kSupplyScanSlotMin, kSupplyScanSlotMax);
		if (next == g_supplyScanSlotLimit) return;
		g_supplyScanSlotLimit = next;
		break;
	}
	case SupplyScanMenuAction::ColorHealth:
	case SupplyScanMenuAction::ColorAmmo:
	case SupplyScanMenuAction::ColorThrow:
	case SupplyScanMenuAction::ColorWeapon: {
		const int which = (int)kSupplyScanMenuItems[g_supplyScanSel].action - (int)SupplyScanMenuAction::ColorHealth;
		const int next = CycleWrapDir(g_supplyScanColor[which], 0, 7, step);
		if (next == g_supplyScanColor[which]) return;
		g_supplyScanColor[which] = next;
		break;
	}
	default:
		return;
	}
	SaveSettings();
	EngClientCmd("play buttons/button14");
}

static void MenuAdjustStaticCrosshair(int dir) {
	if (!g_menuVisible || g_menuPage != kMenuPageStaticCrosshair) return;
	const int sel = StaticCrosshairActiveSel();
	if (sel < 0) return;
	const int step = dir < 0 ? -1 : 1;
	XhairTune& tune = XhairT();
	switch (kStaticCrosshairMenuItems[sel].action) {
	case StaticCrosshairMenuAction::CycleStyle: {
		const int next = CycleWrapDir(g_xhairStyle, 0, kXhairStyleCount - 1, step);
		if (next == g_xhairStyle) return;
		g_xhairStyle = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleColor: {
		const int next = CycleWrapDir(tune.color, 0, kXhairColorCount - 1, step);
		if (next == tune.color) return;
		tune.color = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleSize: {
		const int next = ClampAdd(tune.size, step * 10, 50, 200);
		if (next == tune.size) return;
		tune.size = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleLength: {
		const int next = ClampAdd(tune.length, step, 2, 24);
		if (next == tune.length) return;
		tune.length = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleGap: {
		const int next = ClampAdd(tune.gap, step, 0, 16);
		if (next == tune.gap) return;
		tune.gap = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleThick: {
		const int next = ClampAdd(tune.thick, step, 1, 8);
		if (next == tune.thick) return;
		tune.thick = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleDot: {
		const int next = ClampAdd(tune.dot, step, 0, 12);
		if (next == tune.dot) return;
		tune.dot = next;
		break;
	}
	case StaticCrosshairMenuAction::CycleOutline: {
		const int next = ClampAdd(tune.outline, step, 0, 4);
		if (next == tune.outline) return;
		tune.outline = next;
		break;
	}
	case StaticCrosshairMenuAction::AdjustAlpha: {
		const int next = ClampAdd(tune.alpha, step * kSfxVolStep, 10, 100);
		if (next == tune.alpha) return;
		tune.alpha = next;
		break;
	}
	default:
		return;
	}
	ClampXhair();
	SaveSettings();
	XhairNotifyChanged();
	XhairTick();
	EngClientCmd("play buttons/button14");
}

static void MenuAdjustRingCrosshair(int dir) {
	if (!g_menuVisible || g_menuPage != kMenuPageRingCrosshair) return;
	if (g_ringXhairSel < 0 || g_ringXhairSel >= (int)_countof(kRingCrosshairMenuItems)) return;
	const int step = dir < 0 ? -1 : 1;
	switch (kRingCrosshairMenuItems[g_ringXhairSel].action) {
	case RingCrosshairMenuAction::CycleColor:
		g_xhairRingColor = CycleWrapDir(g_xhairRingColor, 0, kXhairColorCount - 1, step);
		break;
	case RingCrosshairMenuAction::CycleMode:
		g_xhairRingMode = (g_xhairRingMode == 0) ? 2 : 0;
		break;
	case RingCrosshairMenuAction::CycleAlpha: {
		const int next = ClampAdd(g_xhairRingAlpha, step * 10, 10, 100);
		if (next == g_xhairRingAlpha) return;
		g_xhairRingAlpha = next;
		break;
	}
	default:
		return;
	}
	g_xhairHudMode = -1;
	ClampXhair();
	SaveSettings();
	XhairTick();
	EngClientCmd("play buttons/button14");
}

static void MenuAdjustTextureCrosshair(int dir) {
	if (!g_menuVisible || g_menuPage != kMenuPageTextureCrosshair) return;
	if (g_texXhairSel < 0 || g_texXhairSel >= (int)_countof(kTextureCrosshairMenuItems)) return;
	const int step = dir < 0 ? -1 : 1;
	switch (kTextureCrosshairMenuItems[g_texXhairSel].action) {
	case TextureCrosshairMenuAction::CycleMaterial: {
		TexXhairRememberCurrent();
		TexXhairRefreshList();
		if (g_texXhairCount <= 0) {
			Log("menu: xhairTex no materials (drop vmt into materials/skeeto/xhair/)");
			EngClientCmd("play buttons/button10");
			return;
		}
		int idx = TexXhairIndexOf(g_xhairTexMat);
		if (idx < 0) idx = 0;
		else idx = (idx + (step < 0 ? g_texXhairCount - 1 : 1)) % g_texXhairCount;
		strncpy(g_xhairTexMat, g_texXhairList[idx], sizeof(g_xhairTexMat) - 1);
		g_xhairTexMat[sizeof(g_xhairTexMat) - 1] = 0;
		g_texXhairBound[0] = 0;
		g_texXhairRecoveryBlockedMat[0] = 0;
		g_texXhairRecoveryCount = 0;
		g_texXhairCreateRetryAt = 0;
		g_texXhairCreateFailures = 0;
		TexXhairApplyCurrentOrDefault();
		ClampXhair();
		SaveSettings();
		Log("menu: xhairTexMat=%s (%d/%d) size=%d full=%d", g_xhairTexMat, idx + 1, g_texXhairCount,
			g_xhairTexSize, g_optXhairTexFull ? 1 : 0);
		EngClientCmd("play buttons/button14");
		return;
	}
	case TextureCrosshairMenuAction::CycleSize: {
		if (g_optXhairTexFull) return;
		const int next = ClampAdd(g_xhairTexSize, step * kTexXhairSizeStep, kTexXhairSizeMin, kTexXhairSizeMax);
		if (next == g_xhairTexSize) return;
		g_xhairTexSize = next;
		ClampXhair();
		SaveSettings();
		Log("menu: xhairTexSize=%d", g_xhairTexSize);
		EngClientCmd("play buttons/button14");
		return;
	}
	default:
		return;
	}
}

