static bool MenuKeyEdge(int vk, bool* prev) {
	const bool down = (GetAsyncKeyState(vk) & 0x8000) != 0;
	const bool fire = down && !*prev;
	*prev = down;
	return fire;
}

// Menu keys: Paint GetAsyncKeyState edges for UI (physical 0–9 / numpad / Esc / -/=).
// IN_KeyEvent (chained once) only *eats* those ButtonCodes while menu is open so
// slot* binds do not fire — does not replace this poll. GASK cost is tiny vs HUD draw.
// Direction keys nudge HUD; do not touch WASD.
static void MenuPollPaintKeys() {
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) {
		g_radarEditRequest.store(-1, std::memory_order_release); return;
	}
	if (!g_paintInGame.load(std::memory_order_relaxed)) g_radarEditRequest.store(-1, std::memory_order_release);
	if (!g_paintInGame.load(std::memory_order_relaxed)
		&& !g_mainUiInputReady.load(std::memory_order_acquire)) return;
	if (!g_gameHwnd || !IsWindow(g_gameHwnd))
		g_gameHwnd = FindGameWindow();
	HWND fg = GetForegroundWindow();
	if (!fg || !g_gameHwnd || fg != g_gameHwnd) {
		g_radarEditRequest.store(-1, std::memory_order_release);
		if (skeeto_nav::RadarEditing()) skeeto_nav::RadarEndEdit();
		if (skeeto_nav::Editing()) {
			skeeto_nav::EndEdit();
			g_settingsDirty = true;
			g_settingsSaveAt = GetTickCount() + 400u;
		}
		return;
	}

	const int radarRequest = g_radarEditRequest.load(std::memory_order_acquire);
	if (radarRequest >= 0 && (!g_optSupplyRadar || !g_paintInGame.load(std::memory_order_relaxed)
		|| g_menuVisible || HudCustomHidden() || !RadarMenuItemEnabled((unsigned)radarRequest)))
		g_radarEditRequest.store(-1, std::memory_order_release);
	else if (radarRequest >= 0 && !g_paintGameUiVisible.load(std::memory_order_relaxed) && !BackgroundConsoleOpen()) {
		g_radarEditRequest.store(-1, std::memory_order_release);
		skeeto_nav::RadarBeginEdit((unsigned)radarRequest);
	}
	static bool radarWasEditing = false;
	static bool confirm = false, cancel = false, chat = false, teamChat = false, console = false, bracket = false;
	if (skeeto_nav::RadarEditing()) {
		if (!radarWasEditing) {
			confirm = (GetAsyncKeyState(VK_RETURN) & 0x8000) != 0;
			cancel = (GetAsyncKeyState(VK_ESCAPE) & 0x8000) != 0;
			chat = (GetAsyncKeyState('Y') & 0x8000) != 0;
			teamChat = (GetAsyncKeyState('U') & 0x8000) != 0;
			console = (GetAsyncKeyState(VK_OEM_3) & 0x8000) != 0;
			bracket = (GetAsyncKeyState(VK_OEM_4) & 0x8000) != 0;
			radarWasEditing = true;
		}
		if (g_menuVisible || g_paintGameUiVisible.load(std::memory_order_relaxed)
			|| HudCustomHidden() || !g_paintInGame.load(std::memory_order_relaxed)) {
			skeeto_nav::RadarEndEdit(); return;
		}
		static const unsigned editKeys[] = {VK_LEFT,VK_RIGHT,VK_UP,VK_DOWN,VK_SHIFT,VK_OEM_MINUS,VK_OEM_PLUS,VK_SUBTRACT,VK_ADD,'R',VK_TAB};
		for (unsigned key : editKeys)
			skeeto_nav::RadarEditKey(key, (GetAsyncKeyState((int)key) & 0x8000) != 0);
		// Edits apply live and persist through the debounced settings save; every exit key only leaves edit mode.
		const bool confirmEdge = MenuKeyEdge(VK_RETURN, &confirm);
		if (MenuKeyEdge(VK_ESCAPE, &cancel) || MenuKeyEdge('Y', &chat)
			|| MenuKeyEdge('U', &teamChat) || MenuKeyEdge(VK_OEM_3, &console)
			|| (g_optForceMenuBind && MenuKeyEdge(VK_OEM_4, &bracket)) || confirmEdge) {
			skeeto_nav::RadarEndEdit(); RadarMenuChanged();
		}
		return;
	}
	radarWasEditing = false;
	if (skeeto_nav::Editing()) {
		static const unsigned editKeys[] = {VK_LEFT, VK_RIGHT, VK_UP, VK_DOWN, 'B', 'S'};
		for (unsigned key : editKeys)
			skeeto_nav::EditKey(key, (GetAsyncKeyState((int)key) & 0x8000) != 0);
		static bool exitEnter = false, exitEsc = false, exitTwo = false;
		static bool exitY = false, exitU = false, exitConsole = false;
		if (MenuKeyEdge(VK_RETURN, &exitEnter) || MenuKeyEdge(VK_ESCAPE, &exitEsc)
			|| MenuKeyEdge('2', &exitTwo) || MenuKeyEdge('Y', &exitY)
			|| MenuKeyEdge('U', &exitU) || MenuKeyEdge(VK_OEM_3, &exitConsole)) {
			skeeto_nav::EndEdit();
			g_settingsDirty = true;
			g_settingsSaveAt = GetTickCount() + 400u;
		}
		return;
	}

	static bool pOem4 = false, pEsc = false;
	static bool pDigit[10]{}, pNum[10]{};
	static bool pMinus = false, pPlus = false, pSub = false, pAdd = false;
	static bool pLeft = false, pRight = false;

	const bool bracketPressed = MenuKeyEdge(VK_OEM_4, &pOem4);
	if (g_optForceMenuBind && bracketPressed && GetTickCount() >= g_menuIgnoreOpenUntil) {
		if (GetTickCount() - g_menuCmdStamp >= 120)
			MenuToggle();
	}
	if (!g_optForceMenuBind) {
		const DWORD pendingAt = g_menuBracketPendingAt.load(std::memory_order_acquire);
		const DWORD now = GetTickCount();
		DWORD expected = pendingAt;
		if (pendingAt && now - pendingAt >= 80u
			&& g_menuBracketPendingAt.compare_exchange_strong(
				expected, 0u, std::memory_order_acq_rel)) {
			if (now - g_menuCmdStamp >= 120u)
				MenuToggle();
		}
	} else {
		g_menuBracketPendingAt.store(0, std::memory_order_release);
	}
	if (!g_menuVisible || g_menuParked)
		return;

	if (MenuKeyEdge(VK_ESCAPE, &pEsc)) MenuOnVk(VK_ESCAPE);
	static bool pluginRefreshKey=false;
	if(g_menuPage==kMenuPagePluginPage){if(MenuKeyEdge('R',&pluginRefreshKey))MenuOnVk('R');}
	else pluginRefreshKey=false;
	ViewModelHeldEditPump();
	const bool vmHeld = g_menuPage == kMenuPageViewModel;
	if (MenuKeyEdge(VK_OEM_MINUS, &pMinus) && !vmHeld) MenuOnVk(VK_OEM_MINUS);
	if (MenuKeyEdge(VK_OEM_PLUS, &pPlus) && !vmHeld) MenuOnVk(VK_OEM_PLUS);
	if (MenuKeyEdge(VK_SUBTRACT, &pSub) && !vmHeld) MenuOnVk(VK_SUBTRACT);
	if (MenuKeyEdge(VK_ADD, &pAdd) && !vmHeld) MenuOnVk(VK_ADD);
	// </> 翻页：仅多子页页生效。HUD 编辑页方向键留给挪 HUD。
	if (MenuPageSubCount(g_menuPage) > 1) {
		if (MenuKeyEdge(VK_LEFT, &pLeft))  MenuSubTurn(-1);
		if (MenuKeyEdge(VK_RIGHT, &pRight)) MenuSubTurn(+1);
	} else {
		MenuKeyEdge(VK_LEFT, &pLeft);
		MenuKeyEdge(VK_RIGHT, &pRight);
	}
	for (int d = 0; d < 10; ++d) {
		if (MenuKeyEdge('0' + d, &pDigit[d])) MenuOnVk((DWORD)('0' + d));
		if (MenuKeyEdge(VK_NUMPAD0 + d, &pNum[d])) MenuOnVk((DWORD)(VK_NUMPAD0 + d));
	}
}

static void MenuTickElimNudge() {
	static DWORD start = 0;
	static DWORD last = 0;
	const bool elim = g_menuPage == kMenuPageElimHud;
	const bool clock = g_menuPage == kMenuPageWorldClock;
	const bool chatPosition = g_menuPage == kMenuPageChatUiPosition;
	const bool speed = g_menuPage == kMenuPageSpeed;
	const bool timer = g_menuPage == kMenuPageRoundTimer;
	const bool team = g_menuPage == kMenuPageTeamHealth;
	const bool dirhud = g_menuPage == kMenuPageDirectorHud;
	const bool ammo = g_menuPage == kMenuPageExtraAmmoHud;
	const bool itemhud = g_menuPage == kMenuPageItemHud;
	const bool maphud = g_menuPage == kMenuPageMapProgressHud;
	const bool caphud = g_menuPage == kMenuPageControlHud;
	const bool revhud = g_menuPage == kMenuPageRescueProgressHud;
	const bool tanktargethud = g_menuPage == kMenuPageTankTargetHud;
	const bool damageSourceHud = g_menuPage == kMenuPageDamageSourceHud;
	const bool friendlyFireHud = g_menuPage == kMenuPageFriendlyFireHud;
	const bool siAggroHud = g_menuPage == kMenuPageSiAggroHud;
	const bool witchRageHud = g_menuPage == kMenuPageWitchRageHud;
	const bool bossDmgBoardHud = g_menuPage == kMenuPageBossDmgBoardHud;
	const bool igniteHud = g_menuPage == kMenuPageIgniteHud;
	const bool witchHpHud = g_menuPage == kMenuPageWitchHpHud;
	const bool interacthud = g_menuPage == kMenuPageInteractHud;
	const bool ammoseg = g_menuPage == kMenuPageAmmoGfxHud && g_ammoGfxStyle == 1;
	const bool adrenhud = g_menuPage == kMenuPageAdrenalineHud;
	const bool shovehud = g_menuPage == kMenuPageShoveHud;
	const bool firegate = g_menuPage == kMenuPageFireGateHud;
	const bool hazhud = g_menuPage == kMenuPageHazardHud;
	const bool finale = g_menuPage == kMenuPageFinaleHud;
	const bool lastnotice = g_menuPage == kMenuPageLastMusic && g_lastMusicAdjustSel==2;
	const bool tanknotice = g_menuPage == kMenuPageTankSpawnNotice;
	const bool dirphase = g_menuPage == kMenuPageDirectorPhaseHud;
	const bool routeprogress = g_menuPage == kMenuPageRouteProgressHud;
	const bool killstreak = g_menuPage == kMenuPageKillStreakHud;
	const bool netgraphhud = g_menuPage == kMenuPageNetGraphHud;
	const bool memoryhud = g_menuPage == kMenuPageMemoryHud;
	const bool cachehud = g_optCacheOffload && g_menuPage == kMenuPageCacheOffload;
	const bool sipresencehud = g_menuPage == kMenuPageSiPresenceHud;
	const bool throwhud = g_menuPage == kMenuPageThrowNoticeHud;
	const bool voicehud = g_menuPage == kMenuPageVoiceHud;
	const bool upgradeammohud = g_menuPage == kMenuPageUpgradeAmmoHud;
	const bool bwselfhud = g_menuPage == kMenuPageBwSelfHud;
	const bool killfeed = g_menuPage == kMenuPageKillFeed;
	const bool matealert = g_menuPage == kMenuPageMateLast || g_menuPage == kMenuPageMateLow || g_menuPage == kMenuPageMateSave;
	const bool witchstartle = g_menuPage == kMenuPageWitchStartleHud;
	const bool laserround = g_menuPage == kMenuPageLaserRoundNotice;
	const bool supplyhud = g_menuPage == kMenuPageSupplyScanHud;
	const bool localdirector = g_menuPage == kMenuPageLocalDirector;
	const bool tankrock = g_menuPage == kMenuPageTankRockNotice;
	const bool siwarn = g_menuPage == kMenuPageSiWarningHud;
	const bool tonguecut = g_menuPage == kMenuPageTongueCutHud;
	const bool scorehud = g_menuPage == kMenuPageChapStatsScoreHud;
	const bool overlayhud = OverlayHudEditPage(g_menuPage);
	if (!g_menuVisible || g_menuParked || (!elim && !clock && !chatPosition && !speed && !timer && !team && !dirhud && !ammo && !itemhud && !maphud && !caphud && !revhud && !tanktargethud && !damageSourceHud && !friendlyFireHud && !siAggroHud && !witchRageHud && !bossDmgBoardHud && !igniteHud && !witchHpHud && !adrenhud && !shovehud && !firegate && !hazhud && !finale && !tanknotice && !lastnotice && !dirphase && !routeprogress && !killstreak && !netgraphhud && !memoryhud && !cachehud && !sipresencehud && !throwhud && !voicehud && !upgradeammohud && !bwselfhud && !killfeed && !matealert && !witchstartle && !laserround && !supplyhud && !tankrock && !siwarn && !tonguecut && !interacthud && !ammoseg && !scorehud && !overlayhud && !localdirector)) {
		start = 0;
		return;
	}
	int dx = 0, dy = 0;
	if (GetAsyncKeyState(VK_UP) & 0x8000) dy -= 1;
	if (GetAsyncKeyState(VK_DOWN) & 0x8000) dy += 1;
	if (GetAsyncKeyState(VK_LEFT) & 0x8000) dx -= 1;
	if (GetAsyncKeyState(VK_RIGHT) & 0x8000) dx += 1;
	if (!dx && !dy) {
		start = 0;
		return;
	}
	const int step = (GetAsyncKeyState(VK_SHIFT) & 0x8000) ? 32 : 8;
	const DWORD now = GetTickCount();
	auto apply = [&]() {
		if (chatPosition) NativeUiMenuNudge(dx,dy,step==32);
		else if (clock) ClockNudgeScreen(dx * step, dy * step);
		else if (speed) SpeedNudgeScreen(dx * step, dy * step);
		else if (timer) TimerNudgeScreen(dx * step, dy * step);
		else if (team) TeamHudNudgeScreen(dx * step, dy * step);
		else if (dirhud) DirHudNudgeScreen(dx * step, dy * step);
		else if (ammo) AmmoHudNudgeScreen(dx * step, dy * step);
		else if (itemhud) ItemHudNudgeScreen(dx * step, dy * step);
		else if (maphud) MapHudNudgeScreen(dx * step, dy * step);
		else if (caphud) CapHudNudgeScreen(dx * step, dy * step);
		else if (revhud) ReviveHudNudgeScreen(dx * step, dy * step);
		else if (tanktargethud) TankTargetHudNudgeScreen(dx * step, dy * step);
		else if (damageSourceHud) DamageSourceHudNudgeScreen(dx * step, dy * step);
		else if (friendlyFireHud) FriendlyFireHudNudgeScreen(dx * step, dy * step);
		else if (siAggroHud) SiAggroHudNudgeScreen(dx * step, dy * step);
		else if (witchRageHud) WitchRageHudNudgeScreen(dx * step, dy * step);
		else if (bossDmgBoardHud) BossDmgBoardNudgeScreen(dx * step, dy * step);
		else if (igniteHud) IgniteHudNudgeScreen(dx * step, dy * step);
		else if (witchHpHud) WitchHpHudNudgeScreen(dx * step, dy * step);
		else if (interacthud) InteractHudNudgeScreen(dx * step, dy * step);
		else if (ammoseg) { AmmoSegHudNudgeScreen(dx * step, dy * step); ClampAmmoSegHud(); SaveSettings(); }
		else if (overlayhud) {
			int& x = g_menuPage == kMenuPageOverlayAmmo ? g_ammoArcOverlayOffX : g_menuPage == kMenuPageOverlayReload ? g_reloadRingOverlayOffX : g_fireGateOverlayOffX;
			int& y = g_menuPage == kMenuPageOverlayAmmo ? g_ammoArcOverlayOffY : g_menuPage == kMenuPageOverlayReload ? g_reloadRingOverlayOffY : g_fireGateOverlayOffY;
			x = ClampAdd(x, dx * step, -4096, 4096);
			y = ClampAdd(y, dy * step, -4096, 4096);
			SaveSettings();
		}
		else if (adrenhud) AdrenHudNudgeScreen(dx * step, dy * step);
		else if (shovehud) ShoveHudNudgeScreen(dx * step, dy * step);
		else if (firegate) FireGateHudNudgeScreen(dx * step, dy * step);
		else if (hazhud) HazHudNudgeScreen(dx * step, dy * step);
		else if (finale) FinaleHudNudgeScreen(dx * step, dy * step);
		else if (tanknotice) TankNoticeHudNudgeScreen(dx * step, dy * step);
		else if (lastnotice) HudNudgeAbs(&g_lastMusicHudAbs,&g_lastMusicHudX,&g_lastMusicHudY,4,dx * step,dy * step);
		else if (dirphase) DirectorPhaseHudNudgeScreen(dx * step, dy * step);
		else if (localdirector) LocalDirectorNudgeScreen(dx * step, dy * step);
		else if (routeprogress) HudNudgeAbs(&g_routeProgressAbs, &g_routeProgressX, &g_routeProgressY, 4, dx * step, dy * step);
		else if (killstreak) KillStreakHudNudgeScreen(dx * step, dy * step);
		else if (netgraphhud) NetGraphHudNudgeScreen(dx * step, dy * step);
		else if (memoryhud) MemoryHudNudgeScreen(dx * step, dy * step);
		else if (cachehud) HudNudgeAbs(&g_cacheHudAbs, &g_cacheHudOffX, &g_cacheHudOffY,
			g_cacheHudAlign, dx * step, dy * step);
		else if (sipresencehud) SiPresenceHudNudgeScreen(dx * step, dy * step);
		else if (throwhud) ThrowNoticeHudNudgeScreen(dx * step, dy * step);
		else if (voicehud) VoiceHudNudgeScreen(dx * step, dy * step);
		else if (upgradeammohud) UpgradeAmmoHudNudgeScreen(dx * step, dy * step);
		else if (bwselfhud) BwSelfHudNudgeScreen(dx * step, dy * step);
		else if (killfeed) KillFeedNudgeScreen(dx * step, dy * step);
		else if (matealert) {
			const int kind = g_menuPage == kMenuPageMateLast ? 0 : (g_menuPage == kMenuPageMateLow ? 1 : 2);
			MateAlertNudgeScreen(kind, dx * step, dy * step);
		}
		else if (witchstartle) WitchStartleHudNudgeScreen(dx * step, dy * step);
		else if (laserround) LaserRoundHudNudgeScreen(dx * step, dy * step);
		else if (supplyhud) SupplyScanHudNudgeScreen(dx * step, dy * step);
		else if (tankrock) TankRockNoticeHudNudgeScreen(dx * step, dy * step);
		else if (siwarn) { HudNudgeAbs(&g_siWarnAbs, &g_siWarnOffX, &g_siWarnOffY, g_siWarnAlign, dx * step, dy * step); ClampSiWarningHud(); SaveSettings(); }
		else if (tonguecut) { HudNudgeAbs(&g_tongueCutAbs, &g_tongueCutOffX, &g_tongueCutOffY, g_tongueCutAlign, dx * step, dy * step); ClampTongueCutHud(); SaveSettings(); }
		else if (scorehud) ChapStatsScoreHudNudgeScreen(dx * step, dy * step);
		else ElimNudgeScreen(dx * step, dy * step);
	};
	if (!start) {
		start = now;
		last = now;
		apply();
		return;
	}
	if (now - start < 220) return;
	if (now - last < 40) return;
	last = now;
	apply();
}

static void MenuTick() {
	if (!g_run.load(std::memory_order_relaxed)) {
		MenuForceClose();
		return;
	}
	// Worker may park via Win32 focus only. When g_paintTid is set, never EngInGame().
	const bool ingame = g_paintTid
		? g_paintInGame.load(std::memory_order_relaxed)
		: (g_engine && EngInGame());
	if (!g_engine || (!ingame && !g_mainUiMenuContext.load(std::memory_order_acquire))) {
		MenuForceClose();
		return;
	}
	if (!SkeetoFeaturesOn()) {
		MenuForceClose();
		return;
	}
	if (!g_menuVisible)
		return;
	// While stock dialogs/console own the main menu, park our settings too.
	// Worker reads only Paint-published flags and cannot unpark over a dialog.
	if (!ingame && g_mainUiMenuContext.load(std::memory_order_acquire)
		&& !g_mainUiInputReady.load(std::memory_order_acquire) && !MenuDiscoveryOwnsFocus(GetForegroundWindow())) {
		g_menuParked = true; return;
	}

	if (!g_gameHwnd || !IsWindow(g_gameHwnd))
		g_gameHwnd = FindGameWindow();
	HWND fg = GetForegroundWindow();
	const bool otherApp = (!fg || !g_gameHwnd || fg != g_gameHwnd) && !MenuDiscoveryOwnsFocus(fg);
	if (otherApp) {
		if (!g_menuParked) {
			g_menuParked = true;
			Log("menu parked (other app focused)");
		}
	} else if (g_menuParked) {
		g_menuParked = false;
		Log("menu unparked");
	}
	if (g_menuVisible && !g_menuParked)
		MenuTickElimNudge();
	// Destroy any leftover 1.4.5 Win32 menu HWND (engine draw needs none).
	if (g_menuHwnd)
		MenuDestroyWindow();
}

