bool EngPlayerInfo(int ent, PlayerInfo* out) {
	if (!out || !g_engine || ent <= 0 || ent > 64) return false;
	if (!IfaceAlive(g_engine)) return false;
	using Fn = bool(__thiscall*)(void*, int, PlayerInfo*);
	auto fn = (Fn)VGet(g_engine, 8);
	if (!fn || !IsExec((void*)fn)) return false;
	return fn(g_engine, ent, out);
}

static void RefreshLocalUserId() {
	DWORD now = GetTickCount();
	// EngPlayerInfo is expensive — shotgun fires 8–10 bullet_impact/hurt per shot.
	if (g_localUserId > 0 && g_lastLocalUidRefreshAt && now - g_lastLocalUidRefreshAt < 1000)
		return;
	g_lastLocalUidRefreshAt = now;
	int local = EngLocal();
	if (local <= 0) return;
	PlayerInfo pi{};
	if (EngPlayerInfo(local, &pi) && pi.userid > 0) {
		if (pi.userid != g_localUserId) {
			Log("localUserId %d -> %d (ent=%d name=%.32s)", g_localUserId, pi.userid, local, pi.name);
			g_localUserId = pi.userid;
		}
	}
}

static uintptr_t FindPat(const char* module, const char* pattern) {
	HMODULE h = GetModuleHandleA(module);
	if (!h) return 0;
	auto dos = (PIMAGE_DOS_HEADER)h;
	auto nt = (PIMAGE_NT_HEADERS)((uint8_t*)h + dos->e_lfanew);
	auto base = (uintptr_t)h + nt->OptionalHeader.BaseOfCode;
	auto size = nt->OptionalHeader.SizeOfCode;

	uint8_t bytes[128]; bool wild[128]; int n = 0;
	for (const char* p = pattern; *p && n < 128; ) {
		while (*p == ' ') ++p;
		if (!*p) break;
		if (*p == '?') { bytes[n] = 0; wild[n] = true; p += (p[1] == '?' ? 2 : 1); }
		else { unsigned v = 0; sscanf(p, "%02x", &v); bytes[n] = (uint8_t)v; wild[n] = false; p += 2; }
		++n;
	}
	for (size_t i = 0; i + (size_t)n <= size; ++i) {
		bool ok = true;
		for (int j = 0; j < n; ++j)
			if (!wild[j] && *(uint8_t*)(base + i + j) != bytes[j]) { ok = false; break; }
		if (ok) return base + i;
	}
	return 0;
}

// Same client director object + tempo field that CHudIntensityGraph uses for
// BUILD_UP / SUSTAIN_PEAK / PEAK_FADE / RELAX. Pattern-scan once; never guess from intensity.
static void** g_dirTempoSlot = nullptr;
static bool g_dirTempoTried = false;

bool DirectorTempoRead(int* outTempo) {
	if (!outTempo) return false;
	if (!g_dirTempoTried) {
		g_dirTempoTried = true;
		const uintptr_t hit = FindPat("client.dll",
			"A1 ?? ?? ?? ?? 89 7D F8 C7 45 F4 ?? ?? ?? ?? 85 C0 74 34 8B 80 EC 10 00 00 83 F8 03");
		if (hit && PtrCommitted((void*)hit) && PtrCommitted((void*)(hit + 4))) {
			const uintptr_t slotVa = *(uint32_t*)(hit + 1);
			if (slotVa && PtrCommitted((void*)slotVa))
				g_dirTempoSlot = (void**)slotVa;
		}
		if (g_dirTempoSlot)
			Log("director tempo: slot=%p", (void*)g_dirTempoSlot);
		else
			Log("director tempo: client pattern missing; phase labels disabled");
	}
	if (!g_dirTempoSlot || !PtrCommitted(g_dirTempoSlot)) return false;
	void* dir = *g_dirTempoSlot;
	if (!dir || !IfaceAlive(dir)) return false;
	int* p = (int*)((uint8_t*)dir + 0x10EC);
	if (!PtrCommitted(p)) return false;
	const int tempo = *p;
	if (tempo < 0 || tempo > 3) return false;
	*outTempo = tempo;
	return true;
}

static int CountPat(const char* module, const char* pattern, uintptr_t* out, int maxOut) {
	HMODULE h = GetModuleHandleA(module);
	if (!h) return 0;
	auto dos = (PIMAGE_DOS_HEADER)h;
	auto nt = (PIMAGE_NT_HEADERS)((uint8_t*)h + dos->e_lfanew);
	auto base = (uintptr_t)h + nt->OptionalHeader.BaseOfCode;
	auto size = nt->OptionalHeader.SizeOfCode;
	uint8_t bytes[128]; bool wild[128]; int n = 0;
	for (const char* p = pattern; *p && n < 128; ) {
		while (*p == ' ') ++p;
		if (!*p) break;
		if (*p == '?') { bytes[n] = 0; wild[n] = true; p += (p[1] == '?' ? 2 : 1); }
		else { unsigned v = 0; sscanf(p, "%02x", &v); bytes[n] = (uint8_t)v; wild[n] = false; p += 2; }
		++n;
	}
	int hits = 0;
	for (size_t i = 0; i + (size_t)n <= size; ++i) {
		bool ok = true;
		for (int j = 0; j < n; ++j)
			if (!wild[j] && *(uint8_t*)(base + i + j) != bytes[j]) { ok = false; break; }
		if (!ok) continue;
		if (hits < maxOut) out[hits] = base + i;
		++hits;
	}
	return hits;
}

// Retail x86 client.dll C0A8E1E8...EEB4AF1F:
// UpdateAddonModels RVA 0x2266D0 (__thiscall, no stack arguments), called from
// ClientThink and teardown; CreateAddonModel RVA 0x226300 handles eight slots.
// Weapon ID/name table RVA 0x6E3968 confirms the consumable IDs below. Slots
// 5/6/7 are tongue / defib without paddles / carried dieselcan respectively.
static int ClientUxBackItemCategory(int weaponId) {
	using Category = ClientBackItemCategory;
	switch (weaponId) {
	case 15: case 23: return (int)Category::Medicine;
	case 12: case 24: return (int)Category::Medical;
	case 13: case 14: case 25: return (int)Category::Throwables;
	default: return -1; // Unknown items keep the original display.
	}
}

static unsigned ClientUxFilterAddonBits(unsigned bits, const int* weaponIds) {
	if (g_optClientBackItemHidden[(int)ClientBackItemCategory::Tongue]) bits &= ~(1u << 5);
	if (g_optClientBackItemHidden[(int)ClientBackItemCategory::Medical]) bits &= ~(1u << 6);
	for (int slot = 0; slot < 5; ++slot) {
		if (!(bits & (1u << slot))) continue;
		const int category = ClientUxBackItemCategory(weaponIds[slot]);
		if (category >= 0 && g_optClientBackItemHidden[category]) bits &= ~(1u << slot);
	}
	return bits;
}

static void __fastcall Hooked_ClientUxUpdateAddons(void* self, void*) {
	// The engine owns self for this call. Never retain it across frames/maps.
	// Other threads bypass before reading game-thread-owned options or counters.
	if (GetCurrentThreadId() != g_paintTid) {
		g_clientAddonWrongThread.fetch_add(1, std::memory_order_relaxed);
		g_origClientAddonUpdate(self);
		return;
	}
	++g_clientAddonCalls;
	if (!g_run.load(std::memory_order_relaxed) || !g_optClientHideBackItems
		|| g_clientAddonFailed || !SkeetoFeaturesOn()) {
		g_origClientAddonUpdate(self);
		return;
	}
	int team;
	struct AddonInput { unsigned bits; int weapons[5]; } input;
	// One team read and one 24-byte input read; guarded faults go to memprobe.
	if (!EntRead(self, g_offTeam, &team) || (team != 2 && team != 3)
		|| !EntReadBlock(self, kClientAddonBitsOffset, &input, sizeof(input))) {
		g_origClientAddonUpdate(self);
		return;
	}
	const unsigned filtered = team == 2 ? ClientUxFilterAddonBits(input.bits, input.weapons)
		: (g_optClientBackItemHidden[(int)ClientBackItemCategory::Tongue] ? input.bits & ~(1u << 5) : input.bits);
	if (filtered == input.bits || !EntWrite(self, kClientAddonBitsOffset, filtered)) {
		g_origClientAddonUpdate(self);
		return;
	}
	++g_clientAddonFiltered;
	// Native update deletes unwanted addons and creates only wanted ones. Restore
	// the received mask even if upstream raises; do not swallow its exception.
	__try {
		g_origClientAddonUpdate(self);
	} __finally {
		if (!EntWrite(self, kClientAddonBitsOffset, input.bits)) g_clientAddonFailed = true;
	}
}

// Retail client.dll x86 SHA256:
// c0a8e1e88f7312db11bcfd4b0ec574d224a34b2d9a615d6088b28335eeb4af1f
