    // model's profile during that frame; binding is refreshed on next Paint.
    short modelIndex = 0; void* header = nullptr; void* rawHeader = nullptr;
    if (!EntRead(self, g_offModelIndex, &modelIndex) || modelIndex != binding->modelIndex
        || !EntRead(self, 0x934, &header) || header != binding->header
        || !EntRead(header, 0, &rawHeader) || rawHeader != binding->rawHeader) return;
