    if (!EntReadBlock(self, 0xa0, &origin, sizeof(origin))
        || !EntReadBlock(self, 0xc4, &angles, sizeof(angles))) return;
    skviewmodel::Apply(pose, eyeAngles, origin, angles, &finalOrigin, &finalAngles);
    g_vmSetOrigin(self, finalOrigin);
