			HookHealthProp(cc->table, cc->name);
			if (g_offHealth < 0) g_offHealth = FindOffset(cc->table, "m_iHealth");
			if (g_offLifeState < 0) g_offLifeState = FindOffset(cc->table, "m_lifeState");
