static void ClientUxForceWriteInt(const char* name, int value) {
	void* var = CvarFind(name);
	if (!var) return;
	int n = 0;
	float f = 0.f;
	if (CvarReadPair(var, &n, &f) && n == value && fabsf(f - (float)value) < 0.001f)
		return;
	CvarSetInt(name, value);
}

static void ClientUxForceWriteFloat(const char* name, float value) {
	void* var = CvarFind(name);
	if (!var) return;
	int n = 0;
	float f = 0.f;
	if (CvarReadPair(var, &n, &f) && fabsf(f - value) < 0.001f)
		return;
	CvarSetFloatValue(name, value);
}

