static constexpr int kClientPerfEntryCount = (int)_countof(kClientPerfEntries);
struct ClientPerfSnap { bool have; int n; float f; };
static ClientPerfSnap g_clientPerfSnaps[kClientPerfEntryCount]{};

static void ClientPerfPump() {
	if (!g_run.load(std::memory_order_relaxed) || !g_cvar) return;
	static DWORD s_nextAt = 0;
	const DWORD now = GetTickCount();
	if (!g_clientPerfDirty && s_nextAt && (LONG)(now - s_nextAt) < 0) return;
	s_nextAt = now + 500;
	g_clientPerfDirty = false;
	const bool features = SkeetoFeaturesOn();
	const bool host = ListenDetectHost();
	for (int i = 0; i < kClientPerfEntryCount; ++i) {
		const ClientPerfEntry& e = kClientPerfEntries[i];
		if (!e.name || !_strnicmp(e.name, "mod_load_", 9)) continue; // hard ban
		ClientPerfSnap& snap = g_clientPerfSnaps[i];
		bool on = features && e.group < kClientPerfGroupCount && g_optClientPerf[e.group];
		if (e.group == kClientPerfListenNet) {
			if (!host) on = false;
			// Local listen "allow 0 lerp" owns sv_client_min_interp_ratio.
			if (!_stricmp(e.name, "sv_client_min_interp_ratio") && g_optLocalAllow0Lerp)
				on = false;
		}
		void* var = CvarFind(e.name);
		if (!on) {
			if (snap.have && var) {
				if (e.asFloat) ClientUxForceWriteFloat(e.name, snap.f);
				else ClientUxForceWriteInt(e.name, snap.n);
			}
			snap.have = false;
			continue;
		}
		if (!var) continue;
		if (!snap.have) {
			int n = 0; float f = 0.f;
			if (!CvarReadPair(var, &n, &f)) continue;
			snap.n = n;
			snap.f = f;
			snap.have = true;
		}
		if (e.asFloat) ClientUxForceWriteFloat(e.name, e.target);
		else ClientUxForceWriteInt(e.name, (int)e.target);
	}
}

static bool ClientUxMeleeSwingWritable() {
	static bool warned = false;
	void* var = CvarFind("melee_show_swing");
	if (!var) {
		if (!warned) {
			warned = true;
			Log("force cvar: melee_show_swing unavailable (not a client cvar on this build)");
		}
		return false;
	}
	const int flags = CvarFlagsOf(var);
	// A replicated/server-owned cvar cannot be changed by a client in a remote
	// session.  The listen host is the server process, so it remains writable.
	if (!ListenDetectHost() && (flags & (kFCvarReplicated | kFCvarGameDll))) {
		if (!warned) {
			warned = true;
			Log("force cvar: melee_show_swing is server-owned; remote client cannot change it");
		}
		return false;
	}
	return true;
}

static void ClientUxApplyForceCvars(bool force) {
	(void)force;
	if (!g_run.load(std::memory_order_relaxed) || !g_cvar) return;
	const bool features = SkeetoFeaturesOn();
	if (g_optClientNoGroundCorpses || g_ragdollSnap.haveAll) ClientUxApplyNoCorpseCvars(force);

	auto intPin = [&](const char* name, bool on, bool& have, int& saved, int target) {
		void* var = CvarFind(name);
		if (!on) {
			if (have && var) ClientUxForceWriteInt(name, saved);
			if (have && var) have = false;
			return;
		}
		if (!var) return;
		if (!have) {
			int n = 0; float f = 0.f;
			if (!CvarReadPair(var, &n, &f)) return;
			saved = n;
			have = true;
		}
		ClientUxForceWriteInt(name, target);
	};
	auto floatPin = [&](const char* name, bool on, bool& have, float& saved, float target) {
		void* var = CvarFind(name);
		if (!on) {
			if (have && var) ClientUxForceWriteFloat(name, saved);
			if (have && var) have = false;
			return;
		}
		if (!var) return;
		if (!have) {
			int n = 0; float f = 0.f;
			if (!CvarReadPair(var, &n, &f)) return;
			saved = f;
			have = true;
		}
		ClientUxForceWriteFloat(name, target);
	};
	auto floatCommandPin = [&](const char* name, bool on, bool& have, float& saved, float target) {
		// Renderer cvars (r_flashlightbrightness): the live light only updates via
		// the command callback. Do NOT route through CvarWriteValue — cheat-numeric
		// poke-only leaves the number changed but the beam at full brightness.
		auto writeCommand = [&](float value) {
			UnlockConCommand(name, kFCvarCheat | kFCvarDevOnly | kFCvarHidden,
				kFCvarClientCmdCanExecute);
			char cmd[96]{};
			snprintf(cmd, sizeof(cmd), "%s %.3f", name, (double)value);
			EngClientCmd(cmd);
		};
		void* var = CvarFind(name);
		if (!on) {
			if (have && var) writeCommand(saved);
			if (have && var) have = false;
			return;
		}
		if (!var) return;
		if (!have) {
			int n = 0; float f = 0.f;
			if (!CvarReadPair(var, &n, &f)) return;
			saved = f;
			have = true;
		}
		writeCommand(target);
	};
	auto relativeFloatPin = [&](const char* name, bool on, bool& have, float& saved, int pct) {
		void* var = CvarFind(name);
		if (!on) {
			if (have && var) ClientUxForceWriteFloat(name, saved);
			if (have && var) have = false;
			return;
		}
		if (!var) return;
		if (!have) {
			int n = 0; float f = 0.f;
			if (!CvarReadPair(var, &n, &f) || f != f) return;
			saved = f;
			have = true;
		}
		ClientUxForceWriteFloat(name, saved * (float)pct / 100.f);
	};

	const bool fog = g_optClientForceFog && features;
	intPin("fog_override", fog, g_forceCvarSnap.fogOverride,
		g_forceCvarSnap.fogOverrideValue, 1);
	floatPin("fog_end", fog, g_forceCvarSnap.fogEnd,
		g_forceCvarSnap.fogEndValue, 99999.f);
	intPin("fog_endskybox", fog, g_forceCvarSnap.fogEndSkybox,
		g_forceCvarSnap.fogEndSkyboxValue, 0);
	floatPin("fog_maxdensity", fog, g_forceCvarSnap.fogMaxDensity,
		g_forceCvarSnap.fogMaxDensityValue, 0.f);
	floatPin("r_farz", g_optClientForceFarZ && features,
		g_forceCvarSnap.farz, g_forceCvarSnap.farzValue, 999999.f);
	const bool localDebug = features && ListenDetectHost();
	// melee_show_swing is absent or server-owned on some branches.
	intPin("melee_show_swing", g_optClientForceMeleeSwing && localDebug && ClientUxMeleeSwingWritable(),
		g_forceCvarSnap.meleeSwing, g_forceCvarSnap.meleeSwingValue, 1);
	intPin("z_noise_level_display", g_optLocalDebugNoise && localDebug,
		g_forceCvarSnap.noiseLevel, g_forceCvarSnap.noiseLevelValue, 1);
	intPin("z_debug_spawnable_areas", g_optLocalDebugSpawnAreas && localDebug,
		g_forceCvarSnap.spawnAreas, g_forceCvarSnap.spawnAreasValue, 1);
	intPin("sv_showfootsteps", g_optLocalDebugFootsteps > 0 && localDebug,
		g_forceCvarSnap.footsteps, g_forceCvarSnap.footstepsValue, g_optLocalDebugFootsteps);
	intPin("inferno_debug", g_optLocalDebugInferno && localDebug,
		g_forceCvarSnap.infernoDebug, g_forceCvarSnap.infernoDebugValue, 1);
	intPin("chainsaw_debug", g_optLocalDebugChainsaw && localDebug,
		g_forceCvarSnap.chainsawDebug, g_forceCvarSnap.chainsawDebugValue, 1);
	intPin("z_show_swings", g_optLocalDebugShowSwings && localDebug,
		g_forceCvarSnap.showSwings, g_forceCvarSnap.showSwingsValue, 1);
	intPin("upgrade_show_explosive_ammo_radius", g_optLocalDebugExplosiveRadius && localDebug,
		g_forceCvarSnap.explosiveRadius, g_forceCvarSnap.explosiveRadiusValue, 1);
	intPin("tongue_debug", g_optLocalDebugTongue && localDebug,
		g_forceCvarSnap.tongueDebug, g_forceCvarSnap.tongueDebugValue, 1);
	intPin("z_tank_rock_debug", g_optLocalDebugTankRock && localDebug,
		g_forceCvarSnap.tankRockDebug, g_forceCvarSnap.tankRockDebugValue, 1);
	intPin("z_vomit_debug", g_optLocalDebugVomit && localDebug,
		g_forceCvarSnap.vomitDebug, g_forceCvarSnap.vomitDebugValue, 1);
	const bool wantHitboxes = g_optLocalDebugHitboxes && localDebug;
	if (wantHitboxes && !g_localDebugHitboxesApplied) {
		UnlockConCommand("sv_showhitboxes_cursor", kFCvarCheat | kFCvarDevOnly | kFCvarHidden,
			kFCvarClientCmdCanExecute);
		UnlockConCommand("sv_showhitboxes", kFCvarCheat | kFCvarDevOnly | kFCvarHidden,
			kFCvarClientCmdCanExecute);
		EngClientCmd("sv_showhitboxes_cursor");
		g_localDebugHitboxesApplied = true;
	} else if (!wantHitboxes && g_localDebugHitboxesApplied) {
		EngClientCmd("sv_showhitboxes -1");
		g_localDebugHitboxesApplied = false;
	}
	const bool flashlight = g_optClientForceFlashlight && features;
	floatPin("r_flashlightconstant", flashlight,
		g_forceCvarSnap.flashlightConstant, g_forceCvarSnap.flashlightConstantValue, 1.f);
	intPin("r_flashlight_attach_to_viewmodel", flashlight,
		g_forceCvarSnap.flashlightAttach, g_forceCvarSnap.flashlightAttachValue, 0);
	floatPin("r_flashlightfar", flashlight,
		g_forceCvarSnap.flashlightFar, g_forceCvarSnap.flashlightFarValue, 750.f);
	floatPin("r_flashlightfov", flashlight,
		g_forceCvarSnap.flashlightFov, g_forceCvarSnap.flashlightFovValue, 120.f);
	floatCommandPin("r_flashlightbrightness", flashlight,
		g_forceCvarSnap.flashlightBrightness, g_forceCvarSnap.flashlightBrightnessValue,
		(float)g_clientFlashlightBrightnessQ * 0.25f);
	intPin("r_flashlightmuzzleflash", flashlight,
		g_forceCvarSnap.flashlightMuzzle, g_forceCvarSnap.flashlightMuzzleValue, 0);
	intPin("muzzleflash_light", flashlight,
		g_forceCvarSnap.muzzleflashLight, g_forceCvarSnap.muzzleflashLightValue, 0);
	// Some maps leave dynamic-shadow draw distance far too high with a bright
	// flashlight; pin the client cull distance while the force-flashlight pack is on.
	intPin("cl_max_shadow_renderable_dist", flashlight,
		g_forceCvarSnap.shadowRenderDist, g_forceCvarSnap.shadowRenderDistValue, 1);
	floatPin("z_gun_vertical_punch", flashlight,
		g_forceCvarSnap.verticalPunch, g_forceCvarSnap.verticalPunchValue, 0.f);
	const bool noWeather = g_optClientDisableWeather && features;
	floatPin("r_RainParticleDensity", noWeather,
		g_forceCvarSnap.rainDensity, g_forceCvarSnap.rainDensityValue, 0.f);
	intPin("r_SnowParticles", noWeather,
		g_forceCvarSnap.snowParticles, g_forceCvarSnap.snowParticlesValue, 0);
	intPin("mat_fullbright", g_optClientFullbright && features,
		g_forceCvarSnap.fullbright, g_forceCvarSnap.fullbrightValue, 1);
	intPin("inferno_scorch_decals", g_optScorch && features,
		g_forceCvarSnap.scorch, g_forceCvarSnap.scorchValue, 1);
	floatPin("survivor_incapacitated_roll", g_optIncapRoll && features,
		g_forceCvarSnap.incapRoll, g_forceCvarSnap.incapRollValue, -38.f);
	// Vanilla default is 1 (client.dll ConVar string). A previous pin leaves 0 in
	// the live cvar; the snap is process-local, so "off" must not restore that 0.
	const bool noFirstPersonTracers = g_optClientDisableFirstPersonTracers && features;
	if (noFirstPersonTracers) {
		intPin("r_drawtracers_firstperson", true,
			g_forceCvarSnap.firstPersonTracers, g_forceCvarSnap.firstPersonTracersValue, 0);
	} else if (g_forceCvarSnap.firstPersonTracers) {
		if (g_forceCvarSnap.firstPersonTracersValue == 0)
			g_forceCvarSnap.firstPersonTracersValue = 1;
		intPin("r_drawtracers_firstperson", false,
			g_forceCvarSnap.firstPersonTracers, g_forceCvarSnap.firstPersonTracersValue, 0);
	} else {
		static bool s_tracerOffRestored = false;
		if (!s_tracerOffRestored) {
			void* tracerVar = CvarFind("r_drawtracers_firstperson");
			int tracerN = 0;
			float tracerF = 0.f;
			if (tracerVar && CvarReadPair(tracerVar, &tracerN, &tracerF)) {
				s_tracerOffRestored = true;
				if (tracerN == 0) {
					ClientUxForceWriteInt("r_drawtracers_firstperson", 1);
					Log("tracers: option off, restored r_drawtracers_firstperson 1");
				}
			}
		}
	}
	// Fully isolated while never enabled: do not even resolve the debug CVar or
	// query the local entity. Enter this block only to apply it or restore a
	// value captured by an earlier enabled state.
	if (g_optGunDebugSpread || g_forceCvarSnap.gunDebugSpread) {
		const int debugSpreadPlayer = EngLocal();
		intPin("z_gun_debug_spread",
			g_optGunDebugSpread && features && debugSpreadPlayer > 0,
			g_forceCvarSnap.gunDebugSpread, g_forceCvarSnap.gunDebugSpreadValue,
			debugSpreadPlayer);
	}
	const bool glowOwned = features && !g_worldHudRealism && SurvivorGlowWanted();
	relativeFloatPin("cl_glow_brightness", glowOwned && g_survivorGlowBrightnessPct != 100,
		g_forceCvarSnap.glowBrightness, g_forceCvarSnap.glowBrightnessValue,
		g_survivorGlowBrightnessPct);
	relativeFloatPin("cl_glow_blur_scale", glowOwned && g_survivorGlowBlurPct != 100,
		g_forceCvarSnap.glowBlur, g_forceCvarSnap.glowBlurValue,
		g_survivorGlowBlurPct);
	static const char* kGlowStateCvars[kGlowStateCvarCount][3] = {
		{ "cl_glow_infected_vomit_r", "cl_glow_infected_vomit_g", "cl_glow_infected_vomit_b" },
		{ "cl_glow_item_r", "cl_glow_item_g", "cl_glow_item_b" },
		{ "cl_glow_survivor_vomit_r", "cl_glow_survivor_vomit_g", "cl_glow_survivor_vomit_b" },
		{ "cl_glow_item_far_r", "cl_glow_item_far_g", "cl_glow_item_far_b" },
		{ "cl_glow_survivor_health_crit_r", "cl_glow_survivor_health_crit_g", "cl_glow_survivor_health_crit_b" }
	};
	for (int kind = 0; kind < kGlowStateCvarCount; ++kind) {
		const bool configured = g_glowStateColor[kind] >= 0;
		const bool retained = g_forceCvarSnap.glowState[kind][0]
			|| g_forceCvarSnap.glowState[kind][1] || g_forceCvarSnap.glowState[kind][2];
		// The untouched default path performs no CVar lookup or write. Enter only
		// while applying a selected color or restoring a previously captured value.
		if (!configured && !retained) continue;
		const int color = configured ? g_glowStateColor[kind] : 0;
		const float rgb[3] = {
			(float)(color & 0xFF) / 255.f,
			(float)((color >> 8) & 0xFF) / 255.f,
			(float)((color >> 16) & 0xFF) / 255.f
		};
		for (int channel = 0; channel < 3; ++channel) {
			floatPin(kGlowStateCvars[kind][channel], configured && features,
				g_forceCvarSnap.glowState[kind][channel],
				g_forceCvarSnap.glowStateValue[kind][channel], rgb[channel]);
		}
	}
	intPin("r_drawmodeldecals", g_optClientNoModelDecals && features,
		g_forceCvarSnap.modelDecals, g_forceCvarSnap.modelDecalsValue, 0);
	intPin("mat_colorcorrection", g_optClientDisableColorCorrection && features,
		g_forceCvarSnap.colorCorrection, g_forceCvarSnap.colorCorrectionValue, 0);
	intPin("mat_colcorrection_disableentities",
		g_optClientDisableColorCorrectionEntities && features,
		g_forceCvarSnap.colorCorrectionEntities,
		g_forceCvarSnap.colorCorrectionEntitiesValue, 1);
}

// Pin vanilla director_show_intensity. Chapter change / sv_cheats 0 restores CHEAT
// cvars. Same idea as the spread ring, but only written on menu toggle or the
// first non-loading map Paint. Does not touch the custom 8-player director HUD.
static void ClientUxApplyDirectorHud(bool force) {
	(void)force;
	if (!g_run.load(std::memory_order_relaxed) || !g_cvar) return;
	static bool s_pinned = false;
	static bool s_haveSnap = false;
	static float s_snap = 0.f;
	static bool s_missingLogged = false;
	static bool s_onLogged = false;
	const bool on = g_optClientDirectorHud && SkeetoFeaturesOn();
	void* var = CvarFind("director_show_intensity");
	if (!var) {
		if (!s_missingLogged) {
			s_missingLogged = true;
			Log("director hud: director_show_intensity missing");
		}
		return;
	}
	if (!on) {
		if (s_pinned) {
			CvarSetFloatValue("director_show_intensity", s_haveSnap ? s_snap : 0.f);
			s_pinned = false;
			s_haveSnap = false;
			s_onLogged = false;
			Log("director hud: vanilla off (restored %.2f)", s_snap);
		}
		return;
	}
	if (!s_pinned) {
		int n = 0;
		float f = 0.f;
		if (CvarReadPair(var, &n, &f)) {
			s_snap = f;
			s_haveSnap = true;
		}
	}
	int n = 0;
	float f = 0.f;
	if (!CvarReadPair(var, &n, &f) || fabsf(f - 1.f) > 0.001f)
		CvarSetFloatValue("director_show_intensity", 1.f);
	s_pinned = true;
	if (!s_onLogged) {
		s_onLogged = true;
		Log("director hud: vanilla pinned");
	}
}

static void NetGraphHudApplyVanilla(bool enable) {
	if (!g_cvar) return;
	void* var = CvarFind("net_graph");
	if (!var) return;
	if (enable) {
		if (!g_netGraphHudVanillaPinned) {
			int n = 0;
			if (CvarReadPair(var, &n, nullptr)) {
				g_netGraphHudVanillaSnap = n;
				g_netGraphHudVanillaHaveSnap = true;
			}
		}
		int n = 0;
		float f = 0.f;
		if (!CvarReadPair(var, &n, &f) || n != 0)
			CvarSetInt("net_graph", 0);
		g_netGraphHudVanillaPinned = true;
		return;
	}
	if (!g_netGraphHudVanillaPinned) return;
	CvarSetInt("net_graph",
		g_netGraphHudVanillaHaveSnap ? g_netGraphHudVanillaSnap : 0);
	g_netGraphHudVanillaPinned = false;
	g_netGraphHudVanillaHaveSnap = false;
}

// Black Mesa View Tilt is consumed by client.dll even though sv_rollangle is
// FCVAR_REPLICATED. Numeric writes use the existing local ConVar poke path; no
// command is sent to a remote server. A 1 Hz readback repairs later replication.
static struct {
	bool applied;
	bool haveRestore;
	float restoreAngle;
	float restoreSpeed;
	DWORD verifyAt;
} g_viewRollState{};

static void ClientUxApplyViewRoll(bool force) {
	if (!g_run.load(std::memory_order_relaxed) || !g_cvar) return;
	const bool stableInGame = g_paintInGame.load(std::memory_order_relaxed)
		&& !g_paintLoading.load(std::memory_order_relaxed)
		&& !g_mapEnterGameThreadResetPending.load(std::memory_order_acquire)
		&& !g_hudPostMissionQuiet;
	const bool wanted = stableInGame && g_optLocalViewRoll
		&& g_optLocalViewRollAngle > 0 && SkeetoFeaturesOn();
	if (!wanted && !g_viewRollState.applied)
		return;
	const DWORD now = GetTickCount();
	if (wanted && !force && g_viewRollState.applied
		&& (LONG)(now - g_viewRollState.verifyAt) < 0)
		return;

	void* angleVar = CvarFind("sv_rollangle");
	void* speedVar = CvarFind("sv_rollspeed");
	static bool s_missingLogged = false;
	if (!angleVar || !speedVar) {
		if (!s_missingLogged) {
			s_missingLogged = true;
			Log("view roll: %s missing", !angleVar ? "sv_rollangle" : "sv_rollspeed");
		}
		return;
	}
	s_missingLogged = false;

	float currentAngle = 0.f, currentSpeed = 0.f;
	if (!CvarReadPair(angleVar, nullptr, &currentAngle) || currentAngle != currentAngle) return;
	if (!CvarReadPair(speedVar, nullptr, &currentSpeed) || currentSpeed != currentSpeed) return;

	if (!wanted) {
		if (g_viewRollState.haveRestore) {
			if (fabsf(currentAngle - g_viewRollState.restoreAngle) > 0.001f)
				ClientUxCvarWriteFloat("sv_rollangle", g_viewRollState.restoreAngle);
			if (fabsf(currentSpeed - g_viewRollState.restoreSpeed) > 0.001f)
				ClientUxCvarWriteFloat("sv_rollspeed", g_viewRollState.restoreSpeed);
		}
		Log("view roll: released (restored angle %.2f speed %.2f)",
			g_viewRollState.haveRestore ? g_viewRollState.restoreAngle : currentAngle,
			g_viewRollState.haveRestore ? g_viewRollState.restoreSpeed : currentSpeed);
		g_viewRollState = {};
		return;
	}

	const float wantedAngle = (float)g_optLocalViewRollAngle;
	const float wantedSpeed = (float)g_optLocalViewRollSpeed;
	// Differing values while owned are fresh server replication. Preserve them
	// before reapplying the local visual preference. A forced call while already
	// owned is a menu change, not replication.
	if (!g_viewRollState.haveRestore) {
		g_viewRollState.restoreAngle = currentAngle;
		g_viewRollState.restoreSpeed = currentSpeed;
		g_viewRollState.haveRestore = true;
	} else if (!force) {
		if (fabsf(currentAngle - wantedAngle) > 0.001f)
			g_viewRollState.restoreAngle = currentAngle;
		if (fabsf(currentSpeed - wantedSpeed) > 0.001f)
			g_viewRollState.restoreSpeed = currentSpeed;
	}
	if (fabsf(currentAngle - wantedAngle) > 0.001f)
		ClientUxCvarWriteFloat("sv_rollangle", wantedAngle);
	if (fabsf(currentSpeed - wantedSpeed) > 0.001f)
		ClientUxCvarWriteFloat("sv_rollspeed", wantedSpeed);
	g_viewRollState.applied = true;
	g_viewRollState.verifyAt = now + 1000u;
}

static void ClientUxViewRollPump() {
	if (!g_optLocalViewRoll && !g_viewRollState.applied)
		return;
	ClientUxApplyViewRoll(false);
}

static void ClientUxHideEntHard(void* e, int idx) {
	if (!EntReadable(e)) return;
	// Never hide survivor/SI/Tank pawn slots. That is what made respawned SI invisible.
	if (ClientUxIsPlayerSlot(idx)) return;
	const char* cn = EntNetClassName(idx);
	if (ClientUxIsPlayerPawnClass(cn)) return;
	// Draw flags only — do not move origin (that fought prediction and could not be undone).
	if (g_offEffects >= 0 && g_offEffects <= 0x4000) {
		int* pe = (int*)((uint8_t*)e + g_offEffects);
		if (PtrCommitted(pe)) *pe |= kEfNoDraw;
	}
	if (g_offRenderMode >= 0 && g_offRenderMode <= 0x4000) {
		uint8_t* pm = (uint8_t*)e + g_offRenderMode;
		if (PtrCommitted(pm)) *pm = (uint8_t)kRenderNone;
	}
	if (g_offClrRender >= 0 && g_offClrRender <= 0x4000) {
		uint32_t* pc = (uint32_t*)((uint8_t*)e + g_offClrRender);
		if (PtrCommitted(pc)) *pc = 0;
	}
}

static void ClientUxUnhideEnt(void* e) {
	if (!EntReadable(e)) return;
	if (g_offEffects >= 0 && g_offEffects <= 0x4000) {
		int* pe = (int*)((uint8_t*)e + g_offEffects);
		if (PtrCommitted(pe)) *pe &= ~kEfNoDraw;
	}
	if (g_offRenderMode >= 0 && g_offRenderMode <= 0x4000) {
		uint8_t* pm = (uint8_t*)e + g_offRenderMode;
		if (PtrCommitted(pm)) *pm = 0;
	}
	if (g_offClrRender >= 0 && g_offClrRender <= 0x4000) {
		uint32_t* pc = (uint32_t*)((uint8_t*)e + g_offClrRender);
		if (PtrCommitted(pc)) *pc = 0xFFFFFFFFu;
	}
}

static void ClientUxUnhideIdx(int idx) {
	if (idx <= 0 || ClientUxIsPlayerSlot(idx)) return;
	if (ClientUxIsPlayerPawnClass(EntNetClassName(idx))) return;
	void* e = EntGet(idx);
	if (e) ClientUxUnhideEnt(e);
}

static bool ClientUxIsClientRagdollClass(const char* name) {
	if (!name || !name[0]) return false;
	if (!_stricmp(name, "C_ClientRagdoll") || !_stricmp(name, "C_ClientRagdoll2"))
		return true;
	if (!_stricmp(name, "client_ragdoll") || !_stricmp(name, "client_ragdoll2"))
		return true;
	if (!_stricmp(name, "C_InfectedRagdoll") || !_stricmp(name, "CInfectedRagdoll"))
		return true;
	if (!_stricmp(name, "CCSRagdoll") || !_stricmp(name, "C_CSRagdoll"))
		return true;
	if (strstr(name, "Ragdoll") || strstr(name, "ragdoll"))
		return true;
	return false;
}

static bool ClientUxIsInfectedRagdollClass(const char* name) {
	return name && (!_stricmp(name, "C_InfectedRagdoll") || !_stricmp(name, "CInfectedRagdoll"));
}

static bool ClientUxStillCorpse(int idx, void* expect, bool si) {
	void* e = EntGet(idx);
	if (!e || e != expect || !EntReadable(e)) return false;
	if (ClientUxIsPlayerSlot(idx)) return false;
	const char* cn = EntNetClassName(idx);
	if (ClientUxIsPlayerPawnClass(cn)) return false;
	if (ClientUxIsClientRagdollClass(cn))
		return !(si && ClientUxIsInfectedRagdollClass(cn));
	if (si)
		return false;
	// zombie_death already nailed this id. Client m_iHealth / m_lifeState on Infected
	// often lag "alive"; do not use them. Keep hiding while the slot is still that
	// common/Witch; drop only on pointer recycle / class change.
	if (IsCommonInfectedClass(cn))
		return true;
	return false;
}

static void ClientUxArmRagdollPulse() {
	g_noCorpseRagLeft = 3;
	g_noCorpseRagNextAt = GetTickCount();
}

static void ClientUxReleaseNoCorpseTracks() {
	for (int i = 0; i < g_noCorpseN; ++i)
		ClientUxUnhideIdx(g_noCorpseEnt[i]);
	ClientUxClearNoCorpseTracks();
}

static void ClientUxDropNoCorpseKind(bool si) {
	const bool keepRag = si ? g_optClientNoCorpseCi : g_optClientNoCorpseSi;
	int w = 0;
	for (int i = 0; i < g_noCorpseN; ++i) {
		if (g_noCorpseIsSi[i] == si) {
			const char* cn = EntNetClassName(g_noCorpseEnt[i]);
			if (keepRag && ClientUxIsClientRagdollClass(cn)) {
				g_noCorpseEnt[w] = g_noCorpseEnt[i];
				g_noCorpsePtr[w] = g_noCorpsePtr[i];
				g_noCorpseUntil[w] = g_noCorpseUntil[i];
				g_noCorpseIsSi[w] = !si;
				++w;
				continue;
			}
			ClientUxUnhideIdx(g_noCorpseEnt[i]);
			continue;
		}
		g_noCorpseEnt[w] = g_noCorpseEnt[i];
		g_noCorpsePtr[w] = g_noCorpsePtr[i];
		g_noCorpseUntil[w] = g_noCorpseUntil[i];
		g_noCorpseIsSi[w] = g_noCorpseIsSi[i];
		++w;
	}
	g_noCorpseN = w;
}

static void ClientUxTrackCorpse(int ent, DWORD holdMs, bool si) {
	if (ent <= 0) return;
	if (ClientUxIsPlayerSlot(ent)) {
		ClientUxArmRagdollPulse();
		return;
	}
	const char* cn = EntNetClassName(ent);
	if (ClientUxIsPlayerPawnClass(cn)) {
		ClientUxArmRagdollPulse();
		return;
	}
	if (si && ClientUxIsInfectedRagdollClass(cn)) return;
	// Dissolve and no-corpse share this list. CI/Witch entries come from zombie_death.victim.
	const bool diss = si ? DissSiWanted() : DissCiWanted();
	if (si && !g_optClientNoCorpseSi && !diss) return;
	if (!si && !g_optClientNoCorpseCi && !diss) return;
	void* e = EntGet(ent);
	if (!EntReadable(e)) return;
	const DWORD until = GetTickCount() + holdMs;
	for (int i = 0; i < g_noCorpseN; ++i) {
		if (g_noCorpseEnt[i] == ent) {
			if (until > g_noCorpseUntil[i])
				g_noCorpseUntil[i] = until;
			g_noCorpseIsSi[i] = si;
			g_noCorpsePtr[i] = e;
			ClientUxHideEntHard(e, ent);
			return;
		}
	}
	if (g_noCorpseN >= kNoCorpseTrackMax) {
		ClientUxUnhideIdx(g_noCorpseEnt[0]);
		memmove(g_noCorpseEnt, g_noCorpseEnt + 1, (kNoCorpseTrackMax - 1) * sizeof(int));
		memmove(g_noCorpsePtr, g_noCorpsePtr + 1, (kNoCorpseTrackMax - 1) * sizeof(void*));
		memmove(g_noCorpseUntil, g_noCorpseUntil + 1, (kNoCorpseTrackMax - 1) * sizeof(DWORD));
		memmove(g_noCorpseIsSi, g_noCorpseIsSi + 1, (kNoCorpseTrackMax - 1) * sizeof(bool));
		g_noCorpseN = kNoCorpseTrackMax - 1;
	}
	g_noCorpseEnt[g_noCorpseN] = ent;
	g_noCorpsePtr[g_noCorpseN] = e;
	g_noCorpseUntil[g_noCorpseN] = until;
	g_noCorpseIsSi[g_noCorpseN] = si;
	++g_noCorpseN;
	ClientUxHideEntHard(e, ent);
	ClientUxArmRagdollPulse();
}

// Client-only C_EntityDissolve. Game thread only. Paint calls the pump before the
// in-game panel early-out so a closed switch or a map edge can still release
// effects. Not a HUD: do not hang this on HudAnyCustomPaintWanted.
// Backend addresses come from the loaded client.dll. A signature miss leaves
// the menu switch on and spawns nothing.
static constexpr int kDissActiveMax = 6;
static constexpr int kDissPendingMax = 16;
static constexpr int kDissBytes = 0x680;
static constexpr int kDissStart = 0x63C;
static constexpr int kDissFadeInStart = 0x640;
static constexpr int kDissFadeInLen = 0x644;
static constexpr int kDissFadeModelStart = 0x648;
static constexpr int kDissFadeModelLen = 0x64C;
static constexpr int kDissFadeOutStart = 0x650;
static constexpr int kDissFadeOutLen = 0x654;
static constexpr int kDissType = 0x658;
static constexpr int kDissNextSpark = 0x65C;

struct DissActive {
	int fxIndex;
	void* fx;
	int targetIndex;
	void* target;
	int playerUserId;
	unsigned int playerSpawnEpoch;
	uint8_t oldMode;
	uint32_t oldClr;
	int oldEffects;
	bool haveRender;
	bool commonTarget; // CI/Infected class — concurrent budget + never NODRAW
	DWORD expireAt;
};
struct DissPending {
	int kind;
	int id;
	int playerUserId;
	unsigned int playerSpawnEpoch;
	int tries;
	DWORD nextAt;
	DWORD bornAt;
	float origin[3];
	bool haveOrigin;
	bool heavy; // retained for enqueue defer hints (Witch); type is never forced from this
	void* expect; // SI/CI pointer guard; SI also carries userid + player_spawn epoch
};
struct DissRecent {
	int idx;
	void* ptr;
	DWORD at;
};
static DissActive g_dissActive[kDissActiveMax]{};
static int g_dissActiveN = 0;
static DissPending g_dissPending[kDissPendingMax]{};
static int g_dissPendingN = 0;
static constexpr int kDissPlayerLifeMax = 64;
struct DissPlayerLife {
	int userid;
	unsigned int spawnEpoch;
	DWORD touchedAt;
};
static DissPlayerLife g_dissPlayerLife[kDissPlayerLifeMax]{};
static DissRecent g_dissRecent[16]{};
static int g_dissRecentN = 0;

static DissPlayerLife* DissPlayerLifeFind(int userid, bool create) {
	if (userid <= 0) return nullptr;
	const DWORD now = GetTickCount();
	int empty = -1;
	int oldest = -1;
	DWORD oldestAge = 0;
	for (int i = 0; i < kDissPlayerLifeMax; ++i) {
		DissPlayerLife& life = g_dissPlayerLife[i];
		if (life.userid == userid) {
			life.touchedAt = now;
			return &life;
		}
		if (life.userid == 0) {
			if (empty < 0) empty = i;
			continue;
		}
		const DWORD age = now - life.touchedAt;
		if (oldest < 0 || age > oldestAge) {
			oldest = i;
			oldestAge = age;
		}
	}
	if (!create) return nullptr;
	const int slot = empty >= 0 ? empty : oldest;
	if (slot < 0) return nullptr;
	DissPlayerLife& life = g_dissPlayerLife[slot];
	life = {};
	life.userid = userid;
	life.touchedAt = now;
	return &life;
}

static unsigned int DissPlayerLifeEpoch(int userid, bool create) {
	DissPlayerLife* life = DissPlayerLifeFind(userid, create);
	return life ? life->spawnEpoch : 0xFFFFFFFFu;
}

static bool DissPlayerLifeCurrent(int userid, unsigned int spawnEpoch) {
	return userid > 0 && DissPlayerLifeEpoch(userid, false) == spawnEpoch;
}

static void DissPlayerLifeAdvance(int userid) {
	DissPlayerLife* life = DissPlayerLifeFind(userid, true);
	if (!life) return;
	++life->spawnEpoch;
	if (life->spawnEpoch == 0) ++life->spawnEpoch;
}

static bool DissPlayerLifeTracked(int userid) {
	for (int i = 0; i < g_dissPendingN; ++i)
		if (g_dissPending[i].kind == 1 && g_dissPending[i].playerUserId == userid) return true;
	for (int i = 0; i < g_dissActiveN; ++i)
		if (g_dissActive[i].playerUserId == userid) return true;
	return false;
}
static int g_dissBackend = 0;
static int g_dissLogLeft = 6;
static void* (__cdecl* g_dissAlloc)(int) = nullptr;
static void* (__thiscall* g_dissCtor)(void*) = nullptr;
static void (__thiscall* g_dissSetModel)(void*, const void*) = nullptr;
static void (__thiscall* g_dissSetParent)(void*, void*, int) = nullptr;
static void (__thiscall* g_dissSetOrigin)(void*, const float*) = nullptr;
static void (__thiscall* g_dissDelete)(void*, void*) = nullptr;
static void** g_dissDeleteMgr = nullptr;
static void** g_dissVt = nullptr;
static void** g_dissInfectedRagdollVt = nullptr;
static void** g_dissRagdollVt[4]{};
static int g_dissRagdollVtN = 0;
static void (__thiscall* g_dissAddFlags)(void*, int) = nullptr;
static void (__thiscall* g_dissSetEffect)(void*, void*) = nullptr;
static void (__thiscall* g_dissAddLeaf)(void*, int) = nullptr;
static void (__thiscall* g_dissThink)(void*) = nullptr;
static void* g_dissModelInfo = nullptr;
static const void* (__thiscall* g_dissFindModel)(void*, const char*) = nullptr;
static const void* g_dissGlow = nullptr;
static bool g_dissGlowTried = false;
static DWORD g_dissWindowAt = 0;
static int g_dissWindowN = 0;
static DWORD g_dissTick = 0;
static int g_dissTickN = 0;
static DWORD g_dissCiLastApplyAt = 0;
static constexpr DWORD kDissCiMinGapMs = 175; // multi-kill hitch: hard gap between CI creates
static constexpr int kDissCiActiveMax = 3;    // CI share of kDissActiveMax
static constexpr DWORD kDissSiPendingLifeMs = 700;
// Deferred hide of -lv client ragdoll that spawns a tick after dissolve apply.
static float g_dissPulseOrg[3]{};
static DWORD g_dissPulseNextAt = 0;
static DWORD g_dissPulseUntil = 0;
static int g_dissPulseLeft = 0;

static void DissLog(const char* msg) {
	if (g_dissLogLeft <= 0) return;
	--g_dissLogLeft;
	Log("dissolve: %s", msg);
}

static bool DissBytes(const void* p, const void* sig, int n) {
	if (n <= 0 || !PtrCommitted(p) || !PtrCommitted((const uint8_t*)p + n - 1)) return false;
	return memcmp(p, sig, (size_t)n) == 0;
}

static uintptr_t DissRelCall(uintptr_t insn) {
	if (!PtrCommitted((void*)insn) || *(uint8_t*)insn != 0xE8) return 0;
	const int32_t rel = *(int32_t*)(insn + 1);
	const uintptr_t dest = insn + 5 + (uintptr_t)rel;
	return IsExec((void*)dest) ? dest : 0;
}

static void** DissRttiVtable(HMODULE mod, const char* rttiName) {
	// Disabled: a previous page-walk called VirtualQuery per byte across client.dll
	// and froze the game on the first SI death before backend-ready could log.
	(void)mod;
	(void)rttiName;
	return nullptr;
}

static bool ClientUxDissolveResolve() {
	if (g_dissBackend != 0) return g_dissBackend > 0;
	g_dissBackend = -1;
	HMODULE client = GetModuleHandleA("client.dll");
	if (!client) {
		DissLog("client.dll missing");
		return false;
	}
	uintptr_t hits[4]{};
	const int nHits = CountPat("client.dll", "55 8B EC 56 68 80 06 00 00 E8", hits, 4);
	if (nHits <= 0) {
		DissLog("DissolveEffect prologue not found");
		return false;
	}
	const uint8_t* fn = nullptr;
	const uint8_t kPushSize[] = { 0x68, 0x80, 0x06, 0x00, 0x00 };
	const uint8_t kInitSlot[] = { 0x8B, 0x90, 0x70, 0x01, 0x00, 0x00 };
	const uint8_t kParent[] = { 0x6A, 0x00, 0x57, 0x8B, 0xCE, 0xE8 };
	const uint8_t kOrigin[] = { 0x50, 0x8B, 0xCE, 0xE8 };
	const uint8_t kOnData[] = { 0x8B, 0x46, 0x08, 0x8B, 0x50, 0x10, 0x8D, 0x4E, 0x08, 0x6A, 0x00, 0xFF, 0xD2 };
	const uint8_t kStart[] = { 0xF3, 0x0F, 0x11, 0x86, 0x3C, 0x06, 0x00, 0x00 };
	for (int i = 0; i < nHits && i < 4; ++i) {
		const uint8_t* cand = (const uint8_t*)hits[i];
		if (!DissBytes(cand + 4, kPushSize, 5) || *(cand + 9) != 0xE8 || *(cand + 0x17) != 0xE8
			|| !DissBytes(cand + 0x24, kInitSlot, 6) || !DissBytes(cand + 0x39, "\x8B\x0D", 2)
			|| *(cand + 0x3F) != 0x56 || *(cand + 0x40) != 0xE8
			|| !DissBytes(cand + 0x5A, kParent, 6) || !DissBytes(cand + 0x7A, kOrigin, 4)
			|| !DissBytes(cand + 0x64, kOnData, 13) || !DissBytes(cand + 0x87, kStart, 8)
			|| *(cand + 0x4E) != 0x68 || *(cand + 0x55) != 0xE8 || *(cand + 0xFE) != 0xE8)
			continue;
		fn = cand;
		break;
	}
	if (!fn) {
		DissLog("DissolveEffect body does not match this build");
		return false;
	}
	const uintptr_t alloc = DissRelCall((uintptr_t)fn + 9);
	const uintptr_t ctor = DissRelCall((uintptr_t)fn + 0x17);
	const uintptr_t setParent = DissRelCall((uintptr_t)fn + 0x5F);
	const uintptr_t setOrigin = DissRelCall((uintptr_t)fn + 0x7D);
	const uintptr_t del = DissRelCall((uintptr_t)fn + 0x40);
	const uintptr_t addFlags = DissRelCall((uintptr_t)fn + 0x55);
	const uintptr_t setEffect = DissRelCall((uintptr_t)fn + 0xFE);
	void** mgr = *(void***)(fn + 0x3B);
	if (!alloc || !ctor || !setParent || !setOrigin || !del || !addFlags || !setEffect
		|| !mgr || !PtrCommitted(mgr)) {
		DissLog("DissolveEffect call targets failed");
		return false;
	}
	void** vt = nullptr;
	const uint8_t* c = (const uint8_t*)ctor;
	for (int i = 0; i < 0x40; ++i) {
		if (!PtrCommitted(c + i + 6)) break;
		if (c[i] == 0xC7 && c[i + 1] == 0x06) {
			vt = *(void***)(c + i + 2);
			break;
		}
	}
	if (!vt || !PtrCommitted(vt) || !IsExec(vt[0]) || !IsExec(vt[0x170 / 4])) {
		DissLog("C_EntityDissolve vtable failed");
		return false;
	}
	uintptr_t modelHits[2]{};
	if (CountPat("client.dll", "55 8B EC 56 57 8B 7D 08 8B F1 3B 7E 60 74 41", modelHits, 2) != 1) {
		DissLog("SetModelPointer is not unique");
		return false;
	}
	void* mi = GetIface("engine.dll", "VModelInfoClient004");
	if (!mi) mi = GetIface("engine.dll", "VModelInfoClient006");
	if (!IfaceAlive(mi)) {
		DissLog("VModelInfo missing");
		return false;
	}
	auto findModel = (const void* (__thiscall*)(void*, const char*))VGet(mi, 41);
	if (!IsExec((void*)findModel)) {
		DissLog("FindOrLoadModel slot failed");
		return false;
	}
	g_dissAlloc = (void* (__cdecl*)(int))alloc;
	g_dissCtor = (void* (__thiscall*)(void*))ctor;
	g_dissSetParent = (void (__thiscall*)(void*, void*, int))setParent;
	g_dissSetOrigin = (void (__thiscall*)(void*, const float*))setOrigin;
	g_dissDelete = (void (__thiscall*)(void*, void*))del;
	g_dissDeleteMgr = mgr;
	g_dissVt = vt;
	g_dissSetModel = (void (__thiscall*)(void*, const void*))modelHits[0];
	g_dissModelInfo = mi;
	g_dissFindModel = findModel;
	void** thinkVt = nullptr;
	for (int i = 0; i < 0x60; ++i) {
		if (!PtrCommitted(c + i + 7)) break;
		if (c[i] == 0xC7 && c[i + 1] == 0x46 && c[i + 2] == 0x0C) {
			thinkVt = *(void***)(c + i + 3);
			break;
		}
	}
	void* think = (thinkVt && PtrCommitted(thinkVt)) ? thinkVt[1] : nullptr;
	g_dissAddFlags = (void (__thiscall*)(void*, int))addFlags;
	g_dissSetEffect = (void (__thiscall*)(void*, void*))setEffect;
	g_dissAddLeaf = nullptr;
	g_dissThink = IsExec(think) ? (void (__thiscall*)(void*))think : nullptr;
	g_dissInfectedRagdollVt = nullptr;
	g_dissRagdollVtN = 0;
	g_dissLogLeft = 24;
	g_dissBackend = 1;
	Log("dissolve: backend ready think=%d", g_dissThink ? 1 : 0);
	return true;
}

static bool ClientUxDissolveBackendFailed() {
	return g_dissBackend < 0;
}

static bool DissIsFx(void* fx) {
	if (!fx || !g_dissVt || !EntReadable(fx)) return false;
	void** vt = *(void***)fx;
	return vt == g_dissVt;
}

static void DissDeleteFx(void* fx) {
	if (!DissIsFx(fx) || !g_dissDelete || !g_dissDeleteMgr || !PtrCommitted(g_dissDeleteMgr)) return;
	void* mgr = *g_dissDeleteMgr;
	if (!mgr || !EntReadable(mgr)) return;
	g_dissDelete(mgr, fx);
}

static void DissDrawFx(void* fx) {
	if (!DissIsFx(fx)) return;
	void* rend = (uint8_t*)fx + 4;
	if (!EntReadable(rend)) return;
	void** rvt = *(void***)rend;
	if (!PtrCommitted(rvt) || !IsExec(rvt[9])) return;
	auto drawModel = (int (__thiscall*)(void*, int, void*))rvt[9];
	uint8_t inst[16]{};
	inst[0] = 255;
	drawModel(rend, 1, inst);
}

static bool DissReadOrigin(void* e, float out[3]) {
	if (!e || !out || g_offOrigin < 0 || g_offOrigin > 0x2000) return false;
	float* o = (float*)((uint8_t*)e + g_offOrigin);
	if (!PtrCommitted(o) || !PtrCommitted(o + 2)) return false;
	out[0] = o[0];
	out[1] = o[1];
	out[2] = o[2];
	return out[0] == out[0] && out[1] == out[1] && out[2] == out[2];
}

static int DissTeam(void* e) {
	if (!e || g_offTeam < 0 || g_offTeam > 0x4000) return -1;
	int* t = (int*)((uint8_t*)e + g_offTeam);
	return PtrCommitted(t) ? *t : -1;
}

static bool DissLooksAlive(void* e, bool common) {
	const int offLife = common ? g_offLifeStateCommon : g_offLifeState;
	const int offHp = common ? g_offHealthCommon : g_offHealth;
	if (offLife < 0 || offLife > 0x4000 || offHp < 0 || offHp > 0x4000) return false;
	uint8_t* life = (uint8_t*)e + offLife;
	int* hp = (int*)((uint8_t*)e + offHp);
	if (!PtrCommitted(life) || !PtrCommitted(hp)) return false;
	return *life == 0 && *hp > 0;
}

static void DissRemember(int idx, void* ptr) {
	if (!ptr) return;
	const DWORD now = GetTickCount();
	for (int i = 0; i < g_dissRecentN; ++i) {
		if (g_dissRecent[i].ptr == ptr) {
			g_dissRecent[i].idx = idx;
			g_dissRecent[i].at = now;
			return;
		}
	}
	if (g_dissRecentN >= 16) {
		memmove(g_dissRecent, g_dissRecent + 1, 15 * sizeof(DissRecent));
		g_dissRecentN = 15;
	}
	g_dissRecent[g_dissRecentN].idx = idx;
	g_dissRecent[g_dissRecentN].ptr = ptr;
	g_dissRecent[g_dissRecentN].at = now;
	++g_dissRecentN;
}

static bool DissRecentHit(void* ptr) {
	const DWORD now = GetTickCount();
	int w = 0;
	bool hit = false;
	for (int i = 0; i < g_dissRecentN; ++i) {
		if ((LONG)(now - g_dissRecent[i].at) > 2000) continue;
		if (g_dissRecent[i].ptr == ptr) hit = true;
		g_dissRecent[w++] = g_dissRecent[i];
	}
	g_dissRecentN = w;
	return hit;
}

static bool DissTargetBusy(void* ptr) {
	for (int i = 0; i < g_dissActiveN; ++i)
		if (g_dissActive[i].target == ptr) return true;
	return DissRecentHit(ptr);
}

static const void* DissGlowModel() {
	if (g_dissGlowTried) return g_dissGlow;
	g_dissGlowTried = true;
	if (!g_dissFindModel || !g_dissModelInfo) return nullptr;
	// Prefer retail L4D2 sprites that exist in pak01 (not HL2-only blueglow1).
	static const char* kPaths[] = {
		"sprites/glow01.vmt",
		"sprites/light_glow01.vmt",
		"sprites/glow.vmt",
		"sprites/laserbeam.vmt",
	};
	for (int i = 0; i < 4; ++i) {
		const void* model = g_dissFindModel(g_dissModelInfo, kPaths[i]);
		if (model) {
			g_dissGlow = model;
			Log("dissolve: glow model=%s", kPaths[i]);
			break;
		}
	}
	if (!g_dissGlow) DissLog("glow sprite model missing");
	return g_dissGlow;
}

static int DissFindIndex(void* fx) {
	if (!fx || !g_entlist) return 0;
	int hi = EntHighestIndex();
	if (hi > 2048) hi = 2048;
	int lo = hi > 96 ? hi - 96 : 1;
	if (lo < 1) lo = 1;
	for (int i = hi; i >= lo; --i) {
		if (EntGet(i) == fx) return i;
	}
	return 0;
}

static void DissWriteFloat(void* fx, int off, float v) {
	float* p = (float*)((uint8_t*)fx + off);
	if (PtrCommitted(p)) *p = v;
}

static void DissHideTarget(const DissActive* slot);
static void DissHideNearOrigin(const float* origin, void* except);
static void DissArmRagPulse(const float* origin);
static void DissPumpRagPulse(DWORD now);

static bool DissApply(void* target, int targetIndex, bool trustExactId,
	int playerUserId = 0, unsigned int playerSpawnEpoch = 0) {
	if (!ClientUxDissolveResolve() || !target || !EntReadable(target)) {
		DissLog("apply reject: resolve/target");
		return false;
	}
	const char* tcn = EntNetClassName(targetIndex);
	const bool common = IsCommonInfectedClass(tcn) && !IsWitchClass(tcn);
	// Client lifeState/hp on Infected is unreliable (often still "alive" after death).
	// Do NOT gate dissolve on DissLooksAlive — that path was already proven dead.
	// Wrong-target safety is identity (hurt/Trace id + anchor glue), not corpse netvars.
	(void)trustExactId;
	(void)common;
	// Some servers expose no separate SI ragdoll, so the effect may target the
	// dead player pawn. Its userid + spawn epoch, not pointer equality, guards reuse.
	const bool playerPawn = ClientUxIsPlayerSlot(targetIndex) || ClientUxIsPlayerPawnClass(tcn);
	if (playerPawn) {
		if (DissTeam(target) != 3 || !DissPlayerLifeCurrent(playerUserId, playerSpawnEpoch)) {
			DissLog("apply reject: player");
			return false;
		}
	}
	if (DissIsFx(target) || DissTargetBusy(target)) {
		DissLog("apply reject: busy");
		return false;
	}
	const void* glow = DissGlowModel();
	void* storage = g_dissAlloc(kDissBytes);
	if (!storage) {
		DissLog("apply reject: alloc");
		return false;
	}
	void* fx = g_dissCtor(storage);
	if (!DissIsFx(fx)) {
		DissLog("constructor did not publish the dissolve vtable");
		return false;
	}
	void** vt = *(void***)fx;
	auto init = (bool (__thiscall*)(void*, const char*, int))vt[0x170 / 4];
	if (!IsExec((void*)init) || !init(fx, nullptr, 0)) {
		DissDeleteFx(fx);
		DissLog("model-less init failed");
		return false;
	}
	// Must SetParent to the corpse: sparks are emitted from parent hitboxes.
	// Skipping parent (previous light path) made Witch/CI dissolve invisible.
	if (glow && g_dissSetModel) g_dissSetModel(fx, glow);
	// Never AddFlags on player pawns — FL_DISSOLVING can stick across SI respawn.
	if (g_dissAddFlags
		&& !ClientUxIsPlayerSlot(targetIndex)
		&& !ClientUxIsPlayerPawnClass(tcn))
		g_dissAddFlags(target, 0x10000000);
	g_dissSetParent(fx, target, 0);
	void* net = (uint8_t*)fx + 8;
	if (!EntReadable(net)) {
		DissDeleteFx(fx);
		DissLog("apply reject: net");
		return false;
	}
	void** nvt = *(void***)net;
	auto onData = (void (__thiscall*)(void*, int))nvt[4];
	if (!IsExec((void*)onData)) {
		DissDeleteFx(fx);
		DissLog("apply reject: ondata");
		return false;
	}
	onData(net, 0);
	void** tvt = *(void***)target;
	auto getOrg = (const float* (__thiscall*)(void*))tvt[0x2C / 4];
	if (IsExec((void*)getOrg)) {
		const float* org = getOrg(target);
		if (org && PtrCommitted(org)) g_dissSetOrigin(fx, org);
	} else {
		float orgBuf[3];
		if (DissReadOrigin(target, orgBuf)) g_dissSetOrigin(fx, orgBuf);
	}
	const float nowT = EngClientCurTime();
	int ms = g_optClientDissolveMs;
	if (ms < kDissMsMin) ms = kDissMsMin;
	if (ms > kDissMsMax) ms = kDissMsMax;
	// Respect menu type + duration for everyone. Hitch control is defer/rate-limit only.
	const float scale = (float)ms / 550.f;
	DissWriteFloat(fx, kDissStart, nowT);
	DissWriteFloat(fx, kDissFadeInStart, 0.f);
	DissWriteFloat(fx, kDissFadeInLen, 0.45f * scale);
	DissWriteFloat(fx, kDissFadeModelStart, 0.02f * scale);
	DissWriteFloat(fx, kDissFadeModelLen, 0.28f * scale);
	DissWriteFloat(fx, kDissFadeOutStart, 0.02f * scale);
	DissWriteFloat(fx, kDissFadeOutLen, 0.35f * scale);
	DissWriteFloat(fx, kDissNextSpark, nowT + 0.06f);
	int* kind = (int*)((uint8_t*)fx + kDissType);
	int dtype = g_optClientDissolveType;
	if (dtype < 0) dtype = 0;
	if (dtype > 3) dtype = 3;
	if (PtrCommitted(kind)) *kind = dtype;
	uint8_t* flag = (uint8_t*)fx + 0x678;
	if (PtrCommitted(flag)) *flag = 0;
	if (playerPawn && !DissPlayerLifeCurrent(playerUserId, playerSpawnEpoch)) {
		DissDeleteFx(fx);
		return false;
	}
	if (g_dissSetEffect) g_dissSetEffect(target, fx);
	// Do not Think here — death-frame Think+DrawModel on SI hitboxes hitch hard.
	if (g_dissActiveN >= kDissActiveMax) {
		DissDeleteFx(fx);
		DissLog("apply reject: full");
		return false;
	}
	DissActive* slot = &g_dissActive[g_dissActiveN++];
	*slot = {};
	slot->fx = fx;
	// Skip DissFindIndex (up to 96 EntGet) on the hot apply path.
	slot->fxIndex = 0;
	slot->target = target;
	slot->targetIndex = targetIndex;
	slot->playerUserId = playerPawn ? playerUserId : 0;
	slot->playerSpawnEpoch = playerPawn ? playerSpawnEpoch : 0;
	slot->commonTarget = common;
	slot->expireAt = GetTickCount() + (DWORD)ms;
	if (g_offRenderMode >= 0 && g_offRenderMode <= 0x4000) {
		uint8_t* mode = (uint8_t*)target + g_offRenderMode;
		if (PtrCommitted(mode)) {
			slot->oldMode = *mode;
			slot->haveRender = true;
		}
	}
	if (g_offClrRender >= 0 && g_offClrRender <= 0x4000) {
		uint32_t* clr = (uint32_t*)((uint8_t*)target + g_offClrRender);
		if (PtrCommitted(clr)) slot->oldClr = *clr;
	}
	if (g_offEffects >= 0 && g_offEffects <= 0x4000) {
		int* fxFlags = (int*)((uint8_t*)target + g_offEffects);
		if (PtrCommitted(fxFlags)) slot->oldEffects = *fxFlags;
	}
	DissRemember(targetIndex, target);
	// Commons: never NODRAW (wrong near-matches → invisible living CI).
	// Player slots: never NODRAW (same hard rule as NoCorpse — see DissHideTarget).
	// Witch / high-index ragdolls may still be hidden.
	if (!common)
		DissHideTarget(slot);
	Log("dissolve: apply ok idx=%d exact=%d glow=%d", targetIndex, trustExactId ? 1 : 0, glow ? 1 : 0);
	return true;
}

static void DissRestoreTarget(const DissActive* slot) {
	if (!slot || !slot->haveRender || !slot->target) return;
	// Render snapshots belong to one player life. Never copy a dead-life snapshot
	// onto the same pawn after a player_spawn event.
	if (slot->playerUserId > 0
		&& !DissPlayerLifeCurrent(slot->playerUserId, slot->playerSpawnEpoch)) return;
	if (slot->targetIndex <= 0 || EntGet(slot->targetIndex) != slot->target) return;
	// Pointer equality alone does not identify a player life; the epoch guard above
	// prevents a death snapshot from being copied onto a respawned pawn.
	if (g_offRenderMode >= 0 && g_offRenderMode <= 0x4000) {
		uint8_t* mode = (uint8_t*)slot->target + g_offRenderMode;
		if (PtrCommitted(mode)) *mode = slot->oldMode;
	}
	if (g_offClrRender >= 0 && g_offClrRender <= 0x4000) {
		uint32_t* clr = (uint32_t*)((uint8_t*)slot->target + g_offClrRender);
		if (PtrCommitted(clr)) *clr = slot->oldClr;
	}
	if (g_offEffects >= 0 && g_offEffects <= 0x4000) {
		int* fxFlags = (int*)((uint8_t*)slot->target + g_offEffects);
		if (PtrCommitted(fxFlags)) *fxFlags = slot->oldEffects;
	}
}

static void DissHideTarget(const DissActive* slot) {
	if (!slot || !slot->target || slot->targetIndex <= 0) return;
	if (EntGet(slot->targetIndex) != slot->target) return;
	// Hard rule (same as ClientUxHideEntHard / NoCorpse): NEVER NODRAW slots 1–64
	// or TerrorPlayer pawns. Dead SI still occupy a player slot; hiding that pawn
	// made fast-respawn living SI invisible. DissLooksAlive cannot tell a corpse
	// from a recycled living pawn on the same pointer — do not rely on it here.
	if (ClientUxIsPlayerSlot(slot->targetIndex)) return;
	{
		const char* hn = EntNetClassName(slot->targetIndex);
		if (ClientUxIsPlayerPawnClass(hn)) return;
		// Hard rule: never NODRAW commons — wrong matches were turning living CI invisible.
		if (IsCommonInfectedClass(hn) && !IsWitchClass(hn))
			return;
	}
	if (g_offEffects >= 0 && g_offEffects <= 0x4000) {
		int* fxFlags = (int*)((uint8_t*)slot->target + g_offEffects);
		if (PtrCommitted(fxFlags)) *fxFlags |= kEfNoDraw;
	}
	if (g_offRenderMode >= 0 && g_offRenderMode <= 0x4000) {
		uint8_t* mode = (uint8_t*)slot->target + g_offRenderMode;
		if (PtrCommitted(mode)) *mode = (uint8_t)kRenderNone;
	}
}

// =============================================================================
// Skeetoscript: client-side spit acid range estimate (insect_swarm / DT_Inferno)
// Scan+Paint on Paint thread only. Feature OFF => O(1) early-out, no scan/draw.
// =============================================================================
static constexpr int kAcidOutlineRadii[] = { 60, 75, 90, 105 };
static constexpr int kAcidOutlineRadiiN = 4;
static constexpr DWORD kAcidOutlineActiveScanMs = 200; // refresh known active acid at 5 Hz
static constexpr DWORD kAcidOutlineIdleScanMs = 300;   // less discovery work when no pool is known
static constexpr int kAcidOutlineMaxPools = 8;
static constexpr int kAcidOutlineMaxNodesTotal = 128;
static constexpr int kAcidOutlineSegs = 20;
static constexpr int kAcidOutlineSegCap = 600;
static constexpr float kAcidOutlineDistCap = 1500.f;
static constexpr float kAcidOutlineLift = 3.f;
static constexpr float kAcidOutlineTau = 6.28318530718f;
static constexpr int kAcidOutlineColorCount = 8;
static_assert(kAcidOutlineColorCount == 8, "supply scan color wrap uses 0..7");
static constexpr int kAcidOutlineColors[kAcidOutlineColorCount][3] = {
	{ 170, 220, 40 },   // original green
	{ 0, 220, 255 },    // cyan
	{ 70, 150, 255 },   // blue
	{ 255, 215, 45 },   // yellow
	{ 255, 130, 35 },   // orange
	{ 255, 70, 70 },    // red
	{ 245, 70, 220 },   // magenta
	{ 245, 245, 245 }, // white
};

static int g_offAcidFireCount = -1;
static int g_offAcidFireX = -1;
static int g_offAcidFireY = -1;
static int g_offAcidFireZ = -1;
static int g_offAcidFireStride = 4;
static int g_offAcidOrigin = -1;
static bool g_acidOutlineResolveTried = false;
static bool g_acidOutlineResolveOk = false;
static bool g_acidOutlineProbed = false;

struct AcidOutlineNode { float x, y, z; };
struct AcidOutlineSeg { float ax, ay, az, bx, by, bz; };
struct AcidOutlinePool {
	int entIdx;
	int n;
	AcidOutlineNode nodes[64];
};
static AcidOutlinePool g_acidOutlinePools[kAcidOutlineMaxPools];
static int g_acidOutlinePoolN = 0;
static int g_acidOutlineNodeTotal = 0;
static DWORD g_acidOutlineScanAt = 0;
static AcidOutlineSeg g_acidOutlineSegs[kAcidOutlineSegCap];
static int g_acidOutlineSegN = 0;
static unsigned long long g_acidOutlineGeomHash = 0;
static int g_acidOutlineKnownIdx[kAcidOutlineMaxPools];
static int g_acidOutlineKnownN = 0;
static int g_acidOutlineDiscoverCursor = 1;
static ClientClass* g_acidOutlineSwarmCC = nullptr; // InsectSwarm only; pointer compare in discovery
static constexpr int kAcidOutlineDiscoverPassTicks = 5; // max-index discovery: 1s active, 1.5s idle

static bool AcidOutlineWanted() {
	return g_optClientAcidOutline && SkeetoFeaturesOn();
}

static void ClientUxAcidOutlineClear() {
	g_acidOutlinePoolN = 0;
	g_acidOutlineNodeTotal = 0;
	g_acidOutlineSegN = 0;
	g_acidOutlineGeomHash = 0;
	g_acidOutlineKnownN = 0;
	g_acidOutlineScanAt = 0;
	g_acidOutlineDiscoverCursor = 1;
}

static int AcidOutlineNormRadius(int r) {
	int best = kAcidOutlineRadii[1], bestD = 1 << 30;
	for (int i = 0; i < kAcidOutlineRadiiN; ++i) {
		const int d = r - kAcidOutlineRadii[i];
		const int ad = d < 0 ? -d : d;
		if (ad < bestD) { bestD = ad; best = kAcidOutlineRadii[i]; }
	}
	return best;
}

static int AcidOutlineNormColor(int color) {
	if (color < 0) return 0;
	if (color >= kAcidOutlineColorCount) return kAcidOutlineColorCount - 1;
	return color;
}

static COLORREF AcidOutlineColorRgb(int color) {
	color = AcidOutlineNormColor(color);
	return RGB(kAcidOutlineColors[color][0], kAcidOutlineColors[color][1], kAcidOutlineColors[color][2]);
}

static const wchar_t* AcidOutlineColorName(int color) {
	switch (AcidOutlineNormColor(color)) {
	case 1: return UiText(UiId::AcidOutlineColorCyan, L"青色");
	case 2: return UiText(UiId::AcidOutlineColorBlue, L"蓝色");
	case 3: return UiText(UiId::AcidOutlineColorYellow, L"黄色");
	case 4: return UiText(UiId::AcidOutlineColorOrange, L"橙色");
	case 5: return UiText(UiId::AcidOutlineColorRed, L"红色");
	case 6: return UiText(UiId::AcidOutlineColorMagenta, L"洋红");
	case 7: return UiText(UiId::AcidOutlineColorWhite, L"白色");
	default: return UiText(UiId::AcidOutlineColorGreen, L"绿色");
	}
}

static void MenuCycleAcidOutlineRadius(int dir) {
	int idx = 1;
	for (int i = 0; i < kAcidOutlineRadiiN; ++i) {
		if (kAcidOutlineRadii[i] == g_optClientAcidOutlineRadius) { idx = i; break; }
	}
	idx = (idx + (dir >= 0 ? 1 : kAcidOutlineRadiiN - 1)) % kAcidOutlineRadiiN;
	g_optClientAcidOutlineRadius = kAcidOutlineRadii[idx];
	g_acidOutlineGeomHash = 0;
	SaveSettings();
	Log("menu: clientAcidOutlineRadius=%d", g_optClientAcidOutlineRadius);
	EngClientCmd("play buttons/button14");
}

static void MenuCycleAcidOutlineWidth() {
	int w = g_optClientAcidOutlineWidth;
	w = (w < 1 || w >= 4) ? 1 : w + 1;
	g_optClientAcidOutlineWidth = w;
	SaveSettings();
	Log("menu: clientAcidOutlineWidth=%d", g_optClientAcidOutlineWidth);
	EngClientCmd("play buttons/button14");
}

static void MenuCycleAcidOutlineColor() {
	g_optClientAcidOutlineColor = (AcidOutlineNormColor(g_optClientAcidOutlineColor) + 1)
		% kAcidOutlineColorCount;
	SaveSettings();
	Log("menu: clientAcidOutlineColor=%d", g_optClientAcidOutlineColor);
	EngClientCmd("play buttons/button14");
}

static int AcidOutlineArrayOff(RecvTable* table, const char* baseName, int* strideOut) {
	if (!table || !baseName) return -1;
	char named[64];
	_snprintf_s(named, sizeof(named), _TRUNCATE, "%s[0]", baseName);
	int off = FindOffset(table, named);
	uint8_t* prop = FindRecvProp(table, named);
	if (off < 0) {
		off = FindOffset(table, baseName);
		prop = FindRecvProp(table, baseName);
	}
	if (off < 0) return -1;
	int stride = 4;
	if (prop) {
		const int s = *(int*)(prop + 0x30); // RecvProp::m_ElementStride
		if (s >= 4 && s <= 32) stride = s;
	}
	if (strideOut) *strideOut = stride;
	return off;
}

static void AcidOutlineTryResolveTable(RecvTable* table) {
	if (!table || g_acidOutlineResolveOk) return;
	int stride = 4;
	const int fireCount = FindOffset(table, "m_fireCount");
	const int fireX = AcidOutlineArrayOff(table, "m_fireXDelta", &stride);
	const int fireY = AcidOutlineArrayOff(table, "m_fireYDelta", nullptr);
	const int fireZ = AcidOutlineArrayOff(table, "m_fireZDelta", nullptr);
	const int origin = FindOffset(table, "m_vecOrigin");
	if (fireCount < 0 || fireX < 0 || fireY < 0 || fireZ < 0) return;
	if (fireCount > 0x4000 || fireX > 0x4000 || fireY > 0x4000 || fireZ > 0x4000) return;
	g_offAcidFireCount = fireCount;
	g_offAcidFireX = fireX;
	g_offAcidFireY = fireY;
	g_offAcidFireZ = fireZ;
	g_offAcidFireStride = stride;
	if (origin >= 0 && origin <= 0x4000) g_offAcidOrigin = origin;
	else if (g_offOrigin >= 0) g_offAcidOrigin = g_offOrigin;
	g_acidOutlineResolveOk = (g_offAcidOrigin >= 0);
}

static void AcidOutlineEnsureResolved() {
	if (g_acidOutlineResolveTried) return;
	g_acidOutlineResolveTried = true;
	void* bc = GetIface("client.dll", "VClient016");
	if (!bc) return;
	using Fn = ClientClass*(__thiscall*)(void*);
	auto getCc = (Fn)VGet(bc, 7);
	if (!getCc || !IsExec((void*)getCc)) return;
	ClientClass* insectCc = nullptr;
	ClientClass* infernoCc = nullptr;
	for (ClientClass* cc = getCc(bc); cc; cc = cc->next) {
		if (!cc->name || !cc->table) continue;
		const bool insect = strstr(cc->name, "InsectSwarm")
			|| (cc->table->name && strstr(cc->table->name, "InsectSwarm"));
		const bool inferno = strstr(cc->name, "Inferno")
			|| (cc->table->name && strstr(cc->table->name, "Inferno"));
		if (insect && !insectCc) insectCc = cc;
		if (inferno && !infernoCc) infernoCc = cc;
	}
	// Offsets may live on DT_Inferno; entity identity for spit must be InsectSwarm.
	ClientClass* offCc = insectCc ? insectCc : infernoCc;
	if (offCc) AcidOutlineTryResolveTable(offCc->table);
	if (g_acidOutlineResolveOk) {
		g_acidOutlineSwarmCC = insectCc; // may be null if only Inferno offsets resolved
		Log("[SpitOutline] resolved class=%s table=%s swarmCC=%p count=%d x=%d y=%d z=%d stride=%d origin=%d",
			offCc->name, offCc->table->name ? offCc->table->name : "?",
			(void*)g_acidOutlineSwarmCC,
			g_offAcidFireCount, g_offAcidFireX, g_offAcidFireY, g_offAcidFireZ,
			g_offAcidFireStride, g_offAcidOrigin);
	}
}

static ClientClass* EntClientClass(int i) {
	if (i <= 0 || i >= 2048) return nullptr;
	void* net = EntNetworkable(i);
	if (!net || !IfaceAlive(net)) return nullptr;
	using Fn = ClientClass*(__thiscall*)(void*);
	auto fn = (Fn)VGet(net, 1);
	if (!fn || !IsExec((void*)fn)) return nullptr;
	__try {
		ClientClass* cc = fn(net);
		return (cc && PtrCommitted(cc)) ? cc : nullptr;
	} __except (EXCEPTION_EXECUTE_HANDLER) {
		skmem::NoteFault((uintptr_t)_ReturnAddress());
		return nullptr;
	}
}

// Cheap per-index gate for discovery: one vcall + pointer compare (no strstr).
static bool AcidOutlineIsSwarmEnt(int entIdx) {
	if (!g_acidOutlineSwarmCC) return false;
	ClientClass* cc = EntClientClass(entIdx);
	return cc == g_acidOutlineSwarmCC;
}

static bool AcidOutlineKnownHas(int entIdx) {
	for (int i = 0; i < g_acidOutlineKnownN; ++i)
		if (g_acidOutlineKnownIdx[i] == entIdx) return true;
	return false;
}

static unsigned long long AcidOutlineHashMix(unsigned long long h, unsigned long long v) {
	h ^= v + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
	return h;
}

static unsigned long long AcidOutlineMakeGeomHash(int radius) {
	unsigned long long h = 0xcbf29ce484222325ULL;
	h = AcidOutlineHashMix(h, (unsigned long long)radius);
	h = AcidOutlineHashMix(h, (unsigned long long)g_acidOutlinePoolN);
	h = AcidOutlineHashMix(h, (unsigned long long)g_acidOutlineNodeTotal);
	for (int p = 0; p < g_acidOutlinePoolN; ++p) {
		const AcidOutlinePool& pool = g_acidOutlinePools[p];
		h = AcidOutlineHashMix(h, (unsigned long long)pool.entIdx);
		h = AcidOutlineHashMix(h, (unsigned long long)pool.n);
		// Mix every node (quantized). First-node-only hash missed expansions that
		// kept the same seed and count.
		for (int i = 0; i < pool.n; ++i) {
			h = AcidOutlineHashMix(h, (unsigned long long)(int)(pool.nodes[i].x + (pool.nodes[i].x >= 0.f ? 0.5f : -0.5f)));
			h = AcidOutlineHashMix(h, (unsigned long long)(int)(pool.nodes[i].y + (pool.nodes[i].y >= 0.f ? 0.5f : -0.5f)));
			h = AcidOutlineHashMix(h, (unsigned long long)(int)(pool.nodes[i].z + (pool.nodes[i].z >= 0.f ? 0.5f : -0.5f)));
		}
	}
	return h;
}

static bool AcidOutlineSegInsideOther(const AcidOutlineNode* nodes, int n, int self,
	float mx, float my, float radius) {
	const float r2 = radius * radius * 0.98f;
	for (int j = 0; j < n; ++j) {
		if (j == self) continue;
		const float dx = mx - nodes[j].x;
		const float dy = my - nodes[j].y;
		if (dx * dx + dy * dy < r2) return true;
	}
	return false;
}

static void AcidOutlineRebuildWorldSegs(float radius) {
	g_acidOutlineSegN = 0;
	if (g_acidOutlinePoolN <= 0 || g_acidOutlineNodeTotal <= 0 || radius <= 0.f) return;

	// Flatten nodes across pools for merge tests within the same spit cloud.
	AcidOutlineNode flat[kAcidOutlineMaxNodesTotal];
	int flatN = 0;
	for (int p = 0; p < g_acidOutlinePoolN && flatN < kAcidOutlineMaxNodesTotal; ++p) {
		const AcidOutlinePool& pool = g_acidOutlinePools[p];
		for (int i = 0; i < pool.n && flatN < kAcidOutlineMaxNodesTotal; ++i)
			flat[flatN++] = pool.nodes[i];
	}
	if (flatN <= 0) return;

	for (int i = 0; i < flatN && g_acidOutlineSegN < kAcidOutlineSegCap; ++i) {
		float prevWx = 0.f, prevWy = 0.f, prevWz = 0.f;
		bool havePrev = false;
		for (int s = 0; s <= kAcidOutlineSegs && g_acidOutlineSegN < kAcidOutlineSegCap; ++s) {
			const float a = kAcidOutlineTau * (float)s / (float)kAcidOutlineSegs;
			const float wx = flat[i].x + radius * cosf(a);
			const float wy = flat[i].y + radius * sinf(a);
			const float wz = flat[i].z + kAcidOutlineLift;
			if (havePrev) {
				const float mx = 0.5f * (prevWx + wx);
				const float my = 0.5f * (prevWy + wy);
				if (!AcidOutlineSegInsideOther(flat, flatN, i, mx, my, radius)) {
					AcidOutlineSeg& seg = g_acidOutlineSegs[g_acidOutlineSegN++];
					seg.ax = prevWx; seg.ay = prevWy; seg.az = prevWz;
					seg.bx = wx; seg.by = wy; seg.bz = wz;
				}
			}
			prevWx = wx; prevWy = wy; prevWz = wz;
			havePrev = true;
		}
	}
}

static bool AcidOutlineFillPool(int entIdx, AcidOutlinePool* out, int* ioNodeTotal) {
	if (!out || !ioNodeTotal) return false;
	void* e = EntGet(entIdx);
	if (!e || !EntReadable(e)) return false;
	if (!AcidOutlineIsSwarmEnt(entIdx)) return false;
	const char* cn = (g_acidOutlineSwarmCC && g_acidOutlineSwarmCC->name) ? g_acidOutlineSwarmCC->name : "?";
	const int fireCount = *(int*)((uint8_t*)e + g_offAcidFireCount);
	if (fireCount <= 0 || fireCount > 64) return false;
	const float* origin = (const float*)((uint8_t*)e + g_offAcidOrigin);
	if (!EntReadable((void*)origin)) return false;

	out->entIdx = entIdx;
	out->n = 0;
	for (int k = 0; k < fireCount && *ioNodeTotal < kAcidOutlineMaxNodesTotal; ++k) {
		const int* xd = (const int*)((uint8_t*)e + g_offAcidFireX + k * g_offAcidFireStride);
		const int* yd = (const int*)((uint8_t*)e + g_offAcidFireY + k * g_offAcidFireStride);
		const int* zd = (const int*)((uint8_t*)e + g_offAcidFireZ + k * g_offAcidFireStride);
		if (!EntReadable((void*)xd) || !EntReadable((void*)yd) || !EntReadable((void*)zd))
			break;
		out->nodes[out->n].x = origin[0] + (float)xd[0];
		out->nodes[out->n].y = origin[1] + (float)yd[0];
		out->nodes[out->n].z = origin[2] + (float)zd[0];
		++out->n;
		++(*ioNodeTotal);
	}
	if (out->n <= 0) return false;

	if (!g_acidOutlineProbed) {
		g_acidOutlineProbed = true;
		Log("[SpitOutline]: class=%s countOff=%d xOff=%d yOff=%d zOff=%d stride=%d originOff=%d fireCount=%d",
			cn ? cn : "?", g_offAcidFireCount, g_offAcidFireX, g_offAcidFireY, g_offAcidFireZ,
			g_offAcidFireStride, g_offAcidOrigin, fireCount);
		const int show = out->n < 3 ? out->n : 3;
		for (int s = 0; s < show; ++s) {
			const int* xs = (const int*)((uint8_t*)e + g_offAcidFireX + s * g_offAcidFireStride);
			const int* ys = (const int*)((uint8_t*)e + g_offAcidFireY + s * g_offAcidFireStride);
			const int* zs = (const int*)((uint8_t*)e + g_offAcidFireZ + s * g_offAcidFireStride);
			Log("[SpitOutline]: delta[%d]=(%d,%d,%d) node=(%.1f,%.1f,%.1f)",
				s, xs[0], ys[0], zs[0], out->nodes[s].x, out->nodes[s].y, out->nodes[s].z);
		}
	}
	return true;
}

static void ClientUxAcidOutlineScanTick() {
	if (!AcidOutlineWanted()) {
		if (g_acidOutlinePoolN || g_acidOutlineNodeTotal || g_acidOutlineSegN)
			ClientUxAcidOutlineClear();
		return;
	}
	const DWORD now = GetTickCount();
	const DWORD scanInterval = g_acidOutlinePoolN > 0
		? kAcidOutlineActiveScanMs : kAcidOutlineIdleScanMs;
	if (g_acidOutlineScanAt && (LONG)(now - g_acidOutlineScanAt) < (LONG)scanInterval)
		return;
	g_acidOutlineScanAt = now;
	if (!g_run.load(std::memory_order_relaxed) || !g_engine || !EngInGame() || !g_entlist) {
		ClientUxAcidOutlineClear();
		g_acidOutlineScanAt = now;
		return;
	}

	AcidOutlineEnsureResolved();
	if (!g_acidOutlineResolveOk) {
		ClientUxAcidOutlineClear();
		g_acidOutlineScanAt = now;
		return;
	}

	int hi = EntHighestIndex();
	if (hi > 2048) hi = 2048;
	if (hi < 1) {
		ClientUxAcidOutlineClear();
		g_acidOutlineScanAt = now;
		return;
	}

	AcidOutlinePool localPools[kAcidOutlineMaxPools];
	int localN = 0;
	int localNodes = 0;

	// Re-validate remembered insect_swarm indices only (no full-table walk).
	for (int i = 0; i < g_acidOutlineKnownN && localN < kAcidOutlineMaxPools; ++i) {
		const int entIdx = g_acidOutlineKnownIdx[i];
		if (entIdx < 1 || entIdx > hi) continue;
		AcidOutlinePool pool{};
		if (!AcidOutlineFillPool(entIdx, &pool, &localNodes)) continue;
		localPools[localN++] = pool;
	}

	// Incremental discovery: scale slice so one full pass finishes in <= PassTicks (~1s).
	int cursor = g_acidOutlineDiscoverCursor;
	if (cursor < 1 || cursor > hi) cursor = 1;
	int slice = (hi + kAcidOutlineDiscoverPassTicks - 1) / kAcidOutlineDiscoverPassTicks;
	if (slice < 128) slice = 128;
	if (slice > 512) slice = 512;
	for (int step = 0; step < slice; ++step) {
		const int entIdx = cursor;
		++cursor;
		if (cursor > hi) cursor = 1;
		if (localN >= kAcidOutlineMaxPools) continue;
		bool already = false;
		for (int k = 0; k < localN; ++k) {
			if (localPools[k].entIdx == entIdx) { already = true; break; }
		}
		if (already) continue;
		// Cheap reject before FillPool property reads.
		if (!AcidOutlineIsSwarmEnt(entIdx)) continue;
		AcidOutlinePool pool{};
		if (!AcidOutlineFillPool(entIdx, &pool, &localNodes)) continue;
		localPools[localN++] = pool;
	}
	g_acidOutlineDiscoverCursor = cursor;

	g_acidOutlinePoolN = localN;
	g_acidOutlineNodeTotal = localNodes;
	for (int p = 0; p < localN; ++p)
		g_acidOutlinePools[p] = localPools[p];

	g_acidOutlineKnownN = localN;
	for (int p = 0; p < localN; ++p)
		g_acidOutlineKnownIdx[p] = localPools[p].entIdx;

	if (localN <= 0 || localNodes <= 0) {
		g_acidOutlineSegN = 0;
		g_acidOutlineGeomHash = 0;
		return;
	}

	const int radiusI = AcidOutlineNormRadius(g_optClientAcidOutlineRadius);
	const unsigned long long hash = AcidOutlineMakeGeomHash(radiusI);
	if (hash != g_acidOutlineGeomHash || g_acidOutlineSegN <= 0) {
		AcidOutlineRebuildWorldSegs((float)radiusI);
		g_acidOutlineGeomHash = hash;
	}
}

// Screen-space thick line: w parallel 1px lines offset across the minor axis.
static void SurfThickLine(int x0, int y0, int x1, int y1, int w) {
	if (w <= 1) { SurfLine(x0, y0, x1, y1); return; }
	const int adx = x1 > x0 ? x1 - x0 : x0 - x1;
	const int ady = y1 > y0 ? y1 - y0 : y0 - y1;
	const bool steep = ady > adx;
	const int lo = -(w - 1) / 2;
	for (int k = 0; k < w; ++k) {
		const int o = lo + k;
		if (steep) SurfLine(x0 + o, y0, x1 + o, y1);
		else SurfLine(x0, y0 + o, x1, y1 + o);
	}
}

static void ClientUxAcidOutlinePaint() {
	if (!AcidOutlineWanted()) return;
	if (!g_run.load(std::memory_order_relaxed)) return;
	if (g_acidOutlineSegN <= 0) return;
	if (!g_acidOutlineResolveOk) return;

	float eye[3]{};
	const bool haveEye = LocalEyePos(eye);
	const float distCap2 = kAcidOutlineDistCap * kAcidOutlineDistCap;

	int sw = 0, sh = 0;
	if (!SurfGetScreenSize(&sw, &sh) || sw < 8 || sh < 8) return;

	const int segN = g_acidOutlineSegN < kAcidOutlineSegCap ? g_acidOutlineSegN : kAcidOutlineSegCap;
	// Hard per-frame cap: shadow + stroke = 2*w SurfLine per segment, <= 2400 lines total.
	int lineW = g_optClientAcidOutlineWidth < 1 ? 1 : (g_optClientAcidOutlineWidth > 4 ? 4 : g_optClientAcidOutlineWidth);
	const COLORREF rgb = AcidOutlineColorRgb(g_optClientAcidOutlineColor);
	if (segN > 0 && segN * 2 * lineW > 2400) {
		lineW = 2400 / (2 * segN);
		if (lineW < 1) lineW = 1;
	}
	for (int i = 0; i < segN; ++i) {
		const AcidOutlineSeg& seg = g_acidOutlineSegs[i];
		if (haveEye) {
			const float mx = 0.5f * (seg.ax + seg.bx) - eye[0];
			const float my = 0.5f * (seg.ay + seg.by) - eye[1];
			const float mz = 0.5f * (seg.az + seg.bz) - eye[2];
			if (mx * mx + my * my + mz * mz > distCap2) continue;
		}
		float sx0 = 0.f, sy0 = 0.f, sx1 = 0.f, sy1 = 0.f;
		const float a[3] = { seg.ax, seg.ay, seg.az };
		const float b[3] = { seg.bx, seg.by, seg.bz };
		if (!LocalPlayWorldToScreen(a, &sx0, &sy0, sw, sh)) continue;
		if (!LocalPlayWorldToScreen(b, &sx1, &sy1, sw, sh)) continue;
		const int x0 = (int)(sx0 + 0.5f), y0 = (int)(sy0 + 0.5f);
		const int x1 = (int)(sx1 + 0.5f), y1 = (int)(sy1 + 0.5f);
		SurfColor(20, 20, 20, 180);
		SurfThickLine(x0 + 1, y0 + 1, x1 + 1, y1 + 1, lineW);
		SurfColor(GetRValue(rgb), GetGValue(rgb), GetBValue(rgb), 230);
		SurfThickLine(x0, y0, x1, y1, lineW);
	}
}



static void ClientUxDissolveDrop() {
	g_dissActiveN = 0;
	g_dissPendingN = 0;
	g_dissRecentN = 0;
	g_dissCiHurtN = 0;
	g_dissGlow = nullptr;
	g_dissGlowTried = false;
	g_dissWindowN = 0;
	g_dissTickN = 0;
	g_dissCiLastApplyAt = 0;
	g_dissPulseLeft = 0;
	g_dissPulseUntil = 0;
	if (g_dissBackend < 0) g_dissBackend = 0;
}

static void ClientUxDissolveShutdown(bool restoreTargets) {
	const bool live = g_engine && EngInGame() && g_entlist;
	for (int i = 0; i < g_dissActiveN; ++i) {
		if (!live) continue;
		// Player targets are never hidden; their render snapshot is life-epoch guarded.
		if (restoreTargets || ClientUxIsPlayerSlot(g_dissActive[i].targetIndex)
			|| g_dissActive[i].playerUserId > 0)
			DissRestoreTarget(&g_dissActive[i]);
		else
			DissHideTarget(&g_dissActive[i]);
		DissDeleteFx(g_dissActive[i].fx);
	}
	g_dissActiveN = 0;
	g_dissPendingN = 0;
	g_dissRecentN = 0;
	g_dissCiHurtN = 0;
	g_dissPulseLeft = 0;
	g_dissPulseUntil = 0;
}

static bool DissReadCiOrigin(void* e, float out[3]) {
	const int off = (g_offOriginCommon >= 0 && g_offOriginCommon <= 0x4000)
		? g_offOriginCommon : g_offOrigin;
	if (!e || !out || off < 0 || off > 0x4000) return false;
	float* o = (float*)((uint8_t*)e + off);
	if (!PtrCommitted(o) || !PtrCommitted(o + 2)) return false;
	out[0] = o[0]; out[1] = o[1]; out[2] = o[2];
	return out[0] == out[0] && out[1] == out[1] && out[2] == out[2];
}

static void DissCiHurtNote(int ent, void* ptr) {
	if (ent <= 0 || !ptr || ClientUxIsPlayerSlot(ent)) return;
	const DWORD now = GetTickCount();
	for (int i = 0; i < g_dissCiHurtN; ++i) {
		if (g_dissCiHurt[i].idx != ent) continue;
		// Shotgun pellet storm (mirror CI hit feedback 70ms): keep the slot fresh but
		// Avoid repeated origin reads for the same traced CI candidate.
		if ((LONG)(now - g_dissCiHurt[i].at) < 70) {
			g_dissCiHurt[i].ptr = ptr;
			g_dissCiHurt[i].at = now;
			return;
		}
		g_dissCiHurt[i].ptr = ptr;
		g_dissCiHurt[i].at = now;
		g_dissCiHurt[i].haveOrg = DissReadCiOrigin(ptr, g_dissCiHurt[i].org);
		return;
	}
	if (g_dissCiHurtN >= kDissCiHurtMax) {
		memmove(g_dissCiHurt, g_dissCiHurt + 1, (kDissCiHurtMax - 1) * sizeof(DissCiHurt));
		g_dissCiHurtN = kDissCiHurtMax - 1;
	}
	DissCiHurt* h = &g_dissCiHurt[g_dissCiHurtN++];
	*h = {};
	h->idx = ent;
	h->ptr = ptr;
	h->at = now;
	h->haveOrg = DissReadCiOrigin(ptr, h->org);
}

static void DissEnqueue(int kind, int id, bool heavy = false, int playerUserId = 0) {
	const bool want = (kind == 1) ? DissSiWanted() : DissCiWanted();
	if (!want || id <= 0 || g_dissPendingN >= kDissPendingMax) return;
	void* e = EntGet(id);
	unsigned int playerSpawnEpoch = 0;
	if (kind == 1) {
		// Caller passes an entity index (not userid); SI also captures its spawn epoch.
		if (!EntReadable(e) || DissTeam(e) != 3 || playerUserId <= 0) return;
		playerSpawnEpoch = DissPlayerLifeEpoch(playerUserId, true);
		for (int i = 0; i < g_dissPendingN; ++i) {
			if (g_dissPending[i].kind != 1) continue;
			if (g_dissPending[i].playerUserId == playerUserId
				&& g_dissPending[i].playerSpawnEpoch == playerSpawnEpoch
				&& (g_dissPending[i].id == id || g_dissPending[i].expect == e)) return;
		}
	} else {
		for (int i = 0; i < g_dissPendingN; ++i)
			if (g_dissPending[i].kind == kind && g_dissPending[i].id == id) return;
		if (kind == 2 && !EntReadable(e)) return; // caller should DissEnqueueAt(victim_*)
	}
	DissPending* p = &g_dissPending[g_dissPendingN++];
	*p = {};
	p->kind = kind;
	p->id = id;
	p->playerUserId = kind == 1 ? playerUserId : 0;
	p->playerSpawnEpoch = kind == 1 ? playerSpawnEpoch : 0;
	p->heavy = heavy;
	p->expect = (kind == 1 || kind == 2) ? e : nullptr;
	if (kind == 2) {
		if (DissReadCiOrigin(e, p->origin) || DissReadOrigin(e, p->origin))
			p->haveOrigin = true;
	} else if (DissReadOrigin(e, p->origin)) {
		p->haveOrigin = true;
	}
	const DWORD t = GetTickCount();
	const DWORD defer = (kind == 3) ? 50u : (kind == 2 ? 16u : 32u);
	p->nextAt = t + defer;
	p->bornAt = t;
	Log("dissolve: enqueue kind=%d id=%d heavy=%d origin=%d pending=%d",
		kind, id, heavy ? 1 : 0, p->haveOrigin ? 1 : 0, g_dissPendingN);
}

static void DissEnqueueAt(int kind, float x, float y, float z, bool heavy = false) {
	const bool want = (kind == 1) ? DissSiWanted() : DissCiWanted();
	if (!want || g_dissPendingN >= kDissPendingMax) return;
	for (int i = 0; i < g_dissPendingN; ++i) {
		if (g_dissPending[i].kind != kind || !g_dissPending[i].haveOrigin) continue;
		const float dx = g_dissPending[i].origin[0] - x;
		const float dy = g_dissPending[i].origin[1] - y;
		const float dz = g_dissPending[i].origin[2] - z;
		if (dx * dx + dy * dy + dz * dz <= 64.f * 64.f) return; // same death
	}
	DissPending* p = &g_dissPending[g_dissPendingN++];
	*p = {};
	p->kind = kind;
	p->id = 0;
	p->haveOrigin = true;
	p->heavy = heavy;
	p->origin[0] = x;
	p->origin[1] = y;
	p->origin[2] = z;
	const DWORD t = GetTickCount();
	p->nextAt = t + ((kind == 3) ? 50u : 16u);
	p->bornAt = t;
	Log("dissolve: enqueue kind=%d at=%.0f,%.0f,%.0f heavy=%d pending=%d",
		kind, x, y, z, heavy ? 1 : 0, g_dissPendingN);
}

static void ClientUxDissolveOnPlayerSpawn(void* ev) {
	if (!ev) return;
	const int userid = EvInt(ev, "userid");
	if (userid > 0 && DissPlayerLifeTracked(userid))
		DissPlayerLifeAdvance(userid);
}

static int DissCiHurtTake(float x, float y, float z, bool haveVictim) {
	const DWORD now = GetTickCount();
	int best = 0;
	DWORD bestAt = 0;
	float bestD = 160.f * 160.f;
	int recent = 0;
	DWORD recentAt = 0;
	int w = 0;
	for (int i = 0; i < g_dissCiHurtN; ++i) {
		DissCiHurt h = g_dissCiHurt[i];
		if ((LONG)(now - h.at) > 900) continue;
		void* e = EntGet(h.idx);
		const bool same = (e == h.ptr);
		if (same || h.haveOrg)
			g_dissCiHurt[w++] = h;
		if ((LONG)(now - h.at) > 700) continue;
		float ox = h.org[0], oy = h.org[1], oz = h.org[2];
		bool have = h.haveOrg;
		if (same) {
			float cur[3];
			if (DissReadCiOrigin(e, cur)) {
				ox = cur[0]; oy = cur[1]; oz = cur[2];
				have = true;
			}
		}
		if (!haveVictim) {
			if ((LONG)(now - h.at) <= 400 && (!recent || (LONG)(h.at - recentAt) >= 0)) {
				recent = h.idx;
				recentAt = h.at;
			}
			continue;
		}
		if (!have) continue;
		const float dx = ox - x, dy = oy - y, dz = oz - z;
		const float d = dx * dx + dy * dy + dz * dz;
		if (d > bestD) continue;
		if (!best || d < bestD - 1.f || (d <= bestD && (LONG)(h.at - bestAt) >= 0)) {
			best = h.idx; bestAt = h.at; bestD = d;
		}
	}
	g_dissCiHurtN = w;
	return haveVictim ? best : recent;
}

// Unified zombie_death path (verified listen + remote coop).
// victim = entity index; attacker = entity index (not userid).
// Sole source for corpse dissolve and no-corpse clear (CI / Witch / SI / Tank).
static void ClientUxOnZombieDeath(void* ev) {
	if (!ev) return;
	const int attacker = EvInt(ev, "attacker", 0);
	const int victim = EvInt(ev, "victim", 0);
	if (victim <= 0 || victim >= 2048) return;

	const char* cn = EntNetClassName(victim);
	if (!cn || !cn[0]) return;

	enum { kNone, kCi, kWitch, kSi } kind = kNone;
	if (IsWitchClass(cn)) kind = kWitch;
	else if (!_stricmp(cn, "Infected") || !_stricmp(cn, "C_Infected")) kind = kCi;
	else if (!_stricmp(cn, "Tank") || !_stricmp(cn, "Boomer") || !_stricmp(cn, "Hunter")
		|| !_stricmp(cn, "Smoker") || !_stricmp(cn, "Jockey") || !_stricmp(cn, "Charger")
		|| !_stricmp(cn, "Spitter"))
		kind = kSi;
	else
		return;

	const int local = EngLocal();
	const bool localKill = local > 0 && attacker == local;

	if (kind == kCi) {
		if (DissCiWanted() && localKill)
			DissEnqueue(2, victim, true);
		if (g_optClientNoCorpseCi && !ClientUxIsPlayerSlot(victim)) {
			ClientUxTrackCorpse(victim, 2500, false);
			ClientUxArmRagdollPulse();
			ClientUxArmNoCorpseDestroy();
		}
		return;
	}
	if (kind == kWitch) {
		if (DissCiWanted())
			DissEnqueue(3, victim, true);
		if (g_optClientNoCorpseCi && !ClientUxIsPlayerSlot(victim)) {
			ClientUxTrackCorpse(victim, 2500, false);
			ClientUxArmRagdollPulse();
			ClientUxArmNoCorpseDestroy();
		}
		return;
	}
	// SI / Tank: never hide player slots 1-64.
	if (DissSiWanted() && localKill) {
		PlayerInfo pi{};
		if (EngPlayerInfo(victim, &pi) && pi.userid > 0)
			DissEnqueue(1, victim, false, pi.userid);
	}
	if (g_optClientNoCorpseSi) {
		ClientUxArmRagdollPulse();
		ClientUxArmNoCorpseDestroy();
	}
}

static bool DissRagdollNet(const char* cn) {
	if (ClientUxIsClientRagdollClass(cn)) return true;
	if (!cn || !cn[0]) return false;
	if (!_stricmp(cn, "CCSRagdoll") || !_stricmp(cn, "C_CSRagdoll")) return true;
	for (const char* p = cn; *p; ++p) {
		if ((p[0] == 'r' || p[0] == 'R') && _strnicmp(p, "ragdoll", 7) == 0)
			return true;
	}
	return false;
}

static bool DissNear(const float* a, const float* b) {
	const float dx = a[0] - b[0];
	const float dy = a[1] - b[1];
	const float dz = a[2] - b[2];
	return dx * dx + dy * dy + dz * dz <= 384.f * 384.f;
}

// Hide at most ONE leftover client ragdoll near the dissolve target.
// Never hide Infected class entities here — wrong lifeState would make living commons vanish.
static bool DissHideOneRagdollNear(const float* origin, void* except, float maxDist) {
	if (!origin || !g_entlist || maxDist <= 0.f) return false;
	const float maxD2 = maxDist * maxDist;
	int hi = EntHighestIndex();
	if (hi > 2048) hi = 2048;
	int lo = hi > 64 ? hi - 64 : 1;
	if (lo < 1) lo = 1;
	int bestIdx = -1;
	void* bestE = nullptr;
	float bestD = maxD2;
	for (int i = hi; i >= lo; --i) {
		if (ClientUxIsPlayerSlot(i)) continue;
		void* e = EntGet(i);
		if (!e || e == except || !EntReadable(e) || DissIsFx(e)) continue;
		const char* cn = EntNetClassName(i);
		if (!DissRagdollNet(cn)) continue;
		if (IsCommonInfectedClass(cn) || IsWitchClass(cn)) continue;
		float o[3];
		if (!DissReadOrigin(e, o)) continue;
		const float dx = origin[0] - o[0];
		const float dy = origin[1] - o[1];
		const float dz = origin[2] - o[2];
		const float d = dx * dx + dy * dy + dz * dz;
		if (d > bestD) continue;
		bestD = d;
		bestIdx = i;
		bestE = e;
	}
	if (!bestE || bestIdx <= 0) return false;
	if (g_offEffects >= 0 && g_offEffects <= 0x4000) {
		int* fxFlags = (int*)((uint8_t*)bestE + g_offEffects);
		if (PtrCommitted(fxFlags)) *fxFlags |= kEfNoDraw;
	}
	if (g_offRenderMode >= 0 && g_offRenderMode <= 0x4000) {
		uint8_t* mode = (uint8_t*)bestE + g_offRenderMode;
		if (PtrCommitted(mode)) *mode = (uint8_t)kRenderNone;
	}
	return true;
}

static void DissHideNearOrigin(const float* origin, void* except) {
	DissHideOneRagdollNear(origin, except, 128.f);
}

static void DissArmRagPulse(const float* origin) {
	if (!origin) return;
	g_dissPulseOrg[0] = origin[0];
	g_dissPulseOrg[1] = origin[1];
	g_dissPulseOrg[2] = origin[2];
	const DWORD now = GetTickCount();
	g_dissPulseUntil = now + 450;
	g_dissPulseNextAt = now + 50;
	g_dissPulseLeft = 5;
}

static void DissPumpRagPulse(DWORD now) {
	if (g_dissPulseLeft <= 0) return;
	if ((LONG)(now - g_dissPulseUntil) >= 0) {
		g_dissPulseLeft = 0;
		return;
	}
	if ((LONG)(now - g_dissPulseNextAt) < 0) return;
	g_dissPulseNextAt = now + 80;
	--g_dissPulseLeft;
	// One hide attempt per pulse tick; stop early once a ragdoll was found.
	if (DissHideOneRagdollNear(g_dissPulseOrg, nullptr, 160.f))
		g_dissPulseLeft = 0;
}


static bool DissRagdollVt(void* e) {
	if (!e || !EntReadable(e) || g_dissRagdollVtN <= 0) return false;
	void** vt = *(void***)e;
	for (int i = 0; i < g_dissRagdollVtN; ++i)
		if (vt == g_dissRagdollVt[i]) return true;
	return false;
}


// Ragdoll only near death anchor. Never "nearest living Infected" — that is the invisible-enemy bug.
// Client cannot reliably tell Infected dead vs alive via lifeState/hp.
static int DissNearestRagAt(const float* org, float maxDist) {
	if (!org || maxDist <= 0.f || !g_entlist) return 0;
	const float maxD = maxDist * maxDist;
	int hi = EntHighestIndex();
	if (hi > 2048) hi = 2048;
	if (hi < 65) return 0;
	int best = 0;
	float bestD = maxD;
	int budget = 192; // was 768; multi-kill miss path hitch
	for (int i = hi; i >= 65 && budget > 0; --i, --budget) {
		if (ClientUxIsPlayerSlot(i)) continue;
		void* e = EntGet(i);
		if (!e) continue;
		if (!EntReadable(e) || DissIsFx(e) || DissTargetBusy(e)) continue;
		float o[3];
		if (!DissReadOrigin(e, o) && !DissReadCiOrigin(e, o)) continue;
		const float dx = o[0] - org[0], dy = o[1] - org[1], dz = o[2] - org[2];
		const float d = dx * dx + dy * dy + dz * dz;
		if (d > bestD) continue;
		const char* cn = EntNetClassName(i);
		if (!DissRagdollNet(cn) && !DissRagdollVt(e)) continue;
		if (IsCommonInfectedClass(cn) || IsWitchClass(cn)) continue;
		bestD = d;
		best = i;
	}
	return best;
}

// Like cfg: alias st "cl_destroy_ragdolls; wait 50; st".
// Must use ClientCmd_Unrestricted: ClientCmd silently drops this command even after
// UnlockConCommand (log showed option on + dissolve working, but never a successful
// UnlockCmd(cl_destroy_ragdolls) fire path that cleared ragdolls).
static void ClientUxDissolveRagCleanPump() {
	if (!g_optClientDissolveRagClean) {
		g_dissRagCleanNextAt = 0;
		return;
	}
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()
		|| !g_engine || !EngInGame()) {
		g_dissRagCleanNextAt = 0;
		return;
	}
	const DWORD now = GetTickCount();
	if (g_dissRagCleanNextAt && (LONG)(now - g_dissRagCleanNextAt) < 0)
		return;
	g_dissRagCleanNextAt = now + kDissRagCleanIntervalMs;
	ClientUxFireDestroyRagdolls();
	static int s_fireLog = 12;
	if (s_fireLog > 0) {
		--s_fireLog;
		Log("dissolve-rag-clean: Unrestricted cl_destroy_ragdolls");
	}
}

static void ClientUxDissolvePump() {
	if (!DissAnyWanted() && g_dissActiveN == 0 && g_dissPendingN == 0)
		return;
	if (!DissAnyWanted()
		|| (DissSiWanted() && g_optClientNoCorpseSi)
		|| (DissCiWanted() && g_optClientNoCorpseCi)) {
		if (g_dissActiveN || g_dissPendingN) ClientUxDissolveShutdown(true);
		return;
	}
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()
		|| !g_engine || !EngInGame() || !g_entlist) {
		if (g_dissActiveN || g_dissPendingN) ClientUxDissolveShutdown(false);
		return;
	}
	const DWORD now = GetTickCount();
	int w = 0;
	for (int i = 0; i < g_dissActiveN; ++i) {
		DissActive slot = g_dissActive[i];
		if (slot.playerUserId > 0
			&& !DissPlayerLifeCurrent(slot.playerUserId, slot.playerSpawnEpoch)) {
			// A respawn reused this player pawn. Remove the old effect without
			// restoring render values captured from its previous life.
			DissDeleteFx(slot.fx);
			continue;
		}
		const bool alive = DissIsFx(slot.fx)
			&& (slot.fxIndex <= 0 || EntGet(slot.fxIndex) == slot.fx);
		const bool sameTarget = slot.target && slot.targetIndex > 0
			&& EntGet(slot.targetIndex) == slot.target;
		const bool playerPawn = sameTarget
			&& (slot.playerUserId > 0 || ClientUxIsPlayerSlot(slot.targetIndex));
		if (!alive) {
			if (playerPawn)
				DissRestoreTarget(&slot);
			else
				DissHideTarget(&slot);
			continue;
		}
		if ((LONG)(now - slot.expireAt) >= 0) {
			if (playerPawn)
				DissRestoreTarget(&slot);
			else
				DissHideTarget(&slot);
			DissDeleteFx(slot.fx);
			continue;
		}
		// No manual Think — engine ClientThink is enough; calling it from Paint hitch.
		g_dissActive[w++] = slot;
	}
	g_dissActiveN = w;
	if (g_dissPendingN <= 0) return;
	if (!ClientUxDissolveResolve()) {
		g_dissPendingN = 0;
		return;
	}
	if (now != g_dissTick) {
		g_dissTick = now;
		g_dissTickN = 0;
	}
	if ((LONG)(now - g_dissWindowAt) > 100) {
		g_dissWindowAt = now;
		g_dissWindowN = 0;
	}
	int ciActiveN = 0;
	for (int a = 0; a < g_dissActiveN; ++a)
		if (g_dissActive[a].commonTarget) ++ciActiveN;

	struct Cand {
		int idx;
		void* ent;
		float origin[3];
		bool haveOrigin;
	};
	Cand cands[16]{};
	int nc = 0;
	int hi = EntHighestIndex();
	if (hi > 2048) hi = 2048;
	// Cand list is a bounded, typed ragdoll backup for SI/Witch. CI never pays for a wide scan here.
	bool wantCandScan = false;
	for (int i = 0; i < g_dissPendingN; ++i) {
		const DissPending& it = g_dissPending[i];
		if ((LONG)(now - it.nextAt) < 0) continue;
		if (it.kind == 1 || it.kind == 3)
			wantCandScan = true;
	}
	if (hi > 0 && wantCandScan) {
		// Plan + Necola recipe: HighestIndex tail ≤64, empty early-out, class after.
		int lo = hi > 64 ? hi - 64 : 1;
		if (lo < 1) lo = 1;
		for (int i = hi; i >= lo && nc < 16; --i) {
			if (ClientUxIsPlayerSlot(i)) continue;
			void* e = EntGet(i);
			if (!e) continue;
			if (!EntReadable(e) || DissIsFx(e) || DissTargetBusy(e)) continue;
			const char* cn = EntNetClassName(i);
			if (!DissRagdollNet(cn)) continue;
			cands[nc].idx = i;
			cands[nc].ent = e;
			cands[nc].haveOrigin = DissReadOrigin(e, cands[nc].origin);
			++nc;
		}
	}

	int pw = 0;
	for (int i = 0; i < g_dissPendingN; ++i) {
		DissPending item = g_dissPending[i];
		const DWORD lifeMs = (item.kind == 1) ? kDissSiPendingLifeMs
			: ((item.kind == 2) ? 900u : 1200u);
		const int tryCap = (item.kind == 1) ? 10 : ((item.kind == 2) ? 8 : 20);
		if ((LONG)(now - item.bornAt) > (LONG)lifeMs || item.tries >= tryCap)
			continue;
		if ((LONG)(now - item.nextAt) < 0) {
			g_dissPending[pw++] = item;
			continue;
		}
		// CI create budget before any expensive match/scan — defer only.
		if (item.kind == 2) {
			if (!DissCiWanted() || !item.haveOrigin) continue;
			if (ciActiveN >= kDissCiActiveMax
				|| g_dissActiveN >= kDissActiveMax
				|| g_dissTickN >= 1
				|| g_dissWindowN >= 1
				|| (g_dissCiLastApplyAt
					&& (LONG)(now - g_dissCiLastApplyAt) < (LONG)kDissCiMinGapMs)) {
				DWORD due = now + 40u;
				if (g_dissCiLastApplyAt) {
					const DWORD gapDue = g_dissCiLastApplyAt + kDissCiMinGapMs;
					if ((LONG)(gapDue - due) > 0) due = gapDue;
				}
				item.nextAt = due;
				g_dissPending[pw++] = item;
				continue;
			}
		}
		void* chosen = nullptr;
		int chosenIdx = 0;
		auto pickNear = [&](float maxDist) -> int {
			// Only typed ragdolls qualify; client life/health fields cannot prove a corpse.
			int best = -1;
			float bestD = maxDist * maxDist;
			if (!item.haveOrigin || maxDist <= 0.f) return -1;
			for (int c = 0; c < nc; ++c) {
				if (DissTargetBusy(cands[c].ent) || !cands[c].haveOrigin) continue;
				const float dx = item.origin[0] - cands[c].origin[0];
				const float dy = item.origin[1] - cands[c].origin[1];
				const float dz = item.origin[2] - cands[c].origin[2];
				const float d = dx * dx + dy * dy + dz * dz;
				if (d <= bestD) {
					bestD = d;
					best = c;
				}
			}
			return best;
		};
		if (item.kind == 1) {
			if (!DissSiWanted()) continue;
			// The event-time pointer is an extra guard; userid + spawn epoch catches
			// the same pointer reused for a later player life.
			if (!item.expect || item.id <= 0 || item.playerUserId <= 0
				|| !DissPlayerLifeCurrent(item.playerUserId, item.playerSpawnEpoch)) continue;
			void* pawn = EntGet(item.id);
			if (pawn != item.expect) continue; // recycled — miss rather than NODRAW living SI
			const int team = DissTeam(pawn);
			if (team == 2) continue;
			if (team == 3 && EntReadable(pawn)) {
				// Death-frame lifeState often still "alive". Only reject when the
				// same pointer looks alive well after the death enqueue (respawn reuse).
				if (DissLooksAlive(pawn, false) && (LONG)(now - item.bornAt) > 150)
					continue;
				if (!item.haveOrigin && DissReadOrigin(pawn, item.origin))
					item.haveOrigin = true;
				if (!DissTargetBusy(pawn)) {
					chosen = pawn;
					chosenIdx = item.id;
				}
			}
			// Distance-limited ragdoll backup only. No "any ragdoll" fallback.
			if (!chosen && item.haveOrigin) {
				const int best = pickNear(192.f);
				if (best >= 0) {
					chosen = cands[best].ent;
					chosenIdx = cands[best].idx;
				}
			}
		} else if (item.kind == 2) {
			// Identity only — never "nearest Infected" (picks living neighbors → invisible enemy).
			// Client lifeState cannot prove dead; trust hurt/Trace id glued to death anchor,
			// else a ragdoll at the anchor. Miss if neither.
			auto glued = [&](void* e) -> bool {
				float o[3];
				if (!DissReadCiOrigin(e, o) && !DissReadOrigin(e, o)) return false;
				const float dx = o[0] - item.origin[0];
				const float dy = o[1] - item.origin[1];
				const float dz = o[2] - item.origin[2];
				return dx * dx + dy * dy + dz * dz <= 96.f * 96.f;
			};
			int idx = 0;
			if (item.id > 0) {
				void* e0 = EntGet(item.id);
				if (e0 && (!item.expect || e0 == item.expect) && EntReadable(e0)
					&& !ClientUxIsPlayerSlot(item.id) && !DissTargetBusy(e0)) {
					const char* cn0 = EntNetClassName(item.id);
					if (IsCommonInfectedClass(cn0) && !IsWitchClass(cn0) && glued(e0))
						idx = item.id;
				}
			}
			if (idx <= 0) {
				const int hurt = DissCiHurtTake(item.origin[0], item.origin[1], item.origin[2], true);
				void* he = hurt > 0 ? EntGet(hurt) : nullptr;
				if (he && EntReadable(he) && !ClientUxIsPlayerSlot(hurt) && !DissTargetBusy(he)) {
					const char* hcn = EntNetClassName(hurt);
					if (IsCommonInfectedClass(hcn) && !IsWitchClass(hcn) && glued(he))
						idx = hurt;
				}
			}
			// Ragdoll scan only when cheap identity missed (budget already gated above).
			if (idx <= 0)
				idx = DissNearestRagAt(item.origin, 128.f);
			void* e = idx > 0 ? EntGet(idx) : nullptr;
			if (e && EntReadable(e) && !DissTargetBusy(e)) {
				chosen = e;
				chosenIdx = idx;
				item.id = idx;
				item.expect = e;
				item.heavy = true; // exact kill id / ragdoll at death — OK even if lifeState lags
			}
			if (!chosen) {
				if (item.tries < 4) {
					++item.tries;
					item.nextAt = now + 40u;
					g_dissPending[pw++] = item;
				}
				continue; // miss — do not grab a living neighbor
			}
		} else if (item.kind == 3) {
			if (!DissCiWanted()) continue;
			if (item.id > 0) {
				void* e = EntGet(item.id);
				if (EntReadable(e) && !DissTargetBusy(e)) {
					if (!item.haveOrigin && DissReadOrigin(e, item.origin))
						item.haveOrigin = true;
					chosen = e;
					chosenIdx = item.id;
				}
			}
			if (!chosen && item.haveOrigin) {
				const int best = pickNear(128.f);
				if (best >= 0) {
					chosen = cands[best].ent;
					chosenIdx = cands[best].idx;
				}
			}
		}
		// 1 new DissApply / Paint. CI also gated by kDissCiMinGapMs / kDissCiActiveMax above.
		const int tickCap = 1;
		const int windowCap = 1;
		if (chosen && g_dissActiveN < kDissActiveMax
			&& g_dissTickN < tickCap && g_dissWindowN < windowCap) {
			if (item.kind == 2 && ciActiveN >= kDissCiActiveMax) {
				item.nextAt = now + 40u;
				g_dissPending[pw++] = item;
				continue;
			}
			const bool trustExact = (item.kind == 2) ? item.heavy
				: (item.id > 0 && chosenIdx == item.id);
			if (DissApply(chosen, chosenIdx, trustExact,
				item.playerUserId, item.playerSpawnEpoch)) {
				++g_dissTickN;
				++g_dissWindowN;
				if (item.kind == 2) {
					g_dissCiLastApplyAt = now;
					++ciActiveN;
					for (int j = i + 1; j < g_dissPendingN; ++j) {
						DissPending& o = g_dissPending[j];
						if (o.kind != 2) continue;
						if (o.id > 0 && item.id > 0 && o.id == item.id) {
							o.tries = 99;
							continue;
						}
						if (!item.haveOrigin || !o.haveOrigin) continue;
						const float dx = o.origin[0] - item.origin[0];
						const float dy = o.origin[1] - item.origin[1];
						const float dz = o.origin[2] - item.origin[2];
						if (dx * dx + dy * dy + dz * dz <= 64.f * 64.f)
							o.tries = 99;
					}
				}
				continue;
			}
			DissLog("apply failed");
			if (item.kind == 2) continue; // one death → one apply attempt
		} else if (chosen) {
			g_dissPending[pw++] = item; // rate-limited: keep without burning tries
			continue;
		} else if (!chosen && item.tries == 0) {
			Log("dissolve: no target kind=%d id=%d cands=%d haveOrigin=%d",
				item.kind, item.id, nc, item.haveOrigin ? 1 : 0);
		}
		if (item.kind == 2) continue; // CI handled above (retry≤1 or drop)
		++item.tries;
		item.nextAt = now + 80u;
		if (item.tries < tryCap && (LONG)(now - item.bornAt) <= (LONG)lifeMs)
			g_dissPending[pw++] = item;
	}
	g_dissPendingN = pw;
}

static void ClientUxPaintNoCorpse() {
	const bool noCorpse = g_optClientNoCorpseSi || g_optClientNoCorpseCi;
	const bool dissHide = DissAnyWanted() && (g_noCorpseN > 0 || g_noCorpseRagLeft > 0);
	if (!noCorpse && !dissHide) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_engine || !EngInGame() || !g_entlist) return;

	const DWORD now = GetTickCount();

	int w = 0;
	for (int i = 0; i < g_noCorpseN; ++i) {
		const int ent = g_noCorpseEnt[i];
		void* expect = g_noCorpsePtr[i];
		void* e = EntGet(ent);
		const bool si = g_noCorpseIsSi[i];
		const bool expired = now > g_noCorpseUntil[i];
		if (ClientUxIsPlayerSlot(ent))
			continue;
		const char* cn = EntNetClassName(ent);
		if (ClientUxIsPlayerPawnClass(cn))
			continue;
		const bool rag = ClientUxIsClientRagdollClass(cn);
		const bool kindOff = rag
			? (!g_optClientNoCorpseSi && !g_optClientNoCorpseCi && !DissAnyWanted())
			: (si ? (!g_optClientNoCorpseSi && !DissSiWanted())
				: (!g_optClientNoCorpseCi && !DissCiWanted()));
		if (!e || e != expect || expired || kindOff || !ClientUxStillCorpse(ent, expect, si)) {
			if (e) ClientUxUnhideEnt(e);
			continue;
		}
		ClientUxHideEntHard(e, ent);
		g_noCorpseEnt[w] = ent;
		g_noCorpsePtr[w] = expect;
		g_noCorpseUntil[w] = g_noCorpseUntil[i];
		g_noCorpseIsSi[w] = si;
		++w;
	}
	g_noCorpseN = w;

	// After a death: at most 3 pulses, newest 48 slots, indices 65+. Budget ~48
	// EntNetClassName calls, not a full entlist walk.
	if (g_noCorpseRagLeft > 0 && now >= g_noCorpseRagNextAt) {
		--g_noCorpseRagLeft;
		g_noCorpseRagNextAt = now + 90;
		int hi = EntHighestIndex();
		if (hi > 2048) hi = 2048;
		if (hi >= 65) {
			int lo = (hi > 48) ? (hi - 48) : 65;
			if (lo < 65) lo = 65;
			for (int i = lo; i <= hi; ++i) {
				if (ClientUxIsPlayerSlot(i)) continue;
				const char* cn = EntNetClassName(i);
				if (!ClientUxIsClientRagdollClass(cn)) continue;
				void* e = EntGet(i);
				if (!e) continue;
				const bool infectedRag = ClientUxIsInfectedRagdollClass(cn);
				if (infectedRag) {
					if (!g_optClientNoCorpseCi && !DissCiWanted()) continue;
					ClientUxTrackCorpse(i, 2500, false);
				} else {
					if (!g_optClientNoCorpseSi && !DissSiWanted()) continue;
					ClientUxTrackCorpse(i, 2500, true);
				}
			}
		}
	}
}

static void ClientUxPaintThrowLand() {
	if (IdleSwapHudQuietActive()) return;
	if (!g_optClientThrowLand) return;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()) return;
	if (!g_paintInGame.load(std::memory_order_relaxed)) return;
	if (g_menuVisible && !g_menuParked) return;
	if (!g_trace || !g_entlist) return;
	const DWORD quietUntil = g_spawnQuietUntil.load(std::memory_order_relaxed);
	if (quietUntil && (LONG)(GetTickCount() - quietUntil) < 0) return;

	// Paint owns the fixed preview and linger snapshots. Only a selected live
	// throwable samples launch inputs or predicts. Release and linger draw the
	// last snapshot; they never trace. No launch-input sampling during linger.
	static DWORD s_lastSimAt = 0;
	static float s_land[3]{};
	static float s_path[kThrowPathMax][3]{};
	static int s_pathN = 0;
	static bool s_have = false;
	static bool s_haveLand = false;
	static unsigned s_epoch = 0;
	static int s_simWeaponHandle = 0;
	static float s_simEye[3]{}, s_simAng[3]{}, s_simVel[3]{};
	static bool s_simInputValid = false;
	static float s_lockLand[3]{};
	static float s_lockPath[kThrowPathMax][3]{};
	static int s_lockPathN = 0;
	static bool s_lockHave = false;
	static DWORD s_lockUntil = 0;
	static bool s_prevLmb = false;
	static bool s_heldThrow = false;
	static int s_throwWepKind = 0;
	static float s_landFlightSec = 0.f;

	const DWORD now = GetTickCount();
	const unsigned epoch = SiDamageEpoch();
	if (g_throwLandReset.exchange(false, std::memory_order_relaxed) || s_epoch != epoch) {
		s_epoch = epoch;
		s_have = s_haveLand = s_lockHave = s_prevLmb = s_heldThrow = s_simInputValid = false;
		s_pathN = s_lockPathN = s_simWeaponHandle = s_throwWepKind = 0;
		s_lockUntil = 0;
		s_landFlightSec = 0.f;
	}
	if (s_lockHave && (LONG)(now - s_lockUntil) >= 0) {
		s_lockHave = false;
		s_lockPathN = 0;
	}
	auto drawLocked = [&]() {
		if (g_throwLandOnAttack || g_optHideAllWorldHud || !MenuEnsureSurf()) return;
		int sw = 0, sh = 0;
		if (SurfGetScreenSize(&sw, &sh))
			ClientUxDrawThrowOverlay(s_lockLand, s_lockPath, s_lockPathN, true, sw, sh, now);
	};
	auto commitLockFromPreview = [&]() {
		if (!s_have || !s_haveLand || now - s_lastSimAt > 300u || s_lockHave) return;
		memcpy(s_lockLand, s_land, sizeof(s_lockLand));
		s_lockPathN = s_pathN;
		memcpy(s_lockPath, s_path, sizeof(s_path[0]) * s_pathN);
		s_lockHave = true;
		s_lockUntil = now + kThrowLingerMs;
		Log("throw-lock (native throw) pathN=%d", s_lockPathN);
		if (HazHudThrowNotifyWanted() && s_throwWepKind > 0)
			HazHudOnThrow(s_throwWepKind, s_lockLand, s_landFlightSec);
	};

	void* me = nullptr;
	int weaponHandle = 0;
	const int kind = ClientUxLocalThrowableKind(&me, &weaponHandle);
	if (s_heldThrow && me && ClientUxThrowAccepted(s_simWeaponHandle)) {
		commitLockFromPreview();
		s_heldThrow = false;
		s_throwWepKind = 0;
	}
	if (s_heldThrow && now - s_lastSimAt > 300u) {
		s_heldThrow = false;
		s_throwWepKind = 0;
	}
	if (kind < 1) {
		// A holster without the old weapon's native throw timer cancels the
		// armed preview, including a swap and mouse release in the same Paint.
		s_have = s_haveLand = s_simInputValid = s_prevLmb = s_heldThrow = false;
		s_pathN = s_simWeaponHandle = s_throwWepKind = 0;
		if (s_lockHave) drawLocked();
		return;
	}
	if (weaponHandle != s_simWeaponHandle) {
		// A newly selected throwable owns a fresh preview, not the previous
		// weapon's held input or four-second linger, even if its type is identical.
		s_have = s_haveLand = s_simInputValid = s_prevLmb = s_heldThrow = s_lockHave = false;
		s_lockPathN = s_pathN = s_throwWepKind = 0;
	}
	const bool lmb = (GetAsyncKeyState(VK_LBUTTON) & 0x8000) != 0;
	const bool released = !lmb && s_prevLmb;
	s_prevLmb = lmb;
	if (lmb && !s_lockHave) {
		s_heldThrow = true;
		s_throwWepKind = kind == 1 ? kHazMolotov : (kind == 3 ? kHazBileGround : 0);
	}
	if (released || (s_heldThrow && !lmb)) {
		// Wait for native acceptance on the next Paint without resimulating.
		if (s_lockHave) drawLocked();
		return;
	}
	if (s_lockHave) { drawLocked(); return; }
	if (g_throwLandOnAttack && !lmb) {
		s_have = s_haveLand = s_simInputValid = false;
		s_pathN = 0;
		return;
	}

	float ang[3]{};
	EngGetViewAngles(ang);
	float curEye[3]{}, viewOffset[3]{}, curVel[3]{};
	const bool haveEye = EntReadBlock(me, g_offOrigin, curEye, sizeof(curEye))
		&& EntReadBlock(me, g_offViewOffset, viewOffset, sizeof(viewOffset));
	const bool haveVel = EntReadBlock(me, g_offAbsVelocity, curVel, sizeof(curVel));
	if (!haveEye || !haveVel) {
		s_have = s_haveLand = s_simInputValid = false;
		return;
	}
	for (int i = 0; i < 3; ++i) curEye[i] += viewOffset[i];

	auto refreshPreview = [&]() {
		// Preserve the existing listen-host hitch gate; do not add work to a
		// frame already delayed by loading/physics. Old snapshots expire at 300 ms.
		if (g_paintLastDtMs.load(std::memory_order_relaxed) >= 60u) return;
		auto angleDelta = [](float a, float b) {
			float d = fabsf(a - b);
			return d > 180.f ? 360.f - d : d;
		};
		const float eyeD2 = (curEye[0] - s_simEye[0]) * (curEye[0] - s_simEye[0])
			+ (curEye[1] - s_simEye[1]) * (curEye[1] - s_simEye[1])
			+ (curEye[2] - s_simEye[2]) * (curEye[2] - s_simEye[2]);
		const float velD2 = (curVel[0] - s_simVel[0]) * (curVel[0] - s_simVel[0])
			+ (curVel[1] - s_simVel[1]) * (curVel[1] - s_simVel[1])
			+ (curVel[2] - s_simVel[2]) * (curVel[2] - s_simVel[2]);
		const bool inputMoved = !s_simInputValid || weaponHandle != s_simWeaponHandle
			|| angleDelta(ang[1], s_simAng[1]) >= 0.35f
			|| fabsf(ang[0] - s_simAng[0]) >= 0.35f || eyeD2 >= 1.f || velD2 >= 4.f;
		// Explicit rates refresh even stable aim; only the default retains the
		// adaptive cadence. Round up so a selected rate is an upper bound.
		const DWORD gap = g_throwLandHz ? (1000u + g_throwLandHz - 1u) / g_throwLandHz
			: (inputMoved ? 50u : 150u);
		if (s_simInputValid && now - s_lastSimAt < gap) return;
		// Use the owned fixed buffer directly; a failed prediction invalidates
		// the previous marker instead of retaining or translating it.
		s_haveLand = ClientUxPredictThrowLand(kind, me, curEye, ang, curVel,
			s_land, s_path, &s_pathN, &s_landFlightSec);
		s_have = s_pathN >= 2;
		s_simWeaponHandle = weaponHandle;
		s_lastSimAt = now;
		memcpy(s_simAng, ang, sizeof(s_simAng));
		memcpy(s_simVel, curVel, sizeof(s_simVel));
		memcpy(s_simEye, curEye, sizeof(s_simEye));
		s_simInputValid = true; // partial/failed attempts are throttled too
	};
	refreshPreview();
	if (!s_have || now - s_lastSimAt > 300u || g_optHideAllWorldHud) return;
	if (!MenuEnsureSurf()) return;
	int sw = 0, sh = 0;
	if (SurfGetScreenSize(&sw, &sh))
		ClientUxDrawThrowOverlay(s_land, s_path, s_pathN, false, sw, sh, now, s_haveLand);
}

static void RunDeferredCiTrace() {
	if (!g_pendingCiImpactScan) return;
	g_pendingCiImpactScan = false;
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn())
		return;
	const bool wantHit = g_hitDetectArmed.load() && HitModeCiAllowed();
	const bool wantDiss = DissCiWanted();
	if (!wantHit && !wantDiss)
		return;
	// Kill feedback suppresses hit FX for 400ms. Dissolve still needs the kill-shot Trace
	// so a one-pellet headshot can DissCiHurtNote the corpse.
	const bool suppressed = GetTickCount() < g_suppressCommonHitUntil;
	if (suppressed && !wantDiss)
		return;
	if (!TryCiHitTrace(g_ciTracePos))
		return;
	if (wantHit && !suppressed)
		QueueHitFeedback();
}

enum { kFxJobMax = 24 };
struct FxJob {
	uint8_t kind; // 1 = ApplyDlcFx, 2 = FireFX
	bool throttle;
	bool isKill; // FF heavy-hit style is not a kill.
	unsigned epoch;
	DWORD overlayMs;
	float x, y, z;
	DlcFx fx;
	char fireName[48];
};
// Producer fills one fixed buffer while Paint owns the other. No large stack
// array or whole-batch memcpy; the existing CS only protects publication.
static FxJob g_fxJobs[2][kFxJobMax];
static int g_fxWriteBuffer = 0;
static int g_fxJobN = 0;
static std::atomic_bool g_fxJobsPending{false};
static thread_local bool g_inFxPump = false;

static void ClearFeedbackQueuesOnMapBoundary() {
	// Jobs contain old-map entity indices/origins. Drop them atomically instead of
	// letting the first Paint of the new chapter dispatch stale FX or damage work.
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	g_feedbackQueueEpoch.fetch_add(1, std::memory_order_relaxed);
	g_lastLocalGunImpactAt = 0;
	g_fxJobN = 0;
	g_hpDropN = 0;
	g_damageEventCount = 0;
	g_fxJobsPending.store(false, std::memory_order_release);
	g_hpDropsPending.store(false, std::memory_order_release);
	g_damageEventsPending.store(false, std::memory_order_release);
	LeaveCriticalSection(&g_fxHpCs);
	LocalPlayResetHpLives();
	g_pendingCiImpactScan = false;
	g_pendingCommonHit = false;
	g_pendingCommonHitAt = 0;
	CheckpointDmgReset();
	g_ckptWitchCachedId = 0;
	g_ckptTankCachedId = 0;
	g_elimCkptHaveSample = false;
	DamageSourceHudClear();
	FriendlyFireHudClear();
	SiAggroHudClear();
	WitchRageHudClear();
	WitchHpHudClear();
	BossDmgBoardClear();
	IgniteHudClear();
	if (g_overlayClearAt)
		g_overlayBoundaryClearPending.store(true, std::memory_order_release);
}

// Pause toggle edge (Paint thread). Both directions drop queued work so stale hit/damage
// jobs never replay after the switch. Elimination baseline (g_elimCkptHaveSample) is kept.
// Drops queued hit/damage feedback and any live screen overlay. Paint thread only.
static void DiscardFeedbackWork() {
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	g_feedbackQueueEpoch.fetch_add(1, std::memory_order_relaxed);
	g_fxJobN = 0;
	g_hpDropN = 0;
	g_damageEventCount = 0;
	g_fxJobsPending.store(false, std::memory_order_release);
	g_hpDropsPending.store(false, std::memory_order_release);
	g_damageEventsPending.store(false, std::memory_order_release);
	LeaveCriticalSection(&g_fxHpCs);
	g_pendingCiImpactScan = false;
	g_pendingCommonHit = false;
	g_pendingCommonHitAt = 0;
	if (g_overlayClearAt) ClearHitOverlay();
}

static void PauseSamplingEdgePump() {
	static bool s_applied = false;
	if (s_applied == g_optPauseSampling) return;
	s_applied = g_optPauseSampling;
	DiscardFeedbackWork();
	CheckpointDmgReset();
	DamageSourceHudClear();
	FriendlyFireHudClear();
	SiAggroHudClear();
	WitchRageHudClear();
	WitchHpHudClear();
	BossDmgBoardClear();
	IgniteHudClear();
	TeamHudResetRuntimeState();
	Log("hud pause sampling: %s", s_applied ? "paused" : "resumed");
}

static void EnqueueFxJob(const FxJob& job) {
	if (g_optPauseSampling) return;
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	if (job.epoch != g_feedbackQueueEpoch.load(std::memory_order_relaxed) || g_fxJobN >= kFxJobMax) {
		LeaveCriticalSection(&g_fxHpCs);
		return;
	}
	g_fxJobs[g_fxWriteBuffer][g_fxJobN++] = job;
	g_fxJobsPending.store(true, std::memory_order_release);
	LeaveCriticalSection(&g_fxHpCs);
}

static void DrainFxQueue() {
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	int n = g_fxJobN;
	if (n <= 0) {
		g_fxJobsPending.store(false, std::memory_order_release);
		LeaveCriticalSection(&g_fxHpCs);
		return;
	}
	if (n > kFxJobMax)
		n = kFxJobMax;
	const FxJob* tmp = g_fxJobs[g_fxWriteBuffer];
	g_fxWriteBuffer ^= 1;
	g_fxJobN = 0;
	g_fxJobsPending.store(false, std::memory_order_release);
	LeaveCriticalSection(&g_fxHpCs);
	int bestKill = -1;
	for (int i = 0; i < n; ++i) {
		if (tmp[i].kind == 1 && tmp[i].isKill
			&& (bestKill < 0 || tmp[i].fx.priority >= tmp[bestKill].fx.priority))
			bestKill = i;
	}
	for (int i = 0; i < n; ++i) {
		if (tmp[i].epoch != g_feedbackQueueEpoch.load(std::memory_order_relaxed)) break;
		if (tmp[i].kind == 1)
			ApplyDlcFx(&tmp[i].fx, tmp[i].throttle, tmp[i].x, tmp[i].y, tmp[i].z,
				tmp[i].overlayMs, tmp[i].isKill, !tmp[i].isKill || i == bestKill);
		else if (tmp[i].kind == 2)
			FireFX(tmp[i].fireName, tmp[i].x, tmp[i].y, tmp[i].z);
	}
}

// Game-thread pump: CI TraceRay + delayed hit FX + overlay clear.
// Called from EngineVGui::Paint AFTER the original engine Paint.
// Never call this from the Sleep worker.
static void PumpGameThreadFeedback() {
	if (g_inFxPump) return; // Engine commands may reenter; never recycle an active batch.
	if (!g_run.load(std::memory_order_relaxed))
		return;
	if (g_optPauseSampling) {
		if (g_fxJobsPending.load(std::memory_order_acquire) || g_hpDropsPending.load(std::memory_order_acquire)
			|| DamageEventQueuePending() || g_pendingCiImpactScan || g_pendingCommonHit || g_overlayClearAt)
			DiscardFeedbackWork();
		return;
	}
	const bool fxPending = g_fxJobsPending.load(std::memory_order_acquire);
	const bool hpPending = g_hpDropsPending.load(std::memory_order_acquire);
	const bool damageEventPending = DamageEventQueuePending();
	if (!fxPending && !hpPending && !damageEventPending && !g_pendingCiImpactScan && !g_pendingCommonHit
		&& !g_overlayClearAt)
		return;
	CrashMark(kBcHit);
	static bool s_pumpLogged = false;
	if (!s_pumpLogged) {
		s_pumpLogged = true;
		Log("ci-fx pump on EngineVGui::Paint (not worker/FSN)");
	}
	if (!SkeetoFeaturesOn()) {
		// Global disable must not leave queued work making this pump hot forever.
		if (fxPending) DrainFxQueue();
		if (hpPending) DrainHpDropQueue();
		if (damageEventPending) DrainDamageEventQueue();
		g_pendingCiImpactScan = false;
		g_pendingCommonHit = false;
		g_pendingCommonHitAt = 0;
		if (g_overlayClearAt) ClearHitOverlay();
		return;
	}
	{
		struct PumpScope {
			PumpScope() { g_inFxPump = true; }
			~PumpScope() { g_inFxPump = false; }
		} scope;
		if (fxPending) DrainFxQueue();
		if (hpPending) DrainHpDropQueue();
		if (damageEventPending) DrainDamageEventQueue();
		RunDeferredCiTrace();
		FlushPendingCommonHit();
	}
	DWORD now = GetTickCount();
	PumpFeedbackOverlaySequence(now);
	if (g_overlayClearAt && (LONG)(now - g_overlayClearAt) >= 0)
		ClearHitOverlay();
}

static void AngleVectors(float pitch, float yaw, float* forward) {
	const float deg = 0.01745329251f;
	float p = pitch * deg, y = yaw * deg;
	float cp = cosf(p), sp = sinf(p), cy = cosf(y), sy = sinf(y);
	forward[0] = cp * cy;
	forward[1] = cp * sy;
	forward[2] = -sp;
}

// No Trace: only test the damaged object's direction against the Paint view.
// All HP candidates share one eye/angle sample; gun and melee keep their ranges.
static bool HpAimHitConfirm(void* ent, float maxDist, float minDot, HpAimCache& cache) {
	if (!cache.attempted) {
		cache.attempted = true;
		if (!LocalEyePos(cache.eye)) return false;
		float angles[3]{};
		EngGetViewAngles(angles);
		AngleVectors(angles[0], angles[1], cache.forward);
		cache.valid = true;
	}
	if (!cache.valid) return false;
	const float* o = (const float*)((const uint8_t*)ent + g_offOrigin);
	const float dx = o[0] - cache.eye[0], dy = o[1] - cache.eye[1], dz = o[2] + 40.f - cache.eye[2];
	const float len = sqrtf(dx * dx + dy * dy + dz * dz);
	if (!std::isfinite(len) || len < 1.f || len > maxDist) return false;
	const float dot = (dx * cache.forward[0] + dy * cache.forward[1] + dz * cache.forward[2]) / len;
	return std::isfinite(dot) && dot >= minDot;
}

static bool CkptZombieKillsReady() {
	return g_offCkptZombieKills >= 0 && g_offCkptZombieKills <= 0x4000;
}

static bool CkptReadIntField(void* e, int off, int* out) {
	if (!e || !out || off < 0 || off > 0x4000) return false;
	int* p = (int*)((uint8_t*)e + off);
	if (!PtrCommitted(p)) return false;
	*out = *p;
	return *out >= 0 && *out <= 1000000;
}

static bool CkptReadZombieKills(void* e, int out[kCkptZkN]) {
	if (!CkptZombieKillsReady() || !e || !out) return false;
	for (int i = 0; i < kCkptZkN; ++i) {
		int* p = (int*)((uint8_t*)e + g_offCkptZombieKills + i * 4);
		if (!PtrCommitted(p)) return false;
		out[i] = *p;
		if (out[i] < 0 || out[i] > 1000000) return false;
	}
	return true;
}

// Paint: local m_checkpointZombieKills deltas drive elim CI/SI/Witch/Tank counts.
static void ElimCkptPaintPump() {
	if (!g_optElim || !CkptZombieKillsReady()) {
		g_elimCkptHaveSample = false;
		return;
	}
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()
		|| !FeedbackLocalSurvivorActive() || !g_engine || !EngInGame()) {
		g_elimCkptHaveSample = false;
		return;
	}
	const int local = g_dbgLocalEnt.load(std::memory_order_relaxed);
	if (local <= 0) { g_elimCkptHaveSample = false; return; }
	void* me = EntGet(local);
	if (!EntReadable(me)) { g_elimCkptHaveSample = false; return; }
	int zk[kCkptZkN]{};
	if (!CkptReadZombieKills(me, zk)) return;
	if (!g_elimCkptHaveSample) {
		memcpy(g_elimCkptZk, zk, sizeof(zk));
		g_elimCkptHaveSample = true;
		return;
	}
	bool changed = false;
	for (int i = 0; i < kCkptZkN; ++i) {
		if (zk[i] < g_elimCkptZk[i]) {
			// Chapter/checkpoint reset: resync without crediting.
			memcpy(g_elimCkptZk, zk, sizeof(zk));
			return;
		}
		if (zk[i] == g_elimCkptZk[i]) continue;
		const int d = zk[i] - g_elimCkptZk[i];
		g_elimCkptZk[i] = zk[i];
		changed = true;
		if (i == 0) g_elimCi.fetch_add(d, std::memory_order_relaxed);
		else if (i >= 1 && i <= 6) g_elimSi.fetch_add(d, std::memory_order_relaxed);
		else if (i == 7) {
			g_elimWitch.fetch_add(d, std::memory_order_relaxed);
			g_elimSi.fetch_add(d, std::memory_order_relaxed);
		} else if (i == 8) g_elimTank.fetch_add(d, std::memory_order_relaxed);
	}
	if (changed) ElimPersistMarkChanged();
}

static void CheckpointDmgReset() {
	g_ckptDmgTankLast = -1;
	g_ckptDmgWitchLast = -1;
	g_ckptDmgHaveSample = false;
}

static bool CheckpointDmgWanted() {
	if (g_offCheckpointDamageToTank < 0 && g_offCheckpointDamageToWitch < 0)
		return false;
	return HitModeSiAllowed() || HitModeCiAllowed() || g_optClientDmgNum;
}

static bool CheckpointTankReadPos(int id, void** outEnt, float* outPos) {
	if (id <= 0 || id > 32) return false;
	if (!g_entlist || g_offTeam < 0 || g_offZombieClass < 0 || g_offLifeState < 0
		|| g_offOrigin < 0 || g_offOrigin > 0x4000)
		return false;
	void* e = EntGet(id);
	if (!EntReadable(e) || !EntNetworkable(id)) return false;
	const int* team = (const int*)((const uint8_t*)e + g_offTeam);
	const int* zc = (const int*)((const uint8_t*)e + g_offZombieClass);
	const uint8_t* life = (const uint8_t*)e + g_offLifeState;
	if (!PtrCommitted(team) || !PtrCommitted(zc) || !PtrCommitted(life)) return false;
	if (*team != 3 || *zc != 8 || *life != 0) return false;
	const float* o = (const float*)((const uint8_t*)e + g_offOrigin);
	if (!PtrCommitted(o)) return false;
	if (outEnt) *outEnt = e;
	if (outPos) { outPos[0] = o[0]; outPos[1] = o[1]; outPos[2] = o[2]; }
	return true;
}

static int CheckpointFindAliveTank(void** outEnt, float* outPos) {
	if (outEnt) *outEnt = nullptr;
	if (CheckpointTankReadPos(g_ckptTankCachedId, outEnt, outPos))
		return g_ckptTankCachedId;
	for (int i = 1; i <= 32; ++i) {
		if (!CheckpointTankReadPos(i, outEnt, outPos)) continue;
		g_ckptTankCachedId = i;
		return i;
	}
	g_ckptTankCachedId = 0;
	return 0;
}

// O(1)/O(8): cached Trace id, then g_witchId slots. Never scan EntHighestIndex here.
static bool CheckpointWitchReadPos(int id, void** outEnt, float* outPos) {
	if (id <= 0 || id >= 2048) return false;
	if (!IsWitchClass(EntNetClassName(id))) return false;
	void* e = EntGet(id);
	if (!EntReadable(e)) return false;
	if (g_offLifeStateCommon >= 0 && g_offLifeStateCommon <= 0x4000) {
		const uint8_t* life = (const uint8_t*)e + g_offLifeStateCommon;
		if (!PtrCommitted(life) || *life != 0) return false;
	}
	const int orgOff = (g_offOriginCommon >= 0 && g_offOriginCommon <= 0x4000)
		? g_offOriginCommon : g_offOrigin;
	if (orgOff < 0 || orgOff > 0x4000) return false;
	const float* o = (const float*)((const uint8_t*)e + orgOff);
	if (!PtrCommitted(o)) return false;
	if (outEnt) *outEnt = e;
	if (outPos) { outPos[0] = o[0]; outPos[1] = o[1]; outPos[2] = o[2]; }
	return true;
}

static int CheckpointFindWitchTarget(void** outEnt, float* outPos) {
	if (outEnt) *outEnt = nullptr;
	if (!g_entlist) return 0;

	if (CheckpointWitchReadPos(g_ckptWitchCachedId, outEnt, outPos))
		return g_ckptWitchCachedId;

	float eye[3]{};
	float forward[3]{};
	const bool haveAim = LocalEyePos(eye);
	if (haveAim) {
		float angles[3]{};
		EngGetViewAngles(angles);
		AngleVectors(angles[0], angles[1], forward);
	}

	int bestId = 0;
	void* bestE = nullptr;
	float bestPos[3]{};
	float bestScore = -1e30f;
	for (int i = 0; i < 8; ++i) {
		const int id = g_witchId[i];
		void* e = nullptr;
		float pos[3]{};
		if (!CheckpointWitchReadPos(id, &e, pos)) continue;
		float score = 0.f;
		if (haveAim) {
			const float dx = pos[0] - eye[0], dy = pos[1] - eye[1], dz = pos[2] + 40.f - eye[2];
			const float len = sqrtf(dx * dx + dy * dy + dz * dz);
			if (len > 1.f)
				score = (dx * forward[0] + dy * forward[1] + dz * forward[2]) / len;
		}
		if (!bestId || score > bestScore) {
			bestId = id;
			bestE = e;
			bestPos[0] = pos[0]; bestPos[1] = pos[1]; bestPos[2] = pos[2];
			bestScore = score;
		}
	}
	if (!bestId) {
		g_ckptWitchCachedId = 0;
		return 0;
	}
	g_ckptWitchCachedId = bestId;
	if (outEnt) *outEnt = bestE;
	if (outPos) { outPos[0] = bestPos[0]; outPos[1] = bestPos[1]; outPos[2] = bestPos[2]; }
	return bestId;
}

static void ClientUxDmgOnWitchEnt(int entIdx, const float* pos, int dmg) {
	if (!g_optClientDmgNum || dmg < 1 || !pos) return;
	ClientUxDmgPush(entIdx, dmg, pos, 56.f);
}

// Paint / game thread. O(1) when options off; two int reads on local survivor when on.
// Positive local deltas drive Tank/Witch hit FX and damage numbers (own hits only).
static void CheckpointDmgPaintPump() {
	if (!CheckpointDmgWanted()) {
		if (g_ckptDmgHaveSample) CheckpointDmgReset();
		return;
	}
	if (!g_run.load(std::memory_order_relaxed) || !SkeetoFeaturesOn()
		|| !FeedbackLocalSurvivorActive() || !g_engine || !EngInGame()) {
		if (g_ckptDmgHaveSample) CheckpointDmgReset();
		return;
	}
	const int local = g_dbgLocalEnt.load(std::memory_order_relaxed);
	if (local <= 0) { CheckpointDmgReset(); return; }
	void* me = EntGet(local);
	if (!EntReadable(me)) { CheckpointDmgReset(); return; }

	int tankDmg = -1, witchDmg = -1;
	if (g_offCheckpointDamageToTank >= 0 && g_offCheckpointDamageToTank <= 0x4000) {
		int* p = (int*)((uint8_t*)me + g_offCheckpointDamageToTank);
		if (!PtrCommitted(p)) return;
		tankDmg = *p;
		if (tankDmg < 0 || tankDmg > 1000000) return;
	}
	if (g_offCheckpointDamageToWitch >= 0 && g_offCheckpointDamageToWitch <= 0x4000) {
		int* p = (int*)((uint8_t*)me + g_offCheckpointDamageToWitch);
		if (!PtrCommitted(p)) return;
		witchDmg = *p;
		if (witchDmg < 0 || witchDmg > 1000000) return;
	}

	if (!g_ckptDmgHaveSample) {
		g_ckptDmgTankLast = tankDmg;
		g_ckptDmgWitchLast = witchDmg;
		g_ckptDmgHaveSample = true;
		return;
	}
	// Reuse the HP-attribution timestamps: bullet_impact and melee/chainsaw
	// sampling, never weapon_fire. Only gate Hit FX; always advance totals below.
	bool bossHitAllowed = true;
	if (g_optBossHitActiveOnly && (HitModeSiAllowed() || HitModeCiAllowed())) {
		const DWORD now = GetTickCount();
		const DWORD gunAt = g_lastLocalGunImpactAt.load(std::memory_order_relaxed);
		const DWORD meleeUntil = g_meleeAttackUntil.load(std::memory_order_relaxed);
		bossHitAllowed = (gunAt && now - gunAt < 180u)
			|| (meleeUntil && (LONG)(meleeUntil - now) >= 0);
	}

	if (tankDmg >= 0 && g_ckptDmgTankLast >= 0 && tankDmg > g_ckptDmgTankLast) {
		const int delta = tankDmg - g_ckptDmgTankLast;
		void* tankEnt = nullptr;
		float pos[3]{};
		const int tankId = CheckpointFindAliveTank(&tankEnt, pos);
		if (tankId > 0) {
			if (g_optClientDmgNum)
				ClientUxDmgOnSi(tankEnt, tankId, delta);
			if (bossHitAllowed && (HitModeSiAllowed() || HitModeCiAllowed()))
				FeedbackSiHit(pos[0], pos[1], pos[2] + 40.f);
			if (g_hitDetectLogLeft > 0) {
				--g_hitDetectLogLeft;
				Log("ckpt-tank dmg=%d id=%d total=%d hit_allowed=%d active_only=%d",
					delta, tankId, tankDmg, bossHitAllowed ? 1 : 0, g_optBossHitActiveOnly ? 1 : 0);
			}
		}
	}
	if (witchDmg >= 0 && g_ckptDmgWitchLast >= 0 && witchDmg > g_ckptDmgWitchLast) {
		const int delta = witchDmg - g_ckptDmgWitchLast;
		void* witchEnt = nullptr;
		float pos[3]{};
		const int witchId = CheckpointFindWitchTarget(&witchEnt, pos);
		if (witchId > 0) {
			ClientUxDmgOnWitchEnt(witchId, pos, delta);
			if (bossHitAllowed && (HitModeSiAllowed() || HitModeCiAllowed()))
				FeedbackCi("hit", true, false, true, pos[0], pos[1], pos[2] + 40.f);
			if (g_hitDetectLogLeft > 0) {
				--g_hitDetectLogLeft;
				Log("ckpt-witch dmg=%d id=%d total=%d hit_allowed=%d active_only=%d",
					delta, witchId, witchDmg, bossHitAllowed ? 1 : 0, g_optBossHitActiveOnly ? 1 : 0);
			}
		} else {
			// No cached Witch id: place FX at recent local impact or eye. Never scan entlist.
			float posFb[3]{};
			bool havePos = false;
			if (g_haveImpactPos) {
				posFb[0] = g_lastImpactPos[0];
				posFb[1] = g_lastImpactPos[1];
				posFb[2] = g_lastImpactPos[2];
				havePos = true;
			} else if (LocalEyePos(posFb)) {
				posFb[2] += 8.f;
				havePos = true;
			}
			if (havePos) {
				ClientUxDmgOnWitchEnt(0, posFb, delta);
				if (bossHitAllowed && (HitModeSiAllowed() || HitModeCiAllowed()))
					FeedbackCi("hit", true, false, true, posFb[0], posFb[1], posFb[2] + 40.f);
			}
		}
	}

	// Chapter/reset can drop totals; resync without firing.
	if (tankDmg >= 0) g_ckptDmgTankLast = tankDmg;
	if (witchDmg >= 0) g_ckptDmgWitchLast = witchDmg;
}

// SI hit, world HP bar and damage numbers share this attributed HP update.
static void OnSiHealthDecreased(void* ent, int objectId, int oldHp, int newHp, bool gun, HpAimCache& aim) {
	if (objectId <= 0 || objectId > 64) return;
	if (!EntReadable(ent) || g_offOrigin < 0 || g_offOrigin > 0x4000) return;
	if (!PtrCommitted((uint8_t*)ent + g_offOrigin)) return;
	// Gun follow-ups still require the cheap cone; a bar lock is not ownership.
	if (gun && !HpAimHitConfirm(ent, 5000.f, 0.93f, aim)) return;
	const DWORD now = GetTickCount();
	const int dmgAmt = oldHp - newHp;
	auto showBar = [&]() {
		if (!g_optClientInfectedHp) return;
		PlayerInfo pi{};
		const int uid = EngPlayerInfo(objectId, &pi) && pi.userid > 0 ? pi.userid : 0;
		LocalPlayNotifySiHp(ent, objectId, newHp, uid);
	};
	const bool locked = g_hpLocalSiEnt == objectId && g_hpLocalSiEntity == ent
		&& g_hpLocalSiGeneration == g_hpEntityGeneration[objectId].load(std::memory_order_relaxed)
		&& g_hpLocalSiUntil && (LONG)(g_hpLocalSiUntil - now) >= 0;
	if (!locked) {
		if (now - g_lastHitFeedbackAt < 70 && !g_optClientDmgNum) return;
		if (!gun && !HpAimHitConfirm(ent, 110.f, 0.90f, aim)) return;
		if (g_optClientInfectedHp)
			LocalPlayMarkLocalSi(objectId, ent, g_hpEntityGeneration[objectId].load(std::memory_order_relaxed));
	}
	WorldNoticeTrackAirborneEntity(ent, objectId);
	showBar(); // Notification alone never renews the lock.
	int zc = 0;
	if (g_offZombieClass >= 0 && g_offZombieClass <= 0x4000) {
		const int* pzc = (const int*)((const uint8_t*)ent + g_offZombieClass);
		if (PtrCommitted(pzc)) zc = *pzc;
	}
	// Tank hit+dmg owned by local m_checkpointDamageToTank when available.
	const bool tankCkpt = (zc == 8 && g_offCheckpointDamageToTank >= 0);
	if (!tankCkpt) {
		ClientUxDmgOnSi(ent, objectId, dmgAmt, newHp);
		if (HitModeSiAllowed()) {
			const float* o = (const float*)((const uint8_t*)ent + g_offOrigin);
			FeedbackSiHit(o[0], o[1], o[2] + 40.f);
		}
	}
	if (g_hitDetectLogLeft > 0) {
		--g_hitDetectLogLeft;
		Log("si-hit hp id=%d gun=%d locked=%d tankCkpt=%d", objectId, gun ? 1 : 0, locked ? 1 : 0,
			tankCkpt ? 1 : 0);
	}
}

static void DrainHpDropQueue() {
	HpDropJob tmp[kHpDropMax];
	HpAimCache aim{};
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	int n = g_hpDropN;
	if (n <= 0) {
		g_hpDropsPending.store(false, std::memory_order_release);
		LeaveCriticalSection(&g_fxHpCs);
		return;
	}
	if (n > kHpDropMax)
		n = kHpDropMax;
	memcpy(tmp, g_hpDrops, sizeof(HpDropJob) * (size_t)n);
	g_hpDropN = 0;
	g_hpDropsPending.store(false, std::memory_order_release);
	LeaveCriticalSection(&g_fxHpCs);
	if (!g_engine || !EngInGame() || !SkeetoFeaturesOn() || !FeedbackLocalSurvivorActive())
		return;
	for (int i = 0; i < n; ++i) {
		const HpDropJob& j = tmp[i];
		if (j.epoch != g_feedbackQueueEpoch.load(std::memory_order_relaxed)) break;
		if ((DWORD)(GetTickCount() - j.sampledAt) > 400u) continue;
		if (j.localEnt != g_dbgLocalEnt.load(std::memory_order_relaxed)) continue;
		if (j.generation != g_hpEntityGeneration[j.objectId].load(std::memory_order_relaxed)) continue;
		if (j.hpSpawn != g_hpLifeSpawn[j.objectId].load(std::memory_order_acquire)) continue;
		void* e = EntGet(j.objectId);
		// Compare with the recv object captured at enqueue, not a second identical
		// lookup at drain. Pointer equality alone cannot prove a spawn serial.
		if (e != j.entity || !EntReadable(e)) continue;
		if (j.team >= 0 && g_offTeam >= 0 && g_offTeam <= 0x4000) {
			int* pt = (int*)((uint8_t*)e + g_offTeam);
			if (!PtrCommitted(pt) || *pt != j.team) continue;
		}
		if (HitModeSiAllowed() || g_optClientInfectedHp || g_optClientDmgNum || WorldNoticeAirborneTrackingWanted())
			OnSiHealthDecreased(e, j.objectId, j.oldHp, j.newHp, j.gun != 0, aim);
	}
}

static bool DamageEventReadTeam(int ent, int* team) {
	if (!team || ent <= 0 || ent > 64 || g_offTeam < 0 || g_offTeam > 0x4000) return false;
	void* player = EntGet(ent);
	if (!EntReadable(player)) return false;
	int* field = (int*)((uint8_t*)player + g_offTeam);
	if (!PtrCommitted(field)) return false;
	*team = *field;
	return true;
}

static void DrainDamageEventQueue(bool allowChapterSettle) {
	if (!allowChapterSettle && g_engine && SkeetoFeaturesOn()
		&& (!EngInGame() || EngDrawingLoading())) return;
	DamageEventRecord events[kDamageEventQueueMax]{};
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	int count = g_damageEventCount;
	if (count > kDamageEventQueueMax) count = kDamageEventQueueMax;
	if (count > 0)
		memcpy(events, g_damageEvents, sizeof(DamageEventRecord) * (size_t)count);
	g_damageEventCount = 0;
	g_damageEventsPending.store(false, std::memory_order_release);
	LeaveCriticalSection(&g_fxHpCs);
	if (count <= 0 || !g_engine || !SkeetoFeaturesOn()) return;

	const DWORD now = GetTickCount();
	const int localEnt = EngLocal();
	int localTeam = -1;
	DamageEventReadTeam(localEnt, &localTeam);
	for (int i = 0; i < count; ++i) {
		const DamageEventRecord& event = events[i];
		if (event.epoch != g_feedbackQueueEpoch.load(std::memory_order_relaxed)) continue;
		if ((DWORD)(now - event.sampledAt) > 5000u) continue;
		const int victimEnt = EngPlayerForUserID(event.victimUserId);
		if (victimEnt <= 0 || victimEnt > 64) continue;
		PlayerInfo victimInfo{};
		if (!EngPlayerInfo(victimEnt, &victimInfo) || victimInfo.userid != event.victimUserId) continue;
		int victimTeam = -1;
        if (event.siDeath) {
            if (g_optClientDmgNum) ClientUxDmgConfirmDeath(victimEnt);
            continue;
        }
		DamageEventReadTeam(victimEnt, &victimTeam);

		const int attackerEnt = event.attackerEntId;
		int attackerTeam = -1, attackerUserId = 0;
		PlayerInfo attackerInfo{};
		if (attackerEnt > 0 && attackerEnt <= 64
			&& EngPlayerInfo(attackerEnt, &attackerInfo) && attackerInfo.userid > 0) {
			attackerUserId = attackerInfo.userid;
			DamageEventReadTeam(attackerEnt, &attackerTeam);
		}

		const bool friendlyFire = skeeto_damage::IsFriendlyFireDamage(
			victimEnt, victimTeam, attackerEnt, attackerTeam, event.damage);
		if (friendlyFire && g_optChapStats) {
			if (attackerUserId > 0) ChapStatsBumpDamage(attackerUserId, event.damage);
			if (victimInfo.userid > 0) ChapStatsBumpTakenDamage(victimInfo.userid, event.damage);
		}
		if (friendlyFire && g_optWorldFriendlyFire && victimEnt == localEnt)
			WorldNoticeSetFriendlyFire(attackerEnt);
		if (friendlyFire && g_optFf && attackerEnt == localEnt
			&& FeedbackLocalSurvivorActive()
			&& FeedbackFriendlyDamageEventAllowed(localEnt, localTeam, victimEnt,
				victimTeam, attackerEnt, event.damage)) {
			float wx = 0.f, wy = 0.f, wz = 0.f;
			void* victim = EntGet(victimEnt);
			if (EntReadable(victim) && g_offOrigin >= 0 && g_offOrigin <= 0x4000
				&& PtrCommitted((uint8_t*)victim + g_offOrigin)) {
				const float* origin = (const float*)((uint8_t*)victim + g_offOrigin);
				if (std::isfinite(origin[0]) && std::isfinite(origin[1]) && std::isfinite(origin[2])) {
					wx = origin[0]; wy = origin[1]; wz = origin[2] + 40.f;
				}
			}
			FeedbackFf(event.damage, wx, wy, wz);
			if (g_hitDetectLogLeft > 0) {
				--g_hitDetectLogLeft;
				Log("ff-event attacker=%d victim=%d/%d damage=%d",
					localEnt, event.victimUserId, victimEnt, event.damage);
			}
		}
		if (g_optDamageSourceHud && skeeto_damage::DamageSourceHudAccepts(
			g_damageSourceHudMode, localEnt, localTeam, victimEnt, victimTeam,
			attackerEnt, attackerTeam, event.damage))
			DamageSourceHudOnEvent(attackerEnt, event.damage);
		if (skeeto_damage::IsLocalFriendlyFireDamage(localEnt, victimEnt, victimTeam,
			attackerEnt, attackerTeam, event.damage) && FeedbackLocalSurvivorActive()) {
			if (g_optWorldFriendlyFireDmgNum) ClientUxDmgOnFriendlyFire(victimEnt, event.damage);
			if (g_optFriendlyFireHud) FriendlyFireHudOnEvent(victimEnt, event.damage);
		}
	}
}

struct FeedbackMeleeSample {
	int localEnt = 0;
	int weaponHandle = 0;
	int weaponKind = TW_None;
	bool prevLmb = false;
};
static FeedbackMeleeSample g_feedbackMeleeSample;

// Only an active survivor's melee swing / held chainsaw opens the window.
// Classify on full weapon-handle changes (including serial), never scan slots.
static void Sample() {
	// fable5/1.4.6: entity Sample must not run on the Sleep worker.
	if (g_paintTid && GetCurrentThreadId() != g_paintTid)
		return;
	const bool needMeleeWindow = NeedHealthProxyWork() || g_optClientInfectedHp || g_optClientDmgNum;
	if (!needMeleeWindow || !SkeetoFeaturesOn() || !FeedbackLocalSurvivorActive()) {
		if (g_feedbackMeleeSample.localEnt || g_hpLocalSiEnt || g_meleeAttackUntil.load(std::memory_order_relaxed)) {
			g_meleeAttackUntil = 0;
			g_hpLocalSiEnt = 0;
			g_hpLocalSiEntity = nullptr;
			g_hpLocalSiUntil = 0;
			g_feedbackMeleeSample = FeedbackMeleeSample{};
		}
		return;
	}
	const bool lmb = (GetAsyncKeyState(VK_LBUTTON) & 0x8000) != 0;
	const DWORD meleeUntil = g_meleeAttackUntil.load(std::memory_order_relaxed);
	if (meleeUntil && (LONG)(GetTickCount() - meleeUntil) > 0) g_meleeAttackUntil = 0;
	if (!lmb && !g_meleeAttackUntil.load(std::memory_order_relaxed)) {
		g_feedbackMeleeSample.prevLmb = false;
		return; // Idle input needs no entity or weapon query.
	}
	const int local = g_dbgLocalEnt.load(std::memory_order_relaxed);
	int handle = 0;
	EntRead(EntGet(local), g_offActiveWeapon, &handle);
	if (local != g_feedbackMeleeSample.localEnt || handle != g_feedbackMeleeSample.weaponHandle) {
		g_meleeAttackUntil = 0;
		g_feedbackMeleeSample.localEnt = local;
		g_feedbackMeleeSample.weaponHandle = handle;
		const int weapon = EntIndexFromHandle(handle);
		g_feedbackMeleeSample.weaponKind = weapon > 0
			? TeamHudWepKind(EntNetClassName(weapon)) : TW_None;
	}
	const int kind = g_feedbackMeleeSample.weaponKind;
	if (g_paintGameUiVisible.load(std::memory_order_relaxed) || (g_menuVisible && !g_menuParked)) {
		g_meleeAttackUntil = 0;
	} else if (lmb && (kind == TW_Saw || (kind == TW_Melee && !g_feedbackMeleeSample.prevLmb))) {
		g_meleeAttackUntil = GetTickCount() + 400;
	}
	g_feedbackMeleeSample.prevLmb = lmb;
}

static void ResetHealthCache() {
	g_meleeAttackUntil = 0;
	g_lastLocalGunImpactAt = 0;
	g_hpLocalSiEnt = 0;
	g_hpLocalSiEntity = nullptr;
	g_hpLocalSiUntil = 0;
	g_feedbackMeleeSample = FeedbackMeleeSample{};
	memset(g_lastHealth, 0, sizeof(g_lastHealth));
	memset(g_healthInit, 0, sizeof(g_healthInit));
	memset(g_localAirHitAt, 0, sizeof(g_localAirHitAt));
	g_hitDetectArmed = false;
	g_hitDetectEnableAt = GetTickCount() + 4000;
	g_suppressCommonHitUntil = 0;
	g_pendingCommonHit = false;
	g_pendingCommonHitAt = 0;
	g_pendingCiImpactScan = false;
	g_ciStreak = 0;
	g_siStreak = 0;
	g_ciStreakLastKillAt = 0;
	g_siStreakLastKillAt = 0;
	Log("recv-hit arm in 4s (hooks=%d orig=%p)", g_healthProxyHooks, (void*)g_origHealthProxy);
}

static void FireParticle(const char* effectName, float x, float y, float z, bool worldSpace) {
	if (!SkeetoFeaturesOn()) return;
	if (!effectName || !effectName[0]) return;
	// JSON permits one primary plus up to eight extra particles. At the 70 ms hit
	// cadence a pathological pack could otherwise submit 100+ systems/s and make
	// long-lived effects accumulate. Normal one/two-particle presets stay below
	// this guard; only excess combat dispatches are dropped.
	static DWORD s_budgetAt = 0;
	static int s_budgetN = 0;
	const DWORD now = GetTickCount();
	if (!s_budgetAt || now - s_budgetAt >= 1000u) {
		s_budgetAt = now;
		s_budgetN = 0;
	}
	if (s_budgetN >= 32) return;
	++s_budgetN;
	if (!g_dispatch || !IsExec((void*)g_dispatch)) {
		if (g_feedbackLogLeft > 0) {
			--g_feedbackLogLeft;
			Log("particle SKIP dispatch=null name=%s", effectName);
		}
		return;
	}
	// Combat Dispatch: do not PrecacheParticleSystem here (MDL/datacache). Names were
	// precached at connect/loading.
	if (worldSpace) {
		g_fxOrigin[0] = x; g_fxOrigin[1] = y; g_fxOrigin[2] = z;
		g_fxAngles[0] = 0.f; g_fxAngles[1] = 270.f; g_fxAngles[2] = 0.f;
	} else {
		g_fxOrigin[0] = 0.f; g_fxOrigin[1] = 0.f; g_fxOrigin[2] = 0.f;
		g_fxAngles[0] = 0.f; g_fxAngles[1] = 0.f; g_fxAngles[2] = 0.f;
	}
	g_dispatch(effectName, g_fxOrigin, g_fxAngles, 2, 0, 0);
	if (g_feedbackLogLeft > 0) {
		--g_feedbackLogLeft;
		Log("particle '%s' world=%d at %.0f %.0f %.0f", effectName, worldSpace ? 1 : 0, x, y, z);
	}
}

static bool StartFeedbackOverlay(const DlcFx* fx, DWORD defaultOverlayMs, DWORD now) {
	if (!g_optIcon || !fx) return false;
	if (!fx->overlay[0] && fx->overlaySequenceCount <= 0) return false;

	g_overlaySequenceCount = 0;
	g_overlaySequenceIndex = 0;
	g_overlaySequenceStartAt = 0;
	g_overlaySequenceStepMs = 0;

	const char* first = fx->overlay;
	DWORD stepMs = 0;
	if (fx->overlaySequenceCount > 0) {
		g_overlaySequenceCount = fx->overlaySequenceCount;
		if (g_overlaySequenceCount > kDlcMaxOverlaySequence)
			g_overlaySequenceCount = kDlcMaxOverlaySequence;
		for (int i = 0; i < g_overlaySequenceCount; ++i) {
			strncpy(g_overlaySequence[i], fx->overlaySequence[i], sizeof(g_overlaySequence[i]) - 1);
			g_overlaySequence[i][sizeof(g_overlaySequence[i]) - 1] = 0;
		}
		first = g_overlaySequence[0];
		stepMs = fx->overlayStepMs > 0 ? (DWORD)fx->overlayStepMs : 40u;
		if (stepMs < 16u) stepMs = 16u;
		if (stepMs > 1000u) stepMs = 1000u;
		// The overlay owner has a hard five-second lifetime. Keep every accepted
		// sequence playable within that same bound instead of silently clearing
		// a long-step sequence before it reaches its final entry.
		const DWORD maxStepMs = 5000u / (DWORD)g_overlaySequenceCount;
		if (stepMs > maxStepMs) stepMs = maxStepMs;
		g_overlaySequenceStartAt = now;
		g_overlaySequenceStepMs = stepMs;
	}
	if (!first || !first[0]) {
		g_overlaySequenceCount = 0;
		return false;
	}

	UnlockOverlayCommand();
	char cmd[160]{};
	snprintf(cmd, sizeof(cmd), "r_screenoverlay %s", first);
	EngClientCmd(cmd);

	DWORD clearMs = (fx->overlayMs > 0) ? (DWORD)fx->overlayMs : defaultOverlayMs;
	if (g_overlaySequenceCount > 0) {
		const DWORD sequenceMs = stepMs * (DWORD)g_overlaySequenceCount;
		if (clearMs < sequenceMs) clearMs = sequenceMs;
	}
	if (clearMs < 40u) clearMs = 40u;
	if (clearMs > 5000u) clearMs = 5000u;
	g_overlayClearAt = now + clearMs;
	return true;
}

static void PumpFeedbackOverlaySequence(DWORD now) {
	if (g_overlaySequenceCount <= 1 || !g_overlaySequenceStartAt || !g_overlaySequenceStepMs)
		return;
	DWORD elapsed = now - g_overlaySequenceStartAt;
	int target = (int)(elapsed / g_overlaySequenceStepMs);
	if (target >= g_overlaySequenceCount) target = g_overlaySequenceCount - 1;
	if (target <= g_overlaySequenceIndex) return;
	// Low FPS skips directly to the correct frame instead of issuing a burst of
	// stale commands. At most one engine command is sent per Paint.
	g_overlaySequenceIndex = target;
	UnlockOverlayCommand();
	char cmd[160]{};
	snprintf(cmd, sizeof(cmd), "r_screenoverlay %s", g_overlaySequence[target]);
	EngClientCmd(cmd);
}

static void ApplyDlcFx(const DlcFx* fx, bool throttle, float wx, float wy, float wz,
	DWORD defaultOverlayMs, bool isKill, bool overlayAndSound) {
	if (!SkeetoFeaturesOn()) return;
	if (!fx || !fx->used) return;
	if (!g_optSound && !g_optIcon) return;
	if (!g_inFxPump) {
		FxJob job{};
		job.kind = 1;
		job.throttle = throttle;
		job.isKill = isKill;
		job.epoch = g_feedbackQueueEpoch.load(std::memory_order_relaxed);
		job.overlayMs = defaultOverlayMs;
		job.x = wx; job.y = wy; job.z = wz;
		job.fx = *fx;
		EnqueueFxJob(job);
		return;
	}
	DWORD now = GetTickCount();
	if (throttle && now - g_lastHitFeedbackAt < 70)
		return;
	g_lastHitFeedbackAt = now;

	// overlay is always fullscreen (r_screenoverlay). world:true only affects particle
	// spawn coords — do NOT gate overlay on worldSpace (SI hit can have both).
	if (overlayAndSound) StartFeedbackOverlay(fx, defaultOverlayMs, now);
	if (g_optIcon && fx->particle[0])
		FireParticle(fx->particle, wx, wy, wz, fx->worldSpace);
	if (g_optIcon) {
		for (int i = 0; i < fx->particleExtraCount; ++i) {
			if (fx->particleExtra[i][0])
				FireParticle(fx->particleExtra[i], wx, wy, wz, fx->worldSpace);
		}
	}
	char snd[96]{};
	const bool haveSnd = overlayAndSound && g_optSound && DlcPickSound(fx, snd, sizeof(snd));
	if (haveSnd)
		PlayHitSound(snd);

	if (g_feedbackLogLeft > 0) {
		--g_feedbackLogLeft;
		Log("dlc-fx ov=%s ovSeq=%d pt=%s extras=%d snd=%s sndPool=%d pri=%d world=%d ovMs=%d",
			fx->overlay, fx->overlaySequenceCount, fx->particle, fx->particleExtraCount,
			haveSnd ? snd : "-", fx->soundExtraCount, fx->priority,
			fx->worldSpace ? 1 : 0,
			fx->overlayMs > 0 ? fx->overlayMs : (int)defaultOverlayMs);
	}
}

static void ClearHitOverlay() {
	UnlockOverlayCommand();
	EngClientCmd("r_screenoverlay \"\"");
	g_overlayClearAt = 0;
	g_overlaySequenceCount = 0;
	g_overlaySequenceIndex = 0;
	g_overlaySequenceStartAt = 0;
	g_overlaySequenceStepMs = 0;
}

static bool IsMeleeWeaponName(const char* w) {
	if (!w || !w[0]) return false;
	if (!_stricmp(w, "melee") || !_stricmp(w, "weapon_melee") || !_stricmp(w, "chainsaw")
		|| !_stricmp(w, "weapon_chainsaw"))
		return true;
	if (strstr(w, "melee") || strstr(w, "Melee")) return true;
	static const char* kMelee[] = {
		"katana", "fireaxe", "machete", "crowbar", "cricket_bat", "baseball_bat",
		"electric_guitar", "frying_pan", "golfclub", "pitchfork", "shovel",
		"tonfa", "knife", "riotshield", "guitar", "pan", "bat",
		nullptr
	};
	for (int i = 0; kMelee[i]; ++i) {
		if (!_stricmp(w, kMelee[i]))
			return true;
	}
	return false;
}

static bool WeaponIsMelee(const char* wpn) {
	return wpn && wpn[0] && IsMeleeWeaponName(wpn);
}

// Prefer networked melee_kill stamp; infected_death often lacks a usable weapon string.
static bool EventWeaponIsMelee(void* ev) {
	const DWORD nowMk = GetTickCount();
	if (g_meleeKillAt && (nowMk - g_meleeKillAt) < 250u && g_meleeKillUid > 0) {
		int atk = EvInt(ev, "attacker", 0);
		if (atk <= 0) atk = EvInt(ev, "userid", 0);
		if (atk > 0 && atk == g_meleeKillUid)
			return true;
	}
	const char* wpn = EvStr(ev, "weapon");
	if (WeaponIsMelee(wpn))
		return true;
	if (wpn && wpn[0]) {
		// Named firearm / explosive — trust the event.
		if (!_stricmp(wpn, "world") || !_stricmp(wpn, "player") || !_stricmp(wpn, "entityflame")
			|| !_stricmp(wpn, "inferno") || !_stricmp(wpn, "prop_minigun") || !_stricmp(wpn, "prop_mounted_machine_gun"))
			return false;
		// Non-empty non-melee string (smg, rifle, ...) > not melee.
		if (!IsMeleeWeaponName(wpn))
			return false;
	}
	if (g_offActiveWeapon < 0 || g_offActiveWeapon > 0x4000)
		return false;
	const int local = EngLocal();
	if (local <= 0) return false;
	void* me = EntGet(local);
	if (!EntReadable(me)) return false;
	int* ph = (int*)((uint8_t*)me + g_offActiveWeapon);
	if (!PtrCommitted(ph)) return false;
	const int idx = EntIndexFromHandle(*ph);
	if (idx <= 0) return false;
	const int k = TeamHudWepKind(EntNetClassName(idx));
	return k == TW_Melee || k == TW_Saw;
}

static bool VictimWasAirborne(int ve, bool jockey) {
	if (ve <= 0 || ve >= 65) return false;
	const DWORD now = GetTickCount();
	const bool recentAttackAirHit = g_localAirHitAt[ve] != 0
		&& (now - g_localAirHitAt[ve] <= 250u);
	void* victim = EntGet(ve);
	if (!EntReadable(victim) || g_offLifeState < 0 || g_offLifeState > 0x4000)
		return recentAttackAirHit;
	if (jockey) {
		// Replicated base sequences are not yet a verified Jockey attack signal.
		if (g_offFlags < 0 || g_offFlags > 0x4000) return recentAttackAirHit;
		const int* flags = (const int*)((const uint8_t*)victim + g_offFlags);
		return (PtrCommitted(flags) && ((*flags & 1) == 0)) || recentAttackAirHit;
	}
	const unsigned char* lifeState = (const unsigned char*)victim + g_offLifeState;
	if (!PtrCommitted(lifeState) || *lifeState != 0)
		// Hunter death can clear live flags before player_death reaches us; prefer
		// its ability state or the preceding qualified hurt snapshot.
		return WorldNoticeReadAttackLeap(victim, 3) || recentAttackAirHit;
	if (g_offFlags < 0 || g_offFlags > 0x4000)
		return recentAttackAirHit;
	const int* flags = (const int*)((const uint8_t*)victim + g_offFlags);
	if (!PtrCommitted(flags)) return recentAttackAirHit;
	// A confirmed live ground contact cancels a preceding sample.  While still
	// airborne, accept the live attack state or the very recent hurt snapshot in
	// case the death transition already cleared that state before player_death.
	if ((*flags & 1) != 0) return false;
	return WorldNoticeReadAttackLeap(victim, 3) || recentAttackAirHit;
}

void FireFX(const char* name, float x, float y, float z) {
	if (!SkeetoFeaturesOn()) return;
	// Special SI kill FX: DIY dual channel.
	// - particle > always world-space (victim origin)
	// - overlay > screen overlay only if JSON sets a real overlay path
	//   (leave empty when material is SpriteCard particle sheet)
	if (!g_optKillFx) return;
	if (!name || !name[0]) return;
	if (!g_inFxPump) {
		FxJob job{};
		job.kind = 2;
		job.epoch = g_feedbackQueueEpoch.load(std::memory_order_relaxed);
		job.x = x; job.y = y; job.z = z;
		strncpy(job.fireName, name, sizeof(job.fireName) - 1);
		EnqueueFxJob(job);
		return;
	}

	DlcFx fx{};
	const char* effect = name;
	char snd[96]{};
	bool haveSnd = false;
	if (DlcResolveNamed("fx", name, &fx)) {
		if (fx.particle[0])
			effect = fx.particle;
		else
			effect = nullptr; // JSON explicitly disabled particle
		haveSnd = g_optSound && DlcPickSound(&fx, snd, sizeof(snd));
	}

	if (effect && effect[0])
		FireParticle(effect, x, y, z, true);
	// Optional extras from JSON "particles" (same world origin as primary).
	for (int i = 0; i < fx.particleExtraCount; ++i) {
		if (fx.particleExtra[i][0])
			FireParticle(fx.particleExtra[i], x, y, z, true);
	}

	StartFeedbackOverlay(&fx, kOverlayClearMsFx, GetTickCount());

	if (haveSnd)
		PlayHitSound(snd);

	if (g_feedbackLogLeft > 0) {
		--g_feedbackLogLeft;
		Log("FireFX name=%s pt=%s ov=%s ovSeq=%d", name, effect ? effect : "",
			fx.overlay, fx.overlaySequenceCount);
	}
}

bool IsLocalAttacker(void* ev) {
	if (!ev) return false;
	if (g_localUserId <= 0)
		RefreshLocalUserId();
	int local = EngLocal();
	int atkUid = EvInt(ev, "attacker");
	int atkEntId = EvInt(ev, "attackerentid");

	if (atkUid > 0 && g_localUserId > 0 && atkUid == g_localUserId)
		return true;
	if (local > 0 && atkUid > 0 && EngPlayerForUserID(atkUid) == local)
		return true;
	if (local > 0 && atkEntId > 0 && atkEntId == local)
		return true;
	return false;
}

static bool CiChannelOn() {
	const char* id = DlcGetSelected("ci");
	return id && id[0] && _stricmp(id, "off") != 0;
}

static bool SiChannelOn() {
	const char* id = DlcGetSelected("si");
	return id && id[0] && _stricmp(id, "off") != 0;
}

// SI entry points require an enabled SI channel. Sources are explicit, never
// substituted merely because the chosen event/pack has no corresponding media.
static void AssembleSiFx(const DlcFx* si, bool haveSi, const DlcFx* ci, bool haveCi, DlcFx* out) {
	memset(out, 0, sizeof(*out));
	const DlcFx* visual = g_optSiVisual ? (haveSi ? si : nullptr) : (haveCi ? ci : nullptr);
	const DlcFx* sound = g_optSiSound ? (haveSi ? si : nullptr) : (haveCi ? ci : nullptr);
	if (visual) *out = *visual;
	else if (!sound) return;
	const bool hasVisual = out->overlay[0] || out->overlaySequenceCount > 0
		|| out->particle[0] || out->particleExtraCount > 0;
	if (!hasVisual && sound) out->priority = sound->priority;

	out->sound[0] = 0;
	out->soundExtraCount = 0;
	if (sound) {
		memcpy(out->sound, sound->sound, sizeof(out->sound));
		memcpy(out->soundExtra, sound->soundExtra, sizeof(out->soundExtra));
		out->soundExtraCount = sound->soundExtraCount;
	}
	out->sound[sizeof(out->sound) - 1] = 0;
	out->used = hasVisual || out->sound[0] || out->soundExtraCount > 0;
}

static void BloodSplatNoteHit() {
	if (!g_optBloodSplat || !g_optSound || !SkeetoFeaturesOn()) return;
	const DWORD now = GetTickCount();
	const unsigned due = g_bloodSplatDue.load(std::memory_order_acquire);
	if (due && (LONG)(due - now) > 0) return;
	const unsigned cooldown = g_bloodSplatCooldown.load(std::memory_order_acquire);
	if (cooldown && (LONG)(cooldown - now) > 0) return;
	g_bloodSplatDue.store(now + 200u + (now & 127u), std::memory_order_release);
	g_bloodSplatCooldown.store(now + 250u, std::memory_order_release);
}

static void BloodSplatPaint() {
	const unsigned due = g_bloodSplatDue.load(std::memory_order_acquire);
	if (!due) return;
	const DWORD now = GetTickCount();
	if ((LONG)(now - due) < 0) return;
	g_bloodSplatDue.store(0, std::memory_order_release);
	if (!g_optBloodSplat || !g_optSound || !SkeetoFeaturesOn() || !EngInGame() || EngDrawingLoading())
		return;
	static const char* kSplat[] = {
		"player/survivor/splat/zombie_blood_spray_01.wav",
		"player/survivor/splat/zombie_blood_spray_02.wav",
		"player/survivor/splat/zombie_blood_spray_03.wav",
		"player/survivor/splat/zombie_blood_spray_04.wav",
		"player/survivor/splat/zombie_blood_spray_05.wav",
		"player/survivor/splat/zombie_blood_spray_06.wav",
	};
	static unsigned s_rng = 0x6C078965u;
	static int s_last = -1;
	s_rng = s_rng * 1664525u + 1013904223u;
	int pick = (int)((s_rng >> 16) % 6);
	if (pick == s_last) pick = (pick + 1) % 6;
	s_last = pick;
	EngEmitLocalSfxBus(kSplat[pick], 0.5f, SfxEmitBus::ClientUx);
}

static void FeedbackCi(const char* kind, bool throttle, bool meleeKill, bool ignoreHitModeGate,
	float wx, float wy, float wz) {
	if (!kind || !kind[0] || !g_engine || !EngInGame()) return;
	if (!CiChannelOn()) return;
	if (!g_optSound && !g_optIcon) return;

	const bool isHit = !_stricmp(kind, "hit");
	if (isHit && !ignoreHitModeGate && !HitModeCiAllowed()) return;
	// Shotgun pellet storms: skip resolve work when hit FX already played.
	if (throttle && isHit) {
		DWORD now = GetTickCount();
		if (now - g_lastHitFeedbackAt < 70)
			return;
	}
	const bool isHs = !_stricmp(kind, "headshot");
	if (!isHit)
		FeedbackAdvanceStreak("ci", &g_ciStreak, &g_ciStreakLastKillAt);
	DlcFx fx{};
	BloodSplatNoteHit();
	if (!DlcResolve("ci", isHit ? "hit" : "kill", isHs, meleeKill && !isHit && !isHs,
		isHit ? 0 : g_ciStreak, &fx))
		return;
	ApplyDlcFx(&fx, throttle, wx, wy, wz, isHit ? kOverlayClearMsHit : kOverlayClearMs, !isHit);
}

static void FeedbackFf(int dmg, float wx, float wy, float wz) {
	if (!g_optFf || !g_engine || !EngInGame()) return;
	if (!g_optSound && !g_optIcon) return;
	DlcFx fx{};
	if (!DlcResolve("ff", dmg >= 15 ? "kill" : "hit", false, false, 0, &fx))
		return;
	const bool isHit = (dmg < 15);
	ApplyDlcFx(&fx, true, wx, wy, wz, isHit ? kOverlayClearMsHit : kOverlayClearMs);
}

static void FeedbackSiHit(float wx, float wy, float wz) {
	if (!HitModeSiAllowed() || !SiChannelOn()) return;
	// Coalesce hit feedback before resolving its style.
	DWORD now = GetTickCount();
	if (now - g_lastHitFeedbackAt < 70)
		return;
	BloodSplatNoteHit();

	DlcFx si{}, ci{};
	const bool haveSi = (g_optSiVisual || g_optSiSound) && DlcResolve("si", "hit", false, false, 0, &si);
	const bool needCi = !g_optSiVisual || !g_optSiSound;
	const bool haveCi = needCi && CiChannelOn() && DlcResolve("ci", "hit", false, false, 0, &ci);
	if (!haveSi && !haveCi) return;

	DlcFx out{};
	AssembleSiFx(&si, haveSi, &ci, haveCi, &out);
	if (!out.used) return;
	ApplyDlcFx(&out, true, wx, wy, wz, kOverlayClearMsHit);
	if (g_feedbackLogLeft > 0) {
		--g_feedbackLogLeft;
		Log("si-hit siVis=%d siSnd=%d ov=%s pt=%s snd=%s",
			g_optSiVisual ? 1 : 0, g_optSiSound ? 1 : 0,
			out.overlay[0] ? out.overlay : "-",
			out.particle[0] ? out.particle : "-",
			out.sound[0] ? out.sound : "-");
	}
}

static int FeedbackStreakMax(const char* channel) {
	const DlcStyle* st = DlcFindStyle(DlcGetSelected(channel));
	if (!st || !st->streakEnabled) return 0;
	int limit = 10;
	if (st->streakWrap > 0 && st->streakWrap < limit)
		limit = st->streakWrap;
	for (int i = limit; i >= 1; --i)
		if (st->streakSlot[i]) return i;
	return 0;
}

static void FeedbackAdvanceStreak(const char* channel, int* streak, DWORD* lastKillAt) {
	if (!streak || !lastKillAt) return;
	if (g_feedbackStreakWindowSec <= 0) {
		++*streak;
		*lastKillAt = 0;
		return;
	}
	const int maxStreak = FeedbackStreakMax(channel);
	if (maxStreak <= 0) {
		*streak = 0;
		*lastKillAt = 0;
		return;
	}
	const DWORD now = GetTickCount();
	const DWORD windowMs = (DWORD)g_feedbackStreakWindowSec * 1000u;
	const bool inWindow = *lastKillAt && (DWORD)(now - *lastKillAt) < windowMs;
	if (!inWindow)
		*streak = 1;
	else if (*streak < maxStreak)
		++*streak;
	else
		*streak = maxStreak;
	*lastKillAt = now;
}

static void FeedbackSiKill(void* ev) {
	if (!g_engine || !EngInGame() || !ev || !SiChannelOn()) return;
	if (!g_optSound && !g_optIcon) return;
	BloodSplatNoteHit();
	g_suppressCommonHitUntil = GetTickCount() + 400;

	bool hs = EvBool(ev, "headshot") || EvInt(ev, "hitgroup", 0) == 1;
	bool melee = EventWeaponIsMelee(ev);
	FeedbackAdvanceStreak("si", &g_siStreak, &g_siStreakLastKillAt);

	DlcFx si{}, ci{};
	const bool haveSi = (g_optSiVisual || g_optSiSound) && DlcResolve("si", "kill", hs, melee, g_siStreak, &si);
	const bool needCi = !g_optSiVisual || !g_optSiSound;
	const bool haveCi = needCi && CiChannelOn() && DlcResolve("ci", "kill", hs, melee && !hs, 0, &ci);
	if (!haveSi && !haveCi) {
		Log("si-kill: no si/ci resolve (si=%s ci=%s)",
			DlcGetSelected("si")[0] ? DlcGetSelected("si") : "off",
			DlcGetSelected("ci")[0] ? DlcGetSelected("ci") : "off");
		return;
	}

	float wx = EvFloat(ev, "victim_x"), wy = EvFloat(ev, "victim_y"), wz = EvFloat(ev, "victim_z");
	if (wx == 0.f && wy == 0.f && wz == 0.f && g_haveImpactPos) {
		wx = g_lastImpactPos[0]; wy = g_lastImpactPos[1]; wz = g_lastImpactPos[2];
	}

	DlcFx out{};
	AssembleSiFx(&si, haveSi, &ci, haveCi, &out);
	if (!out.used) return;
	ApplyDlcFx(&out, false, wx, wy, wz, kOverlayClearMs, true);
	Log("feedback si kill streak=%d window=%d hs=%d melee=%d siVis=%d siSnd=%d ov=%s pt=%s snd=%s",
		g_siStreak, g_feedbackStreakWindowSec, hs ? 1 : 0, melee ? 1 : 0,
		g_optSiVisual ? 1 : 0, g_optSiSound ? 1 : 0,
		out.overlay[0] ? out.overlay : "-",
		out.particle[0] ? out.particle : "-",
		out.sound[0] ? out.sound : "-");
}

static void OnBulletImpact(void* ev) {
	const unsigned epoch = g_feedbackQueueEpoch.load(std::memory_order_relaxed);
	// Local gun impacts: stamp coords. CI TraceRay is deferred to EngineVGui::Paint
	// (same MASK_SHOT eye→impact as before — not run inside FireGameEvent / FSN).
	if (g_localUserId <= 0)
		RefreshLocalUserId();
	int uid = EvInt(ev, "userid");
	if (uid <= 0 || g_localUserId <= 0 || uid != g_localUserId)
		return;
	if (!NeedGunHitAttribution() && !g_optClientInfectedHp && !g_optClientDmgNum
		&& !DissCiWanted())
		return;

	DWORD now = GetTickCount();
	const float point[3] = { EvFloat(ev, "x"), EvFloat(ev, "y"), EvFloat(ev, "z") };
	FxHpCsEnsure();
	EnterCriticalSection(&g_fxHpCs);
	if (epoch != g_feedbackQueueEpoch.load(std::memory_order_relaxed)) {
		LeaveCriticalSection(&g_fxHpCs);
		return;
	}
	memcpy(g_lastImpactPos, point, sizeof(point));
	g_haveImpactPos = true;
	g_lastLocalGunImpactAt.store(now, std::memory_order_relaxed);
	LeaveCriticalSection(&g_fxHpCs);

	// One-shot / headshot: arm dissolve Trace even when hit-FX is off or suppressed.
	// Paint runs Trace before dissolve pump so DissCiHurtNote lands the kill entity.
	if (DissCiWanted() && !g_pendingCiImpactScan) {
		g_ciTracePos[0] = g_lastImpactPos[0];
		g_ciTracePos[1] = g_lastImpactPos[1];
		g_ciTracePos[2] = g_lastImpactPos[2];
		g_pendingCiImpactScan = true;
	}

	if (!HitModeCiAllowed())
		return;
	if (!g_hitDetectArmed.load())
		return;
	if (now < g_suppressCommonHitUntil)
		return;
	if (g_pendingCommonHit)
		return;
	// First pellet of a burst keeps the trace origin (shotgun storm).
	if (g_pendingCiImpactScan)
		return;
	g_ciTracePos[0] = g_lastImpactPos[0];
	g_ciTracePos[1] = g_lastImpactPos[1];
	g_ciTracePos[2] = g_lastImpactPos[2];
	g_pendingCiImpactScan = true;
}


static void OnKillFeedback(void* ev, bool specialInfected) {
	if (!IsLocalAttacker(ev)) return;
	g_pendingCommonHit = false;
	g_pendingCommonHitAt = 0;
	// Keep the last bullet Trace armed for dissolve. One-shot CI kills otherwise lose
	// the only DissCiHurtNote chance when this clears before Paint runs the Trace.
	if (!DissCiWanted())
		g_pendingCiImpactScan = false;
	g_suppressCommonHitUntil = GetTickCount() + 400;
	if (specialInfected)
		FeedbackSiKill(ev);
	else {
		if (!CiChannelOn())
			return;
		bool hs = EvBool(ev, "headshot");
		bool melee = EventWeaponIsMelee(ev);
		float wx = 0.f, wy = 0.f, wz = 0.f;
		if (g_haveImpactPos) {
			wx = g_lastImpactPos[0]; wy = g_lastImpactPos[1]; wz = g_lastImpactPos[2];
		}
		if (hs)
			FeedbackCi("headshot", false, false, false, wx, wy, wz);
		else
			FeedbackCi("kill", false, melee, false, wx, wy, wz);
	}
}

static bool KillStreakIsSpecialName(const char* name) {
	if (!name || !name[0]) return false;
	static const char* const kNames[] = {
		"Smoker", "Boomer", "Hunter", "Spitter", "Jockey", "Charger", "Tank", "Witch", nullptr
	};
	for (int i = 0; kNames[i]; ++i) {
		if (!_stricmp(name, kNames[i])) return true;
	}
	return false;
}

static void KillStreakHudOnSpecialDeath(const char* victimName) {
	if (!g_optKillStreakHud || !KillStreakIsSpecialName(victimName)) return;
	const DWORD now = GetTickCount();
	const DWORD gap = g_killStreakLastKillAt ? (now - g_killStreakLastKillAt) : 0xFFFFFFFFu;
	const bool inWindow = g_killStreakWindowSec == 0
		|| (g_killStreakLastKillAt && gap < (DWORD)g_killStreakWindowSec * 1000u);
	if (g_killStreakLastKillAt && inWindow)
		++g_killStreakCount;
	else
		g_killStreakCount = 1;
	g_killStreakLastKillAt = now;
	if (g_killStreakCount >= 3) {
		g_killStreakShowBorn = now;
		g_killStreakShowUntil = now + 2000u;
		if (g_optKillStreakSound && g_killStreakSound[0]) {
			strncpy(g_killStreakPendingSound, g_killStreakSound, sizeof(g_killStreakPendingSound) - 1);
			g_killStreakPendingSound[sizeof(g_killStreakPendingSound) - 1] = 0;
			g_killStreakSoundPlayAt = now + 1000u;
		}
	}
}

static bool IsLocalWitchKiller(void* ev) {
	if (!ev) return false;
	if (g_localUserId <= 0)
		RefreshLocalUserId();
	const int uid = EvInt(ev, "userid");
	if (uid <= 0) return false;
	if (g_localUserId > 0 && uid == g_localUserId) return true;
	const int local = EngLocal();
	return local > 0 && EngPlayerForUserID(uid) == local;
}

static void ElimCreditWitch(void* ev, bool localKill) {
	if (!g_optElim || !ev || !localKill) return;
	const bool ckptElim = CkptZombieKillsReady();
	if (!ckptElim) {
		g_elimWitch.fetch_add(1, std::memory_order_relaxed);
		g_elimSi.fetch_add(1, std::memory_order_relaxed);
	}
	const bool melee = EventWeaponIsMelee(ev);
	if (melee) {
		g_elimSiMelee.fetch_add(1, std::memory_order_relaxed);
	} else {
		// witch_killed has no headshot; keep non-melee HS-pool denominator only.
		g_elimHsPool.fetch_add(1, std::memory_order_relaxed);
	}
	ElimPersistMarkChanged();
}

static bool ElimTankEventIsDup(int uid, int source) {
	const DWORD now = GetTickCount();
	if (uid > 0) {
		int put = 0;
		for (int i = 0; i < 4; ++i) {
			if (g_elimTankDedup[i].at && now - g_elimTankDedup[i].at <= 3000u
				&& g_elimTankDedup[i].uid == uid)
				return true;
			if (!g_elimTankDedup[i].at || now - g_elimTankDedup[i].at > 3000u
				|| g_elimTankDedup[i].at < g_elimTankDedup[put].at)
				put = i;
		}
		g_elimTankDedup[put] = {uid, now};
		return false;
	}
	// Without an id, only pair opposite event sources. Repeated same-source events
	// can be distinct Tanks on multi-Tank servers and must each remain countable.
	source = source == 1 ? 1 : 0;
	const int other = source ^ 1;
	for (int i = 0; i < 4; ++i) {
		if (g_elimTankUnmatchedAt[other][i]
			&& now - g_elimTankUnmatchedAt[other][i] <= 3000u) {
			g_elimTankUnmatchedAt[other][i] = 0;
			return true;
		}
	}
	int put = 0;
	for (int i = 0; i < 4; ++i) {
		if (!g_elimTankUnmatchedAt[source][i]
			|| now - g_elimTankUnmatchedAt[source][i] > 3000u
			|| g_elimTankUnmatchedAt[source][i] < g_elimTankUnmatchedAt[source][put])
			put = i;
	}
	g_elimTankUnmatchedAt[source][put] = now;
	return false;
}

static void OnWitchKillFx(void* ev) {
	if ((!g_optKillFx && !g_optWorldMeleeCrown && !g_optWorldCrown) || !IsLocalWitchKiller(ev)) return;

	const bool melee = EventWeaponIsMelee(ev);
	const int witch = EvInt(ev, "witchid");
	float x = 0.f, y = 0.f, z = 0.f;
	bool havePos = false;
	if (witch > 0 && g_offOriginCommon >= 0 && g_offOriginCommon <= 0x4000) {
		void* e = EntGet(witch);
		if (EntReadable(e)) {
			float* o = (float*)((uint8_t*)e + g_offOriginCommon);
			if (PtrCommitted(o) && o[0] == o[0] && o[1] == o[1] && o[2] == o[2]) {
				x = o[0]; y = o[1]; z = o[2] + 40.f;
				havePos = true;
			}
		}
	}
	if (!havePos) {
		for (int i = 0; i < 8; ++i) {
			if (g_witchId[i] == witch && g_witchFxPosValid[i]) {
				x = g_witchFxPos[i][0]; y = g_witchFxPos[i][1]; z = g_witchFxPos[i][2];
				havePos = true;
				break;
			}
		}
	}
	if (!havePos) return;

	const bool perfect = !melee && EvBool(ev, "oneshot");
	if ((melee && g_optWorldMeleeCrown) || (!melee && g_optWorldCrown)) {
		g_worldCrownNotice.world[0] = x;
		g_worldCrownNotice.world[1] = y;
		// x/y/z already carries a +40 body lift. Keep the badge around upper torso
		// rather than another 34 units above it, which disappeared at crown range.
		g_worldCrownNotice.world[2] = z + 12.f;
		const DWORD now = GetTickCount();
		g_worldCrownNotice.born = now;
		g_worldCrownNotice.until = now + 2200u;
		g_worldCrownKind = melee ? 1 : (perfect ? 3 : 2);
	}
	if (g_optKillFx) {
		if (melee)
			FireFX("melee_crown", x, y, z);
		else
			FireFX(perfect ? "perfect_crown" : "crown", x, y, z);
	}
}

#include "skeeto_script_extras.h"

static void OnDeath(void* ev) {
	RefreshLocalUserId();
	const char* vn = EvStr(ev, "victimname");
	int atk = EvInt(ev, "attacker");
	int atkEntId = EvInt(ev, "attackerentid");
	int local = EngLocal();
	int atkEnt = atk > 0 ? EngPlayerForUserID(atk) : -1;

	if (g_deathLogLeft > 0) {
		--g_deathLogLeft;
		Log("player_death vn=%s atkUid=%d atkEnt=%d local=%d localUid=%d atkEntId=%d hs=%d wpn=%s",
			vn ? vn : "?", atk, atkEnt, local, g_localUserId, atkEntId,
			EvBool(ev, "headshot") ? 1 : 0,
			EvStr(ev, "weapon"));
	}

	if (!vn || !vn[0] || !strcmp(vn, "Infected")) return;
	WorldNoticeOnPinKill(ev);

	const bool localKill = IsLocalAttacker(ev);
	// Count the Tank death before the local-killer gate when the user selected the
	// all-deaths mode. Both event paths share the same userid/time de-dup state.
	// Checkpoint ledger owns Tank kills when ready (local path); all-deaths mode
	// still needs the event for non-local Tank credits.
	if (g_optElim && !strcmp(vn, "Tank") && (g_elimTankMode == 1 || localKill)
		&& !ElimTankEventIsDup(EvInt(ev, "userid"), 0)) {
		if (!(CkptZombieKillsReady() && localKill)) {
			g_elimTank.fetch_add(1, std::memory_order_relaxed);
			if (!localKill) ElimPersistMarkChanged();
		}
	}

	if (!localKill) {
		if (g_skipLogLeft > 0 && vn[0]) {
			--g_skipLogLeft;
			Log("skip not-local vn=%s atkUid=%d localUid=%d atkEnt=%d local=%d atkEntId=%d",
				vn, atk, g_localUserId, atkEnt, local, atkEntId);
		}
		return;
	}

    if (g_optClientDmgNum && (!strcmp(vn, "Hunter") || !strcmp(vn, "Jockey")
        || !strcmp(vn, "Smoker") || !strcmp(vn, "Boomer") || !strcmp(vn, "Spitter")
        || !strcmp(vn, "Charger") || !strcmp(vn, "Tank"))) EnqueueDamageEvent(ev, true);
	const bool elimWanted = g_optElim;
	const bool ckptElim = CkptZombieKillsReady();
	if (elimWanted && !ckptElim)
		g_elimSi.fetch_add(1, std::memory_order_relaxed);
	KillStreakHudOnSpecialDeath(vn);

	const bool melee = EventWeaponIsMelee(ev);
	const bool hs = EvBool(ev, "headshot") || EvInt(ev, "hitgroup", 0) == 1;
	// HS% denominator excludes melee kills (guns/explosives/etc. only).
	if (elimWanted && !melee) {
		g_elimHsPool.fetch_add(1, std::memory_order_relaxed);
		if (hs)
			g_elimHs.fetch_add(1, std::memory_order_relaxed);
	}

	if (elimWanted && melee)
		g_elimSiMelee.fetch_add(1, std::memory_order_relaxed);

	const bool hunterOrJockey = !strcmp(vn, "Hunter") || !strcmp(vn, "Jockey");
	int ve = 0;
	bool airborne = false;
	if (hunterOrJockey && WorldNoticeAirborneTrackingWanted()) {
		ve = EngPlayerForUserID(EvInt(ev, "userid"));
		airborne = VictimWasAirborne(ve, !strcmp(vn, "Jockey"));
		if (ve > 0 && ve < 65) g_localAirHitAt[ve] = 0;
	}
	bool chargerLevel = false;
	if (!strcmp(vn, "Charger") && melee && WorldNoticeChargerTrackingWanted()) {
		if (ve <= 0) ve = EngPlayerForUserID(EvInt(ev, "userid"));
		chargerLevel = WorldNoticeWasCharging(ve);
	}
	if (elimWanted && hunterOrJockey && airborne) {
		if (melee)
			g_elimMeleeSkeet.fetch_add(1, std::memory_order_relaxed);
		else
			g_elimSkeet.fetch_add(1, std::memory_order_relaxed);
	}
	if (elimWanted)
		ElimPersistMarkChanged();
	const float victimX = EvFloat(ev, "victim_x");
	const float victimY = EvFloat(ev, "victim_y");
	const float victimZ = EvFloat(ev, "victim_z");
	if (hunterOrJockey && airborne && melee && g_optWorldMeleeSkeet) {
		if (WorldNoticeSnapshotInfected(&g_worldMeleeSkeetNotice, ve, victimX, victimY, victimZ))
			g_worldMeleeSkeetNotice.world[2] -= 22.f;
	}
	if (hunterOrJockey && airborne && !melee && g_optWorldSkeet)
		WorldNoticeSnapshotInfected(&g_worldSkeetNotice, ve, victimX, victimY, victimZ);
	if (chargerLevel && g_optWorldLevel) {
		if (WorldNoticeSnapshotInfected(&g_worldLevelNotice, ve, victimX, victimY, victimZ))
			g_worldLevelNotice.world[2] -= 18.f;
	}

	OnKillFeedback(ev, true); // special infected — HUD kill/headshot (ci/si)
	if (g_optParry) {
		bool parryAir = airborne;
		bool parryLevel = chargerLevel;
		if (!parryAir && hunterOrJockey && (g_optParrySkeet || g_optParryMeleeSkeet)) {
			if (ve <= 0) ve = EngPlayerForUserID(EvInt(ev, "userid"));
			parryAir = VictimWasAirborne(ve, !strcmp(vn, "Jockey"));
		}
		if (!parryLevel && !strcmp(vn, "Charger") && melee && g_optParryLevel) {
			if (ve <= 0) ve = EngPlayerForUserID(EvInt(ev, "userid"));
			parryLevel = WorldNoticeChargeWindow(ve);
		}
		ScriptExtrasOnLocalKill(vn, melee, parryAir, parryLevel, hunterOrJockey);
	}
	if (!g_optKillFx) return;

	float x = EvFloat(ev, "victim_x"), y = EvFloat(ev, "victim_y"), z = EvFloat(ev, "victim_z");

	if (!strcmp(vn, "Charger")) {
		if (chargerLevel) FireFX("level", x, y, z);
		else if (hs) FireFX("crit_text", x, y, z);
		return;
	}
	if (hunterOrJockey) {
		// Only skeet / melee_skeet when actually airborne — ground melee must NOT count.
		if (airborne) {
			if (melee) FireFX(hs ? "headshot_skeet" : "melee_skeet", x, y, z);
			else if (hs) FireFX("headshot_skeet", x, y, z);
			else FireFX("skeet", x, y, z);
		} else if (hs) {
			FireFX("crit_text", x, y, z);
		}
		return;
	}
	if (hs) FireFX("crit_text", x, y, z);
}

static void OnInfectedDeath(void* ev) {
	// Witch also arrives as infected_death; CI elim prefers checkpoint ledger when ready.
	g_ciKillUndo = {};
	const bool ckptElim = CkptZombieKillsReady();
	if (g_optElim && IsLocalAttacker(ev)) {
		g_ciKillUndo.uid = EvInt(ev, "attacker", 0);
		g_ciKillUndo.valid = true;
		if (!ckptElim) {
			g_elimCi.fetch_add(1, std::memory_order_relaxed);
			g_ciKillUndo.elimCi = true;
		}
		const bool melee = EventWeaponIsMelee(ev);
		const bool hs = EvBool(ev, "headshot");
		if (!melee) {
			g_elimHsPool.fetch_add(1, std::memory_order_relaxed);
			g_ciKillUndo.elimHsPool = true;
			if (hs) {
				g_elimHs.fetch_add(1, std::memory_order_relaxed);
				g_ciKillUndo.elimHs = true;
			}
		}
		if (!ckptElim || g_ciKillUndo.elimHsPool || g_ciKillUndo.elimHs)
			ElimPersistMarkChanged();
	}
	OnKillFeedback(ev, false); // common infected — keep fullscreen kill/headshot overlays
}

static void ElimUndoCiForWitch(int uid) {
	if (!g_ciKillUndo.valid) return;
	if (g_ciKillUndo.uid != uid) {
		Log("witch-ci-undo miss uid=%d slot=%d valid=%d", uid, g_ciKillUndo.uid,
			g_ciKillUndo.valid ? 1 : 0);
		g_ciKillUndo = {};
		return;
	}
	if (g_ciKillUndo.elimCi && g_elimCi.load(std::memory_order_relaxed) > 0)
		g_elimCi.fetch_sub(1, std::memory_order_relaxed);
	if (g_ciKillUndo.elimHsPool && g_elimHsPool.load(std::memory_order_relaxed) > 0)
		g_elimHsPool.fetch_sub(1, std::memory_order_relaxed);
	if (g_ciKillUndo.elimHs && g_elimHs.load(std::memory_order_relaxed) > 0)
		g_elimHs.fetch_sub(1, std::memory_order_relaxed);
	if (g_ciKillUndo.tabCi)
		TabBoardUncountCiKill(uid);
	if (g_ciKillUndo.elimCi || g_ciKillUndo.elimHsPool || g_ciKillUndo.elimHs)
		ElimPersistMarkChanged();
	Log("witch-ci-undo uid=%d elim=%d/%d/%d tab=%d", uid,
		g_ciKillUndo.elimCi ? 1 : 0, g_ciKillUndo.elimHsPool ? 1 : 0,
		g_ciKillUndo.elimHs ? 1 : 0, g_ciKillUndo.tabCi ? 1 : 0);
	g_ciKillUndo = {};
}

static void OnMeleeKill(void* ev) {
	if (!ev) return;
	RefreshLocalUserId();
	const int uid = EvInt(ev, "userid", 0);
	if (uid <= 0) return;
	bool local = false;
	if (g_localUserId > 0 && uid == g_localUserId) local = true;
	else if (EngPlayerForUserID(uid) == EngLocal()) local = true;
	// Stamp every networked melee_kill (teammate too) for EventWeaponIsMelee.
	g_meleeKillAt = GetTickCount();
	g_meleeKillUid = uid;
	g_meleeKillEnt = EvInt(ev, "entityid", 0);
	(void)local;
}

static void OnTongue(void* ev) {
	TongueCutHudOnPullStopped(ev); // 先判自身开关；不受击杀特效/世界提示开关影响
	const bool wantTongueFx = g_optKillFx || g_optWorldTongueCut;
	const bool wantParry = g_optParry && g_optParryTongue;
	if (!wantTongueFx && !wantParry) return;
	RefreshLocalUserId();
	if (EvInt(ev, "release_type") != 4) return;
	if (EvInt(ev, "userid") != EvInt(ev, "victim")) return;
	int cutUid = EvInt(ev, "userid");
	if (g_localUserId > 0) {
		if (cutUid != g_localUserId) return;
	} else if (EngPlayerForUserID(cutUid) != EngLocal()) {
		return;
	}
	if (wantParry) ScriptExtrasOnTongueCut();
	if (!wantTongueFx) return;
	int se = EngPlayerForUserID(EvInt(ev, "smoker"));
	void* e = (se > 0) ? EntGet(se) : nullptr;
	if (!EntReadable(e) || g_offOrigin < 0 || g_offOrigin > 0x4000) return;
	float* o = (float*)((uint8_t*)e + g_offOrigin);
	if (!PtrCommitted(o)) return;
	if (g_optWorldTongueCut
		&& WorldNoticeSnapshotInfected(&g_worldTongueCutNotice, se, o[0], o[1], o[2]))
		g_worldTongueCutNotice.world[2] += 28.f;
	if (g_optKillFx)
		FireFX("tongue_cut", o[0], o[1], o[2] + 64.f);
}

// =============================================================================
// Idle flashlight — the survivor bot that takes over while you idle (Take a Break
// or AFK timeout) often turns the flashlight on and leaves it on when you return.
// Capture your own flashlight state at the moment the bot takes over, then undo
// the bot's change once after takeover with ONE legit toggle (impulse 100).
// No periodic sampling and no entity scans: the baseline is read in the swap event
// (game thread, O(1)) and the only timed work is one bounded, self-terminating
// check after takeover. The toggle runs on the Paint thread.
//
// There was also a local-server branch pinning server cvar sb_flashlight (-1/0/1).
// Removed 2026-09-15: that ConVar is registered in server.dll but no code reads it
// (no accessor call site, only its ctor and atexit dtor thunk), so it cannot change
// bot behavior. Full evidence: archive/运行日志/游戏根目录/game_root_logs_20260915/sb_flashlight_结论.md
// Do not re-add without a reproducible accessor call site in some server.dll.
// =============================================================================
static constexpr int kEfDimLight = 4;                  // EF_DIMLIGHT on the local pawn
static constexpr DWORD kIdleFlashSettleMs = 150;       // let the taken-back pawn settle
static constexpr DWORD kIdleFlashRetryMs = 100;        // re-check period while armed
static constexpr DWORD kIdleFlashWindowMs = 4000;      // remote latency needs a wider window

static void IdleFlashMuteArm(DWORD ms) {
	const DWORD now = GetTickCount();
	const DWORD until = now + ms;
	if (!g_idleFlashMuteUntil || (LONG)(until - g_idleFlashMuteUntil) > 0)
		g_idleFlashMuteUntil = until;
}

// Anything to undo/clear? Keeps the disabled path down to a few compares.
static bool IdleFlashlightStateLive() {
	return g_idleFlashArmed || g_idleFlashWantOn >= 0 || g_idleFlashBrightHeld;
}

static void IdleFlashlightResetState(const char* why) {
	const bool had = IdleFlashlightStateLive();
	IdleFlashlightBrightRestore(why ? why : "reset");
	g_idleFlashWantOn = -1;
	g_idleFlashArmed = false;
	g_idleFlashAt = 0;
	g_idleFlashGiveUpAt = 0;
	g_idleFlashSent = false;
	g_idleFlashSawIdle = false;
	g_idleFlashLive = -1;
	g_idleFlashLiveAt = 0;
	if (had)
		Log("idle-flashlight: state reset [%s]", why ? why : "?");
}

// Own pawn only. -1 means "not usable right now" — never guess, because a wrong
// read here would toggle a teammate's or an observed entity's flashlight.
// requirePlaying also rejects the moment we are observing instead of playing; the
// baseline read at idle start skips it, because the engine may already be putting
// us into observing our own pawn by the time the swap event arrives.
//
// Order matters: the observer-mode check is what the post-takeover retry keeps
// hitting, so it runs BEFORE EngPlayerInfo. That keeps the whole retry path down to
// EngLocal + EntGet + one int read — no PlayerInfo fill per attempt.
static int IdleFlashlightReadOwn(bool requirePlaying) {
	if (g_offEffects < 0 || g_offEffects > 0x4000) return -1;
	if (g_localUserId <= 0) return -1;
	const int local = EngLocal();
	if (local < 1) return -1;
	void* e = EntGet(local);
	if (!EntReadable(e)) return -1;
	if (requirePlaying && g_offObserverMode >= 0 && g_offObserverMode <= 0x4000) {
		const int* po = (const int*)((const uint8_t*)e + g_offObserverMode);
		if (PtrCommitted(po) && *po != 0) return -1;
	}
	// Ownership check before acting: a read-only offset probe above is harmless on
	// a wrong entity, but toggling one would not be.
	PlayerInfo pi{};
	if (!EngPlayerInfo(local, &pi) || pi.userid != g_localUserId) return -1;
	const int* pe = (const int*)((const uint8_t*)e + g_offEffects);
	if (!PtrCommitted(pe)) return -1;
	return (*pe & kEfDimLight) ? 1 : 0;
}

// Event side: record only. No cvar write, no ClientCmd, no engine command.
static void IdleFlashlightOnSwap(const char* evName, int playerUid, int botUid) {
	if (!g_optClientIdleFlashlight || !SkeetoFeaturesOn()) return;
	if (!evName || (playerUid <= 0 && botUid <= 0)) return;
	if (g_localUserId <= 0)
		RefreshLocalUserId();
	if (g_localUserId <= 0 || (playerUid != g_localUserId && botUid != g_localUserId))
		return;
	const bool takeover = (evName[0] == 'b'); // bot_player_replace
	if (!takeover) {
		// Prefer the last playing-frame sample: on remote servers the swap event
		// often lands after the bot has already changed EF_DIMLIGHT.
		if (g_idleFlashLive >= 0)
			g_idleFlashWantOn = g_idleFlashLive;
		else
			g_idleFlashWantOn = IdleFlashlightReadOwn(false);
		g_idleFlashLive = -1;
		g_idleFlashArmed = false;
		g_idleFlashAt = 0;
		g_idleFlashGiveUpAt = 0;
		g_idleFlashSent = false;
		g_idleFlashSawIdle = false;
		if (g_idleFlashWantOn < 0)
			Log("idle-flashlight: baseline unavailable (own pawn not readable)");
		else
			Log("idle-flashlight: baseline want=%d", g_idleFlashWantOn);
		return;
	}
	// Takeover: act once, shortly after the pawn comes back under our control.
	if (g_idleFlashWantOn < 0) return;
	const DWORD now = GetTickCount();
	g_idleFlashArmed = true;
	g_idleFlashAt = now + kIdleFlashSettleMs;
	g_idleFlashGiveUpAt = now + kIdleFlashWindowMs;
	g_idleFlashSent = false;
	// Cover engine sync + our impulse 100 click for the whole restore window.
	IdleFlashMuteArm(kIdleFlashWindowMs + 500u);
}

static void IdleFlashlightClearRestore(const char* why, int have) {
	Log("idle-flashlight: %s want=%d have=%d", why, g_idleFlashWantOn, have);
	IdleFlashlightBrightRestore(why ? why : "clear");
	g_idleFlashWantOn = -1;
	g_idleFlashArmed = false;
	g_idleFlashAt = 0;
	g_idleFlashGiveUpAt = 0;
	g_idleFlashSent = false;
	g_idleFlashSawIdle = false;
	g_idleFlashLive = -1;
	IdleFlashMuteArm(400u);
}

static void IdleViewRestoreReset(const char* /*why*/) {
	g_idleViewHaveSnapshot = false;
	g_idleViewCapturePending = false;
	g_idleViewArmed = false;
	g_idleViewAt = g_idleViewGiveUpAt = g_idleViewUntil = 0;
	g_idleViewWrites = 0;
	g_idleViewHaveBot = false;
	g_idleViewHaveLastDSnap = false;
	g_idleViewFrozen = false;
	g_idleViewWasPlaying = false;
}

static bool IdleViewRestoreWanted() {
	return g_optClientIdleViewRestore;
}

static float IdleViewAbsDelta(const float* a, const float* b) {
	float dp = a[0] - b[0];
	float dy = a[1] - b[1];
	while (dy > 180.f) dy -= 360.f;
	while (dy < -180.f) dy += 360.f;
	const float ap = fabsf(dp);
	const float ay = fabsf(dy);
	return ap > ay ? ap : ay;
}

static void IdleViewCopy(float* dst, const float* src) {
	dst[0] = src[0];
	dst[1] = src[1];
	dst[2] = src[2];
}

static bool IdleViewAnglesFinite(const float* a) {
	return a && a[0] == a[0] && a[1] == a[1] && a[2] == a[2]
		&& a[0] > -90.f && a[0] < 90.f;
}

// Engine GetViewAngles during idle/spec is the spectator camera, not the
// pre-idle look. Only sample while the local pawn is actually playing.
static void IdleViewSampleLive() {
	if (!g_engine || EngLocal() <= 0) return;
	float cur[3]{};
	EngGetViewAngles(cur);
	if (!IdleViewAnglesFinite(cur)) return;
	IdleViewCopy(g_idleViewLive, cur);
	g_idleViewHaveLive = true;
}

static void IdleViewCommitLiveSnapshot() {
	if (!g_idleViewHaveLive) return;
	IdleViewCopy(g_idleViewAngles, g_idleViewLive);
	g_idleViewHaveSnapshot = true;
	g_idleViewCapturePending = false;
}

static void IdleViewRestoreOnSwap(const char* evName, int playerUid, int botUid) {
	if (!IdleViewRestoreWanted() || !SkeetoFeaturesOn() || !evName) return;
	if (g_localUserId <= 0) RefreshLocalUserId();
	if (g_localUserId <= 0 || (playerUid != g_localUserId && botUid != g_localUserId)) return;
	if (evName[0] != 'b') {
		// Freeze pre-idle look. Never GetViewAngles here: may already be
		// spectator / bot aim by the time the swap event arrives.
		IdleViewCommitLiveSnapshot();
		if (!g_idleViewHaveSnapshot)
			g_idleViewCapturePending = true;
		g_idleViewFrozen = true;
		g_idleViewHaveBot = false;
		g_idleViewArmed = false;
		return;
	}
	if (!g_idleViewHaveSnapshot)
		IdleViewCommitLiveSnapshot();
	g_idleViewFrozen = true;
	const DWORD now = GetTickCount();
	g_idleViewArmed = true;
	g_idleViewAt = now + 100u;
	g_idleViewGiveUpAt = now + 2000u;
	g_idleViewUntil = now + 650u;
	g_idleViewWrites = 0;
	g_idleViewHaveLastDSnap = false;
}

static bool IdleViewRestorePlaying() {
	const int local = EngLocal();
	if (local < 1) return false;
	void* e = EntGet(local);
	if (!EntReadable(e)) return false;
	if (g_offObserverMode >= 0 && g_offObserverMode <= 0x4000) {
		const int* o = (const int*)((const uint8_t*)e + g_offObserverMode);
		if (PtrCommitted(o) && *o != 0) return false;
	}
	PlayerInfo pi{};
	return EngPlayerInfo(local, &pi) && g_localUserId > 0 && pi.userid == g_localUserId;
}

// Paint owns the snapshot; events publish only a bounded transition request.
// Native x86 CInput CAM getter/first/third were checked in client.dll
// C0A8E1E8...: getter takes split-screen slot (-1), transitions take no args.
static std::atomic_int g_idlePersonRequest{0}; // -1 reset, 1 idle, 2 takeover
static bool g_idlePersonHaveLive = false, g_idlePersonFrozen = false;
static bool g_idlePersonThird = false, g_idlePersonHaveSnapshot = false;
static DWORD g_idlePersonSampleAt = 0, g_idlePersonRestoreAt = 0, g_idlePersonUntil = 0;
static bool g_idlePersonArmed = false;
static const uint8_t* g_idlePersonClient = nullptr;
static void IdlePersonRestoreReset() { g_idlePersonRequest.store(-1, std::memory_order_release); }
static void IdlePersonRestoreOnSwap(const char* name, int player, int bot) {
    if (!g_optClientIdlePersonRestore || !SkeetoFeaturesOn() || g_localUserId <= 0
        || (player != g_localUserId && bot != g_localUserId)) return;
    g_idlePersonRequest.store(name[0] == 'b' ? 2 : 1, std::memory_order_release);
}
static void* IdlePersonInput() {
    static bool tried = false;
    static void** cell = nullptr;
    if (!tried) {
        tried = true;
        const auto base = (const uint8_t*)GetModuleHandleA("client.dll");
        if (!base) return nullptr;
        const auto dos = (const IMAGE_DOS_HEADER*)base;
        const auto nt = (const IMAGE_NT_HEADERS*)(base + dos->e_lfanew);
        static const uint8_t getter[] = {0x55,0x8b,0xec,0x56,0x8b,0xf1,0xe8,0xe5,0xe5,0x14,0x00};
        static const uint8_t third[] = {0x55,0x8b,0xec,0x83,0xec,0x0c,0x56,0x6a,0xff};
        static const uint8_t first[] = {0x6a,0xff,0xe8,0x39,0x36,0x00,0x00,0x33,0xc9};
        if (nt->FileHeader.Machine == IMAGE_FILE_MACHINE_I386
            && nt->FileHeader.TimeDateStamp == 0x6a440ecf && nt->OptionalHeader.SizeOfImage == 0x963000
            && !memcmp(base + 0x12e050, getter, sizeof(getter))
            && !memcmp(base + 0x12ddc0, third, sizeof(third))
            && !memcmp(base + 0x12de30, first, sizeof(first))) {
            cell = (void**)(base + 0x6e2f04); g_idlePersonClient = base;
        }
        else Log("idle-person: unsupported native camera; not restored");
    }
    void* input = nullptr;
    return cell && skmem::Copy(&input, cell, sizeof(input)) ? input : nullptr;
}
static void IdlePersonRestorePump() {
    const int request = g_idlePersonRequest.exchange(0, std::memory_order_acq_rel);
    if (request == -1 || !g_optClientIdlePersonRestore || !SkeetoFeaturesOn()
        || !g_paintInGame.load(std::memory_order_relaxed)) {
        g_idlePersonHaveLive = g_idlePersonFrozen = g_idlePersonHaveSnapshot = g_idlePersonArmed = false;
        return;
    }
    const DWORD now = GetTickCount();
    if (request == 1) {
        g_idlePersonFrozen = true;
        g_idlePersonHaveSnapshot = g_idlePersonHaveLive;
        g_idlePersonArmed = false;
    } else if (request == 2) {
        g_idlePersonFrozen = true;
        if (!g_idlePersonHaveSnapshot) g_idlePersonHaveSnapshot = g_idlePersonHaveLive;
        g_idlePersonArmed = g_idlePersonHaveSnapshot;
        g_idlePersonRestoreAt = now + 100u;
        g_idlePersonUntil = now + 2000u;
    }
    if (g_idlePersonSampleAt && (LONG)(now - g_idlePersonSampleAt) < 0) return;
    g_idlePersonSampleAt = now + 100u;
    if (g_idlePersonFrozen && !g_idlePersonArmed) return;
    if (g_idlePersonArmed && (LONG)(now - g_idlePersonUntil) >= 0) {
        g_idlePersonArmed = g_idlePersonFrozen = g_idlePersonHaveSnapshot = g_idlePersonHaveLive = false;
        Log("idle-person: takeover timed out; snapshot discarded"); return;
    }
    if (!IdleViewRestorePlaying() || g_dbgLocalTeam.load(std::memory_order_relaxed) != 2
        || g_dbgLifeState.load(std::memory_order_relaxed) != 0) return;
    void* input = IdlePersonInput();
    if (!input) return;
    const auto base = g_idlePersonClient;
    using GetCamera = bool(__thiscall*)(void*, int);
    using SetCamera = void(__thiscall*)(void*);
    const bool third = ((GetCamera)(base + 0x12e050))(input, -1);
    if (g_idlePersonArmed) {
        if ((LONG)(now - g_idlePersonRestoreAt) < 0) return;
        if (third != g_idlePersonThird)
            ((SetCamera)(base + (g_idlePersonThird ? 0x12ddc0 : 0x12de30)))(input);
        g_idlePersonArmed = g_idlePersonFrozen = g_idlePersonHaveSnapshot = false;
    } else {
        g_idlePersonThird = third;
        g_idlePersonHaveLive = true;
    }
}

static bool IdleViewLocalObserving() {
	const int local = EngLocal();
	if (local < 1) return false;
	void* e = EntGet(local);
	if (!EntReadable(e)) return false;
	if (g_offObserverMode < 0 || g_offObserverMode > 0x4000) return false;
	const int* o = (const int*)((const uint8_t*)e + g_offObserverMode);
	return PtrCommitted(o) && *o != 0;
}

static void IdleViewRestorePump() {
	if (!IdleViewRestoreWanted() || !SkeetoFeaturesOn()) {
		if (g_idleViewHaveSnapshot || g_idleViewArmed) IdleViewRestoreReset("off");
		return;
	}
	if (!g_paintInGame.load(std::memory_order_relaxed)) {
		if (g_idleViewHaveSnapshot || g_idleViewArmed) IdleViewRestoreReset("left-game");
		g_idleViewHaveLive = false;
		g_idleViewWasPlaying = false;
		g_idleViewFrozen = false;
		return;
	}
	if (!g_idleViewArmed) {
		const bool playing = IdleViewRestorePlaying();
		if (!g_idleViewFrozen) {
			if (playing) {
				if (g_idleViewWasPlaying)
					IdleViewSampleLive();
				g_idleViewWasPlaying = true;
			} else {
				g_idleViewWasPlaying = false;
			}
		}
		if (g_idleViewCapturePending && !g_idleViewFrozen && playing) {
			IdleViewSampleLive();
			IdleViewCommitLiveSnapshot();
		}
		if (g_idleViewHaveSnapshot && g_engine && IdleViewLocalObserving()) {
			EngGetViewAngles(g_idleViewBot);
			g_idleViewHaveBot = true;
		}
		return;
	}
	if (!g_idleViewHaveSnapshot) {
		IdleViewCommitLiveSnapshot();
		if (!g_idleViewHaveSnapshot) {
			const DWORD now = GetTickCount();
			if ((LONG)(now - g_idleViewGiveUpAt) >= 0)
				IdleViewRestoreReset("no snapshot");
			return;
		}
	}
	const DWORD now = GetTickCount();
	if (!IdleViewRestorePlaying()) {
		if ((LONG)(now - g_idleViewAt) < 0) return;
		g_idleViewAt = now + 100u;
		if ((LONG)(now - g_idleViewGiveUpAt) >= 0) IdleViewRestoreReset("timeout");
		return;
	}
	if (g_idleViewWrites == 0) {
		if ((LONG)(now - g_idleViewAt) < 0) return;
		EngSetViewAngles(g_idleViewAngles);
		g_idleViewWrites = 1;
		g_idleViewHaveLastDSnap = false;
		return;
	}
	if ((LONG)(now - g_idleViewUntil) >= 0) {
		IdleViewRestoreReset("restored");
		return;
	}

	float current[3]{};
	EngGetViewAngles(current);
	const float dSnap = IdleViewAbsDelta(current, g_idleViewAngles);
	if (g_idleViewHaveLastDSnap) {
		const float inc = dSnap - g_idleViewLastDSnap;
		// Gradual move away from the snapshot is mouse. Stop on same Paint.
		if (inc > 0.4f && inc < 18.f) {
			IdleViewRestoreReset("mouse");
			return;
		}
	}
	g_idleViewLastDSnap = dSnap;
	g_idleViewHaveLastDSnap = true;

	if (dSnap <= 1.f)
		return;

	const float dBot = g_idleViewHaveBot
		? IdleViewAbsDelta(current, g_idleViewBot) : 999.f;
	if (dBot <= 8.f && dSnap >= 20.f && g_idleViewWrites < 2) {
		EngSetViewAngles(g_idleViewAngles);
		++g_idleViewWrites;
		g_idleViewHaveLastDSnap = false;
		return;
	}
	if (dBot > 8.f) {
		IdleViewRestoreReset("view moved after restore");
		return;
	}
}

// Idle weapon slot: snapshot the local pawn's active slot (1=primary .. 5=pills)
// at idle start, then one/two slotN ClientCmds after takeover. No scan.
static int IdleWepSlotFromNetClass(const char* cn) {
	if (!cn || !cn[0]) return 0;
	if (strstr(cn, "Molotov") || strstr(cn, "PipeBomb") || strstr(cn, "Pipebomb")
		|| strstr(cn, "VomitJar") || strstr(cn, "Vomitjar") || strstr(cn, "Bile"))
		return 3;
	if (strstr(cn, "FirstAid") || strstr(cn, "Defibrillator") || strstr(cn, "Defib")
		|| strstr(cn, "UpgradePack") || strstr(cn, "Incendiary") || strstr(cn, "AmmoPack")
		|| strstr(cn, "Explosive"))
		return 4;
	if (strstr(cn, "PainPills") || strstr(cn, "Adrenaline"))
		return 5;
	if (strstr(cn, "Pistol") || strstr(cn, "Magnum") || strstr(cn, "Melee")
		|| strstr(cn, "melee") || strstr(cn, "Chainsaw"))
		return 2;
	if (strstr(cn, "Rifle") || strstr(cn, "SMG") || strstr(cn, "Smg") || strstr(cn, "smg")
		|| strstr(cn, "Shotgun") || strstr(cn, "Sniper") || strstr(cn, "Hunting")
		|| strstr(cn, "Launcher") || strstr(cn, "M60") || strstr(cn, "AK47")
		|| strstr(cn, "Scout") || strstr(cn, "AWP") || strstr(cn, "MP5")
		|| strstr(cn, "SG552") || strstr(cn, "Military") || strstr(cn, "Chrome")
		|| strstr(cn, "Pump") || strstr(cn, "Spas") || strstr(cn, "AutoShot")
		|| strstr(cn, "TerrorGun") || strstr(cn, "SubMachine"))
		return 1;
	return 0;
}

static bool IdleWepLocalObserving(void* e) {
	if (!e) return false;
	if (g_offObserverMode < 0 || g_offObserverMode > 0x4000) return false;
	const int* o = (const int*)((const uint8_t*)e + g_offObserverMode);
	return PtrCommitted(o) && *o != 0;
}

static bool IdleWepLocalIncap(void* e) {
	if (!e) return false;
	if (g_offIsIncapacitated < 0 || g_offIsIncapacitated > 0x4000) return false;
	const unsigned char* p = (const unsigned char*)e + g_offIsIncapacitated;
	return PtrCommitted(p) && *p != 0;
}

static int IdleWepActiveSlotFromPawn(void* e) {
	if (!EntReadable(e) || g_offActiveWeapon < 0 || g_offActiveWeapon > 0x4000)
		return 0;
	const int* ph = (const int*)((const uint8_t*)e + g_offActiveWeapon);
	if (!PtrCommitted(ph)) return 0;
	const int h = *ph;
	if (h == g_idleWepLiveHandle && g_idleWepLive > 0)
		return g_idleWepLive;
	if (h == -1 || h == 0) return 0;
	const int idx = EntIndexFromHandle(h);
	if (idx <= 0) return 0;
	const int slot = IdleWepSlotFromNetClass(EntNetClassName(idx));
	g_idleWepLiveHandle = h;
	if (slot > 0) g_idleWepLive = slot;
	return slot;
}

static int IdleWepReadOwnSlot(bool requirePlaying) {
	if (g_localUserId <= 0) return 0;
	const int local = EngLocal();
	if (local < 1) return 0;
	void* e = EntGet(local);
	if (!EntReadable(e)) return 0;
	if (requirePlaying && IdleWepLocalObserving(e)) return 0;
	PlayerInfo pi{};
	if (!EngPlayerInfo(local, &pi) || pi.userid != g_localUserId) return 0;
	return IdleWepActiveSlotFromPawn(e);
}

static void IdleWepRestoreReset(const char* /*why*/) {
	g_idleWepWant = 0;
	g_idleWepArmed = false;
	g_idleWepSawIdle = false;
	g_idleWepAt = 0;
	g_idleWepGiveUpAt = 0;
	g_idleWepSends = 0;
}

static void IdleWepRestoreOnSwap(const char* evName, int playerUid, int botUid) {
	if (!g_optClientIdleWepRestore || !SkeetoFeaturesOn() || !evName) return;
	if (g_localUserId <= 0) RefreshLocalUserId();
	if (g_localUserId <= 0 || (playerUid != g_localUserId && botUid != g_localUserId))
		return;
	if (evName[0] != 'b') {
		int slot = g_idleWepLive;
		if (slot <= 0) slot = IdleWepReadOwnSlot(false);
		g_idleWepWant = slot;
		g_idleWepArmed = false;
		g_idleWepSawIdle = false;
		g_idleWepSends = 0;
		g_idleWepAt = 0;
		g_idleWepGiveUpAt = 0;
		return;
	}
	if (g_idleWepWant <= 0) return;
	const DWORD now = GetTickCount();
	g_idleWepArmed = true;
	g_idleWepSends = 0;
	g_idleWepAt = now + 100u;
	g_idleWepGiveUpAt = now + 2000u;
}

static void IdleWepEnsureSlotCmd() {
	if (g_idleWepCmdReady) return;
	g_idleWepCmdReady = true;
	UnlockConCommand("slot1", 0, kFCvarClientCmdCanExecute);
	UnlockConCommand("slot2", 0, kFCvarClientCmdCanExecute);
	UnlockConCommand("slot3", 0, kFCvarClientCmdCanExecute);
	UnlockConCommand("slot4", 0, kFCvarClientCmdCanExecute);
	UnlockConCommand("slot5", 0, kFCvarClientCmdCanExecute);
}

static void IdleWepRestorePump() {
	if (!g_optClientIdleWepRestore || !SkeetoFeaturesOn()) {
		if (g_idleWepWant || g_idleWepArmed) IdleWepRestoreReset("off");
		g_idleWepLive = 0;
		g_idleWepLiveHandle = 0;
		return;
	}
	if (!g_paintInGame.load(std::memory_order_relaxed)) {
		if (g_idleWepWant || g_idleWepArmed) IdleWepRestoreReset("left-game");
		g_idleWepLive = 0;
		g_idleWepLiveHandle = 0;
		return;
	}
	if (!g_idleWepArmed) {
		const int local = EngLocal();
		void* e = local > 0 ? EntGet(local) : nullptr;
		const bool playing = EntReadable(e) && !IdleWepLocalObserving(e);
		if (playing) {
			if (g_idleWepWant <= 0) {
				const int slot = IdleWepActiveSlotFromPawn(e);
				if (slot > 0)
					g_idleWepLive = slot;
			}
			if (g_idleWepWant > 0 && g_idleWepSawIdle) {
				const DWORD now = GetTickCount();
				g_idleWepArmed = true;
				g_idleWepSends = 0;
				g_idleWepAt = now + 100u;
				g_idleWepGiveUpAt = now + 2000u;
			}
		} else {
			g_idleWepSawIdle = true;
		}
		if (!g_idleWepArmed)
			return;
	}
	const DWORD now = GetTickCount();
	if ((LONG)(now - g_idleWepAt) < 0) return;
	const int local = EngLocal();
	if (local < 1) {
		g_idleWepAt = now + 100u;
		if ((LONG)(now - g_idleWepGiveUpAt) >= 0) IdleWepRestoreReset("timeout");
		return;
	}
	void* e = EntGet(local);
	if (!EntReadable(e) || IdleWepLocalObserving(e)) {
		g_idleWepAt = now + 100u;
		if ((LONG)(now - g_idleWepGiveUpAt) >= 0) IdleWepRestoreReset("timeout");
		return;
	}
	if (IdleWepLocalIncap(e) && g_idleWepWant != 2) {
		g_idleWepAt = now + 100u;
		if ((LONG)(now - g_idleWepGiveUpAt) >= 0) IdleWepRestoreReset("incap");
		return;
	}
	const int have = IdleWepReadOwnSlot(true);
	if (have == g_idleWepWant && g_idleWepWant > 0) {
		IdleWepRestoreReset("restored");
		return;
	}
	if (g_idleWepSends >= 2) {
		IdleWepRestoreReset("not converged");
		return;
	}
	if (g_idleWepWant < 1 || g_idleWepWant > 5) {
		IdleWepRestoreReset("bad slot");
		return;
	}
	IdleWepEnsureSlotCmd();
	char cmd[8]{};
	cmd[0] = 's'; cmd[1] = 'l'; cmd[2] = 'o'; cmd[3] = 't';
	cmd[4] = (char)('0' + g_idleWepWant);
	cmd[5] = 0;
	EngClientCmd(cmd);
	++g_idleWepSends;
	g_idleWepAt = now + 100u;
	Log("idle-weapon: slot%d have=%d send=%d", g_idleWepWant, have, (int)g_idleWepSends);
}

// Brightness hold. When the player left the flashlight OFF we force r_flashlightbrightness
// to 0 for the whole idle window AND through the takeover restore below, because the game
// switches its own flashlight on the instant the player takes back control — releasing the
// brightness any earlier makes that flashlight visible until the toggle lands.
// Written through the console command, the same way the 强制 Cvar page writes this cvar;
// the value is read back once per write and poked directly if the command did not take.
// Paint/game thread only.
static void IdleFlashlightBrightWrite(float v) {
	void* var = CvarFind("r_flashlightbrightness");
	if (!var) return;
	// The renderer applies this cvar from its command callback. Always use the
	// same unlock/dispatch route as the proven ClientUx force-cvar module;
	// merely poking ConVar storage changes the displayed value but not the light.
	UnlockConCommand("r_flashlightbrightness",
		kFCvarCheat | kFCvarDevOnly | kFCvarHidden, kFCvarClientCmdCanExecute);
	char cmd[96]{};
	snprintf(cmd, sizeof(cmd), "r_flashlightbrightness %.3f", (double)v);
	EngClientCmd(cmd);
	CvarPokeFloatValue(var, v);
}

static void IdleFlashlightBrightRestore(const char* why) {
	if (!g_idleFlashBrightHeld) return;
	g_idleFlashBrightHeld = false;
	g_idleFlashBrightAt = 0;
	if (g_idleFlashBrightSavedOk && g_run.load(std::memory_order_relaxed)) {
		IdleFlashlightBrightWrite(g_idleFlashBrightSaved);
		Log("idle-flashlight: brightness given back %.2f [%s]",
			(double)g_idleFlashBrightSaved, why ? why : "?");
	}
	g_idleFlashBrightSavedOk = false;
}

static void IdleFlashlightBrightHold() {
	void* var = CvarFind("r_flashlightbrightness");
	if (!var) return;
	int n = 0;
	float f = 0.f;
	if (!g_idleFlashBrightHeld) {
		if (!CvarReadPair(var, &n, &f) || f != f) return;
		g_idleFlashBrightSaved = f;
		g_idleFlashBrightSavedOk = true;
		g_idleFlashBrightHeld = true;
		IdleFlashlightBrightWrite(0.f);
		if (CvarReadPair(var, &n, &f) && f != 0.f)
			CvarPokeFloatValue(var, 0.f); // command refused: write the value directly
		Log("idle-flashlight: brightness held at 0 (was %.2f)", (double)g_idleFlashBrightSaved);
		return;
	}
	// Re-assert at 2 Hz only: the 强制 Cvar page can re-pin this same cvar while we idle.
	const DWORD now = GetTickCount();
	if (g_idleFlashBrightAt && (LONG)(now - g_idleFlashBrightAt) < 0) return;
	g_idleFlashBrightAt = now + 500;
	if (CvarReadPair(var, &n, &f) && f != 0.f) {
		IdleFlashlightBrightWrite(0.f);
		if (CvarReadPair(var, &n, &f) && f != 0.f)
			CvarPokeFloatValue(var, 0.f);
	}
}

// Paint-thread pump. Module closed => a few bool/atomic reads and out.
static void IdleFlashlightPump() {
	if (!g_optClientIdleFlashlight || !SkeetoFeaturesOn()) {
		if (IdleFlashlightStateLive())
			IdleFlashlightResetState("opt-off");
		return;
	}
	if (!g_paintInGame.load(std::memory_order_relaxed)) {
		if (IdleFlashlightStateLive())
			IdleFlashlightResetState("left-game");
		g_idleFlashLive = -1;
		return;
	}
	if (!g_idleFlashArmed) {
		// Keep a playing-frame baseline so idle events on remote servers do not
		// capture the bot's already-changed EF_DIMLIGHT.
		if (g_idleFlashWantOn < 0) {
			const DWORD now = GetTickCount();
			if (!g_idleFlashLiveAt || (LONG)(now - g_idleFlashLiveAt) >= 0) {
				g_idleFlashLiveAt = now + kIdleFlashLiveSampleMs;
				const int live = IdleFlashlightReadOwn(true);
				if (live >= 0)
					g_idleFlashLive = live;
			}
			if (!g_idleFlashBrightHeld)
				return;
		}
		// Hold as soon as baseline says off — do not wait for observer mode.
		// Remote servers often stay "playing" until takeover; delaying the hold
		// until !playing is what lets the takeover flash show at full brightness.
		if (g_idleFlashWantOn == 0)
			IdleFlashlightBrightHold();

		const int on = IdleFlashlightReadOwn(true);
		const bool playing = on >= 0;
		if (!playing) {
			g_idleFlashSawIdle = true;
			return;
		}
		// Playing again. wantOn==0 must keep brightness at 0 until the off
		// toggle lands — restoring here is the remote-server "flash then off".
		if (g_idleFlashBrightHeld && g_idleFlashWantOn != 0)
			IdleFlashlightBrightRestore("playing");
		if (g_idleFlashWantOn >= 0 && g_idleFlashSawIdle) {
			const DWORD now = GetTickCount();
			g_idleFlashArmed = true;
			g_idleFlashAt = now + kIdleFlashSettleMs;
			g_idleFlashGiveUpAt = now + kIdleFlashWindowMs;
			g_idleFlashSent = false;
			IdleFlashMuteArm(kIdleFlashWindowMs + 500u);
		}
		if (!g_idleFlashArmed)
			return;
	}
	// The game switches its own flashlight on at the moment of takeover, so the brightness
	// is NOT given back here: it has to stay at 0 until the state restore below has landed,
	// otherwise the player sees the flashlight blink on and then off again. Every exit path
	// (IdleFlashlightClearRestore / ResetState) hands it back.
	if (g_idleFlashWantOn == 0)
		IdleFlashlightBrightHold();
	const DWORD now = GetTickCount();
	if ((LONG)(now - g_idleFlashAt) < 0) return;
	const int on = IdleFlashlightReadOwn(true);
	if (on < 0) {
		g_idleFlashAt = now + kIdleFlashRetryMs;
		if ((LONG)(now - g_idleFlashGiveUpAt) >= 0)
			IdleFlashlightClearRestore("gave up (pawn not ours)", on);
		return;
	}
	if (on == g_idleFlashWantOn) {
		if (g_idleFlashSent)
			IdleFlashlightClearRestore("restored", on);
		else {
			IdleFlashlightBrightRestore("state already matched");
			g_idleFlashWantOn = -1;
			g_idleFlashArmed = false;
			g_idleFlashAt = 0;
			g_idleFlashSent = false;
			g_idleFlashSawIdle = false;
			g_idleFlashLive = -1;
			IdleFlashMuteArm(400u);
		}
		return;
	}
	if (g_idleFlashSent) {
		// One toggle already out. On remote servers EF_DIMLIGHT often lags the
		// impulse by more than one retry — keep waiting inside the window.
		// Never send a second toggle: a stale read would double-flip.
		g_idleFlashAt = now + kIdleFlashRetryMs;
		if ((LONG)(now - g_idleFlashGiveUpAt) >= 0)
			IdleFlashlightClearRestore("not converged, left as is", on);
		return;
	}
	if (!g_idleFlashCmdReady) {
		g_idleFlashCmdReady = true;
		UnlockConCommand("impulse", 0, kFCvarClientCmdCanExecute);
	}
	g_idleFlashSent = true;
	g_idleFlashAt = now + kIdleFlashRetryMs;
	IdleFlashMuteArm(800u);
	EngClientCmd("impulse 100");
	Log("idle-flashlight: one toggle want=%d have=%d", g_idleFlashWantOn, on);
}

// =============================================================================
// DSP lock (优化听声辨位). dsp_volume 0 kills reverb/echo, but L4D2's client-side
// C_SoundscapeSystem (client.dll, c_soundscape.cpp) re-applies the soundscape's own
// dsp_volume through IConVar::SetValue(float) every time a soundscape activates, so a
// one-shot console write / keybind never sticks.
// Instead of re-issuing the command on a timer, block that write at the cvar class: the
// writer enters through the IConVar subobject vtable ([ConVar+0x18] then slot +8), so we
// replace that slot and force 0 only for the dsp_volume object; every other cvar forwards
// untouched. No hook on the soundscape path, no per-frame work, no polling.
// Slot identity: the dsp_volume soundscape handler loads *(ConVar+0x18) and calls [+8],
// while the dsp_player handler in the same dispatcher calls [+0xc] — i.e. +8 is
// SetValue(float) and +0xc is SetValue(int). Evidence: archive/运行日志/游戏根目录/game_root_logs_20260915.
// Sub-option dsp_off (engine.dll, 0x1046E990, FCVAR_CHEAT 0x4000) has no known re-writer,
// so it gets no slot: it is only forced once while the sub-option is on.
// Forcing a value goes through the ConVar's own SetValue(float) (see DspLockWriteVal), not
// a raw memory poke: only that path also updates the string form the console prints and
// runs change callbacks. dsp_volume carries no cheat flag, so it needs no flag handling at
// all; dsp_off is FCVAR_CHEAT, so its flags are cleared for the instant of our own call.
// The slot is not the whole story: a soundscape change can still move the value through a
// write path we never replaced, and the name can resolve to a different ConVar after a
// level load. DspLockVerify covers both a few times per second (re-target + re-assert) and
// is capped so it can never turn into an endless reinstall loop. Observed in game: the
// value occasionally flips to 0.8 on an indoor/outdoor change and is corrected at once.
// =============================================================================
static constexpr int kDspLockMaxTries = 6;
static constexpr int kDspLockMaxRetargets = 16;  // bound on the safety net's reinstall loop
static constexpr int kDspLockVolume = 0;  // dsp_volume: also clamped at the vtable slot
static constexpr int kDspLockOff = 1;     // dsp_off: value only, no known writer to block
static constexpr int kDspLockMaxTargets = 2;

struct DspLockTarget {
	const char* name;
	void* var;     // ConVar*
	void* setFn;   // that object's own ConVar::SetValue(float) — never our hook
	float want;    // value forced while the option (or sub-option) is on
	bool savedOk;  // pre-lock value captured, handed back when the option goes off
	int savedN;
	float savedF;
};

static DspLockTarget g_dspLockTgt[kDspLockMaxTargets]{};
static bool g_dspLockOffForced = false;  // the dsp_off row is currently forced
static void** g_dspLockSlot = nullptr;   // &vt[2] of the dsp_volume IConVar subobject
static void* g_dspLockOrig = nullptr;    // original SetValue(float)
static bool g_dspLockApplied = false;    // that slot points at our hook
static bool g_dspLockOffReady = false;   // dsp_off resolved: the sub-option can act
static bool g_dspLockOffWarned = false;
static DWORD g_dspLockNextTryAt = 0;
static DWORD g_dspLockVerifyAt = 0;      // safety-net re-assert throttle
static unsigned char g_dspLockReasserts = 0;
static unsigned char g_dspLockRetargets = 0;
static bool g_dspLockRetargetWarned = false;
static unsigned char g_dspLockFixLogs = 0;  // bounded log budget for write-path anomalies
static unsigned char g_dspLockTries = 0;
static unsigned char g_dspLockClamps = 0;  // bounded proof-of-work log budget

static void __fastcall Hooked_DspSetValue(void* ecx, void* edx, float value) {
	(void)edx;
	const DspLockTarget& t = g_dspLockTgt[kDspLockVolume];
	if (ecx && t.var && ecx == (void*)((uint8_t*)t.var + 0x18)) {
		// Bounded proof: without this the feature is silent and can only be judged by
		// ear. Only the first few clamps are logged.
		if (g_dspLockClamps < 4) {
			++g_dspLockClamps;
			Log("dsp-lock: clamped dsp_volume write %.3f -> %.3f",
				(double)value, (double)t.want);
		}
		value = t.want;
	}
	auto fn = (void(__thiscall*)(void*, float))g_dspLockOrig;
	if (fn) fn(ecx, value);
}

// Write one target's value through the cvar's OWN ConVar::SetValue(float) (the pointer we
// captured before hooking, or the same slot of that object's class). That is the engine's
// own path: it updates m_fValue/m_nValue and the string form the console prints, and runs
// any change callback — a raw memory poke does none of that, which is how a "successful"
// write can still leave the console showing the old value.
// A cheat-flagged cvar (dsp_off) is refused by that path while sv_cheats is 0, so the
// judging flags are cleared for the duration of our own call and put back right after.
static void DspLockWriteVal(const DspLockTarget& t, float v) {
	if (!t.var || !t.setFn || !PtrCommitted(t.var)) return;
	const int flags = CvarFlagsOf(t.var);
	const int clear = kFCvarCheat | kFCvarDevOnly | kFCvarHidden;
	const bool masked = (flags & clear) != 0;
	if (masked) CvarWriteFlags(t.var, flags & ~clear);
	((void(__thiscall*)(void*, float))t.setFn)((void*)((uint8_t*)t.var + 0x18), v);
	if (masked) CvarWriteFlags(t.var, flags);
	// Verify on the edge only, and never log unconditionally: this is also the path the
	// 250 ms safety net uses, so an unbounded line here would spam while a writer fights
	// us. Callers log the install / sub-option / re-assert edges themselves.
	int n = 0;
	float got = 0.f;
	if (!CvarReadPair(t.var, &n, &got) || got == v) return;
	const float left = got;  // what the engine's own setter left behind
	// Fallback = the 强制 Cvar page's direct memory poke, for the case where the engine's
	// own setter refuses or does not take (bounds, cheat state, another hook in front).
	CvarPokeFloatValue(t.var, v);
	if (g_dspLockFixLogs < 8) {
		++g_dspLockFixLogs;
		float after = 0.f;
		const bool ok = CvarReadPair(t.var, &n, &after) && after == v;
		Log("dsp-lock: %s setter left %.3f, poked %.3f %s",
			t.name, (double)left, (double)v, ok ? "ok" : "FAILED");
	}
}

static void DspLockRestore(const char* why, bool restoreValues);

// Safety net for everything the slot hook cannot see. Two ways this feature can lose the
// value while the option stays on: (a) something writes the cvar through a path that is
// not the IConVar slot we replaced — another overload, the primary vtable, a config exec,
// which is what an indoor/outdoor soundscape change does — and (b) the object behind the
// name can change, because the resolver returns whatever the name hashes to first and that
// order is not ours to control. So: a few times per second re-resolve both names, re-target
// the lock when the object moved, and put the values back when they drifted. In the healthy
// case this only reads memory; the force-Cvar style write is the backstop.
static void DspLockVerify() {
	const DWORD now = GetTickCount();
	if (g_dspLockVerifyAt && (LONG)(now - g_dspLockVerifyAt) < 0) return;
	g_dspLockVerifyAt = now + 250;

	// (b) Same name, possibly a different ConVar now.
	void* volNow = CvarFind(g_dspLockTgt[kDspLockVolume].name);
	void* offNow = CvarFind(g_dspLockTgt[kDspLockOff].name);
	if ((volNow && volNow != g_dspLockTgt[kDspLockVolume].var)
		|| (offNow && offNow != g_dspLockTgt[kDspLockOff].var)) {
		if (g_dspLockRetargets >= kDspLockMaxRetargets) {
			// Self-terminating: a name that keeps resolving elsewhere must not turn into
			// an endless unhook/rehook loop. Keep the current lock and say so once.
			if (!g_dspLockRetargetWarned) {
				g_dspLockRetargetWarned = true;
				Log("dsp-lock: WARN cvar keeps resolving elsewhere, re-targeting stopped");
			}
			return;
		}
		++g_dspLockRetargets;
		if (g_dspLockRetargets <= 4)
			Log("dsp-lock: cvar object moved, re-targeting (vol=%p off=%p)", volNow, offNow);
		// Restore clears the state and re-arms the install, which runs on the next Paint.
		DspLockRestore("retarget", true);
		return;
	}

	// (a) Value drift: a write that never reached the slot hook.
	int n = 0;
	float f = 0.f;
	DspLockTarget& vol = g_dspLockTgt[kDspLockVolume];
	if (vol.var && CvarReadPair(vol.var, &n, &f) && f != vol.want) {
		if (g_dspLockReasserts < 8) {
			++g_dspLockReasserts;
			Log("dsp-lock: re-assert dsp_volume %.3f -> %.3f", (double)f, (double)vol.want);
		}
		DspLockWriteVal(vol, vol.want);
	}
	if (!g_dspLockOffForced) return;
	DspLockTarget& off = g_dspLockTgt[kDspLockOff];
	if (off.var && CvarReadPair(off.var, &n, &f) && f != off.want) {
		if (g_dspLockReasserts < 8) {
			++g_dspLockReasserts;
			Log("dsp-lock: re-assert dsp_off %.3f -> %.3f", (double)f, (double)off.want);
		}
		DspLockWriteVal(off, off.want);
	}
}

// Restore the slot FIRST, then hand the cvars back: with the slot still patched our own
// restore write would be clamped straight back to `want`.
// `restoreValues` is false on the shutdown path: the slot must never be left pointing
// into this module across unload, but the worker must not poke cvar memory either — the
// engine has already written config.cfg by then, so the values do not matter anymore.
static void DspLockRestore(const char* why, bool restoreValues) {
	DspLockTarget saved[kDspLockMaxTargets];
	for (int i = 0; i < kDspLockMaxTargets; ++i) saved[i] = g_dspLockTgt[i];
	if (g_dspLockSlot && g_dspLockOrig) {
		void* prev = nullptr;
		if (VtProtectWrite(g_dspLockSlot, g_dspLockOrig, &prev))
			Log("dsp-lock: off, SetValue(float) slot restored [%s]", why ? why : "?");
		else
			Log("dsp-lock: WARN slot restore failed [%s]", why ? why : "?");
	}
	g_dspLockSlot = nullptr;
	g_dspLockOrig = nullptr;
	g_dspLockApplied = false;
	g_dspLockOffForced = false;
	g_dspLockOffReady = false;
	g_dspLockOffWarned = false;
	g_dspLockNextTryAt = 0;
	g_dspLockTries = 0;
	// A fresh lock lifetime starts whenever this was not the safety net re-targeting
	// itself; the counter must survive a re-target or its cap would never apply.
	if (!why || strcmp(why, "retarget") != 0) {
		g_dspLockRetargets = 0;
		g_dspLockRetargetWarned = false;
	}
	// Hand the cvars back their pre-lock values. Direct memory writes only, so this needs
	// no engine call; a row we never forced writes back the value we captured (a no-op).
	if (restoreValues) {
		for (int i = 0; i < kDspLockMaxTargets; ++i) {
			if (saved[i].var && saved[i].savedOk)
				DspLockWriteVal(saved[i], saved[i].savedF);
		}
	}
	for (int i = 0; i < kDspLockMaxTargets; ++i) g_dspLockTgt[i] = DspLockTarget{};
}

// Sub-option edge. Called straight from the menu handler (Paint/game thread), so there is
// no per-frame work at all: the value moves when [4] is toggled, and the install forces it
// when the sub-option was already on at load time.
static void DspLockApplyOff(bool on) {
	DspLockTarget& t = g_dspLockTgt[kDspLockOff];
	if (!t.var || !t.setFn) return;
	if (on && !g_dspLockOffReady) {
		if (!g_dspLockOffWarned) {
			g_dspLockOffWarned = true;
			Log("dsp-lock: WARN dsp_off unresolved, sub-option inactive");
		}
		return;
	}
	if (on == g_dspLockOffForced) return;
	g_dspLockOffForced = on;
	if (on) {
		DspLockWriteVal(t, t.want);
		Log("dsp-lock: dsp_off forced %.3f (sub-option on)", (double)t.want);
	} else {
		const float back = t.savedOk ? t.savedF : 0.0f;
		DspLockWriteVal(t, back);
		Log("dsp-lock: dsp_off restored to %.3f (sub-option off)", (double)back);
	}
}

// Menu readout only (2 Hz cache; the menu paints in two passes). -1 = unknown/unreadable.
static float g_dspLockShowVol = -1.f;
static float g_dspLockShowOff = -1.f;
static DWORD g_dspLockShowAt = 0;

static bool DspLockReadBack(int idx, float* out) {
	const DspLockTarget& t = g_dspLockTgt[idx];
	if (!out || !t.var) return false;
	int n = 0;
	float f = 0.f;
	if (!CvarReadPair(t.var, &n, &f)) return false;
	*out = f;
	return true;
}

// The menu asks before this module's globals are in scope, so the 2 Hz refresh lives
// behind these two entry points instead of in the menu.
static bool DspLockShowValue(int idx, float* out) {
	const DWORD now = GetTickCount();
	if (!g_dspLockShowAt || (LONG)(now - g_dspLockShowAt) >= 0) {
		g_dspLockShowAt = now + 500;
		g_dspLockShowVol = -1.f;
		g_dspLockShowOff = -1.f;
		float f = 0.f;
		if (DspLockReadBack(kDspLockVolume, &f)) g_dspLockShowVol = f;
		if (DspLockReadBack(kDspLockOff, &f)) g_dspLockShowOff = f;
	}
	if (!out) return false;
	const float v = (idx == kDspLockOff) ? g_dspLockShowOff : g_dspLockShowVol;
	if (v < 0.f) return false;
	*out = v;
	return true;
}

static bool DspLockShowVolume(float* out) { return DspLockShowValue(kDspLockVolume, out); }
static bool DspLockShowOff(float* out) { return DspLockShowValue(kDspLockOff, out); }

// Bounded install: the cvars have to be registered first, so retry at 1 Hz for a few
// seconds and then fail closed (the option can look on while doing nothing, and the log
// says why). Once installed the steady state is one pointer compare per Paint.
static void DspLockPump() {
	// Distinct reasons in the log: "opt-off" is the user's switch, "policy-off" is the
	// sv_pure mod-ban purge (SkeetoFeaturesOn), "not-running" is engine teardown. All of
	// them hand the cvars back, which is why the value returns to 0.8 in those states.
	const char* why = nullptr;
	bool restoreValues = true;
	if (!g_run.load(std::memory_order_relaxed)) {
		why = "not-running";
		restoreValues = false;
	} else if (!g_optClientDspLock) {
		why = "opt-off";
	} else if (!SkeetoFeaturesOn()) {
		why = "policy-off";
	}
	if (why) {
		if (g_dspLockApplied || g_dspLockSlot || g_dspLockTgt[kDspLockVolume].var)
			DspLockRestore(why, restoreValues);
		return;
	}
	if (g_dspLockApplied) {
		DspLockVerify();
		return;
	}
	const DWORD now = GetTickCount();
	if (g_dspLockNextTryAt && (LONG)(now - g_dspLockNextTryAt) < 0) return;
	if (g_dspLockTries >= kDspLockMaxTries) return;
	g_dspLockNextTryAt = now + 1000;
	++g_dspLockTries;

	// dsp_off is resolved even while the sub-option is off, so [2] can act immediately
	// instead of waiting for a reinstall.
	static const char* const kNames[kDspLockMaxTargets] = { "dsp_volume", "dsp_off" };
	static const float kWant[kDspLockMaxTargets] = { 0.0f, 1.0f };
	for (int i = 0; i < kDspLockMaxTargets; ++i) {
		DspLockTarget& t = g_dspLockTgt[i];
		t = DspLockTarget{};
		t.name = kNames[i];
		t.want = kWant[i];
		t.var = CvarFind(kNames[i]);
		if (t.var && PtrCommitted((uint8_t*)t.var + 0x18 + sizeof(void*))) {
			// +0x18 is the IConVar subobject, +8 its SetValue(float) (see banner).
			void** vt = *(void***)((uint8_t*)t.var + 0x18);
			if (vt && PtrCommitted(vt + 2) && IsExec(vt[2]))
				t.setFn = vt[2];
		}
		t.savedOk = t.var && CvarReadPair(t.var, &t.savedN, &t.savedF);
	}
	DspLockTarget& vol = g_dspLockTgt[kDspLockVolume];
	g_dspLockOffReady = g_dspLockTgt[kDspLockOff].setFn != nullptr;
	if (!vol.var || !vol.setFn) return;
	void** vt = *(void***)((uint8_t*)vol.var + 0x18);
	if (!vt || !PtrCommitted(vt + 2)) return;
	void* orig = vt[2];
	if (!orig || !IsExec(orig)) return;
	// Publish our state BEFORE the slot starts pointing at us: another thread may call
	// SetValue between these two steps, and it must find a valid g_dspLockOrig or its
	// write would be silently dropped.
	g_dspLockSlot = &vt[2];
	g_dspLockOrig = orig;
	void* prev = nullptr;
	if (!VtProtectWrite(&vt[2], (void*)&Hooked_DspSetValue, &prev) || prev != orig) {
		// Someone else owned the slot: put their pointer back, never ours.
		if (prev && prev != orig) {
			void* other = nullptr;
			VtProtectWrite(&vt[2], prev, &other);
		}
		g_dspLockSlot = nullptr;
		g_dspLockOrig = nullptr;
		return;
	}
	g_dspLockApplied = true;
	g_dspLockClamps = 0;
	// Force the current value down once; every later write is blocked at the slot.
	DspLockWriteVal(vol, vol.want);
	Log("dsp-lock: on dsp_volume var=%p slot=%p orig=%p want=%.3f was=%.3f tries=%u",
		vol.var, (void*)g_dspLockSlot, orig, (double)vol.want, (double)vol.savedF,
		(unsigned)g_dspLockTries);
	if (g_optClientDspOff)
		DspLockApplyOff(true);  // warns once by itself when dsp_off did not resolve
}

// =============================================================================
// HandleEvent — game event callback.
// Record state or push a bounded queue. No Trace, particles, disk, or engine draw.
// =============================================================================
static void MainUiHubServerSpawn(void* ev) {
 g_escUiServerMax.store(std::max(0,std::min(64,EvInt(ev,"maxplayers",0))),std::memory_order_relaxed);
 MainUiServerRecord row{};
 if((g_optMainMenuUi||g_optEscMenuUi) && SkeetoFeaturesOn()){
 const char* address=EvStr(ev,"address","");const char* name=EvStr(ev,"hostname","");
 if(address&&address[0]){int port=EvInt(ev,"port",27015);if(port<1||port>65535)port=27015;
  if(strchr(address,':'))strncpy_s(row.address,address,_TRUNCATE);else snprintf(row.address,sizeof(row.address),"%s:%d",address,port);
 }
 if(name)strncpy_s(row.name,name,_TRUNCATE);
 }
 if(TryAcquireSRWLockExclusive(&g_mainUiServerLock)){g_mainUiCurrentServer=row;g_mainUiServerGeneration.fetch_add(1,std::memory_order_release);ReleaseSRWLockExclusive(&g_mainUiServerLock);}
}
static void HandleEvent(void* ev) {
	if (!ev || !g_ready.load() || !g_run.load(std::memory_order_relaxed)) return;
	const char* n = EvName(ev);
	if (n && (!strcmp(n,"round_start") || !strcmp(n,"round_end") || !strcmp(n,"game_disconnect")
		|| !strcmp(n,"game_newmap") || !strcmp(n,"map_transition") || !strcmp(n,"mission_lost")))
		g_tpsAimResetRequested.store(true,std::memory_order_release); // No engine access on Event thread.
	else if (n && (!strcmp(n,"player_spawn") || !strcmp(n,"player_death") || !strcmp(n,"player_team"))) {
		const int own=g_tpsAimEventUser.load(std::memory_order_acquire);
		if (own>0 && EvInt(ev,"userid",0)==own) g_tpsAimResetRequested.store(true,std::memory_order_release);
	}
	if (n && !strcmp(n, "player_hurt_concise") && SkeetoFeaturesOn())
		EnqueueDamageEvent(ev); // Event thread: bounded field copy; Paint resolves and dispatches consumers.

	if(n&&(!strcmp(n,"round_start")||!strcmp(n,"game_disconnect")||!strcmp(n,"game_newmap")||!strcmp(n,"map_transition"))){g_lastMusicReset.store(true,std::memory_order_release);g_lastMusicRoundFailed.store(false,std::memory_order_release);}
	else if(n&&!strcmp(n,"mission_lost")&&g_lastMusicEventWanted.load(std::memory_order_acquire))g_lastMusicRoundFailed.store(true,std::memory_order_release);
	if (n && (!strcmp(n, "round_start") || !strcmp(n, "game_disconnect") || !strcmp(n, "game_newmap")))
		SafeMusicResetChapter();
	else if (n && !strcmp(n, "map_transition") && g_safeMusicHookWanted.load(std::memory_order_acquire))
		g_safeMusicEventPending.store(true, std::memory_order_release);
	if (n && (!strcmp(n, "game_disconnect") || !strcmp(n, "game_newmap")))
		g_campaignMapEpoch.fetch_add(1, std::memory_order_relaxed);
	if (n && !strcmp(n, "round_start")) g_campaignRoundReset.store(true, std::memory_order_release);
	if (n && !strcmp(n, "server_spawn")) {
		MainUiHubServerSpawn(ev);
		// Event thread: store only. Paint/LevelInit apply the lock.
		const bool vanilla = EvBool(ev, "vanilla", false);
		g_eclipseVanilla.store(vanilla ? 1 : 0, std::memory_order_relaxed);
		g_policyDirty.store(true, std::memory_order_relaxed);
		Log("server_spawn vanilla=%d (addons %s)", vanilla ? 1 : 0, vanilla ? "off" : "on");
	}
	// Life tracking must still cancel an in-flight dissolve while global Skeeto
	// features are being switched off; this only records the userid/epoch pair.
	if (n && !strcmp(n, "player_spawn"))
		ClientUxDissolveOnPlayerSpawn(ev);
	// Preserve cached HP life boundaries through a global off/on transition too.
	if (n && !strcmp(n, "player_spawn")) LocalPlayOnHpLifeEvent(ev, true);
	else if (n && !strcmp(n, "player_death")) LocalPlayOnHpLifeEvent(ev, false);
	if (!SkeetoFeaturesOn()) return;
	CrashMark(kBcEvent);
	if (!n) return;
	if (!strcmp(n, "map_transition") && g_fastLoadLocalTransitionEnabled.load(std::memory_order_acquire)
		&& g_fastLoadLocalLevel.load(std::memory_order_relaxed))
		g_fastLoadLocalTransitionPending.store(true, std::memory_order_release);
	InterlockedIncrement(&g_fireCalls);
	if (g_evtLogLeft > 0) {
		--g_evtLogLeft;
		Log("evt #%ld '%s'", (long)g_fireCalls, n);
	}
	if(g_optMainMenuUi && g_optMainUiBattleArchive && g_optChapStats
		&& (!strcmp(n,"map_transition") || !strcmp(n,"finale_win")))
		g_mainUiBattlePending = true;
	if(!strcmp(n,"mission_lost") || !strcmp(n,"game_disconnect"))
		g_mainUiBattlePending = false;
	if (n && (!strcmp(n, "mission_lost") || !strcmp(n, "game_disconnect")
		|| !strcmp(n, "map_transition") || !strcmp(n, "round_end")))
		LaserRoundPost(2);
	if (!strcmp(n, "game_disconnect")) WorldTankPredictClear();
	if(!strcmp(n,"game_disconnect"))g_escUiServerMax.store(0,std::memory_order_relaxed);
	if(!strcmp(n,"game_disconnect")&&TryAcquireSRWLockExclusive(&g_mainUiServerLock)){
		g_mainUiCurrentServer=MainUiServerRecord{};ReleaseSRWLockExclusive(&g_mainUiServerLock);
	}
	if (g_optChapStats) ChapStatsOnEvent(n, ev); // counters only; returns at once when off
	// A pending old-chapter freeze must precede timing reset on round_start.
	if(!strcmp(n,"round_start") || !strcmp(n,"game_newmap")) {
		g_mainUiBattlePending = false;
		if(g_optMainMenuUi && g_optMainUiBattleArchive && g_optChapStats) {
			g_mainUiBattleStart=GetTickCount();g_mainUiBattleCaptured=false;
		}
	}
	// Pellet bursts use the attribution branch directly after shared bookkeeping.
	if (!strcmp(n, "bullet_impact")) {
		OnBulletImpact(ev);
		return;
	}
	if (!strcmp(n, "player_say")) {
		LocalPlayOnPlayerSay(ev);
	}
	else if (!strcmp(n, "player_spawn")) {
		SilentSiOnPlayerSpawn(ev);
	}
	else if (!strcmp(n, "player_death")) {
		HazHudOnSpitterDeath(ev);
		WorldNoticeOnTankKilled(ev);
		WorldNoticeOnTankSlayer(ev);
		StaggerHudOnPlayerDeath(ev);
		// KillFeed before OnDeath so VictimWasAirborne still sees g_localAirHitAt.
		KillFeedOnPlayerDeath(ev);
		OnDeath(ev);
		TabBoardOnPlayerDeath(ev);
	}
	else if (!strcmp(n, "charger_killed") || !strcmp(n, "hunter_headshot") || !strcmp(n, "jockey_headshot")) {
		KillFeedOnGoldEvent(ev, n);
	}
	else if (!strcmp(n, "infected_death")) {
		OnInfectedDeath(ev);
		if (g_optTabBoard) {
			const int atk = EvInt(ev, "attacker", 0);
			if (!CkptZombieKillsReady()) {
				TabBoardCountKill(atk, false);
				if (g_ciKillUndo.valid && g_ciKillUndo.uid == atk)
					g_ciKillUndo.tabCi = true;
			}
		}
	}
	else if (!strcmp(n, "melee_kill")) {
		OnMeleeKill(ev);
	}
	else if (!strcmp(n, "zombie_death")) {
		ClientUxOnZombieDeath(ev);
	}
	else if (!strcmp(n, "player_shoved")) {
		WorldNoticeOnPinShove(ev);
		StaggerHudOnPlayerShoved(ev);
		ScriptExtrasOnShove(ev);
	}
	else if (!strcmp(n, "tongue_grab")) {
		WorldNoticeOnControlStarted(ev, kWorldPinTongue);
		TongueCutHudOnGrab(ev);
	}
	else if (!strcmp(n, "lunge_pounce"))
		WorldNoticeOnControlStarted(ev, kWorldPinPounce);
	else if (!strcmp(n, "jockey_ride"))
		WorldNoticeOnControlStarted(ev, kWorldPinJockey);
	else if (!strcmp(n, "charger_carry_start")) {
		WorldNoticeOnControlStarted(ev, kWorldPinCharger);
		WorldNoticeOnChargerCharge(ev, false);
	}
	else if (!strcmp(n, "charger_pummel_start"))
		WorldNoticeOnControlStarted(ev, kWorldPinCharger);
	else if (!strcmp(n, "spit_burst")) HazHudOnSpitBurst();
	else if (!strcmp(n, "tongue_pull_stopped")) {
		WorldNoticeOnPinEnd(ev, "userid");
		OnTongue(ev);
	}
	else if (!strcmp(n, "pounce_stopped"))
		WorldNoticeOnPinEnd(ev, "userid");
	else if (!strcmp(n, "jockey_ride_end"))
		WorldNoticeOnPinEnd(ev, "rescuer");
	else if (!strcmp(n, "charger_pummel_end"))
		WorldNoticeOnPinEnd(ev, "rescuer");
	else if (!strcmp(n, "charger_carry_end"))
		WorldNoticeOnPinEnd(ev, nullptr);
	else if (!strcmp(n, "revive_success")) WorldNoticeOnReviveSuccess(ev);
	else if (!strcmp(n, "defibrillator_used")) WorldNoticeOnDefibSuccess(ev);
	else if (!strcmp(n, "player_now_it")) WorldNoticeOnBile(ev, true);
	else if (!strcmp(n, "player_no_longer_it")) WorldNoticeOnBile(ev, false);
	else if (!strcmp(n, "charger_charge_start")) WorldNoticeOnChargerCharge(ev, true);
	else if (!strcmp(n, "charger_charge_end"))
		WorldNoticeOnChargerCharge(ev, false);
	else if (!strcmp(n, "witch_spawn")) {
		LocalPlayOnWitchSpawn(ev);
		int wid = EvInt(ev, "witchid");
		if (wid <= 0) wid = EvInt(ev, "entityid");
		if (wid > 0) g_ckptWitchCachedId = wid;
		WitchRageHudNoteSpawn(wid); // atomic hint only; returns at once when the HUD is off
		WitchHpHudNoteSpawn(wid);
	}
	else if (!strcmp(n, "zombie_ignited")) {
		IgniteHudOnEvent(ev); // bounded ring write; Paint resolves names
	}
	else if (!strcmp(n, "witch_harasser_set")) {
		WitchStartleOnEvent(ev);
		const int wid = EvInt(ev, "witchid");
		if (wid > 0) g_ckptWitchCachedId = wid;
	}
	else if (!strcmp(n, "witch_killed")) {
		ElimUndoCiForWitch(EvInt(ev, "userid", 0));
		const bool localWitch = IsLocalWitchKiller(ev);
		ElimCreditWitch(ev, localWitch);
		ScriptExtrasOnWitch(localWitch);
		OnWitchKillFx(ev);
		WorldNoticeOnWitchKilled(ev);
		LocalPlayOnWitchKilled(ev);
		WitchHpHudNoteKilled();
		KillFeedOnWitchKilled(ev);
		BossDmgBoardOnWitchKilled(); // atomic stamp; Paint reads checkpoint totals
		g_ckptWitchCachedId = 0;
	}
	else if (!strcmp(n, "round_start")) {
		SilentSiClear();
		TongueCutHudClear();
		HudMapEnterStableArm("round_start");
		g_overlayBoundaryClearPending.store(true, std::memory_order_release);
		ClientUxClearNoCorpseTracks();
		WorldNoticeClear();
		KillStreakHudClear();
		g_clientUxFade = {};
		ClientUxClearDelayedSfx();
		LocalPlayOnRoundBoundary(true);
		ClientUxDmgReset();
		ClientUxResetHealthCueArms();
		if (g_optClientNoCorpseSi || g_optClientNoCorpseCi)
			ClientUxApplyNoCorpseCvars(true);
		ClientUxDissolveShutdown(false);
			ClientUxAcidOutlineClear();
		RoundTimerOnStart();
		FinaleRescueHudClear();
		TankSpawnNoticeClear();
		TankRockNoticeClear();
		WitchStartleHudClear();
		VoiceHudClear();
		KillFeedClear();
		TabBoardKillsClear();
		MateAlertClear();
		DirectorPhaseHudReset();
		HazHudClearZones();
		BossDmgBoardOnRoundStart(); // Paint re-baselines checkpoint totals after entities settle
		IdleFlashlightResetState("round_start");
		IdleViewRestoreReset("round_start");
		IdlePersonRestoreReset();
		skeeto_nav::ProgressRoundBoundary(false);
		IdleWepRestoreReset("round_start");

	}
	else if (!strcmp(n, "round_end")) {
		TabBoardKillsClear();
		SilentSiClear();
		TongueCutHudClear();
		g_overlayBoundaryClearPending.store(true, std::memory_order_release);
		WorldNoticeClear();
		TankRockNoticeClear();
		WitchStartleHudClear();
		VoiceHudClear();
		KillFeedClear();
		MateAlertClear();
		KillStreakHudClear();
		LocalPlayOnRoundBoundary(false);
		XhairHideNow();
		RoundTimerOnEnd();
		FinaleRescueHudClear();
		DirectorPhaseHudReset();
		HazHudClearZones();
		IdleFlashlightResetState("round_end");
		IdleViewRestoreReset("round_end");
		IdlePersonRestoreReset();
		skeeto_nav::ProgressRoundBoundary(true);
		IdleWepRestoreReset("round_end");
		ClientUxDissolveShutdown(false);
			ClientUxAcidOutlineClear();
		HudPostMissionQuietBegin("round_end");
	}
	else if (!strcmp(n, "map_transition")) {
		TabBoardKillsClear();
		SilentSiClear();
		TongueCutHudClear();
		g_overlayBoundaryClearPending.store(true, std::memory_order_release);
		WorldNoticeClear();
		TankRockNoticeClear();
		WorldTankPredictClear();
		WitchStartleHudClear();
		VoiceHudClear();
		KillFeedClear();
		MateAlertClear();
		KillStreakHudClear();
		XhairHideNow();
		FinaleRescueHudClear();
		DirectorPhaseHudReset();
		HazHudClearZones();
		IdleFlashlightResetState("map_transition");
		IdleViewRestoreReset("map_transition");
		IdlePersonRestoreReset();
		skeeto_nav::ProgressRoundBoundary(true);
		IdleWepRestoreReset("map_transition");
		ClientUxDissolveShutdown(false);
			ClientUxAcidOutlineClear();
		HudPostMissionQuietBegin("map_transition");
	}
	else if (!strcmp(n, "mission_lost")) {
		TabBoardKillsClear();
		SilentSiClear();
		TongueCutHudClear();
		g_overlayBoundaryClearPending.store(true, std::memory_order_release);
		WorldNoticeClear();
		TankRockNoticeClear();
		WorldTankPredictClear();
		WitchStartleHudClear();
		VoiceHudClear();
		KillFeedClear();
		MateAlertClear();
		KillStreakHudClear();
		ElimOnMissionLost();
		FinaleRescueHudClear();
		DirectorPhaseHudReset();
		HazHudClearZones();
		IdleFlashlightResetState("mission_lost");
		IdleViewRestoreReset("mission_lost");
		IdlePersonRestoreReset();
		skeeto_nav::ProgressRoundBoundary(true);
		IdleWepRestoreReset("mission_lost");
		ClientUxDissolveShutdown(false);
			ClientUxAcidOutlineClear();
		HudPostMissionQuietBegin("mission_lost");
	}
	else if (!strcmp(n, "finale_start") || !strcmp(n, "finale_radio_start"))
		FinaleRescueHudStart(n);
	else if (!strcmp(n, "finale_radio_end") || !strcmp(n, "finale_failed"))
		FinaleRescueHudClear();
	else if (!strcmp(n, "tank_spawn")) {
		const int tid = EvInt(ev, "userid", 0);
		const int tent = tid > 0 ? EngPlayerForUserID(tid) : 0;
		if (tent > 0) g_ckptTankCachedId = tent;
		if (g_optTankSpawnNotice)
			TankSpawnNoticeTrigger();
		if (g_optFinaleRescueHud)
			FinaleRescueHudOnTankSpawn();
	}
	else if (!strcmp(n, "ability_use")) {
		TankRockNoticeOnAbilityUse(ev);
	}
	else if (!strcmp(n, "tank_rock_killed")) {
		TankRockNoticeOnRockKilled();
		ScriptExtrasOnRock(ev);
	}
	else if (!strcmp(n, "tank_killed")) {
		TankRockNoticeClearUser(EvInt(ev, "userid"));
		BossDmgBoardOnTankKilled(); // atomic stamp; Paint reads checkpoint totals
		// AI Tank often fires both player_death(Tank) and tank_killed. Credit once
		// per userid in a 3s window; do not wait 1s in Paint.
		if (g_optElim && (g_elimTankMode == 1 || IsLocalAttacker(ev))
			&& !ElimTankEventIsDup(EvInt(ev, "userid"), 1)) {
			const bool localKill = IsLocalAttacker(ev);
			if (!(CkptZombieKillsReady() && localKill)) {
				g_elimTank.fetch_add(1, std::memory_order_relaxed);
				ElimPersistMarkChanged();
			}
		}
	}
	else if (!strcmp(n, "tank_frustrated")) {
		TankRockNoticeClearUser(EvInt(ev, "userid"));
	}
	else if (!strcmp(n, "create_panic_event")) {
		if (g_optHordeNotice)
			HordeNoticeTrigger();
	}
	else if (!strcmp(n, "finale_vehicle_ready"))
		FinaleRescueHudOnVehicleReady();
	else if (!strcmp(n, "finale_vehicle_leaving") || !strcmp(n, "finale_win")) {
		FinaleRescueHudClear();
		HudPostMissionQuietBegin(n);
	}
	else if (!strcmp(n, "bot_player_replace") || !strcmp(n, "player_bot_replace")) {
		const int playerUid = EvInt(ev, "player");
		const int botUid = EvInt(ev, "bot");
		LocalPlayOnCharBotSwap(ev, n[0] == 'b');
		TeamHudOnBotSwap(n, playerUid, botUid);
		IdleSwapHudOnSwapEvent(n, playerUid, botUid);
		IdleFlashlightOnSwap(n, playerUid, botUid);
		IdleViewRestoreOnSwap(n, playerUid, botUid);
		IdlePersonRestoreOnSwap(n, playerUid, botUid);
		IdleWepRestoreOnSwap(n, playerUid, botUid);
		if (g_localUserId > 0 && (playerUid == g_localUserId || botUid == g_localUserId))
			ClientUxHealthCueOnIdleSwap();
	}
	else if (!strcmp(n, "weapon_reload")) {
		ClientUxOnWeaponReloadClank(ev);
	}
	else if (!strcmp(n, "pills_used")) {
		ClientUxOnHealFadeEvent(ev);
	}
	else if (!strcmp(n, "adrenaline_used")) {
		ClientUxOnHealFadeEvent(ev);
		const int uid = EvInt(ev, "userid");
		bool localUse = false;
		if (uid > 0 && g_localUserId > 0 && uid == g_localUserId)
			localUse = true;
		else if (uid > 0) {
			const int ent = EngPlayerForUserID(uid);
			if (ent > 0 && ent == EngLocal())
				localUse = true;
		}
		if (localUse)
			AdrenHudOnLocalUsed();
	}
}

// IGameEventListener2 (MSVC vtable[0]=dtor, [1]=FireGameEvent, [2]=GetEventDebugID=42)
struct SkeetoEventListener {
	virtual ~SkeetoEventListener() {}
	virtual void FireGameEvent(void* ev) { HandleEvent(ev); }
	virtual int GetEventDebugID() { return 42; }
};
static SkeetoEventListener g_pod;

static bool AddOne(const char* name) {
	if (!g_events) return false;
	auto fn = (AddListenerFn)VGet(g_events, 3);
	if (!fn || !IsExec((void*)fn)) {
		Log("AddListener fn invalid");
		return false;
	}
	bool ok = fn(g_events, &g_pod, name, false);
	if (!ok) Log("AddListener('%s') failed", name);
	return ok;
}

